-- 0001 Initial schema of a Silo cell: every schema, table, key, index, policy,
-- grant and trigger in docs/siloDatabaseDesign.doc.md, as one migration.
-- Runs as silo_migrate (spec 11.3) after src/db/bootstrap/cell.bootstrap.sql. Later changes
-- are new numbered migrations (forward only, expand and contract).
--
-- Order: foundation and shared functions; platform core; identity; audit and the
-- outbox; then each domain (governance, Connect, ontology, clones and workspace,
-- recognition and simulation, automation, files and the AI FDE, Actions, Siloes and
-- billing). Each domain declares keys to its own tables inline; keys that cross into
-- a later domain are added in the section "Cross-domain keys" at the end, once every
-- table exists. Partitions are created last.

-- ============================================================================
-- Foundation: schemas, privileges, shared functions
-- ============================================================================

do $$
declare
  missing text;
begin
  if current_user <> 'silo_migrate' then
    raise exception 'migrations run as silo_migrate, not %', current_user;
  end if;

  select string_agg(e, ', ') into missing
  from unnest(array['pgcrypto', 'ltree', 'citext', 'btree_gist', 'pg_trgm', 'vector']) as e
  where not exists (select 1 from pg_extension where extname = e);
  if missing is not null then
    raise exception 'extensions missing, run bootstrap/cell.bootstrap.sql first: %', missing;
  end if;

  select string_agg(r, ', ') into missing
  from unnest(array['silo_app', 'silo_auth', 'silo_audit_writer', 'silo_report',
                    'silo_credential', 'silo_outbox_relay', 'silo_billing']) as r
  where not exists (select 1 from pg_roles where rolname = r);
  if missing is not null then
    raise exception 'roles missing, run bootstrap/cell.bootstrap.sql first: %', missing;
  end if;
end
$$;

-- Functions are not executable by PUBLIC. Every grant is explicit.
alter default privileges for role silo_migrate revoke execute on functions from public;

-- Schemas (build rules). The runner may already have created platform.
create schema if not exists iam;
create schema if not exists gov;
create schema if not exists audit;
create schema if not exists platform;
create schema if not exists connect;
create schema if not exists ontology;
create schema if not exists clone;
create schema if not exists workspace;
create schema if not exists recognition;
create schema if not exists simulation;
create schema if not exists automation;
create schema if not exists files;
create schema if not exists action;
create schema if not exists fde;
create schema if not exists siloes;
create schema if not exists billing;

do $$
declare
  s text;
begin
  foreach s in array array['iam', 'gov', 'audit', 'platform', 'connect', 'ontology', 'clone',
                           'workspace', 'recognition', 'simulation', 'automation', 'files',
                           'action', 'fde', 'siloes', 'billing'] loop
    execute format('revoke all on schema %I from public', s);
    execute format('grant usage on schema %I to silo_app, silo_report', s);
  end loop;
end
$$;

grant usage on schema iam to silo_auth, silo_credential, silo_audit_writer;
grant usage on schema connect to silo_credential;
grant usage on schema audit, platform to silo_audit_writer, silo_auth;
grant usage on schema platform to silo_outbox_relay;

-- The migration ledger is the runner's, not the application's.
revoke all on table platform.schema_migrations from public;

-- ---------------------------------------------------------------------------
-- UUIDv7. Services generate ids themselves (build rules: primary keys); this is
-- for ids minted inside the database, such as the policy version row.
create function platform.uuid_v7() returns uuid
language sql volatile parallel safe
set search_path = pg_catalog
as $$
  select encode(
    set_bit(set_bit(
      overlay(uuid_send(gen_random_uuid())
              placing substring(int8send(floor(extract(epoch from clock_timestamp()) * 1000)::bigint) from 3)
              from 1 for 6),
      52, 1), 53, 1),
    'hex')::uuid
$$;

-- updated_at, set by one shared trigger (build rules: timestamps).
create function platform.set_updated_at() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
begin
  new.updated_at := now();
  return new;
end
$$;

-- Append-only guard (build rules: append-only ledgers). Rejects update, delete and
-- truncate. With the argument 'purge_by_migrate', silo_migrate may delete rows
-- (Silo purges and entity purges, which are receipted); nobody else may.
create function platform.reject_ledger_change() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
begin
  if tg_op = 'DELETE' and tg_nargs > 0 and tg_argv[0] = 'purge_by_migrate'
     and current_user = 'silo_migrate' then
    return old;
  end if;
  raise exception '%.% is append-only: % rejected', tg_table_schema, tg_table_name, tg_op
    using errcode = 'insufficient_privilege';
end
$$;

-- Immutable columns. Trigger arguments name the columns that may never change.
create function platform.freeze_columns() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
declare
  c text;
  o jsonb := to_jsonb(old);
  n jsonb := to_jsonb(new);
begin
  foreach c in array tg_argv loop
    if o -> c is distinct from n -> c then
      raise exception '%.%.% cannot be changed', tg_table_schema, tg_table_name, c
        using errcode = 'insufficient_privilege';
    end if;
  end loop;
  return new;
end
$$;

-- ---------------------------------------------------------------------------
-- Migration-time helpers. Executable by silo_migrate only (default privileges).

-- Tenant isolation (spec 64.2): enable and force RLS with one policy for reads and
-- writes. The setting is read once per statement through a scalar subquery. An
-- unset or empty app.org_id raises an error, so a forgotten SET LOCAL fails closed.
create function platform.enable_tenant_rls(tbl regclass) returns void
language plpgsql
set search_path = pg_catalog
as $$
begin
  execute format('alter table %s enable row level security', tbl);
  execute format('alter table %s force row level security', tbl);
  execute format(
    'create policy tenant_isolation on %s '
    'using (organisation_id = (select current_setting(''app.org_id'')::uuid)) '
    'with check (organisation_id = (select current_setting(''app.org_id'')::uuid))', tbl);
end
$$;

create function platform.add_updated_at_trigger(tbl regclass) returns void
language plpgsql
set search_path = pg_catalog
as $$
begin
  execute format(
    'create trigger set_updated_at before update on %s '
    'for each row execute function platform.set_updated_at()', tbl);
end
$$;

create function platform.make_append_only(tbl regclass, purge_by_migrate boolean default false)
returns void
language plpgsql
set search_path = pg_catalog
as $$
begin
  execute format(
    'create trigger ledger_no_update before update on %s '
    'for each row execute function platform.reject_ledger_change()', tbl);
  execute format(
    'create trigger ledger_no_delete before delete on %s '
    'for each row execute function platform.reject_ledger_change(%L)',
    tbl, case when purge_by_migrate then 'purge_by_migrate' else 'strict' end);
  execute format(
    'create trigger ledger_no_truncate before truncate on %s '
    'for each statement execute function platform.reject_ledger_change()', tbl);
end
$$;

-- ---------------------------------------------------------------------------
-- Partitions. Ledgers are range-partitioned by time, so retention is a partition drop
-- by silo_migrate. Every range-partitioned table also has a default partition, so no
-- write ever fails for want of a partition, whatever its date. A daily job runs
-- platform.maintain_partitions() as silo_migrate: it creates partitions ahead and moves
-- any row that reached a default partition into a partition of its own. The job alerts
-- on platform.partition_status().

create table platform.partition_plan (
  parent       text primary key,
  granularity  text not null check (granularity in ('day', 'month')),
  create_ahead integer not null check (create_ahead between 1 and 90),
  created_at   timestamptz not null default now()
);
comment on table platform.partition_plan is
  'Range-partitioned tables and how far ahead their partitions are created.';

-- Creates one partition covering [p_start, p_start + one unit) in UTC, with tenant
-- RLS on the partition as well as the parent (defence in depth: a partition queried
-- directly never reads unprotected). No-op if it exists.
create function platform.create_partition(p_parent regclass, p_granularity text, p_start date)
returns void
language plpgsql
set search_path = pg_catalog
as $$
declare
  v_schema text;
  v_table  text;
  v_name   text;
  v_end    date;
begin
  select n.nspname, c.relname into v_schema, v_table
  from pg_class c join pg_namespace n on n.oid = c.relnamespace
  where c.oid = p_parent;

  if p_granularity = 'month' then
    v_name := format('%s_y%sm%s', v_table, to_char(p_start, 'YYYY'), to_char(p_start, 'MM'));
    v_end  := (p_start + interval '1 month')::date;
  else
    v_name := format('%s_d%s', v_table, to_char(p_start, 'YYYYMMDD'));
    v_end  := p_start + 1;
  end if;

  if to_regclass(format('%I.%I', v_schema, v_name)) is not null then
    return;
  end if;

  execute format(
    'create table %I.%I partition of %s for values from (%L) to (%L)',
    v_schema, v_name, p_parent,
    (p_start::timestamp at time zone 'UTC'), (v_end::timestamp at time zone 'UTC'));

  if exists (select 1 from pg_attribute
             where attrelid = p_parent and attname = 'organisation_id' and not attisdropped) then
    perform platform.enable_tenant_rls(format('%I.%I', v_schema, v_name)::regclass);
  end if;
end
$$;

-- Creates the default partition of a range-partitioned table, named <table>_default,
-- with tenant RLS. Returns it; no-op if the table already has one.
create function platform.ensure_default_partition(p_parent regclass)
returns regclass
language plpgsql
set search_path = pg_catalog
as $$
declare
  v_default oid;
  v_schema  text;
  v_name    text;
begin
  select pt.partdefid into v_default from pg_partitioned_table pt where pt.partrelid = p_parent;
  if not found then
    raise exception '% is not a partitioned table', p_parent;
  end if;
  if v_default <> 0 then
    return v_default::regclass;
  end if;

  select n.nspname, c.relname || '_default' into v_schema, v_name
  from pg_class c join pg_namespace n on n.oid = c.relnamespace
  where c.oid = p_parent;
  execute format('create table %I.%I partition of %s default', v_schema, v_name, p_parent);

  if exists (select 1 from pg_attribute
             where attrelid = p_parent and attname = 'organisation_id' and not attisdropped) then
    perform platform.enable_tenant_rls(format('%I.%I', v_schema, v_name)::regclass);
  end if;
  return format('%I.%I', v_schema, v_name)::regclass;
end
$$;

-- Brings one range-partitioned table up to date, in the caller's transaction:
-- 1. its default partition exists;
-- 2. rows in the default move to partitions of their own. Postgres will not create a
--    partition while the default holds rows for its range, so the default is detached,
--    a partition is created for every unit its rows fall in, the rows are re-inserted
--    through the parent with their ids, and the emptied default is attached again;
-- 3. partitions exist from one unit before p_now to p_create_ahead units after it.
-- Idempotent. Serialised per table, so the daily job and Fleet never race.
create function platform.maintain_partitioned_table(p_parent regclass, p_granularity text,
                                                    p_create_ahead integer,
                                                    p_now timestamptz default now())
returns void
language plpgsql
set search_path = pg_catalog
as $$
declare
  v_default regclass;
  v_key     text;
  v_columns text;
  v_starts  date[];
  v_start   date;
  v_base    date;
  i         integer;
begin
  if p_granularity is null or p_granularity not in ('day', 'month') then
    raise exception 'granularity must be day or month' using errcode = 'invalid_parameter_value';
  end if;
  if p_create_ahead is null or p_create_ahead < 1 then
    raise exception 'create_ahead must be at least 1' using errcode = 'invalid_parameter_value';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('platform.partitions:' || p_parent::text, 0));

  select a.attname into v_key
  from pg_partitioned_table pt
  join pg_attribute a on a.attrelid = pt.partrelid and a.attnum = pt.partattrs[0]
  where pt.partrelid = p_parent and pt.partstrat = 'r';
  if v_key is null then
    raise exception '% is not range-partitioned on a column', p_parent;
  end if;

  v_default := platform.ensure_default_partition(p_parent);

  execute format('select array_agg(distinct date_trunc(%L, %I at time zone ''UTC'')::date) from %s',
                 p_granularity, v_key, v_default)
    into v_starts;
  if v_starts is not null then
    select string_agg(quote_ident(a.attname), ', ' order by a.attnum) into v_columns
    from pg_attribute a
    where a.attrelid = p_parent and a.attnum > 0 and not a.attisdropped and a.attgenerated = '';

    execute format('alter table %s detach partition %s', p_parent, v_default);
    foreach v_start in array v_starts loop
      perform platform.create_partition(p_parent, p_granularity, v_start);
    end loop;
    execute format('insert into %s (%s) overriding system value select %s from %s',
                   p_parent, v_columns, v_columns, v_default);
    execute format('truncate %s', v_default);
    execute format('alter table %s attach partition %s default', p_parent, v_default);
  end if;

  if p_granularity = 'month' then
    v_base := date_trunc('month', p_now at time zone 'UTC')::date;
    for i in -1 .. p_create_ahead loop
      perform platform.create_partition(p_parent, 'month', (v_base + make_interval(months => i))::date);
    end loop;
  else
    v_base := (p_now at time zone 'UTC')::date;
    for i in -1 .. p_create_ahead loop
      perform platform.create_partition(p_parent, 'day', v_base + i);
    end loop;
  end if;
end
$$;

-- The daily job. Maintains every planned table. A planned table that no longer exists
-- (an organisation's Capture partition dropped by a purge that left its plan row) is
-- skipped here and reported by platform.partition_status().
create function platform.maintain_partitions(p_now timestamptz default now())
returns void
language plpgsql
set search_path = pg_catalog
as $$
declare
  p record;
begin
  for p in select pp.parent, pp.granularity, pp.create_ahead from platform.partition_plan pp
           where to_regclass(pp.parent) is not null order by pp.parent loop
    perform platform.maintain_partitioned_table(p.parent::regclass, p.granularity, p.create_ahead, p_now);
  end loop;
end
$$;

-- What the partition job alerts on: one row per planned table. Healthy when the table
-- exists, its partitions reach create_ahead units past p_now, and its default
-- partition is empty (a row there arrived after the last maintenance run).
create function platform.partition_status(p_now timestamptz default now())
returns table (
  parent         text,
  granularity    text,
  covered_until  timestamptz,
  required_until timestamptz,
  default_rows   bigint,
  healthy        boolean)
language plpgsql
stable
set search_path = pg_catalog
as $$
#variable_conflict use_column
declare
  p         record;
  v_parent  regclass;
  v_default oid;
begin
  for p in select pp.parent, pp.granularity, pp.create_ahead from platform.partition_plan pp order by pp.parent loop
    parent := p.parent;
    granularity := p.granularity;
    required_until := (date_trunc(p.granularity, p_now at time zone 'UTC')
                       + case when p.granularity = 'month' then make_interval(months => p.create_ahead + 1)
                              else make_interval(days => p.create_ahead + 1) end) at time zone 'UTC';
    covered_until := null;
    default_rows := null;
    v_parent := to_regclass(p.parent);
    if v_parent is not null then
      select max(substring(pg_get_expr(c.relpartbound, c.oid) from 'TO \(''([^'']+)''\)')::timestamptz)
        into covered_until
      from pg_inherits i join pg_class c on c.oid = i.inhrelid
      where i.inhparent = v_parent;
      select pt.partdefid into v_default from pg_partitioned_table pt where pt.partrelid = v_parent;
      if v_default <> 0 then
        execute format('select count(*) from %s', v_default::regclass) into default_rows;
      end if;
    end if;
    healthy := coalesce(default_rows = 0 and covered_until >= required_until, false);
    return next;
  end loop;
end
$$;

-- ============================================================================
-- Platform core: cells and operators
-- ============================================================================

create table platform.cells (
  id                 text primary key check (id ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  kind               text not null check (kind in ('commercial', 'sovereign', 'dedicated', 'self_managed')),
  residency          text not null check (residency in ('uk', 'eu', 'us')),
  location           text not null,
  hosting            text not null check (hosting in ('gke', 'conformant_kubernetes', 'customer_cloud', 'customer_premises')),
  hostname           text not null unique,
  placement_open     boolean not null default false,
  organisation_limit integer not null default 2000 check (organisation_limit > 0),
  connection_limit   integer not null default 50000 check (connection_limit > 0),
  organisation_count integer not null default 0 check (organisation_count >= 0),
  connection_count   integer not null default 0 check (connection_count >= 0),
  counts_at          timestamptz,
  is_local           boolean not null default false,
  status             text not null default 'provisioning'
                       check (status in ('provisioning', 'active', 'closed_to_placement', 'draining', 'retired')),
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now(),
  version            integer not null default 1
);
create unique index cells_one_local on platform.cells (is_local) where is_local;
create index cells_open_for_placement on platform.cells (residency, kind) where placement_open;
select platform.add_updated_at_trigger('platform.cells');

grant select on platform.cells to silo_app, silo_report, silo_auth;
grant update (organisation_count, connection_count, counts_at, updated_at) on platform.cells to silo_app;

-- ---------------------------------------------------------------------------
-- platform.operators: Silo staff known to this cell. Holds no customer data and
-- no email or password. Written by admin-portal (staff.manage, staff.review); the
-- staff identity provider signs them in by idp_subject. Customer pages never join it
-- (names are copied onto sessions).
create table platform.operators (
  id                      uuid primary key,
  idp_subject             text not null unique,
  display_name            text not null,
  clearance               text not null check (clearance in ('bpss', 'sc', 'dv')),
  uk_resident             boolean not null,
  sovereign_access_listed boolean not null default false,
  status                  text not null default 'active' check (status in ('active', 'suspended', 'removed')),
  last_reviewed_at        timestamptz,
  last_reviewed_by        uuid references platform.operators (id),
  removed_at              timestamptz,
  created_at              timestamptz not null default now(),
  updated_at              timestamptz not null default now(),
  version                 integer not null default 1,
  check (not sovereign_access_listed or (uk_resident and clearance in ('sc', 'dv'))),
  check ((status = 'removed') = (removed_at is not null))
);
create index operators_review_due on platform.operators (last_reviewed_at) where status = 'active';
create index operators_last_reviewed_by on platform.operators (last_reviewed_by) where last_reviewed_by is not null;
select platform.add_updated_at_trigger('platform.operators');

grant select on platform.operators to silo_app, silo_report;
grant insert (id, idp_subject, display_name, clearance, uk_resident, sovereign_access_listed)
  on platform.operators to silo_app;
grant update (display_name, clearance, uk_resident, sovereign_access_listed, status, last_reviewed_at,
              last_reviewed_by, removed_at, updated_at, version)
  on platform.operators to silo_app;

-- ============================================================================
-- Identity: organisations, users, sessions, roles, scopes, SSO
-- ============================================================================

create table iam.kms_key_versions (
  id           uuid primary key,
  provider     text not null check (provider in ('gcp_kms', 'uk_hsm', 'pkcs11_hsm', 'vault_transit', 'local')),
  key_uri      text not null,
  version      integer not null check (version >= 1),
  status       text not null check (status in ('active', 'decrypt_only', 'retired')),
  created_at   timestamptz not null default now(),
  activated_at timestamptz,
  retired_at   timestamptz,
  unique (provider, key_uri, version),
  check ((status = 'retired') = (retired_at is not null))
);
create unique index kms_key_versions_one_active on iam.kms_key_versions ((true)) where status = 'active';
comment on column iam.kms_key_versions.key_uri is 'Reference to the key in the KMS or HSM. Never key material.';
comment on column iam.kms_key_versions.provider is
  'local is a key in configuration, for development and tests only; production refuses it (config).';

grant select on iam.kms_key_versions to silo_app, silo_auth, silo_credential, silo_report;

-- ===========================================================================
-- Organisations
-- ===========================================================================

create table iam.organisations (
  id                         uuid primary key,
  name                       text not null check (length(btrim(name)) > 0),
  slug                       citext not null unique check (slug::text ~ '^[a-z0-9][a-z0-9-]{1,62}$'),
  status                     text not null default 'active' check (status in ('active', 'suspended', 'closed')),
  is_system                  boolean not null default false,
  -- Silo's synthetic organisation in this cell (spec 11.2; decision 2026-11-18): the release gates' tests run in it.
  is_synthetic               boolean not null default false check (not (is_synthetic and is_system)),
  plan                       text not null check (plan in ('standard', 'business', 'enterprise')),
  sso_required               boolean not null default false,
  mfa_required               boolean not null default false,
  storage_enabled            boolean not null default false,
  discovery_enabled          boolean not null default false,
  logo_object_key            text,
  logo_content_type          text,
  logo_uploaded_by           uuid,
  logo_uploaded_at           timestamptz,
  billing_status             text not null default 'active'
                               check (billing_status in ('active', 'past_due', 'suspended', 'cancelled')),
  view_sharing_policy        text not null default 'explicit_only'
                               check (view_sharing_policy in ('open', 'scope_only', 'explicit_only', 'disabled')),
  org_wide_sharing_permitted boolean not null default false,
  external_sharing_permitted boolean not null default false check (external_sharing_permitted = false),
  cell_id                    text not null references platform.cells (id),
  calendar_time_zone         text not null,
  financial_year_start_month integer check (financial_year_start_month between 1 and 12),
  financial_year_start_day   integer not null default 1 check (financial_year_start_day between 1 and 31),
  week_start_day             integer not null default 1 check (week_start_day between 1 and 7),
  financial_year_label       text check (financial_year_label in ('start_year', 'end_year')),
  calendar_updated_by        uuid,
  calendar_updated_at        timestamptz,
  session_idle_minutes       integer check (session_idle_minutes is null or session_idle_minutes > 0),
  session_absolute_minutes   integer check (session_absolute_minutes is null or session_absolute_minutes > 0),
  operator_access_approval_required boolean not null default false,
  canary_sample_rows         integer check (canary_sample_rows is null or canary_sample_rows between 1 and 9999),
  -- A physical Action needs a dry run's receipt before it is proposed (47.5). Added.
  physical_dry_run_required  boolean not null default false,
  -- Inference beyond observed evidence, each off until the organisation turns it on (decision 2026-11-11; D71).
  inference_simulation       boolean not null default false,
  inference_resolution       boolean not null default false,
  inference_links            boolean not null default false,
  inference_findings         boolean not null default false,
  -- Ask's web context (36.7): on by default where the cell has a search provider (D84).
  ask_web_enabled            boolean not null default true,
  created_at                 timestamptz not null default now(),
  updated_at                 timestamptz not null default now(),
  version                    integer not null default 1,
  check (num_nonnulls(logo_object_key, logo_content_type, logo_uploaded_by, logo_uploaded_at) in (0, 4)),
  check ((financial_year_label is null) = (financial_year_start_month is null)),
  check (session_idle_minutes is null or session_absolute_minutes is null or session_idle_minutes <= session_absolute_minutes)
);
comment on column iam.organisations.is_synthetic is
  'Silo''s one synthetic organisation in the cell (spec 11.2; decision 2026-11-18): the Fleet agent''s release gates run their '
  'question, subscription, Action and revert tests in it, over a fixture source the agent serves. No customer data, no billing, '
  'never in the directory; its two members never sign in, auth mints their sessions for the agent alone.';
comment on column iam.organisations.is_system is
  'The cell''s one system organisation (review D10). Never in the directory, no members. '
  'Holds only Silo-owned secrets such as Silo-registered OAuth clients.';
comment on column iam.organisations.session_idle_minutes is
  'Organisation policy may shorten the cell''s session timeouts, never lengthen them: the shorter of this and the '
  'cell setting applies (utils/session.util.ts). Null uses the cell setting.';
comment on column iam.organisations.session_absolute_minutes is 'As session_idle_minutes, for the absolute timeout.';
comment on column iam.organisations.inference_simulation is
  'D71: simulation may combine stated lead times with observations (a prior), beyond spec 39.5''s observed-only rule.';
comment on column iam.organisations.inference_resolution is 'D71: resolution may propose probabilistic record matches for a person to confirm.';
comment on column iam.organisations.inference_links is 'D71: the ontology may propose inferred link candidates for a person to confirm.';
comment on column iam.organisations.inference_findings is 'D71: findings carry a probability of being true from their detector''s dispositions.';
comment on column iam.organisations.canary_sample_rows is
  'Spec 45.4: the canary sample across all connections of a mutation of 10,000 rows or more, set by mutation.policy '
  'organisation-wide. Null is the default of 100. The threshold itself is not a setting (43.9).';
comment on column iam.organisations.operator_access_approval_required is
  'Spec 13.3, 13.5 org.operator_access.policy: every break-glass session needs the customer''s approval first. '
  'The sovereign cell requires it whatever this says (admin-portal).';
create unique index organisations_one_system on iam.organisations ((true)) where is_system;
create unique index organisations_one_synthetic on iam.organisations ((true)) where is_synthetic;
create index organisations_cell on iam.organisations (cell_id);

create trigger organisations_frozen before update on iam.organisations
  for each row execute function platform.freeze_columns('id', 'slug', 'cell_id', 'is_system', 'is_synthetic');
select platform.add_updated_at_trigger('iam.organisations');

create function iam.check_time_zone() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
begin
  if not exists (select 1 from pg_timezone_names where name = new.calendar_time_zone) then
    raise exception 'unknown IANA time zone: %', new.calendar_time_zone using errcode = 'check_violation';
  end if;
  return new;
end
$$;
create trigger organisations_time_zone before insert or update of calendar_time_zone on iam.organisations
  for each row execute function iam.check_time_zone();

-- RLS: the organisation row is its own tenant key. Provisioning sets app.org_id to
-- the new id before inserting.
alter table iam.organisations enable row level security;
alter table iam.organisations force row level security;
create policy tenant_isolation on iam.organisations
  using (id = (select current_setting('app.org_id')::uuid))
  with check (id = (select current_setting('app.org_id')::uuid));

grant select on iam.organisations to silo_app, silo_report;
-- billing_status is written only by the billing webhook or a staff path (ch 75),
-- through silo_billing, which only the billing service's login holds. is_system is set by Fleet.
grant insert (id, name, slug, status, plan, sso_required, mfa_required, storage_enabled,
              discovery_enabled, view_sharing_policy, org_wide_sharing_permitted,
              cell_id, calendar_time_zone, financial_year_start_month, financial_year_start_day,
              week_start_day, financial_year_label)
  on iam.organisations to silo_app;
-- The synthetic organisation is made by auth alone, at the Fleet agent's asking (spec 11.2).
grant insert (is_synthetic) on iam.organisations to silo_auth;
grant update (name, status, plan, sso_required, mfa_required, storage_enabled, discovery_enabled,
              logo_object_key, logo_content_type, logo_uploaded_by, logo_uploaded_at,
              view_sharing_policy, org_wide_sharing_permitted, calendar_time_zone,
              financial_year_start_month, financial_year_start_day, week_start_day,
              financial_year_label, calendar_updated_by, calendar_updated_at, session_idle_minutes,
              session_absolute_minutes, operator_access_approval_required, canary_sample_rows, physical_dry_run_required,
              inference_simulation, inference_resolution, inference_links, inference_findings, ask_web_enabled, updated_at, version)
  on iam.organisations to silo_app;
grant update (billing_status) on iam.organisations to silo_billing;

-- ===========================================================================
-- Policy version: one monotonic counter per organisation, the permission cache key
-- ===========================================================================

create table iam.policy_versions (
  id                    uuid primary key,
  organisation_id       uuid not null unique references iam.organisations (id),
  version               bigint not null default 1 check (version >= 1),
  last_changed_at       timestamptz not null default now(),
  last_changed_by_table text,
  unique (organisation_id, id)
);
select platform.enable_tenant_rls('iam.policy_versions');
grant select on iam.policy_versions to silo_app, silo_auth, silo_report;

create function iam.policy_versions_only_increase() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
begin
  if new.version <= old.version or new.organisation_id <> old.organisation_id then
    raise exception 'policy version can only increase' using errcode = 'insufficient_privilege';
  end if;
  return new;
end
$$;
create trigger policy_versions_only_increase before update on iam.policy_versions
  for each row execute function iam.policy_versions_only_increase();

-- Bumps run as the owner so that silo_app, which holds select only, can cause them.
create function iam.bump_policy_version(p_organisation_id uuid, p_source text) returns void
language sql
security definer
set search_path = pg_catalog
as $$
  update iam.policy_versions
     set version = version + 1, last_changed_at = now(), last_changed_by_table = p_source
   where organisation_id = p_organisation_id
$$;

-- Statement-level: one bump per organisation per statement, so a batch bumps once.
create function iam.policy_bump_statement() returns trigger
language plpgsql
security definer
set search_path = pg_catalog
as $$
declare
  v_org uuid;
  v_source text := tg_table_schema || '.' || tg_table_name;
begin
  if tg_op = 'DELETE' then
    for v_org in select distinct organisation_id from old_rows loop
      perform iam.bump_policy_version(v_org, v_source);
    end loop;
  else
    for v_org in select distinct organisation_id from new_rows loop
      perform iam.bump_policy_version(v_org, v_source);
    end loop;
  end if;
  return null;
end
$$;

-- Row-level, for tables where only some column changes affect policy. The trigger
-- argument names the column that holds the organisation id.
create function iam.policy_bump_row() returns trigger
language plpgsql
security definer
set search_path = pg_catalog
as $$
begin
  perform iam.bump_policy_version((to_jsonb(new) ->> tg_argv[0])::uuid,
                                  tg_table_schema || '.' || tg_table_name);
  return null;
end
$$;

create function iam.attach_policy_bump(tbl regclass) returns void
language plpgsql
set search_path = pg_catalog
as $$
begin
  execute format('create trigger policy_bump_insert after insert on %s '
                 'referencing new table as new_rows for each statement '
                 'execute function iam.policy_bump_statement()', tbl);
  execute format('create trigger policy_bump_update after update on %s '
                 'referencing new table as new_rows for each statement '
                 'execute function iam.policy_bump_statement()', tbl);
  execute format('create trigger policy_bump_delete after delete on %s '
                 'referencing old table as old_rows for each statement '
                 'execute function iam.policy_bump_statement()', tbl);
end
$$;

-- A new organisation starts at policy version 1, in the same transaction.
create function iam.organisations_create_policy_version() returns trigger
language plpgsql
security definer
set search_path = pg_catalog
as $$
begin
  -- The seeded roles come first, while there is no version row for their bumps, so an
  -- organisation starts at version 1 with its roles (iam.seed_system_roles, below).
  if not new.is_system then
    perform iam.seed_system_roles(new.id);
  end if;
  insert into iam.policy_versions (id, organisation_id, version, last_changed_by_table)
  values (platform.uuid_v7(), new.id, 1, 'iam.organisations');
  return null;
end
$$;
create trigger organisations_policy_version after insert on iam.organisations
  for each row execute function iam.organisations_create_policy_version();

create trigger organisations_policy_bump after update on iam.organisations
  for each row
  when (old.status is distinct from new.status
        or old.mfa_required is distinct from new.mfa_required
        or old.sso_required is distinct from new.sso_required)
  execute function iam.policy_bump_row('id');

-- ===========================================================================
-- Organisation data and HMAC keys (review D12)
-- ===========================================================================

create table iam.organisation_keys (
  id              uuid primary key,
  organisation_id uuid not null references iam.organisations (id),
  purpose         text not null check (purpose in ('data', 'hmac')),
  version         integer not null check (version >= 1),
  dek_wrapped     bytea not null,
  key_version_id  uuid not null references iam.kms_key_versions (id),
  status          text not null default 'active' check (status in ('active', 'decrypt_only', 'retired')),
  created_at      timestamptz not null default now(),
  activated_at    timestamptz,
  retired_at      timestamptz,
  updated_at      timestamptz not null default now(),
  unique (organisation_id, id),
  unique (organisation_id, id, purpose),
  unique (organisation_id, purpose, version),
  check ((status = 'retired') = (retired_at is not null))
);
comment on column iam.organisation_keys.version is
  'The data key version carried in every ciphertext envelope header.';
comment on column iam.organisation_keys.dek_wrapped is
  'The 256-bit key wrapped by the cell KEK. Readable only by silo_credential.';
create unique index organisation_keys_active on iam.organisation_keys (organisation_id, purpose)
  where status = 'active';
create index organisation_keys_kek on iam.organisation_keys (key_version_id);
create trigger organisation_keys_frozen before update on iam.organisation_keys
  for each row execute function platform.freeze_columns('organisation_id', 'purpose', 'version');
select platform.add_updated_at_trigger('iam.organisation_keys');
select platform.enable_tenant_rls('iam.organisation_keys');

grant select, insert, update on iam.organisation_keys to silo_credential;
grant select (id, organisation_id, purpose, version, key_version_id, status, created_at,
              activated_at, retired_at, updated_at)
  on iam.organisation_keys to silo_app, silo_report;

-- ===========================================================================
-- User-keyed tables. No tenant: protected by privileges (silo_auth only),
-- key-only access, user-keyed RLS, and definer functions for lookups made before
-- the user is known. See "How the user-keyed tables are protected".
-- ===========================================================================

create table iam.users (
  id                   uuid primary key,
  first_name           text not null,
  last_name            text not null,
  email                citext not null unique
                         check (position('@' in email) > 1 and email::text = btrim(email::text)),
  email_verified_at    timestamptz,
  password_hash        text check (password_hash is null or password_hash like '$argon2id$%'),
  sso_only             boolean not null default false,
  password_changed_at  timestamptz,
  failed_attempt_count integer not null default 0 check (failed_attempt_count >= 0),
  locked_until         timestamptz,
  avatar_object_key    text,
  avatar_content_type  text,
  status               text not null default 'active' check (status in ('active', 'suspended', 'deprovisioned')),
  created_at           timestamptz not null default now(),
  updated_at           timestamptz not null default now(),
  last_seen_at         timestamptz,
  check (password_hash is not null or sso_only),
  check ((avatar_object_key is null) = (avatar_content_type is null))
);
comment on column iam.users.password_hash is 'Argon2id encoded hash. Never a plaintext or reversible value.';
create trigger users_frozen before update on iam.users
  for each row execute function platform.freeze_columns('id');
select platform.add_updated_at_trigger('iam.users');

alter table iam.users enable row level security;
alter table iam.users force row level security;
create policy user_self on iam.users
  using (id = (select nullif(current_setting('app.user_id', true), '')::uuid))
  with check (id = (select nullif(current_setting('app.user_id', true), '')::uuid));

-- A person the directory has not heard of yet (spec 55.1; D69): registration after the
-- commit failed, so auth retries it with backoff until the directory answers. The user id
-- only: the address is read from iam.users, and its keyed hash computed, at each attempt.
create table iam.directory_registrations (
  user_id         uuid primary key references iam.users (id),
  attempts        integer not null default 1 check (attempts >= 1),
  next_attempt_at timestamptz not null,
  last_error      text check (length(last_error) <= 200),
  created_at      timestamptz not null default now()
);
comment on table iam.directory_registrations is
  'Directory registrations still to make, retried by auth (55.1). Cell-level, like iam.users; ids only.';
create index directory_registrations_due on iam.directory_registrations (next_attempt_at);
grant select, insert, update, delete on iam.directory_registrations to silo_app;

create table iam.password_resets (
  id                     uuid primary key,
  user_id                uuid not null references iam.users (id),
  token_hash             bytea not null unique check (octet_length(token_hash) = 32),
  requested_from_ip_hash bytea check (requested_from_ip_hash is null or octet_length(requested_from_ip_hash) = 32),
  created_at             timestamptz not null default now(),
  expires_at             timestamptz not null,
  consumed_at            timestamptz,
  check (expires_at > created_at)
);
create index password_resets_open_by_user on iam.password_resets (user_id) where consumed_at is null;

alter table iam.password_resets enable row level security;
alter table iam.password_resets force row level security;
create policy user_self on iam.password_resets
  using (user_id = (select nullif(current_setting('app.user_id', true), '')::uuid))
  with check (user_id = (select nullif(current_setting('app.user_id', true), '')::uuid));

-- TOTP secrets are sealed (AES-256-GCM, fresh DEK per factor). The GCM AAD is
-- (id, user_id, kind). The KEK version is bound to the wrapped DEK through the KMS
-- encryption context, never to the ciphertext, so rotation re-wraps the DEK
-- without decrypting the secret (review D2).
create table iam.mfa_factors (
  id                  uuid primary key,
  user_id             uuid not null references iam.users (id),
  kind                text not null check (kind in ('totp', 'webauthn')),
  secret_sealed       bytea,
  nonce               bytea check (nonce is null or octet_length(nonce) = 12),
  dek_wrapped         bytea,
  key_version_id      uuid references iam.kms_key_versions (id),
  credential_id       bytea,
  webauthn_public_key bytea,
  sign_count          bigint check (sign_count is null or sign_count >= 0),
  confirmed_at        timestamptz,
  revoked_at          timestamptz,
  created_at          timestamptz not null default now(),
  last_used_at        timestamptz,
  last_used_step      bigint check (last_used_step is null or last_used_step >= 0),
  check (kind = 'totp' or last_used_step is null),
  check (
    (kind = 'totp'
      and secret_sealed is not null and nonce is not null and dek_wrapped is not null
      and key_version_id is not null
      and credential_id is null and webauthn_public_key is null and sign_count is null)
    or
    (kind = 'webauthn'
      and credential_id is not null and webauthn_public_key is not null and sign_count is not null
      and secret_sealed is null and nonce is null and dek_wrapped is null and key_version_id is null))
);
comment on column iam.mfa_factors.last_used_step is
  'TOTP: the time step of the last accepted code. A code at or before it is refused, so a code works once even '
  'with a step of drift. Set by compare-and-set: update ... where last_used_step is null or last_used_step < $step.';
create unique index mfa_factors_credential_id on iam.mfa_factors (credential_id) where credential_id is not null;
create index mfa_factors_usable_by_user on iam.mfa_factors (user_id)
  where revoked_at is null and confirmed_at is not null;
create index mfa_factors_user on iam.mfa_factors (user_id);
create index mfa_factors_kek on iam.mfa_factors (key_version_id) where key_version_id is not null;
create trigger mfa_factors_frozen before update on iam.mfa_factors
  for each row execute function platform.freeze_columns('id', 'user_id', 'kind', 'credential_id', 'webauthn_public_key');

alter table iam.mfa_factors enable row level security;
alter table iam.mfa_factors force row level security;
create policy user_self on iam.mfa_factors
  using (user_id = (select nullif(current_setting('app.user_id', true), '')::uuid))
  with check (user_id = (select nullif(current_setting('app.user_id', true), '')::uuid));

revoke all on iam.users, iam.password_resets, iam.mfa_factors from public;
grant select, insert, update on iam.users, iam.password_resets, iam.mfa_factors to silo_auth;

-- ===========================================================================
-- Memberships
-- ===========================================================================

create table iam.memberships (
  id               uuid primary key,
  user_id          uuid not null references iam.users (id),
  organisation_id  uuid not null references iam.organisations (id),
  status           text not null default 'invited' check (status in ('invited', 'active', 'suspended', 'removed')),
  job_title        text,
  invited_by       uuid,
  invited_at       timestamptz,
  joined_at        timestamptz,
  suspended_at     timestamptz,
  removed_at       timestamptz,
  scim_external_id text check (scim_external_id is null or length(scim_external_id) between 1 and 512),
  -- Provisioned by SCIM (decision 2026-11-14; D77): the identity provider is the source of
  -- truth for this member's roles, so no one edits them by hand in Silo.
  scim_managed     boolean not null default false,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  unique (organisation_id, id),
  unique (user_id, organisation_id),
  foreign key (organisation_id, invited_by) references iam.memberships (organisation_id, id),
  check (status = 'invited' or joined_at is not null),
  check (status <> 'suspended' or suspended_at is not null),
  check (status <> 'removed' or removed_at is not null)
);
create unique index memberships_scim_external_id on iam.memberships (organisation_id, scim_external_id)
  where scim_external_id is not null;
create index memberships_list on iam.memberships (organisation_id, created_at desc);
create index memberships_live on iam.memberships (organisation_id, status) where status <> 'removed';
create index memberships_invited_by on iam.memberships (organisation_id, invited_by) where invited_by is not null;
create trigger memberships_frozen before update on iam.memberships
  for each row execute function platform.freeze_columns('id', 'user_id', 'organisation_id');
select platform.add_updated_at_trigger('iam.memberships');
select platform.enable_tenant_rls('iam.memberships');

create function iam.memberships_not_in_system_org() returns trigger
language plpgsql
security definer
set search_path = pg_catalog
as $$
begin
  if exists (select 1 from iam.organisations where id = new.organisation_id and is_system) then
    raise exception 'the system organisation has no members' using errcode = 'check_violation';
  end if;
  return new;
end
$$;
create trigger memberships_not_in_system_org before insert on iam.memberships
  for each row execute function iam.memberships_not_in_system_org();

create trigger memberships_policy_bump after update on iam.memberships
  for each row when (old.status is distinct from new.status)
  execute function iam.policy_bump_row('organisation_id');

grant select, insert, update on iam.memberships to silo_app;
grant select on iam.memberships to silo_report;

-- Organisation columns that name a membership. Deferrable: the organisation exists
-- before its first membership.
alter table iam.organisations
  add constraint organisations_logo_uploaded_by_fkey
    foreign key (id, logo_uploaded_by) references iam.memberships (organisation_id, id)
    deferrable initially deferred,
  add constraint organisations_calendar_updated_by_fkey
    foreign key (id, calendar_updated_by) references iam.memberships (organisation_id, id)
    deferrable initially deferred;
create index organisations_logo_uploaded_by on iam.organisations (id, logo_uploaded_by)
  where logo_uploaded_by is not null;
create index organisations_calendar_updated_by on iam.organisations (id, calendar_updated_by)
  where calendar_updated_by is not null;

-- ===========================================================================
-- Scopes
-- ===========================================================================

create table iam.scope_types (
  id              uuid primary key,
  organisation_id uuid not null references iam.organisations (id),
  name            text not null check (length(btrim(name)) > 0),
  icon            text,
  colour          text,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  unique (organisation_id, id),
  unique (organisation_id, name)
);
select platform.add_updated_at_trigger('iam.scope_types');
select platform.enable_tenant_rls('iam.scope_types');

create table iam.scopes (
  id              uuid primary key,
  organisation_id uuid not null references iam.organisations (id),
  scope_type_id   uuid not null,
  name            text not null check (length(btrim(name)) > 0),
  parent_scope_id uuid,
  path            ltree not null,
  depth           integer not null,
  archived_at     timestamptz,
  created_by      uuid not null,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  version         integer not null default 1,
  unique (organisation_id, id),
  unique nulls not distinct (organisation_id, parent_scope_id, name),
  unique (organisation_id, path),
  foreign key (organisation_id, scope_type_id) references iam.scope_types (organisation_id, id),
  foreign key (organisation_id, parent_scope_id) references iam.scopes (organisation_id, id),
  foreign key (organisation_id, created_by) references iam.memberships (organisation_id, id),
  check (depth = nlevel(path) and depth between 1 and 12),
  check (parent_scope_id is distinct from id)
);
comment on column iam.scopes.path is
  'Ancestor chain. Each label is the scope id as 32 hex characters, so a rename never '
  'rewrites paths. Maintained by trigger; never written by the application.';
create index scopes_path on iam.scopes using gist (organisation_id, path);
create index scopes_children on iam.scopes (organisation_id, parent_scope_id);
create index scopes_scope_type on iam.scopes (organisation_id, scope_type_id);
create index scopes_created_by on iam.scopes (organisation_id, created_by);
select platform.add_updated_at_trigger('iam.scopes');
select platform.enable_tenant_rls('iam.scopes');
create trigger scopes_frozen before update on iam.scopes
  for each row execute function platform.freeze_columns('id', 'organisation_id');

create function iam.scopes_maintain_path() returns trigger
language plpgsql
set search_path = pg_catalog, public
as $$
declare
  v_parent_path ltree;
begin
  if tg_op = 'INSERT' or new.parent_scope_id is distinct from old.parent_scope_id then
    if new.parent_scope_id is null then
      new.path := text2ltree(replace(new.id::text, '-', ''));
    else
      select s.path into v_parent_path
      from iam.scopes s
      where s.organisation_id = new.organisation_id and s.id = new.parent_scope_id;
      if v_parent_path is null then
        raise exception 'parent scope % not found', new.parent_scope_id using errcode = 'foreign_key_violation';
      end if;
      if tg_op = 'UPDATE' and v_parent_path <@ old.path then
        raise exception 'a scope cannot move under its own descendant' using errcode = 'check_violation';
      end if;
      new.path := v_parent_path || text2ltree(replace(new.id::text, '-', ''));
    end if;
    new.depth := nlevel(new.path);
  elsif new.path is distinct from old.path then
    -- Only the descendant rewrite below (a nested trigger) may change a path.
    if pg_trigger_depth() < 2 then
      raise exception 'scope path is maintained by the database' using errcode = 'insufficient_privilege';
    end if;
    new.depth := nlevel(new.path);
  end if;
  return new;
end
$$;
create trigger scopes_maintain_path before insert or update on iam.scopes
  for each row execute function iam.scopes_maintain_path();

-- A move rewrites the prefix of every descendant in the same transaction.
create function iam.scopes_move_descendants() returns trigger
language plpgsql
set search_path = pg_catalog, public
as $$
begin
  update iam.scopes s
     set path = new.path || subpath(s.path, nlevel(old.path))
   where s.organisation_id = new.organisation_id
     and s.path <@ old.path
     and s.id <> new.id;
  return null;
end
$$;
create trigger scopes_move_descendants after update of parent_scope_id on iam.scopes
  for each row when (old.parent_scope_id is distinct from new.parent_scope_id)
  execute function iam.scopes_move_descendants();

create table iam.scope_memberships (
  id              uuid primary key,
  organisation_id uuid not null references iam.organisations (id),
  membership_id   uuid not null,
  scope_id        uuid not null,
  is_primary      boolean not null default false,
  added_by        uuid not null,
  added_at        timestamptz not null default now(),
  inactive_since  timestamptz,
  unique (organisation_id, id),
  unique (organisation_id, membership_id, scope_id),
  foreign key (organisation_id, membership_id) references iam.memberships (organisation_id, id),
  foreign key (organisation_id, scope_id) references iam.scopes (organisation_id, id),
  foreign key (organisation_id, added_by) references iam.memberships (organisation_id, id)
);
comment on column iam.scope_memberships.is_primary is 'Display and routing only, never authorisation.';
create unique index scope_memberships_one_primary on iam.scope_memberships (organisation_id, membership_id)
  where is_primary and inactive_since is null;
create index scope_memberships_scope on iam.scope_memberships (organisation_id, scope_id);
create index scope_memberships_added_by on iam.scope_memberships (organisation_id, added_by);
select platform.enable_tenant_rls('iam.scope_memberships');

-- Archiving needs no active scope memberships beneath (scopes are archived, never deleted).
create function iam.scopes_check_archive() returns trigger
language plpgsql
set search_path = pg_catalog, public
as $$
begin
  if exists (
    select 1
    from iam.scope_memberships sm
    join iam.scopes s on s.organisation_id = sm.organisation_id and s.id = sm.scope_id
    where s.organisation_id = new.organisation_id
      and s.path <@ new.path
      and sm.inactive_since is null) then
    raise exception 'scope % has active members beneath it', new.id using errcode = 'check_violation';
  end if;
  return new;
end
$$;
create trigger scopes_check_archive before update of archived_at on iam.scopes
  for each row when (old.archived_at is null and new.archived_at is not null)
  execute function iam.scopes_check_archive();

grant select, insert, update on iam.scope_types, iam.scopes, iam.scope_memberships to silo_app;
grant select on iam.scope_types, iam.scopes, iam.scope_memberships to silo_report;

-- ===========================================================================
-- Permissions and roles
-- ===========================================================================

-- Global catalogue of permission verbs (chapter 76). Seeded by migration only.
create table iam.permissions (
  id          text primary key check (id ~ '^[a-z][a-z0-9_]*(\.[a-z][a-z0-9_]*)+$'),
  category    text not null check (category in ('standard', 'authorising', 'silo_staff')),
  scopeable   boolean not null,
  description text not null,
  created_at  timestamptz not null default now()
);
grant select on iam.permissions to silo_app, silo_auth, silo_report;

create table iam.roles (
  id              uuid primary key,
  organisation_id uuid not null references iam.organisations (id),
  name            text not null check (length(btrim(name)) > 0),
  system_role     boolean not null default false,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  retired_at      timestamptz,
  version         integer not null default 1,
  unique (organisation_id, id),
  unique (organisation_id, name)
);
select platform.add_updated_at_trigger('iam.roles');
select platform.enable_tenant_rls('iam.roles');
create trigger roles_frozen before update on iam.roles
  for each row execute function platform.freeze_columns('id', 'organisation_id', 'system_role');

create function iam.roles_protect_system() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
begin
  if old.system_role and (new.name is distinct from old.name or new.retired_at is distinct from old.retired_at) then
    raise exception 'seeded roles cannot be renamed or retired' using errcode = 'insufficient_privilege';
  end if;
  return new;
end
$$;
create trigger roles_protect_system before update on iam.roles
  for each row execute function iam.roles_protect_system();

-- Link tables: no id; the primary key is the tenant key. Removing a permission
-- from a role deletes the link row (the audit trail records it).
create table iam.role_permissions (
  organisation_id uuid not null references iam.organisations (id),
  role_id         uuid not null,
  permission_id   text not null references iam.permissions (id),
  created_at      timestamptz not null default now(),
  primary key (organisation_id, role_id, permission_id),
  foreign key (organisation_id, role_id) references iam.roles (organisation_id, id)
);
create index role_permissions_permission on iam.role_permissions (permission_id);
select platform.enable_tenant_rls('iam.role_permissions');

create table iam.role_grantable_roles (
  organisation_id   uuid not null references iam.organisations (id),
  granting_role_id  uuid not null,
  grantable_role_id uuid not null,
  created_at        timestamptz not null default now(),
  primary key (organisation_id, granting_role_id, grantable_role_id),
  foreign key (organisation_id, granting_role_id) references iam.roles (organisation_id, id),
  foreign key (organisation_id, grantable_role_id) references iam.roles (organisation_id, id)
);
create index role_grantable_roles_grantable on iam.role_grantable_roles (organisation_id, grantable_role_id);
select platform.enable_tenant_rls('iam.role_grantable_roles');

create table iam.role_assignments (
  id                  uuid primary key,
  organisation_id     uuid not null references iam.organisations (id),
  membership_id       uuid not null,
  role_id             uuid not null,
  on_scope_id         uuid,
  on_connection_id    uuid,
  on_silo_id          uuid,
  on_view_id          uuid,
  on_object_type_id   uuid,
  on_app_id           uuid,
  granted_by          uuid not null,
  granted_at_scope_id uuid,
  granted_at          timestamptz not null default now(),
  expires_at          timestamptz,
  revoked_by          uuid,
  revoked_at          timestamptz,
  silenced_at         timestamptz,
  -- Given by an admin's mapping of a SCIM group the member is in (D77); revoked when they
  -- leave the group or the mapping goes, never edited by hand. Foreign key added below.
  scim_group_mapping_id uuid,
  unique (organisation_id, id),
  foreign key (organisation_id, membership_id) references iam.memberships (organisation_id, id),
  foreign key (organisation_id, role_id) references iam.roles (organisation_id, id),
  foreign key (organisation_id, on_scope_id) references iam.scopes (organisation_id, id),
  foreign key (organisation_id, granted_by) references iam.memberships (organisation_id, id),
  foreign key (organisation_id, revoked_by) references iam.memberships (organisation_id, id),
  foreign key (organisation_id, granted_at_scope_id) references iam.scopes (organisation_id, id),
  check (num_nonnulls(on_scope_id, on_connection_id, on_silo_id, on_view_id, on_object_type_id, on_app_id) <= 1),
  check (revoked_by is null or revoked_at is not null),
  check (expires_at is null or expires_at > granted_at)
);
create unique index role_assignments_live on iam.role_assignments (
  organisation_id, membership_id, role_id,
  coalesce(on_scope_id, on_connection_id, on_silo_id, on_view_id, on_object_type_id, on_app_id,
           '00000000-0000-0000-0000-000000000000'::uuid))
  where revoked_at is null;
create index role_assignments_membership on iam.role_assignments (organisation_id, membership_id)
  where revoked_at is null;
create index role_assignments_membership_all on iam.role_assignments (organisation_id, membership_id);
create index role_assignments_on_scope on iam.role_assignments (organisation_id, on_scope_id)
  where on_scope_id is not null and revoked_at is null;
create index role_assignments_on_scope_all on iam.role_assignments (organisation_id, on_scope_id)
  where on_scope_id is not null;
create index role_assignments_granted_at_scope on iam.role_assignments (organisation_id, granted_at_scope_id)
  where granted_at_scope_id is not null;
create index role_assignments_on_connection on iam.role_assignments (organisation_id, on_connection_id)
  where on_connection_id is not null;
create index role_assignments_on_silo on iam.role_assignments (organisation_id, on_silo_id)
  where on_silo_id is not null;
create index role_assignments_on_view on iam.role_assignments (organisation_id, on_view_id)
  where on_view_id is not null;
create index role_assignments_on_object_type on iam.role_assignments (organisation_id, on_object_type_id)
  where on_object_type_id is not null;
create index role_assignments_on_app on iam.role_assignments (organisation_id, on_app_id)
  where on_app_id is not null;
create index role_assignments_role on iam.role_assignments (organisation_id, role_id);
create index role_assignments_granted_by on iam.role_assignments (organisation_id, granted_by);
create index role_assignments_revoked_by on iam.role_assignments (organisation_id, revoked_by)
  where revoked_by is not null;
select platform.enable_tenant_rls('iam.role_assignments');
create trigger role_assignments_frozen before update on iam.role_assignments
  for each row execute function platform.freeze_columns(
    'id', 'organisation_id', 'membership_id', 'role_id', 'on_scope_id', 'on_connection_id', 'on_silo_id',
    'on_view_id', 'on_object_type_id', 'on_app_id', 'granted_by', 'granted_at_scope_id', 'granted_at', 'scim_group_mapping_id');

grant select, insert, update on iam.roles, iam.role_assignments to silo_app;
grant select, insert, delete on iam.role_permissions, iam.role_grantable_roles to silo_app;
grant select on iam.roles, iam.role_permissions, iam.role_grantable_roles, iam.role_assignments to silo_report;

