-- The roles every organisation starts with (implementation 2026-11-01; the spec names no
-- seeded set). Roles are data (spec 57.2): an organisation may add its own, and give the
-- seeded ones more or fewer permissions, but not rename or retire them.
-- - Super admin: every customer permission, held organisation-wide (spec 56.5).
-- - Admin: administers a subtree: scopes, people, connections, agents and what the
--   catalogue gives scope admins, plus everything Member has.
-- - Member: query, propose, save and share, export (spec 56.5: "query, save views, propose
--   Actions, approve where granted"). Approval is never a default.
-- - Security reviewer and Billing: the roles the catalogue names.
-- - Physical operations (spec 47.8; decision 2026-11-18): the named physical-operations role,
--   the only one holding actuation.approve. Never granted by default (20.8): not even Super
--   admin holds it, though a super admin may assign it. A physical connection is enabled only
--   once someone holds it, so two-person physical approval (47.2) can always be met.
create function iam.seed_system_roles(p_organisation_id uuid) returns void
language plpgsql
security definer
set search_path = pg_catalog
as $$
declare
  v_member      text[] := array['query.compile', 'mutation.propose', 'object_set.save', 'canvas.save', 'canvas.share', 'clone.view', 'ontology.view', 'lineage.view', 'file.export', 'file.share', 'automation.create', 'connection.create', 'connector.build', 'lens.share', 'recognition.run', 'org.residency.view', 'app.create', 'app.share', 'workbook.save', 'report.save', 'process.save', 'pipeline.save', 'ai_agent.save', 'notebook.save', 'model.save'];
  v_admin       text[] := array['scope.manage', 'admin.delegate', 'member.invite', 'member.suspend', 'session.revoke', 'service_principal.manage', 'connection.grant', 'connection.manage', 'connection.credential.rotate', 'connection.reconnect', 'connector.verify', 'connector.heal_review', 'connector.enable_writes', 'connector.edit', 'agent.view', 'agent.enrol', 'agent.manage', 'automation.manage', 'app.manage', 'audit.read', 'estate.view', 'file.delete', 'file.manage', 'discovery.authorise', 'discovery.review', 'seat.allocate', 'silo.create', 'silo.import', 'silo.manage', 'stream.enable', 'stream.manage', 'scope.sharing.narrow', 'recognition.configure', 'marking.manage'] || v_member;
  v_reviewer    text[] := array['audit.read', 'audit.export', 'lineage.read', 'lineage.view', 'fde.view'];
  v_billing     text[] := array['billing.manage', 'billing.view', 'tokens.purchase', 'seat.allocate', 'seat.release'];
  v_physical    text[] := array['actuation.approve'];
  v_super       uuid := platform.uuid_v7();
  v_admin_role  uuid := platform.uuid_v7();
  v_member_role uuid := platform.uuid_v7();
  v_reviewer_role uuid := platform.uuid_v7();
  v_billing_role  uuid := platform.uuid_v7();
  v_physical_role uuid := platform.uuid_v7();
begin
  insert into iam.roles (id, organisation_id, name, system_role) values
    (v_super, p_organisation_id, 'Super admin', true),
    (v_admin_role, p_organisation_id, 'Admin', true),
    (v_member_role, p_organisation_id, 'Member', true),
    (v_reviewer_role, p_organisation_id, 'Security reviewer', true),
    (v_billing_role, p_organisation_id, 'Billing', true),
    (v_physical_role, p_organisation_id, 'Physical operations', true);
  insert into iam.role_permissions (organisation_id, role_id, permission_id)
    select p_organisation_id, v_super, p.id from iam.permissions p where p.category <> 'silo_staff' and p.id <> all (v_physical)
    union all select p_organisation_id, v_admin_role, unnest(v_admin)
    union all select p_organisation_id, v_member_role, unnest(v_member)
    union all select p_organisation_id, v_reviewer_role, unnest(v_reviewer)
    union all select p_organisation_id, v_billing_role, unnest(v_billing)
    union all select p_organisation_id, v_physical_role, unnest(v_physical);
  -- Which roles each may assign (spec 56.7 rule 5).
  insert into iam.role_grantable_roles (organisation_id, granting_role_id, grantable_role_id) values
    (p_organisation_id, v_super, v_super), (p_organisation_id, v_super, v_admin_role), (p_organisation_id, v_super, v_member_role),
    (p_organisation_id, v_super, v_reviewer_role), (p_organisation_id, v_super, v_billing_role), (p_organisation_id, v_super, v_physical_role),
    (p_organisation_id, v_admin_role, v_admin_role), (p_organisation_id, v_admin_role, v_member_role);
end
$$;

-- A customer's role never holds a Silo staff permission, and a permission held only
-- organisation-wide (scopeable false) lives only in the seeded Super admin role, so no
-- custom role can carry clearance.grant, purpose.define or marking.declassify to someone
-- who is not a super admin (spec 56.7 rule 4).
create function iam.role_permissions_guard() returns trigger
language plpgsql
security definer
set search_path = pg_catalog
as $$
declare
  v_category  text;
  v_scopeable boolean;
begin
  select p.category, p.scopeable into v_category, v_scopeable from iam.permissions p where p.id = new.permission_id;
  if v_category = 'silo_staff' then
    raise exception 'permission % belongs to Silo staff, never to a customer role', new.permission_id
      using errcode = 'insufficient_privilege';
  end if;
  if not v_scopeable and not exists (
    select 1 from iam.roles r
    where r.organisation_id = new.organisation_id and r.id = new.role_id and r.system_role and r.name = 'Super admin') then
    raise exception 'permission % is held through the Super admin role only', new.permission_id
      using errcode = 'insufficient_privilege';
  end if;
  return new;
end
$$;
create trigger role_permissions_guard before insert on iam.role_permissions
  for each row execute function iam.role_permissions_guard();

-- Delegation (spec 56.7), enforced in the inserting transaction, not by the application
-- alone. A live assignment is unrevoked, unsilenced and unexpired. An assignment applies
-- at a target scope when it is organisation-wide or on a scope whose path contains the
-- target's (subtree containment, one indexed ltree test).

create function iam.is_super_admin(p_organisation_id uuid, p_membership_id uuid) returns boolean
language sql
stable
security definer
set search_path = pg_catalog
as $$
  select exists (
    select 1 from iam.role_assignments ra
    join iam.roles r on r.organisation_id = ra.organisation_id and r.id = ra.role_id
    where ra.organisation_id = p_organisation_id and ra.membership_id = p_membership_id
      and r.system_role and r.name = 'Super admin'
      and num_nonnulls(ra.on_scope_id, ra.on_connection_id, ra.on_silo_id, ra.on_view_id, ra.on_object_type_id, ra.on_app_id) = 0
      and ra.revoked_at is null and ra.silenced_at is null and (ra.expires_at is null or ra.expires_at > now()))
$$;

-- The roles a membership holds that apply at a scope (null: organisation-wide only).
create function iam.roles_applying_at(p_organisation_id uuid, p_membership_id uuid, p_scope_id uuid)
returns table (role_id uuid)
language sql
stable
security definer
set search_path = pg_catalog, public
as $$
  select ra.role_id
  from iam.role_assignments ra
  left join iam.scopes held on held.organisation_id = ra.organisation_id and held.id = ra.on_scope_id
  left join iam.scopes target on target.organisation_id = p_organisation_id and target.id = p_scope_id
  where ra.organisation_id = p_organisation_id and ra.membership_id = p_membership_id
    and ra.revoked_at is null and ra.silenced_at is null and (ra.expires_at is null or ra.expires_at > now())
    and num_nonnulls(ra.on_connection_id, ra.on_silo_id, ra.on_view_id, ra.on_object_type_id, ra.on_app_id) = 0
    and (ra.on_scope_id is null or (target.path is not null and target.path <@ held.path))
$$;

-- Whether a membership may grant a role at a scope (null: organisation-wide), by the
-- rules of spec 56.7. Null when it may; otherwise the reason. The delegation trigger
-- applies it to every insert, and auth asks it before issuing an invitation, so an
-- invitation that could never be accepted is refused when it is made.
create function iam.check_grant(p_organisation_id uuid, p_granter uuid, p_role_id uuid, p_target_scope_id uuid)
returns text
language plpgsql
stable
security definer
set search_path = pg_catalog, public
as $$
declare
  v_granter_roles uuid[];
begin
  if not exists (select 1 from iam.roles r where r.organisation_id = p_organisation_id and r.id = p_role_id and r.retired_at is null) then
    return 'no such role';
  end if;
  -- A role holding an organisation-wide-only permission is assigned organisation-wide.
  if p_target_scope_id is not null and exists (
    select 1 from iam.role_permissions rp join iam.permissions p on p.id = rp.permission_id
    where rp.organisation_id = p_organisation_id and rp.role_id = p_role_id and not p.scopeable) then
    return 'role is held organisation-wide only';
  end if;
  if iam.is_super_admin(p_organisation_id, p_granter) then
    return null;
  end if;
  -- Rule 3: only a super admin grants organisation-wide (and so creates a super admin).
  if p_target_scope_id is null then
    return 'only a super admin grants organisation-wide';
  end if;
  select array_agg(r.role_id) into v_granter_roles from iam.roles_applying_at(p_organisation_id, p_granter, p_target_scope_id) r;
  -- Rule 1: the granter administers the target scope (subtree containment).
  if v_granter_roles is null or not exists (
    select 1 from iam.role_permissions rp
    where rp.organisation_id = p_organisation_id and rp.role_id = any (v_granter_roles)
      and rp.permission_id in ('admin.delegate', 'member.invite')) then
    return 'the granter does not administer that scope';
  end if;
  -- Rule 2: no escalation. Every permission of the role is one the granter holds there.
  if exists (
    select rp.permission_id from iam.role_permissions rp
    where rp.organisation_id = p_organisation_id and rp.role_id = p_role_id
    except
    select gp.permission_id from iam.role_permissions gp
    where gp.organisation_id = p_organisation_id and gp.role_id = any (v_granter_roles)) then
    return 'the role holds permissions the granter does not';
  end if;
  -- Rule 5: the role is whitelisted for one of the granter's roles.
  if not exists (
    select 1 from iam.role_grantable_roles g
    where g.organisation_id = p_organisation_id and g.granting_role_id = any (v_granter_roles) and g.grantable_role_id = p_role_id) then
    return 'the granter''s roles may not assign that role';
  end if;
  return null;
end
$$;

-- The scope a granter administers the target from: the nearest scope, at or above the
-- target, on which they hold admin.delegate or member.invite. What a grant records as
-- granted_at_scope_id (spec 56.8). Null for a super admin acting organisation-wide.
create function iam.acting_scope(p_organisation_id uuid, p_granter uuid, p_target_scope_id uuid)
returns uuid
language sql
stable
security definer
set search_path = pg_catalog, public
as $$
  select held.id
  from iam.role_assignments ra
  join iam.scopes held on held.organisation_id = ra.organisation_id and held.id = ra.on_scope_id
  join iam.scopes target on target.organisation_id = ra.organisation_id and target.id = p_target_scope_id
  join iam.role_permissions rp on rp.organisation_id = ra.organisation_id and rp.role_id = ra.role_id
  where ra.organisation_id = p_organisation_id and ra.membership_id = p_granter
    and ra.revoked_at is null and ra.silenced_at is null and (ra.expires_at is null or ra.expires_at > now())
    and rp.permission_id in ('admin.delegate', 'member.invite')
    and target.path <@ held.path
  order by nlevel(held.path) desc
  limit 1
$$;

-- Runs as the caller, not the owner, so current_user names who is inserting (inside a
-- security definer function it would always be the owner, silo_migrate). It reads only
-- the caller's own organisation's rows; the helpers above see past RLS where needed.
create function iam.role_assignments_delegation() returns trigger
language plpgsql
set search_path = pg_catalog, public
as $$
declare
  v_resource_scoped boolean := num_nonnulls(new.on_connection_id, new.on_silo_id, new.on_view_id, new.on_object_type_id, new.on_app_id) > 0;
  -- A resource-scoped grant is checked at the scope the granter acted under.
  v_target uuid := coalesce(new.on_scope_id, case when v_resource_scoped then new.granted_at_scope_id end);
  v_refusal text;
begin
  -- Provisioning creates an organisation's first super admin before anyone can grant.
  if current_user = 'silo_migrate' then
    return new;
  end if;
  if v_resource_scoped and v_target is null and not iam.is_super_admin(new.organisation_id, new.granted_by) then
    raise exception 'only a super admin grants organisation-wide' using errcode = 'insufficient_privilege';
  end if;
  v_refusal := iam.check_grant(new.organisation_id, new.granted_by, new.role_id, v_target);
  if v_refusal is not null then
    raise exception '%', v_refusal using errcode = 'insufficient_privilege';
  end if;
  -- Provenance (spec 56.8): a scope grant records the scope the granter acted under,
  -- which contains the target. A super admin may act organisation-wide (null).
  if v_target is not null and not (new.granted_at_scope_id is null and iam.is_super_admin(new.organisation_id, new.granted_by))
     and (new.granted_at_scope_id is null or not exists (
       select 1 from iam.scopes acted join iam.scopes target on target.organisation_id = acted.organisation_id
       where acted.organisation_id = new.organisation_id and acted.id = new.granted_at_scope_id
         and target.id = v_target and target.path <@ acted.path)) then
    raise exception 'granted_at_scope_id must be a scope the granter acted under, containing the target'
      using errcode = 'insufficient_privilege';
  end if;
  return new;
end
$$;
create trigger role_assignments_delegation before insert on iam.role_assignments
  for each row execute function iam.role_assignments_delegation();
grant execute on function iam.is_super_admin(uuid, uuid), iam.roles_applying_at(uuid, uuid, uuid),
  iam.check_grant(uuid, uuid, uuid, uuid), iam.acting_scope(uuid, uuid, uuid) to silo_app;

-- Revocation (spec 56.8, revision 5): by the issuer, an admin whose subtree contains the
-- scope it was issued under, or a super admin; never merely an admin above the person.
create function iam.role_assignments_revocation() returns trigger
language plpgsql
set search_path = pg_catalog, public
as $$
begin
  if old.revoked_at is not null or new.revoked_at is null or current_user = 'silo_migrate' then
    return new;
  end if;
  if new.revoked_by is null then
    raise exception 'a revocation names who revoked it' using errcode = 'insufficient_privilege';
  end if;
  if new.revoked_by = old.granted_by or iam.is_super_admin(new.organisation_id, new.revoked_by) then
    return new;
  end if;
  if old.granted_at_scope_id is not null and exists (
    select 1 from iam.roles_applying_at(new.organisation_id, new.revoked_by, old.granted_at_scope_id) r
    join iam.role_permissions rp on rp.organisation_id = new.organisation_id and rp.role_id = r.role_id
    where rp.permission_id = 'admin.delegate') then
    return new;
  end if;
  raise exception 'only the issuer, an admin over the scope it was issued under, or a super admin may revoke this'
    using errcode = 'insufficient_privilege';
end
$$;
create trigger role_assignments_revocation before update of revoked_at on iam.role_assignments
  for each row execute function iam.role_assignments_revocation();

-- ===========================================================================
-- Service principals: execute, never authorise
-- ===========================================================================

create table iam.service_principals (
  id                      uuid primary key,
  organisation_id         uuid not null references iam.organisations (id),
  kind                    text not null check (kind in ('agent', 'automation', 'api_client', 'fde')),
  name                    text not null check (length(btrim(name)) > 0),
  certificate_fingerprint bytea check (certificate_fingerprint is null or octet_length(certificate_fingerprint) = 32),
  secret_hash             bytea check (secret_hash is null or octet_length(secret_hash) = 32),
  scope_id                uuid,
  owner_membership_id     uuid not null,
  engagement_id           uuid,
  expires_at              timestamptz,
  created_by              uuid not null,
  created_at              timestamptz not null default now(),
  revoked_at              timestamptz,
  expiry_recorded_at      timestamptz,
  updated_at              timestamptz not null default now(),
  unique (organisation_id, id),
  unique (organisation_id, id, kind),
  foreign key (organisation_id, scope_id) references iam.scopes (organisation_id, id),
  foreign key (organisation_id, owner_membership_id) references iam.memberships (organisation_id, id),
  foreign key (organisation_id, created_by) references iam.memberships (organisation_id, id),
  check (kind <> 'agent' or certificate_fingerprint is not null),
  check (kind <> 'api_client' or secret_hash is not null),
  check ((kind = 'fde') = (engagement_id is not null)),
  check (kind not in ('fde', 'api_client') or expires_at is not null),
  check (expiry_recorded_at is null or expires_at is not null)
);
comment on column iam.service_principals.expiry_recorded_at is
  'When maintenance recorded service_principal_expired, once, after expires_at passed (D63). The principal is refused from expires_at regardless.';
create unique index service_principals_certificate on iam.service_principals (organisation_id, certificate_fingerprint)
  where certificate_fingerprint is not null;
create index service_principals_owner on iam.service_principals (organisation_id, owner_membership_id);
create index service_principals_scope on iam.service_principals (organisation_id, scope_id) where scope_id is not null;
create index service_principals_engagement on iam.service_principals (organisation_id, engagement_id)
  where engagement_id is not null;
create index service_principals_created_by on iam.service_principals (organisation_id, created_by);
create index service_principals_expiry on iam.service_principals (organisation_id, expires_at)
  where revoked_at is null and expires_at is not null;
select platform.add_updated_at_trigger('iam.service_principals');
select platform.enable_tenant_rls('iam.service_principals');
create trigger service_principals_frozen before update on iam.service_principals
  for each row execute function platform.freeze_columns('id', 'organisation_id', 'kind', 'engagement_id');

create table iam.service_principal_roles (
  organisation_id      uuid not null references iam.organisations (id),
  service_principal_id uuid not null,
  role_id              uuid not null,
  granted_by           uuid not null,
  granted_at           timestamptz not null default now(),
  primary key (organisation_id, service_principal_id, role_id),
  foreign key (organisation_id, service_principal_id) references iam.service_principals (organisation_id, id),
  foreign key (organisation_id, role_id) references iam.roles (organisation_id, id),
  foreign key (organisation_id, granted_by) references iam.memberships (organisation_id, id)
);
create index service_principal_roles_role on iam.service_principal_roles (organisation_id, role_id);
create index service_principal_roles_granted_by on iam.service_principal_roles (organisation_id, granted_by);
select platform.enable_tenant_rls('iam.service_principal_roles');

-- Invariant: people decide. A role holding a permission of category 'authorising'
-- can never be held by a service principal, whichever side changes. Deferred to
-- commit and serialised on the role row, so neither order nor concurrency evades it.
create function iam.reject_authorising_for_principals() returns trigger
language plpgsql
security definer
set search_path = pg_catalog
as $$
begin
  perform 1 from iam.roles r where r.organisation_id = new.organisation_id and r.id = new.role_id for update;

  if exists (
    select 1
    from iam.service_principal_roles spr
    join iam.role_permissions rp on rp.organisation_id = spr.organisation_id and rp.role_id = spr.role_id
    join iam.permissions p on p.id = rp.permission_id
    where spr.organisation_id = new.organisation_id
      and spr.role_id = new.role_id
      and p.category = 'authorising') then
    raise exception 'service principals execute but never authorise: role % holds an authorising permission', new.role_id
      using errcode = 'insufficient_privilege';
  end if;
  return null;
end
$$;
create constraint trigger service_principal_roles_no_authorising
  after insert or update on iam.service_principal_roles
  deferrable initially deferred
  for each row execute function iam.reject_authorising_for_principals();
create constraint trigger role_permissions_no_authorising_for_principals
  after insert or update on iam.role_permissions
  deferrable initially deferred
  for each row execute function iam.reject_authorising_for_principals();

grant select, insert, update on iam.service_principals to silo_app;
grant select, insert, delete on iam.service_principal_roles to silo_app;
grant select on iam.service_principals, iam.service_principal_roles to silo_report;

-- ===========================================================================
-- Sessions: opaque, server-side. Postgres is the revocation list.
-- ===========================================================================

create table iam.sessions (
  id                   uuid primary key,
  token_hash           bytea not null unique check (octet_length(token_hash) = 32),
  user_id              uuid references iam.users (id),
  service_principal_id uuid,
  organisation_id      uuid references iam.organisations (id),
  active_membership_id uuid,
  issued_at            timestamptz not null default now(),
  expires_at           timestamptz not null,
  revoked_at           timestamptz,
  ip_hash              bytea check (ip_hash is null or octet_length(ip_hash) = 32),
  user_agent_hash      bytea check (user_agent_hash is null or octet_length(user_agent_hash) = 32),
  auth_method          text not null check (auth_method in ('password', 'sso', 'agent', 'synthetic')),
  mfa_satisfied_at     timestamptz,
  -- A SAML sign-in (spec 55.5): the provider, and its session index for single logout. An
  -- identifier at the provider, which signs no one in.
  identity_provider_id uuid,
  sso_session_index    text check (length(sso_session_index) <= 512),
  unique (organisation_id, id),
  foreign key (organisation_id, active_membership_id) references iam.memberships (organisation_id, id),
  foreign key (organisation_id, service_principal_id) references iam.service_principals (organisation_id, id),
  check (num_nonnulls(user_id, service_principal_id) = 1),
  check ((organisation_id is null) = (active_membership_id is null and service_principal_id is null)),
  check (service_principal_id is null or active_membership_id is null),
  check ((service_principal_id is not null) = (auth_method = 'agent')),
  check (identity_provider_id is null or auth_method = 'sso'),
  check (sso_session_index is null or identity_provider_id is not null),
  check (expires_at > issued_at)
);
comment on table iam.sessions is
  'A session without an organisation authorises nothing. Switching membership issues a new session.';
create index sessions_live_by_user on iam.sessions (user_id) where revoked_at is null;
create index sessions_live_by_provider on iam.sessions (organisation_id, identity_provider_id, user_id)
  where revoked_at is null and identity_provider_id is not null;
create index sessions_user on iam.sessions (user_id);
create index sessions_live_by_membership on iam.sessions (organisation_id, active_membership_id)
  where revoked_at is null;
create index sessions_membership on iam.sessions (organisation_id, active_membership_id)
  where active_membership_id is not null;
create index sessions_live_by_principal on iam.sessions (organisation_id, service_principal_id)
  where revoked_at is null;
create index sessions_principal on iam.sessions (organisation_id, service_principal_id)
  where service_principal_id is not null;
create index sessions_expiry on iam.sessions (expires_at) where revoked_at is null;
create trigger sessions_frozen before update on iam.sessions
  for each row execute function platform.freeze_columns(
    'id', 'token_hash', 'user_id', 'service_principal_id', 'organisation_id', 'active_membership_id',
    'issued_at', 'auth_method');

-- Spec 64.2: every table carrying organisation_id has forced RLS (review D20). The
-- auth service reaches a session either as its user or within its organisation;
-- lookups by token go through iam.resolve_session.
alter table iam.sessions enable row level security;
alter table iam.sessions force row level security;
create policy session_owner on iam.sessions
  using (user_id = (select nullif(current_setting('app.user_id', true), '')::uuid)
         or organisation_id = (select nullif(current_setting('app.org_id', true), '')::uuid))
  with check (user_id = (select nullif(current_setting('app.user_id', true), '')::uuid)
              or organisation_id = (select nullif(current_setting('app.org_id', true), '')::uuid));

revoke all on iam.sessions from public;
grant select, insert, update on iam.sessions to silo_auth;

-- ===========================================================================
-- SSO configuration, SSO identity links, SCIM tokens
-- ===========================================================================

-- Provider metadata (including any OIDC client secret) is sealed. The GCM AAD is
-- (id, organisation_id, kind); the KEK version is bound through the KMS
-- encryption context (review D2). Sealed columns are read and written only by the
-- credential mediator (silo_credential); unwrap reason 'idp'.
create table iam.identity_providers (
  id               uuid primary key,
  organisation_id  uuid not null references iam.organisations (id),
  kind             text not null check (kind in ('saml', 'oidc')),
  issuer           text not null check (length(issuer) between 1 and 2048),
  metadata_sealed  bytea not null,
  nonce            bytea not null check (octet_length(nonce) = 12),
  dek_wrapped      bytea not null,
  key_version_id   uuid not null references iam.kms_key_versions (id),
  jit_provisioning boolean not null default false,
  default_role_id  uuid,
  default_scope_id uuid,
  active           boolean not null default false,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  version          integer not null default 1,
  unique (organisation_id, id),
  unique (organisation_id, issuer),
  foreign key (organisation_id, default_role_id) references iam.roles (organisation_id, id),
  foreign key (organisation_id, default_scope_id) references iam.scopes (organisation_id, id),
  check (not jit_provisioning or default_role_id is not null)
);
create index identity_providers_default_role on iam.identity_providers (organisation_id, default_role_id)
  where default_role_id is not null;
create index identity_providers_default_scope on iam.identity_providers (organisation_id, default_scope_id)
  where default_scope_id is not null;
create index identity_providers_kek on iam.identity_providers (key_version_id);
select platform.add_updated_at_trigger('iam.identity_providers');
select platform.enable_tenant_rls('iam.identity_providers');
create trigger identity_providers_frozen before update on iam.identity_providers
  for each row execute function platform.freeze_columns('id', 'organisation_id', 'kind');

grant select, insert, update on iam.identity_providers to silo_credential;
grant select (id, organisation_id, kind, issuer, key_version_id, jit_provisioning, default_role_id,
              default_scope_id, active, created_at, updated_at, version)
  on iam.identity_providers to silo_app, silo_report;
grant update (jit_provisioning, default_role_id, default_scope_id, active, updated_at, version)
  on iam.identity_providers to silo_app;

-- Review D1. Login by SSO resolves the user here, by the provider's stable subject,
-- never by email: a first link needs an invitation, JIT creation of a new user, or
-- the person's existing sign-in in the same flow. Email claims can be set by the
-- provider's tenant admins.
create table iam.user_identities (
  id                   uuid primary key,
  organisation_id      uuid not null references iam.organisations (id),
  identity_provider_id uuid not null,
  user_id              uuid not null references iam.users (id),
  subject              text not null check (length(subject) between 1 and 512),
  email_at_link        citext not null,
  linked_via           text not null check (linked_via in ('invitation', 'jit', 'existing_session')),
  linked_at            timestamptz not null default now(),
  last_login_at        timestamptz,
  revoked_at           timestamptz,
  revoked_by           uuid,
  created_at           timestamptz not null default now(),
  updated_at           timestamptz not null default now(),
  unique (organisation_id, id),
  foreign key (organisation_id, identity_provider_id) references iam.identity_providers (organisation_id, id),
  foreign key (organisation_id, revoked_by) references iam.memberships (organisation_id, id),
  check ((revoked_at is null) = (revoked_by is null))
);
comment on column iam.user_identities.subject is
  'Stable, non-reassignable provider identifier: OIDC sub; Entra ID tid:oid; SAML persistent NameID. Never email.';
comment on column iam.user_identities.email_at_link is 'Display and audit only. Never used to match.';
create unique index user_identities_subject on iam.user_identities (organisation_id, identity_provider_id, subject)
  where revoked_at is null;
create unique index user_identities_one_per_provider on iam.user_identities (organisation_id, identity_provider_id, user_id)
  where revoked_at is null;
create index user_identities_provider on iam.user_identities (organisation_id, identity_provider_id);
create index user_identities_live_by_user on iam.user_identities (user_id) where revoked_at is null;
create index user_identities_user on iam.user_identities (user_id);
create index user_identities_revoked_by on iam.user_identities (organisation_id, revoked_by)
  where revoked_by is not null;
select platform.add_updated_at_trigger('iam.user_identities');
select platform.enable_tenant_rls('iam.user_identities');
create trigger user_identities_frozen before update on iam.user_identities
  for each row execute function platform.freeze_columns(
    'id', 'organisation_id', 'identity_provider_id', 'user_id', 'subject', 'email_at_link',
    'linked_via', 'linked_at');

revoke all on iam.user_identities from public;
grant select, insert, update on iam.user_identities to silo_auth;

-- SCIM bearer tokens, issued as <organisation_id>.<random>; the gateway sets
-- app.org_id from the prefix before the lookup.
create table iam.scim_tokens (
  id              uuid primary key,
  organisation_id uuid not null references iam.organisations (id),
  token_hash      bytea not null check (octet_length(token_hash) = 32),
  created_by      uuid not null,
  created_at      timestamptz not null default now(),
  last_used_at    timestamptz,
  revoked_at      timestamptz,
  unique (organisation_id, id),
  unique (organisation_id, token_hash),
  foreign key (organisation_id, created_by) references iam.memberships (organisation_id, id)
);
create index scim_tokens_created_by on iam.scim_tokens (organisation_id, created_by);
select platform.enable_tenant_rls('iam.scim_tokens');
create trigger scim_tokens_frozen before update on iam.scim_tokens
  for each row execute function platform.freeze_columns('id', 'organisation_id', 'token_hash', 'created_by');
grant select, insert, update on iam.scim_tokens to silo_app;

-- Self-serve sign-up (decision 2026-11-14; D78): Standard and Business only. A sign-up
-- waits here until its address is verified through the emailed link; completing it creates
-- the organisation, the person (when the cell has none with the address) and the founding
-- super admin. Cell-level like iam.users: there is no organisation yet. It holds the address
-- and the organisation's name, never a password; unverified rows are deleted a day after
-- they expire.
create table iam.signups (
  id                uuid primary key,
  email             citext not null check (position('@' in email) > 1 and email::text = btrim(email::text)),
  organisation_name text not null check (length(btrim(organisation_name)) between 1 and 200),
  organisation_slug citext not null check (organisation_slug::text ~ '^[a-z0-9][a-z0-9-]{1,62}$'),
  plan              text not null check (plan in ('standard', 'business')),
  term              text not null check (term in ('monthly', 'annual')),
  seats             integer not null check (seats between 1 and 499),
  token_hash        bytea not null unique check (octet_length(token_hash) = 32),
  expires_at        timestamptz not null,
  created_at        timestamptz not null default now(),
  completed_at      timestamptz,
  -- What it created: a reference, not a tenant key (the sign-up precedes its organisation).
  created_organisation_id uuid references iam.organisations (id),
  check ((completed_at is null) = (created_organisation_id is null))
);
comment on table iam.signups is
  'A self-serve sign-up waiting for its address to be verified (decision 2026-11-14). No password is kept here.';
create index signups_expiry on iam.signups (expires_at) where completed_at is null;
create index signups_organisation on iam.signups (created_organisation_id) where created_organisation_id is not null;
grant select, insert, update, delete on iam.signups to silo_auth;

-- The founding super admin of a signed-up organisation (D78): the one grant with no granter
-- above it, as provisioning makes it (iam.role_assignments_delegation lets silo_migrate, the
-- owner, through). Only into an organisation with no assignment yet, for an active member of it.
create function iam.grant_founding_super_admin(p_organisation_id uuid, p_membership_id uuid) returns uuid
language plpgsql
security definer
set search_path = pg_catalog
as $$
declare
  v_role uuid;
  v_id   uuid := platform.uuid_v7();
begin
  if nullif(current_setting('app.org_id', true), '')::uuid is distinct from p_organisation_id then
    raise exception 'the founding grant is made in the organisation''s own context' using errcode = 'insufficient_privilege';
  end if;
  if exists (select 1 from iam.role_assignments where organisation_id = p_organisation_id) then
    raise exception 'the organisation already has its founder' using errcode = 'insufficient_privilege';
  end if;
  if not exists (select 1 from iam.memberships where organisation_id = p_organisation_id and id = p_membership_id and status = 'active') then
    raise exception 'the founder is an active member of the organisation' using errcode = 'insufficient_privilege';
  end if;
  select id into v_role from iam.roles where organisation_id = p_organisation_id and name = 'Super admin' and system_role;
  insert into iam.role_assignments (id, organisation_id, membership_id, role_id, granted_by)
  values (v_id, p_organisation_id, p_membership_id, v_role, p_membership_id);
  return v_id;
end
$$;
revoke all on function iam.grant_founding_super_admin(uuid, uuid) from public;
grant execute on function iam.grant_founding_super_admin(uuid, uuid) to silo_auth;

-- The cell's synthetic organisation (spec 11.2; decision 2026-11-18), for auth to find it before
-- app.org_id can be set. Its identifier only.
create function iam.synthetic_organisation_id() returns uuid
language sql stable security definer
set search_path = pg_catalog
as $$ select id from iam.organisations where is_synthetic $$;
revoke all on function iam.synthetic_organisation_id() from public;
grant execute on function iam.synthetic_organisation_id() to silo_auth;

-- Its members, by the part each plays (proposer, approver), read from their addresses.
create function iam.synthetic_members() returns table (member text, membership_id uuid, user_id uuid)
language sql stable security definer
set search_path = pg_catalog
as $$
  select substring(u.email::text from '^synthetic-([a-z]+)@'), m.id, u.id
    from iam.organisations o join iam.memberships m on m.organisation_id = o.id join iam.users u on u.id = m.user_id
   where o.is_synthetic and u.email::text ~ '^synthetic-[a-z]+@'
$$;
revoke all on function iam.synthetic_members() from public;
grant execute on function iam.synthetic_members() to silo_auth;

-- Its two members, each a Super admin, so one can propose and the other approve, as two people
-- would: once, in the synthetic organisation only.
create function iam.grant_synthetic_members(p_organisation_id uuid, p_first uuid, p_second uuid) returns void
language plpgsql
security definer
set search_path = pg_catalog
as $$
declare
  v_role uuid;
begin
  if not exists (select 1 from iam.organisations where id = p_organisation_id and is_synthetic) then
    raise exception 'only the synthetic organisation''s members are granted so' using errcode = 'insufficient_privilege';
  end if;
  if exists (select 1 from iam.role_assignments where organisation_id = p_organisation_id) then return; end if;
  select id into v_role from iam.roles where organisation_id = p_organisation_id and name = 'Super admin' and system_role;
  insert into iam.role_assignments (id, organisation_id, membership_id, role_id, granted_by)
  values (platform.uuid_v7(), p_organisation_id, p_first, v_role, p_first), (platform.uuid_v7(), p_organisation_id, p_second, v_role, p_first);
end
$$;
revoke all on function iam.grant_synthetic_members(uuid, uuid, uuid) from public;
grant execute on function iam.grant_synthetic_members(uuid, uuid, uuid) to silo_auth;

-- An organisation's email domains (decision 2026-11-14; D79). Verifying one is optional: a
-- TXT record at _silo-verification.<domain> carrying the token proves the organisation
-- controls it, and a verified domain is claimed: in this cell no one signs up a new
-- organisation with an address at it (they ask the claiming organisation for an invitation).
-- One claim per domain in the cell. The token is published in DNS, so it is no secret.
create table iam.organisation_domains (
  id                 uuid primary key,
  organisation_id    uuid not null references iam.organisations (id),
  domain             citext not null check (length(domain) <= 253
                       and domain::text ~ '^([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$'),
  verification_token text not null check (length(verification_token) between 20 and 100),
  status             text not null default 'pending' check (status in ('pending', 'verified', 'removed')),
  created_by         uuid not null,
  created_at         timestamptz not null default now(),
  verified_at        timestamptz,
  removed_by         uuid,
  removed_at         timestamptz,
  unique (organisation_id, id),
  foreign key (organisation_id, created_by) references iam.memberships (organisation_id, id),
  foreign key (organisation_id, removed_by) references iam.memberships (organisation_id, id),
  check (status <> 'verified' or verified_at is not null),
  check ((status = 'removed') = (removed_at is not null)),
  check ((removed_at is null) = (removed_by is null))
);
comment on table iam.organisation_domains is
  'An organisation''s email domain; verified through DNS it is claimed in the cell (decision 2026-11-14).';
create unique index organisation_domains_claimed on iam.organisation_domains (domain) where status = 'verified';
create unique index organisation_domains_live on iam.organisation_domains (organisation_id, domain) where status <> 'removed';
select platform.enable_tenant_rls('iam.organisation_domains');
create trigger organisation_domains_frozen before update on iam.organisation_domains
  for each row execute function platform.freeze_columns('id', 'organisation_id', 'domain', 'verification_token', 'created_by', 'created_at');
grant select, insert, update on iam.organisation_domains to silo_app;

-- Whether a domain is claimed in the cell, across organisations, for sign-up (yes or no only).
create function iam.domain_claimed(p_domain text) returns boolean
language sql stable security definer
set search_path = pg_catalog
as $$
  select exists (select 1 from iam.organisation_domains where domain = p_domain::public.citext and status = 'verified')
$$;
revoke all on function iam.domain_claimed(text) from public;
grant execute on function iam.domain_claimed(text) to silo_auth;

-- SCIM groups (decision 2026-11-14; D77). A group the identity provider pushes grants
-- nothing by itself: an admin maps it to a Silo role and scope, and its members hold that
-- role while they are in it. Roles are never created from group names, and a mapping is by
-- the group's id, so a group renamed in the customer's directory grants nothing new.
create table iam.scim_groups (
  id              uuid primary key,
  organisation_id uuid not null references iam.organisations (id),
  display_name    text not null check (length(btrim(display_name)) between 1 and 256),
  external_id     text check (external_id is null or length(external_id) between 1 and 512),
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  deleted_at      timestamptz,
  unique (organisation_id, id)
);
comment on table iam.scim_groups is
  'A group pushed over SCIM. Grants nothing by itself; an admin''s mapping gives its members a role (decision 2026-11-14).';
create unique index scim_groups_external_id on iam.scim_groups (organisation_id, external_id)
  where external_id is not null and deleted_at is null;
create index scim_groups_list on iam.scim_groups (organisation_id, created_at) where deleted_at is null;
select platform.add_updated_at_trigger('iam.scim_groups');
select platform.enable_tenant_rls('iam.scim_groups');
create trigger scim_groups_frozen before update on iam.scim_groups
  for each row execute function platform.freeze_columns('id', 'organisation_id', 'created_at');
grant select, insert, update on iam.scim_groups to silo_app;

-- Who is in each group now, as the identity provider last said.
create table iam.scim_group_members (
  id              uuid primary key,
  organisation_id uuid not null references iam.organisations (id),
  group_id        uuid not null,
  membership_id   uuid not null,
  added_at        timestamptz not null default now(),
  unique (organisation_id, id),
  unique (organisation_id, group_id, membership_id),
  foreign key (organisation_id, group_id) references iam.scim_groups (organisation_id, id),
  foreign key (organisation_id, membership_id) references iam.memberships (organisation_id, id)
);
create index scim_group_members_membership on iam.scim_group_members (organisation_id, membership_id);
select platform.enable_tenant_rls('iam.scim_group_members');
grant select, insert, delete on iam.scim_group_members to silo_app;

-- An admin's mapping of a group to a role, at a scope or organisation-wide (null). Its
-- grants are given as the admin who made it, under the delegation rules.
create table iam.scim_group_mappings (
  id              uuid primary key,
  organisation_id uuid not null references iam.organisations (id),
  group_id        uuid not null,
  role_id         uuid not null,
  scope_id        uuid,
  created_by      uuid not null,
  created_at      timestamptz not null default now(),
  removed_by      uuid,
  removed_at      timestamptz,
  unique (organisation_id, id),
  foreign key (organisation_id, group_id) references iam.scim_groups (organisation_id, id),
  foreign key (organisation_id, role_id) references iam.roles (organisation_id, id),
  foreign key (organisation_id, scope_id) references iam.scopes (organisation_id, id),
  foreign key (organisation_id, created_by) references iam.memberships (organisation_id, id),
  foreign key (organisation_id, removed_by) references iam.memberships (organisation_id, id),
  check ((removed_at is null) = (removed_by is null))
);
comment on table iam.scim_group_mappings is
  'An admin-maintained mapping of a SCIM group to a Silo role and scope (decision 2026-11-14). Unmapped groups grant nothing.';
create unique index scim_group_mappings_live on iam.scim_group_mappings
  (organisation_id, group_id, role_id, coalesce(scope_id, '00000000-0000-0000-0000-000000000000'::uuid)) where removed_at is null;
create index scim_group_mappings_group on iam.scim_group_mappings (organisation_id, group_id);
create index scim_group_mappings_role on iam.scim_group_mappings (organisation_id, role_id);
create index scim_group_mappings_scope on iam.scim_group_mappings (organisation_id, scope_id) where scope_id is not null;
create index scim_group_mappings_created_by on iam.scim_group_mappings (organisation_id, created_by);
create index scim_group_mappings_removed_by on iam.scim_group_mappings (organisation_id, removed_by) where removed_by is not null;
select platform.enable_tenant_rls('iam.scim_group_mappings');
create trigger scim_group_mappings_frozen before update on iam.scim_group_mappings
  for each row execute function platform.freeze_columns('id', 'organisation_id', 'group_id', 'role_id', 'scope_id', 'created_by', 'created_at');
grant select, insert, update on iam.scim_group_mappings to silo_app;

alter table iam.role_assignments add constraint role_assignments_scim_group_mapping_fkey
  foreign key (organisation_id, scim_group_mapping_id) references iam.scim_group_mappings (organisation_id, id);
create index role_assignments_scim_group_mapping on iam.role_assignments (organisation_id, scim_group_mapping_id)
  where scim_group_mapping_id is not null;

-- ===========================================================================
-- Invitations
-- ===========================================================================

create table iam.invitations (
  id                     uuid primary key,
  organisation_id        uuid not null references iam.organisations (id),
  email                  citext not null check (position('@' in email) > 1),
  token_hash             bytea not null check (octet_length(token_hash) = 32),
  role_id                uuid not null,
  scope_id               uuid,
  seat_id                uuid,
  invited_by             uuid not null,
  created_at             timestamptz not null default now(),
  expires_at             timestamptz not null,
  accepted_at            timestamptz,
  accepted_membership_id uuid,
  revoked_at             timestamptz,
  unique (organisation_id, id),
  unique (organisation_id, token_hash),
  foreign key (organisation_id, role_id) references iam.roles (organisation_id, id),
  foreign key (organisation_id, scope_id) references iam.scopes (organisation_id, id),
  foreign key (organisation_id, invited_by) references iam.memberships (organisation_id, id),
  foreign key (organisation_id, accepted_membership_id) references iam.memberships (organisation_id, id),
  check (expires_at > created_at),
  check (not (accepted_at is not null and revoked_at is not null)),
  check ((accepted_at is null) = (accepted_membership_id is null))
);
create unique index invitations_one_open_per_email on iam.invitations (organisation_id, email)
  where accepted_at is null and revoked_at is null;
create index invitations_pending on iam.invitations (organisation_id, created_at desc)
  where accepted_at is null and revoked_at is null;
create index invitations_role on iam.invitations (organisation_id, role_id);
create index invitations_scope on iam.invitations (organisation_id, scope_id) where scope_id is not null;
create index invitations_seat on iam.invitations (organisation_id, seat_id) where seat_id is not null;
create index invitations_invited_by on iam.invitations (organisation_id, invited_by);
create index invitations_accepted_membership on iam.invitations (organisation_id, accepted_membership_id)
  where accepted_membership_id is not null;
select platform.enable_tenant_rls('iam.invitations');
create trigger invitations_frozen before update on iam.invitations
  for each row execute function platform.freeze_columns(
    'id', 'organisation_id', 'email', 'token_hash', 'role_id', 'scope_id', 'invited_by', 'created_at', 'expires_at');
grant select, insert, update on iam.invitations to silo_app;
grant select on iam.invitations to silo_report;

-- ===========================================================================
-- Key retirement guard. Replaced when connect.connection_credentials exists.
-- ===========================================================================

create function iam.kms_key_retire_guard() returns trigger
language plpgsql
security definer
set search_path = pg_catalog
as $$
begin
  if exists (select 1 from iam.mfa_factors where key_version_id = new.id and revoked_at is null)
     or exists (select 1 from iam.identity_providers where key_version_id = new.id)
     or exists (select 1 from iam.organisation_keys where key_version_id = new.id and status <> 'retired') then
    raise exception 'key version % still wraps live keys; re-wrap before retiring', new.id
      using errcode = 'check_violation';
  end if;
  return new;
end
$$;
create trigger kms_key_versions_retire_guard before update of status on iam.kms_key_versions
  for each row when (new.status = 'retired' and old.status <> 'retired')
  execute function iam.kms_key_retire_guard();

-- ===========================================================================
-- Lookups made before the user or organisation is known. Owned by silo_migrate
-- (review D3): silo_auth is itself subject to the user-keyed RLS and could not
-- perform them. Each returns the minimum the caller needs.
-- ===========================================================================

create function iam.find_user_for_login(p_email public.citext)
returns table (
  id                   uuid,
  password_hash        text,
  sso_only             boolean,
  status               text,
  failed_attempt_count integer,
  locked_until         timestamptz,
  email_verified_at    timestamptz)
language sql
stable
security definer
set search_path = pg_catalog, public
as $$
  select u.id, u.password_hash, u.sso_only, u.status, u.failed_attempt_count, u.locked_until,
         u.email_verified_at
  from iam.users u
  where u.email = p_email
$$;

-- Consumes a reset token once and, in the same transaction, sets the new password (an
-- Argon2id hash), revokes every session of the user and every other open reset (spec
-- 55.3 binding rule). Returns the session ids so the caller can delete their Redis copies.
create function iam.consume_password_reset(p_token_hash bytea, p_password_hash text)
returns table (user_id uuid, revoked_session_ids uuid[])
language plpgsql
security definer
set search_path = pg_catalog
as $$
declare
  v_user uuid;
  v_sessions uuid[];
begin
  update iam.password_resets r
     set consumed_at = now()
   where r.token_hash = p_token_hash and r.consumed_at is null and r.expires_at > now()
  returning r.user_id into v_user;

  if v_user is null then
    return;
  end if;

  update iam.users u
     set password_hash = p_password_hash, password_changed_at = now(), failed_attempt_count = 0, locked_until = null
   where u.id = v_user;

  with revoked as (
    update iam.sessions s set revoked_at = now()
     where s.user_id = v_user and s.revoked_at is null
    returning s.id)
  select coalesce(array_agg(revoked.id), '{}') into v_sessions from revoked;

  update iam.password_resets r
     set consumed_at = now()
   where r.user_id = v_user and r.consumed_at is null;

  return query select v_user, v_sessions;
end
$$;

create function iam.resolve_session(p_token_hash bytea)
returns table (
  id                   uuid,
  user_id              uuid,
  service_principal_id uuid,
  organisation_id      uuid,
  active_membership_id uuid,
  issued_at            timestamptz,
  expires_at           timestamptz,
  auth_method          text,
  mfa_satisfied_at     timestamptz)
language sql
stable
security definer
set search_path = pg_catalog
as $$
  select s.id, s.user_id, s.service_principal_id, s.organisation_id, s.active_membership_id,
         s.issued_at, s.expires_at, s.auth_method, s.mfa_satisfied_at
  from iam.sessions s
  where s.token_hash = p_token_hash and s.revoked_at is null and s.expires_at > now()
$$;

-- The organisation a login names, by slug, before app.org_id can be set: only what the
-- login needs. Password login is per organisation (sessions and auth events carry it).
create function iam.find_organisation_for_login(p_slug public.citext)
returns table (
  id                       uuid,
  status                   text,
  mfa_required             boolean,
  sso_required             boolean,
  session_idle_minutes     integer,
  session_absolute_minutes integer)
language sql
stable
security definer
set search_path = pg_catalog, public
as $$
  select o.id, o.status, o.mfa_required, o.sso_required, o.session_idle_minutes, o.session_absolute_minutes
  from iam.organisations o
  where o.slug = p_slug and not o.is_system and not o.is_synthetic
$$;

-- The organisations a user can choose (RLS would hide all but one).
create function iam.list_user_memberships(p_user_id uuid)
returns table (
  membership_id     uuid,
  organisation_id   uuid,
  organisation_name text,
  organisation_slug text,
  membership_status text)
language sql
stable
security definer
set search_path = pg_catalog
as $$
  select m.id, o.id, o.name, o.slug::text, m.status
  from iam.memberships m
  join iam.organisations o on o.id = m.organisation_id
  where m.user_id = p_user_id
    and m.status in ('invited', 'active')
    and o.status = 'active'
    and not o.is_system
  order by o.name
$$;

grant execute on function iam.find_user_for_login(public.citext),
                          iam.find_organisation_for_login(public.citext),
                          iam.consume_password_reset(bytea, text),
                          iam.resolve_session(bytea),
                          iam.list_user_memberships(uuid)
  to silo_auth;

-- Profile data for tenant services, without password, lockout or MFA columns. The
-- owner bypasses RLS, so the explicit organisation filter is the guard.
create view iam.member_profiles with (security_barrier = true) as
  select m.id              as membership_id,
         m.organisation_id,
         m.status          as membership_status,
         u.first_name,
         u.last_name,
         u.email,
         u.avatar_object_key,
         u.avatar_content_type,
         u.status          as user_status
  from iam.memberships m
  join iam.users u on u.id = m.user_id
  where m.organisation_id = (select current_setting('app.org_id')::uuid);
grant select on iam.member_profiles to silo_app, silo_report;

