-- Policy version bumps
-- ===========================================================================

select iam.attach_policy_bump('iam.scopes');
select iam.attach_policy_bump('iam.scope_memberships');
select iam.attach_policy_bump('iam.roles');
select iam.attach_policy_bump('iam.role_permissions');
select iam.attach_policy_bump('iam.role_grantable_roles');
select iam.attach_policy_bump('iam.role_assignments');
select iam.attach_policy_bump('iam.service_principals');
select iam.attach_policy_bump('iam.service_principal_roles');

-- ============================================================================
-- Audit ledger, outbox, model calls, operator access
-- ============================================================================

create table platform.operator_access_sessions (
  id                                uuid primary key,
  organisation_id                   uuid not null references iam.organisations (id),
  operator_id                       uuid not null references platform.operators (id),
  operator_display_name             text not null,
  purpose                           text not null check (purpose in ('support_request', 'incident_response',
                                                                     'legal_obligation', 'security_investigation')),
  access_level                      text not null check (access_level in ('metadata_read', 'tenant_read', 'tenant_act')),
  reason                            text not null check (length(btrim(reason)) > 0),
  ticket_reference                  text not null check (length(btrim(ticket_reference)) > 0),
  scope_note                        text,
  requested_minutes                 integer not null check (requested_minutes between 1 and 240),
  status                            text not null default 'requested'
                                      check (status in ('requested', 'approved', 'denied', 'active', 'ended',
                                                        'expired', 'cancelled')),
  requested_at                      timestamptz not null default now(),
  emergency                         boolean not null default false,
  customer_approval_required        boolean not null,
  staff_approver_operator_id        uuid constraint operator_access_staff_approver_fkey references platform.operators (id),
  staff_approver_display_name       text,
  staff_approved_at                 timestamptz,
  staff_second_approver_operator_id uuid constraint operator_access_second_approver_fkey references platform.operators (id),
  staff_second_approver_display_name text,
  approved_by_membership_id         uuid,
  customer_decided_at               timestamptz,
  denied_reason                     text,
  starts_at                         timestamptz,
  expires_at                        timestamptz,
  ended_at                          timestamptz,
  ended_reason                      text check (ended_reason in ('ended', 'expired', 'revoked')),
  ended_by_membership_id            uuid,
  recording_reference               text,
  recording_retained_until          timestamptz,
  resources_touched_count           integer not null default 0 check (resources_touched_count >= 0),
  updated_at                        timestamptz not null default now(),
  version                           integer not null default 1,
  unique (organisation_id, id),
  foreign key (organisation_id, approved_by_membership_id) references iam.memberships (organisation_id, id),
  foreign key (organisation_id, ended_by_membership_id) references iam.memberships (organisation_id, id),
  check (staff_approver_operator_id is null or staff_approver_operator_id <> operator_id),
  check ((staff_approver_display_name is null) = (staff_approver_operator_id is null)),
  check ((staff_second_approver_display_name is null) = (staff_second_approver_operator_id is null)),
  check ((ended_by_membership_id is not null) = (ended_reason is not distinct from 'revoked')),
  check (staff_second_approver_operator_id is null or staff_second_approver_operator_id <> operator_id),
  check (staff_second_approver_operator_id is null
         or staff_second_approver_operator_id is distinct from staff_approver_operator_id),
  check ((staff_approver_operator_id is null) = (staff_approved_at is null)),
  check ((starts_at is null) = (expires_at is null)),
  check (starts_at is null or (expires_at > starts_at and expires_at - starts_at <= interval '4 hours')),
  check ((ended_at is null) = (ended_reason is null)),
  check (status not in ('approved', 'active', 'ended', 'expired')
         or (staff_approver_operator_id is not null
             and (approved_by_membership_id is not null or not customer_approval_required or emergency)
             and (not emergency or staff_second_approver_operator_id is not null))),
  check (access_level <> 'tenant_act' or customer_approval_required or not emergency)
);
comment on table platform.operator_access_sessions is
  'Customer-visible break-glass sessions (spec 13.3). No level unwraps credentials or approves an Action.';
comment on column platform.operator_access_sessions.requested_minutes is
  'How long the session may run once started: expires_at is starts_at plus this, at most 4 hours.';
comment on column platform.operator_access_sessions.staff_approver_display_name is
  'Snapshots of the approvers'' names, so the tenant''s view needs no join to platform.operators.';
comment on column platform.operator_access_sessions.ended_by_membership_id is
  'The customer member who revoked an active session (ended_reason revoked).';
create index operator_access_sessions_list on platform.operator_access_sessions (organisation_id, requested_at desc);
create index operator_access_sessions_open on platform.operator_access_sessions (organisation_id, status)
  where status in ('requested', 'approved', 'active');
create index operator_access_sessions_expiry on platform.operator_access_sessions (expires_at)
  where status = 'active';
create index operator_access_sessions_operator on platform.operator_access_sessions (organisation_id, operator_id);
create index operator_access_sessions_approved_by on platform.operator_access_sessions (organisation_id, approved_by_membership_id)
  where approved_by_membership_id is not null;
select platform.add_updated_at_trigger('platform.operator_access_sessions');
select platform.enable_tenant_rls('platform.operator_access_sessions');

-- The tenant sees its own sessions. admin-portal writes them: the staff steps, and the
-- customer's decision and revocation through its tenant endpoints. Never deleted.
grant select on platform.operator_access_sessions to silo_app, silo_report;
grant insert (id, organisation_id, operator_id, operator_display_name, purpose, access_level, reason, ticket_reference,
              scope_note, requested_minutes, emergency, customer_approval_required)
  on platform.operator_access_sessions to silo_app;
grant update (status, staff_approver_operator_id, staff_approver_display_name, staff_approved_at,
              staff_second_approver_operator_id, staff_second_approver_display_name, approved_by_membership_id,
              customer_decided_at, denied_reason, starts_at, expires_at, ended_at, ended_reason, ended_by_membership_id,
              recording_reference, recording_retained_until, resources_touched_count, updated_at, version)
  on platform.operator_access_sessions to silo_app;

-- Silo staff work across organisations; the rows stay under RLS. These list identifiers
-- only, for admin-portal to load each row under its organisation's context.
create function platform.operator_access_sessions_open(p_limit integer) returns table (organisation_id uuid, id uuid)
language sql stable security definer
set search_path = pg_catalog
as $$
  select s.organisation_id, s.id from platform.operator_access_sessions s
  where s.status in ('requested', 'approved', 'active')
  order by s.requested_at, s.id limit p_limit
$$;
create function platform.operator_access_sessions_due(p_limit integer) returns table (organisation_id uuid, id uuid)
language sql stable security definer
set search_path = pg_catalog
as $$
  select s.organisation_id, s.id from platform.operator_access_sessions s
  where s.status = 'active' and s.expires_at <= now()
  order by s.expires_at, s.id limit p_limit
$$;
grant execute on function platform.operator_access_sessions_open(integer), platform.operator_access_sessions_due(integer) to silo_app;

-- Support tickets (U4, D254): what a member asks Silo support, and the replies. A ticket holds
-- references and the person's own words, never a record value (spec 8.5): admin-portal refuses
-- text matching a value pattern, and the client asks for references rather than pasted values.
-- A Silo staff access request (13.3) names the ticket it serves by its reference.
create table platform.support_tickets (
  id                             uuid primary key,
  organisation_id                uuid not null references iam.organisations (id),
  reference                      text not null unique check (reference ~ '^SUP-[0-9A-HJKMNP-TV-Z]{8}$'),
  raised_by_membership_id        uuid not null,
  subject                        text not null check (length(btrim(subject)) between 1 and 200),
  category                       text not null check (category in ('question', 'problem', 'access', 'billing', 'feature', 'security')),
  severity                       text not null default 'normal' check (severity in ('low', 'normal', 'high', 'urgent')),
  status                         text not null default 'waiting_on_silo'
                                   check (status in ('waiting_on_silo', 'waiting_on_customer', 'resolved', 'closed')),
  -- The page of the client it was raised from: a path of the client's own, never a query.
  place                          text check (place ~ '^/[a-z0-9/_-]{0,199}$'),
  -- Requests it is about, by correlation id, so support can find them in the logs.
  correlation_ids                uuid[] not null default '{}' check (cardinality(correlation_ids) <= 10),
  -- Things in Silo it is about, by reference: [{kind, id}], kinds a closed set the service checks.
  refs                           jsonb not null default '[]' check (jsonb_typeof(refs) = 'array' and jsonb_array_length(refs) <= 20),
  assigned_operator_id           uuid references platform.operators (id),
  assigned_operator_display_name text,
  last_message_at                timestamptz not null default now(),
  resolved_at                    timestamptz,
  closed_at                      timestamptz,
  created_at                     timestamptz not null default now(),
  updated_at                     timestamptz not null default now(),
  version                        integer not null default 1,
  unique (organisation_id, id),
  foreign key (organisation_id, raised_by_membership_id) references iam.memberships (organisation_id, id),
  check ((assigned_operator_display_name is null) = (assigned_operator_id is null)),
  check ((resolved_at is not null) = (status in ('resolved', 'closed'))),
  check ((closed_at is not null) = (status = 'closed'))
);
comment on table platform.support_tickets is
  'A member''s request to Silo support (U4). References and the person''s own words only, never a record value (spec 8.5).';
create index support_tickets_list on platform.support_tickets (organisation_id, last_message_at desc, id);
create index support_tickets_raised_by on platform.support_tickets (organisation_id, raised_by_membership_id, last_message_at desc);
create index support_tickets_queue on platform.support_tickets (status, severity, last_message_at) where status = 'waiting_on_silo';
select platform.add_updated_at_trigger('platform.support_tickets');
select platform.enable_tenant_rls('platform.support_tickets');
grant select on platform.support_tickets to silo_app, silo_report;
grant insert (id, organisation_id, reference, raised_by_membership_id, subject, category, severity, place, correlation_ids, refs)
  on platform.support_tickets to silo_app;
grant update (status, severity, assigned_operator_id, assigned_operator_display_name, last_message_at, resolved_at, closed_at,
              updated_at, version)
  on platform.support_tickets to silo_app;

create table platform.support_ticket_messages (
  id                    uuid primary key,
  organisation_id       uuid not null,
  ticket_id             uuid not null,
  author_kind           text not null check (author_kind in ('member', 'staff')),
  author_membership_id  uuid,
  author_operator_id    uuid references platform.operators (id),
  -- A member of staff's name as the customer sees it; a member's name is read from their account.
  author_display_name   text,
  body                  text not null check (length(btrim(body)) between 1 and 4000),
  created_at            timestamptz not null default now(),
  unique (organisation_id, id),
  foreign key (organisation_id, ticket_id) references platform.support_tickets (organisation_id, id),
  foreign key (organisation_id, author_membership_id) references iam.memberships (organisation_id, id),
  check ((author_kind = 'member') = (author_membership_id is not null)),
  check ((author_kind = 'staff') = (author_operator_id is not null)),
  check ((author_kind = 'staff') = (author_display_name is not null))
);
comment on table platform.support_ticket_messages is
  'A ticket''s messages, in order: the member''s and Silo staff''s own words. Never edited, never deleted.';
create index support_ticket_messages_ticket on platform.support_ticket_messages (organisation_id, ticket_id, created_at, id);
select platform.enable_tenant_rls('platform.support_ticket_messages');
grant select on platform.support_ticket_messages to silo_app, silo_report;
grant insert (id, organisation_id, ticket_id, author_kind, author_membership_id, author_operator_id, author_display_name, body)
  on platform.support_ticket_messages to silo_app;

-- Support staff work across organisations; the rows stay under RLS. The queue lists identifiers
-- only (the most urgent, longest waiting first), for admin-portal to load each under its
-- organisation's context; a reference finds one ticket.
create function platform.support_tickets_waiting(p_limit integer) returns table (organisation_id uuid, id uuid)
language sql stable security definer
set search_path = pg_catalog
as $$
  select t.organisation_id, t.id from platform.support_tickets t
  where t.status = 'waiting_on_silo'
  order by case t.severity when 'urgent' then 0 when 'high' then 1 when 'normal' then 2 else 3 end, t.last_message_at, t.id
  limit p_limit
$$;
create function platform.support_ticket_by_reference(p_reference text) returns table (organisation_id uuid, id uuid)
language sql stable security definer
set search_path = pg_catalog
as $$
  select t.organisation_id, t.id from platform.support_tickets t where t.reference = p_reference
$$;
grant execute on function platform.support_tickets_waiting(integer), platform.support_ticket_by_reference(text) to silo_app;

-- Staff name an organisation by its slug (admin-portal). Identity and standing only: no
-- member, no content.
create function platform.organisation_for_staff(p_slug citext)
  returns table (id uuid, name text, slug citext, plan text, status text, billing_status text, cell_id text,
                 operator_access_approval_required boolean)
language sql stable security definer
set search_path = pg_catalog, public
as $$
  select o.id, o.name, o.slug, o.plan, o.status, o.billing_status, o.cell_id, o.operator_access_approval_required
  from iam.organisations o where o.slug = p_slug and not o.is_system
$$;
grant execute on function platform.organisation_for_staff(citext) to silo_app;

-- ===========================================================================
-- audit.auth_events: authentication and administration events (ch 63.1)
-- ===========================================================================

create table audit.auth_events (
  id                   bigint generated always as identity,
  occurred_at          timestamptz not null default now(),
  organisation_id      uuid not null references iam.organisations (id),
  user_id              uuid references iam.users (id),
  membership_id        uuid,
  service_principal_id uuid,
  event                text not null check (event ~ '^[a-z][a-z0-9_]*$'),
  detail               jsonb not null default '{}'
                         check (jsonb_typeof(detail) = 'object' and octet_length(detail::text) <= 65536),
  ip_hash              bytea check (ip_hash is null or octet_length(ip_hash) = 32),
  correlation_id       uuid,
  source_event_id      uuid,
  primary key (id, occurred_at),
  unique (organisation_id, id, occurred_at),
  foreign key (organisation_id, membership_id) references iam.memberships (organisation_id, id),
  foreign key (organisation_id, service_principal_id) references iam.service_principals (organisation_id, id),
  check (num_nonnulls(membership_id, service_principal_id) <= 1)
) partition by range (occurred_at);
comment on column audit.auth_events.user_id is
  'Null for a failed login against an unknown address: no plaintext email is ever stored.';
comment on column audit.auth_events.source_event_id is
  'The outbox event id the audit service stored this row from; bus-durable redelivers, the row is stored once. '
  'occurred_at is the outbox row''s time, so a redelivery collides on the key.';
create unique index auth_events_source_event on audit.auth_events (organisation_id, source_event_id, occurred_at)
  where source_event_id is not null;
create index auth_events_list on audit.auth_events (organisation_id, occurred_at desc);
create index auth_events_by_event on audit.auth_events (organisation_id, event, occurred_at desc);
create index auth_events_by_user on audit.auth_events (organisation_id, user_id, occurred_at desc)
  where user_id is not null;
create index auth_events_by_membership on audit.auth_events (organisation_id, membership_id, occurred_at desc)
  where membership_id is not null;
create index auth_events_by_principal on audit.auth_events (organisation_id, service_principal_id)
  where service_principal_id is not null;
create index auth_events_time on audit.auth_events using brin (occurred_at);
select platform.enable_tenant_rls('audit.auth_events');
select platform.make_append_only('audit.auth_events');

grant select, insert on audit.auth_events to silo_audit_writer;
grant select on audit.auth_events to silo_app, silo_report;

-- The organisations whose chains the audit service closes each day, so a quiet
-- organisation still gets its daily head after a restart (ch 63.2). The writer has no
-- cross-tenant read of iam.organisations; this returns identifiers only.
create function audit.organisations_for_chain_close() returns setof uuid
language sql stable security definer
set search_path = pg_catalog
as $$ select id from iam.organisations where not is_system $$;
grant execute on function audit.organisations_for_chain_close() to silo_audit_writer;

-- ===========================================================================
-- audit.audit_events: the main ledger, hash-chained per organisation
-- ===========================================================================
-- Sub-partitioned: list on retention_class, then monthly on occurred_at, so each
-- retention class is dropped by partition. Postgres requires every partition key
-- in a unique key, so both uniques carry retention_class (review D19). The class is
-- fixed per event, so a redelivered event still collides; chain_seq is assigned by
-- the single writer under an advisory lock, and the key is a backstop.

create table audit.audit_events (
  id                         bigint generated always as identity,
  occurred_at                timestamptz not null,
  retention_class            text not null default 'standard' check (retention_class in ('standard', 'high_volume')),
  source_event_id            uuid not null,
  organisation_id            uuid not null references iam.organisations (id),
  event                      text not null check (event ~ '^[a-z][a-z0-9_]*$'),
  membership_id              uuid,
  service_principal_id       uuid,
  operator_id                uuid references platform.operators (id),
  system_service             text check (system_service is null or system_service ~ '^[a-z][a-z0-9-]*$'),
  subject_membership_id      uuid,
  scope_id                   uuid,
  resource_type              text check (resource_type is null or resource_type ~ '^[a-z][a-z0-9_]*$'),
  resource_id                uuid,
  purpose_session_id         uuid,
  operator_access_session_id uuid,
  correlation_id             uuid not null,
  detail                     jsonb not null default '{}'
                               check (jsonb_typeof(detail) = 'object' and octet_length(detail::text) <= 65536),
  ip_hash                    bytea check (ip_hash is null or octet_length(ip_hash) = 32),
  chain_seq                  bigint not null check (chain_seq >= 1),
  prev_hash                  bytea not null check (octet_length(prev_hash) = 32),
  row_hash                   bytea not null check (octet_length(row_hash) = 32),
  recorded_at                timestamptz not null default now(),
  primary key (id, retention_class, occurred_at),
  unique (organisation_id, source_event_id, retention_class, occurred_at),
  unique (organisation_id, chain_seq, retention_class, occurred_at),
  foreign key (organisation_id, membership_id) references iam.memberships (organisation_id, id),
  foreign key (organisation_id, service_principal_id) references iam.service_principals (organisation_id, id),
  foreign key (organisation_id, subject_membership_id) references iam.memberships (organisation_id, id),
  foreign key (organisation_id, scope_id) references iam.scopes (organisation_id, id),
  foreign key (organisation_id, operator_access_session_id)
    references platform.operator_access_sessions (organisation_id, id),
  check (num_nonnulls(membership_id, service_principal_id, operator_id, system_service) = 1),
  check ((resource_type is null) = (resource_id is null))
) partition by list (retention_class);
comment on column audit.audit_events.resource_id is
  'Deliberate exception to the exclusive-arc rule: rows outlive what they describe, and a foreign key '
  'would block retention. The event registry validates type and id per event.';

create table audit.audit_events_standard partition of audit.audit_events
  for values in ('standard') partition by range (occurred_at);
create table audit.audit_events_high_volume partition of audit.audit_events
  for values in ('high_volume') partition by range (occurred_at);

create index audit_events_list on audit.audit_events (organisation_id, occurred_at desc);
create index audit_events_by_event on audit.audit_events (organisation_id, event, occurred_at desc);
create index audit_events_by_membership on audit.audit_events (organisation_id, membership_id, occurred_at desc)
  where membership_id is not null;
create index audit_events_by_scope on audit.audit_events (organisation_id, scope_id, occurred_at desc)
  where scope_id is not null;
create index audit_events_by_resource on audit.audit_events (organisation_id, resource_type, resource_id, occurred_at desc)
  where resource_id is not null;
create index audit_events_by_correlation on audit.audit_events (organisation_id, correlation_id);
create index audit_events_by_principal on audit.audit_events (organisation_id, service_principal_id, occurred_at desc)
  where service_principal_id is not null;
create index audit_events_by_purpose_session on audit.audit_events (organisation_id, purpose_session_id)
  where purpose_session_id is not null;
create index audit_events_by_operator_session on audit.audit_events (organisation_id, operator_access_session_id)
  where operator_access_session_id is not null;
create index audit_events_by_subject on audit.audit_events (organisation_id, subject_membership_id)
  where subject_membership_id is not null;
create index audit_events_time on audit.audit_events using brin (occurred_at);

select platform.enable_tenant_rls('audit.audit_events');
select platform.enable_tenant_rls('audit.audit_events_standard');
select platform.enable_tenant_rls('audit.audit_events_high_volume');
select platform.make_append_only('audit.audit_events');

grant select, insert on audit.audit_events to silo_audit_writer;
grant select on audit.audit_events to silo_app, silo_report;

-- ===========================================================================
-- audit.chain_heads: the daily closing hash per organisation, published to the
-- customer's audit view (ch 13.4, 63.1)
-- ===========================================================================

create table audit.chain_heads (
  id              uuid primary key,
  organisation_id uuid not null references iam.organisations (id),
  head_date       date not null,
  last_chain_seq  bigint not null check (last_chain_seq >= 1),
  head_hash       bytea not null check (octet_length(head_hash) = 32),
  event_count     bigint not null check (event_count >= 0),
  closed_at       timestamptz not null default now(),
  published_at    timestamptz,
  unique (organisation_id, id),
  unique (organisation_id, head_date)
);
select platform.enable_tenant_rls('audit.chain_heads');

-- Insert-only, except published_at, which is set once.
create function audit.chain_heads_publish_once() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
begin
  if old.published_at is not null
     or (to_jsonb(new) - 'published_at') <> (to_jsonb(old) - 'published_at') then
    raise exception 'audit.chain_heads is insert-only; published_at is set once'
      using errcode = 'insufficient_privilege';
  end if;
  return new;
end
$$;
create trigger chain_heads_publish_once before update on audit.chain_heads
  for each row execute function audit.chain_heads_publish_once();
create trigger chain_heads_no_delete before delete on audit.chain_heads
  for each row execute function platform.reject_ledger_change('strict');
create trigger chain_heads_no_truncate before truncate on audit.chain_heads
  for each statement execute function platform.reject_ledger_change();

grant select, insert, update (published_at) on audit.chain_heads to silo_audit_writer;
grant select on audit.chain_heads to silo_app, silo_report;

-- ===========================================================================
-- audit.partition_seals: running hash and row count of each closed ledger
-- partition, so a removed row is detectable (ch 63.1, 63.5). No tenant data.
-- ===========================================================================

create table audit.partition_seals (
  id             uuid primary key,
  ledger         text not null check (ledger in ('audit.auth_events', 'audit.audit_events',
                                                 'platform.model_calls', 'iam.credential_unwraps')),
  partition_name text not null,
  range_start    timestamptz not null,
  range_end      timestamptz not null,
  row_count      bigint not null check (row_count >= 0),
  running_hash   bytea not null check (octet_length(running_hash) = 32),
  sealed_at      timestamptz not null default now(),
  dropped_at     timestamptz,
  unique (ledger, partition_name),
  check (range_end > range_start)
);
create index partition_seals_by_range on audit.partition_seals (ledger, range_start);

-- Only silo_migrate may change a seal, and only to record that retention dropped
-- the partition. The seal row stays as the record that the drop was complete.
create function audit.partition_seals_guard() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
begin
  if tg_op = 'UPDATE' and current_user = 'silo_migrate'
     and old.dropped_at is null and new.dropped_at is not null
     and (to_jsonb(new) - 'dropped_at') = (to_jsonb(old) - 'dropped_at') then
    return new;
  end if;
  raise exception 'audit.partition_seals: % rejected', tg_op using errcode = 'insufficient_privilege';
end
$$;
create trigger partition_seals_guard before update or delete on audit.partition_seals
  for each row execute function audit.partition_seals_guard();
create trigger partition_seals_no_truncate before truncate on audit.partition_seals
  for each statement execute function platform.reject_ledger_change();

grant select, insert on audit.partition_seals to silo_audit_writer;
grant select on audit.partition_seals to silo_app, silo_report;

-- ===========================================================================
-- platform.outbox: the transactional outbox (ch 9.2). A service writes its durable
-- event here in the same transaction as the change; the relay publishes it.
-- ===========================================================================

create table platform.outbox (
  id                  uuid not null,
  created_at          timestamptz not null default transaction_timestamp(),
  seq                 bigint generated always as identity,
  organisation_id     uuid not null references iam.organisations (id),
  topic               text not null check (topic in ('audit.events', 'metering.usage', 'control.policy',
                                                     'control.connection', 'control.agent', 'control.action',
                                                     'siloes.capture', 'platform.purge_ledger')),
  ordering_key        text not null check (length(ordering_key) between 1 and 200),
  event               text not null check (event ~ '^[a-z][a-z0-9_]*$'),
  schema_version      integer not null default 1 check (schema_version >= 1),
  payload             jsonb not null
                        check (jsonb_typeof(payload) = 'object' and octet_length(payload::text) <= 65536),
  correlation_id      uuid not null,
  published_at        timestamptz,
  attempts            integer not null default 0 check (attempts >= 0),
  next_attempt_at     timestamptz not null default now(),
  last_error_category text check (last_error_category is null or last_error_category ~ '^[a-z][a-z0-9_]*$'),
  dead_lettered_at    timestamptz,
  primary key (id, created_at),
  unique (organisation_id, id, created_at),
  check (published_at is null or dead_lettered_at is null),
  -- Organisation-ordered topics carry the organisation id as their ordering key.
  check (topic not in ('audit.events', 'metering.usage', 'control.policy', 'siloes.capture', 'platform.purge_ledger')
         or ordering_key = organisation_id::text)
) partition by range (created_at);
comment on column platform.outbox.payload is 'References and counts only, never record values.';
comment on column platform.outbox.last_error_category is
  'A category only: broker and driver messages can carry values.';

create index outbox_pending_by_org on platform.outbox (organisation_id, seq)
  where published_at is null and dead_lettered_at is null;
create index outbox_due on platform.outbox (next_attempt_at, seq)
  where published_at is null and dead_lettered_at is null;
create index outbox_backlog_age on platform.outbox (created_at)
  where published_at is null;
create index outbox_heads on platform.outbox (topic, ordering_key, seq)
  where published_at is null and dead_lettered_at is null;
select platform.enable_tenant_rls('platform.outbox');

grant select, insert on platform.outbox to silo_app;
grant select on platform.outbox to silo_report;

-- Relay functions (review D21). The relay reads across organisations, which no
-- policy grants; these return only what publishing needs and change only the
-- publication columns. Only the head of each ordering key is claimed, so events of
-- one key are published strictly in sequence.
create function platform.outbox_claim(p_limit integer default 100,
                                      p_lease interval default interval '30 seconds')
returns table (
  id              uuid,
  created_at      timestamptz,
  seq             bigint,
  organisation_id uuid,
  topic           text,
  ordering_key    text,
  event           text,
  schema_version  integer,
  payload         jsonb,
  correlation_id  uuid,
  attempts        integer)
language plpgsql
security definer
set search_path = pg_catalog
as $$
#variable_conflict use_column
begin
  if p_limit not between 1 and 1000 then
    raise exception 'p_limit must be between 1 and 1000' using errcode = 'invalid_parameter_value';
  end if;
  return query
  with heads as (
    select distinct on (o.topic, o.ordering_key) o.id, o.created_at, o.next_attempt_at, o.seq
    from platform.outbox o
    where o.published_at is null and o.dead_lettered_at is null
    order by o.topic, o.ordering_key, o.seq
  ),
  due as (
    select o.id, o.created_at
    from platform.outbox o
    join heads h on h.id = o.id and h.created_at = o.created_at
    where h.next_attempt_at <= now()
    order by h.seq
    limit p_limit
    for update of o skip locked
  )
  update platform.outbox o
     set attempts = o.attempts + 1,
         next_attempt_at = now() + p_lease
    from due
   where o.id = due.id and o.created_at = due.created_at
  returning o.id, o.created_at, o.seq, o.organisation_id, o.topic, o.ordering_key, o.event,
            o.schema_version, o.payload, o.correlation_id, o.attempts;
end
$$;

create function platform.outbox_mark_published(p_ids uuid[], p_created_ats timestamptz[])
returns integer
language sql
security definer
set search_path = pg_catalog
as $$
  with published as (
    update platform.outbox o
       set published_at = now()
      from unnest(p_ids, p_created_ats) as k(id, created_at)
     where o.id = k.id and o.created_at = k.created_at
       and o.published_at is null and o.dead_lettered_at is null
    returning 1)
  select count(*)::integer from published
$$;

-- Records a failed publish. After 7 days unacknowledged the row is dead-lettered,
-- which raises an alert (ch 9.1).
create function platform.outbox_mark_failed(p_id uuid, p_created_at timestamptz,
                                            p_error_category text, p_retry_after interval)
returns void
language sql
security definer
set search_path = pg_catalog
as $$
  update platform.outbox o
     set last_error_category = p_error_category,
         next_attempt_at = now() + p_retry_after,
         dead_lettered_at = case when now() - o.created_at > interval '7 days' then now() end
   where o.id = p_id and o.created_at = p_created_at
     and o.published_at is null and o.dead_lettered_at is null
$$;

-- The backlog the cell's Fleet agent gates a release on (spec 11.2, audit outbox backlog): rows
-- waiting to be published (dead letters excluded, they alert on their own), counted up to
-- 100,000, and the age in seconds of the oldest. Read by the relay, which reports it.
create function platform.outbox_backlog()
returns table (pending integer, oldest_seconds integer)
language sql
stable
security definer
set search_path = pg_catalog
as $$
  select (select count(*)::integer from (select 1 from platform.outbox
            where published_at is null and dead_lettered_at is null limit 100000) waiting),
         coalesce((select extract(epoch from now() - min(created_at))::integer from platform.outbox
            where published_at is null and dead_lettered_at is null), 0)
$$;

grant execute on function platform.outbox_claim(integer, interval),
                          platform.outbox_mark_published(uuid[], timestamptz[]),
                          platform.outbox_mark_failed(uuid, timestamptz, text, interval),
                          platform.outbox_backlog()
  to silo_outbox_relay;

-- ===========================================================================
-- platform.model_calls: metadata of every model call. Never the prompt, the
-- output or a record value: one appearing here is a severity 1 incident (ch 8.5).
-- ===========================================================================

create table platform.model_calls (
  id               bigint generated always as identity,
  occurred_at      timestamptz not null default now(),
  organisation_id  uuid not null references iam.organisations (id),
  call_id          uuid not null,
  correlation_id   uuid not null,
  engagement_id    uuid,
  task_id          uuid,
  caller_service   text not null check (caller_service in ('compile', 'resolution', 'recognition',
                                                           'fde-orchestrator', 'siloes-import',
                                                           'connect-registry', 'ask', 'connector-builder', 'ontology')),
  request_type     text not null check (request_type in ('vocabulary', 'document_extraction', 'embedding')),
  model            text not null,
  model_route      text not null,
  input_tokens     integer not null check (input_tokens >= 0),
  output_tokens    integer not null check (output_tokens >= 0),
  thinking_tokens  integer not null default 0 check (thinking_tokens >= 0),
  prompt_hash      bytea not null check (octet_length(prompt_hash) = 32),
  outcome          text not null check (outcome in ('ok', 'refused', 'error')),
  refusal_category text check (refusal_category in ('redaction_match', 'record_value_field', 'concurrency_bound',
                                                    'length_bound', 'extraction_not_enabled')),
  latency_ms       integer check (latency_ms is null or latency_ms >= 0),
  provider_cost    numeric(14,8) check (provider_cost is null or provider_cost >= 0),
  primary key (id, occurred_at),
  unique (organisation_id, call_id, occurred_at),
  check ((outcome = 'refused') = (refusal_category is not null))
) partition by range (occurred_at);
comment on column platform.model_calls.engagement_id is
  'AI FDE engagement, for reconciling provider cost per task. No foreign key: ledger.';
comment on column platform.model_calls.provider_cost is
  'Pounds the provider charges for the call at its route''s prices (input, and output with thinking, per million tokens); null where the route names no price.';
create index model_calls_by_correlation on platform.model_calls (organisation_id, correlation_id);
create index model_calls_list on platform.model_calls (organisation_id, occurred_at desc);
create index model_calls_by_engagement on platform.model_calls (organisation_id, engagement_id, occurred_at)
  where engagement_id is not null;
create index model_calls_time on platform.model_calls using brin (occurred_at);
select platform.enable_tenant_rls('platform.model_calls');
select platform.make_append_only('platform.model_calls');

grant select, insert on platform.model_calls to silo_audit_writer;
grant select on platform.model_calls to silo_app, silo_report;

-- The margin calculator's measured cost per compile (74.4, 74.7): across the cell, how many
-- compiles have been logged and their mean tokens (input, output and thinking) over the
-- most recent p_limit. Counts only: no organisation, no prompt.
create function platform.compile_call_sample(p_limit integer)
  returns table (logged bigint, sampled bigint, mean_tokens numeric, priced bigint, mean_cost numeric)
language sql stable security definer
set search_path = pg_catalog
as $$
  with recent as (
    select input_tokens + output_tokens + thinking_tokens as tokens, provider_cost from platform.model_calls
    where caller_service = 'compile' and outcome = 'ok'
    order by occurred_at desc
    limit least(greatest(p_limit, 1), 10000)
  )
  select (select count(*) from platform.model_calls where caller_service = 'compile' and outcome = 'ok'),
         (select count(*) from recent), (select avg(tokens) from recent),
         (select count(provider_cost) from recent), (select avg(provider_cost) from recent)
$$;
revoke all on function platform.compile_call_sample(integer) from public;
grant execute on function platform.compile_call_sample(integer) to silo_app;

