-- ============================================================================
-- Domain: gov, iam, platform
-- ============================================================================

-- Governance (schema gov), the remaining identity tables (connection grants, field
-- policies, object type markings, credential unwraps) and the remaining platform
-- tables (tenant migrations, organisation exports).
-- Design: docs/siloDatabaseDesign.doc.md, schema gov, schema iam and schema platform.
-- Keys to tables in later domains (Connect, ontology, Actions, Siloes, workspace) are
-- in gov_iam_platform_fks.sql. Not here, because they need the permission catalogue
-- and effective-permission resolution: the delegation and revocation triggers on
-- connection grants, the clearance.grant, purpose.define and marking.declassify
-- holder checks, and the declassification execution trigger.

-- ===========================================================================
-- Shared trigger function for this domain
-- ===========================================================================

-- Set-once columns. Trigger arguments name columns that may go from null to a value
-- once and never change after that.
create function gov.set_once_columns() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
declare
  c text;
  o jsonb := to_jsonb(old);
  n jsonb := to_jsonb(new);
begin
  foreach c in array tg_argv loop
    if o ->> c is not null and o -> c is distinct from n -> c then
      raise exception '%.%.% is set once and cannot be changed', tg_table_schema, tg_table_name, c
        using errcode = 'insufficient_privilege';
    end if;
  end loop;
  return new;
end
$$;

-- ===========================================================================
-- Markings and clearances (ch 58.3)
-- ===========================================================================

create table gov.markings (
  id              uuid primary key,
  organisation_id uuid not null references iam.organisations (id),
  name            text not null check (length(btrim(name)) > 0),
  kind            text not null check (kind in ('classification', 'compartment', 'purpose')),
  rank            integer,
  description     text not null default '',
  created_by      uuid not null,
  created_at      timestamptz not null default now(),
  retired_at      timestamptz,
  updated_at      timestamptz not null default now(),
  version         integer not null default 1,
  unique (organisation_id, id),
  unique (organisation_id, name),
  unique (organisation_id, id, kind),
  foreign key (organisation_id, created_by) references iam.memberships (organisation_id, id),
  check (rank is null or kind = 'classification')
);
comment on table gov.markings is 'Organisation-defined mandatory access labels (spec 58.3). Retired, never deleted.';
comment on column gov.markings.rank is 'Order of a classification marking. Set only for kind classification.';
create index markings_created_by on gov.markings (organisation_id, created_by);
select platform.add_updated_at_trigger('gov.markings');
select platform.enable_tenant_rls('gov.markings');
create trigger markings_frozen before update on gov.markings
  for each row execute function platform.freeze_columns('id', 'organisation_id', 'kind');

grant select, insert, update on gov.markings to silo_app;
grant select on gov.markings to silo_report;

create table gov.clearances (
  id                   uuid primary key,
  organisation_id      uuid not null references iam.organisations (id),
  membership_id        uuid,
  service_principal_id uuid,
  marking_id           uuid not null,
  marking_kind         text not null check (marking_kind in ('classification', 'compartment')),
  granted_by           uuid not null,
  granted_at           timestamptz not null default now(),
  expires_at           timestamptz,
  revoked_by           uuid,
  revoked_at           timestamptz,
  unique (organisation_id, id),
  foreign key (organisation_id, membership_id) references iam.memberships (organisation_id, id),
  foreign key (organisation_id, service_principal_id) references iam.service_principals (organisation_id, id),
  foreign key (organisation_id, marking_id, marking_kind) references gov.markings (organisation_id, id, kind),
  foreign key (organisation_id, granted_by) references iam.memberships (organisation_id, id),
  foreign key (organisation_id, revoked_by) references iam.memberships (organisation_id, id),
  check (num_nonnulls(membership_id, service_principal_id) = 1),
  check (revoked_by is null or revoked_at is not null),
  check (expires_at is null or expires_at > granted_at)
);
comment on table gov.clearances is
  'Clearance of a membership or service principal for a classification or compartment marking (spec 58.3).';
comment on column gov.clearances.marking_kind is
  'Copy of the marking kind, held true by the composite key, so a purpose marking can never be cleared.';
comment on column gov.clearances.revoked_by is 'Null with revoked_at set when the expiry sweep revoked it.';
create unique index clearances_live_membership on gov.clearances (organisation_id, membership_id, marking_id)
  where revoked_at is null and membership_id is not null;
create unique index clearances_live_principal on gov.clearances (organisation_id, service_principal_id, marking_id)
  where revoked_at is null and service_principal_id is not null;
create index clearances_marking on gov.clearances (organisation_id, marking_id, marking_kind)
  where revoked_at is null;
create index clearances_granted_by on gov.clearances (organisation_id, granted_by);
create index clearances_revoked_by on gov.clearances (organisation_id, revoked_by) where revoked_by is not null;
select platform.enable_tenant_rls('gov.clearances');
create trigger clearances_frozen before update on gov.clearances
  for each row execute function platform.freeze_columns(
    'id', 'organisation_id', 'membership_id', 'service_principal_id', 'marking_id', 'marking_kind',
    'granted_by', 'granted_at');

grant select, insert, update on gov.clearances to silo_app;
grant select on gov.clearances to silo_report;

-- Declassifiers (spec 58.10 "a membership named for that marking"; decision 2026-11-14; D81):
-- a membership, or the members of a scope, named as able to request a marking's
-- declassification. Append-only: a grant is approved once, by a second person, and revoked
-- once; nothing else about it changes and no row is deleted. Kept apart from roles.
create table gov.declassifier_memberships (
  id              uuid primary key,
  organisation_id uuid not null references iam.organisations (id),
  marking_id      uuid not null,
  membership_id   uuid,
  scope_id        uuid,
  justification   text not null check (length(btrim(justification)) between 1 and 2000),
  granted_by      uuid not null,
  granted_at      timestamptz not null default now(),
  approved_by     uuid,
  approved_at     timestamptz,
  expires_at      timestamptz,
  revoked_by      uuid,
  revoked_at      timestamptz,
  unique (organisation_id, id),
  foreign key (organisation_id, marking_id) references gov.markings (organisation_id, id),
  foreign key (organisation_id, membership_id) references iam.memberships (organisation_id, id),
  foreign key (organisation_id, scope_id) references iam.scopes (organisation_id, id),
  foreign key (organisation_id, granted_by) references iam.memberships (organisation_id, id),
  foreign key (organisation_id, approved_by) references iam.memberships (organisation_id, id),
  foreign key (organisation_id, revoked_by) references iam.memberships (organisation_id, id),
  check (num_nonnulls(membership_id, scope_id) = 1),
  check (approved_by is null or approved_by <> granted_by),
  check ((approved_by is null) = (approved_at is null)),
  check ((revoked_by is null) = (revoked_at is null)),
  check (expires_at is null or expires_at > granted_at)
);
comment on table gov.declassifier_memberships is
  'Who is named for a marking as its declassifier (58.10): approved by a second person, append-only, apart from roles (decision 2026-11-14).';
create index declassifier_memberships_marking on gov.declassifier_memberships (organisation_id, marking_id);
create index declassifier_memberships_membership on gov.declassifier_memberships (organisation_id, membership_id) where membership_id is not null;
create index declassifier_memberships_scope on gov.declassifier_memberships (organisation_id, scope_id) where scope_id is not null;
select platform.enable_tenant_rls('gov.declassifier_memberships');
create trigger declassifier_memberships_frozen before update on gov.declassifier_memberships
  for each row execute function platform.freeze_columns('id', 'organisation_id', 'marking_id', 'membership_id', 'scope_id', 'justification',
    'granted_by', 'granted_at', 'expires_at');
-- Approved once, revoked once.
create function gov.declassifier_memberships_once() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
begin
  if (old.approved_at is not null and new.approved_at is distinct from old.approved_at)
     or (old.revoked_at is not null and new.revoked_at is distinct from old.revoked_at) then
    raise exception 'a declassifier grant is approved once and revoked once' using errcode = 'insufficient_privilege';
  end if;
  return new;
end
$$;
create trigger declassifier_memberships_once before update on gov.declassifier_memberships
  for each row execute function gov.declassifier_memberships_once();
grant select, insert on gov.declassifier_memberships to silo_app;
grant update (approved_by, approved_at, revoked_by, revoked_at) on gov.declassifier_memberships to silo_app;

-- ===========================================================================
-- Purposes (ch 58.5)
-- ===========================================================================

-- ===========================================================================
-- gov.change_policies, change_freezes, change_exceptions: when a dedicated, sovereign or
-- on-premises cell may change (spec 11.5)
-- ===========================================================================
-- "Sovereign, on-premises and dedicated customers set change windows and freezes. During a
-- freeze Fleet applies only a security fix the customer's named change authority approves in
-- writing." Set by a holder of org.change_window.manage; an exception is approved by the named
-- change authority alone, and its statement is the writing. The cell's Fleet agent reads them
-- (gov.change_policies_for_fleet) and carries them to fleet-control (D120).

create table gov.change_policies (
  organisation_id                uuid primary key references iam.organisations (id),
  time_zone                      text not null check (length(time_zone) between 1 and 64),
  windows                        jsonb not null default '[]' check (jsonb_typeof(windows) = 'array'),
  change_authority_membership_id uuid,
  updated_by                     uuid not null,
  created_at                     timestamptz not null default now(),
  updated_at                     timestamptz not null default now(),
  foreign key (organisation_id, change_authority_membership_id) references iam.memberships (organisation_id, id),
  foreign key (organisation_id, updated_by) references iam.memberships (organisation_id, id)
);
comment on table gov.change_policies is
  'The organisation''s weekly change windows (day 1 Monday to 7, local start and end in time_zone; an end not after the start '
  'runs past midnight; none: any time) and its named change authority (spec 11.5).';
create index change_policies_authority on gov.change_policies (organisation_id, change_authority_membership_id);
create index change_policies_updated_by on gov.change_policies (organisation_id, updated_by);
select platform.add_updated_at_trigger('gov.change_policies');
select platform.enable_tenant_rls('gov.change_policies');
