create table gov.change_freezes (
  id              uuid primary key,
  organisation_id uuid not null references iam.organisations (id),
  starts_at       timestamptz not null,
  ends_at         timestamptz not null,
  reason          text not null check (length(btrim(reason)) between 1 and 500),
  set_by          uuid not null,
  set_at          timestamptz not null default now(),
  ended_at        timestamptz,
  ended_by        uuid,
  unique (organisation_id, id),
  foreign key (organisation_id, set_by) references iam.memberships (organisation_id, id),
  foreign key (organisation_id, ended_by) references iam.memberships (organisation_id, id),
  check (starts_at < ends_at),
  check ((ended_at is null) = (ended_by is null))
);
comment on table gov.change_freezes is
  'Freezes: from starts_at to ends_at, or to ended_at when ended early, no change but an approved security fix (spec 11.5).';
create index change_freezes_current on gov.change_freezes (organisation_id, ends_at);
create index change_freezes_set_by on gov.change_freezes (organisation_id, set_by);
create index change_freezes_ended_by on gov.change_freezes (organisation_id, ended_by);
select platform.enable_tenant_rls('gov.change_freezes');
grant select, insert, update on gov.change_freezes to silo_app;
grant select on gov.change_freezes to silo_report;

create table gov.change_exceptions (
  id              uuid primary key,
  organisation_id uuid not null references iam.organisations (id),
  freeze_id       uuid not null,
  release_id      text not null check (release_id ~ '^[A-Za-z0-9._+-]{1,128}$'),
  statement       text not null check (length(btrim(statement)) between 1 and 4000),
  approved_by     uuid not null,
  approved_at     timestamptz not null default now(),
  unique (organisation_id, id),
  unique (organisation_id, freeze_id, release_id),
  foreign key (organisation_id, freeze_id) references gov.change_freezes (organisation_id, id),
  foreign key (organisation_id, approved_by) references iam.memberships (organisation_id, id)
);
comment on table gov.change_exceptions is
  'The change authority''s written approval of a security fix during a freeze: the release, and the statement in their words. '
  'Fleet applies it only if the release is a security fix and the approver is still the named authority. Never changed.';
create index change_exceptions_approved_by on gov.change_exceptions (organisation_id, approved_by);
select platform.enable_tenant_rls('gov.change_exceptions');
grant select, insert on gov.change_exceptions to silo_app;
grant select on gov.change_exceptions to silo_report;

-- What the cell's Fleet agent carries to fleet-control: each organisation's policy, its freezes
-- not yet over, and the approvals made in them. Every organisation of the cell, so it reads past
-- row-level security; it returns nothing else.
create function gov.change_policies_for_fleet(p_now timestamptz)
  returns table (organisation_id uuid, policy jsonb)
language sql stable security definer
set search_path = pg_catalog
as $$
  select p.organisation_id, jsonb_build_object(
    'organisationId', p.organisation_id,
    'timeZone', p.time_zone,
    'windows', p.windows,
    'changeAuthorityMembershipId', p.change_authority_membership_id,
    'freezes', coalesce((select jsonb_agg(jsonb_build_object('id', f.id, 'startsAt', f.starts_at, 'endsAt', least(f.ends_at, coalesce(f.ended_at, f.ends_at)),
                                                             'reason', f.reason) order by f.starts_at)
                         from gov.change_freezes f
                         where f.organisation_id = p.organisation_id and least(f.ends_at, coalesce(f.ended_at, f.ends_at)) > p_now
                           and f.starts_at < least(f.ends_at, coalesce(f.ended_at, f.ends_at))), '[]'::jsonb),
    'exceptions', coalesce((select jsonb_agg(jsonb_build_object('releaseId', e.release_id, 'freezeId', e.freeze_id, 'approvedBy', e.approved_by,
                                                                'approvedAt', e.approved_at, 'statement', e.statement) order by e.approved_at)
                            from gov.change_exceptions e join gov.change_freezes f on f.organisation_id = e.organisation_id and f.id = e.freeze_id
                            where e.organisation_id = p.organisation_id and least(f.ends_at, coalesce(f.ended_at, f.ends_at)) > p_now), '[]'::jsonb))
  from gov.change_policies p
  order by p.organisation_id
$$;
revoke all on function gov.change_policies_for_fleet(timestamptz) from public;
grant execute on function gov.change_policies_for_fleet(timestamptz) to silo_app;

create table gov.purpose_definitions (
  id                     uuid primary key,
  organisation_id        uuid not null references iam.organisations (id),
  marking_id             uuid not null,
  marking_kind           text not null default 'purpose' check (marking_kind = 'purpose'),
  name                   text not null check (length(btrim(name)) > 0),
  description            text not null,
  lawful_basis           text,
  max_session_minutes    integer not null check (max_session_minutes > 0),
  requires_justification boolean not null default true,
  requires_approval      boolean not null default false,
  -- What the purpose is for (decision 2026-11-14; D81). Everything but analysis needs each
  -- declaration approved by a second person: export, sharing outside the organisation,
  -- writing back to sources, and marked data in AI or simulation outputs.
  use                    text not null default 'analysis'
                           check (use in ('analysis', 'export', 'external_sharing', 'write_back', 'ai_or_simulation')),
  status                 text not null default 'draft' check (status in ('draft', 'approved', 'suspended', 'retired')),
  approved_by            uuid,
  approved_at            timestamptz,
  review_due_at          timestamptz,
  created_by             uuid not null,
  -- Who answers for it: its creator, until they are removed and it transfers to a super admin (55.7; D207).
  owner_membership_id    uuid not null,
  created_at             timestamptz not null default now(),
  updated_at             timestamptz not null default now(),
  version                integer not null default 1,
  unique (organisation_id, id),
  constraint purpose_definitions_marking_fkey
    foreign key (organisation_id, marking_id, marking_kind) references gov.markings (organisation_id, id, kind),
  foreign key (organisation_id, approved_by) references iam.memberships (organisation_id, id),
  foreign key (organisation_id, created_by) references iam.memberships (organisation_id, id),
  foreign key (organisation_id, owner_membership_id) references iam.memberships (organisation_id, id),
  check (approved_by <> created_by),
  check (requires_approval or use = 'analysis'),
  check ((approved_by is null) = (approved_at is null)),
  check (status not in ('approved', 'suspended') or approved_by is not null)
);
comment on table gov.purpose_definitions is
  'An approved reason for which purpose-marked data may be reached (spec 58.5).';
comment on column gov.purpose_definitions.lawful_basis is 'Recorded, not validated.';
-- marking_kind is constant, so this is one live definition per marking; it also
-- serves the marking foreign key.
create unique index purpose_definitions_live_marking on gov.purpose_definitions (organisation_id, marking_id, marking_kind)
  where status <> 'retired';
create index purpose_definitions_review_due on gov.purpose_definitions (organisation_id, review_due_at)
  where status = 'approved';
create index purpose_definitions_approved_by on gov.purpose_definitions (organisation_id, approved_by)
  where approved_by is not null;
create index purpose_definitions_created_by on gov.purpose_definitions (organisation_id, created_by);
create index purpose_definitions_owner on gov.purpose_definitions (organisation_id, owner_membership_id);
select platform.add_updated_at_trigger('gov.purpose_definitions');
select platform.enable_tenant_rls('gov.purpose_definitions');
create trigger purpose_definitions_frozen before update on gov.purpose_definitions
  for each row execute function platform.freeze_columns(
    'id', 'organisation_id', 'marking_id', 'marking_kind', 'created_by', 'created_at');

-- Once a definition has been approved, its approval is never cleared (a re-approval
-- after review may replace it).
create function gov.purpose_definitions_keep_approval() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
begin
  if old.approved_by is not null and new.approved_by is null then
    raise exception 'the approval of purpose definition % cannot be cleared', old.id
      using errcode = 'insufficient_privilege';
  end if;
  return new;
end
$$;
create trigger purpose_definitions_keep_approval before update of approved_by, approved_at on gov.purpose_definitions
  for each row execute function gov.purpose_definitions_keep_approval();

grant select, insert, update on gov.purpose_definitions to silo_app;
grant select on gov.purpose_definitions to silo_report;

