create table gov.purpose_sessions (
  id                    uuid primary key,
  organisation_id       uuid not null references iam.organisations (id),
  membership_id         uuid,
  service_principal_id  uuid,
  session_id            uuid not null,
  purpose_definition_id uuid not null,
  app_id                uuid,
  justification         text,
  approval_chain_id     uuid,
  -- A declaration its definition requires approved (D81) reaches nothing until a holder of
  -- purpose.define other than the declarer approves it, within its time.
  requires_approval     boolean not null default false,
  approved_by           uuid,
  approved_at           timestamptz,
  declared_at           timestamptz not null default now(),
  expires_at            timestamptz not null,
  ended_at              timestamptz,
  ended_reason          text check (ended_reason in ('expired', 'ended_by_user', 'session_revoked',
                                                     'eligibility_revoked', 'definition_suspended',
                                                     'membership_removed')),
  unique (organisation_id, id),
  foreign key (organisation_id, membership_id) references iam.memberships (organisation_id, id),
  constraint purpose_sessions_principal_fkey
    foreign key (organisation_id, service_principal_id) references iam.service_principals (organisation_id, id),
  foreign key (organisation_id, session_id) references iam.sessions (organisation_id, id),
  constraint purpose_sessions_definition_fkey
    foreign key (organisation_id, purpose_definition_id) references gov.purpose_definitions (organisation_id, id),
  check (num_nonnulls(membership_id, service_principal_id) = 1),
  check ((ended_at is null) = (ended_reason is null)),
  check (expires_at > declared_at),
  constraint purpose_sessions_approved_by_fkey foreign key (organisation_id, approved_by) references iam.memberships (organisation_id, id),
  check ((approved_by is null) = (approved_at is null)),
  check (requires_approval or approved_by is null),
  check (approved_by is null or approved_by is distinct from membership_id)
);
comment on table gov.purpose_sessions is
  'Record of a declared purpose, bounded in time and by the parent session (spec 58.5). Never extended in place.';
comment on column gov.purpose_sessions.justification is 'Never sent to a model.';
create index purpose_sessions_open_by_session on gov.purpose_sessions (organisation_id, session_id)
  where ended_at is null;
create index purpose_sessions_by_membership on gov.purpose_sessions (organisation_id, membership_id, declared_at desc);
create index purpose_sessions_open_by_definition on gov.purpose_sessions (organisation_id, purpose_definition_id)
  where ended_at is null;
create index purpose_sessions_expiry on gov.purpose_sessions (organisation_id, expires_at) where ended_at is null;
create index purpose_sessions_principal on gov.purpose_sessions (organisation_id, service_principal_id)
  where service_principal_id is not null;
create index purpose_sessions_app on gov.purpose_sessions (organisation_id, app_id) where app_id is not null;
