  for each row execute function gov.set_once_columns('ended_at', 'ended_reason');

-- Declaration checks. Definer: the parent session is in iam.sessions, which only the
-- auth service can read. The definition must be approved (read under a share lock,
-- so a concurrent suspension waits or sees this row); a justification is present
-- when required; expires_at is within max_session_minutes and the parent session's
-- expiry; the parent session is live and belongs to the declarer.
create function gov.purpose_sessions_check_declare() returns trigger
language plpgsql
security definer
set search_path = pg_catalog
as $$
declare
  v_org     uuid := nullif(current_setting('app.org_id', true), '')::uuid;
  v_def     record;
  v_session record;
begin
  if v_org is not null and v_org <> new.organisation_id then
    raise exception 'purpose session belongs to another organisation' using errcode = 'insufficient_privilege';
  end if;

  select d.status, d.max_session_minutes, d.requires_justification into v_def
  from gov.purpose_definitions d
  where d.organisation_id = new.organisation_id and d.id = new.purpose_definition_id
  for share;
  if not found then
    raise exception 'purpose definition % not found', new.purpose_definition_id
      using errcode = 'foreign_key_violation';
  end if;
  if v_def.status <> 'approved' then
    raise exception 'purpose definition % is %, not approved', new.purpose_definition_id, v_def.status
      using errcode = 'check_violation';
  end if;
  if v_def.requires_justification and length(btrim(coalesce(new.justification, ''))) = 0 then
    raise exception 'purpose definition % requires a justification', new.purpose_definition_id
      using errcode = 'check_violation';
  end if;
  if new.expires_at > new.declared_at + make_interval(mins => v_def.max_session_minutes) then
    raise exception 'purpose session exceeds the definition''s % minutes', v_def.max_session_minutes
      using errcode = 'check_violation';
  end if;

  select s.expires_at, s.revoked_at, s.active_membership_id, s.service_principal_id into v_session
  from iam.sessions s
  where s.organisation_id = new.organisation_id and s.id = new.session_id;
  if not found then
    raise exception 'session % not found', new.session_id using errcode = 'foreign_key_violation';
  end if;
  if v_session.revoked_at is not null or v_session.expires_at <= now() then
    raise exception 'session % is not live', new.session_id using errcode = 'check_violation';
  end if;
  if new.expires_at > v_session.expires_at then
    raise exception 'purpose session cannot outlive its session' using errcode = 'check_violation';
  end if;
  if new.membership_id is distinct from v_session.active_membership_id
     or new.service_principal_id is distinct from v_session.service_principal_id then
    raise exception 'session % belongs to another member or principal', new.session_id
      using errcode = 'check_violation';
  end if;
  return new;
end
$$;
create trigger purpose_sessions_check_declare before insert on gov.purpose_sessions
  for each row execute function gov.purpose_sessions_check_declare();

-- Suspending or retiring a definition ends its open purpose sessions in the same
-- transaction (the service also deletes their Redis copies). Checked at commit.
create function gov.purpose_definitions_sessions_ended() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
begin
  if exists (select 1 from gov.purpose_sessions s
             where s.organisation_id = new.organisation_id
               and s.purpose_definition_id = new.id
               and s.ended_at is null) then
    raise exception 'purpose definition % is %: end its open purpose sessions in the same transaction',
      new.id, new.status using errcode = 'check_violation';
  end if;
  return null;
end
$$;
create constraint trigger purpose_definitions_sessions_ended
  after update of status on gov.purpose_definitions
  deferrable initially deferred
  for each row when (new.status in ('suspended', 'retired') and old.status is distinct from new.status)
  execute function gov.purpose_definitions_sessions_ended();

grant select, insert, update on gov.purpose_sessions to silo_app;
grant select on gov.purpose_sessions to silo_report;

-- ===========================================================================
-- Lineage (ch 59.2)
-- ===========================================================================

-- Hash partitioned by organisation, so the keys carry the partition key and the
-- edge and artefact marking tables can reference (organisation_id, id).
create table gov.lineage_nodes (
  id                              uuid not null,
  organisation_id                 uuid not null references iam.organisations (id),
  kind                            text not null check (kind in (
                                    'source_field', 'connector_version', 'connection', 'property',
                                    'object_type_version', 'link_type_version', 'action_type_version',
                                    'function_version', 'object_set', 'view', 'app_version', 'export',
                                    'ask_prompt', 'action', 'receipt', 'scenario', 'simulation_result',
                                    'silo', 'import_file', 'finding', 'workbook', 'report', 'process_analysis', 'notebook')),
  ref_id                          uuid not null,
  version                         text not null check (length(version) > 0),
  created_by_membership_id        uuid,
  created_by_service_principal_id uuid,
  created_at                      timestamptz not null default now(),
  primary key (organisation_id, id),
  unique (organisation_id, kind, ref_id, version),
  constraint lineage_nodes_created_by_membership_fkey
    foreign key (organisation_id, created_by_membership_id) references iam.memberships (organisation_id, id),
  constraint lineage_nodes_created_by_principal_fkey
    foreign key (organisation_id, created_by_service_principal_id) references iam.service_principals (organisation_id, id),
  check (num_nonnulls(created_by_membership_id, created_by_service_principal_id) <= 1)
) partition by hash (organisation_id);
comment on table gov.lineage_nodes is
  'Immutable versioned nodes of the lineage graph (spec 59.2). Never holds record values.';
comment on column gov.lineage_nodes.ref_id is
  'The resource, typed by kind. No foreign key (identity decision 8): lineage outlives purged receipts, '
  'Silo files and exports; a nightly sweep reports orphans and never deletes.';
comment on column gov.lineage_nodes.version is 'Version or hash (CEL source hash, manifest hash).';
comment on column gov.lineage_nodes.created_by_membership_id is 'Neither creator set means a platform service.';

create table gov.lineage_nodes_p0  partition of gov.lineage_nodes for values with (modulus 16, remainder 0);
create table gov.lineage_nodes_p1  partition of gov.lineage_nodes for values with (modulus 16, remainder 1);
create table gov.lineage_nodes_p2  partition of gov.lineage_nodes for values with (modulus 16, remainder 2);
create table gov.lineage_nodes_p3  partition of gov.lineage_nodes for values with (modulus 16, remainder 3);
create table gov.lineage_nodes_p4  partition of gov.lineage_nodes for values with (modulus 16, remainder 4);
create table gov.lineage_nodes_p5  partition of gov.lineage_nodes for values with (modulus 16, remainder 5);
create table gov.lineage_nodes_p6  partition of gov.lineage_nodes for values with (modulus 16, remainder 6);
create table gov.lineage_nodes_p7  partition of gov.lineage_nodes for values with (modulus 16, remainder 7);
create table gov.lineage_nodes_p8  partition of gov.lineage_nodes for values with (modulus 16, remainder 8);
create table gov.lineage_nodes_p9  partition of gov.lineage_nodes for values with (modulus 16, remainder 9);
create table gov.lineage_nodes_p10 partition of gov.lineage_nodes for values with (modulus 16, remainder 10);
create table gov.lineage_nodes_p11 partition of gov.lineage_nodes for values with (modulus 16, remainder 11);
create table gov.lineage_nodes_p12 partition of gov.lineage_nodes for values with (modulus 16, remainder 12);
create table gov.lineage_nodes_p13 partition of gov.lineage_nodes for values with (modulus 16, remainder 13);
create table gov.lineage_nodes_p14 partition of gov.lineage_nodes for values with (modulus 16, remainder 14);
create table gov.lineage_nodes_p15 partition of gov.lineage_nodes for values with (modulus 16, remainder 15);

create index lineage_nodes_created_by_membership on gov.lineage_nodes (organisation_id, created_by_membership_id)
  where created_by_membership_id is not null;
create index lineage_nodes_created_by_principal on gov.lineage_nodes (organisation_id, created_by_service_principal_id)
  where created_by_service_principal_id is not null;
select platform.enable_tenant_rls('gov.lineage_nodes');
select platform.enable_tenant_rls(format('gov.lineage_nodes_p%s', i)::regclass) from generate_series(0, 15) as i;
-- Immutable: never updated, never deleted. The writer inserts with on conflict do nothing.
select platform.make_append_only('gov.lineage_nodes');

grant select, insert on gov.lineage_nodes to silo_app;
grant select on gov.lineage_nodes to silo_report;

create table gov.lineage_edges (
  id              bigint generated always as identity,
  created_at      timestamptz not null default now(),
  organisation_id uuid not null references iam.organisations (id),
  from_node_id    uuid not null,
  to_node_id      uuid not null,
  relation        text not null check (relation in (
                    'read_via', 'maps_to', 'member_of', 'derives', 'filters_on', 'traverses', 'compiles_to',
                    'uses', 'exported_from', 'writes', 'receipted_by', 'reverts', 'simulates')),
  primary key (id, created_at),
  constraint lineage_edges_from_node_fkey
    foreign key (organisation_id, from_node_id) references gov.lineage_nodes (organisation_id, id),
  constraint lineage_edges_to_node_fkey
    foreign key (organisation_id, to_node_id) references gov.lineage_nodes (organisation_id, id),
  check (from_node_id <> to_node_id)
) partition by range (created_at);
comment on table gov.lineage_edges is
  'Append-only typed edges from input node to derived node (spec 59.2). Retention must cover the longest '
  'artefact retention: traversal reads every attached partition.';
create index lineage_edges_downstream on gov.lineage_edges (organisation_id, from_node_id, relation);
create index lineage_edges_upstream on gov.lineage_edges (organisation_id, to_node_id, relation);
create index lineage_edges_time on gov.lineage_edges using brin (created_at);
select platform.enable_tenant_rls('gov.lineage_edges');
select platform.make_append_only('gov.lineage_edges');

grant select, insert on gov.lineage_edges to silo_app;
grant select on gov.lineage_edges to silo_report;

-- ===========================================================================
-- Declassification and artefact markings (ch 58.7, 58.9)
-- ===========================================================================

create table gov.marking_declassifications (
  id                           uuid primary key,
  organisation_id              uuid not null references iam.organisations (id),
  action_id                    uuid not null,
  lineage_node_id              uuid not null,
  marking_id                   uuid not null,
  resource_type                text not null check (resource_type in ('object_type', 'connection', 'property', 'link_type', 'action_type',
                                                                      'silo', 'view', 'app', 'function', 'interface', 'property_mapping')),
  resource_id                  uuid not null,
  apply_downstream             boolean not null default false,
  justification                text not null check (length(trim(justification)) > 0),
  readers_gaining_access_count integer check (readers_gaining_access_count >= 0),
  requested_by                 uuid not null,
  approval_chain_id            uuid,
  created_at                   timestamptz not null default now(),
  executed_at                  timestamptz,
  reverted_at                  timestamptz,
  unique (organisation_id, id),
  constraint marking_declassifications_action_key unique (organisation_id, action_id, lineage_node_id, marking_id),
  constraint marking_declassifications_node_fkey
    foreign key (organisation_id, lineage_node_id) references gov.lineage_nodes (organisation_id, id),
  constraint marking_declassifications_marking_fkey
    foreign key (organisation_id, marking_id) references gov.markings (organisation_id, id),
  constraint marking_declassifications_requested_by_fkey
    foreign key (organisation_id, requested_by) references iam.memberships (organisation_id, id),
  check (executed_at is null or approval_chain_id is not null),
  check (reverted_at is null or executed_at is not null)
);
comment on table gov.marking_declassifications is
  'Audited removal of a marking, carried by an Action (spec 58.9). Never deleted.';
comment on column gov.marking_declassifications.action_id is
  'The Action carrying the change: the declassification itself (its own id). It changes governance state, not a source '
  'record, so it has no action.mutations row; its approval chain is of subject kind declassification (D62).';
comment on column gov.marking_declassifications.resource_type is
  'The resource the direct marking was on, with resource_id: what execution removes it from and a revert puts it back on.';
comment on column gov.marking_declassifications.lineage_node_id is 'The resource or artefact declassified.';
comment on column gov.marking_declassifications.readers_gaining_access_count is 'Computed at preview.';
comment on column gov.marking_declassifications.requested_by is
  'A membership only, so no service principal can request a declassification.';
create index marking_declassifications_pending on gov.marking_declassifications (organisation_id, created_at desc)
  where executed_at is null;
create index marking_declassifications_node on gov.marking_declassifications (organisation_id, lineage_node_id);
create index marking_declassifications_marking on gov.marking_declassifications (organisation_id, marking_id);
create index marking_declassifications_requested_by on gov.marking_declassifications (organisation_id, requested_by);
create index marking_declassifications_approval_chain on gov.marking_declassifications (organisation_id, approval_chain_id)
  where approval_chain_id is not null;
select platform.enable_tenant_rls('gov.marking_declassifications');
create trigger marking_declassifications_frozen before update on gov.marking_declassifications
  for each row execute function platform.freeze_columns(
    'id', 'organisation_id', 'action_id', 'lineage_node_id', 'marking_id', 'resource_type', 'resource_id', 'requested_by', 'created_at');
create trigger marking_declassifications_set_once before update on gov.marking_declassifications
  for each row execute function gov.set_once_columns('executed_at', 'reverted_at');

grant select, insert, update on gov.marking_declassifications to silo_app;
grant select on gov.marking_declassifications to silo_report;

create table gov.artefact_markings (
  id                     uuid not null,
  organisation_id        uuid not null references iam.organisations (id),
  lineage_node_id        uuid not null,
  marking_id             uuid not null,
  origin                 text not null check (origin in ('direct', 'inherited')),
  inherited_from_node_id uuid,
  applied_at             timestamptz not null default now(),
  declassification_id    uuid,
  removed_at             timestamptz,
  primary key (organisation_id, id),
  constraint artefact_markings_node_fkey
    foreign key (organisation_id, lineage_node_id) references gov.lineage_nodes (organisation_id, id),
  constraint artefact_markings_inherited_from_fkey
    foreign key (organisation_id, inherited_from_node_id) references gov.lineage_nodes (organisation_id, id),
  constraint artefact_markings_marking_fkey
    foreign key (organisation_id, marking_id) references gov.markings (organisation_id, id),
  constraint artefact_markings_declassification_fkey
    foreign key (organisation_id, declassification_id) references gov.marking_declassifications (organisation_id, id),
  check ((origin = 'inherited') = (inherited_from_node_id is not null)),
  check (inherited_from_node_id is distinct from lineage_node_id),
  check ((declassification_id is null) = (removed_at is null))
) partition by hash (organisation_id);
comment on table gov.artefact_markings is
  'Markings an artefact carries, direct or inherited by propagation (spec 58.7). Removed rows are retained.';
comment on column gov.artefact_markings.inherited_from_node_id is 'Nearest upstream node carrying the marking.';

create table gov.artefact_markings_p0  partition of gov.artefact_markings for values with (modulus 16, remainder 0);
create table gov.artefact_markings_p1  partition of gov.artefact_markings for values with (modulus 16, remainder 1);
create table gov.artefact_markings_p2  partition of gov.artefact_markings for values with (modulus 16, remainder 2);
create table gov.artefact_markings_p3  partition of gov.artefact_markings for values with (modulus 16, remainder 3);
create table gov.artefact_markings_p4  partition of gov.artefact_markings for values with (modulus 16, remainder 4);
create table gov.artefact_markings_p5  partition of gov.artefact_markings for values with (modulus 16, remainder 5);
create table gov.artefact_markings_p6  partition of gov.artefact_markings for values with (modulus 16, remainder 6);
create table gov.artefact_markings_p7  partition of gov.artefact_markings for values with (modulus 16, remainder 7);
create table gov.artefact_markings_p8  partition of gov.artefact_markings for values with (modulus 16, remainder 8);
create table gov.artefact_markings_p9  partition of gov.artefact_markings for values with (modulus 16, remainder 9);
create table gov.artefact_markings_p10 partition of gov.artefact_markings for values with (modulus 16, remainder 10);
create table gov.artefact_markings_p11 partition of gov.artefact_markings for values with (modulus 16, remainder 11);
create table gov.artefact_markings_p12 partition of gov.artefact_markings for values with (modulus 16, remainder 12);
create table gov.artefact_markings_p13 partition of gov.artefact_markings for values with (modulus 16, remainder 13);
create table gov.artefact_markings_p14 partition of gov.artefact_markings for values with (modulus 16, remainder 14);
create table gov.artefact_markings_p15 partition of gov.artefact_markings for values with (modulus 16, remainder 15);

create unique index artefact_markings_live on gov.artefact_markings (organisation_id, lineage_node_id, marking_id)
  where removed_at is null;
create index artefact_markings_marking on gov.artefact_markings (organisation_id, marking_id)
  where removed_at is null;
create index artefact_markings_inherited_from on gov.artefact_markings (organisation_id, inherited_from_node_id)
  where inherited_from_node_id is not null;
create index artefact_markings_declassification on gov.artefact_markings (organisation_id, declassification_id)
  where declassification_id is not null;
select platform.enable_tenant_rls('gov.artefact_markings');
select platform.enable_tenant_rls(format('gov.artefact_markings_p%s', i)::regclass) from generate_series(0, 15) as i;
create trigger artefact_markings_frozen before update on gov.artefact_markings
  for each row execute function platform.freeze_columns(
    'id', 'organisation_id', 'lineage_node_id', 'marking_id', 'applied_at');
create trigger artefact_markings_removed_once before update on gov.artefact_markings
  for each row execute function gov.set_once_columns('removed_at', 'declassification_id');

grant select, insert, update on gov.artefact_markings to silo_app;
grant select on gov.artefact_markings to silo_report;

-- ===========================================================================
-- Resource markings (ch 58.3): direct markings on resources other than object types
-- ===========================================================================

-- Exclusive arc over ten resource tables (keys in gov_iam_platform_fks.sql). Rows are
-- inserted and deleted, never updated; a delete is a declassification, made only by
-- the declassification Action.
create table gov.resource_markings (
  id                  uuid primary key,
  organisation_id     uuid not null references iam.organisations (id),
  connection_id       uuid,
  property_mapping_id uuid,
  property_id         uuid,
  link_type_id        uuid,
  action_type_id      uuid,
  silo_id             uuid,
  view_id             uuid,
  app_id              uuid,
  function_id         uuid,
  interface_id        uuid,
  marking_id          uuid not null,
  applied_by          uuid not null,
  applied_at          timestamptz not null default now(),
  unique (organisation_id, id),
  constraint resource_markings_marking_fkey
    foreign key (organisation_id, marking_id) references gov.markings (organisation_id, id),
  constraint resource_markings_applied_by_fkey
    foreign key (organisation_id, applied_by) references iam.memberships (organisation_id, id),
  check (num_nonnulls(connection_id, property_mapping_id, property_id, link_type_id, action_type_id, silo_id,
                      view_id, app_id, function_id, interface_id) = 1)
);
comment on table gov.resource_markings is
  'Direct markings on resources other than object types (spec 58.3); object types use iam.object_type_markings.';
comment on column gov.resource_markings.property_mapping_id is 'The spec''s field map entry.';
create unique index resource_markings_connection on gov.resource_markings (organisation_id, connection_id, marking_id)
  where connection_id is not null;
create unique index resource_markings_property_mapping on gov.resource_markings (organisation_id, property_mapping_id, marking_id)
  where property_mapping_id is not null;
create unique index resource_markings_property on gov.resource_markings (organisation_id, property_id, marking_id)
  where property_id is not null;
create unique index resource_markings_link_type on gov.resource_markings (organisation_id, link_type_id, marking_id)
  where link_type_id is not null;
create unique index resource_markings_action_type on gov.resource_markings (organisation_id, action_type_id, marking_id)
  where action_type_id is not null;
create unique index resource_markings_silo on gov.resource_markings (organisation_id, silo_id, marking_id)
  where silo_id is not null;
create unique index resource_markings_view on gov.resource_markings (organisation_id, view_id, marking_id)
  where view_id is not null;
create unique index resource_markings_app on gov.resource_markings (organisation_id, app_id, marking_id)
  where app_id is not null;
create unique index resource_markings_function on gov.resource_markings (organisation_id, function_id, marking_id)
  where function_id is not null;
create unique index resource_markings_interface on gov.resource_markings (organisation_id, interface_id, marking_id)
  where interface_id is not null;
create index resource_markings_marking on gov.resource_markings (organisation_id, marking_id);
create index resource_markings_applied_by on gov.resource_markings (organisation_id, applied_by);
select platform.enable_tenant_rls('gov.resource_markings');

grant select, insert, delete on gov.resource_markings to silo_app;
grant select on gov.resource_markings to silo_report;

-- ===========================================================================
-- iam.connection_grants (ch 57.3): default-deny access of a grantee to a connection
-- ===========================================================================

create table iam.connection_grants (
  id                           uuid primary key,
  organisation_id              uuid not null references iam.organisations (id),
  connection_id                uuid not null,
  grantee_membership_id        uuid,
  grantee_scope_id             uuid,
  grantee_role_id              uuid,
  grantee_service_principal_id uuid,
  access                       text not null check (access in ('read', 'write')),
  include_descendants          boolean not null default true,
  granted_by                   uuid not null,
  granted_at_scope_id          uuid,
  granted_at                   timestamptz not null default now(),
  expires_at                   timestamptz,
  revoked_by                   uuid,
  revoked_at                   timestamptz,
  silenced_at                  timestamptz,
  unique (organisation_id, id),
  constraint connection_grants_membership_fkey
    foreign key (organisation_id, grantee_membership_id) references iam.memberships (organisation_id, id),
  constraint connection_grants_scope_fkey
    foreign key (organisation_id, grantee_scope_id) references iam.scopes (organisation_id, id),
  constraint connection_grants_role_fkey
    foreign key (organisation_id, grantee_role_id) references iam.roles (organisation_id, id),
  constraint connection_grants_principal_fkey
    foreign key (organisation_id, grantee_service_principal_id) references iam.service_principals (organisation_id, id),
  constraint connection_grants_granted_by_fkey
    foreign key (organisation_id, granted_by) references iam.memberships (organisation_id, id),
  constraint connection_grants_revoked_by_fkey
    foreign key (organisation_id, revoked_by) references iam.memberships (organisation_id, id),
  constraint connection_grants_granted_at_scope_fkey
    foreign key (organisation_id, granted_at_scope_id) references iam.scopes (organisation_id, id),
  check (num_nonnulls(grantee_membership_id, grantee_scope_id, grantee_role_id, grantee_service_principal_id) = 1),
  check (include_descendants or grantee_scope_id is not null),
  check (revoked_by is null or revoked_at is not null),
  check (expires_at is null or expires_at > granted_at)
);
comment on table iam.connection_grants is 'Default-deny access of a grantee to a connection (spec 57.3).';
comment on column iam.connection_grants.include_descendants is
  'Meaningful for a scope grantee only; must be true for any other grantee.';
comment on column iam.connection_grants.granted_at_scope_id is
  'Null only when a super admin issued it. Decides revocation authority.';
-- One live grant per grantee and connection; read and write to one grantee are one
-- row with the higher access.
create unique index connection_grants_live on iam.connection_grants (
  organisation_id, connection_id,
  coalesce(grantee_membership_id, grantee_scope_id, grantee_role_id, grantee_service_principal_id))
  where revoked_at is null;
create index connection_grants_connection on iam.connection_grants (organisation_id, connection_id)
  where revoked_at is null;
create index connection_grants_membership on iam.connection_grants (organisation_id, grantee_membership_id)
  where grantee_membership_id is not null and revoked_at is null;
create index connection_grants_scope on iam.connection_grants (organisation_id, grantee_scope_id)
  where grantee_scope_id is not null and revoked_at is null;
create index connection_grants_role on iam.connection_grants (organisation_id, grantee_role_id)
  where grantee_role_id is not null and revoked_at is null;
create index connection_grants_principal on iam.connection_grants (organisation_id, grantee_service_principal_id)
  where grantee_service_principal_id is not null and revoked_at is null;
create index connection_grants_granted_at_scope on iam.connection_grants (organisation_id, granted_at_scope_id)
  where granted_at_scope_id is not null;
create index connection_grants_granted_by on iam.connection_grants (organisation_id, granted_by);
create index connection_grants_revoked_by on iam.connection_grants (organisation_id, revoked_by)
  where revoked_by is not null;
select platform.enable_tenant_rls('iam.connection_grants');
create trigger connection_grants_frozen before update on iam.connection_grants
  for each row execute function platform.freeze_columns(
    'id', 'organisation_id', 'connection_id', 'grantee_membership_id', 'grantee_scope_id', 'grantee_role_id',
    'grantee_service_principal_id', 'granted_by', 'granted_at_scope_id', 'granted_at');

grant select, insert, update on iam.connection_grants to silo_app;
grant select on iam.connection_grants to silo_report;

-- ===========================================================================
-- iam.field_policies (ch 57.4): deny, mask or redact a source field or a property
-- ===========================================================================

create table iam.field_policies (
  id                    uuid primary key,
  organisation_id       uuid not null references iam.organisations (id),
  connection_id         uuid,
  field_path            text check (field_path is null or length(field_path) > 0),
  property_id           uuid,
  effect                text not null check (effect in ('deny', 'mask', 'redact')),
  applies_to_role_id    uuid,
  applies_to_marking_id uuid,
  applies_to_scope_id   uuid,
  include_descendants   boolean not null default false,
  created_by            uuid not null,
  created_at            timestamptz not null default now(),
  updated_at            timestamptz not null default now(),
  version               integer not null default 1,
  retired_at            timestamptz,
  unique (organisation_id, id),
  constraint field_policies_role_fkey
    foreign key (organisation_id, applies_to_role_id) references iam.roles (organisation_id, id),
  constraint field_policies_marking_fkey
    foreign key (organisation_id, applies_to_marking_id) references gov.markings (organisation_id, id),
  constraint field_policies_scope_fkey
    foreign key (organisation_id, applies_to_scope_id) references iam.scopes (organisation_id, id),
  constraint field_policies_created_by_fkey
    foreign key (organisation_id, created_by) references iam.memberships (organisation_id, id),
  check ((connection_id is not null and field_path is not null and property_id is null)
         or (connection_id is null and field_path is null and property_id is not null))
);
comment on table iam.field_policies is
  'Deny, mask or redact a source field or a property, resolved before the plan exists (spec 57.4). Retired, not deleted.';
comment on column iam.field_policies.applies_to_role_id is
  'Each applies_to column that is set narrows the audience (AND); all null means everyone.';
comment on column iam.field_policies.include_descendants is 'Meaningful with applies_to_scope_id.';
create index field_policies_field on iam.field_policies (organisation_id, connection_id, field_path)
  where connection_id is not null and retired_at is null;
create index field_policies_property on iam.field_policies (organisation_id, property_id)
  where property_id is not null and retired_at is null;
create index field_policies_role on iam.field_policies (organisation_id, applies_to_role_id)
  where applies_to_role_id is not null;
create index field_policies_marking on iam.field_policies (organisation_id, applies_to_marking_id)
  where applies_to_marking_id is not null;
create index field_policies_scope on iam.field_policies (organisation_id, applies_to_scope_id)
  where applies_to_scope_id is not null;
create index field_policies_created_by on iam.field_policies (organisation_id, created_by);
select platform.add_updated_at_trigger('iam.field_policies');
select platform.enable_tenant_rls('iam.field_policies');
create trigger field_policies_frozen before update on iam.field_policies
  for each row execute function platform.freeze_columns('id', 'organisation_id', 'created_by', 'created_at');

grant select, insert, update on iam.field_policies to silo_app;
grant select on iam.field_policies to silo_report;

-- ===========================================================================
-- iam.object_type_markings (ch 21 and 57 merged): direct markings on an object type
-- ===========================================================================

-- No id: the row is its key. Removal is a declassification: the row is deleted
-- only by the declassification Action, and its receipt records it.
create table iam.object_type_markings (
  organisation_id uuid not null references iam.organisations (id),
  object_type_id  uuid not null,
  marking_id      uuid not null,
  applied_by      uuid not null,
  applied_at      timestamptz not null default now(),
  primary key (organisation_id, object_type_id, marking_id),
  constraint object_type_markings_marking_fkey
    foreign key (organisation_id, marking_id) references gov.markings (organisation_id, id),
  constraint object_type_markings_applied_by_fkey
    foreign key (organisation_id, applied_by) references iam.memberships (organisation_id, id)
);
comment on table iam.object_type_markings is
  'Direct markings on an object type, applying to every version of it (spec 21 and 57).';
create index object_type_markings_marking on iam.object_type_markings (organisation_id, marking_id);
create index object_type_markings_applied_by on iam.object_type_markings (organisation_id, applied_by);
select platform.enable_tenant_rls('iam.object_type_markings');

grant select, insert, delete on iam.object_type_markings to silo_app;
grant select on iam.object_type_markings to silo_report;

-- ===========================================================================
-- gov.marking_propagations: a marking applied upstream, carried downstream along lineage
-- (spec 58.6). Requested by trigger in the transaction that applies the marking; walked
-- by the lineage service in bounded batches; evaluated at read time until complete.
-- ===========================================================================
create table gov.marking_propagations (
  id               uuid not null,
  organisation_id  uuid not null references iam.organisations (id),
  marking_id       uuid not null,
  source_kind      text not null check (source_kind in ('connection', 'source_field', 'property', 'object_type_version',
                     'link_type_version', 'action_type_version', 'function_version', 'silo', 'view', 'app_version')),
  source_ref_id    uuid not null,
  requested_at     timestamptz not null default now(),
  first_pass_at    timestamptz,
  nodes_marked     integer not null default 0 check (nodes_marked >= 0),
  completed_at     timestamptz,
  refused_reason   text check (refused_reason is null or refused_reason in ('depth_bound', 'source_unmarked')),
  primary key (organisation_id, id),
  constraint marking_propagations_marking_fkey
    foreign key (organisation_id, marking_id) references gov.markings (organisation_id, id),
  check (completed_at is null or first_pass_at is not null)
);
comment on table gov.marking_propagations is
  'A direct marking applied upstream, walked downstream by the lineage service in bounded batches (spec 58.6). '
  'Until completed, policy evaluates it at read time, so there is no window of exposure.';
comment on column gov.marking_propagations.source_kind is 'The lineage node kind of the marked resource; source_ref_id is its id.';
comment on column gov.marking_propagations.refused_reason is
  'depth_bound: the walk is deeper than its bound and stays pending (evaluated at read time); '
  'source_unmarked: the source lost the marking before the walk (a declassification).';
create index marking_propagations_pending on gov.marking_propagations (organisation_id, source_kind, source_ref_id)
  where completed_at is null;
create index marking_propagations_queue on gov.marking_propagations (requested_at)
  where completed_at is null and refused_reason is null;
create index marking_propagations_marking on gov.marking_propagations (organisation_id, marking_id);
select platform.enable_tenant_rls('gov.marking_propagations');
grant select, insert, update on gov.marking_propagations to silo_app;
grant select on gov.marking_propagations to silo_report;

-- Requested in the transaction that applies the direct marking (spec 58.6). Definer: the
-- applying role need not write the table or execute platform.uuid_v7.
create function gov.request_marking_propagation() returns trigger
language plpgsql
security definer
set search_path = pg_catalog
as $$
declare
  v_kind text;
  v_ref  uuid;
begin
  if tg_table_name = 'object_type_markings' then
    v_kind := 'object_type_version'; v_ref := new.object_type_id;
  elsif new.connection_id is not null then v_kind := 'connection'; v_ref := new.connection_id;
  elsif new.property_mapping_id is not null then v_kind := 'source_field'; v_ref := new.property_mapping_id;
  elsif new.property_id is not null then v_kind := 'property'; v_ref := new.property_id;
  elsif new.link_type_id is not null then v_kind := 'link_type_version'; v_ref := new.link_type_id;
  elsif new.action_type_id is not null then v_kind := 'action_type_version'; v_ref := new.action_type_id;
  elsif new.function_id is not null then v_kind := 'function_version'; v_ref := new.function_id;
  elsif new.silo_id is not null then v_kind := 'silo'; v_ref := new.silo_id;
  elsif new.view_id is not null then v_kind := 'view'; v_ref := new.view_id;
  elsif new.app_id is not null then v_kind := 'app_version'; v_ref := new.app_id;
  else
    -- An interface is not a lineage node: its implementations carry their own markings.
    return null;
  end if;
  insert into gov.marking_propagations (id, organisation_id, marking_id, source_kind, source_ref_id)
  values (platform.uuid_v7(), new.organisation_id, new.marking_id, v_kind, v_ref);
  return null;
end
$$;
create trigger resource_markings_propagate after insert on gov.resource_markings
  for each row execute function gov.request_marking_propagation();
create trigger object_type_markings_propagate after insert on iam.object_type_markings
  for each row execute function gov.request_marking_propagation();

-- The lineage service's queue, across organisations: identifiers only.
create function gov.pending_marking_propagations(p_limit integer) returns table (organisation_id uuid, id uuid)
language sql stable security definer
set search_path = pg_catalog
as $$
  select organisation_id, id from gov.marking_propagations
  where completed_at is null and refused_reason is null order by requested_at limit p_limit
$$;
grant execute on function gov.pending_marking_propagations(integer) to silo_app;

-- ===========================================================================
-- iam.credential_unwraps (ch 61.3, 61.9): append-only ledger of every unwrap
-- ===========================================================================

create table iam.credential_unwraps (
  id                       bigint generated always as identity,
  occurred_at              timestamptz not null default now(),
  organisation_id          uuid not null references iam.organisations (id),
  connection_credential_id uuid,
  identity_provider_id     uuid,
  mfa_factor_id            uuid,
  user_id                  uuid,
  reason                   text not null check (reason in ('connect', 'query', 'mutation', 'read_back', 'refresh',
                                                           'probe', 'rotation', 'change_stream', 'idp',
                                                           'mfa_verify', 'sso_assert', 'action_event', 'webhook')),
  calling_service          text not null check (calling_service ~ '^[a-z][a-z0-9-]*$'),
  correlation_id           uuid not null,
  membership_id            uuid,
  service_principal_id     uuid,
  key_version_id           uuid
                             constraint credential_unwraps_key_version_fkey references iam.kms_key_versions (id),
  dek_cache_hit            boolean not null,
  outcome                  text not null check (outcome in ('ok', 'failed', 'held_by_agent')),
  primary key (id, occurred_at),
  constraint credential_unwraps_identity_provider_fkey
    foreign key (organisation_id, identity_provider_id) references iam.identity_providers (organisation_id, id),
  constraint credential_unwraps_mfa_factor_fkey foreign key (mfa_factor_id) references iam.mfa_factors (id),
  constraint credential_unwraps_user_fkey foreign key (user_id) references iam.users (id),
  check (num_nonnulls(connection_credential_id, identity_provider_id, mfa_factor_id) = 1),
  check ((reason in ('idp', 'sso_assert')) = (identity_provider_id is not null)),
  check ((reason = 'mfa_verify') = (mfa_factor_id is not null)),
  check (reason <> 'mfa_verify' or user_id is not null),
  check (num_nonnulls(membership_id, service_principal_id) <= 1),
  -- An agent-held credential was used on the agent's host: nothing was opened here.
  check ((outcome = 'held_by_agent') = (key_version_id is null)),
  check (outcome <> 'held_by_agent' or (connection_credential_id is not null and not dek_cache_hit))
) partition by range (occurred_at);
comment on table iam.credential_unwraps is
  'Append-only ledger of every unwrap of a sealed credential, with its reason (spec 61.3, 61.9). '
  'Never holds the secret or last_four.';
comment on column iam.credential_unwraps.calling_service is 'Service name from the deployment identity.';
comment on column iam.credential_unwraps.mfa_factor_id is
  'The MFA factor whose secret was opened (reason mfa_verify, spec 61.2). Factors are revoked, never deleted.';
comment on column iam.credential_unwraps.user_id is
  'The person verifying MFA (reason mfa_verify). The row stays tenant-scoped: organisation_id is the organisation '
  'being logged into, which login routing resolves before MFA, so the event is in that organisation''s audit.';
comment on column iam.credential_unwraps.membership_id is
  'Actor, id only: no foreign key, so ledger rows survive any later change. Both actors null for platform jobs.';
comment on column iam.credential_unwraps.service_principal_id is 'Actor, id only: no foreign key (see membership_id).';
comment on column iam.credential_unwraps.outcome is
  'ok or failed for a credential opened here; held_by_agent for a use of a credential the customer keeps on the Silo '
  'Agent''s host (spec 6, 10.7), where the cell holds no value and opens nothing (no key version).';
comment on column iam.credential_unwraps.dek_cache_hit is
  'True when the DEK came from the cache, so every use is logged even when KMS was not called.';
comment on constraint credential_unwraps_key_version_fkey on iam.credential_unwraps is
  'lint:no-index key versions are retired, never deleted; ledger reads lead with organisation_id';
create index credential_unwraps_by_credential on iam.credential_unwraps
  (organisation_id, connection_credential_id, occurred_at desc) where connection_credential_id is not null;
create index credential_unwraps_by_identity_provider on iam.credential_unwraps
  (organisation_id, identity_provider_id, occurred_at desc) where identity_provider_id is not null;
create index credential_unwraps_by_mfa_factor on iam.credential_unwraps
  (organisation_id, mfa_factor_id, occurred_at desc) where mfa_factor_id is not null;
create index credential_unwraps_by_reason on iam.credential_unwraps (organisation_id, reason, occurred_at desc);
create index credential_unwraps_by_correlation on iam.credential_unwraps (organisation_id, correlation_id);
create index credential_unwraps_time on iam.credential_unwraps using brin (occurred_at);
select platform.enable_tenant_rls('iam.credential_unwraps');
select platform.make_append_only('iam.credential_unwraps');

-- The credential service is the only writer.
grant select, insert on iam.credential_unwraps to silo_credential;
grant select on iam.credential_unwraps to silo_app, silo_report;

-- ===========================================================================
-- platform.tenant_migrations (ch 6.4, 6.7): cell-to-cell moves of an organisation
-- ===========================================================================

create table platform.tenant_migrations (
  id                                     uuid primary key,
  organisation_id                        uuid not null references iam.organisations (id),
  source_cell_id                         text not null
                                           constraint tenant_migrations_source_cell_fkey references platform.cells (id),
  destination_cell_id                    text not null
                                           constraint tenant_migrations_destination_cell_fkey references platform.cells (id),
  reason                                 text not null check (reason in ('residency_change', 'rebalancing',
                                                                         'promotion_dedicated', 'promotion_sovereign')),
  status                                 text not null default 'requested' check (status in (
                                           'requested', 'approved', 'scheduled', 'read_only', 'exporting',
                                           'importing', 'verifying', 'reauthorising', 'directory_updated',
                                           'source_read_only', 'source_purged', 'completed', 'aborted')),
  -- The customer's super admin, or for rebalancing (which Silo starts) the operator.
  requested_by_membership_id             uuid,
  requested_by_operator_id               uuid
                                           constraint tenant_migrations_requested_by_operator_fkey
                                           references platform.operators (id),
  approved_by_membership_id              uuid,
  security_officer_operator_id           uuid
                                           constraint tenant_migrations_security_officer_fkey
                                           references platform.operators (id),
  sovereign_security_officer_operator_id uuid
                                           constraint tenant_migrations_sovereign_officer_fkey
                                           references platform.operators (id),
  -- The operator who confirmed the contract a promotion needs (spec 6.4).
  contract_operator_id                   uuid
                                           constraint tenant_migrations_contract_operator_fkey
                                           references platform.operators (id),
  notice_given_at                        timestamptz,
  customer_objected_at                   timestamptz,
  objection_note                         text,
  window_starts_at                       timestamptz,
  window_ends_at                         timestamptz,
  read_only_at                           timestamptz,
  export_started_at                      timestamptz,
  export_completed_at                    timestamptz,
  import_started_at                      timestamptz,
  import_completed_at                    timestamptz,
  verified_at                            timestamptz,
  connections_reauthorised_at            timestamptz,
  directory_updated_at                   timestamptz,
  source_read_only_until                 timestamptz,
  source_purged_at                       timestamptz,
  purge_receipt_object_key               text,
  purge_receipt_sha256                   bytea check (purge_receipt_sha256 is null or octet_length(purge_receipt_sha256) = 32),
  bundle_object_key                      text,
  bundle_bytes                           bigint check (bundle_bytes >= 0),
  bundle_checksum                        bytea check (bundle_checksum is null or octet_length(bundle_checksum) = 32),
  destination_key_id                     text check (destination_key_id ~ '^[0-9a-f]{64}$'),
  destination_import_key                 text check (length(destination_import_key) between 1 and 4096),
  move_siloes                            boolean not null default true,
  connections_pending_reauthorisation    integer check (connections_pending_reauthorisation >= 0),
  aborted_at                             timestamptz,
  abort_reason                           text check (abort_reason ~ '^[a-z][a-z0-9_]*$'),
  completed_at                           timestamptz,
  created_at                             timestamptz not null default now(),
  updated_at                             timestamptz not null default now(),
  version                                integer not null default 1,
  unique (organisation_id, id),
  constraint tenant_migrations_requested_by_fkey
    foreign key (organisation_id, requested_by_membership_id) references iam.memberships (organisation_id, id),
  constraint tenant_migrations_approved_by_fkey
    foreign key (organisation_id, approved_by_membership_id) references iam.memberships (organisation_id, id),
  check (source_cell_id <> destination_cell_id),
  check ((window_starts_at is null) = (window_ends_at is null)),
  check (window_ends_at > window_starts_at),
  check (num_nonnulls(requested_by_membership_id, requested_by_operator_id) = 1),
  check ((requested_by_operator_id is not null) = (reason = 'rebalancing')),
  -- Reason-specific approvals, required once the request has moved past 'requested'
  -- (spec 6.4): the customer's super admin in writing, plus the Silo security officer for a
  -- residency change and the sovereign security officer for the sovereign cell. Rebalancing
  -- gives 30 days' notice and goes ahead unless the customer objects.
  check (status in ('requested', 'aborted') or reason = 'rebalancing' or approved_by_membership_id is not null),
  check (status in ('requested', 'aborted') or reason <> 'residency_change' or security_officer_operator_id is not null),
  check (status in ('requested', 'aborted') or reason <> 'promotion_sovereign'
         or sovereign_security_officer_operator_id is not null),
  check (status in ('requested', 'aborted') or reason not in ('promotion_dedicated', 'promotion_sovereign')
         or contract_operator_id is not null),
  check (status in ('requested', 'aborted') or reason <> 'rebalancing'
         or (notice_given_at is not null and customer_objected_at is null)),
  check (reason <> 'rebalancing' or window_starts_at is null or notice_given_at is null
         or window_starts_at >= notice_given_at + interval '30 days'),
  check ((destination_key_id is null) = (destination_import_key is null)),
  check (status not in ('scheduled', 'read_only', 'exporting') or destination_key_id is not null),
  check (objection_note is null or customer_objected_at is not null),
  check (status <> 'completed' or (verified_at is not null and directory_updated_at is not null)),
  check ((status = 'completed') = (completed_at is not null)),
  check ((status = 'aborted') = (aborted_at is not null)),
  check (abort_reason is null or aborted_at is not null)
);
comment on table platform.tenant_migrations is
  'One row per cell-to-cell move of an organisation: approvals, window, stage times, checksums (spec 6.4, 6.7).';
comment on column platform.tenant_migrations.status is
  'Stages in order (spec 6.4). Moves forward only; aborted is reachable from any stage before completed.';
comment on column platform.tenant_migrations.source_read_only_until is 'directory_updated_at plus 30 days.';
comment on column platform.tenant_migrations.bundle_checksum is 'SHA-256 of the encrypted bundle.';
comment on column platform.tenant_migrations.destination_key_id is
  'SHA-256 of the destination import key''s SubjectPublicKeyInfo, hex.';
comment on column platform.tenant_migrations.destination_import_key is
  'The public half of the destination cell''s import key (PEM), which the export is sealed to. Never a private key.';
comment on column platform.tenant_migrations.move_siloes is
  'Whether the destination residency permits Siloes (spec 6.4); when false they stay behind and are purged with the source.';
comment on column platform.tenant_migrations.purge_receipt_sha256 is
  'SHA-256 of the source purge receipt, recorded in the destination when the receipt is handed over.';
comment on column platform.tenant_migrations.connections_pending_reauthorisation is
  'Connections left to re-authorise. Credentials are never migrated (spec 6.4).';
comment on column platform.tenant_migrations.abort_reason is 'A category only.';
comment on constraint tenant_migrations_source_cell_fkey on platform.tenant_migrations is
  'lint:no-index cells are retired, never deleted; one row per migration';
comment on constraint tenant_migrations_destination_cell_fkey on platform.tenant_migrations is
  'lint:no-index cells are retired, never deleted; one row per migration';
-- One live migration per organisation; the write pause in Actions and Crons reads it.
create unique index tenant_migrations_live on platform.tenant_migrations (organisation_id)
  where status not in ('completed', 'aborted');
create index tenant_migrations_list on platform.tenant_migrations (organisation_id, created_at desc);
create index tenant_migrations_due on platform.tenant_migrations (status, window_starts_at)
  where status in ('approved', 'scheduled');
create index tenant_migrations_purge_due on platform.tenant_migrations (source_read_only_until)
  where status = 'source_read_only';
create index tenant_migrations_requested_by on platform.tenant_migrations (organisation_id, requested_by_membership_id)
  where requested_by_membership_id is not null;
create index tenant_migrations_requested_by_operator on platform.tenant_migrations (requested_by_operator_id)
  where requested_by_operator_id is not null;
create index tenant_migrations_approved_by on platform.tenant_migrations (organisation_id, approved_by_membership_id)
  where approved_by_membership_id is not null;
select platform.add_updated_at_trigger('platform.tenant_migrations');
select platform.enable_tenant_rls('platform.tenant_migrations');
create trigger tenant_migrations_frozen before update on platform.tenant_migrations
  for each row execute function platform.freeze_columns(
    'id', 'organisation_id', 'source_cell_id', 'destination_cell_id', 'reason', 'requested_by_membership_id',
    'requested_by_operator_id', 'created_at');

grant select, insert, update on platform.tenant_migrations to silo_app;
grant select on platform.tenant_migrations to silo_report;

create table platform.tenant_migration_tables (
  id                    uuid primary key,
  organisation_id       uuid not null references iam.organisations (id),
  migration_id          uuid not null,
  schema_name           text not null check (schema_name ~ '^[a-z_][a-z0-9_]*$'),
  table_name            text not null check (table_name ~ '^[a-z_][a-z0-9_]*$'),
  source_row_count      bigint check (source_row_count >= 0),
  source_checksum       bytea check (source_checksum is null or octet_length(source_checksum) = 32),
  destination_row_count bigint check (destination_row_count >= 0),
  destination_checksum  bytea check (destination_checksum is null or octet_length(destination_checksum) = 32),
  matched               boolean,
  verified_at           timestamptz,
  created_at            timestamptz not null default now(),
  unique (organisation_id, id),
  constraint tenant_migration_tables_table_key unique (organisation_id, migration_id, schema_name, table_name),
  constraint tenant_migration_tables_migration_fkey
    foreign key (organisation_id, migration_id) references platform.tenant_migrations (organisation_id, id),
  check ((source_row_count is null) = (source_checksum is null)),
  check ((destination_row_count is null) = (destination_checksum is null)),
  -- Null until both sides are present; when set, equals the comparison.
  check (matched is null
         or (source_row_count is not null and destination_row_count is not null
             and matched = (source_row_count = destination_row_count and source_checksum = destination_checksum)))
);
comment on table platform.tenant_migration_tables is
  'Per-table row counts and checksums at both ends of a tenant migration (spec 6.4, 6.7). No values.';
comment on column platform.tenant_migration_tables.source_checksum is
  'SHA-256 over the table''s rows for the organisation, each as jsonb text without identity columns, sorted. Set at export.';
comment on column platform.tenant_migration_tables.destination_checksum is 'Set at import verification.';
create index tenant_migration_tables_unmatched on platform.tenant_migration_tables (organisation_id, migration_id)
  where matched is distinct from true;
select platform.enable_tenant_rls('platform.tenant_migration_tables');
-- Only counts, checksums, matched and verified_at change after insert.
create trigger tenant_migration_tables_frozen before update on platform.tenant_migration_tables
  for each row execute function platform.freeze_columns(
    'id', 'organisation_id', 'migration_id', 'schema_name', 'table_name', 'created_at');

grant select, insert, update on platform.tenant_migration_tables to silo_app;
grant select on platform.tenant_migration_tables to silo_report;

-- Status moves forward through the stage list; completed and aborted are final; and
-- completed needs every table of the migration matched.
create function platform.tenant_migrations_check_status() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
declare
  v_order constant text[] := array['requested', 'approved', 'scheduled', 'read_only', 'exporting', 'importing',
                                   'verifying', 'reauthorising', 'directory_updated', 'source_read_only',
                                   'source_purged', 'completed'];
begin
  if old.status in ('completed', 'aborted') then
    raise exception 'tenant migration % is %; its status is final', old.id, old.status
      using errcode = 'check_violation';
  end if;
  if new.status <> 'aborted'
     and array_position(v_order, new.status) < array_position(v_order, old.status) then
    raise exception 'tenant migration status moves forward only: % to %', old.status, new.status
      using errcode = 'check_violation';
  end if;
  if new.status = 'completed' and exists (
       select 1 from platform.tenant_migration_tables t
       where t.organisation_id = new.organisation_id and t.migration_id = new.id
         and t.matched is distinct from true) then
    raise exception 'tenant migration % has tables not yet matched', new.id using errcode = 'check_violation';
  end if;
  return new;
end
$$;
create trigger tenant_migrations_check_status before update of status on platform.tenant_migrations
  for each row when (old.status is distinct from new.status)
  execute function platform.tenant_migrations_check_status();

-- ===========================================================================
-- platform.org_exports (ch 2.6): organisation exit export jobs
-- ===========================================================================

create table platform.org_exports (
  id                         uuid primary key,
  organisation_id            uuid not null references iam.organisations (id),
  requested_by_membership_id uuid not null,
  status                     text not null default 'requested'
                               check (status in ('requested', 'running', 'completed', 'failed', 'cancelled')),
  billing_status_at_request  text not null
                               check (billing_status_at_request in ('active', 'past_due', 'suspended', 'cancelled')),
  format_version             text not null check (length(btrim(format_version)) > 0),
  clearance_snapshot_at      timestamptz not null,
  cleared_marking_ids        uuid[] not null default '{}',
  requested_at               timestamptz not null default now(),
  started_at                 timestamptz,
  completed_at               timestamptz,
  failed_at                  timestamptz,
  failure_category           text check (failure_category ~ '^[a-z][a-z0-9_]*$'),
  manifest_object_key        text,
  manifest_sha256            bytea check (manifest_sha256 is null or octet_length(manifest_sha256) = 32),
  bundle_object_key          text,
  bundle_bytes               bigint check (bundle_bytes >= 0),
  bundle_sha256              bytea check (bundle_sha256 is null or octet_length(bundle_sha256) = 32),
  item_count                 integer check (item_count >= 0),
  omitted_item_count         integer check (omitted_item_count >= 0),
  receipt_object_key         text,
  receipt_sha256             bytea check (receipt_sha256 is null or octet_length(receipt_sha256) = 32),
  receipt_issued_at          timestamptz,
  updated_at                 timestamptz not null default now(),
  version                    integer not null default 1,
  unique (organisation_id, id),
  constraint org_exports_requested_by_fkey
    foreign key (organisation_id, requested_by_membership_id) references iam.memberships (organisation_id, id),
  check (status not in ('running', 'completed') or started_at is not null),
  check ((status = 'completed') = (completed_at is not null)),
  check ((status = 'failed') = (failed_at is not null)),
  check (failure_category is null or status = 'failed'),
  check ((manifest_object_key is null) = (manifest_sha256 is null)),
  check (num_nonnulls(bundle_object_key, bundle_bytes, bundle_sha256) in (0, 3)),
  check (num_nonnulls(receipt_object_key, receipt_sha256, receipt_issued_at) in (0, 3)),
  -- The receipt (counts, hashes, named omissions) is issued when the job completes.
  check (status <> 'completed'
         or num_nonnulls(manifest_object_key, bundle_object_key, receipt_object_key, item_count, omitted_item_count) = 5)
);
comment on table platform.org_exports is
  'Organisation exit export jobs with status, contents manifest and receipt (spec 2.6). Requested_at is the creation time.';
comment on column platform.org_exports.billing_status_at_request is
  'Snapshot of iam.organisations.billing_status. Exports are never withheld; this records which state applied.';
comment on column platform.org_exports.format_version is 'Version of the published export schema.';
comment on column platform.org_exports.clearance_snapshot_at is
  'When the requester''s clearances were resolved: at the request, in their own session. Markings omit what they could not see then.';
comment on column platform.org_exports.cleared_marking_ids is
  'The organisation''s markings the requester satisfied at clearance_snapshot_at; an artefact carrying any other is omitted and named.';
comment on column platform.org_exports.failure_category is 'A category only, never a source message.';
-- One export at a time per organisation.
create unique index org_exports_live on platform.org_exports (organisation_id) where status in ('requested', 'running');
create index org_exports_list on platform.org_exports (organisation_id, requested_at desc);
create index org_exports_requested_by on platform.org_exports (organisation_id, requested_by_membership_id);
create index org_exports_running on platform.org_exports (started_at) where status = 'running';
select platform.add_updated_at_trigger('platform.org_exports');
select platform.enable_tenant_rls('platform.org_exports');
create trigger org_exports_frozen before update on platform.org_exports
  for each row execute function platform.freeze_columns(
    'id', 'organisation_id', 'requested_by_membership_id', 'billing_status_at_request', 'format_version',
    'clearance_snapshot_at', 'cleared_marking_ids', 'requested_at');

grant select, insert, update on platform.org_exports to silo_app;
grant select on platform.org_exports to silo_report;

create table platform.org_export_items (
  id                 uuid primary key,
  organisation_id    uuid not null references iam.organisations (id),
  export_id          uuid not null,
  family             text not null check (family in (
                       'connector_manifests', 'ontology', 'resolution', 'applications', 'views', 'crons',
                       'scenarios', 'receipts', 'audit', 'siloes_transitions', 'siloes_imports', 'siloes_index')),
  artefact_name      text not null check (length(btrim(artefact_name)) > 0),
  format             text not null check (format in ('yaml', 'json', 'jsonl', 'csv', 'parquet', 'original')),
  status             text not null check (status in ('included', 'omitted_marking')),
  omitted_marking_id uuid,
  bundle_path        text,
  object_key         text,
  sha256             bytea check (sha256 is null or octet_length(sha256) = 32),
  bytes              bigint check (bytes >= 0),
  row_count          bigint check (row_count >= 0),
  created_at         timestamptz not null default now(),
  unique (organisation_id, id),
  constraint org_export_items_artefact_key unique (organisation_id, export_id, family, artefact_name),
  constraint org_export_items_export_fkey
    foreign key (organisation_id, export_id) references platform.org_exports (organisation_id, id),
  constraint org_export_items_omitted_marking_fkey
    foreign key (organisation_id, omitted_marking_id) references gov.markings (organisation_id, id),
  check ((status = 'omitted_marking') = (omitted_marking_id is not null)),
  -- Omitted items carry no file. Included items carry all five completion fields once
  -- the job completes the item (enforced at export completion).
  check (num_nonnulls(bundle_path, object_key, sha256, bytes, row_count)
           in (0, case when status = 'included' then 5 else 0 end))
);
comment on table platform.org_export_items is
  'One row per artefact file in an organisation export, with named omissions (spec 2.6). Names, hashes and counts only.';
comment on column platform.org_export_items.artefact_name is
  'Snapshot for the reader, not a reference. An omitted name is shown only to the requester.';
comment on column platform.org_export_items.omitted_marking_id is 'The marking that caused the omission.';
create index org_export_items_omitted_marking on platform.org_export_items (organisation_id, omitted_marking_id)
  where omitted_marking_id is not null;
select platform.enable_tenant_rls('platform.org_export_items');

-- Insert-only, except the job's own completion fields while the export is running.
create function platform.org_export_items_guard() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
declare
  v_completion constant text[] := array['bundle_path', 'object_key', 'sha256', 'bytes', 'row_count'];
begin
  if (to_jsonb(new) - v_completion) is distinct from (to_jsonb(old) - v_completion) then
    raise exception 'platform.org_export_items: only the completion fields may change'
      using errcode = 'insufficient_privilege';
  end if;
  if not exists (select 1 from platform.org_exports e
                 where e.organisation_id = new.organisation_id and e.id = new.export_id
                   and e.status = 'running') then
    raise exception 'platform.org_export_items: export % is not running', new.export_id
      using errcode = 'insufficient_privilege';
  end if;
  return new;
end
$$;
create trigger org_export_items_guard before update on platform.org_export_items
  for each row execute function platform.org_export_items_guard();

-- Terminal statuses are final, and an export completes only with every included
-- item complete.
create function platform.org_exports_check_status() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
begin
  if old.status in ('completed', 'failed', 'cancelled') then
    raise exception 'organisation export % is %; its status is final', old.id, old.status
      using errcode = 'check_violation';
  end if;
  if new.status = 'completed' and exists (
       select 1 from platform.org_export_items i
       where i.organisation_id = new.organisation_id and i.export_id = new.id
         and i.status = 'included' and i.sha256 is null) then
    raise exception 'organisation export % has included items not yet complete', new.id
      using errcode = 'check_violation';
  end if;
  return new;
end
$$;
create trigger org_exports_check_status before update of status on platform.org_exports
  for each row when (old.status is distinct from new.status)
  execute function platform.org_exports_check_status();

grant select, insert, update on platform.org_export_items to silo_app;
grant select on platform.org_export_items to silo_report;

-- The export worker's sweep across organisations (spec 2.6): exports waiting to run, and
-- exports left running by a process that stopped, which are failed so they can be asked again.
create function platform.org_exports_due(p_limit integer, p_stale interval)
returns table (organisation_id uuid, id uuid, stale boolean)
language sql stable security definer
set search_path = pg_catalog
as $$
  select e.organisation_id, e.id, e.status = 'running' from platform.org_exports e
  where e.status = 'requested' or (e.status = 'running' and e.started_at < now() - p_stale)
  order by e.requested_at, e.id limit p_limit
$$;
grant execute on function platform.org_exports_due(integer, interval) to silo_app;

