-- ============================================================================
-- Domain: connect
-- ============================================================================

-- Connect: connectors and manifests (the catalogue), connections, sealed credentials,
-- OAuth, probing and conformance, self-healing, change streams, webhooks, CDC,
-- agent discovery, industrial endpoints, writable points, and Silo Agents.
-- Design: docs/siloDatabaseDesign.doc.md, schema connect (spec chapters 10, 14 to 20),
-- with review decisions D2 (AAD without the key version), D10 (system organisation), D16 (composite session key), R2 (subquery
-- RLS form on the catalogue policies) and R6 (session_id index).
--
-- Keys to automation, siloes, action and ontology are in connect_fks.sql.

-- ===========================================================================
-- Catalogue reference rule. connect.connectors and connect.connector_manifests
-- hold global rows (organisation_id null) and private rows. A reference into them
-- from a tenant table is a plain key on id, guarded by this constraint trigger:
-- the target must be global or belong to the row's organisation, and a manifest
-- must belong to the connector named in the same row.
--
-- Trigger arguments, one per referencing column: '<column>:<mode>[:<connector column>]'.
--   connector        target connector is global or the row's organisation's
--   manifest         same, for a manifest; with a third part, the manifest must
--                    belong to the connector held in that column
--   connector_owner  target connector's organisation equals the row's (both may be
--                    null): a manifest has its connector's organisation
-- A global row (organisation_id null) is written only by silo_migrate and is not
-- checked in modes connector and manifest.
--
-- Not security definer: the caller reads exactly the rows the rule permits (global
-- rows and its own), so a row of another organisation is not found and is refused.
-- ===========================================================================

create function connect.assert_catalogue_visible() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
declare
  v_row        jsonb := to_jsonb(new);
  v_org        uuid := (v_row ->> 'organisation_id')::uuid;
  v_arg        text;
  v_part       text[];
  v_id         uuid;
  v_target_org uuid;
  v_target_con uuid;
  v_found      boolean;
begin
  foreach v_arg in array tg_argv loop
    v_part := string_to_array(v_arg, ':');
    v_id := (v_row ->> v_part[1])::uuid;
    continue when v_id is null;
    continue when v_org is null and v_part[2] in ('connector', 'manifest');

    if v_part[2] in ('connector', 'connector_owner') then
      select c.organisation_id into v_target_org from connect.connectors c where c.id = v_id;
      v_found := found;
    else
      select m.organisation_id, m.connector_id into v_target_org, v_target_con
      from connect.connector_manifests m where m.id = v_id;
      v_found := found;
    end if;

    if not v_found
       or (v_part[2] = 'connector_owner' and v_target_org is distinct from v_org)
       or (v_part[2] <> 'connector_owner' and v_target_org is not null and v_target_org is distinct from v_org) then
      raise exception '%.%.%: % is not a catalogue row visible to this organisation',
        tg_table_schema, tg_table_name, v_part[1], v_id
        using errcode = 'foreign_key_violation';
    end if;

    if cardinality(v_part) >= 3 and v_target_con is distinct from (v_row ->> v_part[3])::uuid then
      raise exception '%.%.%: manifest % does not belong to connector %',
        tg_table_schema, tg_table_name, v_part[1], v_id, v_row ->> v_part[3]
        using errcode = 'foreign_key_violation';
    end if;
  end loop;
  return null;
end
$$;

-- ===========================================================================
-- connect.connectors: the catalogue entry for one kind of source system (ch 14, 16)
-- ===========================================================================

create table connect.connectors (
  id                              uuid primary key,
  organisation_id                 uuid references iam.organisations (id),
  kind                            text not null check (kind in ('prebuilt', 'private')),
  slug                            text not null check (slug ~ '^[a-z0-9][a-z0-9-]*$'),
  name                            text not null check (length(btrim(name)) > 0),
  provider                        text not null check (length(btrim(provider)) > 0),
  description                     text,
  trust_tier                      text not null check (trust_tier in ('private', 'certified')),
  -- silo: generated for an Import Silo's definition, so the Silo answers as a source (66.5).
  source_route                    text not null check (source_route in ('catalogue', 'ai', 'visual', 'silo')),
  status                          text not null default 'draft'
                                    check (status in ('draft', 'active', 'deprecated', 'withdrawn')),
  author_organisation_id          uuid references iam.organisations (id),
  derived_from_connector_id       uuid constraint connectors_derived_from_fkey references connect.connectors (id),
  derivation                      text check (derivation in ('fork')),
  created_by_membership_id        uuid,
  created_by_service_principal_id uuid,
  created_at                      timestamptz not null default now(),
  updated_at                      timestamptz not null default now(),
  version                         integer not null default 1,
  unique (organisation_id, id),
  foreign key (organisation_id, created_by_membership_id) references iam.memberships (organisation_id, id),
  foreign key (organisation_id, created_by_service_principal_id) references iam.service_principals (organisation_id, id),
  check (kind <> 'private'
         or (organisation_id is not null and trust_tier = 'private' and author_organisation_id = organisation_id)),
  check (kind <> 'prebuilt' or (organisation_id is null and trust_tier = 'certified' and author_organisation_id is null)),
  check ((derived_from_connector_id is null) = (derivation is null)),
  check (derived_from_connector_id is distinct from id),
  check (case when organisation_id is null
              then num_nonnulls(created_by_membership_id, created_by_service_principal_id) = 0
              else num_nonnulls(created_by_membership_id, created_by_service_principal_id) = 1 end)
);
comment on table connect.connectors is
  'Catalogue entry for one kind of source system: global (organisation_id null) or private (spec 14, 16).';
comment on column connect.connectors.organisation_id is
  'Null for a global catalogue row (a Silo prebuilt connector), written only by silo_migrate.';
comment on column connect.connectors.author_organisation_id is
  'The organisation that wrote a private connector (its own). Null for Silo prebuilt rows.';
comment on constraint connectors_derived_from_fkey on connect.connectors is
  'lint:cross-tenant catalogue reference rule (connect): guarded by connect.assert_catalogue_visible()';

create unique index connectors_global_slug on connect.connectors (slug) where organisation_id is null;
create unique index connectors_private_slug on connect.connectors (organisation_id, slug)
  where organisation_id is not null;
create index connectors_name_search on connect.connectors using gin (name public.gin_trgm_ops);
create index connectors_catalogue_browse on connect.connectors (trust_tier, kind)
  where organisation_id is null and status = 'active';
create index connectors_private_list on connect.connectors (organisation_id, created_at desc)
  where organisation_id is not null;
create index connectors_author on connect.connectors (author_organisation_id) where author_organisation_id is not null;
create index connectors_derived_from on connect.connectors (derived_from_connector_id)
  where derived_from_connector_id is not null;
create index connectors_created_by_membership on connect.connectors (organisation_id, created_by_membership_id)
  where created_by_membership_id is not null;
create index connectors_created_by_principal on connect.connectors (organisation_id, created_by_service_principal_id)
  where created_by_service_principal_id is not null;

select platform.add_updated_at_trigger('connect.connectors');
create trigger connectors_frozen before update on connect.connectors
  for each row execute function platform.freeze_columns('id', 'organisation_id', 'kind', 'slug', 'trust_tier');

-- The trust tier is the kind's (a private connector is private, a Silo prebuilt one certified) and never changes.

create constraint trigger connectors_catalogue_visible
  after insert or update of derived_from_connector_id on connect.connectors
  for each row execute function connect.assert_catalogue_visible('derived_from_connector_id:connector');

-- Mixed global and tenant table: read own and global rows; write own private rows only.
alter table connect.connectors enable row level security;
alter table connect.connectors force row level security;
create policy catalogue_read on connect.connectors for select
  using (organisation_id is null or organisation_id = (select current_setting('app.org_id')::uuid));
create policy tenant_insert on connect.connectors for insert
  with check (organisation_id = (select current_setting('app.org_id')::uuid)
              and kind = 'private' and trust_tier = 'private');
create policy tenant_update on connect.connectors for update
  using (organisation_id = (select current_setting('app.org_id')::uuid))
  with check (organisation_id = (select current_setting('app.org_id')::uuid)
              and kind = 'private' and trust_tier = 'private');
create policy tenant_delete on connect.connectors for delete
  using (organisation_id = (select current_setting('app.org_id')::uuid));

grant select, insert, update on connect.connectors to silo_app;
grant select on connect.connectors to silo_report;

-- ===========================================================================
-- connect.connector_manifests: immutable, versioned manifest documents (ch 14.8)
-- ===========================================================================

create table connect.connector_manifests (
  id                              uuid primary key,
  organisation_id                 uuid references iam.organisations (id),
  connector_id                    uuid not null constraint connector_manifests_connector_fkey
                                    references connect.connectors (id),
  version                         text not null
                                    check (version ~ '^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)(-[0-9A-Za-z-]+(\.[0-9A-Za-z-]+)*)?(\+[0-9A-Za-z-]+(\.[0-9A-Za-z-]+)*)?$'),
  document                        jsonb not null check (jsonb_typeof(document) = 'object'),
  document_hash                   bytea not null check (octet_length(document_hash) = 32),
  schema_version                  text not null check (length(btrim(schema_version)) > 0),
  source_route                    text not null check (source_route in ('catalogue', 'ai', 'visual', 'silo')),
  parent_version_id               uuid,
  first_used_at                   timestamptz,
  created_by_membership_id        uuid,
  created_by_service_principal_id uuid,
  created_at                      timestamptz not null default now(),
  superseded_at                   timestamptz,
  unique (connector_id, version),
  unique (connector_id, id),
  unique (organisation_id, id),
  constraint connector_manifests_parent_fkey
    foreign key (connector_id, parent_version_id) references connect.connector_manifests (connector_id, id),
  foreign key (organisation_id, created_by_membership_id) references iam.memberships (organisation_id, id),
  foreign key (organisation_id, created_by_service_principal_id) references iam.service_principals (organisation_id, id),
  check (parent_version_id is distinct from id),
  -- A private version names at most one creator: none for a self-heal repair the platform
  -- made (spec 17.3), which its heal_proposals row names.
  constraint connector_manifests_creator
    check (case when organisation_id is null
                then num_nonnulls(created_by_membership_id, created_by_service_principal_id) = 0
                else num_nonnulls(created_by_membership_id, created_by_service_principal_id) <= 1 end)
);
comment on table connect.connector_manifests is
  'One immutable, versioned manifest of a connector; no secrets. Global or private like its connector (spec 14.8).';
comment on column connect.connector_manifests.document_hash is 'SHA-256 of the canonical document.';
comment on column connect.connector_manifests.first_used_at is
  'Set on first query or write. From then on only superseded_at may change.';
comment on constraint connector_manifests_connector_fkey on connect.connector_manifests is
  'lint:cross-tenant catalogue reference rule (connect): guarded by connect.assert_catalogue_visible()';
comment on constraint connector_manifests_parent_fkey on connect.connector_manifests is
  'lint:cross-tenant catalogue reference rule (connect): guarded by connect.assert_catalogue_visible()';

create unique index connector_manifests_current on connect.connector_manifests (connector_id)
  where superseded_at is null;
create index connector_manifests_history on connect.connector_manifests (organisation_id, connector_id, created_at desc)
  where organisation_id is not null;
create index connector_manifests_parent on connect.connector_manifests (connector_id, parent_version_id)
  where parent_version_id is not null;
create index connector_manifests_created_by_membership
  on connect.connector_manifests (organisation_id, created_by_membership_id)
  where created_by_membership_id is not null;
create index connector_manifests_created_by_principal
  on connect.connector_manifests (organisation_id, created_by_service_principal_id)
  where created_by_service_principal_id is not null;

-- Before first use: first_used_at, superseded_at and a draft document edit (document,
-- its hash, the schema version it validated against). After first use: superseded_at
-- only. Everything else never changes.
create function connect.connector_manifests_immutable() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
declare
  v_mutable text[];
begin
  if old.first_used_at is not null then
    v_mutable := array['superseded_at'];
  else
    v_mutable := array['first_used_at', 'superseded_at', 'document', 'document_hash', 'schema_version'];
  end if;
  if (to_jsonb(new) - v_mutable) <> (to_jsonb(old) - v_mutable) then
    raise exception 'connect.connector_manifests row % is immutable%', old.id,
      case when old.first_used_at is not null then ' after first use, except superseded_at' else '' end
      using errcode = 'insufficient_privilege';
  end if;
  if new.document is distinct from old.document and new.document_hash = old.document_hash then
    raise exception 'a document edit must carry its new document_hash' using errcode = 'check_violation';
  end if;
  return new;
end
$$;
create trigger connector_manifests_immutable before update on connect.connector_manifests
  for each row execute function connect.connector_manifests_immutable();

create constraint trigger connector_manifests_catalogue_visible
  after insert or update of organisation_id, connector_id on connect.connector_manifests
  for each row execute function connect.assert_catalogue_visible('connector_id:connector_owner');

alter table connect.connector_manifests enable row level security;
alter table connect.connector_manifests force row level security;
create policy catalogue_read on connect.connector_manifests for select
  using (organisation_id is null or organisation_id = (select current_setting('app.org_id')::uuid));
create policy tenant_insert on connect.connector_manifests for insert
  with check (organisation_id = (select current_setting('app.org_id')::uuid));
create policy tenant_update on connect.connector_manifests for update
  using (organisation_id = (select current_setting('app.org_id')::uuid))
  with check (organisation_id = (select current_setting('app.org_id')::uuid));
create policy tenant_delete on connect.connector_manifests for delete
  using (organisation_id = (select current_setting('app.org_id')::uuid));

grant select, insert, update on connect.connector_manifests to silo_app;
grant select on connect.connector_manifests to silo_report;

-- ===========================================================================
-- connect.agent_pools: high availability pools of Silo Agents (ch 10.2, 10.3)
-- ===========================================================================

create table connect.agent_pools (
  id              uuid primary key,
  organisation_id uuid not null references iam.organisations (id),
  name            text not null check (length(btrim(name)) > 0),
  environment     text not null default 'production' check (environment in ('production', 'non_production')),
  update_policy   text not null default 'automatic' check (update_policy in ('automatic', 'pinned', 'approval')),
  pinned_version  text check (pinned_version is null or pinned_version ~ '^[0-9]+\.[0-9]+\.[0-9]+([-+][0-9A-Za-z.+-]+)?$'),
  approved_version text check (approved_version is null or approved_version ~ '^[0-9]+\.[0-9]+\.[0-9]+([-+][0-9A-Za-z.+-]+)?$'),
  approved_by     uuid,
  approved_at     timestamptz,
  status          text not null default 'active' check (status in ('active', 'retired')),
  created_by      uuid not null,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  retired_at      timestamptz,
  version         integer not null default 1,
  unique (organisation_id, id),
  foreign key (organisation_id, created_by) references iam.memberships (organisation_id, id),
  foreign key (organisation_id, approved_by) references iam.memberships (organisation_id, id),
  check (update_policy <> 'pinned' or pinned_version is not null),
  check ((approved_version is null) = (approved_at is null) and (approved_by is null) = (approved_at is null)),
  check ((status = 'retired') = (retired_at is not null))
);
comment on table connect.agent_pools is
  'High availability pool of Silo Agents that connections bind to (spec 10.2, 10.3).';
comment on column connect.agent_pools.update_policy is
  'Spec 10.7, 11.4: automatic follows the cell''s agent waves; pinned holds the pool at pinned_version; approval '
  'takes approved_version, which someone with agent.manage approves. A pin or an approval overrides the waves.';
comment on column connect.agent_pools.approved_version is
  'Under the approval policy, the release the pool may take: its agents update to it, one at a time.';

create index agent_pools_list on connect.agent_pools (organisation_id, created_at desc);
create unique index agent_pools_live_name on connect.agent_pools (organisation_id, name) where retired_at is null;
create index agent_pools_created_by on connect.agent_pools (organisation_id, created_by);
select platform.add_updated_at_trigger('connect.agent_pools');
select platform.enable_tenant_rls('connect.agent_pools');

grant select, insert, update on connect.agent_pools to silo_app;
grant select on connect.agent_pools to silo_report;

-- ===========================================================================
-- connect.agents: enrolled Silo Agents (ch 10.2 to 10.7). Heartbeat, load and
-- tunnel columns are flushed from redis-state, hence fillfactor 70.
-- ===========================================================================

create table connect.agents (
  id                         uuid primary key,
  organisation_id            uuid not null references iam.organisations (id),
  pool_id                    uuid not null,
  name                       text not null check (length(btrim(name)) > 0),
  service_principal_id       uuid not null,
  certificate_fingerprint    bytea not null unique check (octet_length(certificate_fingerprint) = 32),
  certificate_serial         text not null check (length(btrim(certificate_serial)) > 0),
  certificate_issued_at      timestamptz not null,
  certificate_expires_at     timestamptz not null,
  version                    text not null check (version ~ '^[0-9]+\.[0-9]+\.[0-9]+([-+][0-9A-Za-z.+-]+)?$'),
  row_version                integer not null default 1,
  version_state              text not null default 'current' check (version_state in ('current', 'outdated', 'refused')),
  version_since              timestamptz not null default now(),
  previous_version           text check (previous_version is null or previous_version ~ '^[0-9]+\.[0-9]+\.[0-9]+([-+][0-9A-Za-z.+-]+)?$'),
  version_outdated_at        timestamptz,
  updating_to                text check (updating_to is null or updating_to ~ '^[0-9]+\.[0-9]+\.[0-9]+([-+][0-9A-Za-z.+-]+)?$'),
  update_started_at          timestamptz,
  work_done                  bigint not null default 0 check (work_done >= 0),
  work_failed                bigint not null default 0 check (work_failed >= 0 and work_failed <= work_done),
  prior_work_done            bigint not null default 0 check (prior_work_done >= 0),
  prior_work_failed          bigint not null default 0 check (prior_work_failed >= 0 and prior_work_failed <= prior_work_done),
  platform                   text not null
                               check (platform in ('linux_x86_64', 'linux_arm64', 'windows_x86_64', 'container')),
  hostname                   text not null check (length(btrim(hostname)) > 0),
  status                     text not null default 'healthy'
                               check (status in ('healthy', 'unhealthy', 'offline', 'revoked')),
  last_heartbeat_at          timestamptz,
  active_calls               integer not null default 0 check (active_calls >= 0),
  cdc_readers                integer not null default 0 check (cdc_readers >= 0),
  tunnel_connected_at        timestamptz,
  discovery_disabled_locally boolean not null default false,
  sealing_key                bytea check (sealing_key is null or octet_length(sealing_key) = 32),
  enrolled_by                uuid not null,
  enrolled_at                timestamptz not null default now(),
  revoked_at                 timestamptz,
  revoked_by                 uuid,
  created_at                 timestamptz not null default now(),
  updated_at                 timestamptz not null default now(),
  unique (organisation_id, id),
  unique (organisation_id, service_principal_id),
  foreign key (organisation_id, pool_id) references connect.agent_pools (organisation_id, id),
  foreign key (organisation_id, service_principal_id) references iam.service_principals (organisation_id, id),
  foreign key (organisation_id, enrolled_by) references iam.memberships (organisation_id, id),
  foreign key (organisation_id, revoked_by) references iam.memberships (organisation_id, id),
  check (status <> 'revoked' or revoked_at is not null),
  check (revoked_by is null or revoked_at is not null),
  check (certificate_expires_at > certificate_issued_at),
  check ((updating_to is null) = (update_started_at is null)),
  check ((version_state = 'current') = (version_outdated_at is null))
) with (fillfactor = 70);
comment on table connect.agents is
  'One enrolled Silo Agent: identity, certificate, version, host and health (spec 10.2 to 10.7).';
comment on column connect.agents.certificate_fingerprint is
  'SHA-256 of the current client certificate, copied from iam.service_principals for the pre-organisation '
  'lookup; enrolment and renewal update both in one transaction.';
comment on column connect.agents.version is
  'Agent release (semver), as the agent reports it. The optimistic lock is row_version.';
comment on column connect.agents.sealing_key is
  'The X25519 public key the agent made, for the logins of cell-custody connections sealed to it per call (HPKE, '
  'spec 10.7). Replaced at each certificate renewal; the private key never leaves the host. Null: it takes none.';
comment on column connect.agents.version_state is
  'Spec 10.7: outdated once older than the last three minor releases the cell has received; refused 90 days after. '
  'A refused agent is given no work, but may still update.';
comment on column connect.agents.version_since is 'When the agent began reporting its version: its update, or its enrolment.';
comment on column connect.agents.updating_to is
  'The release this agent was offered and is taking (spec 10.7: pool members update one at a time); cleared when it '
  'reports that version or refuses it.';
comment on column connect.agents.work_done is
  'Work given this agent since version_since, and work_failed the part the agent itself failed (internal errors, '
  'answers broken off): the error-rate gate of the agent waves (spec 11.4). prior_* hold the counts of the version before.';
comment on column connect.agents.last_heartbeat_at is
  'Flushed from redis-state at most every 60 seconds and on status change; the live value drives health.';

create index agents_pool_members on connect.agents (organisation_id, pool_id) where status <> 'revoked';
create index agents_heartbeat_sweep on connect.agents (organisation_id, last_heartbeat_at)
  where status in ('healthy', 'unhealthy');
create index agents_certificate_renewal on connect.agents (organisation_id, certificate_expires_at)
  where status <> 'revoked';
create index agents_outdated on connect.agents (organisation_id, version_state) where version_state <> 'current';
create index agents_enrolled_by on connect.agents (organisation_id, enrolled_by);
create index agents_revoked_by on connect.agents (organisation_id, revoked_by) where revoked_by is not null;
select platform.add_updated_at_trigger('connect.agents');
select platform.enable_tenant_rls('connect.agents');

grant select, insert, update on connect.agents to silo_app;
grant select on connect.agents to silo_report;

-- ===========================================================================
-- connect.agent_releases: the Silo Agent releases this cell has received through Fleet
-- (spec 10.7, 11.1, 11.4), each as fleet-control signed it. Silo's software, not tenant data.
-- ===========================================================================

create table connect.agent_releases (
  release_id       text primary key check (release_id ~ '^[A-Za-z0-9._+-]{1,128}$'),
  version          text not null unique check (version ~ '^[0-9]+\.[0-9]+\.[0-9]+([-+][0-9A-Za-z.+-]+)?$'),
  target           text not null check (target in ('commercial', 'sovereign')),
  channel          text not null check (channel in ('agent-stable', 'agent-sovereign')),
  channel_sequence integer not null check (channel_sequence >= 1),
  manifest         text not null check (length(manifest) between 2 and 524288),
  manifest_digest  text not null check (manifest_digest ~ '^sha256:[0-9a-f]{64}$'),
  signatures       jsonb not null check (jsonb_typeof(signatures) = 'array'),
  head             text not null check (length(head) between 2 and 4096),
  head_signatures  jsonb not null check (jsonb_typeof(head_signatures) = 'array'),
  binaries         jsonb not null check (jsonb_typeof(binaries) = 'array' and jsonb_array_length(binaries) between 1 and 4),
  installed_at     timestamptz not null default now(),
  unique (channel, channel_sequence)
);
comment on table connect.agent_releases is
  'Agent releases received from Fleet''s agent channel by the cell''s Fleet agent, checked again on arrival: the '
  'release manifest and the channel head exactly as signed (canonical JSON text, so the agent verifies the same bytes), '
  'and each platform''s binary, held in object storage by digest (spec 10.7, 11.1).';
comment on column connect.agent_releases.binaries is
  '[{platform, version, digest, bytes}], one per platform the release carries.';

create trigger agent_releases_frozen before update on connect.agent_releases
  for each row execute function platform.freeze_columns('release_id', 'version', 'manifest', 'signatures', 'head', 'head_signatures', 'binaries');

grant select, insert on connect.agent_releases to silo_app;
grant select on connect.agent_releases to silo_report;

-- ===========================================================================
-- connect.agent_rollouts: each agent release rolling through this cell's agents in waves
-- (spec 11.4): Silo's own organisations, then 5%, 25%, all, 24 hours apart, gated on
-- heartbeat and error rate. One runs at a time; a newer release supersedes it.
-- ===========================================================================

create table connect.agent_rollouts (
  id              uuid primary key,
  release_id      text not null unique references connect.agent_releases (release_id),
  version         text not null,
  status          text not null default 'running' check (status in ('running', 'halted', 'completed', 'superseded')),
  wave            smallint not null default 0 check (wave between 0 and 3),
  wave_started_at timestamptz not null default now(),
  started_at      timestamptz not null default now(),
  ended_at        timestamptz,
  halt_reason     text check (halt_reason in ('heartbeat', 'error_rate', 'refused')),
  halt_detail     jsonb check (halt_detail is null or jsonb_typeof(halt_detail) = 'object'),
  check ((status = 'running') = (ended_at is null)),
  check ((status = 'halted') = (halt_reason is not null))
);
comment on table connect.agent_rollouts is
  'An agent release rolling through the cell''s agents in automatic pools (spec 11.4). Wave 0 is Silo''s own '
  'organisations (CONNECT_AGENT_FIRST_ORGANISATIONS), 1 a stable 5% of agents, 2 25%, 3 all; each soaks 24 hours. '
  'A wave with no agents passes at once. A gate failure halts it, and the agents it updated go back to their version before.';
comment on column connect.agent_rollouts.halt_detail is 'Counts only: agents updated, stalled, silent, failing, refusing.';

create unique index agent_rollouts_one_running on connect.agent_rollouts ((true)) where status = 'running';

grant select, insert, update on connect.agent_rollouts to silo_app;
grant select on connect.agent_rollouts to silo_report;

-- ===========================================================================
-- connect.agent_enrolment_tokens: single-use 24 hour enrolment tokens (ch 10.2)
-- ===========================================================================

create table connect.agent_enrolment_tokens (
  id                   uuid primary key,
  organisation_id      uuid not null references iam.organisations (id),
  pool_id              uuid not null,
  token_hash           bytea not null unique check (octet_length(token_hash) = 32),
  created_by           uuid not null,
  created_at           timestamptz not null default now(),
  expires_at           timestamptz not null,
  consumed_at          timestamptz,
  consumed_by_agent_id uuid,
  revoked_at           timestamptz,
  unique (organisation_id, id),
  foreign key (organisation_id, pool_id) references connect.agent_pools (organisation_id, id),
  foreign key (organisation_id, created_by) references iam.memberships (organisation_id, id),
  -- Deferred: the token is consumed (connect.resolve_enrolment_token) before the
  -- agent row exists; both happen in one transaction.
  constraint agent_enrolment_tokens_consumed_by_fkey
    foreign key (organisation_id, consumed_by_agent_id) references connect.agents (organisation_id, id)
    deferrable initially deferred,
  check (expires_at > created_at),
  check ((consumed_at is null) = (consumed_by_agent_id is null))
);
comment on table connect.agent_enrolment_tokens is
  'Single-use, 24 hour token that lets one new agent obtain its client certificate (spec 10.2).';
comment on column connect.agent_enrolment_tokens.token_hash is
  'SHA-256 of the token; the token is shown once and never stored.';

create index agent_enrolment_tokens_pool on connect.agent_enrolment_tokens (organisation_id, pool_id, created_at desc);
create index agent_enrolment_tokens_created_by on connect.agent_enrolment_tokens (organisation_id, created_by);
create index agent_enrolment_tokens_consumed_by on connect.agent_enrolment_tokens (organisation_id, consumed_by_agent_id)
  where consumed_by_agent_id is not null;
select platform.enable_tenant_rls('connect.agent_enrolment_tokens');

-- Consumption happens only in connect.resolve_enrolment_token, so silo_app can never
-- clear consumed_at and reuse a token.
grant select, insert on connect.agent_enrolment_tokens to silo_app;
grant update (revoked_at) on connect.agent_enrolment_tokens to silo_app;
grant select on connect.agent_enrolment_tokens to silo_report;

-- ===========================================================================
-- connect.connections: a configured instance of a connector (ch 14.7, 14.8)
-- ===========================================================================

create table connect.connections (
  id                             uuid primary key,
  organisation_id                uuid not null references iam.organisations (id),
  connector_id                   uuid not null constraint connections_connector_fkey references connect.connectors (id),
  manifest_id                    uuid not null,
  name                           text not null check (length(btrim(name)) > 0),
  provider                       text not null check (length(btrim(provider)) > 0),
  trust_tier                     text not null check (trust_tier in ('private', 'certified')),
  owning_scope_id                uuid not null,
  owning_membership_id           uuid not null,
  policy_authority               text not null default 'owner_set'
                                   check (policy_authority in ('owner_set', 'delegated', 'locked')),
  policy_authority_granted_to    uuid,
  policy_authority_set_by        uuid,
  policy_authority_set_at        timestamptz,
  status                         text not null default 'draft'
                                   check (status in ('draft', 'probing', 'verified', 'active', 'halted', 'revoked')),
  writes_enabled                 boolean not null default false,
  max_physical_writes_per_minute integer check (max_physical_writes_per_minute is null or max_physical_writes_per_minute > 0),
  physical_webhook               boolean not null default false,
  agent_pool_id                  uuid,
  credential_custody             text not null default 'cell' check (credential_custody in ('cell', 'agent')),
  created_by                     uuid,
  created_by_service_principal_id uuid,
  created_at                     timestamptz not null default now(),
  last_healthy_at                timestamptz,
  halted_reason                  text,
  halted_at                      timestamptz,
  revoked_at                     timestamptz,
  parameters                     jsonb not null default '{}'
                                   check (jsonb_typeof(parameters) = 'object' and octet_length(parameters::text) <= 16384),
  updated_at                     timestamptz not null default now(),
  version                        integer not null default 1,
  unique (organisation_id, id),
  unique (organisation_id, id, connector_id),
  constraint connections_manifest_fkey
    foreign key (connector_id, manifest_id) references connect.connector_manifests (connector_id, id),
  foreign key (organisation_id, owning_scope_id) references iam.scopes (organisation_id, id),
  foreign key (organisation_id, owning_membership_id) references iam.memberships (organisation_id, id),
  foreign key (organisation_id, policy_authority_granted_to) references iam.memberships (organisation_id, id),
  foreign key (organisation_id, policy_authority_set_by) references iam.memberships (organisation_id, id),
  foreign key (organisation_id, created_by) references iam.memberships (organisation_id, id),
  constraint connections_created_by_service_principal_fkey
    foreign key (organisation_id, created_by_service_principal_id) references iam.service_principals (organisation_id, id),
  foreign key (organisation_id, agent_pool_id) references connect.agent_pools (organisation_id, id),
  -- A person, or an AI FDE's Integration principal drafting a connector (51.4), whose owner owns the connection.
  check (num_nonnulls(created_by, created_by_service_principal_id) = 1),
  check (credential_custody = 'cell' or agent_pool_id is not null),
  check ((policy_authority = 'delegated') = (policy_authority_granted_to is not null)),
  check (policy_authority = 'owner_set'
         or (policy_authority_set_by is not null and policy_authority_set_at is not null)),
  check (not writes_enabled or status in ('active', 'halted')),
  check (status <> 'halted' or (halted_reason is not null and halted_at is not null)),
  check (status <> 'revoked' or revoked_at is not null)
);
comment on table connect.connections is
  'A configured instance of a connector for one organisation; default deny until granted (spec 14.7, 14.8).';
comment on column connect.connections.credential_custody is
  'Spec 10.7, for a connection through the Silo Agent: cell (the default) seals its login here, and the credential '
  'service passes it for one call, sealed to the agent running it; agent keeps it on the agent''s host, the cell holds '
  'none, and each use is recorded held_by_agent. A connection reached from the cell is always cell.';
comment on column connect.connections.provider is 'Copied from connect.connectors.provider at creation; read-only.';
comment on column connect.connections.trust_tier is
  'Snapshot of connect.connectors.trust_tier, which never changes (private, or certified for a Silo prebuilt connector).';
comment on column connect.connections.writes_enabled is
  'True only after the write-verify-undo conformance class passes (17.1).';
comment on column connect.connections.max_physical_writes_per_minute is
  'Physical write rate limit, enforced by actions and by the agent (spec 47.5, 47.7).';
comment on column connect.connections.physical_webhook is 'Webhook actions on this connection are physical (spec 47.7).';
comment on column connect.connections.parameters is
  'The manifest''s declared connection parameters (a tenant subdomain, a region): public, never secret. Secrets '
  'are sealed in connect.connection_credentials.';
comment on constraint connections_connector_fkey on connect.connections is
  'lint:cross-tenant catalogue reference rule (connect): guarded by connect.assert_catalogue_visible()';
comment on constraint connections_manifest_fkey on connect.connections is
  'lint:cross-tenant catalogue reference rule (connect): guarded by connect.assert_catalogue_visible()';

create index connections_list on connect.connections (organisation_id, created_at desc);
create index connections_owning_scope on connect.connections (organisation_id, owning_scope_id) where revoked_at is null;
create index connections_owning_membership on connect.connections (organisation_id, owning_membership_id)
  where revoked_at is null;
create index connections_connector on connect.connections (organisation_id, connector_id, manifest_id);
create index connections_manifest on connect.connections (organisation_id, manifest_id);
create index connections_agent_pool on connect.connections (organisation_id, agent_pool_id)
  where agent_pool_id is not null;
create index connections_policy_authority_granted_to on connect.connections (organisation_id, policy_authority_granted_to)
  where policy_authority_granted_to is not null;
create index connections_health_sweep on connect.connections (organisation_id, last_healthy_at)
  where status = 'active';
create index connections_created_by on connect.connections (organisation_id, created_by);
create index connections_created_by_service_principal on connect.connections (organisation_id, created_by_service_principal_id)
  where created_by_service_principal_id is not null;
create index connections_policy_authority_set_by on connect.connections (organisation_id, policy_authority_set_by)
  where policy_authority_set_by is not null;

select platform.add_updated_at_trigger('connect.connections');
select platform.enable_tenant_rls('connect.connections');
create trigger connections_frozen before update on connect.connections
  for each row execute function platform.freeze_columns('provider', 'credential_custody');

-- draft to probing; probing to verified or draft; verified to active; active to
-- halted; halted to active; any state to revoked; revoked is terminal.
create function connect.connections_status_transition() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
begin
  if old.status <> 'revoked'
     and (new.status = 'revoked'
          or (old.status = 'draft' and new.status = 'probing')
          or (old.status = 'probing' and new.status in ('verified', 'draft'))
          or (old.status = 'verified' and new.status = 'active')
          or (old.status = 'active' and new.status = 'halted')
          or (old.status = 'halted' and new.status = 'active')) then
    return new;
  end if;
  raise exception 'connection status cannot move from % to %', old.status, new.status
    using errcode = 'check_violation';
end
$$;
create trigger connections_status_transition before update of status on connect.connections
  for each row when (old.status is distinct from new.status)
  execute function connect.connections_status_transition();

create constraint trigger connections_catalogue_visible
  after insert or update of connector_id, manifest_id on connect.connections
  for each row execute function connect.assert_catalogue_visible(
    'connector_id:connector', 'manifest_id:manifest:connector_id');

grant select, insert, update on connect.connections to silo_app;
grant select on connect.connections to silo_report;

-- ===========================================================================
-- connect.connection_credentials: sealed secrets of a connection or an OAuth client
-- (ch 15.2, 15.5, 61). The chapter 15 and chapter 61 definitions, merged.
-- ===========================================================================

create table connect.connection_credentials (
  id                    uuid primary key,
  organisation_id       uuid not null references iam.organisations (id),
  connection_id         uuid,
  purpose               text not null default 'connection_auth'
                          check (purpose in ('connection_auth', 'oauth_client_secret', 'oauth_registration_token',
                                             'action_event_secret', 'outbound_webhook_secret', 'opcua_application_key')),
  field_name            text not null check (length(btrim(field_name)) > 0),
  custody               text not null default 'cell' check (custody in ('cell', 'agent')),
  ciphertext            bytea,
  nonce                 bytea check (nonce is null or octet_length(nonce) = 12),
  dek_wrapped           bytea,
  key_version_id        uuid references iam.kms_key_versions (id),
  last_four             text check (last_four is null or char_length(last_four) <= 4),
  auth_strategy         text not null check (length(btrim(auth_strategy)) > 0),
  granted_scopes        text[] not null default '{}',
  expires_at            timestamptz,
  refreshed_at          timestamptz,
  refresh_failure_count integer not null default 0 check (refresh_failure_count >= 0),
  last_used_at          timestamptz,
  revoked_at            timestamptz,
  created_at            timestamptz not null default now(),
  updated_at            timestamptz not null default now(),
  unique (organisation_id, id),
  foreign key (organisation_id, connection_id) references connect.connections (organisation_id, id),
  check (custody <> 'cell' or revoked_at is not null
         or (ciphertext is not null and nonce is not null and dek_wrapped is not null and key_version_id is not null)),
  check (custody <> 'agent'
         or (ciphertext is null and nonce is null and dek_wrapped is null and key_version_id is null)),
  -- Revocation crypto-shreds: the sealed columns are nulled in the statement that
  -- sets revoked_at; the row stays for audit.
  check (revoked_at is null or (ciphertext is null and nonce is null and dek_wrapped is null)),
  check (custody <> 'agent' or last_four is null),
  check ((connection_id is null) = (purpose in ('oauth_client_secret', 'oauth_registration_token', 'action_event_secret')))
);
comment on table connect.connection_credentials is
  'One sealed secret of a connection or OAuth client; ciphertext only, opened only by the credential service '
  '(spec 15.2, 15.5, 61).';
comment on column connect.connection_credentials.ciphertext is
  'AES-256-GCM ciphertext and tag. AAD (id, organisation_id, connection_id, field_name, purpose); the key version '
  'is bound to the wrapped DEK through the KMS encryption context, never the AAD (review D2). silo_credential only.';
comment on column connect.connection_credentials.dek_wrapped is
  'Per-credential 256-bit DEK wrapped by the KEK. Rotation re-wraps it and changes key_version_id only.';
comment on column connect.connection_credentials.custody is
  'cell: sealed here. agent: the secret stays in the customer''s key store and the cell holds none (10.7).';
comment on column connect.connection_credentials.last_four is
  'The only clear-text fragment, computed inside the credential service. Null when custody is agent.';

create unique index connection_credentials_live_field
  on connect.connection_credentials (organisation_id, connection_id, field_name)
  where revoked_at is null and connection_id is not null;
create index connection_credentials_refresh_sweep on connect.connection_credentials (organisation_id, expires_at)
  where revoked_at is null and expires_at is not null;
create index connection_credentials_key_version on connect.connection_credentials (organisation_id, key_version_id)
  where revoked_at is null and custody = 'cell';

select platform.add_updated_at_trigger('connect.connection_credentials');
select platform.enable_tenant_rls('connect.connection_credentials');
-- The AAD columns never change, or the ciphertext could not be opened.
create trigger connection_credentials_frozen before update on connect.connection_credentials
  for each row execute function platform.freeze_columns(
    'id', 'organisation_id', 'connection_id', 'purpose', 'field_name');

-- Single mediator, enforced in the database: only silo_credential reads the sealed
-- columns and writes the table. Every other service reads the safe view.
grant select, insert, update on connect.connection_credentials to silo_credential;
grant select (id, organisation_id, connection_id, purpose, field_name, custody, key_version_id, last_four,
              auth_strategy, granted_scopes, expires_at, refreshed_at, refresh_failure_count, last_used_at,
              revoked_at, created_at, updated_at)
  on connect.connection_credentials to silo_app, silo_report;

-- security_invoker: the caller's privileges and RLS apply, so the view shows only the
-- caller's organisation and never the sealed columns.
create view connect.connection_credentials_safe with (security_invoker = true) as
  select id, organisation_id, connection_id, purpose, field_name, custody, key_version_id, last_four,
         auth_strategy, granted_scopes, expires_at, refreshed_at, refresh_failure_count, last_used_at,
         revoked_at, created_at, updated_at
  from connect.connection_credentials;
comment on view connect.connection_credentials_safe is
  'connect.connection_credentials without ciphertext, nonce and dek_wrapped. What every service but the '
  'credential service reads.';
grant select on connect.connection_credentials_safe to silo_app, silo_report;

-- Revoking a connection revokes its credentials in the same transaction (spec 14.7),
-- crypto-shredding the sealed columns. Definer: silo_app may not write this table.
create function connect.connections_revoke_credentials() returns trigger
language plpgsql security definer
set search_path = pg_catalog
as $$
begin
  update connect.connection_credentials
     set revoked_at = now(), ciphertext = null, nonce = null, dek_wrapped = null
   where organisation_id = new.organisation_id and connection_id = new.id and revoked_at is null;
  return null;
end
$$;
create trigger connections_revoke_credentials after update of status on connect.connections
  for each row when (new.status = 'revoked' and old.status <> 'revoked')
  execute function connect.connections_revoke_credentials();

-- ===========================================================================
-- Connection grants: delegation and revocation (spec 14.8, 56.7, 56.8, 57.3), enforced
-- by the database like role assignments. A grant stays within the granter's subtree,
-- the granter must hold the connection there (owner, connection.grant, or a live grant
-- of at least that access), only a super admin grants to a role or from the organisation
-- level, and revocation is by the issuer, an admin over the scope it was issued under, or
-- a super admin. Also: suspension and removal revoke a membership's sessions in the same
-- transaction, though iam.sessions belongs to auth.
-- ===========================================================================
create function iam.revoke_membership_sessions(p_organisation_id uuid, p_membership_id uuid)
returns setof uuid
language sql
security definer
set search_path = pg_catalog
as $$
  update iam.sessions set revoked_at = now()
   where organisation_id = p_organisation_id and active_membership_id = p_membership_id and revoked_at is null
     and p_organisation_id = nullif(current_setting('app.org_id', true), '')::uuid
  returning id
$$;
grant execute on function iam.revoke_membership_sessions(uuid, uuid) to silo_app;

create function iam.holds_connection(p_organisation_id uuid, p_membership_id uuid, p_connection_id uuid,
                                                p_target_scope_id uuid, p_access text)
returns boolean
language sql
stable
security definer
set search_path = pg_catalog, public
as $$
  select iam.is_super_admin(p_organisation_id, p_membership_id)
    or exists (
      select 1
      from connect.connections c
      join iam.scopes owning on owning.organisation_id = c.organisation_id and owning.id = c.owning_scope_id
      join iam.scopes target on target.organisation_id = c.organisation_id and target.id = p_target_scope_id
      where c.organisation_id = p_organisation_id and c.id = p_connection_id
        and target.path <@ owning.path
        and (c.owning_membership_id = p_membership_id
             or exists (
               select 1 from iam.roles_applying_at(p_organisation_id, p_membership_id, c.owning_scope_id) r
               join iam.role_permissions rp on rp.organisation_id = p_organisation_id and rp.role_id = r.role_id
               where rp.permission_id = 'connection.grant')))
    or exists (
      select 1
      from iam.connection_grants g
      left join iam.scopes gs on gs.organisation_id = g.organisation_id and gs.id = g.grantee_scope_id
      left join iam.scopes target on target.organisation_id = g.organisation_id and target.id = p_target_scope_id
      where g.organisation_id = p_organisation_id and g.connection_id = p_connection_id
        and g.revoked_at is null and g.silenced_at is null and (g.expires_at is null or g.expires_at > now())
        and (p_access = 'read' or g.access = 'write')
        and (g.grantee_membership_id = p_membership_id
             or g.grantee_role_id in (
               select ra.role_id from iam.role_assignments ra
               where ra.organisation_id = p_organisation_id and ra.membership_id = p_membership_id
                 and ra.revoked_at is null and ra.silenced_at is null and (ra.expires_at is null or ra.expires_at > now()))
             or (gs.id is not null and target.id is not null
                 and (target.id = gs.id or (g.include_descendants and target.path <@ gs.path)))))
$$;

create function iam.check_connection_grant(
  p_organisation_id uuid, p_granter uuid, p_connection_id uuid, p_grantee_membership_id uuid, p_grantee_scope_id uuid,
  p_grantee_role_id uuid, p_grantee_service_principal_id uuid, p_access text, p_granted_at_scope_id uuid)
returns text
language plpgsql
stable
security definer
set search_path = pg_catalog, public
as $$
declare
  v_acted ltree;
begin
  if not exists (select 1 from connect.connections c
                 where c.organisation_id = p_organisation_id and c.id = p_connection_id and c.status <> 'revoked') then
    return 'no such connection';
  end if;
  if iam.is_super_admin(p_organisation_id, p_granter) then
    return null;
  end if;
  if p_grantee_role_id is not null then
    return 'only a super admin grants a connection to a role';
  end if;
  if p_granted_at_scope_id is null then
    return 'only a super admin grants from the organisation level';
  end if;
  select s.path into v_acted from iam.scopes s where s.organisation_id = p_organisation_id and s.id = p_granted_at_scope_id;
  if not exists (
       select 1 from iam.roles_applying_at(p_organisation_id, p_granter, p_granted_at_scope_id) r
       join iam.role_permissions rp on rp.organisation_id = p_organisation_id and rp.role_id = r.role_id
       where rp.permission_id = 'connection.grant')
     and not exists (
       select 1 from connect.connections c
       join iam.scopes owning on owning.organisation_id = c.organisation_id and owning.id = c.owning_scope_id
       where c.organisation_id = p_organisation_id and c.id = p_connection_id
         and c.owning_membership_id = p_granter and v_acted <@ owning.path) then
    return 'the granter does not grant connections there';
  end if;
  if p_grantee_scope_id is not null then
    if not exists (select 1 from iam.scopes s where s.organisation_id = p_organisation_id and s.id = p_grantee_scope_id
                   and s.path <@ v_acted) then
      return 'the grantee is outside the granter''s subtree';
    end if;
  elsif p_grantee_membership_id is not null then
    if not exists (select 1 from iam.scope_memberships sm
                   join iam.scopes s on s.organisation_id = sm.organisation_id and s.id = sm.scope_id
                   where sm.organisation_id = p_organisation_id and sm.membership_id = p_grantee_membership_id
                     and sm.inactive_since is null and s.path <@ v_acted) then
      return 'the grantee is outside the granter''s subtree';
    end if;
  elsif not exists (select 1 from iam.service_principals sp
                    join iam.scopes s on s.organisation_id = sp.organisation_id and s.id = sp.scope_id
                    where sp.organisation_id = p_organisation_id and sp.id = p_grantee_service_principal_id
                      and s.path <@ v_acted) then
    return 'the grantee is outside the granter''s subtree';
  end if;
  if not iam.holds_connection(p_organisation_id, p_granter, p_connection_id,
                              coalesce(p_grantee_scope_id, p_granted_at_scope_id), p_access) then
    return 'the granter does not hold that connection there';
  end if;
  return null;
end
$$;

create function iam.connection_grants_delegation() returns trigger
language plpgsql
set search_path = pg_catalog, public
as $$
declare
  v_refusal text;
begin
  if current_user = 'silo_migrate' then
    return new;
  end if;
  v_refusal := iam.check_connection_grant(new.organisation_id, new.granted_by, new.connection_id, new.grantee_membership_id,
    new.grantee_scope_id, new.grantee_role_id, new.grantee_service_principal_id, new.access, new.granted_at_scope_id);
  if v_refusal is not null then
    raise exception '%', v_refusal using errcode = 'insufficient_privilege';
  end if;
  return new;
end
$$;
create trigger connection_grants_delegation before insert on iam.connection_grants
  for each row execute function iam.connection_grants_delegation();

create function iam.connection_grants_revocation() returns trigger
language plpgsql
set search_path = pg_catalog, public
as $$
begin
  if old.revoked_at is not null or new.revoked_at is null or current_user = 'silo_migrate' then
    return new;
  end if;
  if new.revoked_by is null then
    raise exception 'a revocation names who revoked it' using errcode = 'insufficient_privilege';
  end if;
  if new.revoked_by = old.granted_by or iam.is_super_admin(new.organisation_id, new.revoked_by) then
    return new;
  end if;
  if old.granted_at_scope_id is not null and exists (
    select 1 from iam.roles_applying_at(new.organisation_id, new.revoked_by, old.granted_at_scope_id) r
    join iam.role_permissions rp on rp.organisation_id = new.organisation_id and rp.role_id = r.role_id
    where rp.permission_id = 'connection.grant') then
    return new;
  end if;
  raise exception 'only the issuer, an admin over the scope it was issued under, or a super admin may revoke this'
    using errcode = 'insufficient_privilege';
end
$$;
create trigger connection_grants_revocation before update of revoked_at on iam.connection_grants
  for each row execute function iam.connection_grants_revocation();
grant execute on function iam.holds_connection(uuid, uuid, uuid, uuid, text),
  iam.check_connection_grant(uuid, uuid, uuid, uuid, uuid, uuid, uuid, text, uuid) to silo_app;

-- The system organisation (Silo's own: Silo-registered OAuth clients, spec 15.3), for a
-- service resolving a fallback client. Its identifier only.
create function iam.system_organisation_id() returns uuid
language sql stable security definer
set search_path = pg_catalog
as $$ select id from iam.organisations where is_system $$;
grant execute on function iam.system_organisation_id() to silo_app;

-- ===========================================================================
-- connect.oauth_pending_flows: OAuth authorisations in flight (ch 15.3, 15.5)
-- ===========================================================================

create table connect.oauth_pending_flows (
  state_hash           bytea not null unique check (octet_length(state_hash) = 32),
  organisation_id      uuid not null references iam.organisations (id),
  connection_id        uuid not null,
  connector_id         uuid not null,
  membership_id        uuid not null,
  session_id           uuid not null,
  pkce_verifier_sealed bytea,
  created_at           timestamptz not null default now(),
  expires_at           timestamptz not null,
  consumed_at          timestamptz,
  expired_at           timestamptz,
  -- The tenant key leads the primary key (build rules); state_hash alone is unique
  -- across the cell for the callback lookup.
  primary key (organisation_id, state_hash),
  -- Follows the connection when a repair forks its connector and repoints it.
  foreign key (organisation_id, connection_id, connector_id)
    references connect.connections (organisation_id, id, connector_id) on update cascade,
  foreign key (organisation_id, membership_id) references iam.memberships (organisation_id, id),
  foreign key (organisation_id, session_id) references iam.sessions (organisation_id, id),
  check (expires_at > created_at),
  check (consumed_at is null or expired_at is null)
);
comment on table connect.oauth_pending_flows is
  'Server-side record of an OAuth authorisation in flight, keyed by the hash of the state (spec 15.3, 15.5).';
comment on column connect.oauth_pending_flows.state_hash is 'SHA-256 of the state parameter, never the state itself.';
comment on column connect.oauth_pending_flows.pkce_verifier_sealed is
  'PKCE verifier sealed in the credential envelope, written by the credential service.';

create index oauth_pending_flows_expiry on connect.oauth_pending_flows (organisation_id, expires_at)
  where consumed_at is null and expired_at is null;
create index oauth_pending_flows_connection on connect.oauth_pending_flows (organisation_id, connection_id, connector_id);
create index oauth_pending_flows_membership on connect.oauth_pending_flows (organisation_id, membership_id);
create index oauth_pending_flows_session on connect.oauth_pending_flows (organisation_id, session_id);
select platform.enable_tenant_rls('connect.oauth_pending_flows');

-- Consumption happens only in connect.resolve_oauth_flow (single use); the service
-- may only mark a flow expired or abandoned.
grant select, insert on connect.oauth_pending_flows to silo_app;
grant update (expired_at) on connect.oauth_pending_flows to silo_app;
grant select (state_hash, organisation_id, connection_id, connector_id, membership_id, session_id,
              created_at, expires_at, consumed_at, expired_at)
  on connect.oauth_pending_flows to silo_report;

-- ===========================================================================
-- connect.oauth_clients: registered OAuth applications (ch 15.4, 15.5)
-- ===========================================================================

create table connect.oauth_clients (
  id                                      uuid primary key,
  organisation_id                         uuid not null references iam.organisations (id),
  connector_id                            uuid not null constraint oauth_clients_connector_fkey
                                            references connect.connectors (id),
  origin                                  text not null
                                            check (origin in ('silo_registered', 'dynamic_registration', 'bring_your_own')),
  client_id                               text not null check (length(btrim(client_id)) > 0),
  client_secret_credential_id             uuid,
  metadata_url                            text,
  registration_access_token_credential_id uuid,
  redirect_uri                            text not null check (length(btrim(redirect_uri)) > 0),
  created_by                              uuid,
  created_at                              timestamptz not null default now(),
  revoked_at                              timestamptz,
  updated_at                              timestamptz not null default now(),
  unique (organisation_id, id),
  constraint oauth_clients_client_secret_fkey
    foreign key (organisation_id, client_secret_credential_id)
    references connect.connection_credentials (organisation_id, id),
  constraint oauth_clients_registration_token_fkey
    foreign key (organisation_id, registration_access_token_credential_id)
    references connect.connection_credentials (organisation_id, id),
  foreign key (organisation_id, created_by) references iam.memberships (organisation_id, id),
  check (origin = 'silo_registered' or created_by is not null)
);
comment on table connect.oauth_clients is
  'OAuth client used to authenticate to a provider; Silo-registered clients belong to the system organisation '
  '(spec 15.4, 15.5).';
comment on column connect.oauth_clients.registration_access_token_credential_id is
  'RFC 7592 management token, sealed in connect.connection_credentials.';
comment on constraint oauth_clients_connector_fkey on connect.oauth_clients is
  'lint:cross-tenant catalogue reference rule (connect): guarded by connect.assert_catalogue_visible()';

create unique index oauth_clients_live_client on connect.oauth_clients (organisation_id, connector_id, client_id)
  where revoked_at is null;
create index oauth_clients_connector on connect.oauth_clients (organisation_id, connector_id) where revoked_at is null;
create index oauth_clients_client_secret on connect.oauth_clients (organisation_id, client_secret_credential_id)
  where client_secret_credential_id is not null;
create index oauth_clients_registration_token
  on connect.oauth_clients (organisation_id, registration_access_token_credential_id)
  where registration_access_token_credential_id is not null;
create index oauth_clients_created_by on connect.oauth_clients (organisation_id, created_by) where created_by is not null;
select platform.add_updated_at_trigger('connect.oauth_clients');
select platform.enable_tenant_rls('connect.oauth_clients');

create constraint trigger oauth_clients_catalogue_visible
  after insert or update of connector_id on connect.oauth_clients
  for each row execute function connect.assert_catalogue_visible('connector_id:connector');

grant select, insert, update on connect.oauth_clients to silo_app;
grant select on connect.oauth_clients to silo_report;

-- ===========================================================================
-- connect.probe_runs: stages of the sandbox probe and build pipeline (ch 17.1, 17.4)
-- ===========================================================================

create table connect.probe_runs (
  id              uuid primary key,
  organisation_id uuid not null references iam.organisations (id),
  connection_id   uuid not null,
  manifest_id     uuid not null constraint probe_runs_manifest_fkey references connect.connector_manifests (id),
  stage           text not null check (stage in ('parse', 'probe', 'reconcile', 'conform', 'propose_mapping',
                                                 'confirm', 'verify', 'recheck')),
  status          text not null default 'running' check (status in ('running', 'completed', 'failed')),
  findings        jsonb,
  errors          jsonb,
  started_at      timestamptz not null default now(),
  completed_at    timestamptz,
  unique (organisation_id, id),
  foreign key (organisation_id, connection_id) references connect.connections (organisation_id, id),
  check ((status = 'running') = (completed_at is null))
);
comment on table connect.probe_runs is
  'One stage of the sandbox probe and build pipeline for a connection; structure only (spec 17.1, 17.4).';
comment on column connect.probe_runs.findings is
  'Structure only: objects, fields, types, counts, documented versus observed disagreements. Never values.';
comment on constraint probe_runs_manifest_fkey on connect.probe_runs is
  'lint:cross-tenant catalogue reference rule (connect): guarded by connect.assert_catalogue_visible()';

create index probe_runs_history on connect.probe_runs (organisation_id, connection_id, started_at desc);
create index probe_runs_manifest on connect.probe_runs (organisation_id, manifest_id);
create index probe_runs_abandoned on connect.probe_runs (organisation_id, started_at) where status = 'running';
select platform.enable_tenant_rls('connect.probe_runs');

create constraint trigger probe_runs_catalogue_visible
  after insert or update of manifest_id on connect.probe_runs
  for each row execute function connect.assert_catalogue_visible('manifest_id:manifest');

grant select, insert, update on connect.probe_runs to silo_app;
grant select on connect.probe_runs to silo_report;

-- ===========================================================================
-- connect.conformance_runs: executions of the conformance suite (ch 17.2)
-- ===========================================================================

create table connect.conformance_runs (
  id              uuid primary key,
  organisation_id uuid not null references iam.organisations (id),
  connection_id   uuid not null,
  manifest_id     uuid not null constraint conformance_runs_manifest_fkey references connect.connector_manifests (id),
  suite_version   text not null check (length(btrim(suite_version)) > 0),
  trigger         text not null check (trigger in ('build', 'release', 'weekly', 'self_heal', 'manual')),
  route           text not null check (route in ('catalogue', 'ai', 'visual')),
  classes_run     text[] not null
                    check (classes_run <@ array['read', 'pagination', 'filter_pushdown', 'error',
                                                'write_verify_undo', 'change_stream']::text[]),
  results         jsonb not null,
  passed_count    integer not null default 0 check (passed_count >= 0),
  failed_count    integer not null default 0 check (failed_count >= 0),
  test_record_ref text,
  started_at      timestamptz not null default now(),
  completed_at    timestamptz,
  unique (organisation_id, id),
  foreign key (organisation_id, connection_id) references connect.connections (organisation_id, id)
);
comment on table connect.conformance_runs is
  'One execution of the versioned conformance suite against a connection and manifest (spec 17.2).';
comment on column connect.conformance_runs.results is
  'Per test: id, outcome (passed, failed, not_applicable), duration, redacted reason. Not applicable is never passed.';
comment on column connect.conformance_runs.test_record_ref is 'Identifier of the nominated test record, never its values.';
comment on constraint conformance_runs_manifest_fkey on connect.conformance_runs is
  'lint:cross-tenant catalogue reference rule (connect): guarded by connect.assert_catalogue_visible()';

create index conformance_runs_latest on connect.conformance_runs (organisation_id, connection_id, manifest_id, started_at desc);
create index conformance_runs_manifest on connect.conformance_runs (organisation_id, manifest_id);
create index conformance_runs_weekly on connect.conformance_runs (organisation_id, started_at desc)
  where trigger = 'weekly';
select platform.enable_tenant_rls('connect.conformance_runs');

create constraint trigger conformance_runs_catalogue_visible
  after insert or update of manifest_id on connect.conformance_runs
  for each row execute function connect.assert_catalogue_visible('manifest_id:manifest');

grant select, insert, update on connect.conformance_runs to silo_app;
grant select on connect.conformance_runs to silo_report;

-- ===========================================================================
-- connect.heal_proposals: manifest repairs after drift (ch 17.3, 17.4). A repair of
-- a global connector is a version of a private fork, so applied_manifest_id is a
-- composite key to the organisation's own manifest.
-- ===========================================================================

create table connect.heal_proposals (
  id                  uuid primary key,
  organisation_id     uuid not null references iam.organisations (id),
  connection_id       uuid not null,
  from_manifest_id    uuid not null constraint heal_proposals_from_manifest_fkey
                        references connect.connector_manifests (id),
  change_kind         text not null check (change_kind in ('rename', 'semantic', 'new_field', 'object_removed',
                                                           'type_changed', 'pushdown_lost')),
  proposed_diff       jsonb not null,
  sandbox_result      jsonb,
  conformance_run_id  uuid,
  disposition         text not null check (disposition in ('auto_applied', 'awaiting_review', 'applied', 'halted', 'rejected')),
  applied_manifest_id uuid,
  reviewed_by         uuid,
  reviewed_at         timestamptz,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),
  unique (organisation_id, id),
  foreign key (organisation_id, connection_id) references connect.connections (organisation_id, id),
  constraint heal_proposals_applied_manifest_fkey
    foreign key (organisation_id, applied_manifest_id) references connect.connector_manifests (organisation_id, id),
  constraint heal_proposals_conformance_run_fkey
    foreign key (organisation_id, conformance_run_id) references connect.conformance_runs (organisation_id, id),
  foreign key (organisation_id, reviewed_by) references iam.memberships (organisation_id, id),
  check (disposition <> 'auto_applied' or applied_manifest_id is not null),
  check (disposition <> 'rejected' or (reviewed_by is not null and reviewed_at is not null)),
  -- A repair a person accepted, tested and applied (spec 17.3, 17.5).
  constraint heal_proposals_applied_reviewed
    check (disposition <> 'applied' or (applied_manifest_id is not null and reviewed_by is not null and reviewed_at is not null))
);
comment on table connect.heal_proposals is
  'Proposed manifest repair after drift, with its sandbox result and disposition (spec 17.3, 17.4).';
comment on column connect.heal_proposals.proposed_diff is 'Manifest diff. No secrets, no values.';
comment on constraint heal_proposals_from_manifest_fkey on connect.heal_proposals is
  'lint:cross-tenant catalogue reference rule (connect): guarded by connect.assert_catalogue_visible()';

create index heal_proposals_review_queue on connect.heal_proposals (organisation_id, created_at desc)
  where disposition = 'awaiting_review';
create index heal_proposals_history on connect.heal_proposals (organisation_id, connection_id, created_at desc);
create index heal_proposals_from_manifest on connect.heal_proposals (organisation_id, from_manifest_id);
create index heal_proposals_applied_manifest on connect.heal_proposals (organisation_id, applied_manifest_id)
  where applied_manifest_id is not null;
create index heal_proposals_conformance_run on connect.heal_proposals (organisation_id, conformance_run_id)
  where conformance_run_id is not null;
create index heal_proposals_reviewed_by on connect.heal_proposals (organisation_id, reviewed_by)
  where reviewed_by is not null;
select platform.add_updated_at_trigger('connect.heal_proposals');
select platform.enable_tenant_rls('connect.heal_proposals');

create constraint trigger heal_proposals_catalogue_visible
  after insert or update of from_manifest_id on connect.heal_proposals
  for each row execute function connect.assert_catalogue_visible('from_manifest_id:manifest');

grant select, insert, update on connect.heal_proposals to silo_app;
grant select on connect.heal_proposals to silo_report;

-- The weekly re-check (spec 17.3): active connections without a completed re-check within the
-- interval (a failed one is retried after an hour), across organisations, identifiers only.
create function connect.connections_due_for_recheck(p_interval interval, p_limit integer)
returns table (organisation_id uuid, connection_id uuid)
language sql stable security definer
set search_path = pg_catalog
as $$
  select c.organisation_id, c.id from connect.connections c
  where c.status = 'active'
    and not exists (
      select 1 from connect.probe_runs r
      where r.organisation_id = c.organisation_id and r.connection_id = c.id and r.stage = 'recheck'
        and (r.status = 'running'
             or r.started_at > now() - case when r.status = 'failed' then interval '1 hour' else p_interval end))
  order by c.last_healthy_at nulls first, c.id
  limit p_limit
$$;
grant execute on function connect.connections_due_for_recheck(interval, integer) to silo_app;

-- ===========================================================================
-- connect.change_stream_subscriptions: durable consumers of a change stream (ch 18.3).
-- last_delta_at is flushed from redis-state, hence fillfactor 70. Keys to
-- automation.automations and siloes.siloes are in connect_fks.sql.
-- ===========================================================================

create table connect.change_stream_subscriptions (
  id              uuid primary key,
  organisation_id uuid not null references iam.organisations (id),
  connection_id   uuid not null,
  object_set_ref  jsonb not null,
  consumer_kind   text not null check (consumer_kind in ('cron', 'silo_capture')),
  cron_id         uuid,
  silo_id         uuid,
  source_kind     text not null check (source_kind in ('webhook', 'cdc', 'provider_events', 'poll', 'mqtt',
                                                       'opcua_subscription')),
  status          text not null default 'active' check (status in ('active', 'delayed', 'stale', 'stopped')),
  last_delta_at   timestamptz,
  watermark       text,
  created_by      uuid not null,
  created_at      timestamptz not null default now(),
  stopped_at      timestamptz,
  updated_at      timestamptz not null default now(),
  unique (organisation_id, id),
  foreign key (organisation_id, connection_id) references connect.connections (organisation_id, id),
  foreign key (organisation_id, created_by) references iam.memberships (organisation_id, id),
  check (num_nonnulls(cron_id, silo_id) = 1),
  check ((consumer_kind = 'cron') = (cron_id is not null)),
  check (status <> 'stopped' or stopped_at is not null)
) with (fillfactor = 70);
comment on table connect.change_stream_subscriptions is
  'Durable consumer (a Cron or a Silo with Capture) of a connection''s change stream (spec 18.3).';
comment on column connect.change_stream_subscriptions.object_set_ref is 'Object set definition reference, never values.';
comment on column connect.change_stream_subscriptions.last_delta_at is
  'Flushed from redis-state at most every 60 seconds and on status change.';
comment on column connect.change_stream_subscriptions.watermark is
  'Polling watermark or event cursor (timestamp, sequence or cursor), never a record value.';

create index change_stream_subscriptions_connection on connect.change_stream_subscriptions (organisation_id, connection_id)
  where status <> 'stopped';
create index change_stream_subscriptions_cron on connect.change_stream_subscriptions (organisation_id, cron_id)
  where cron_id is not null and status <> 'stopped';
create index change_stream_subscriptions_silo on connect.change_stream_subscriptions (organisation_id, silo_id)
  where silo_id is not null and status <> 'stopped';
create index change_stream_subscriptions_staleness on connect.change_stream_subscriptions (organisation_id, last_delta_at)
  where status in ('active', 'delayed');
create index change_stream_subscriptions_created_by on connect.change_stream_subscriptions (organisation_id, created_by);
select platform.add_updated_at_trigger('connect.change_stream_subscriptions');
select platform.enable_tenant_rls('connect.change_stream_subscriptions');

grant select, insert, update on connect.change_stream_subscriptions to silo_app;
grant select on connect.change_stream_subscriptions to silo_report;

-- ===========================================================================
-- connect.stream_polling_fallbacks: polling an object whose stream is not subscribable
-- (decision 2026-11-15). An admin (stream.manage) may let a source object that has not
-- passed the change-stream class be polled with a watermark every N minutes, where the
-- connector's rate limits allow; its clones then show "Not live, refreshed every N
-- minutes" with their staleness, never live. One active row per object; disabling ends it.
-- ===========================================================================

create table connect.stream_polling_fallbacks (
  id               uuid primary key,
  organisation_id  uuid not null references iam.organisations (id),
  connection_id    uuid not null,
  object           text not null check (object ~ '^[a-z][a-z0-9_]{0,62}$'),
  interval_seconds integer not null check (interval_seconds between 60 and 86400 and interval_seconds % 60 = 0),
  enabled_by       uuid not null,
  enabled_at       timestamptz not null default now(),
  disabled_by      uuid,
  disabled_at      timestamptz,
  unique (organisation_id, id),
  foreign key (organisation_id, connection_id) references connect.connections (organisation_id, id),
  foreign key (organisation_id, enabled_by) references iam.memberships (organisation_id, id),
  foreign key (organisation_id, disabled_by) references iam.memberships (organisation_id, id),
  check ((disabled_at is null) = (disabled_by is null)),
  check (disabled_at is null or disabled_at >= enabled_at)
);
comment on table connect.stream_polling_fallbacks is
  'An admin''s permission to poll a source object whose stream is not subscribable, every interval_seconds; shown as not live.';
comment on column connect.stream_polling_fallbacks.object is 'The source object, as the connector manifest names it.';

create unique index stream_polling_fallbacks_active on connect.stream_polling_fallbacks (organisation_id, connection_id, object)
  where disabled_at is null;
select platform.enable_tenant_rls('connect.stream_polling_fallbacks');

grant select, insert, update on connect.stream_polling_fallbacks to silo_app;
grant select on connect.stream_polling_fallbacks to silo_report;

-- ===========================================================================
-- connect.webhook_endpoints: inbound and outbound webhook endpoints (ch 18.8, 20.4).
-- Delivery counters are flushed in batches, hence fillfactor 70.
-- ===========================================================================

create table connect.webhook_endpoints (
  id                       uuid primary key,
  organisation_id          uuid not null references iam.organisations (id),
  connection_id            uuid not null,
  direction                text not null check (direction in ('inbound', 'outbound')),
  path_token_hash          bytea check (path_token_hash is null or octet_length(path_token_hash) = 32),
  target_url               text,
  status_url               text check (status_url is null or (length(status_url) <= 2048 and status_url like 'https://%')),
  risk_class               text not null default 'external' check (risk_class in ('external', 'physical')),
  -- The webhook action's name (20.3, 47.7): what a writable point and an actuation allow-list entry address.
  action_name              text check (action_name is null or action_name ~ '^[a-z][a-z0-9_]{0,62}$'),
  secret_credential_id     uuid not null,
  provider_registration_id text,
  status                   text not null default 'active' check (status in ('active', 'paused', 'revoked')),
  last_delivery_at         timestamptz,
  rejected_count           bigint not null default 0 check (rejected_count >= 0),
  created_by               uuid not null,
  created_at               timestamptz not null default now(),
  revoked_at               timestamptz,
  updated_at               timestamptz not null default now(),
  unique (organisation_id, id),
  foreign key (organisation_id, connection_id) references connect.connections (organisation_id, id),
  constraint webhook_endpoints_secret_credential_fkey
    foreign key (organisation_id, secret_credential_id) references connect.connection_credentials (organisation_id, id),
  foreign key (organisation_id, created_by) references iam.memberships (organisation_id, id),
  check (direction <> 'inbound' or (path_token_hash is not null and target_url is null)),
  check (direction <> 'outbound' or (target_url is not null and path_token_hash is null)),
  check (direction = 'outbound' or status_url is null),
  check (direction = 'outbound' or action_name is null),
  -- A physical target is allow-listed by its action's name (47.4), so it has one.
  check (risk_class <> 'physical' or action_name is not null),
  check (status <> 'revoked' or revoked_at is not null)
) with (fillfactor = 70);
comment on table connect.webhook_endpoints is
  'Inbound endpoints for provider events and outbound webhook targets for actions (spec 18.8, 20.4).';
comment on column connect.webhook_endpoints.path_token_hash is
  'Inbound: SHA-256 of the unguessable path token, unique across the cell. The token routes; it does not authenticate.';
comment on column connect.webhook_endpoints.rejected_count is 'Invalid signature or replay; flushed in batches.';

-- Email fallback (spec 14.4; D155): the address minted for a connection whose notifications
-- are forwarded to Silo, c-<token>@<the cell's inbound domain>. The token routes; the cell's
-- mail relay signs what it posts. Revoked, never deleted.
create table connect.email_addresses (
  id                 uuid primary key,
  organisation_id    uuid not null references iam.organisations (id),
  connection_id      uuid not null,
  token_hash         bytea not null check (octet_length(token_hash) = 32),
  status             text not null default 'active' check (status in ('active', 'revoked')),
  messages_taken     bigint not null default 0 check (messages_taken >= 0),
  messages_set_aside bigint not null default 0 check (messages_set_aside >= 0),
  last_message_at    timestamptz,
  created_by         uuid not null,
  created_at         timestamptz not null default now(),
  revoked_at         timestamptz,
  updated_at         timestamptz not null default now(),
  unique (organisation_id, id),
  foreign key (organisation_id, connection_id) references connect.connections (organisation_id, id),
  foreign key (organisation_id, created_by) references iam.memberships (organisation_id, id),
  check ((status = 'revoked') = (revoked_at is not null))
);
comment on table connect.email_addresses is
  'The address a connection''s notifications are forwarded to (email fallback, 14.4). Counts only; no message is kept.';
comment on column connect.email_addresses.token_hash is 'SHA-256 of the address''s token, unique across the cell. It routes; it does not authenticate.';
create unique index email_addresses_token on connect.email_addresses (token_hash);
create index email_addresses_connection on connect.email_addresses (organisation_id, connection_id);
create unique index email_addresses_live on connect.email_addresses (organisation_id, connection_id) where status = 'active';
create index email_addresses_created_by on connect.email_addresses (organisation_id, created_by);
select platform.add_updated_at_trigger('connect.email_addresses');
select platform.enable_tenant_rls('connect.email_addresses');
grant select, insert, update on connect.email_addresses to silo_app;
grant select on connect.email_addresses to silo_report;

-- The relay posts with no organisation in hand: the token's hash names the live address and its organisation.
-- The cell's live connections (spec 6.3; D203), for its Fleet agent to report beside its
-- registration: every organisation's but the synthetic one's, revoked ones aside. A count only.
create function connect.cell_connection_count() returns integer
language sql stable security definer
set search_path = pg_catalog
as $$
  select count(*)::integer from connect.connections c
   where c.status <> 'revoked' and not exists (select 1 from iam.organisations o where o.id = c.organisation_id and (o.is_synthetic or o.is_system))
$$;
revoke all on function connect.cell_connection_count() from public;
grant execute on function connect.cell_connection_count() to silo_app;

create function connect.resolve_email_address(p_token_hash bytea)
  returns table (organisation_id uuid, id uuid, connection_id uuid)
language sql stable security definer
set search_path = pg_catalog
as $$
  select a.organisation_id, a.id, a.connection_id from connect.email_addresses a
  where a.token_hash = p_token_hash and a.status = 'active'
$$;
revoke all on function connect.resolve_email_address(bytea) from public;
grant execute on function connect.resolve_email_address(bytea) to silo_app;
comment on column connect.webhook_endpoints.action_name is
  'Outbound: the webhook action''s name, unique among the connection''s live targets; a physical target''s writable point and allow-list entry name it (20.3, 47.4).';
comment on column connect.webhook_endpoints.status_url is
  'Outbound: the declared status endpoint a delivery''s effect is read from (20.4). Without one the receipt records delivery, not effect.';

create unique index webhook_endpoints_path_token on connect.webhook_endpoints (path_token_hash)
  where path_token_hash is not null;
create index webhook_endpoints_connection on connect.webhook_endpoints (organisation_id, connection_id)
  where status <> 'revoked';
create index webhook_endpoints_secret_credential on connect.webhook_endpoints (organisation_id, secret_credential_id);
create unique index webhook_endpoints_action on connect.webhook_endpoints (organisation_id, connection_id, action_name)
  where action_name is not null and status <> 'revoked';
create index webhook_endpoints_created_by on connect.webhook_endpoints (organisation_id, created_by);
select platform.add_updated_at_trigger('connect.webhook_endpoints');
select platform.enable_tenant_rls('connect.webhook_endpoints');

grant select, insert, update on connect.webhook_endpoints to silo_app;
grant select on connect.webhook_endpoints to silo_report;

-- ===========================================================================
-- connect.private_links: the private address ranges an Enterprise organisation's
-- VPC-to-VPC link (VPC peering or a Private Service Connect endpoint) carries into
-- the cell, so its connections reach private systems without the Silo Agent
-- (decision 2026-11-09, design D44). Silo staff add and remove them once the
-- network link exists; the credential service's egress reaches a private address
-- only inside the requesting organisation's live links.
-- ===========================================================================

create table connect.private_links (
  id                     uuid primary key,
  organisation_id        uuid not null references iam.organisations (id),
  name                   text not null check (length(btrim(name)) between 1 and 100),
  link_kind              text not null check (link_kind in ('vpc_peering', 'private_service_connect')),
  network                cidr not null,
  status                 text not null default 'active' check (status in ('active', 'removed')),
  added_by_operator_id   uuid not null references platform.operators (id),
  removed_by_operator_id uuid references platform.operators (id),
  removed_at             timestamptz,
  created_at             timestamptz not null default now(),
  updated_at             timestamptz not null default now(),
  version                integer not null default 1,
  unique (organisation_id, id),
  -- Private space only, and no wider than a /8 (IPv4) or /16 (IPv6): RFC 1918, shared
  -- address space (RFC 6598), IPv6 unique local (RFC 4193).
  constraint private_links_network_private check (
    (family(network) = 4 and masklen(network) >= 8 and (network <<= '10.0.0.0/8' or network <<= '172.16.0.0/12'
      or network <<= '192.168.0.0/16' or network <<= '100.64.0.0/10'))
    or (family(network) = 6 and masklen(network) >= 16 and network <<= 'fc00::/7')),
  check ((status = 'removed') = (removed_at is not null)),
  check ((status = 'removed') = (removed_by_operator_id is not null)),
  -- Two live links never share an address, whichever organisations hold them, so a
  -- private address belongs to one organisation at most.
  constraint private_links_no_overlap exclude using gist (network inet_ops with &&) where (status = 'active')
);
comment on table connect.private_links is
  'Private ranges an Enterprise organisation''s VPC-to-VPC link carries into the cell; the egress reaches them for that organisation only (decision 2026-11-09).';

create index private_links_live on connect.private_links (organisation_id, created_at) where status = 'active';
create index private_links_added_by on connect.private_links (added_by_operator_id);
create index private_links_removed_by on connect.private_links (removed_by_operator_id) where removed_by_operator_id is not null;
select platform.add_updated_at_trigger('connect.private_links');
select platform.enable_tenant_rls('connect.private_links');
create trigger private_links_frozen before update on connect.private_links
  for each row execute function platform.freeze_columns('id', 'organisation_id', 'link_kind', 'network', 'added_by_operator_id', 'created_at');

grant select, insert on connect.private_links to silo_app;
grant update (status, removed_by_operator_id, removed_at, updated_at, version) on connect.private_links to silo_app;
grant select on connect.private_links to silo_report;

-- ===========================================================================
-- connect.cdc_slots: change data capture slots on customer databases (ch 18, 10.3).
-- The reader lease is renewed with the heartbeat and the position acknowledged with each
-- transaction read, hence fillfactor 70. One live capture per connection: the publication
-- names its tables. Dropping is asked by a person and done by an agent of the pool, which
-- reports it; until then the slot still holds the customer's log.
-- ===========================================================================

create table connect.cdc_slots (
  id                    uuid primary key,
  organisation_id       uuid not null references iam.organisations (id),
  connection_id         uuid not null,
  agent_pool_id         uuid not null,
  -- mqtt (spec 20.2, 20.6): an agent's subscription to the connection's broker, leased as a
  -- capture is; slot_name is the client identifier the broker sees. Nothing is kept on a disk.
  method                text not null check (method in ('logical_replication', 'binlog', 'change_tracking', 'mqtt', 'opcua')),
  slot_name             text not null check (slot_name ~ '^[a-z0-9_]{1,63}$'),
  publication           text check (publication ~ '^[a-z0-9_]{1,63}$'),
  confirmed_by          uuid not null,
  status                text not null default 'active' check (status in ('active', 'lost', 'dropping', 'dropped')),
  leased_by_agent_id    uuid,
  lease_expires_at      timestamptz,
  acknowledged_position text check (length(acknowledged_position) between 1 and 100),
  acknowledged_at       timestamptz,
  lost_at               timestamptz,
  dropped_by            uuid,
  created_at            timestamptz not null default now(),
  dropped_at            timestamptz,
  updated_at            timestamptz not null default now(),
  unique (organisation_id, id),
  foreign key (organisation_id, connection_id) references connect.connections (organisation_id, id),
  foreign key (organisation_id, agent_pool_id) references connect.agent_pools (organisation_id, id),
  foreign key (organisation_id, confirmed_by) references iam.memberships (organisation_id, id),
  foreign key (organisation_id, dropped_by) references iam.memberships (organisation_id, id),
  foreign key (organisation_id, leased_by_agent_id) references connect.agents (organisation_id, id),
  check ((method = 'logical_replication') = (publication is not null)),
  check (status <> 'lost' or lost_at is not null),
  check (status not in ('dropping', 'dropped') or dropped_by is not null),
  check (status <> 'dropped' or (dropped_at is not null and leased_by_agent_id is null)),
  check ((acknowledged_position is null) = (acknowledged_at is null)),
  check (leased_by_agent_id is null or lease_expires_at is not null)
) with (fillfactor = 70);
comment on table connect.cdc_slots is
  'Change data capture slot on a customer database, created through an agent after owner confirmation (spec 18, 10.3).';
comment on column connect.cdc_slots.lease_expires_at is
  'The reading agent''s lease: renewed with its heartbeats, released when its capture stream ends; lapsed, another agent of the pool resumes.';
comment on column connect.cdc_slots.publication is
  'The Postgres publication the customer made for the captured tables (logical replication only).';
comment on column connect.cdc_slots.dropped_by is
  'Who asked for the slot to be dropped (stream.manage); dropped_at is when an agent dropped it.';
comment on column connect.cdc_slots.acknowledged_position is
  'Last acknowledged log position (LSN, binlog position, change version), never a record value.';

-- One live capture per connection, and a slot name used once on it until it is dropped.
create unique index cdc_slots_connection on connect.cdc_slots (organisation_id, connection_id) where status = 'active';
create unique index cdc_slots_slot_name on connect.cdc_slots (organisation_id, connection_id, slot_name) where status <> 'dropped';
create index cdc_slots_agent_pool on connect.cdc_slots (organisation_id, agent_pool_id) where status in ('active', 'dropping');
create index cdc_slots_lease_expiry on connect.cdc_slots (organisation_id, lease_expires_at)
  where status = 'active' and leased_by_agent_id is not null;
create index cdc_slots_leased_by on connect.cdc_slots (organisation_id, leased_by_agent_id)
  where leased_by_agent_id is not null;
create index cdc_slots_confirmed_by on connect.cdc_slots (organisation_id, confirmed_by);
create index cdc_slots_dropped_by on connect.cdc_slots (organisation_id, dropped_by) where dropped_by is not null;
select platform.add_updated_at_trigger('connect.cdc_slots');
select platform.enable_tenant_rls('connect.cdc_slots');

grant select, insert, update on connect.cdc_slots to silo_app;
grant select on connect.cdc_slots to silo_report;

-- ===========================================================================
-- connect.industrial_endpoints: MQTT brokers and OPC UA servers (ch 20.1 to 20.3)
-- ===========================================================================

create table connect.industrial_endpoints (
  id                         uuid primary key,
  organisation_id            uuid not null references iam.organisations (id),
  connection_id              uuid not null,
  plugin                     text not null check (plugin in ('mqtt', 'opcua')),
  endpoint_url               text not null check (length(btrim(endpoint_url)) > 0),
  agent_pool_id              uuid not null,
  security_policy            text not null check (length(btrim(security_policy)) > 0),
  insecure_exception_by      uuid,
  app_certificate_thumbprint text check (app_certificate_thumbprint is null or app_certificate_thumbprint ~ '^[0-9a-f]{40}$'),
  -- The application instance certificate's PEM, public: what the customer trusts on the server (20.3).
  app_certificate_pem        text check (app_certificate_pem is null or app_certificate_pem like '-----BEGIN CERTIFICATE-----%'),
  -- The server's certificate as the owner read it from the server: SHA-1 (as OPC UA tools show it) or SHA-256, hex.
  server_certificate_thumbprint text check (server_certificate_thumbprint is null or server_certificate_thumbprint ~ '^([0-9a-f]{40}|[0-9a-f]{64})$'),
  namespace_uris             text[] not null default '{}',
  verified_at                timestamptz,
  status                     text not null default 'active'
                               check (status in ('active', 'untrusted', 'unreachable', 'revoked')),
  created_at                 timestamptz not null default now(),
  updated_at                 timestamptz not null default now(),
  unique (organisation_id, id),
  -- Also the foreign key index for connection_id (no separate index).
  unique (organisation_id, connection_id, endpoint_url),
  foreign key (organisation_id, connection_id) references connect.connections (organisation_id, id),
  foreign key (organisation_id, agent_pool_id) references connect.agent_pools (organisation_id, id),
  foreign key (organisation_id, insecure_exception_by) references iam.memberships (organisation_id, id),
  -- A policy naming None needs the owner's recorded exception.
  check (security_policy !~* '\mnone\M' or insecure_exception_by is not null),
  -- A signed OPC UA policy has the application certificate and the server's pinned certificate;
  -- None and MQTT have neither.
  check ((plugin = 'opcua' and security_policy <> 'None')
         = (app_certificate_thumbprint is not null and app_certificate_pem is not null and server_certificate_thumbprint is not null))
);
comment on table connect.industrial_endpoints is
  'Broker or server endpoint of an MQTT or OPC UA connection, reached through an agent (spec 20.1 to 20.3).';
comment on column connect.industrial_endpoints.security_policy is
  'OPC UA policy and mode, or MQTT TLS settings. Naming None requires insecure_exception_by.';
comment on column connect.industrial_endpoints.insecure_exception_by is
  'Owner membership who recorded a security policy None exception.';
comment on column connect.industrial_endpoints.app_certificate_thumbprint is
  'SHA-1 of the endpoint''s OPC UA application instance certificate, as servers list it; its key is a connection '
  'credential (purpose opcua_application_key) sealed to the agent for each piece of work.';
comment on column connect.industrial_endpoints.server_certificate_thumbprint is
  'The server certificate the owner pinned; the agent refuses a server presenting any other before opening the channel.';

create index industrial_endpoints_agent_pool on connect.industrial_endpoints (organisation_id, agent_pool_id)
  where status = 'active';
create index industrial_endpoints_insecure_exception on connect.industrial_endpoints (organisation_id, insecure_exception_by)
  where insecure_exception_by is not null;
select platform.add_updated_at_trigger('connect.industrial_endpoints');
select platform.enable_tenant_rls('connect.industrial_endpoints');

grant select, insert, update on connect.industrial_endpoints to silo_app;
grant select on connect.industrial_endpoints to silo_report;

-- ===========================================================================
-- connect.writable_points: declared write targets with risk class (ch 20.5)
-- ===========================================================================

create table connect.writable_points (
  id               uuid primary key,
  organisation_id  uuid not null references iam.organisations (id),
  connection_id    uuid not null,
  manifest_id      uuid not null constraint writable_points_manifest_fkey references connect.connector_manifests (id),
  address          text not null check (length(btrim(address)) > 0),
  risk_class       text not null check (risk_class in ('standard', 'physical')),
  value_check      text not null check (length(btrim(value_check)) > 0),
  feedback_address text,
  settle_seconds   integer not null default 0 check (settle_seconds >= 0),
  test_safe        boolean not null default false,
  declared_by      uuid not null,
  declared_at      timestamptz not null default now(),
  retired_at       timestamptz,
  unique (organisation_id, id),
  unique (organisation_id, connection_id, manifest_id, address),
  foreign key (organisation_id, connection_id) references connect.connections (organisation_id, id),
  foreign key (organisation_id, declared_by) references iam.memberships (organisation_id, id)
);
comment on table connect.writable_points is
  'Declared write target on an industrial or webhook connection, with its risk class and value check (spec 20.5).';
comment on column connect.writable_points.address is
  'OPC UA node (namespace URI and identifier), MQTT topic, or webhook action name.';
comment on column connect.writable_points.value_check is 'CEL expression; required.';
comment on column connect.writable_points.test_safe is 'The owner nominated this point as safe for conformance writes.';
comment on constraint writable_points_manifest_fkey on connect.writable_points is
  'lint:cross-tenant catalogue reference rule (connect): guarded by connect.assert_catalogue_visible()';

create index writable_points_connection on connect.writable_points (organisation_id, connection_id)
  where retired_at is null;
create index writable_points_manifest on connect.writable_points (organisation_id, manifest_id);
create index writable_points_declared_by on connect.writable_points (organisation_id, declared_by);
select platform.enable_tenant_rls('connect.writable_points');

-- Immutable except risk_class (raise only), test_safe and retired_at.
create function connect.writable_points_guard() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
declare
  v_mutable constant text[] := array['risk_class', 'test_safe', 'retired_at'];
begin
  if (to_jsonb(new) - v_mutable) <> (to_jsonb(old) - v_mutable) then
    raise exception 'connect.writable_points is immutable except risk_class, test_safe and retired_at'
      using errcode = 'insufficient_privilege';
  end if;
  if old.risk_class = 'physical' and new.risk_class <> 'physical' then
    raise exception 'a writable point''s risk class can only be raised' using errcode = 'check_violation';
  end if;
  return new;
end
$$;
create trigger writable_points_guard before update on connect.writable_points
  for each row execute function connect.writable_points_guard();

create constraint trigger writable_points_catalogue_visible
  after insert or update of manifest_id on connect.writable_points
  for each row execute function connect.assert_catalogue_visible('manifest_id:manifest');

grant select, insert on connect.writable_points to silo_app;
grant update (risk_class, test_safe, retired_at) on connect.writable_points to silo_app;
grant select on connect.writable_points to silo_report;

-- ===========================================================================
-- Agent pool retirement is refused while a non-revoked connection, slot or endpoint
-- references the pool (ch 10.2).
-- ===========================================================================

create function connect.agent_pools_retire_guard() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
begin
  if exists (select 1 from connect.connections c
             where c.organisation_id = new.organisation_id and c.agent_pool_id = new.id and c.status <> 'revoked')
     or exists (select 1 from connect.cdc_slots s
                where s.organisation_id = new.organisation_id and s.agent_pool_id = new.id and s.status <> 'dropped')
     or exists (select 1 from connect.industrial_endpoints e
                where e.organisation_id = new.organisation_id and e.agent_pool_id = new.id and e.status <> 'revoked') then
    raise exception 'agent pool % still serves a live connection, CDC slot or industrial endpoint', new.id
      using errcode = 'check_violation';
  end if;
  return new;
end
$$;
create trigger agent_pools_retire_guard before update of status on connect.agent_pools
  for each row when (old.status <> 'retired' and new.status = 'retired')
  execute function connect.agent_pools_retire_guard();

-- ===========================================================================
-- connect.discovery_settings: per-organisation discovery switch, default off (ch 19.1)
-- ===========================================================================

create table connect.discovery_settings (
  organisation_id uuid primary key references iam.organisations (id),
  enabled         boolean not null default false,
  enabled_by      uuid,
  enabled_at      timestamptz,
  disabled_at     timestamptz,
  updated_at      timestamptz not null default now(),
  version         integer not null default 1,
  foreign key (organisation_id, enabled_by) references iam.memberships (organisation_id, id),
  check (not enabled or (enabled_by is not null and enabled_at is not null))
);
comment on table connect.discovery_settings is
  'Per-organisation switch for agent discovery, default off; enabling authorises no scan (spec 19.1).';

create index discovery_settings_enabled_by on connect.discovery_settings (organisation_id, enabled_by)
  where enabled_by is not null;
select platform.add_updated_at_trigger('connect.discovery_settings');
select platform.enable_tenant_rls('connect.discovery_settings');

grant select, insert, update on connect.discovery_settings to silo_app;
grant select on connect.discovery_settings to silo_report;

-- ===========================================================================
-- connect.discovery_authorisations: one scan authorisation (ch 19.2, 10.5). The key
-- to action.approval_chains is in connect_fks.sql.
-- ===========================================================================

create table connect.discovery_authorisations (
  id                uuid primary key,
  organisation_id   uuid not null references iam.organisations (id),
  agent_id          uuid not null,
  ranges            text[] not null check (cardinality(ranges) > 0 and array_position(ranges, null) is null
                                           and array_position(ranges, '') is null),
  methods           text[] not null
                      check (cardinality(methods) > 0
                             and methods <@ array['port_scan', 'host_config', 'catalogue_introspection',
                                                  'opcua_browse', 'mqtt_observe']::text[]),
  max_hosts         integer not null default 1000 check (max_hosts > 0),
  recurrence        text,
  expires_at        timestamptz not null,
  authorised_by     uuid not null,
  approval_chain_id uuid not null,
  signed_hash       bytea check (signed_hash is null or octet_length(signed_hash) = 32),
  revoked_at        timestamptz,
  created_at        timestamptz not null default now(),
  unique (organisation_id, id),
  foreign key (organisation_id, agent_id) references connect.agents (organisation_id, id),
  foreign key (organisation_id, authorised_by) references iam.memberships (organisation_id, id),
  check (expires_at > created_at)
);
comment on table connect.discovery_authorisations is
  'One scan authorisation: agent, ranges, methods, expiry, authorising member and approval chain (spec 19.2, 10.5).';
comment on column connect.discovery_authorisations.ranges is 'Explicit CIDR ranges or hosts. No default subnet.';
comment on column connect.discovery_authorisations.signed_hash is
  'SHA-256 of the cell-signed authorisation document delivered to the agent.';

create index discovery_authorisations_live on connect.discovery_authorisations (organisation_id, agent_id, expires_at)
  where revoked_at is null;
create index discovery_authorisations_list on connect.discovery_authorisations (organisation_id, created_at desc);
create index discovery_authorisations_approval_chain on connect.discovery_authorisations (organisation_id, approval_chain_id);
create index discovery_authorisations_authorised_by on connect.discovery_authorisations (organisation_id, authorised_by);
select platform.enable_tenant_rls('connect.discovery_authorisations');

-- Immutable except revoked_at, which is set once.
create function connect.discovery_authorisations_guard() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
begin
  if (to_jsonb(new) - 'revoked_at') <> (to_jsonb(old) - 'revoked_at')
     or (old.revoked_at is not null and new.revoked_at is distinct from old.revoked_at) then
    raise exception 'connect.discovery_authorisations is immutable; revoked_at is set once'
      using errcode = 'insufficient_privilege';
  end if;
  return new;
end
$$;
create trigger discovery_authorisations_guard before update on connect.discovery_authorisations
  for each row execute function connect.discovery_authorisations_guard();

grant select, insert on connect.discovery_authorisations to silo_app;
grant update (revoked_at) on connect.discovery_authorisations to silo_app;
grant select on connect.discovery_authorisations to silo_report;

-- ===========================================================================
-- connect.discovery_runs: executions of a scan under an authorisation (ch 19.6)
-- ===========================================================================

create table connect.discovery_runs (
  id                    uuid primary key,
  organisation_id       uuid not null references iam.organisations (id),
  authorisation_id      uuid not null,
  status                text not null default 'running' check (status in ('running', 'completed', 'failed', 'revoked')),
  started_at            timestamptz not null default now(),
  completed_at          timestamptz,
  hosts_contacted_count integer not null default 0 check (hosts_contacted_count >= 0),
  reasons               text[] not null default '{}' check (cardinality(reasons) <= 20),
  last_report_at        timestamptz,
  report_sequence       integer not null default 0 check (report_sequence >= 0),
  updated_at            timestamptz not null default now(),
  unique (organisation_id, id),
  foreign key (organisation_id, authorisation_id) references connect.discovery_authorisations (organisation_id, id),
  check (status = 'running' or completed_at is not null)
);
comment on table connect.discovery_runs is 'One execution of a scan under an authorisation (spec 19.6).';
comment on column connect.discovery_runs.hosts_contacted_count is
  'Distinct hosts the agent contacted or reported (connect.discovery_run_hosts), updated with each report.';
comment on column connect.discovery_runs.reasons is
  'Codes, never values: why the run stopped, and what it set aside (a finding refused, a method this agent lacks). At most 20.';
comment on column connect.discovery_runs.report_sequence is
  'The last report taken, numbered by connect-runtime from 1: a report sent again after a lost answer is not taken twice.';
comment on column connect.discovery_runs.last_report_at is
  'When connect-runtime last reported for the run (at least every few seconds while it runs): a run silent too long has lost its agent.';

create index discovery_runs_authorisation on connect.discovery_runs (organisation_id, authorisation_id, started_at desc);
create index discovery_runs_list on connect.discovery_runs (organisation_id, started_at desc);
select platform.add_updated_at_trigger('connect.discovery_runs');
select platform.enable_tenant_rls('connect.discovery_runs');

grant select, insert, update on connect.discovery_runs to silo_app;
grant select on connect.discovery_runs to silo_report;

-- Runs still running whose reports stopped (their agent or its replica went): the sweep that
-- ends them works across organisations, so it reads through this function alone.
create function connect.discovery_runs_silent(p_before timestamptz, p_limit integer)
  returns table (organisation_id uuid, run_id uuid)
language sql stable security definer
set search_path = pg_catalog
as $$
  select r.organisation_id, r.id from connect.discovery_runs r
  where r.status = 'running' and coalesce(r.last_report_at, r.started_at) < p_before
  order by r.started_at
  limit least(greatest(p_limit, 1), 1000)
$$;
revoke all on function connect.discovery_runs_silent(timestamptz, integer) from public;
grant execute on function connect.discovery_runs_silent(timestamptz, integer) to silo_app;

-- ===========================================================================
-- Agent waves (spec 11.4). The rollout of an agent release spans every organisation's
-- agents in the cell, so the waves read and flag agents through these functions alone.
-- ===========================================================================

-- Which wave an agent is in: 0 for Silo's own organisations, then by a stable hash of its id,
-- 1 for 5% of agents, 2 for the next 20%, 3 for the rest.
create function connect.agent_update_wave(p_organisation_id uuid, p_agent_id uuid, p_first_organisations uuid[])
  returns smallint
language sql immutable
set search_path = pg_catalog
as $$
  select case
    when p_organisation_id = any(coalesce(p_first_organisations, '{}')) then 0::smallint
    when ('x' || substr(encode(sha256(convert_to(p_agent_id::text, 'UTF8')), 'hex'), 1, 8))::bit(32)::bigint % 100 < 5 then 1::smallint
    when ('x' || substr(encode(sha256(convert_to(p_agent_id::text, 'UTF8')), 'hex'), 1, 8))::bit(32)::bigint % 100 < 25 then 2::smallint
    else 3::smallint
  end
$$;
grant execute on function connect.agent_update_wave(uuid, uuid, uuid[]) to silo_app;

-- Live agents of automatic pools in one wave that a rollout has to update or watch: still below
-- its version, or come onto it since it began. None: the wave has no one in it and passes at once.
create function connect.agent_wave_size(p_wave smallint, p_version text, p_version_major integer, p_version_minor integer,
  p_version_patch integer, p_since timestamptz, p_first_organisations uuid[])
  returns integer
language sql stable security definer
set search_path = pg_catalog
as $$
  select count(*)::integer
  from connect.agents a join connect.agent_pools p on p.organisation_id = a.organisation_id and p.id = a.pool_id
  where a.status <> 'revoked' and p.status = 'active' and p.update_policy = 'automatic'
    and connect.agent_update_wave(a.organisation_id, a.id, p_first_organisations) = p_wave
    and ((split_part(a.version, '.', 1)::integer, split_part(a.version, '.', 2)::integer,
          split_part(split_part(split_part(a.version, '.', 3), '-', 1), '+', 1)::integer)
         < (p_version_major, p_version_minor, p_version_patch)
         or (a.version = p_version and a.version_since >= p_since))
$$;
revoke all on function connect.agent_wave_size(smallint, text, integer, integer, integer, timestamptz, uuid[]) from public;
grant execute on function connect.agent_wave_size(smallint, text, integer, integer, integer, timestamptz, uuid[]) to silo_app;

-- The gates of a rollout, over the agents of automatic pools it reached (spec 11.4: "gated on
-- heartbeat and error rate"), at p_now (connect-runtime's clock, which wrote the times). Counts only.
--   updated:  agents that came onto the version since the rollout began;
--   stalled:  agents that took it more than p_return_minutes ago and have not come back on it;
--   silent:   updated agents that stopped heartbeating within their first hour on it;
--   failing:  updated agents with at least p_min_work pieces of work since, whose share they
--             failed is above both p_max_failed_share and twice their share before.
create function connect.agent_rollout_health(p_version text, p_since timestamptz, p_now timestamptz, p_return_minutes integer,
  p_min_work integer, p_max_failed_share double precision)
  returns table (updated integer, stalled integer, silent integer, failing integer)
language sql stable security definer
set search_path = pg_catalog
as $$
  with reached as (
    select a.* from connect.agents a
    join connect.agent_pools p on p.organisation_id = a.organisation_id and p.id = a.pool_id
    where a.status <> 'revoked' and p.update_policy = 'automatic'
  )
  select
    (select count(*) from reached where version = p_version and version_since >= p_since)::integer,
    (select count(*) from reached where updating_to = p_version and version <> p_version
       and update_started_at < p_now - make_interval(mins => p_return_minutes))::integer,
    (select count(*) from reached where version = p_version and version_since >= p_since
       and (status = 'offline' or last_heartbeat_at < p_now - interval '5 minutes')
       and coalesce(last_heartbeat_at, version_since) < version_since + interval '1 hour')::integer,
    (select count(*) from reached where version = p_version and version_since >= p_since and work_done >= p_min_work
       and work_failed::double precision / work_done > greatest(p_max_failed_share,
             2 * case when prior_work_done = 0 then 0 else prior_work_failed::double precision / prior_work_done end))::integer
$$;
revoke all on function connect.agent_rollout_health(text, timestamptz, timestamptz, integer, integer, double precision) from public;
grant execute on function connect.agent_rollout_health(text, timestamptz, timestamptz, integer, integer, double precision) to silo_app;

-- Spec 10.7: "An agent older than the last three minor releases is flagged and refused after 90
-- days." Agents below the floor (major, minor) become outdated, and refused once outdated for
-- p_refuse_after, at p_now; agents at or above it are current again. Returns the agents whose state changed.
create function connect.flag_outdated_agents(p_floor_major integer, p_floor_minor integer, p_now timestamptz, p_refuse_after interval)
  returns table (organisation_id uuid, agent_id uuid, version text, version_state text)
language sql volatile security definer
set search_path = pg_catalog
as $$
  with judged as (
    select a.organisation_id, a.id, a.version_state as was,
      case
        when (split_part(a.version, '.', 1)::integer, split_part(a.version, '.', 2)::integer) >= (p_floor_major, p_floor_minor)
          then 'current'
        when a.version_state = 'current' then 'outdated'
        when a.version_outdated_at <= p_now - p_refuse_after then 'refused'
        else a.version_state
      end as now_state
    from connect.agents a
    where a.status <> 'revoked'
  )
  update connect.agents a
     set version_state = j.now_state,
         version_outdated_at = case when j.now_state = 'current' then null else coalesce(a.version_outdated_at, p_now) end
    from judged j
   where a.organisation_id = j.organisation_id and a.id = j.id and j.now_state <> j.was
  returning a.organisation_id, a.id, a.version, a.version_state
$$;
revoke all on function connect.flag_outdated_agents(integer, integer, timestamptz, interval) from public;
grant execute on function connect.flag_outdated_agents(integer, integer, timestamptz, interval) to silo_app;

-- ===========================================================================
-- connect.discovery_run_hosts: each host a run contacted or reported, once (ch 19.3: the
-- authorisation's host bound counts distinct hosts, whichever report names them).
-- ===========================================================================

create table connect.discovery_run_hosts (
  organisation_id uuid not null references iam.organisations (id),
  run_id          uuid not null,
  host            text not null check (length(host) between 1 and 253),
  first_seen_at   timestamptz not null default now(),
  primary key (organisation_id, run_id, host),
  foreign key (organisation_id, run_id) references connect.discovery_runs (organisation_id, id)
);
comment on table connect.discovery_run_hosts is
  'Distinct hosts per discovery run, for the authorisation''s host bound (spec 19.3). A host name or an IPv4 address; no values.';
select platform.enable_tenant_rls('connect.discovery_run_hosts');

grant select, insert on connect.discovery_run_hosts to silo_app;
grant select on connect.discovery_run_hosts to silo_report;

-- ===========================================================================
-- connect.discovery_findings: discovered systems, proposals only (ch 19.4, 19.6).
-- The key to ontology.ontology_proposals is in connect_fks.sql.
-- ===========================================================================

create table connect.discovery_findings (
  id                      uuid primary key,
  organisation_id         uuid not null references iam.organisations (id),
  run_id                  uuid not null,
  host                    text not null check (length(btrim(host)) > 0),
  found                   jsonb not null,
  proposed_connector_type text,
  proposed_object_types   jsonb,
  proposed_links          jsonb,
  confidence              numeric(4, 3) check (confidence between 0 and 1),
  review_decision         text not null default 'pending' check (review_decision in ('pending', 'approved', 'rejected')),
  reviewed_by             uuid,
  reviewed_at             timestamptz,
  promoted_connection_id  uuid,
  promoted_connector_id   uuid constraint discovery_findings_promoted_connector_fkey references connect.connectors (id),
  ontology_proposal_id    uuid,
  created_at              timestamptz not null default now(),
  unique (organisation_id, id),
  foreign key (organisation_id, run_id) references connect.discovery_runs (organisation_id, id),
  foreign key (organisation_id, reviewed_by) references iam.memberships (organisation_id, id),
  constraint discovery_findings_promoted_connection_fkey
    foreign key (organisation_id, promoted_connection_id) references connect.connections (organisation_id, id),
  check (review_decision = 'pending' or (reviewed_by is not null and reviewed_at is not null))
);
comment on table connect.discovery_findings is
  'One discovered system with proposed connector, object types and links; a proposal, never a configuration '
  '(spec 19.4, 19.6).';
comment on column connect.discovery_findings.found is
  'Structure only: product, version, schemas, tables, columns, keys, row counts. Never row contents.';
comment on column connect.discovery_findings.proposed_links is
  'Link type proposals from foreign keys and inferred references (labelled inferred).';
comment on constraint discovery_findings_promoted_connector_fkey on connect.discovery_findings is
  'lint:cross-tenant catalogue reference rule (connect): guarded by connect.assert_catalogue_visible()';

create index discovery_findings_run on connect.discovery_findings (organisation_id, run_id);
