-- ===========================================================================
-- connect.discovery_probes: append-only log of every probe an agent made
-- (ch 19.3, 19.6). Monthly partitions; retention is a partition drop.
-- ===========================================================================

create table connect.discovery_probes (
  id              bigint generated always as identity,
  organisation_id uuid not null references iam.organisations (id),
  run_id          uuid not null,
  agent_id        uuid not null,
  host            text not null check (length(btrim(host)) > 0),
  port            integer check (port is null or port between 1 and 65535),
  method          text not null check (method in ('port_scan', 'host_config', 'catalogue_introspection',
                                                 'opcua_browse', 'mqtt_observe')),
  outcome         text not null check (outcome in ('open', 'closed', 'identified', 'refused', 'error')),
  probed_at       timestamptz not null,
  primary key (id, probed_at),
  foreign key (organisation_id, run_id) references connect.discovery_runs (organisation_id, id),
  foreign key (organisation_id, agent_id) references connect.agents (organisation_id, id)
) partition by range (probed_at);
comment on table connect.discovery_probes is
