insert into platform.partition_plan (parent, granularity, create_ahead) values
  ('connect.discovery_probes', 'month', 3);

-- ===========================================================================
-- Lookups before the organisation is known. Owned by silo_migrate, executable by
-- silo_app only. Each finds the row by its cell-wide unique secret hash and returns
-- only what is needed to set app.org_id; everything after runs under RLS.
-- ===========================================================================

-- OAuth callback. Consumes the flow in one statement (single use) and returns the
-- session to verify, or nothing.
create function connect.resolve_oauth_flow(p_state_hash bytea)
returns table (organisation_id uuid, connection_id uuid, session_id uuid)
language sql
volatile
security definer
set search_path = pg_catalog
as $$
  update connect.oauth_pending_flows f
     set consumed_at = now()
   where f.state_hash = p_state_hash
     and f.consumed_at is null and f.expired_at is null and f.expires_at > now()
  returning f.organisation_id, f.connection_id, f.session_id
$$;

-- OAuth sign-ins left unfinished past their expiry, in every organisation: the oauth sweep
-- marks each expired in its own organisation (oauth_flow_expired). Identifiers only.
create function connect.oauth_flows_expired(p_limit integer)
returns table (organisation_id uuid, state_hash bytea)
language sql
stable
security definer
set search_path = pg_catalog
as $$
  select f.organisation_id, f.state_hash
  from connect.oauth_pending_flows f
  where f.consumed_at is null and f.expired_at is null and f.expires_at <= now()
  order by f.expires_at
  limit least(greatest(p_limit, 1), 1000)
$$;

-- Inbound webhook delivery.
create function connect.resolve_webhook(p_path_token_hash bytea)
returns table (organisation_id uuid, id uuid, connection_id uuid, status text)
language sql
stable
security definer
set search_path = pg_catalog
as $$
  select w.organisation_id, w.id, w.connection_id, w.status
  from connect.webhook_endpoints w
  where w.path_token_hash = p_path_token_hash
$$;

-- Agent mTLS handshake.
create function connect.resolve_agent(p_certificate_fingerprint bytea)
returns table (organisation_id uuid, id uuid, pool_id uuid, status text, version text, version_state text)
language sql
stable
security definer
set search_path = pg_catalog
as $$
  select a.organisation_id, a.id, a.pool_id, a.status, a.version, a.version_state
  from connect.agents a
  where a.certificate_fingerprint = p_certificate_fingerprint
$$;

-- Agent enrolment. Consumes the token in one statement, recording the id the caller
-- has minted for the new agent; the caller inserts that agent in the same
-- transaction (the key to connect.agents is deferred to commit).
create function connect.resolve_enrolment_token(p_token_hash bytea, p_agent_id uuid)
returns table (organisation_id uuid, token_id uuid, pool_id uuid)
language sql
volatile
security definer
set search_path = pg_catalog
as $$
  update connect.agent_enrolment_tokens t
     set consumed_at = now(), consumed_by_agent_id = p_agent_id
   where t.token_hash = p_token_hash
     and t.consumed_at is null and t.revoked_at is null and t.expires_at > now()
  returning t.organisation_id, t.id, t.pool_id
$$;

grant execute on function connect.oauth_flows_expired(integer) to silo_app;
grant execute on function connect.resolve_oauth_flow(bytea),
                          connect.resolve_webhook(bytea),
                          connect.resolve_agent(bytea),
                          connect.resolve_enrolment_token(bytea, uuid)
  to silo_app;

-- ===========================================================================
-- Key retirement guard, replacing the identity version: a key version still
-- wrapping a live cell-custody connection credential cannot be retired either.
-- ===========================================================================

create or replace function iam.kms_key_retire_guard() returns trigger
language plpgsql
security definer
set search_path = pg_catalog
as $$
begin
  if exists (select 1 from iam.mfa_factors where key_version_id = new.id and revoked_at is null)
     or exists (select 1 from iam.identity_providers where key_version_id = new.id)
     or exists (select 1 from iam.organisation_keys where key_version_id = new.id and status <> 'retired')
     or exists (select 1 from connect.connection_credentials
                where key_version_id = new.id and custody = 'cell' and revoked_at is null) then
    raise exception 'key version % still wraps live keys; re-wrap before retiring', new.id
      using errcode = 'check_violation';
  end if;
  return new;
end
$$;

-- ============================================================================
-- Domain: ontology
-- ============================================================================

-- Ontology (spec chapters 21 to 27): object types and their versions, properties and
-- mappings, links, interfaces, shared properties, functions, entity resolution,
-- object sets, ontology versions, branches, proposals and the dependency index, plus
-- ontology.compiled_manifests from the cross-domain section.
-- Design: docs/siloDatabaseDesign.doc.md, "Ontology domain: schema ontology" and
-- "Cross-domain decisions and the one table no domain owned".
--
-- No table here holds a customer record value; source identifiers exist only as keyed
-- hashes in match_keys. Object type markings belong to gov. Keys into Connect,
-- Actions, workspace, automation, simulation, Siloes, recognition and governance
-- tables are added with the cross-domain keys (ontology_fks.sql); their supporting
-- indexes are here.

-- ===========================================================================
-- Shared trigger functions
-- ===========================================================================

-- Version-scoped tables are insert-only. The one permitted update, on
-- object_type_versions and function_versions: referenced_by_lineage from false to
-- true, once, with nothing else changing.
create function ontology.lineage_flag_only() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
begin
  if not old.referenced_by_lineage and new.referenced_by_lineage
     and (to_jsonb(new) - 'referenced_by_lineage') = (to_jsonb(old) - 'referenced_by_lineage') then
    return new;
  end if;
  raise exception '%.% is insert-only: only referenced_by_lineage may change, once, from false to true',
    tg_table_schema, tg_table_name using errcode = 'insufficient_privilege';
end
$$;

-- Child rows of a version are inserted only in the transaction that inserted the
-- parent version: the parent's created_at must equal now(), the transaction start.
-- Arguments: the parent table ('object_type_versions' or 'ontology_versions') and
-- the child column that holds the parent id.
create function ontology.require_parent_in_transaction() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
declare
  v_parent_id  uuid := (to_jsonb(new) ->> tg_argv[1])::uuid;
  v_created_at timestamptz;
begin
  if tg_argv[0] = 'object_type_versions' then
    select v.created_at into v_created_at
    from ontology.object_type_versions v
    where v.organisation_id = new.organisation_id and v.id = v_parent_id;
  elsif tg_argv[0] = 'ontology_versions' then
    select v.created_at into v_created_at
    from ontology.ontology_versions v
    where v.organisation_id = new.organisation_id and v.id = v_parent_id;
  else
    raise exception 'unknown parent version table %', tg_argv[0];
  end if;

  if not found then
    raise exception '%.%: parent % % not found', tg_table_schema, tg_table_name, tg_argv[0], v_parent_id
      using errcode = 'foreign_key_violation';
  end if;
  if v_created_at <> now() then
    raise exception '%.%: rows are added only in the transaction that created % %',
      tg_table_schema, tg_table_name, tg_argv[0], v_parent_id
      using errcode = 'insufficient_privilege';
  end if;
  return new;
end
$$;

-- Forward-only status. The arguments list the statuses in order; a move to an
-- earlier one is rejected.
create function ontology.status_moves_forward() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
begin
  -- A rollback (spec 25.8) brings back to active an element it restores; nothing else moves back.
  if array_position(tg_argv, new.status) < array_position(tg_argv, old.status)
     and not (new.status = 'active' and coalesce(current_setting('app.ontology_rollback', true), '') = 'on') then
    raise exception '%.%: status cannot move from % to %', tg_table_schema, tg_table_name, old.status, new.status
      using errcode = 'check_violation';
  end if;
  return new;
end
$$;

-- ===========================================================================
-- Concept templates: the one cross-tenant table (spec 22.7)
-- ===========================================================================

create table ontology.concept_templates (
  id          uuid primary key,
  name        text not null check (length(btrim(name)) > 0),
  field_names text[] not null check (cardinality(field_names) between 1 and 200),
  authored_by uuid not null,
  reviewed_by uuid,
  reviewed_at timestamptz,
  status      text not null default 'draft' check (status in ('draft', 'reviewed', 'withdrawn')),
  revision    integer not null default 1 check (revision >= 1),
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  check (status <> 'reviewed'
         or (reviewed_by is not null and reviewed_at is not null and reviewed_by <> authored_by))
);
comment on table ontology.concept_templates is
  'Silo-authored type and field names that name a first proposal (spec 22.7). Global per cell; written only by Fleet.';
comment on column ontology.concept_templates.authored_by is
  'Silo staff identity in the global directory database. No foreign key: a cell cannot join to it; Fleet validates it.';
comment on column ontology.concept_templates.reviewed_by is
  'Silo staff identity, as authored_by. Never the author.';
create unique index concept_templates_live_name on ontology.concept_templates (lower(name))
  where status in ('draft', 'reviewed');
select platform.add_updated_at_trigger('ontology.concept_templates');

-- A reviewed row never returns to draft and its names are never edited (a change is
-- a new revision with a fresh review). Rows are withdrawn, never deleted.
create function ontology.concept_templates_guard() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
begin
  if tg_op = 'DELETE' then
    raise exception 'ontology.concept_templates rows are withdrawn, never deleted'
      using errcode = 'insufficient_privilege';
  end if;
  if old.status = 'reviewed' and new.status = 'draft' then
    raise exception 'a reviewed concept template cannot return to draft'
      using errcode = 'insufficient_privilege';
  end if;
  if old.status = 'reviewed'
     and (new.name is distinct from old.name or new.field_names is distinct from old.field_names) then
    raise exception 'a reviewed concept template is not edited: a change is a new revision with a fresh review'
      using errcode = 'insufficient_privilege';
  end if;
  return new;
end
$$;
create trigger concept_templates_guard before update or delete on ontology.concept_templates
  for each row execute function ontology.concept_templates_guard();
create trigger concept_templates_no_truncate before truncate on ontology.concept_templates
  for each statement execute function platform.reject_ledger_change();

-- Tenant requests see reviewed rows only. silo_migrate (Fleet) bypasses RLS to write;
-- no tenant-facing role holds a write grant, so there is no write policy.
alter table ontology.concept_templates enable row level security;
alter table ontology.concept_templates force row level security;
create policy reviewed_only on ontology.concept_templates for select using (status = 'reviewed');

grant select on ontology.concept_templates to silo_app, silo_report;

-- ===========================================================================
-- Branches, ontology versions, proposals (spec 25.1, 25.3, 25.4)
-- ===========================================================================

create table ontology.ontology_branches (
  id                  uuid primary key,
  organisation_id     uuid not null references iam.organisations (id),
  name                text not null check (length(btrim(name)) > 0),
  kind                text not null check (kind in ('main', 'working', 'derivation', 'scenario')),
  base_version_id     uuid,
  head_version_id     uuid,
  scenario_id         uuid,
  owner_membership_id uuid,
  status              text not null default 'open' check (status in ('open', 'merged', 'abandoned')),
  created_at          timestamptz not null default now(),
  closed_at           timestamptz,
  updated_at          timestamptz not null default now(),
  row_version         integer not null default 1,
  unique (organisation_id, id),
  constraint ontology_branches_owner_fkey
    foreign key (organisation_id, owner_membership_id) references iam.memberships (organisation_id, id),
  check ((kind = 'main') = (name = 'main')),
  check (base_version_id is not null or kind = 'main'),
  check (owner_membership_id is null or kind <> 'main'),
  check ((kind = 'scenario') = (scenario_id is not null)),
  check ((status = 'open') = (closed_at is null))
);
comment on table ontology.ontology_branches is
  'A named line of change from a base version of main; main exists for every organisation (spec 25.3).';
create unique index ontology_branches_one_main on ontology.ontology_branches (organisation_id) where kind = 'main';
create unique index ontology_branches_open_name on ontology.ontology_branches (organisation_id, lower(name))
  where status = 'open';
create index ontology_branches_mine on ontology.ontology_branches (organisation_id, owner_membership_id, created_at desc)
  where status = 'open';
create index ontology_branches_base_version on ontology.ontology_branches (organisation_id, base_version_id)
  where base_version_id is not null;
create index ontology_branches_head_version on ontology.ontology_branches (organisation_id, head_version_id)
  where head_version_id is not null;
create index ontology_branches_scenario on ontology.ontology_branches (organisation_id, scenario_id)
  where scenario_id is not null;
select platform.add_updated_at_trigger('ontology.ontology_branches');
select platform.enable_tenant_rls('ontology.ontology_branches');
create trigger ontology_branches_frozen before update on ontology.ontology_branches
  for each row execute function platform.freeze_columns('id', 'organisation_id', 'kind', 'scenario_id', 'created_at');

grant select, insert, update on ontology.ontology_branches to silo_app;
grant select on ontology.ontology_branches to silo_report;

create table ontology.ontology_versions (
  id                              uuid primary key,
  organisation_id                 uuid not null references iam.organisations (id),
  branch_id                       uuid not null,
  sequence                        bigint not null,
  parent_version_id               uuid,
  merged_from_proposal_id         uuid,
  kind                            text not null check (kind in ('change', 'merge', 'rollback', 'migration')),
  rolled_back_to_version_id       uuid,
  manifest_hash                   bytea not null check (octet_length(manifest_hash) = 32),
  created_by_membership_id        uuid,
  created_by_service_principal_id uuid,
  created_at                      timestamptz not null default now(),
  unique (organisation_id, id),
  unique (organisation_id, branch_id, sequence),
  -- Deferrable: the branch head points back at its versions.
  constraint ontology_versions_branch_fkey
    foreign key (organisation_id, branch_id) references ontology.ontology_branches (organisation_id, id)
    deferrable initially deferred,
  constraint ontology_versions_parent_fkey
    foreign key (organisation_id, parent_version_id) references ontology.ontology_versions (organisation_id, id),
  constraint ontology_versions_rolled_back_to_fkey
    foreign key (organisation_id, rolled_back_to_version_id) references ontology.ontology_versions (organisation_id, id),
  constraint ontology_versions_created_by_membership_fkey
    foreign key (organisation_id, created_by_membership_id) references iam.memberships (organisation_id, id),
  constraint ontology_versions_created_by_principal_fkey
    foreign key (organisation_id, created_by_service_principal_id)
    references iam.service_principals (organisation_id, id),
  check (num_nonnulls(created_by_membership_id, created_by_service_principal_id) = 1),
  check ((kind = 'rollback') = (rolled_back_to_version_id is not null)),
  check (kind <> 'merge' or merged_from_proposal_id is not null),
  check (parent_version_id is distinct from id)
);
comment on table ontology.ontology_versions is
  'Immutable snapshot of the ontology on a branch; recorded by plans, apps, Crons and Actions (spec 25.1).';
comment on column ontology.ontology_versions.sequence is
  'Monotonic per branch, assigned by ontology-service under a row lock on the branch.';
comment on column ontology.ontology_versions.manifest_hash is
  'SHA-256 over the canonical serialisation of every element: object_type_versions and element_revisions.';
create index ontology_versions_parent on ontology.ontology_versions (organisation_id, parent_version_id);
create index ontology_versions_merged_from on ontology.ontology_versions (organisation_id, merged_from_proposal_id)
  where merged_from_proposal_id is not null;
create index ontology_versions_rolled_back_to on ontology.ontology_versions (organisation_id, rolled_back_to_version_id)
  where rolled_back_to_version_id is not null;
create index ontology_versions_created_by_membership on ontology.ontology_versions (organisation_id, created_by_membership_id)
  where created_by_membership_id is not null;
create index ontology_versions_created_by_principal on ontology.ontology_versions (organisation_id, created_by_service_principal_id)
  where created_by_service_principal_id is not null;
select platform.enable_tenant_rls('ontology.ontology_versions');
select platform.make_append_only('ontology.ontology_versions');

grant select, insert on ontology.ontology_versions to silo_app;
grant select on ontology.ontology_versions to silo_report;

alter table ontology.ontology_branches
  add constraint ontology_branches_base_version_fkey
    foreign key (organisation_id, base_version_id) references ontology.ontology_versions (organisation_id, id)
    deferrable initially deferred,
  add constraint ontology_branches_head_version_fkey
    foreign key (organisation_id, head_version_id) references ontology.ontology_versions (organisation_id, id)
    deferrable initially deferred;

create table ontology.ontology_proposals (
  id                          uuid primary key,
  organisation_id             uuid not null references iam.organisations (id),
  branch_id                   uuid not null,
  title                       text not null check (length(btrim(title)) > 0),
  description                 text,
  origin                      text not null check (origin in ('person', 'derivation', 'ai_fde', 'rollback')),
  changes                     jsonb not null,
  highest_change_class        text not null check (highest_change_class in ('additive', 'compatible', 'breaking')),
  impact                      jsonb,
  impact_computed_at          timestamptz,
  status                      text not null default 'draft'
                                check (status in ('draft', 'in_review', 'approved', 'merged', 'rejected', 'withdrawn')),
  author_membership_id        uuid,
  author_service_principal_id uuid,
  merged_by                   uuid,
  merged_at                   timestamptz,
  submitted_at                timestamptz,
  decided_at                  timestamptz,
  created_at                  timestamptz not null default now(),
  updated_at                  timestamptz not null default now(),
  row_version                 integer not null default 1,
  unique (organisation_id, id),
  constraint ontology_proposals_branch_fkey
    foreign key (organisation_id, branch_id) references ontology.ontology_branches (organisation_id, id),
  constraint ontology_proposals_author_membership_fkey
    foreign key (organisation_id, author_membership_id) references iam.memberships (organisation_id, id),
  constraint ontology_proposals_author_principal_fkey
    foreign key (organisation_id, author_service_principal_id) references iam.service_principals (organisation_id, id),
  constraint ontology_proposals_merged_by_fkey
    foreign key (organisation_id, merged_by) references iam.memberships (organisation_id, id),
  check (num_nonnulls(author_membership_id, author_service_principal_id) = 1),
  check ((merged_by is null) = (merged_at is null)),
  check ((status = 'merged') = (merged_at is not null))
);
comment on table ontology.ontology_proposals is
  'A reviewable set of changes on one branch, approved and merged by people (spec 25.4, 25.6).';
comment on column ontology.ontology_proposals.changes is 'Element references and change class per change. No values.';
comment on column ontology.ontology_proposals.impact is
  'Dependant references and counts at last analysis; rerun at merge, which is refused if it differs.';
create index ontology_proposals_review_queue on ontology.ontology_proposals (organisation_id, submitted_at desc)
  where status in ('in_review', 'approved');
create index ontology_proposals_branch on ontology.ontology_proposals (organisation_id, branch_id, created_at desc);
create index ontology_proposals_author_membership on ontology.ontology_proposals (organisation_id, author_membership_id)
  where author_membership_id is not null;
create index ontology_proposals_author_principal on ontology.ontology_proposals (organisation_id, author_service_principal_id)
  where author_service_principal_id is not null;
create index ontology_proposals_merged_by on ontology.ontology_proposals (organisation_id, merged_by)
  where merged_by is not null;
select platform.add_updated_at_trigger('ontology.ontology_proposals');
select platform.enable_tenant_rls('ontology.ontology_proposals');
create trigger ontology_proposals_frozen before update on ontology.ontology_proposals
  for each row execute function platform.freeze_columns(
    'id', 'organisation_id', 'branch_id', 'author_membership_id', 'author_service_principal_id', 'created_at');

grant select, insert, update on ontology.ontology_proposals to silo_app;
grant select on ontology.ontology_proposals to silo_report;

alter table ontology.ontology_versions
  add constraint ontology_versions_merged_from_proposal_fkey
    foreign key (organisation_id, merged_from_proposal_id) references ontology.ontology_proposals (organisation_id, id);

-- ===========================================================================
-- Object types and their versions (spec 21.5, 21.6, 25.2)
-- ===========================================================================

create table ontology.object_types (
  id                              uuid primary key,
  organisation_id                 uuid not null references iam.organisations (id),
  api_name                        text not null check (api_name ~ '^[a-z][a-z0-9_]{0,62}$'),
  status                          text not null default 'proposed'
                                    check (status in ('proposed', 'active', 'deprecated', 'retired')),
  current_version_id              uuid,
  template_id                     uuid references ontology.concept_templates (id),
  created_by_membership_id        uuid,
  created_by_service_principal_id uuid,
  confirmed_by                    uuid,
  created_at                      timestamptz not null default now(),
  confirmed_at                    timestamptz,
  deprecated_at                   timestamptz,
  retired_at                      timestamptz,
  origin_branch_id                uuid,
  updated_at                      timestamptz not null default now(),
  row_version                     integer not null default 1,
  unique (organisation_id, id),
  unique (organisation_id, api_name),
  constraint object_types_created_by_membership_fkey
    foreign key (organisation_id, created_by_membership_id) references iam.memberships (organisation_id, id),
  constraint object_types_created_by_principal_fkey
    foreign key (organisation_id, created_by_service_principal_id) references iam.service_principals (organisation_id, id),
  constraint object_types_confirmed_by_fkey
    foreign key (organisation_id, confirmed_by) references iam.memberships (organisation_id, id),
  constraint object_types_origin_branch_fkey
    foreign key (organisation_id, origin_branch_id) references ontology.ontology_branches (organisation_id, id),
  check (num_nonnulls(created_by_membership_id, created_by_service_principal_id) = 1),
  check ((confirmed_by is null) = (confirmed_at is null)),
  check (current_version_id is not null or status = 'proposed')
);
comment on table ontology.object_types is
  'Stable identity and lifecycle of an object type; its content lives in its versions (spec 21.5).';
comment on column ontology.object_types.current_version_id is
  'The version on main. Null only while proposed and no version has merged.';
comment on column ontology.object_types.origin_branch_id is
  'Set while the type exists only on a branch; cleared at merge. Main readers filter on null.';
create index object_types_live on ontology.object_types (organisation_id, status, api_name)
  where status in ('active', 'deprecated');
create index object_types_list on ontology.object_types (organisation_id, created_at desc);
create index object_types_current_version on ontology.object_types (organisation_id, current_version_id);
create index object_types_created_by_membership on ontology.object_types (organisation_id, created_by_membership_id);
create index object_types_created_by_principal on ontology.object_types (organisation_id, created_by_service_principal_id);
create index object_types_confirmed_by on ontology.object_types (organisation_id, confirmed_by);
create index object_types_origin_branch on ontology.object_types (organisation_id, origin_branch_id)
  where origin_branch_id is not null;
create index object_types_template on ontology.object_types (template_id) where template_id is not null;
select platform.add_updated_at_trigger('ontology.object_types');
select platform.enable_tenant_rls('ontology.object_types');
create trigger object_types_frozen before update on ontology.object_types
  for each row execute function platform.freeze_columns(
    'id', 'organisation_id', 'template_id', 'created_by_membership_id', 'created_by_service_principal_id',
    'created_at');
create trigger object_types_api_name_frozen before update on ontology.object_types
  for each row when (old.confirmed_at is not null)
  execute function platform.freeze_columns('api_name');
create trigger object_types_status_forward before update of status on ontology.object_types
  for each row when (old.status is distinct from new.status)
  execute function ontology.status_moves_forward('proposed', 'active', 'deprecated', 'retired');

grant select, insert, update on ontology.object_types to silo_app;
grant select on ontology.object_types to silo_report;

create table ontology.object_type_versions (
  id                              uuid primary key,
  organisation_id                 uuid not null references iam.organisations (id),
  object_type_id                  uuid not null,
  ontology_version_id             uuid not null,
  branch_id                       uuid not null,
  parent_version_id               uuid,
  display_name                    text not null check (length(btrim(display_name)) > 0),
  plural_name                     text not null check (length(btrim(plural_name)) > 0),
  description                     text,
  resolution_class                text not null check (resolution_class in ('resolvable', 'single_source')),
  match_strategy                  jsonb not null check (jsonb_typeof(match_strategy) in ('array', 'object')),
  primary_key_property_id         uuid,
  title_property_id               uuid not null,
  default_time_field_id           uuid,
  visual                          jsonb not null default '{}' check (jsonb_typeof(visual) = 'object'),
  change_class                    text not null check (change_class in ('additive', 'compatible', 'breaking')),
  -- Where the type stands in this version (spec 25.7): a retired entry takes it out of the
  -- vocabulary from this version on; earlier versions keep it.
  lifecycle                       text not null default 'active' check (lifecycle in ('active', 'deprecated', 'retired')),
  replaced_by_id                  uuid,
  retire_after                    date,
  referenced_by_lineage           boolean not null default false,
  created_by_membership_id        uuid,
  created_by_service_principal_id uuid,
  created_at                      timestamptz not null default now(),
  unique (organisation_id, id),
  constraint object_type_versions_type_version_key unique (organisation_id, object_type_id, ontology_version_id),
  constraint object_type_versions_object_type_fkey
    foreign key (organisation_id, object_type_id) references ontology.object_types (organisation_id, id),
  constraint object_type_versions_ontology_version_fkey
    foreign key (organisation_id, ontology_version_id) references ontology.ontology_versions (organisation_id, id),
  constraint object_type_versions_branch_fkey
    foreign key (organisation_id, branch_id) references ontology.ontology_branches (organisation_id, id),
  constraint object_type_versions_parent_fkey
    foreign key (organisation_id, parent_version_id) references ontology.object_type_versions (organisation_id, id),
  constraint object_type_versions_replaced_by_fkey
    foreign key (organisation_id, replaced_by_id) references ontology.object_types (organisation_id, id),
  constraint object_type_versions_lifecycle check (
    (lifecycle = 'active' and replaced_by_id is null and retire_after is null)
    or (lifecycle = 'deprecated' and retire_after is not null)
    or lifecycle = 'retired'),
  check (replaced_by_id is distinct from object_type_id),
  constraint object_type_versions_created_by_membership_fkey
    foreign key (organisation_id, created_by_membership_id) references iam.memberships (organisation_id, id),
  constraint object_type_versions_created_by_principal_fkey
    foreign key (organisation_id, created_by_service_principal_id)
    references iam.service_principals (organisation_id, id),
  check (num_nonnulls(created_by_membership_id, created_by_service_principal_id) = 1),
  check ((resolution_class = 'single_source') = (primary_key_property_id is not null)),
  check (resolution_class <> 'single_source' or match_strategy = '{}'::jsonb),
  check (parent_version_id is distinct from id)
);
comment on table ontology.object_type_versions is
  'One immutable version of an object type''s definition, authored on a branch (spec 21.5, 21.14, 25.2).';
comment on column ontology.object_type_versions.match_strategy is
  'Ordered match key property identity ids with the normalisation per key. Empty object for single_source.';
comment on column ontology.object_type_versions.primary_key_property_id is
  'Property row in this version; required for single_source. A resolvable type is keyed by the Silo object id.';
comment on column ontology.object_type_versions.referenced_by_lineage is
  'One-way flip to true, the only update this table accepts.';
create index object_type_versions_history on ontology.object_type_versions (organisation_id, object_type_id, created_at desc);
create index object_type_versions_branch on ontology.object_type_versions (organisation_id, branch_id, object_type_id);
create index object_type_versions_ontology_version on ontology.object_type_versions (organisation_id, ontology_version_id);
create index object_type_versions_replaced_by on ontology.object_type_versions (organisation_id, replaced_by_id)
  where replaced_by_id is not null;
create index object_type_versions_parent on ontology.object_type_versions (organisation_id, parent_version_id)
  where parent_version_id is not null;
create index object_type_versions_created_by_membership on ontology.object_type_versions (organisation_id, created_by_membership_id)
  where created_by_membership_id is not null;
create index object_type_versions_created_by_principal on ontology.object_type_versions (organisation_id, created_by_service_principal_id)
  where created_by_service_principal_id is not null;
-- Indexes for the same-version keys to properties and time fields (indexing rule 1).
create index object_type_versions_primary_key_property on ontology.object_type_versions
  (organisation_id, primary_key_property_id, id) where primary_key_property_id is not null;
create index object_type_versions_title_property on ontology.object_type_versions
  (organisation_id, title_property_id, id);
create index object_type_versions_default_time_field on ontology.object_type_versions
  (organisation_id, default_time_field_id, id) where default_time_field_id is not null;
select platform.enable_tenant_rls('ontology.object_type_versions');
create trigger object_type_versions_lineage_flag_only before update on ontology.object_type_versions
  for each row execute function ontology.lineage_flag_only();
create trigger ledger_no_delete before delete on ontology.object_type_versions
  for each row execute function platform.reject_ledger_change('strict');
create trigger ledger_no_truncate before truncate on ontology.object_type_versions
  for each statement execute function platform.reject_ledger_change();
create trigger object_type_versions_same_transaction before insert on ontology.object_type_versions
  for each row execute function ontology.require_parent_in_transaction('ontology_versions', 'ontology_version_id');

grant select, insert, update (referenced_by_lineage) on ontology.object_type_versions to silo_app;
grant select on ontology.object_type_versions to silo_report;

-- ---------------------------------------------------------------------------
-- Description embeddings (decision 2026-11-15; spec 7.4): what each element on main is called
-- and described, embedded for compile to narrow a large vocabulary (schema linking). Metadata
-- only. One row per element, replaced when its text changes (the hash says so).
-- ---------------------------------------------------------------------------
create table ontology.description_embeddings (
  id                   uuid primary key,
  organisation_id      uuid not null references iam.organisations (id),
  kind                 text not null check (kind in ('object_type', 'property', 'link_type')),
  element_id           uuid not null,
  object_type_id       uuid not null,
  other_object_type_id uuid,
  text_hash            text not null check (text_hash ~ '^[0-9a-f]{64}$'),
  embedding            public.vector(1536) not null,
  model                text not null check (length(btrim(model)) > 0),
  embedded_at          timestamptz not null default now(),
  unique (organisation_id, id),
  constraint description_embeddings_element_key unique (organisation_id, kind, element_id),
  check ((kind = 'link_type') = (other_object_type_id is not null)),
  check (kind <> 'object_type' or element_id = object_type_id)
);
comment on table ontology.description_embeddings is
  'Embeddings of the names and descriptions of elements on main, for narrowing a compile vocabulary. Never a record value.';
comment on column ontology.description_embeddings.element_id is
  'The object type id, the property identity id or the link type id. No foreign key: a cache of main, rebuilt from it.';
comment on column ontology.description_embeddings.object_type_id is
  'The type it belongs to; for a link type, its from type (other_object_type_id is its to type).';
comment on column ontology.description_embeddings.text_hash is
  'SHA-256 of the text embedded: a different hash means the description changed and is embedded again.';
create index description_embeddings_by_type on ontology.description_embeddings (organisation_id, object_type_id);
create index description_embeddings_by_other_type on ontology.description_embeddings (organisation_id, other_object_type_id)
  where other_object_type_id is not null;
