-- assertResolvable (spec 22.6): a resolvable type version has at least two
-- contributing objects, a single-source one exactly one. Checked at commit, fired by
-- the version insert (so a version with none is caught) and by each contributing
-- object insert. The argument names the column that holds the version id.
create function ontology.assert_resolution_class() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
declare
  v_version_id uuid := (to_jsonb(new) ->> tg_argv[0])::uuid;
  v_class      text;
  v_count      bigint;
begin
  select v.resolution_class into v_class
  from ontology.object_type_versions v
  where v.organisation_id = new.organisation_id and v.id = v_version_id;
  if not found then
    return null;
  end if;

  select count(*) into v_count
  from ontology.contributing_objects c
  where c.organisation_id = new.organisation_id and c.object_type_version_id = v_version_id;

  if v_class = 'resolvable' and v_count < 2 then
    raise exception 'object type version % is resolvable and needs at least two contributing objects, has %',
      v_version_id, v_count using errcode = 'check_violation';
  elsif v_class = 'single_source' and v_count <> 1 then
    raise exception 'object type version % is single_source and needs exactly one contributing object, has %',
      v_version_id, v_count using errcode = 'check_violation';
  end if;
  return null;
end
$$;
create constraint trigger object_type_versions_resolution_class
  after insert on ontology.object_type_versions
  deferrable initially deferred
  for each row execute function ontology.assert_resolution_class('id');
create constraint trigger contributing_objects_resolution_class
  after insert on ontology.contributing_objects
  deferrable initially deferred
  for each row execute function ontology.assert_resolution_class('object_type_version_id');

