create table ontology.properties (
  id                           uuid primary key,
  organisation_id              uuid not null references iam.organisations (id),
  object_type_version_id       uuid not null,
  property_identity_id         uuid not null,
  api_name                     text not null,
  display_name                 text not null,
  description                  text,
  data_type                    text not null check (data_type in ('string', 'integer', 'decimal', 'boolean', 'date',
                                                                  'timestamp', 'duration', 'money', 'enum',
                                                                  'geopoint', 'geoshape', 'struct', 'array')),
  type_params                  jsonb not null default '{}' check (jsonb_typeof(type_params) = 'object'),
  nullable                     boolean not null,
  is_match_key                 boolean not null default false,
  shared_property_id           uuid,
  computed_function_version_id uuid,
  status                       text not null default 'active' check (status in ('active', 'deprecated', 'retired')),
  created_at                   timestamptz not null default now(),
  unique (organisation_id, id),
  constraint properties_version_id_key unique (organisation_id, object_type_version_id, id),
  constraint properties_version_api_name_key unique (organisation_id, object_type_version_id, api_name),
  -- Identity first, so the key also serves following a property across versions and
  -- the identity foreign key.
  constraint properties_identity_version_key unique (organisation_id, property_identity_id, object_type_version_id),
  constraint properties_version_fkey
    foreign key (organisation_id, object_type_version_id) references ontology.object_type_versions (organisation_id, id),
  constraint properties_identity_fkey
    foreign key (organisation_id, property_identity_id) references ontology.property_identities (organisation_id, id),
  constraint properties_shared_property_fkey
    foreign key (organisation_id, shared_property_id) references ontology.shared_properties (organisation_id, id),
  constraint properties_computed_function_version_fkey
    foreign key (organisation_id, computed_function_version_id) references ontology.function_versions (organisation_id, id),
  check (not (is_match_key and computed_function_version_id is not null))
);
comment on table ontology.properties is 'One property of one object type version (spec 21.6).';
comment on column ontology.properties.id is
  'Row id of this property in this type version. The stable id across versions is property_identity_id.';
comment on column ontology.properties.computed_function_version_id is
  'Set for computed properties, which have no mappings.';
create index properties_live on ontology.properties (organisation_id, object_type_version_id)
  where status <> 'retired';
create index properties_shared_property on ontology.properties (organisation_id, shared_property_id)
  where shared_property_id is not null;
create index properties_computed_function_version on ontology.properties (organisation_id, computed_function_version_id)
  where computed_function_version_id is not null;
