grant select on ontology.properties to silo_report;

create table ontology.property_mappings (
  id                     uuid primary key,
  organisation_id        uuid not null references iam.organisations (id),
  object_type_version_id uuid not null,
  property_id            uuid not null,
  connection_id          uuid not null,
  source_object          text not null,
  field_path             text not null,
  value_map              jsonb,
  source_time_zone       text,
  confidence             numeric(4, 3) not null check (confidence between 0 and 1),
  confirmed_by           uuid not null,
  confirmed_at           timestamptz not null,
  created_at             timestamptz not null default now(),
  unique (organisation_id, id),
  constraint property_mappings_source_key
    unique (organisation_id, object_type_version_id, property_id, connection_id, source_object),
  -- Same version: a mapping can never point at another version's property.
  constraint property_mappings_property_fkey
    foreign key (organisation_id, object_type_version_id, property_id)
    references ontology.properties (organisation_id, object_type_version_id, id),
  constraint property_mappings_confirmed_by_fkey
    foreign key (organisation_id, confirmed_by) references iam.memberships (organisation_id, id)
);
comment on table ontology.property_mappings is
  'The field map: which source field supplies a property for one contributing connection (spec 21.6).';
comment on column ontology.property_mappings.value_map is
  'Declared enum or boolean normalisation. Source codes only, never record values.';
comment on column ontology.property_mappings.source_time_zone is
  'IANA name, declared by the mapping when the source stores local time without offset. Never guessed.';
create index property_mappings_connection on ontology.property_mappings (organisation_id, connection_id, source_object);
create index property_mappings_confirmed_by on ontology.property_mappings (organisation_id, confirmed_by);
select platform.enable_tenant_rls('ontology.property_mappings');
select platform.make_append_only('ontology.property_mappings');
create trigger property_mappings_same_transaction before insert on ontology.property_mappings
  for each row execute function ontology.require_parent_in_transaction('object_type_versions', 'object_type_version_id');

-- At commit: the mapped (connection, source object) is a contributing object of the
-- same type version, a computed property is never mapped, and a declared source time
-- zone is a known IANA name.
create function ontology.property_mappings_check() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
begin
  if exists (select 1 from ontology.properties p
             where p.organisation_id = new.organisation_id
               and p.object_type_version_id = new.object_type_version_id
               and p.id = new.property_id
               and p.computed_function_version_id is not null) then
    raise exception 'property % is computed and cannot be mapped', new.property_id
      using errcode = 'check_violation';
  end if;
  if not exists (select 1 from ontology.contributing_objects c
                 where c.organisation_id = new.organisation_id
                   and c.object_type_version_id = new.object_type_version_id
                   and c.connection_id = new.connection_id
                   and c.source_object = new.source_object) then
    raise exception 'mapping source (%, %) is not a contributing object of type version %',
      new.connection_id, new.source_object, new.object_type_version_id using errcode = 'check_violation';
  end if;
  if new.source_time_zone is not null
     and not exists (select 1 from pg_timezone_names where name = new.source_time_zone) then
    raise exception 'unknown IANA time zone: %', new.source_time_zone using errcode = 'check_violation';
  end if;
  return null;
end
$$;
create constraint trigger property_mappings_check
  after insert on ontology.property_mappings
  deferrable initially deferred
  for each row execute function ontology.property_mappings_check();

grant select, insert on ontology.property_mappings to silo_app;
grant select on ontology.property_mappings to silo_report;

