  created_at             timestamptz not null default now(),
  unique (organisation_id, id),
  constraint time_fields_version_id_key unique (organisation_id, object_type_version_id, id),
  constraint time_fields_version_property_key unique (organisation_id, object_type_version_id, property_id),
  constraint time_fields_property_fkey
    foreign key (organisation_id, object_type_version_id, property_id)
    references ontology.properties (organisation_id, object_type_version_id, id)
);
comment on table ontology.time_fields is
  'The declared time fields of a type version, at most one of them the default (spec 21.6, 26.8).';
comment on column ontology.time_fields.meaning is 'Person-written, for example raised, amended, dated, due.';
create unique index time_fields_one_default on ontology.time_fields (organisation_id, object_type_version_id)
  where is_default;
select platform.enable_tenant_rls('ontology.time_fields');
select platform.make_append_only('ontology.time_fields');
create trigger time_fields_same_transaction before insert on ontology.time_fields
  for each row execute function ontology.require_parent_in_transaction('object_type_versions', 'object_type_version_id');

-- A time field is a date or timestamp property.
create function ontology.time_fields_check_type() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
declare
  v_data_type text;
begin
  select p.data_type into v_data_type
  from ontology.properties p
  where p.organisation_id = new.organisation_id
    and p.object_type_version_id = new.object_type_version_id
    and p.id = new.property_id;
  if found and v_data_type not in ('date', 'timestamp') then
    raise exception 'time field % must be a date or timestamp property, not %', new.id, v_data_type
      using errcode = 'check_violation';
  end if;
  return null;
end
$$;
create constraint trigger time_fields_property_type
  after insert on ontology.time_fields
  for each row execute function ontology.time_fields_check_type();

grant select, insert on ontology.time_fields to silo_app;
grant select on ontology.time_fields to silo_report;

