-- ===========================================================================
-- Link types and routes (spec 21.8)
-- ===========================================================================

create table ontology.link_types (
  id                  uuid primary key,
  organisation_id     uuid not null references iam.organisations (id),
  ontology_version_id uuid not null,
  api_name            text not null,
  forward_name        text not null,
  reverse_name        text not null,
  from_type_id        uuid not null,
  to_type_id          uuid not null,
  cardinality         text not null check (cardinality in ('one_to_one', 'one_to_many', 'many_to_many')),
  default_route_id    uuid,
  status              text not null check (status in ('proposed', 'active', 'deprecated', 'retired')),
  confirmed_by        uuid,
  confirmed_at        timestamptz,
  origin_branch_id    uuid,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),
  deprecated_at       timestamptz,
  retired_at          timestamptz,
  row_version         integer not null default 1,
  unique (organisation_id, id),
  unique (organisation_id, api_name),
  constraint link_types_ontology_version_fkey
    foreign key (organisation_id, ontology_version_id) references ontology.ontology_versions (organisation_id, id),
  constraint link_types_from_type_fkey
    foreign key (organisation_id, from_type_id) references ontology.object_types (organisation_id, id),
  constraint link_types_to_type_fkey
    foreign key (organisation_id, to_type_id) references ontology.object_types (organisation_id, id),
  constraint link_types_confirmed_by_fkey
    foreign key (organisation_id, confirmed_by) references iam.memberships (organisation_id, id),
  constraint link_types_origin_branch_fkey
    foreign key (organisation_id, origin_branch_id) references ontology.ontology_branches (organisation_id, id),
  check ((confirmed_by is null) = (confirmed_at is null)),
  check (status <> 'proposed' or confirmed_at is null)
);
comment on table ontology.link_types is
  'A directed, typed relationship between two object types with one or more routes (spec 21.8).';
comment on column ontology.link_types.default_route_id is 'One of this link type''s routes. Set under ontology.manage.';
create index link_types_from_type on ontology.link_types (organisation_id, from_type_id)
  where status in ('active', 'deprecated');
create index link_types_to_type on ontology.link_types (organisation_id, to_type_id)
  where status in ('active', 'deprecated');
create index link_types_ontology_version on ontology.link_types (organisation_id, ontology_version_id);
