  position          integer not null check (position >= 0),
  connection_id     uuid not null,
  source_object     text not null,
  foreign_key_field text not null,
  referenced_field  text not null,
  junction_object   text,
  -- The referenced end in another system (D248): the other type's contributing object there.
  referenced_connection_id uuid,
  referenced_object text,
  -- inferred: proposed from value overlap where the organisation turned link inference on, then confirmed by a person (D75).
  origin            text not null check (origin in ('declared_fk', 'person_declared', 'inferred')),
  created_at        timestamptz not null default now(),
  removed_at        timestamptz,
  unique (organisation_id, id),
