  interface_id           uuid not null,
  object_type_version_id uuid not null,
  property_bindings      jsonb not null check (jsonb_typeof(property_bindings) = 'object'),
  link_bindings          jsonb not null default '{}' check (jsonb_typeof(link_bindings) = 'object'),
  created_at             timestamptz not null default now(),
  unique (organisation_id, id),
  constraint interface_implementations_interface_version_key
    unique (organisation_id, interface_id, object_type_version_id),
  constraint interface_implementations_interface_fkey
    foreign key (organisation_id, interface_id) references ontology.interfaces (organisation_id, id),
  constraint interface_implementations_version_fkey
    foreign key (organisation_id, object_type_version_id) references ontology.object_type_versions (organisation_id, id)
);
comment on table ontology.interface_implementations is
  'A type version''s declaration that it implements an interface, with its bindings (spec 21.9).';
comment on column ontology.interface_implementations.property_bindings is
  'Shared property id to the property row id in this type version. Not foreign keys; ontology_dependencies records them.';
comment on column ontology.interface_implementations.link_bindings is 'Required link name to link type id.';
create index interface_implementations_version on ontology.interface_implementations
  (organisation_id, object_type_version_id);
select platform.enable_tenant_rls('ontology.interface_implementations');
select platform.make_append_only('ontology.interface_implementations');
create trigger interface_implementations_same_transaction before insert on ontology.interface_implementations
  for each row execute function ontology.require_parent_in_transaction('object_type_versions', 'object_type_version_id');

-- At commit: every required shared property is bound to a property of the same type
-- version with the shared property's data type, every required link name is bound,
-- and each bound link type starts or ends at the implementing object type.
create function ontology.interface_implementations_check() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
declare
  v_object_type_id uuid;
  v_link_names     text[];
  v_missing        text;
  b                record;
begin
  select v.object_type_id into v_object_type_id
  from ontology.object_type_versions v
  where v.organisation_id = new.organisation_id and v.id = new.object_type_version_id;

  select i.required_link_type_names into v_link_names
  from ontology.interfaces i
  where i.organisation_id = new.organisation_id and i.id = new.interface_id;

  select string_agg(r.shared_property_id::text, ', ') into v_missing
  from ontology.interface_required_properties r
  where r.organisation_id = new.organisation_id and r.interface_id = new.interface_id
    and r.removed_at is null
    and not new.property_bindings ? r.shared_property_id::text;
  if v_missing is not null then
    raise exception 'implementation of interface % does not bind required shared properties: %',
      new.interface_id, v_missing using errcode = 'check_violation';
  end if;

  for b in
    select k.key, k.value, sp.data_type as wanted, p.data_type as actual
    from jsonb_each_text(new.property_bindings) k
    left join ontology.shared_properties sp
      on sp.organisation_id = new.organisation_id and sp.id::text = k.key
    left join ontology.properties p
      on p.organisation_id = new.organisation_id and p.object_type_version_id = new.object_type_version_id
     and p.id::text = k.value
  loop
    if b.wanted is null or b.actual is null or b.wanted <> b.actual then
      raise exception 'property binding % -> % must name a property of type version % with the shared property''s data type',
        b.key, b.value, new.object_type_version_id using errcode = 'check_violation';
    end if;
  end loop;

  select string_agg(n, ', ') into v_missing
  from unnest(coalesce(v_link_names, '{}'::text[])) n
  where not new.link_bindings ? n;
  if v_missing is not null then
    raise exception 'implementation of interface % does not bind required links: %',
      new.interface_id, v_missing using errcode = 'check_violation';
  end if;

  for b in
    select k.key, k.value, l.id as link_type_id
    from jsonb_each_text(new.link_bindings) k
    left join ontology.link_types l
      on l.organisation_id = new.organisation_id and l.id::text = k.value
     and v_object_type_id in (l.from_type_id, l.to_type_id)
  loop
    if b.link_type_id is null then
      raise exception 'link binding % -> % must name a link type to or from the implementing object type',
        b.key, b.value using errcode = 'check_violation';
    end if;
  end loop;
  return null;
end
$$;
create constraint trigger interface_implementations_check
  after insert on ontology.interface_implementations
  deferrable initially deferred
  for each row execute function ontology.interface_implementations_check();

grant select, insert on ontology.interface_implementations to silo_app;
grant select on ontology.interface_implementations to silo_report;

-- ===========================================================================
-- Field authorities (spec 23.4)
-- ===========================================================================

create table ontology.field_authorities (
  id                    uuid primary key,
  organisation_id       uuid not null references iam.organisations (id),
  object_type_id        uuid not null,
  property_identity_id  uuid not null,
  winning_connection_id uuid not null,
  condition             text,
  declared_by           uuid not null,
  declared_at           timestamptz not null default now(),
  reason                text not null check (length(btrim(reason)) > 0),
  revoked_by            uuid,
  revoked_at            timestamptz,
  ontology_version_id   uuid not null,
  origin_branch_id      uuid,
  unique (organisation_id, id),
  constraint field_authorities_property_identity_fkey
    foreign key (organisation_id, object_type_id, property_identity_id)
    references ontology.property_identities (organisation_id, object_type_id, id),
  constraint field_authorities_declared_by_fkey
    foreign key (organisation_id, declared_by) references iam.memberships (organisation_id, id),
  constraint field_authorities_revoked_by_fkey
    foreign key (organisation_id, revoked_by) references iam.memberships (organisation_id, id),
  constraint field_authorities_ontology_version_fkey
    foreign key (organisation_id, ontology_version_id) references ontology.ontology_versions (organisation_id, id),
  constraint field_authorities_origin_branch_fkey
    foreign key (organisation_id, origin_branch_id) references ontology.ontology_branches (organisation_id, id),
  check ((revoked_by is null) = (revoked_at is null))
);
comment on table ontology.field_authorities is
  'A person''s declaration of which system wins for a property, optionally under a condition (spec 23.4).';
comment on column ontology.field_authorities.condition is 'CEL predicate.';
create index field_authorities_live on ontology.field_authorities (organisation_id, object_type_id, property_identity_id)
  where revoked_at is null and origin_branch_id is null;
create index field_authorities_winning_connection on ontology.field_authorities (organisation_id, winning_connection_id)
  where revoked_at is null;
create index field_authorities_declared_by on ontology.field_authorities (organisation_id, declared_by);
create index field_authorities_revoked_by on ontology.field_authorities (organisation_id, revoked_by)
  where revoked_by is not null;
create index field_authorities_ontology_version on ontology.field_authorities (organisation_id, ontology_version_id);
create index field_authorities_origin_branch on ontology.field_authorities (organisation_id, origin_branch_id)
  where origin_branch_id is not null;
select platform.enable_tenant_rls('ontology.field_authorities');
create trigger field_authorities_frozen before update on ontology.field_authorities
  for each row execute function platform.freeze_columns(
    'id', 'organisation_id', 'object_type_id', 'property_identity_id', 'declared_by', 'declared_at',
    'ontology_version_id');

-- At commit, for a live authority on main: the winning connection has a mapping for
-- the property in the type's current version. Branch authorities are checked when
-- merge clears origin_branch_id. Reads the row as it stands at commit.
create function ontology.field_authorities_check_mapping() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
declare
  r ontology.field_authorities;
begin
  select fa.* into r
  from ontology.field_authorities fa
  where fa.organisation_id = new.organisation_id and fa.id = new.id;
  if not found or r.revoked_at is not null or r.origin_branch_id is not null then
    return null;
  end if;

  if not exists (
    select 1
    from ontology.object_types t
    join ontology.properties p
      on p.organisation_id = t.organisation_id and p.object_type_version_id = t.current_version_id
     and p.property_identity_id = r.property_identity_id
    join ontology.property_mappings m
      on m.organisation_id = p.organisation_id and m.object_type_version_id = p.object_type_version_id
     and m.property_id = p.id and m.connection_id = r.winning_connection_id
    where t.organisation_id = r.organisation_id and t.id = r.object_type_id) then
    raise exception 'field authority %: connection % has no mapping for the property in the current version of object type %',
      r.id, r.winning_connection_id, r.object_type_id using errcode = 'check_violation';
  end if;
  return null;
end
$$;
create constraint trigger field_authorities_winning_mapping
  after insert or update of winning_connection_id, origin_branch_id on ontology.field_authorities
  deferrable initially deferred
  for each row execute function ontology.field_authorities_check_mapping();

grant select, insert, update on ontology.field_authorities to silo_app;
grant select on ontology.field_authorities to silo_report;

-- ===========================================================================
-- Element revisions (spec 25.1, 25.8)
-- ===========================================================================

create table ontology.element_revisions (
  id                  uuid primary key,
  organisation_id     uuid not null references iam.organisations (id),
  ontology_version_id uuid not null,
  link_type_id        uuid,
  interface_id        uuid,
  shared_property_id  uuid,
  function_id         uuid,
  field_authority_id  uuid,
  element_ref         uuid generated always as
                        (coalesce(link_type_id, interface_id, shared_property_id, function_id, field_authority_id)) stored,
  revision            integer not null check (revision >= 1),
  operation           text not null check (operation in ('create', 'change', 'deprecate', 'retire', 'revoke')),
  change_class        text not null check (change_class in ('additive', 'compatible', 'breaking')),
  -- Where the element stands in this version (spec 25.7); retired takes it out of the
  -- vocabulary from this version on. The replacement is an element of the same kind.
  lifecycle           text not null default 'active' check (lifecycle in ('active', 'deprecated', 'retired')),
  replaced_by_ref     uuid,
  retire_after        date,
  snapshot            jsonb not null check (jsonb_typeof(snapshot) = 'object'),
  content_hash        bytea not null check (octet_length(content_hash) = 32),
  created_at          timestamptz not null default now(),
  unique (organisation_id, id),
  constraint element_revisions_element_revision_key unique (organisation_id, element_ref, revision),
  constraint element_revisions_ontology_version_fkey
    foreign key (organisation_id, ontology_version_id) references ontology.ontology_versions (organisation_id, id),
  constraint element_revisions_link_type_fkey
    foreign key (organisation_id, link_type_id) references ontology.link_types (organisation_id, id),
  constraint element_revisions_interface_fkey
    foreign key (organisation_id, interface_id) references ontology.interfaces (organisation_id, id),
  constraint element_revisions_shared_property_fkey
    foreign key (organisation_id, shared_property_id) references ontology.shared_properties (organisation_id, id),
  constraint element_revisions_function_fkey
    foreign key (organisation_id, function_id) references ontology.functions (organisation_id, id),
  constraint element_revisions_field_authority_fkey
    foreign key (organisation_id, field_authority_id) references ontology.field_authorities (organisation_id, id),
  check (num_nonnulls(link_type_id, interface_id, shared_property_id, function_id, field_authority_id) = 1),
  constraint element_revisions_lifecycle check (
    (lifecycle = 'active' and replaced_by_ref is null and retire_after is null)
    or (lifecycle = 'deprecated' and retire_after is not null)
    or lifecycle = 'retired'),
  check (operation <> 'retire' or lifecycle = 'retired'),
  check (operation <> 'deprecate' or lifecycle = 'deprecated'),
  check (replaced_by_ref is distinct from element_ref)
);
comment on table ontology.element_revisions is
  'Immutable record of each change to a current-state element in an ontology version (spec 25.1, 25.8).';
comment on column ontology.element_revisions.snapshot is
  'Metadata of the element after the change: names, types, ids, routes, bindings. Never record values.';
comment on column ontology.element_revisions.content_hash is 'SHA-256 of the canonical snapshot.';
comment on constraint element_revisions_link_type_fkey on ontology.element_revisions is
  'lint:no-index the arc column equals element_ref, served by (organisation_id, element_ref, revision); purge is the only delete';
comment on constraint element_revisions_interface_fkey on ontology.element_revisions is
  'lint:no-index the arc column equals element_ref, served by (organisation_id, element_ref, revision); purge is the only delete';
comment on constraint element_revisions_shared_property_fkey on ontology.element_revisions is
  'lint:no-index the arc column equals element_ref, served by (organisation_id, element_ref, revision); purge is the only delete';
comment on constraint element_revisions_function_fkey on ontology.element_revisions is
  'lint:no-index the arc column equals element_ref, served by (organisation_id, element_ref, revision); purge is the only delete';
comment on constraint element_revisions_field_authority_fkey on ontology.element_revisions is
  'lint:no-index the arc column equals element_ref, served by (organisation_id, element_ref, revision); purge is the only delete';
create index element_revisions_ontology_version on ontology.element_revisions (organisation_id, ontology_version_id);
select platform.enable_tenant_rls('ontology.element_revisions');
select platform.make_append_only('ontology.element_revisions');
create trigger element_revisions_same_transaction before insert on ontology.element_revisions
  for each row execute function ontology.require_parent_in_transaction('ontology_versions', 'ontology_version_id');

grant select, insert on ontology.element_revisions to silo_app;
grant select on ontology.element_revisions to silo_report;

-- ===========================================================================
-- Field profiles (spec 22.3)
-- ===========================================================================

create table ontology.field_profiles (
  id                     uuid primary key,
  organisation_id        uuid not null references iam.organisations (id),
  connection_id          uuid not null,
  source_object          text not null,
  field_path             text not null,
  row_count              bigint not null check (row_count >= 0),
  distinct_count         bigint check (distinct_count >= 0),
  null_count             bigint not null check (null_count >= 0),
  empty_count            bigint not null check (empty_count >= 0),
  min_length             integer check (min_length >= 0),
  max_length             integer check (max_length >= 0),
  type_conformance_count bigint not null check (type_conformance_count >= 0),
  profiled_at            timestamptz not null,
  connector_version      text not null,
  created_at             timestamptz not null default now(),
  unique (organisation_id, id),
  constraint field_profiles_column_key unique (organisation_id, connection_id, source_object, field_path, profiled_at),
  check (null_count + empty_count <= row_count),
  check (distinct_count <= row_count),
  check (type_conformance_count <= row_count),
  check (min_length <= max_length)
);
comment on table ontology.field_profiles is
  'Counts describing one source column, for derivation and confirmation; no column can hold a value (spec 22.3).';
comment on column ontology.field_profiles.distinct_count is
  'Exact only; null when the source cannot push COUNT(DISTINCT). Never estimated from a sample.';
select platform.enable_tenant_rls('ontology.field_profiles');

-- Insert-only; a re-profile adds a row. Retention removes old rows as silo_migrate.
grant select, insert on ontology.field_profiles to silo_app;
grant select on ontology.field_profiles to silo_report;

-- ===========================================================================
-- Entity resolution (spec 23.2, 23.3, 24.7, 24.8)
-- ===========================================================================

create table ontology.resolution_proposals (
  id                               uuid primary key,
  organisation_id                  uuid not null references iam.organisations (id),
  object_type_id                   uuid not null,
  kind                             text not null check (kind in ('normalisation_rule', 'pair_list', 'split')),
  proposal                         jsonb not null,
  affected_count                   integer not null check (affected_count >= 0),
  proposed_by_membership_id        uuid,
  proposed_by_service_principal_id uuid,
  status                           text not null default 'open' check (status in ('open', 'confirmed', 'rejected')),
  decided_by                       uuid,
  decided_at                       timestamptz,
  created_at                       timestamptz not null default now(),
  updated_at                       timestamptz not null default now(),
  unique (organisation_id, id),
  constraint resolution_proposals_object_type_fkey
    foreign key (organisation_id, object_type_id) references ontology.object_types (organisation_id, id),
  constraint resolution_proposals_proposed_by_membership_fkey
    foreign key (organisation_id, proposed_by_membership_id) references iam.memberships (organisation_id, id),
  constraint resolution_proposals_proposed_by_principal_fkey
    foreign key (organisation_id, proposed_by_service_principal_id)
    references iam.service_principals (organisation_id, id),
  constraint resolution_proposals_decided_by_fkey
    foreign key (organisation_id, decided_by) references iam.memberships (organisation_id, id),
  check (num_nonnulls(proposed_by_membership_id, proposed_by_service_principal_id) = 1),
  check ((status = 'open') = (decided_by is null and decided_at is null))
);
comment on table ontology.resolution_proposals is
  'A proposed normalisation rule, pair list or split, confirmed by a person (spec 23.2).';
comment on column ontology.resolution_proposals.proposal is
  'Rule expression or references to match key ids. Key shapes only, never record values.';
create index resolution_proposals_open on ontology.resolution_proposals (organisation_id, created_at desc)
  where status = 'open';
create index resolution_proposals_by_type on ontology.resolution_proposals (organisation_id, object_type_id, created_at desc);
create index resolution_proposals_proposed_by_membership on ontology.resolution_proposals
  (organisation_id, proposed_by_membership_id) where proposed_by_membership_id is not null;
create index resolution_proposals_proposed_by_principal on ontology.resolution_proposals
  (organisation_id, proposed_by_service_principal_id) where proposed_by_service_principal_id is not null;
create index resolution_proposals_decided_by on ontology.resolution_proposals (organisation_id, decided_by)
  where decided_by is not null;
select platform.add_updated_at_trigger('ontology.resolution_proposals');
select platform.enable_tenant_rls('ontology.resolution_proposals');
create trigger resolution_proposals_frozen before update on ontology.resolution_proposals
