-- The entity graph. Hash-partitioned by organisation into 64 partitions, created
-- below. Nothing references it.
create table ontology.match_keys (
  id                     uuid not null,
  organisation_id        uuid not null references iam.organisations (id),
  object_type_id         uuid not null,
  silo_object_id         uuid not null,
  connection_id          uuid not null,
  source_object          text not null,
  source_identifier_hash bytea not null check (octet_length(source_identifier_hash) = 32),
  match_key_hash         bytea not null check (octet_length(match_key_hash) = 32),
  hmac_key_version_id    uuid not null,
  hmac_key_purpose       text not null default 'hmac' check (hmac_key_purpose = 'hmac'),
  origin                 text not null check (origin in ('exact', 'confirmed_mapping')),
  resolution_proposal_id uuid,
  first_seen_at          timestamptz not null default now(),
  last_seen_at           timestamptz not null default now(),
  superseded_at          timestamptz,
  created_at             timestamptz not null default now(),
  primary key (organisation_id, id),
  constraint match_keys_object_type_fkey
    foreign key (organisation_id, object_type_id) references ontology.object_types (organisation_id, id),
  constraint match_keys_resolution_proposal_fkey
    foreign key (organisation_id, resolution_proposal_id) references ontology.resolution_proposals (organisation_id, id),
  -- Pins the key's purpose to 'hmac', so a data key can never be named (review R7).
  constraint match_keys_hmac_key_fkey
    foreign key (organisation_id, hmac_key_version_id, hmac_key_purpose)
    references iam.organisation_keys (organisation_id, id, purpose),
  check ((origin = 'confirmed_mapping') = (resolution_proposal_id is not null))
) partition by hash (organisation_id);
comment on table ontology.match_keys is
  'The entity graph: which keyed-hashed source identifiers belong to which Silo object (spec 23.3, 24.7, 24.8).';
comment on column ontology.match_keys.silo_object_id is
  'UUIDv5 computed by the engine on first resolution, never recomputed. Not a foreign key: objects are virtual.';
comment on column ontology.match_keys.source_identifier_hash is
  'HMAC-SHA-256 of the source identifier under the organisation HMAC key. Never logged, never returned.';
comment on column ontology.match_keys.match_key_hash is
  'HMAC-SHA-256 of the normalised match key under the same key. Never logged, never returned.';
comment on column ontology.match_keys.hmac_key_purpose is 'Always hmac; exists so the key reference proves the purpose.';
create unique index match_keys_live_source on ontology.match_keys
  (organisation_id, object_type_id, connection_id, source_object, source_identifier_hash)
  where superseded_at is null;
create index match_keys_merge_lookup on ontology.match_keys (organisation_id, object_type_id, match_key_hash)
  include (silo_object_id, connection_id, source_object, source_identifier_hash)
  where superseded_at is null;
create index match_keys_by_object on ontology.match_keys (organisation_id, silo_object_id)
  include (connection_id, source_object, source_identifier_hash)
  where superseded_at is null;
create index match_keys_connection on ontology.match_keys (organisation_id, connection_id)
  where superseded_at is null;
create index match_keys_resolution_proposal on ontology.match_keys (organisation_id, resolution_proposal_id)
  where resolution_proposal_id is not null;
create index match_keys_hmac_key on ontology.match_keys (organisation_id, hmac_key_version_id, hmac_key_purpose);
select platform.enable_tenant_rls('ontology.match_keys');

