-- Postgres names each partition's copy of a parent index from its columns, which
-- truncates past 63 characters. Rename them to <partition>_<parent index suffix>,
-- for example match_keys_p7_merge_lookup.
do $$
declare
  r record;
  v_name text;
begin
  for r in
    select child.relname as child_index, part.relname as partition_name, parent.relname as parent_index
    from pg_inherits inh
    join pg_class child on child.oid = inh.inhrelid
    join pg_class parent on parent.oid = inh.inhparent
    join pg_index ix on ix.indexrelid = child.oid
    join pg_class part on part.oid = ix.indrelid
    where parent.relkind = 'I'
      and parent.relnamespace = 'ontology'::regnamespace
      and parent.relname like 'match\_keys\_%'
  loop
    v_name := r.partition_name || substr(r.parent_index, length('match_keys') + 1);
    if r.child_index <> v_name then
      execute format('alter index ontology.%I rename to %I', r.child_index, v_name);
    end if;
  end loop;
end
$$;

-- last_seen_at is touched by a batched write at most hourly; superseded_at is set
-- only by remapping. Nothing else changes.
grant select, insert, update (last_seen_at, superseded_at) on ontology.match_keys to silo_app;
grant select on ontology.match_keys to silo_report;

create table ontology.object_redirects (
  id                     uuid primary key,
  organisation_id        uuid not null references iam.organisations (id),
  object_type_id         uuid not null,
  from_silo_object_id    uuid not null,
  to_silo_object_id      uuid not null,
  resolution_proposal_id uuid,
  created_at             timestamptz not null default now(),
  undone_at              timestamptz,
  unique (organisation_id, id),
  constraint object_redirects_object_type_fkey
    foreign key (organisation_id, object_type_id) references ontology.object_types (organisation_id, id),
  constraint object_redirects_resolution_proposal_fkey
    foreign key (organisation_id, resolution_proposal_id) references ontology.resolution_proposals (organisation_id, id),
  check (from_silo_object_id <> to_silo_object_id)
);
comment on table ontology.object_redirects is
  'One Silo object id merged into another by a source-system merge; reads of the old id resolve to the target (spec 24.8).';
comment on column ontology.object_redirects.undone_at is 'Set by a confirmed split.';
create unique index object_redirects_live_from on ontology.object_redirects (organisation_id, from_silo_object_id)
  where undone_at is null;
create index object_redirects_live_to on ontology.object_redirects (organisation_id, to_silo_object_id)
  where undone_at is null;
create index object_redirects_object_type on ontology.object_redirects (organisation_id, object_type_id);
create index object_redirects_resolution_proposal on ontology.object_redirects (organisation_id, resolution_proposal_id)
  where resolution_proposal_id is not null;
select platform.enable_tenant_rls('ontology.object_redirects');

-- A live redirect may not close a cycle: walk the target's own redirect chain and
-- reject if it reaches the source. Serialised per organisation so two concurrent
-- inserts cannot close a cycle between them.
create function ontology.object_redirects_reject_cycle() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
declare
  v_next  uuid := new.to_silo_object_id;
  v_depth integer := 0;
begin
  perform pg_advisory_xact_lock(hashtextextended('ontology.object_redirects:' || new.organisation_id::text, 0));
  loop
    select r.to_silo_object_id into v_next
    from ontology.object_redirects r
    where r.organisation_id = new.organisation_id and r.from_silo_object_id = v_next
      and r.undone_at is null and r.id <> new.id;
    exit when not found;
    if v_next = new.from_silo_object_id then
      raise exception 'redirect % -> % would form a cycle', new.from_silo_object_id, new.to_silo_object_id
        using errcode = 'check_violation';
    end if;
    v_depth := v_depth + 1;
    if v_depth > 64 then
      raise exception 'redirect chain from % exceeds 64 steps', new.to_silo_object_id using errcode = 'check_violation';
    end if;
  end loop;
  return new;
end
$$;
create trigger object_redirects_reject_cycle
  before insert or update of from_silo_object_id, to_silo_object_id, undone_at on ontology.object_redirects
  for each row when (new.undone_at is null)
  execute function ontology.object_redirects_reject_cycle();

-- undone_at is the only column that changes (a confirmed split).
grant select, insert, update (undone_at) on ontology.object_redirects to silo_app;
grant select on ontology.object_redirects to silo_report;

-- ===========================================================================
-- Object sets (spec 24.4)
-- ===========================================================================

create table ontology.object_sets (
  id                  uuid primary key,
  organisation_id     uuid not null references iam.organisations (id),
  name                text not null check (length(btrim(name)) > 0),
  description         text,
  kind                text not null check (kind in ('filter', 'traversal', 'explicit', 'composite')),
  base_type_id        uuid,
  base_interface_id   uuid,
  definition          jsonb not null,
  explicit_ids        uuid[],
  ontology_version_id uuid not null,
  owner_membership_id uuid not null,
  visibility          text not null default 'private' check (visibility in ('private', 'shared')),
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),
  archived_at         timestamptz,
  row_version         integer not null default 1,
  unique (organisation_id, id),
  constraint object_sets_base_type_fkey
    foreign key (organisation_id, base_type_id) references ontology.object_types (organisation_id, id),
  constraint object_sets_base_interface_fkey
    foreign key (organisation_id, base_interface_id) references ontology.interfaces (organisation_id, id),
  constraint object_sets_ontology_version_fkey
    foreign key (organisation_id, ontology_version_id) references ontology.ontology_versions (organisation_id, id),
  constraint object_sets_owner_fkey
    foreign key (organisation_id, owner_membership_id) references iam.memberships (organisation_id, id),
  check (num_nonnulls(base_type_id, base_interface_id) = 1),
  check ((kind = 'explicit') = (explicit_ids is not null)),
  check (cardinality(explicit_ids) <= 10000)
);
comment on table ontology.object_sets is
  'A saved definition of a set of objects; never the members, except ids for explicit sets (spec 24.4).';
comment on column ontology.object_sets.definition is
  'Predicates, traversal path, set operations; periods stored unresolved. Dependencies mirrored in ontology_dependencies.';
comment on column ontology.object_sets.explicit_ids is 'Silo object ids, explicit sets only. Validated by the engine.';
create unique index object_sets_live_name on ontology.object_sets (organisation_id, owner_membership_id, lower(name))
  where archived_at is null;
create index object_sets_mine on ontology.object_sets (organisation_id, owner_membership_id, created_at desc)
  where archived_at is null;
create index object_sets_shared on ontology.object_sets (organisation_id, created_at desc)
  where visibility = 'shared' and archived_at is null;
create index object_sets_base_type on ontology.object_sets (organisation_id, base_type_id)
  where base_type_id is not null;
create index object_sets_base_interface on ontology.object_sets (organisation_id, base_interface_id)
  where base_interface_id is not null;
create index object_sets_ontology_version on ontology.object_sets (organisation_id, ontology_version_id);
select platform.add_updated_at_trigger('ontology.object_sets');
select platform.enable_tenant_rls('ontology.object_sets');
create trigger object_sets_frozen before update on ontology.object_sets
  for each row execute function platform.freeze_columns('id', 'organisation_id', 'created_at');

grant select, insert, update on ontology.object_sets to silo_app;
grant select on ontology.object_sets to silo_report;

-- ===========================================================================
-- Proposal approvals (spec 25.4)
-- ===========================================================================

create table ontology.proposal_approvals (
  id              uuid primary key,
  organisation_id uuid not null references iam.organisations (id),
  proposal_id     uuid not null,
  membership_id   uuid not null,
  permission      text not null check (permission in ('ontology.confirm', 'ontology.manage', 'ontology.mark')),
  marking_id      uuid,
  approved_at     timestamptz not null default now(),
  unique (organisation_id, id),
  constraint proposal_approvals_once_key unique (organisation_id, proposal_id, membership_id, permission),
  constraint proposal_approvals_proposal_fkey
    foreign key (organisation_id, proposal_id) references ontology.ontology_proposals (organisation_id, id),
  constraint proposal_approvals_membership_fkey
    foreign key (organisation_id, membership_id) references iam.memberships (organisation_id, id),
  check (permission <> 'ontology.mark' or marking_id is not null)
);
comment on table ontology.proposal_approvals is
  'One person''s approval of a proposal, with the permission used. People only (spec 25.4).';
comment on column ontology.proposal_approvals.marking_id is 'For ontology.mark: the marking the approver holds.';
create index proposal_approvals_membership on ontology.proposal_approvals (organisation_id, membership_id);
create index proposal_approvals_marking on ontology.proposal_approvals (organisation_id, marking_id)
  where marking_id is not null;
select platform.enable_tenant_rls('ontology.proposal_approvals');

-- The author of a proposal cannot approve it.
create function ontology.proposal_approvals_not_author() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
begin
  if exists (select 1 from ontology.ontology_proposals p
             where p.organisation_id = new.organisation_id and p.id = new.proposal_id
               and p.author_membership_id = new.membership_id) then
    raise exception 'the author of proposal % cannot approve it', new.proposal_id
      using errcode = 'insufficient_privilege';
  end if;
  return null;
end
$$;
create constraint trigger proposal_approvals_not_author
  after insert on ontology.proposal_approvals
  for each row execute function ontology.proposal_approvals_not_author();

grant select, insert on ontology.proposal_approvals to silo_app;
grant select on ontology.proposal_approvals to silo_report;

-- ===========================================================================
-- Dependency index (spec 25.6)
-- ===========================================================================

-- Seven days before a deprecated element's retirement, the owners of its dependants are told
-- again (spec 25.7; D65). Written at deprecation, sent once by the ontology service's sweep,
-- cancelled when the element is retired first.
create table ontology.retirement_reminders (
  id              uuid primary key,
  organisation_id uuid not null references iam.organisations (id),
  element_kind    text not null check (element_kind in ('object_type', 'link_type', 'shared_property', 'interface', 'function')),
  element_id      uuid not null,
  retire_after    date not null,
  remind_on       date not null,
  sent_at         timestamptz,
  cancelled_at    timestamptz,
  created_at      timestamptz not null default now(),
  unique (organisation_id, id),
  check (remind_on <= retire_after),
  check (num_nonnulls(sent_at, cancelled_at) <= 1)
);
comment on table ontology.retirement_reminders is
  'A deprecated element''s reminder to the owners of its dependants, seven days before retirement (25.7).';
create unique index retirement_reminders_open on ontology.retirement_reminders (organisation_id, element_id)
  where sent_at is null and cancelled_at is null;
create index retirement_reminders_due on ontology.retirement_reminders (remind_on) where sent_at is null and cancelled_at is null;
select platform.enable_tenant_rls('ontology.retirement_reminders');
grant select, insert on ontology.retirement_reminders to silo_app;
grant update (sent_at, cancelled_at) on ontology.retirement_reminders to silo_app;
grant select on ontology.retirement_reminders to silo_report;

create function ontology.retirement_reminders_due(p_on date, p_limit integer)
  returns table (organisation_id uuid, id uuid)
language sql stable security definer
set search_path = pg_catalog
as $$
  select r.organisation_id, r.id from ontology.retirement_reminders r
  where r.sent_at is null and r.cancelled_at is null and r.remind_on <= p_on
  order by r.remind_on, r.id
  limit least(greatest(p_limit, 1), 1000)
$$;
revoke all on function ontology.retirement_reminders_due(date, integer) from public;
grant execute on function ontology.retirement_reminders_due(date, integer) to silo_app;

create table ontology.ontology_dependencies (
  id                          uuid primary key,
  organisation_id             uuid not null references iam.organisations (id),
  -- Element arc: exactly one.
  object_type_id              uuid,
  property_identity_id        uuid,
  link_type_id                uuid,
  interface_id                uuid,
  shared_property_id          uuid,
  function_id                 uuid,
  action_type_id              uuid,
  -- Dependant arc: exactly one.
  app_id                      uuid,
  saved_view_id               uuid,
  object_set_id               uuid,
  automation_id               uuid,
  dependant_action_type_id    uuid,
  scenario_id                 uuid,
  dependant_function_id       uuid,
  silo_object_type_id         uuid,
  detector_threshold_id       uuid,
  lens_id                     uuid,
  interface_implementation_id uuid,
  element_ref                 uuid generated always as
                                (coalesce(object_type_id, property_identity_id, link_type_id, interface_id,
                                          shared_property_id, function_id, action_type_id)) stored,
  dependant_ref               uuid generated always as
                                (coalesce(app_id, saved_view_id, object_set_id, automation_id, dependant_action_type_id,
                                          scenario_id, dependant_function_id, silo_object_type_id,
                                          detector_threshold_id, lens_id, interface_implementation_id)) stored,
  ontology_version_id         uuid not null,
  recorded_at                 timestamptz not null default now(),
  removed_at                  timestamptz,
  unique (organisation_id, id),
  constraint ontology_dependencies_ontology_version_fkey
    foreign key (organisation_id, ontology_version_id) references ontology.ontology_versions (organisation_id, id),
  constraint ontology_dependencies_object_type_fkey
    foreign key (organisation_id, object_type_id) references ontology.object_types (organisation_id, id),
  constraint ontology_dependencies_property_identity_fkey
    foreign key (organisation_id, property_identity_id) references ontology.property_identities (organisation_id, id),
  constraint ontology_dependencies_link_type_fkey
    foreign key (organisation_id, link_type_id) references ontology.link_types (organisation_id, id),
  constraint ontology_dependencies_interface_fkey
    foreign key (organisation_id, interface_id) references ontology.interfaces (organisation_id, id),
  constraint ontology_dependencies_shared_property_fkey
    foreign key (organisation_id, shared_property_id) references ontology.shared_properties (organisation_id, id),
  constraint ontology_dependencies_function_fkey
    foreign key (organisation_id, function_id) references ontology.functions (organisation_id, id),
  constraint ontology_dependencies_object_set_fkey
    foreign key (organisation_id, object_set_id) references ontology.object_sets (organisation_id, id),
  constraint ontology_dependencies_dependant_function_fkey
    foreign key (organisation_id, dependant_function_id) references ontology.functions (organisation_id, id),
  constraint ontology_dependencies_interface_implementation_fkey
    foreign key (organisation_id, interface_implementation_id)
    references ontology.interface_implementations (organisation_id, id),
  constraint ontology_dependencies_one_element
    check (num_nonnulls(object_type_id, property_identity_id, link_type_id, interface_id, shared_property_id,
                        function_id, action_type_id) = 1),
  constraint ontology_dependencies_one_dependant
    check (num_nonnulls(app_id, saved_view_id, object_set_id, automation_id, dependant_action_type_id, scenario_id,
                        dependant_function_id, silo_object_type_id, detector_threshold_id, lens_id,
                        interface_implementation_id) = 1)
);
comment on table ontology.ontology_dependencies is
  'The dependency index: which dependants rely on which ontology elements, written at every compile, save and publish (spec 25.6).';
comment on column ontology.ontology_dependencies.element_ref is 'The element arc column that is set.';
comment on column ontology.ontology_dependencies.dependant_ref is 'The dependant arc column that is set.';
comment on column ontology.ontology_dependencies.removed_at is
  'Set when a recompile no longer uses the element. Rows are never hard-deleted.';
-- Every element column has its own index: "what depends on this element" is the
-- impact analysis every proposal runs. The dependant columns are a stated exception to
-- indexing rule 1: a dependant column equals dependant_ref whenever it is set, so the
-- dependant_ref index serves every lookup by a dependant, and rows are only
-- soft-removed. The cross-domain dependant keys carry the same comment.
comment on constraint ontology_dependencies_object_set_fkey on ontology.ontology_dependencies is
  'lint:no-index arc column equals dependant_ref, served by (organisation_id, dependant_ref); rows are soft-removed';
comment on constraint ontology_dependencies_dependant_function_fkey on ontology.ontology_dependencies is
  'lint:no-index arc column equals dependant_ref, served by (organisation_id, dependant_ref); rows are soft-removed';
comment on constraint ontology_dependencies_interface_implementation_fkey on ontology.ontology_dependencies is
  'lint:no-index arc column equals dependant_ref, served by (organisation_id, dependant_ref); rows are soft-removed';
create unique index ontology_dependencies_live on ontology.ontology_dependencies
  (organisation_id, element_ref, dependant_ref) where removed_at is null;
create index ontology_dependencies_by_element on ontology.ontology_dependencies (organisation_id, element_ref)
  include (dependant_ref, ontology_version_id) where removed_at is null;
create index ontology_dependencies_by_dependant on ontology.ontology_dependencies (organisation_id, dependant_ref)
  where removed_at is null;
create index ontology_dependencies_ontology_version on ontology.ontology_dependencies (organisation_id, ontology_version_id);
create index ontology_dependencies_object_type on ontology.ontology_dependencies (organisation_id, object_type_id)
  where object_type_id is not null;
create index ontology_dependencies_property_identity on ontology.ontology_dependencies
  (organisation_id, property_identity_id) where property_identity_id is not null;
create index ontology_dependencies_link_type on ontology.ontology_dependencies (organisation_id, link_type_id)
  where link_type_id is not null;
create index ontology_dependencies_interface on ontology.ontology_dependencies (organisation_id, interface_id)
  where interface_id is not null;
create index ontology_dependencies_shared_property on ontology.ontology_dependencies
  (organisation_id, shared_property_id) where shared_property_id is not null;
create index ontology_dependencies_function on ontology.ontology_dependencies (organisation_id, function_id)
  where function_id is not null;
create index ontology_dependencies_action_type on ontology.ontology_dependencies (organisation_id, action_type_id)
  where action_type_id is not null;
select platform.enable_tenant_rls('ontology.ontology_dependencies');

-- The one write path (design: compile-service and the publish and save paths call
-- it). Records that the dependant relies on exactly the given elements, compiled
-- against p_ontology_version_id: upserts a live row per element and marks the
-- dependant's other live rows removed. Runs as the owner to mint row ids; every
-- statement is confined to app.org_id.
--   p_dependant_kind: app, saved_view, object_set, automation, action_type, scenario,
--     function, silo_object_type, detector_threshold, lens, interface_implementation.
--   p_element_kinds (parallel to p_element_ids): object_type, property_identity,
--     link_type, interface, shared_property, function, action_type.
create function ontology.record_dependencies(
  p_dependant_kind      text,
  p_dependant_id        uuid,
  p_ontology_version_id uuid,
  p_element_kinds       text[],
  p_element_ids         uuid[])
returns void
language plpgsql
security definer
set search_path = pg_catalog
as $$
declare
  v_org uuid := (select current_setting('app.org_id')::uuid);
begin
  if p_dependant_kind is null
     or p_dependant_kind not in ('app', 'saved_view', 'object_set', 'automation', 'action_type', 'scenario',
                                 'function', 'silo_object_type', 'detector_threshold', 'lens',
                                 'interface_implementation') then
    raise exception 'unknown dependant kind: %', p_dependant_kind using errcode = 'invalid_parameter_value';
  end if;
  if p_dependant_id is null or p_ontology_version_id is null then
    raise exception 'dependant id and ontology version are required' using errcode = 'invalid_parameter_value';
  end if;
  if coalesce(cardinality(p_element_kinds), 0) <> coalesce(cardinality(p_element_ids), 0) then
    raise exception 'element kinds and ids differ in length' using errcode = 'invalid_parameter_value';
  end if;
  if exists (select 1 from unnest(p_element_kinds, p_element_ids) as e(kind, id)
             where e.id is null or e.kind is null
                or e.kind not in ('object_type', 'property_identity', 'link_type', 'interface',
                                  'shared_property', 'function', 'action_type')) then
    raise exception 'unknown element kind or missing element id' using errcode = 'invalid_parameter_value';
  end if;

  update ontology.ontology_dependencies d
     set removed_at = now()
   where d.organisation_id = v_org
     and d.dependant_ref = p_dependant_id
     and d.removed_at is null
     and d.element_ref <> all (coalesce(p_element_ids, '{}'::uuid[]));

  insert into ontology.ontology_dependencies (
    id, organisation_id,
    object_type_id, property_identity_id, link_type_id, interface_id, shared_property_id, function_id,
    action_type_id,
    app_id, saved_view_id, object_set_id, automation_id, dependant_action_type_id, scenario_id,
    dependant_function_id, silo_object_type_id, detector_threshold_id, lens_id, interface_implementation_id,
    ontology_version_id, recorded_at)
  select platform.uuid_v7(), v_org,
         case when e.kind = 'object_type' then e.id end,
         case when e.kind = 'property_identity' then e.id end,
         case when e.kind = 'link_type' then e.id end,
         case when e.kind = 'interface' then e.id end,
         case when e.kind = 'shared_property' then e.id end,
         case when e.kind = 'function' then e.id end,
         case when e.kind = 'action_type' then e.id end,
         case when p_dependant_kind = 'app' then p_dependant_id end,
         case when p_dependant_kind = 'saved_view' then p_dependant_id end,
         case when p_dependant_kind = 'object_set' then p_dependant_id end,
         case when p_dependant_kind = 'automation' then p_dependant_id end,
         case when p_dependant_kind = 'action_type' then p_dependant_id end,
         case when p_dependant_kind = 'scenario' then p_dependant_id end,
         case when p_dependant_kind = 'function' then p_dependant_id end,
         case when p_dependant_kind = 'silo_object_type' then p_dependant_id end,
         case when p_dependant_kind = 'detector_threshold' then p_dependant_id end,
         case when p_dependant_kind = 'lens' then p_dependant_id end,
         case when p_dependant_kind = 'interface_implementation' then p_dependant_id end,
         p_ontology_version_id, now()
  from (select distinct u.kind, u.id from unnest(p_element_kinds, p_element_ids) as u(kind, id)) as e
  on conflict (organisation_id, element_ref, dependant_ref) where removed_at is null
  do update set ontology_version_id = excluded.ontology_version_id,
                recorded_at = excluded.recorded_at;
end
$$;

-- Writes go through ontology.record_dependencies only.
grant select on ontology.ontology_dependencies to silo_app, silo_report;
grant execute on function ontology.record_dependencies(text, uuid, uuid, text[], uuid[]) to silo_app;

-- ===========================================================================
-- Compiled manifests (cross-domain section; spec chapters 26 and 43)
-- ===========================================================================

create table ontology.compiled_manifests (
  id                              uuid primary key,
  organisation_id                 uuid not null references iam.organisations (id),
  kind                            text not null check (kind in ('query', 'analysis')),
  manifest                        jsonb not null check (jsonb_typeof(manifest) = 'object'),
  manifest_hash                   bytea not null check (octet_length(manifest_hash) = 32),
  schema_version                  text not null,
  ontology_version_id             uuid not null,
  policy_version                  bigint not null check (policy_version >= 1),
  period_expressions              jsonb,
  compile_class                   text not null check (compile_class in ('standard', 'advanced')),
  created_by_membership_id        uuid,
  created_by_service_principal_id uuid,
  created_at                      timestamptz not null default now(),
  unique (organisation_id, id),
  constraint compiled_manifests_dedup_key unique (organisation_id, manifest_hash, policy_version),
  constraint compiled_manifests_ontology_version_fkey
    foreign key (organisation_id, ontology_version_id) references ontology.ontology_versions (organisation_id, id),
  constraint compiled_manifests_created_by_membership_fkey
    foreign key (organisation_id, created_by_membership_id) references iam.memberships (organisation_id, id),
  constraint compiled_manifests_created_by_principal_fkey
    foreign key (organisation_id, created_by_service_principal_id)
    references iam.service_principals (organisation_id, id),
  check (num_nonnulls(created_by_membership_id, created_by_service_principal_id) = 1)
);
comment on table ontology.compiled_manifests is
  'The validated plan structure from the compile stage, referenced by saved views, Ask turns and analysis steps (spec 26, 43).';
comment on column ontology.compiled_manifests.manifest is
  'Plan over object types, properties, filters, joins, periods and bounds. Structure only: literals are placeholders.';
comment on column ontology.compiled_manifests.policy_version is
  'iam.policy_versions.version in force at compile, so a stale plan is detectable.';
comment on column ontology.compiled_manifests.period_expressions is
  'Relative periods as written, kept apart from their resolution so a saved view re-resolves on each run.';
create index compiled_manifests_list on ontology.compiled_manifests (organisation_id, created_at desc);
create index compiled_manifests_ontology_version on ontology.compiled_manifests (organisation_id, ontology_version_id);
create index compiled_manifests_created_by_membership on ontology.compiled_manifests (organisation_id, created_by_membership_id)
  where created_by_membership_id is not null;
create index compiled_manifests_created_by_principal on ontology.compiled_manifests (organisation_id, created_by_service_principal_id)
  where created_by_service_principal_id is not null;
select platform.enable_tenant_rls('ontology.compiled_manifests');

-- Insert-only: manifests are immutable once compiled. Retention sweeps run as silo_migrate.
grant select, insert on ontology.compiled_manifests to silo_app;
grant select on ontology.compiled_manifests to silo_report;

-- A stored plan's bound values (planParameters), sealed under the organisation data key and
-- kept by the holder's id (an ask turn, a saved view), so a stored plan replays exactly.
create table ontology.plan_bindings (
  id                              uuid not null,
  organisation_id                 uuid not null references iam.organisations (id),
  compiled_manifest_id            uuid not null,
  parameters                      bytea not null,
  created_by_membership_id        uuid,
  created_by_service_principal_id uuid,
  created_at                      timestamptz not null default now(),
  primary key (organisation_id, id),
  constraint plan_bindings_manifest_fkey
    foreign key (organisation_id, compiled_manifest_id) references ontology.compiled_manifests (organisation_id, id),
  check (num_nonnulls(created_by_membership_id, created_by_service_principal_id) = 1)
);
create index plan_bindings_manifest on ontology.plan_bindings (organisation_id, compiled_manifest_id);
select platform.enable_tenant_rls('ontology.plan_bindings');
grant select, insert on ontology.plan_bindings to silo_app;
grant select on ontology.plan_bindings to silo_report;

-- ============================================================================
-- Domain: clone, workspace
-- ============================================================================

-- Clones and workspace: schemas clone and workspace (spec chapters 28 to 37).
-- Design: docs/siloDatabaseDesign.doc.md, "Clones and workspace", with review changes
-- D9, D14 to D17, R6 and R14. Keys into other domains (ontology, connect, siloes,
-- simulation, automation, action, recognition) are in clone_workspace_fks.sql.
-- clone.render_selections and workspace.ask_turns are range-partitioned by month;
-- their partitions come from platform.maintain_partitions().
--
-- Departures forced by the build-rule linter: workspace.workspace_preferences and
-- workspace.scope_sharing_policies have no id, so their primary keys lead with
-- organisation_id: (organisation_id, membership_id) and (organisation_id, scope_id).
-- A membership or scope belongs to one organisation, so each key is still unique on
-- its own.

-- ===========================================================================
-- Guards shared by both schemas
-- ===========================================================================

-- Supersede-only rows (clone layouts, terminology skins): never updated in place.
-- The one permitted update sets superseded_at, once.
create function clone.supersede_only() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
begin
  if old.superseded_at is not null or new.superseded_at is null
     or (to_jsonb(new) - 'superseded_at') is distinct from (to_jsonb(old) - 'superseded_at') then
    raise exception '%.% rows are superseded, never updated: only superseded_at may be set, once',
      tg_table_schema, tg_table_name using errcode = 'insufficient_privilege';
  end if;
  return new;
end
$$;

-- Allow-list guard. Trigger arguments name the only columns an update may change.
create function clone.only_columns_change() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
begin
  if (to_jsonb(new) - tg_argv) is distinct from (to_jsonb(old) - tg_argv) then
    raise exception '%.%: only % may change', tg_table_schema, tg_table_name, array_to_string(tg_argv, ', ')
      using errcode = 'insufficient_privilege';
  end if;
  return new;
end
$$;

-- Transfer flags are resolved once and never deleted: the one permitted update sets
-- reviewed_at and decision on an unresolved flag.
create function workspace.resolve_once() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
begin
  if old.reviewed_at is not null
     or (to_jsonb(new) - array['reviewed_at', 'decision'])
        is distinct from (to_jsonb(old) - array['reviewed_at', 'decision']) then
    raise exception '%.% rows are resolved once: only reviewed_at and decision may be set',
      tg_table_schema, tg_table_name using errcode = 'insufficient_privilege';
  end if;
  return new;
end
$$;

-- ===========================================================================
-- Schema clone
-- ===========================================================================

-- ---------------------------------------------------------------------------
-- clone.clone_layouts
create table clone.clone_layouts (
  id                       uuid primary key,
  organisation_id          uuid not null references iam.organisations (id),
  object_type_id           uuid not null,
  geo_property_id          uuid,
  crs                      text check (crs ~ '^EPSG:[0-9]+$'),
  containment_link_type_id uuid,
  stage_property_id        uuid,
  time_property_id         uuid,
  lane_property_id         uuid,
  label_property_id        uuid not null,
  ontology_version         bigint not null,
  created_by               uuid not null,
  created_at               timestamptz not null default now(),
  superseded_at            timestamptz,
  unique (organisation_id, id),
  foreign key (organisation_id, created_by) references iam.memberships (organisation_id, id),
  check ((crs is null) = (geo_property_id is null))
);
comment on table clone.clone_layouts is
  'Per object type, the properties that drive each canvas layout. Superseded by a new row, never updated.';
comment on column clone.clone_layouts.ontology_version is 'Ontology version validated against. A counter, no foreign key.';
create unique index clone_layouts_live on clone.clone_layouts (organisation_id, object_type_id)
  where superseded_at is null;
create index clone_layouts_geo_property on clone.clone_layouts (organisation_id, geo_property_id)
  where geo_property_id is not null;
create index clone_layouts_stage_property on clone.clone_layouts (organisation_id, stage_property_id)
  where stage_property_id is not null;
create index clone_layouts_time_property on clone.clone_layouts (organisation_id, time_property_id)
  where time_property_id is not null;
create index clone_layouts_lane_property on clone.clone_layouts (organisation_id, lane_property_id)
  where lane_property_id is not null;
create index clone_layouts_label_property on clone.clone_layouts (organisation_id, label_property_id);
create index clone_layouts_containment_link_type on clone.clone_layouts (organisation_id, containment_link_type_id)
  where containment_link_type_id is not null;
create index clone_layouts_created_by on clone.clone_layouts (organisation_id, created_by);
select platform.enable_tenant_rls('clone.clone_layouts');
create trigger clone_layouts_supersede_only before update on clone.clone_layouts
  for each row execute function clone.supersede_only();

grant select, insert, update (superseded_at) on clone.clone_layouts to silo_app;
grant select on clone.clone_layouts to silo_report;

-- ---------------------------------------------------------------------------
-- clone.state_rules
create table clone.state_rules (
  id                               uuid primary key,
  organisation_id                  uuid not null references iam.organisations (id),
  object_type_id                   uuid not null,
  version                          integer not null check (version >= 1),
  input_property_ids               uuid[] not null,
  rules                            jsonb not null check (jsonb_typeof(rules) = 'array'),
  compiled_hash                    text not null,
  freshness_window_seconds         integer not null default 900 check (freshness_window_seconds > 0),
  marking_ids                      uuid[] not null default '{}',
  proposed_by_membership_id        uuid,
  proposed_by_service_principal_id uuid,
  confirmed_by                     uuid,
  confirmed_at                     timestamptz,
  retired_at                       timestamptz,
  created_at                       timestamptz not null default now(),
  lock_version                     integer not null default 1,
  unique (organisation_id, id),
  unique (organisation_id, object_type_id, version),
  constraint state_rules_proposed_by_membership_fkey
    foreign key (organisation_id, proposed_by_membership_id) references iam.memberships (organisation_id, id),
  constraint state_rules_proposed_by_principal_fkey
    foreign key (organisation_id, proposed_by_service_principal_id) references iam.service_principals (organisation_id, id),
  foreign key (organisation_id, confirmed_by) references iam.memberships (organisation_id, id),
  check (num_nonnulls(proposed_by_membership_id, proposed_by_service_principal_id) = 1),
  check ((confirmed_by is null) = (confirmed_at is null))
);
comment on table clone.state_rules is
  'Versioned, ordered CEL rules deriving a clone''s display state. Unusable until confirmed by a person.';
comment on column clone.state_rules.rules is 'Ordered {state, CEL, reason} entries.';
comment on column clone.state_rules.compiled_hash is 'Shared by the state plane and the client.';
comment on column clone.state_rules.marking_ids is 'Computed from the inputs by the service, never supplied by the caller.';
create unique index state_rules_active on clone.state_rules (organisation_id, object_type_id)
  where confirmed_at is not null and retired_at is null;
create index state_rules_input_properties on clone.state_rules using gin (input_property_ids);
create index state_rules_proposed_by_principal on clone.state_rules (organisation_id, proposed_by_service_principal_id)
  where proposed_by_service_principal_id is not null;
create index state_rules_proposed_by_membership on clone.state_rules (organisation_id, proposed_by_membership_id)
  where proposed_by_membership_id is not null;
create index state_rules_confirmed_by on clone.state_rules (organisation_id, confirmed_by)
  where confirmed_by is not null;
create index state_rules_proposals on clone.state_rules (organisation_id, created_at desc)
  where confirmed_at is null and retired_at is null;
select platform.enable_tenant_rls('clone.state_rules');
create trigger state_rules_frozen before update on clone.state_rules
  for each row execute function platform.freeze_columns(
    'id', 'organisation_id', 'object_type_id', 'proposed_by_membership_id', 'proposed_by_service_principal_id');
-- Once confirmed, rules, inputs, hash and version are fixed; only retirement remains.
create trigger state_rules_confirmed_immutable before update on clone.state_rules
  for each row when (old.confirmed_at is not null)
  execute function clone.only_columns_change('retired_at', 'lock_version');

grant select, insert, update on clone.state_rules to silo_app;
grant select on clone.state_rules to silo_report;

-- ---------------------------------------------------------------------------
-- clone.staleness_thresholds
create table clone.staleness_thresholds (
  id                       uuid primary key,
  organisation_id          uuid not null references iam.organisations (id),
  connection_id            uuid not null,
  object_type_id           uuid,
  threshold_seconds        integer not null check (threshold_seconds > 0),
  manifest_cadence_seconds integer not null check (manifest_cadence_seconds > 0),
  set_by                   uuid not null,
  set_at                   timestamptz not null default now(),
  updated_at               timestamptz not null default now(),
  unique (organisation_id, id),
  foreign key (organisation_id, set_by) references iam.memberships (organisation_id, id)
);
comment on table clone.staleness_thresholds is
  'Maximum age before a source''s clones are stale, per connection and optionally per object type.';
comment on column clone.staleness_thresholds.object_type_id is 'Null: every type on the connection.';
comment on column clone.staleness_thresholds.manifest_cadence_seconds is 'Declared by the connector manifest.';
create unique index staleness_thresholds_connection on clone.staleness_thresholds (organisation_id, connection_id)
  where object_type_id is null;
create unique index staleness_thresholds_connection_type
  on clone.staleness_thresholds (organisation_id, connection_id, object_type_id)
  where object_type_id is not null;
create index staleness_thresholds_object_type on clone.staleness_thresholds (organisation_id, object_type_id)
  where object_type_id is not null;
create index staleness_thresholds_set_by on clone.staleness_thresholds (organisation_id, set_by);
select platform.add_updated_at_trigger('clone.staleness_thresholds');
select platform.enable_tenant_rls('clone.staleness_thresholds');
create trigger staleness_thresholds_frozen before update on clone.staleness_thresholds
  for each row execute function platform.freeze_columns('id', 'organisation_id', 'connection_id', 'object_type_id');

grant select, insert, update on clone.staleness_thresholds to silo_app;
grant select on clone.staleness_thresholds to silo_report;

-- ---------------------------------------------------------------------------
-- clone.spatial_plans
create table clone.spatial_plans (
  id                 uuid primary key,
  organisation_id    uuid not null references iam.organisations (id),
  silo_id            uuid not null,
  silo_file_id       uuid not null,
  raster_tileset_ref text not null,
  name               text not null check (length(btrim(name)) > 0),
  width_px           integer not null check (width_px > 0),
  height_px          integer not null check (height_px > 0),
  control_points     jsonb,
  marking_ids        uuid[] not null,
  uploaded_by        uuid not null,
  uploaded_at        timestamptz not null default now(),
  purged_at          timestamptz,
  unique (organisation_id, id),
  foreign key (organisation_id, uploaded_by) references iam.memberships (organisation_id, id)
);
comment on table clone.spatial_plans is
  'An uploaded floor or site plan held in a Silo, rasterised for the canvas. Purge keeps the row.';
comment on column clone.spatial_plans.raster_tileset_ref is 'Storage key inside the Silo.';
comment on column clone.spatial_plans.control_points is 'Georeferencing pairs.';
comment on column clone.spatial_plans.marking_ids is 'At least the Silo''s markings; the service enforces the superset.';
create index spatial_plans_by_silo on clone.spatial_plans (organisation_id, silo_id) where purged_at is null;
-- Leads with the file id (the design's lookup) and carries silo_id to cover the
-- composite key to siloes.silo_files.
create index spatial_plans_silo_file on clone.spatial_plans (organisation_id, silo_file_id, silo_id);
create index spatial_plans_uploaded_by on clone.spatial_plans (organisation_id, uploaded_by);
create index spatial_plans_picker on clone.spatial_plans (organisation_id, uploaded_at desc) where purged_at is null;
select platform.enable_tenant_rls('clone.spatial_plans');
create trigger spatial_plans_frozen before update on clone.spatial_plans
  for each row execute function platform.freeze_columns(
    'id', 'organisation_id', 'silo_id', 'silo_file_id', 'uploaded_by', 'uploaded_at');

grant select, insert, update on clone.spatial_plans to silo_app;
grant select on clone.spatial_plans to silo_report;

-- ---------------------------------------------------------------------------
-- clone.asset_models
create table clone.asset_models (
  id                uuid primary key,
  organisation_id   uuid not null references iam.organisations (id),
  silo_id           uuid not null,
  silo_file_id      uuid not null,
  name              text not null check (length(btrim(name)) > 0),
  format            text not null default 'gltf2_glb' check (format in ('gltf2_glb')),
  bytes             bigint not null check (bytes > 0),
  lod_refs          text[] not null default '{}',
  validation_report jsonb not null,
  node_names        text[] not null default '{}',
  marking_ids       uuid[] not null,
  uploaded_by       uuid not null,
  uploaded_at       timestamptz not null default now(),
  purged_at         timestamptz,
  unique (organisation_id, id),
  foreign key (organisation_id, uploaded_by) references iam.memberships (organisation_id, id)
);
comment on table clone.asset_models is
  'An uploaded glTF 2.0 binary model held in a Silo. A rejected model is never inserted.';
comment on column clone.asset_models.lod_refs is 'Level-of-detail storage keys inside the Silo.';
comment on column clone.asset_models.validation_report is 'Validator result and stripped extensions. No geometry.';
create index asset_models_by_silo on clone.asset_models (organisation_id, silo_id) where purged_at is null;
create index asset_models_silo_file on clone.asset_models (organisation_id, silo_file_id, silo_id);
create index asset_models_uploaded_by on clone.asset_models (organisation_id, uploaded_by);
select platform.enable_tenant_rls('clone.asset_models');
create trigger asset_models_frozen before update on clone.asset_models
  for each row execute function platform.freeze_columns(
    'id', 'organisation_id', 'silo_id', 'silo_file_id', 'uploaded_by', 'uploaded_at');

grant select, insert, update on clone.asset_models to silo_app;
grant select on clone.asset_models to silo_report;

-- ---------------------------------------------------------------------------
-- clone.canvas_views
create table clone.canvas_views (
  id                             uuid primary key,
  organisation_id                uuid not null references iam.organisations (id),
  owner_membership_id            uuid not null,
  name                           text not null check (length(btrim(name)) > 0),
  canvas_scope                   text not null check (canvas_scope in ('object', 'set', 'estate_ontology', 'estate_map')),
  object_set_ref                 uuid,
  layout_kind                    text not null check (layout_kind in ('schematic', 'graph_force', 'graph_layered',
                                                                      'spatial_map', 'spatial_3d', 'hierarchy',
                                                                      'timeline', 'list')),
  plan_id                        uuid,
  asset_model_id                 uuid,
  camera                         jsonb not null default '{}' check (jsonb_typeof(camera) = 'object'),
  layers                         jsonb not null default '{}' check (jsonb_typeof(layers) = 'object'),
  focus                          jsonb not null default '{}' check (jsonb_typeof(focus) = 'object'),
  state_filter                   text[] not null default '{}',
  pinned_object_refs             uuid[] not null default '{}' check (cardinality(pinned_object_refs) <= 200),
  scenario_id                    uuid,
  favourited                     boolean not null default false,
  ontology_version               bigint not null,
  created_at                     timestamptz not null default now(),
  updated_at                     timestamptz not null default now(),
  deleted_at                     timestamptz,
  archived_at                    timestamptz,
  transferred_from_membership_id uuid,
  transferred_at                 timestamptz,
  visibility                     text not null default 'private' check (visibility in ('private', 'shared', 'org_visible')),
  lock_version                   integer not null default 1,
  unique (organisation_id, id),
  foreign key (organisation_id, owner_membership_id) references iam.memberships (organisation_id, id),
  constraint canvas_views_transferred_from_fkey
    foreign key (organisation_id, transferred_from_membership_id) references iam.memberships (organisation_id, id),
  foreign key (organisation_id, plan_id) references clone.spatial_plans (organisation_id, id),
  foreign key (organisation_id, asset_model_id) references clone.asset_models (organisation_id, id),
  check ((object_set_ref is not null) = (canvas_scope in ('object', 'set'))),
  check (plan_id is null or layout_kind = 'spatial_map'),
  check (asset_model_id is null or layout_kind = 'spatial_3d'),
  check ((transferred_from_membership_id is null) = (transferred_at is null))
);
comment on table clone.canvas_views is
  'A saved Clone Canvas configuration owned by one membership. Shared through workspace.view_shares.';
comment on column clone.canvas_views.scenario_id is 'Scenario overlay.';
comment on column clone.canvas_views.favourited is
  'Promotes the view to the dashboard; kept in step with workspace.dashboard_tiles in one transaction.';
comment on column clone.canvas_views.ontology_version is 'Ontology version at save. A counter, no foreign key.';
create index canvas_views_mine on clone.canvas_views (organisation_id, owner_membership_id, updated_at desc)
  where deleted_at is null and archived_at is null;
create index canvas_views_object_set on clone.canvas_views (organisation_id, object_set_ref)
  where object_set_ref is not null;
create index canvas_views_plan on clone.canvas_views (organisation_id, plan_id) where plan_id is not null;
create index canvas_views_asset_model on clone.canvas_views (organisation_id, asset_model_id)
  where asset_model_id is not null;
create index canvas_views_scenario on clone.canvas_views (organisation_id, scenario_id) where scenario_id is not null;
create index canvas_views_favourited on clone.canvas_views (organisation_id, owner_membership_id)
  where favourited and deleted_at is null;
create index canvas_views_transferred_from on clone.canvas_views (organisation_id, transferred_from_membership_id)
  where transferred_from_membership_id is not null;
select platform.add_updated_at_trigger('clone.canvas_views');
select platform.enable_tenant_rls('clone.canvas_views');
create trigger canvas_views_frozen before update on clone.canvas_views
  for each row execute function platform.freeze_columns('id', 'organisation_id');

grant select, insert, update on clone.canvas_views to silo_app;
grant select on clone.canvas_views to silo_report;

-- ---------------------------------------------------------------------------
-- clone.spatial_anchors
create table clone.spatial_anchors (
  id              uuid primary key,
  organisation_id uuid not null references iam.organisations (id),
  plan_id         uuid,
  asset_model_id  uuid,
  object_type_id  uuid not null,
  object_ref      uuid,
  match_rule      text,
  plan_x          numeric,
  plan_y          numeric,
  model_node_name text,
  created_by      uuid not null,
  created_at      timestamptz not null default now(),
  removed_at      timestamptz,
  unique (organisation_id, id),
  foreign key (organisation_id, plan_id) references clone.spatial_plans (organisation_id, id),
  foreign key (organisation_id, asset_model_id) references clone.asset_models (organisation_id, id),
  foreign key (organisation_id, created_by) references iam.memberships (organisation_id, id),
  check (num_nonnulls(plan_id, asset_model_id) = 1),
  check (num_nonnulls(object_ref, match_rule) = 1),
  check ((plan_x is null) = (plan_y is null)),
  check (plan_x is null or plan_id is not null),
  check (model_node_name is null or asset_model_id is not null),
  check (num_nonnulls(plan_x, model_node_name) = 1)
);
comment on table clone.spatial_anchors is
  'Places one object, or every object matching a rule, on a plan (pixels) or a model node.';
comment on column clone.spatial_anchors.object_ref is 'Object in its source system. A reference, no foreign key.';
comment on column clone.spatial_anchors.match_rule is 'CEL predicate written by a person: configuration, not a record value.';
create index spatial_anchors_plan on clone.spatial_anchors (organisation_id, plan_id)
  where removed_at is null and plan_id is not null;
create index spatial_anchors_asset_model on clone.spatial_anchors (organisation_id, asset_model_id)
  where removed_at is null and asset_model_id is not null;
create index spatial_anchors_object on clone.spatial_anchors (organisation_id, object_type_id, object_ref)
  where removed_at is null and object_ref is not null;
create index spatial_anchors_created_by on clone.spatial_anchors (organisation_id, created_by);
select platform.enable_tenant_rls('clone.spatial_anchors');
create trigger spatial_anchors_frozen before update on clone.spatial_anchors
  for each row execute function platform.freeze_columns(
    'id', 'organisation_id', 'plan_id', 'asset_model_id', 'object_type_id', 'created_by');

grant select, insert, update on clone.spatial_anchors to silo_app;
grant select on clone.spatial_anchors to silo_report;

-- ---------------------------------------------------------------------------
-- clone.live_subscriptions: ephemeral. Ended rows are swept after 7 days by
-- silo_migrate (design decision 5); nothing references them.
create table clone.live_subscriptions (
  id                uuid primary key,
  organisation_id   uuid not null references iam.organisations (id),
  holder_kind       text not null check (holder_kind in ('session', 'cron')),
  membership_id     uuid,
  session_id        uuid,
  cron_id           uuid,
  object_set_ref    uuid not null,
  property_ids      uuid[] not null,
  projection_hash   text not null,
  object_count      integer not null check (object_count >= 0),
  connection_ids    uuid[] not null,
  state_plane_node  text not null,
  created_at        timestamptz not null default now(),
  last_heartbeat_at timestamptz not null default now(),
  ended_at          timestamptz,
  end_reason        text check (end_reason in ('closed', 'expired', 'revoked', 'bound')),
  unique (organisation_id, id),
  foreign key (organisation_id, membership_id) references iam.memberships (organisation_id, id),
  foreign key (organisation_id, session_id) references iam.sessions (organisation_id, id),
  check (num_nonnulls(session_id, cron_id) = 1),
  check (holder_kind <> 'session' or (session_id is not null and membership_id is not null and cron_id is null)),
  check (holder_kind <> 'cron' or (cron_id is not null and session_id is null)),
  check ((end_reason is null) = (ended_at is null))
);
comment on table clone.live_subscriptions is
  'Metadata of a live subscription, so a lost state-plane node can be rebuilt and bounds counted. Never values.';
comment on column clone.live_subscriptions.property_ids is 'Watched properties and rule inputs.';
comment on column clone.live_subscriptions.projection_hash is 'Hash of the effective field projection. No values.';
comment on column clone.live_subscriptions.connection_ids is 'Sources serving the set.';
create index live_subscriptions_by_node on clone.live_subscriptions (organisation_id, state_plane_node)
  where ended_at is null;
create index live_subscriptions_by_membership on clone.live_subscriptions (organisation_id, membership_id)
  include (object_count) where ended_at is null;
create index live_subscriptions_org_bound on clone.live_subscriptions (organisation_id)
  include (object_count) where ended_at is null;
create index live_subscriptions_by_cron on clone.live_subscriptions (organisation_id, cron_id)
  where cron_id is not null and ended_at is null;
create index live_subscriptions_by_object_set on clone.live_subscriptions (organisation_id, object_set_ref)
  where ended_at is null;
create index live_subscriptions_session on clone.live_subscriptions (organisation_id, session_id)
  where session_id is not null;
create index live_subscriptions_connections on clone.live_subscriptions using gin (connection_ids)
  where ended_at is null;
-- Cross-tenant sweeps by silo_migrate: deliberately no organisation_id lead.
create index live_subscriptions_heartbeat on clone.live_subscriptions (last_heartbeat_at) where ended_at is null;
create index live_subscriptions_ended on clone.live_subscriptions (ended_at) where ended_at is not null;
select platform.enable_tenant_rls('clone.live_subscriptions');
create trigger live_subscriptions_frozen before update on clone.live_subscriptions
  for each row execute function platform.freeze_columns(
    'id', 'organisation_id', 'holder_kind', 'membership_id', 'session_id', 'cron_id');

grant select, insert, update on clone.live_subscriptions to silo_app;
grant select on clone.live_subscriptions to silo_report;

-- ---------------------------------------------------------------------------
-- clone.layout_precomputations: ephemeral. Expired rows are swept by silo_migrate
-- (design decision 5).
create table clone.layout_precomputations (
  id                  uuid primary key,
  organisation_id     uuid not null references iam.organisations (id),
  object_set_ref      uuid not null,
  set_definition_hash text not null,
  ontology_version    bigint not null,
  layout_kind         text not null check (layout_kind in ('schematic', 'graph_force', 'graph_layered',
                                                           'spatial_map', 'spatial_3d', 'hierarchy',
                                                           'timeline', 'list')),
  parameters          jsonb not null default '{}' check (jsonb_typeof(parameters) = 'object'),
  node_count          integer not null check (node_count >= 0),
  cache_key           text not null,
  computed_at         timestamptz not null default now(),
  expires_at          timestamptz not null,
  unique (organisation_id, id),
  unique (organisation_id, cache_key),
  check (expires_at > computed_at)
);
comment on table clone.layout_precomputations is
  'Records that a layout for an object set was precomputed and where its positions live in the state plane.';
comment on column clone.layout_precomputations.cache_key is 'State plane key. Positions are never stored here.';
create index layout_precomputations_lookup
  on clone.layout_precomputations (organisation_id, set_definition_hash, layout_kind, ontology_version);
create index layout_precomputations_object_set on clone.layout_precomputations (organisation_id, object_set_ref);
create index layout_precomputations_expiry on clone.layout_precomputations (expires_at);
select platform.enable_tenant_rls('clone.layout_precomputations');
create trigger layout_precomputations_frozen before update on clone.layout_precomputations
  for each row execute function platform.freeze_columns('id', 'organisation_id');

grant select, insert, update on clone.layout_precomputations to silo_app;
grant select on clone.layout_precomputations to silo_report;

-- ---------------------------------------------------------------------------
-- clone.render_selections: append-only ledger, monthly partitions on recorded_at.
-- Retention is a partition drop.
create table clone.render_selections (
  id                   uuid not null,
  organisation_id      uuid not null references iam.organisations (id),
  result_ref           uuid not null,
  result_structure     jsonb not null check (jsonb_typeof(result_structure) = 'object'),
  surface              text not null check (surface in ('view', 'canvas')),
  chosen               text not null,
  alternatives_offered text[] not null default '{}',
  user_override        boolean not null default false,
  overridden_to        text,
  membership_id        uuid not null,
  recorded_at          timestamptz not null default now(),
  primary key (id, recorded_at),
  unique (organisation_id, id, recorded_at),
  foreign key (organisation_id, membership_id) references iam.memberships (organisation_id, id),
  check ((overridden_to is not null) = user_override)
) partition by range (recorded_at);
comment on table clone.render_selections is
  'Which archetype or layout was chosen for a result, what else was offered, and any override. Telemetry.';
comment on column clone.render_selections.result_ref is 'Data plane result id. No foreign key; never the result.';
comment on column clone.render_selections.result_structure is 'Selection signals: counts and booleans only.';
create index render_selections_time on clone.render_selections using brin (recorded_at);
create index render_selections_by_choice on clone.render_selections (organisation_id, surface, chosen, recorded_at);
create index render_selections_membership on clone.render_selections (organisation_id, membership_id);
select platform.enable_tenant_rls('clone.render_selections');
select platform.make_append_only('clone.render_selections');

grant select, insert on clone.render_selections to silo_app;
grant select on clone.render_selections to silo_report;

-- ---------------------------------------------------------------------------
-- clone.estate_snapshots: insert-only. Retention (proposed: daily snapshots kept
-- 13 months) is a receipted delete by silo_migrate.
create table clone.estate_snapshots (
  id               uuid primary key,
  organisation_id  uuid not null references iam.organisations (id),
  taken_at         timestamptz not null,
  node_counts      jsonb not null,
  edge_counts      jsonb not null,
  node_refs        jsonb not null,
  discovery_run_id uuid,
  created_at       timestamptz not null default now(),
  unique (organisation_id, id)
);
comment on table clone.estate_snapshots is
  'Daily and post-discovery counts and id references of the Estate map, for comparing two times.';
comment on column clone.estate_snapshots.node_counts is 'Per kind and health state.';
comment on column clone.estate_snapshots.node_refs is 'Ids present. No values.';
create unique index estate_snapshots_one_per_run on clone.estate_snapshots (organisation_id, discovery_run_id)
  where discovery_run_id is not null;
create index estate_snapshots_by_time on clone.estate_snapshots (organisation_id, taken_at desc);
select platform.enable_tenant_rls('clone.estate_snapshots');
select platform.make_append_only('clone.estate_snapshots', true);

grant select, insert on clone.estate_snapshots to silo_app;
grant select on clone.estate_snapshots to silo_report;

-- clone.view_preferences references workspace.saved_views and is created after it.

-- ===========================================================================
-- Schema workspace
-- ===========================================================================

-- ---------------------------------------------------------------------------
-- workspace.terminology_skins
create table workspace.terminology_skins (
  id              uuid primary key,
  organisation_id uuid not null references iam.organisations (id),
  object_type_id  uuid,
  link_type_id    uuid,
  action_type_id  uuid,
  state_value     text check (length(state_value) > 0),
  label_singular  text not null check (length(btrim(label_singular)) > 0),
  label_plural    text,
  set_by          uuid not null,
  set_at          timestamptz not null default now(),
  superseded_at   timestamptz,
  unique (organisation_id, id),
  foreign key (organisation_id, set_by) references iam.memberships (organisation_id, id),
  check (num_nonnulls(object_type_id, link_type_id, action_type_id) = 1),
  check (state_value is null or object_type_id is not null)
);
comment on table workspace.terminology_skins is
  'Per-organisation display labels for object types, link types, Action types and declared state values.';
comment on column workspace.terminology_skins.state_value is
  'A declared enumeration value of the object type, not a record value.';
-- One live label per element. nulls not distinct stands in for coalesce(state_value, '')
-- (state_value is never empty), so the index also serves the object type key.
create unique index terminology_skins_object_type
  on workspace.terminology_skins (organisation_id, object_type_id, state_value) nulls not distinct
  where superseded_at is null and object_type_id is not null;
create unique index terminology_skins_link_type on workspace.terminology_skins (organisation_id, link_type_id)
  where superseded_at is null and link_type_id is not null;
create unique index terminology_skins_action_type on workspace.terminology_skins (organisation_id, action_type_id)
  where superseded_at is null and action_type_id is not null;
create index terminology_skins_set_by on workspace.terminology_skins (organisation_id, set_by);
create index terminology_skins_live on workspace.terminology_skins (organisation_id) where superseded_at is null;
select platform.enable_tenant_rls('workspace.terminology_skins');
create trigger terminology_skins_supersede_only before update on workspace.terminology_skins
  for each row execute function clone.supersede_only();
-- Labels are cached per policy version, so a change must move the version.
select iam.attach_policy_bump('workspace.terminology_skins');

grant select, insert, update (superseded_at) on workspace.terminology_skins to silo_app;
grant select on workspace.terminology_skins to silo_report;

-- ---------------------------------------------------------------------------
-- workspace.workspace_preferences
create table workspace.workspace_preferences (
  membership_id     uuid not null,
  organisation_id   uuid not null references iam.organisations (id),
  rail_collapsed    boolean not null default false,
  ask_panel_open    boolean not null default false,
  last_home_seen_at timestamptz,
  updated_at        timestamptz not null default now(),
  primary key (organisation_id, membership_id),
  foreign key (organisation_id, membership_id) references iam.memberships (organisation_id, id)
);
comment on table workspace.workspace_preferences is
  'Per-person shell state and the "since last visit" marker for Home.';
comment on column workspace.workspace_preferences.last_home_seen_at is
  'Advanced only when the briefing is rendered, so the next briefing starts after what was shown.';
select platform.add_updated_at_trigger('workspace.workspace_preferences');
select platform.enable_tenant_rls('workspace.workspace_preferences');
create trigger workspace_preferences_frozen before update on workspace.workspace_preferences
  for each row execute function platform.freeze_columns('organisation_id', 'membership_id');

grant select, insert, update on workspace.workspace_preferences to silo_app;
grant select on workspace.workspace_preferences to silo_report;

-- ---------------------------------------------------------------------------
-- workspace.apps
create table workspace.apps (
  id                             uuid primary key,
  organisation_id                uuid not null references iam.organisations (id),
  owner_membership_id            uuid not null,
  name                           text not null check (length(btrim(name)) > 0),
  description                    text,
  kind                           text not null check (kind in ('app', 'object_view_layout')),
  visibility                     text not null default 'private' check (visibility in ('private', 'shared', 'published')),
  current_version_id             uuid,
  generated_by                   text check (generated_by in ('ai_fde')),
  require_full_clearance         boolean not null default false,
  created_at                     timestamptz not null default now(),
  updated_at                     timestamptz not null default now(),
  archived_at                    timestamptz,
  transferred_from_membership_id uuid,
  transferred_at                 timestamptz,
  lock_version                   integer not null default 1,
  unique (organisation_id, id),
  foreign key (organisation_id, owner_membership_id) references iam.memberships (organisation_id, id),
  constraint apps_transferred_from_fkey
    foreign key (organisation_id, transferred_from_membership_id) references iam.memberships (organisation_id, id),
