-- workspace.app_versions
create table workspace.app_versions (
  id                       uuid primary key,
  organisation_id          uuid not null references iam.organisations (id),
  app_id                   uuid not null,
  version                  integer not null check (version >= 1),
  state                    text not null check (state in ('draft', 'review', 'published', 'returned', 'superseded')),
  definition               jsonb not null,
  schema_version           text not null,
  ontology_version         bigint not null,
  markings                 uuid[] not null default '{}',
  validation_findings      jsonb not null default '[]' check (jsonb_typeof(validation_findings) = 'array'),
  invalidated_at_ontology_version bigint,
  rolled_back_from_version integer,
  -- A branch's draft (D229); null on main.
  branch_id                uuid,
  authored_by              uuid not null,
  reviewed_by              uuid,
  created_at               timestamptz not null default now(),
  reviewed_at              timestamptz,
  published_at             timestamptz,
  lock_version             integer not null default 1,
  unique (organisation_id, id),
  unique (organisation_id, app_id, version),
  foreign key (organisation_id, app_id) references workspace.apps (organisation_id, id),
  foreign key (organisation_id, authored_by) references iam.memberships (organisation_id, id),
  foreign key (organisation_id, reviewed_by) references iam.memberships (organisation_id, id),
  check (reviewed_by is null or reviewed_by <> authored_by),
  check (rolled_back_from_version is null or rolled_back_from_version between 1 and version - 1),
  check (branch_id is null or state = 'draft')
);
comment on table workspace.app_versions is
  'A version of an app definition, immutable once out of draft, with validation, markings and review state.';
comment on column workspace.app_versions.markings is
  'Union of the markings on referenced elements, computed from workspace.app_references.';
comment on column workspace.app_versions.validation_findings is 'Empty for a publishable version.';
create index app_versions_review_queue on workspace.app_versions (organisation_id, created_at) where state = 'review';
create index app_versions_authored_by on workspace.app_versions (organisation_id, authored_by);
