  where reviewed_by is not null;
select platform.enable_tenant_rls('workspace.app_versions');
create trigger app_versions_frozen before update on workspace.app_versions
  for each row execute function platform.freeze_columns(
    'id', 'organisation_id', 'app_id', 'version', 'branch_id', 'authored_by', 'created_at');
create trigger app_versions_definition_frozen before update on workspace.app_versions
  for each row when (old.state <> 'draft')
  execute function platform.freeze_columns('definition', 'schema_version', 'ontology_version', 'markings');

-- Lifecycle (spec 35.7): draft -> review -> published -> superseded, or review ->
-- returned. Review freezes the candidate; a returned version stays returned and the
-- author continues in a new draft.
create function workspace.app_versions_lifecycle() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
begin
  if new.state is distinct from old.state
     and (old.state, new.state) not in (('draft', 'review'), ('review', 'published'),
                                        ('review', 'returned'), ('published', 'superseded')) then
    raise exception 'app version cannot move from % to %', old.state, new.state
      using errcode = 'check_violation';
  end if;
  return new;
end
$$;
create trigger app_versions_lifecycle before update of state on workspace.app_versions
  for each row execute function workspace.app_versions_lifecycle();
comment on column workspace.app_versions.invalidated_at_ontology_version is
  'The ontology version at which an open last found widgets of this version invalid: app_invalidated_by_ontology_change is raised once per version and ontology version (35.13).';

