-- Rows of a version past draft are immutable. The version row is share-locked so it
-- cannot leave draft while its references are being written.
create function workspace.app_references_draft_only() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
declare
  v_state text;
begin
  select v.state into v_state
  from workspace.app_versions v
  where v.organisation_id = new.organisation_id and v.id = new.app_version_id
  for share;
  if v_state is not null and v_state <> 'draft' then
    raise exception 'references of app version % are immutable once it leaves draft', new.app_version_id
      using errcode = 'insufficient_privilege';
  end if;
  return new;
end
$$;
create trigger app_references_draft_only before insert or update on workspace.app_references
  for each row execute function workspace.app_references_draft_only();

