  created_at      timestamptz not null default now(),
  unique (organisation_id, id),
  unique (organisation_id, membership_id, resource_type, resource_id),
  foreign key (organisation_id, membership_id) references iam.memberships (organisation_id, id)
);
comment on table workspace.follows is
  'A person''s choice to follow another''s Cron or object-set view, for Home''s briefing. Grants nothing.';
comment on column workspace.follows.resource_id is 'The Cron or saved view. A reference: either may be deleted, which ends the follow.';
create index follows_resource on workspace.follows (organisation_id, resource_type, resource_id);
