-- ---------------------------------------------------------------------------
-- workspace.ask_turns: monthly partitions on created_at. Not append-only: the
-- retention job (silo_migrate, receipted) nulls question. Partitions are dropped only
-- past the longest allowed retention plus the audit horizon (chapter 70).
create table workspace.ask_turns (
  id                    uuid not null,
  organisation_id       uuid not null references iam.organisations (id),
  thread_id             uuid not null,
  sequence              integer not null check (sequence >= 1),
  question              bytea,
  question_purged_at    timestamptz,
  -- Outside context (36.7; D84): the web query sent (the question's wording only), when, and
  -- each result's title, URL and snippet, or that it was unavailable. Web content, never a
  -- record value; never written into a saved result, an export or an Action parameter.
  outside_context       jsonb,
  outcome               text not null check (outcome in ('answer', 'refusal', 'clarification', 'proposal')),
  manifest_id           uuid,
  refusal_reason        text check (refusal_reason in ('no_plan', 'bound_exceeded', 'capability_missing',
                                                       'unsupported', 'daily_limit')),
  clarification_options jsonb,
  -- A proposal (42.9): how the change would be made, as references (the Action types that fit,
  -- or the generic edit; the object type, operation and property names). Never the values.
  proposal              jsonb,
  -- An explanation or navigation tool's subject (36.4): a turn, property, object, Clone Canvas or finding, by reference.
  subject               jsonb,
  -- A failure scenario Ask started (36.4, 39.4): a reference; the scenario keeps its own lifecycle.
  scenario_id           uuid,
  result_ref            text,
  tool                  text not null,
  tokens_charged        integer not null default 0 check (tokens_charged >= 0),
  created_at            timestamptz not null default now(),
  primary key (id, created_at),
  unique (organisation_id, id, created_at),
  -- Per-partition backstop; global uniqueness comes from ask_threads.last_sequence.
  -- Also serves loading a thread in order, so no separate (organisation_id,
  -- thread_id, sequence) index is created.
  unique (organisation_id, thread_id, sequence, created_at),
  foreign key (organisation_id, thread_id) references workspace.ask_threads (organisation_id, id),
  check ((question is null) = (question_purged_at is not null)),
  check ((refusal_reason is not null) = (outcome = 'refusal')),
  check ((clarification_options is not null) = (outcome = 'clarification')),
  check ((proposal is not null) = (outcome = 'proposal')),
  check ((subject is not null) = (tool in ('explain_finding', 'explain_lineage', 'open_clone', 'start_scenario'))),
  check (scenario_id is null or (tool = 'start_scenario' and outcome = 'answer')),
  check (outcome in ('answer', 'proposal') or tokens_charged = 0)
) partition by range (created_at);
comment on table workspace.ask_turns is
  'One Ask question and its outcome. Holds the encrypted question and references, never result rows.';
comment on column workspace.ask_turns.question is
  'Record value: AES-256-GCM under the organisation data key. Never indexed or logged. Null once purged.';
comment on column workspace.ask_turns.clarification_options is 'Vocabulary references offered.';
comment on column workspace.ask_turns.result_ref is 'Data plane key; expires with its TTL.';
comment on column workspace.ask_turns.tool is 'The Ask tool used (spec 36.4).';
create index ask_turns_time on workspace.ask_turns using brin (created_at);
create index ask_turns_purge_candidates on workspace.ask_turns (organisation_id, created_at)
  where question is not null;
create index ask_turns_manifest on workspace.ask_turns (organisation_id, manifest_id) where manifest_id is not null;
select platform.enable_tenant_rls('workspace.ask_turns');

-- Update is permitted only to purge the question: question to null and
-- question_purged_at set, nothing else changed.
create function workspace.ask_turns_purge_only() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
begin
  if old.question is null or new.question is not null or new.question_purged_at is null
     or (to_jsonb(new) - array['question', 'question_purged_at'])
        is distinct from (to_jsonb(old) - array['question', 'question_purged_at']) then
    raise exception 'workspace.ask_turns is updated only to purge the question'
      using errcode = 'insufficient_privilege';
  end if;
  return new;
end
$$;
create trigger ask_turns_purge_only before update on workspace.ask_turns
  for each row execute function workspace.ask_turns_purge_only();

-- The purge runs as silo_migrate; services insert and read.
grant select, insert on workspace.ask_turns to silo_app;
grant select (id, organisation_id, thread_id, sequence, question_purged_at, outcome, manifest_id,
              refusal_reason, clarification_options, result_ref, tool, tokens_charged, created_at)
  on workspace.ask_turns to silo_report;

