-- workspace.ml_model_versions
create table workspace.ml_model_versions (
  id                   uuid primary key,
  organisation_id      uuid not null references iam.organisations (id),
  model_id             uuid not null,
  version              integer not null check (version >= 1),
  status               text not null check (status in ('trained', 'failed')),
  task                 text not null check (task in ('regression', 'classification')),
  object_set_id        uuid not null,
  feature_property_ids uuid[] not null,
  label_property_id    uuid not null,
  rows_trained         integer check (rows_trained >= 0),
  rows_tested          integer check (rows_tested >= 0),
  -- Headline figures only (error, fit, accuracy): never a value read.
  metrics              jsonb check (metrics is null or jsonb_typeof(metrics) = 'object'),
  -- The fitted model, its encoder (category values are record values), importance and full evaluation, sealed.
  artifact             bytea,
  marking_ids          uuid[] not null default '{}',
  failure              text check (failure is null or length(failure) <= 2000),
  trained_by           uuid not null,
  trained_at           timestamptz not null default now(),
  unique (organisation_id, id),
  unique (organisation_id, model_id, version),
  foreign key (organisation_id, model_id) references workspace.ml_models (organisation_id, id),
  foreign key (organisation_id, trained_by) references iam.memberships (organisation_id, id),
  check ((status = 'trained') = (artifact is not null)),
  check ((status = 'trained') = (metrics is not null)),
  check ((status = 'failed') = (failure is not null))
);
comment on table workspace.ml_model_versions is
  'A model trained (D240): what it learnt from, how it scored on the held-out fifth, and the fitted model sealed under the organisation''s data key. Never changed.';
comment on column workspace.ml_model_versions.artifact is
  'Sealed (record values: the categories it learnt): the encoder, the fitted weights, importance and the full evaluation. Opened only for someone holding every marking in marking_ids.';
comment on column workspace.ml_model_versions.marking_ids is 'The markings of what training read: whoever reads the model or predicts with it must hold them.';
create index ml_model_versions_trained_by on workspace.ml_model_versions (organisation_id, trained_by);
select platform.enable_tenant_rls('workspace.ml_model_versions');
select platform.make_append_only('workspace.ml_model_versions');

