-- workspace.notebooks
create table workspace.notebooks (
  id                  uuid primary key,
  organisation_id     uuid not null references iam.organisations (id),
  owner_membership_id uuid not null,
  name                text not null check (length(btrim(name)) between 1 and 200),
  document            jsonb not null check (jsonb_typeof(document) = 'object'),
  visibility          text not null default 'private' check (visibility in ('private', 'shared', 'org_visible')),
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),
  archived_at         timestamptz,
  lock_version        integer not null default 1,
  unique (organisation_id, id),
  foreign key (organisation_id, owner_membership_id) references iam.memberships (organisation_id, id)
);
comment on table workspace.notebooks is
  'A notebook (D239): cells of objects, compiled questions, transforms, statistics and charts, run for whoever opens it. Nothing read is stored.';
comment on column workspace.notebooks.document is
  'Its cells: text a person wrote, saved object sets and properties, compiled plans with the bindings of their values (sealed by compile; never the question), steps, and what to summarise or draw.';
create index notebooks_mine on workspace.notebooks (organisation_id, owner_membership_id, updated_at desc) where archived_at is null;
create index notebooks_name_search on workspace.notebooks using gin (name gin_trgm_ops);
select platform.add_updated_at_trigger('workspace.notebooks');
select platform.enable_tenant_rls('workspace.notebooks');
create trigger notebooks_frozen before update on workspace.notebooks
  for each row execute function platform.freeze_columns('id', 'organisation_id', 'owner_membership_id', 'created_at');

