-- ---------------------------------------------------------------------------
-- workspace.pipeline_runs
create table workspace.pipeline_runs (
  id              uuid primary key,
  organisation_id uuid not null references iam.organisations (id),
  pipeline_id     uuid not null,
  status          text not null check (status in ('running', 'completed', 'failed')),
  rows            integer check (rows is null or rows >= 0),
  silo_file_id    uuid,
  failure         text check (failure is null or length(failure) <= 2000),
  -- Who started it: a person, or its schedule's service principal (D241).
  started_by      uuid,
  started_by_principal uuid,
  started_at      timestamptz not null default now(),
  finished_at     timestamptz,
  unique (organisation_id, id),
  foreign key (organisation_id, pipeline_id) references workspace.pipelines (organisation_id, id),
  foreign key (organisation_id, started_by) references iam.memberships (organisation_id, id),
  foreign key (organisation_id, started_by_principal) references iam.service_principals (organisation_id, id),
  check (num_nonnulls(started_by, started_by_principal) = 1),
  check ((status = 'running') = (finished_at is null)),
  check ((status = 'completed') = (silo_file_id is not null)),
  check ((status = 'failed') = (failure is not null))
);
comment on table workspace.pipeline_runs is 'A pipeline run (D235): what it wrote (rows, the Silo file) or why it failed. No values.';
comment on column workspace.pipeline_runs.silo_file_id is 'The Import Silo file the run wrote. A reference, no foreign key: the file may be purged with its Silo.';
create index pipeline_runs_pipeline on workspace.pipeline_runs (organisation_id, pipeline_id, started_at desc);
create index pipeline_runs_started_by on workspace.pipeline_runs (organisation_id, started_by) where started_by is not null;
create index pipeline_runs_started_by_principal on workspace.pipeline_runs (organisation_id, started_by_principal) where started_by_principal is not null;
select platform.enable_tenant_rls('workspace.pipeline_runs');
create trigger pipeline_runs_frozen before update on workspace.pipeline_runs
  for each row execute function platform.freeze_columns('id', 'organisation_id', 'pipeline_id', 'started_by', 'started_by_principal', 'started_at');

grant select, insert, update on workspace.pipeline_runs to silo_app;
grant select on workspace.pipeline_runs to silo_report;

-- ---------------------------------------------------------------------------
-- workspace.pipeline_schedules
create table workspace.pipeline_schedules (
  organisation_id      uuid not null references iam.organisations (id),
  pipeline_id          uuid not null,
  -- What its runs run as (kind automation, owned by the pipeline's owner): read access to the connections its
  -- inputs read and silo.import, each bounded by its owner at every run (policy, spec 60.4).
  service_principal_id uuid not null,
  -- Five fields, minute hour day-of-month month day-of-week, in the time zone.
  schedule             text not null check (length(btrim(schedule)) between 9 and 200),
  timezone             text not null,
  status               text not null default 'active' check (status in ('active', 'paused')),
  paused_reason        text check (paused_reason in ('failures', 'archived')),
  connection_ids       uuid[] not null default '{}',
  pause_after_failures integer not null default 3 check (pause_after_failures between 1 and 20),
  failures_in_a_row    integer not null default 0 check (failures_in_a_row >= 0),
  next_run_at          timestamptz,
  lease_expires_at     timestamptz,
  last_run_at          timestamptz,
  created_by           uuid not null,
  created_at           timestamptz not null default now(),
  updated_at           timestamptz not null default now(),
  primary key (organisation_id, pipeline_id),
  unique (organisation_id, service_principal_id),
  foreign key (organisation_id, pipeline_id) references workspace.pipelines (organisation_id, id),
  foreign key (organisation_id, service_principal_id) references iam.service_principals (organisation_id, id),
  foreign key (organisation_id, created_by) references iam.memberships (organisation_id, id),
  check ((status = 'paused') = (paused_reason is not null))
);
comment on table workspace.pipeline_schedules is
  'A pipeline run on a schedule (D241), as its own service principal, never exceeding its owner. Missed runs are not backfilled; it pauses after the failures it allows in a row.';
-- Cross-tenant due sweep, by the claim function.
create index pipeline_schedules_due on workspace.pipeline_schedules (next_run_at) where status = 'active' and next_run_at is not null;
create index pipeline_schedules_created_by on workspace.pipeline_schedules (organisation_id, created_by);
select platform.add_updated_at_trigger('workspace.pipeline_schedules');
select platform.enable_tenant_rls('workspace.pipeline_schedules');
create trigger pipeline_schedules_frozen before update on workspace.pipeline_schedules
  for each row execute function platform.freeze_columns('organisation_id', 'pipeline_id', 'service_principal_id', 'created_by', 'created_at');

grant select, insert, update, delete on workspace.pipeline_schedules to silo_app;
grant select on workspace.pipeline_schedules to silo_report;

-- The due sweep's claim across organisations (D241): identifiers only, each leased five minutes.
create function workspace.claim_due_pipeline_schedules(batch_size integer, now timestamptz)
returns table (organisation_id uuid, pipeline_id uuid, next_run_at timestamptz)
language plpgsql
security definer
set search_path = pg_catalog
as $$
#variable_conflict use_column
begin
  if claim_due_pipeline_schedules.batch_size is null or claim_due_pipeline_schedules.batch_size not between 1 and 1000 then
    raise exception 'batch_size must be between 1 and 1000' using errcode = 'invalid_parameter_value';
  end if;
  if claim_due_pipeline_schedules.now is null then
    raise exception 'now must be given' using errcode = 'invalid_parameter_value';
  end if;
  return query
  with due as (
    select s.organisation_id, s.pipeline_id
    from workspace.pipeline_schedules s
    where s.status = 'active' and s.next_run_at is not null and s.next_run_at <= claim_due_pipeline_schedules.now
      and (s.lease_expires_at is null or s.lease_expires_at <= claim_due_pipeline_schedules.now)
    order by s.next_run_at, s.pipeline_id
    limit claim_due_pipeline_schedules.batch_size
    for update of s skip locked
  )
  update workspace.pipeline_schedules s
     set lease_expires_at = claim_due_pipeline_schedules.now + interval '5 minutes'
    from due
   where s.organisation_id = due.organisation_id and s.pipeline_id = due.pipeline_id
  returning s.organisation_id, s.pipeline_id, s.next_run_at;
end
$$;
revoke all on function workspace.claim_due_pipeline_schedules(integer, timestamptz) from public;
grant execute on function workspace.claim_due_pipeline_schedules(integer, timestamptz) to silo_app;

-- ---------------------------------------------------------------------------
-- workspace.view_shares
create table workspace.view_shares (
  id                uuid primary key,
  organisation_id   uuid not null references iam.organisations (id),
  saved_view_id     uuid,
  canvas_view_id    uuid,
  scenario_id       uuid,
  automation_id     uuid,
  -- A workbook (D232): shared to open with live data (view) or to copy (copy).
  workbook_id       uuid,
  -- A report (D233): shared to open (view) or to copy (copy).
  report_id         uuid,
  -- A process analysis (D234): shared to open (view) or to copy (copy).
  process_analysis_id uuid,
  -- An AI agent (D236): shared to ask (view) or to copy (copy).
  ai_agent_id       uuid,
  -- A notebook (D239): shared to open (view) or to copy (copy).
  notebook_id       uuid,
  -- A machine learning model (D240): shared to see and predict with (view) only.
  ml_model_id       uuid,
  membership_id     uuid,
  scope_id          uuid,
  organisation_wide boolean,
  access            text not null check (access in ('view', 'run', 'copy')),
  shared_by         uuid not null,
  shared_at         timestamptz not null default now(),
  expires_at        timestamptz,
  revoked_at        timestamptz,
  suspended_at      timestamptz,
  unique (organisation_id, id),
  foreign key (organisation_id, saved_view_id) references workspace.saved_views (organisation_id, id),
  foreign key (organisation_id, canvas_view_id) references clone.canvas_views (organisation_id, id),
  foreign key (organisation_id, workbook_id) references workspace.workbooks (organisation_id, id),
  foreign key (organisation_id, report_id) references workspace.reports (organisation_id, id),
  foreign key (organisation_id, process_analysis_id) references workspace.process_analyses (organisation_id, id),
  foreign key (organisation_id, ai_agent_id) references workspace.ai_agents (organisation_id, id),
  foreign key (organisation_id, notebook_id) references workspace.notebooks (organisation_id, id),
  foreign key (organisation_id, ml_model_id) references workspace.ml_models (organisation_id, id),
  foreign key (organisation_id, membership_id) references iam.memberships (organisation_id, id),
  foreign key (organisation_id, scope_id) references iam.scopes (organisation_id, id),
  foreign key (organisation_id, shared_by) references iam.memberships (organisation_id, id),
  check (num_nonnulls(saved_view_id, canvas_view_id, scenario_id, automation_id, workbook_id, report_id, process_analysis_id, ai_agent_id, notebook_id, ml_model_id) = 1),
  check (process_analysis_id is null or access in ('view', 'copy')),
  check (ai_agent_id is null or access in ('view', 'copy')),
  check (notebook_id is null or access in ('view', 'copy')),
  check (ml_model_id is null or access = 'view'),
  check (workbook_id is null or access in ('view', 'copy')),
  check (report_id is null or access in ('view', 'copy')),
  check (num_nonnulls(membership_id, scope_id, organisation_wide) = 1),
  -- A Cron is shared for its visibility and run history, never its authorisation (spec 40.8).
  check (automation_id is null or access = 'view'),
  check (organisation_wide is null or organisation_wide)
);
comment on table workspace.view_shares is
  'A share of a saved view, canvas view, scenario or Cron with a membership, a scope or the organisation. Never deleted.';
comment on column workspace.view_shares.automation_id is
  'A Cron, shared for its visibility and run history only (spec 40.8): access is always view.';
comment on column workspace.view_shares.shared_by is 'Must be the current owner.';
comment on column workspace.view_shares.expires_at is
  'Access ends here regardless of the sweep: resolution tests expires_at > now().';
comment on column workspace.view_shares.suspended_at is 'Set while a transfer flag is unreviewed.';
-- One share per view and grantee (three view arms by three grantee arms).
create unique index view_shares_saved_view_membership on workspace.view_shares (organisation_id, saved_view_id, membership_id)
  where saved_view_id is not null and membership_id is not null;
create unique index view_shares_saved_view_scope on workspace.view_shares (organisation_id, saved_view_id, scope_id)
  where saved_view_id is not null and scope_id is not null;
create unique index view_shares_saved_view_organisation on workspace.view_shares (organisation_id, saved_view_id)
  where saved_view_id is not null and organisation_wide;
create unique index view_shares_canvas_view_membership on workspace.view_shares (organisation_id, canvas_view_id, membership_id)
  where canvas_view_id is not null and membership_id is not null;
create unique index view_shares_canvas_view_scope on workspace.view_shares (organisation_id, canvas_view_id, scope_id)
  where canvas_view_id is not null and scope_id is not null;
create unique index view_shares_canvas_view_organisation on workspace.view_shares (organisation_id, canvas_view_id)
  where canvas_view_id is not null and organisation_wide;
create unique index view_shares_scenario_membership on workspace.view_shares (organisation_id, scenario_id, membership_id)
  where scenario_id is not null and membership_id is not null;
create unique index view_shares_scenario_scope on workspace.view_shares (organisation_id, scenario_id, scope_id)
  where scenario_id is not null and scope_id is not null;
create unique index view_shares_scenario_organisation on workspace.view_shares (organisation_id, scenario_id)
  where scenario_id is not null and organisation_wide;
create unique index view_shares_automation_membership on workspace.view_shares (organisation_id, automation_id, membership_id)
  where automation_id is not null and membership_id is not null;
create unique index view_shares_automation_scope on workspace.view_shares (organisation_id, automation_id, scope_id)
  where automation_id is not null and scope_id is not null;
create unique index view_shares_automation_organisation on workspace.view_shares (organisation_id, automation_id)
  where automation_id is not null and organisation_wide;
create unique index view_shares_workbook_membership on workspace.view_shares (organisation_id, workbook_id, membership_id)
  where workbook_id is not null and membership_id is not null;
create unique index view_shares_workbook_scope on workspace.view_shares (organisation_id, workbook_id, scope_id)
  where workbook_id is not null and scope_id is not null;
create unique index view_shares_workbook_organisation on workspace.view_shares (organisation_id, workbook_id)
  where workbook_id is not null and organisation_wide;
create unique index view_shares_report_membership on workspace.view_shares (organisation_id, report_id, membership_id)
  where report_id is not null and membership_id is not null;
create unique index view_shares_report_scope on workspace.view_shares (organisation_id, report_id, scope_id)
  where report_id is not null and scope_id is not null;
create unique index view_shares_report_organisation on workspace.view_shares (organisation_id, report_id)
  where report_id is not null and organisation_wide;
create unique index view_shares_process_membership on workspace.view_shares (organisation_id, process_analysis_id, membership_id)
  where process_analysis_id is not null and membership_id is not null;
create unique index view_shares_process_scope on workspace.view_shares (organisation_id, process_analysis_id, scope_id)
  where process_analysis_id is not null and scope_id is not null;
create unique index view_shares_process_organisation on workspace.view_shares (organisation_id, process_analysis_id)
  where process_analysis_id is not null and organisation_wide;
create unique index view_shares_ai_agent_membership on workspace.view_shares (organisation_id, ai_agent_id, membership_id)
  where ai_agent_id is not null and membership_id is not null;
create unique index view_shares_ai_agent_scope on workspace.view_shares (organisation_id, ai_agent_id, scope_id)
  where ai_agent_id is not null and scope_id is not null;
create unique index view_shares_ai_agent_organisation on workspace.view_shares (organisation_id, ai_agent_id)
  where ai_agent_id is not null and organisation_wide;
create unique index view_shares_notebook_membership on workspace.view_shares (organisation_id, notebook_id, membership_id)
  where notebook_id is not null and membership_id is not null;
create unique index view_shares_notebook_scope on workspace.view_shares (organisation_id, notebook_id, scope_id)
  where notebook_id is not null and scope_id is not null;
create unique index view_shares_notebook_organisation on workspace.view_shares (organisation_id, notebook_id)
  where notebook_id is not null and organisation_wide;
create unique index view_shares_ml_model_membership on workspace.view_shares (organisation_id, ml_model_id, membership_id)
  where ml_model_id is not null and membership_id is not null;
create unique index view_shares_ml_model_scope on workspace.view_shares (organisation_id, ml_model_id, scope_id)
  where ml_model_id is not null and scope_id is not null;
create unique index view_shares_ml_model_organisation on workspace.view_shares (organisation_id, ml_model_id)
  where ml_model_id is not null and organisation_wide;
-- Open with permission re-check, view side.
create index view_shares_live_saved_view on workspace.view_shares (organisation_id, saved_view_id)
  where saved_view_id is not null and revoked_at is null and suspended_at is null;
create index view_shares_live_canvas_view on workspace.view_shares (organisation_id, canvas_view_id)
  where canvas_view_id is not null and revoked_at is null and suspended_at is null;
