  where scope_id is not null and canvas_view_id is not null and revoked_at is null and suspended_at is null;
create index view_shares_member_scenario on workspace.view_shares (organisation_id, membership_id, scenario_id)
  where membership_id is not null and scenario_id is not null and revoked_at is null and suspended_at is null;
