-- ---------------------------------------------------------------------------
-- workspace.dashboard_tiles: a layout preference nothing references. Unfavourite
-- deletes the tile.
create table workspace.dashboard_tiles (
  id              uuid primary key,
  organisation_id uuid not null references iam.organisations (id),
  membership_id   uuid not null,
  saved_view_id   uuid,
  canvas_view_id  uuid,
  scenario_id     uuid,
  grid            integer[] not null,
  created_at      timestamptz not null default now(),
  unique (organisation_id, id),
  foreign key (organisation_id, membership_id) references iam.memberships (organisation_id, id),
  foreign key (organisation_id, saved_view_id) references workspace.saved_views (organisation_id, id),
  foreign key (organisation_id, canvas_view_id) references clone.canvas_views (organisation_id, id),
  check (num_nonnulls(saved_view_id, canvas_view_id, scenario_id) = 1),
  check (array_ndims(grid) = 1 and cardinality(grid) = 4 and array_position(grid, null) is null
         and 1 <= all (grid))
);
comment on table workspace.dashboard_tiles is
  'A person''s dashboard grid of favourited views and scenarios. Exists while favourited.';
comment on column workspace.dashboard_tiles.grid is 'Column, row, column span, row span; each at least 1.';
create unique index dashboard_tiles_one_saved_view on workspace.dashboard_tiles (organisation_id, membership_id, saved_view_id)
  where saved_view_id is not null;
create unique index dashboard_tiles_one_canvas_view on workspace.dashboard_tiles (organisation_id, membership_id, canvas_view_id)
  where canvas_view_id is not null;
