-- ---------------------------------------------------------------------------
-- workspace.analysis_steps: written with the manifest and never changed (a changed
-- chain is a new manifest), so services hold insert and select only.
create table workspace.analysis_steps (
  id              uuid primary key,
  organisation_id uuid not null references iam.organisations (id),
  manifest_id     uuid not null,
  position        integer not null check (position >= 1),
  operation       text not null check (operation in ('filter', 'traverse', 'group', 'pivot', 'compare',
                                                     'time_series', 'derive', 'select')),
  input_steps     integer[] not null default '{}',
  definition      jsonb not null,
  output_kind     text not null check (output_kind in ('object_set', 'result')),
  bound           integer not null check (bound > 0),
  created_at      timestamptz not null default now(),
  unique (organisation_id, id),
  unique (organisation_id, manifest_id, position),
  -- Inputs are earlier steps only, so a chain is acyclic by construction.
  check (array_position(input_steps, null) is null and 1 <= all (input_steps) and position > all (input_steps))
);
comment on table workspace.analysis_steps is
  'The ordered, bounded steps of an analysis manifest over object sets. Immutable.';
comment on column workspace.analysis_steps.input_steps is 'Positions of input steps; empty for a fresh object set.';
comment on column workspace.analysis_steps.definition is
  'Typed operation parameters. No values except placeholder-bound literals.';
select platform.enable_tenant_rls('workspace.analysis_steps');

grant select, insert on workspace.analysis_steps to silo_app;
grant select on workspace.analysis_steps to silo_report;

-- A member's device for mobile push (decision 2026-11-14; D85): the provider's registration
-- token, on the platform the cell's provider serves (FCM, or APNs directly in the sovereign
-- build). A push carries a count and a link only, never a record value. A token the provider
-- reports gone is revoked.
create table workspace.push_devices (
  id              uuid primary key,
  organisation_id uuid not null references iam.organisations (id),
  membership_id   uuid not null,
  platform        text not null check (platform in ('fcm', 'apns')),
  token           text not null check (length(token) between 16 and 4096),
  registered_at   timestamptz not null default now(),
  last_sent_at    timestamptz,
  revoked_at      timestamptz,
  unique (organisation_id, id),
  foreign key (organisation_id, membership_id) references iam.memberships (organisation_id, id)
);
comment on table workspace.push_devices is 'A member''s device for mobile push; the push carries a count and a link only (D85).';
create unique index push_devices_live on workspace.push_devices (organisation_id, platform, token) where revoked_at is null;
create index push_devices_member on workspace.push_devices (organisation_id, membership_id) where revoked_at is null;
select platform.enable_tenant_rls('workspace.push_devices');
create trigger push_devices_frozen before update on workspace.push_devices
  for each row execute function platform.freeze_columns('id', 'organisation_id', 'membership_id', 'platform', 'token', 'registered_at');
grant select, insert, update on workspace.push_devices to silo_app;

-- Ask's web context per scope (36.7; decision 2026-11-14; D89). On by default; an admin
-- turns it off for a scope, or narrows it to a domain allowlist or away from a blocklist.
-- It is off in any scope that holds marked data (a connection it owns carries a marking)
-- unless an admin who satisfies those markings turned it on despite them: the markings they
-- covered are kept, so a marking added later turns it off again.
create table workspace.ask_web_policies (
  id                       uuid primary key,
  organisation_id          uuid not null references iam.organisations (id),
  scope_id                 uuid not null,
  enabled                  boolean not null default true,
  allowed_domains          text[] not null default '{}',
  blocked_domains          text[] not null default '{}',
  marked_override_markings uuid[] not null default '{}',
  override_by              uuid,
  updated_by               uuid not null,
  updated_at               timestamptz not null default now(),
  unique (organisation_id, id),
  unique (organisation_id, scope_id),
  foreign key (organisation_id, scope_id) references iam.scopes (organisation_id, id),
  foreign key (organisation_id, override_by) references iam.memberships (organisation_id, id),
  foreign key (organisation_id, updated_by) references iam.memberships (organisation_id, id),
  check (cardinality(allowed_domains) <= 200 and cardinality(blocked_domains) <= 200),
  check ((override_by is null) = (cardinality(marked_override_markings) = 0))
);
comment on table workspace.ask_web_policies is 'Ask''s web context in one scope: on or off, domain lists, a covered marked-data override (D89).';
select platform.add_updated_at_trigger('workspace.ask_web_policies');
select platform.enable_tenant_rls('workspace.ask_web_policies');
create trigger ask_web_policies_frozen before update on workspace.ask_web_policies
  for each row execute function platform.freeze_columns('id', 'organisation_id', 'scope_id');
grant select, insert, update on workspace.ask_web_policies to silo_app;

-- ---------------------------------------------------------------------------
-- workspace.notifications
create table workspace.notifications (
  id                       uuid primary key,
  organisation_id          uuid not null references iam.organisations (id),
  recipient_membership_id  uuid not null,
  automation_run_action_id uuid,
  approval_chain_id        uuid,
  finding_id               uuid,
  simulation_run_id        uuid,
  operator_access_session_id uuid,
  -- An Action's notification side effect (spec 42.6) names its receipt. No foreign key: the
  -- side effect fires after verification and before the receipt row is written, so the
  -- receipt can record its outcome; the reference is checked by the actions service.
  receipt_id               uuid,
  -- An outbound Action event subscription dead-lettered (spec 48.3): its owner is told.
  action_event_subscription_id uuid,
  -- A custom object view layout an ontology change invalidated (spec 34.6): its author is told.
  object_view_layout_id    uuid,
  -- An ontology element deprecated, or retiring in seven days (spec 25.7): owners of its dependants are told.
  -- No foreign key: the id is an object type, link type, shared property, interface or function.
  ontology_element_id      uuid,
  -- A scheduled pipeline run that failed (D241): its owner is told.
  pipeline_run_id          uuid,
  -- A support reply (U4): the reply is the source, so each reply is told once; its ticket is
  -- carried beside it for the link.
  support_ticket_message_id uuid,
  support_ticket_id        uuid,
  kind                     text not null check (kind in ('cron_notify', 'cron_escalate', 'approval_waiting',
                                                         'finding_new', 'scenario_run_complete',
                                                         'operator_access_waiting', 'operator_access_emergency',
                                                         'action_completed', 'action_event_dead_lettered',
                                                         'object_view_layout_invalidated', 'element_deprecated',
                                                         'element_retiring', 'pipeline_run_failed', 'support_replied')),
  channel                  text not null default 'in_app' check (channel in ('in_app', 'email', 'mobile_push')),
  created_at               timestamptz not null default now(),
  delivered_at             timestamptz,
  read_at                  timestamptz,
  acknowledge_due_at       timestamptz,
  acknowledged_at          timestamptz,
  unique (organisation_id, id),
  foreign key (organisation_id, recipient_membership_id) references iam.memberships (organisation_id, id),
  foreign key (organisation_id, object_view_layout_id) references workspace.object_view_layouts (organisation_id, id),
  foreign key (organisation_id, pipeline_run_id) references workspace.pipeline_runs (organisation_id, id),
  foreign key (organisation_id, support_ticket_message_id) references platform.support_ticket_messages (organisation_id, id),
  foreign key (organisation_id, support_ticket_id) references platform.support_tickets (organisation_id, id),
  check (num_nonnulls(automation_run_action_id, approval_chain_id, finding_id, simulation_run_id, operator_access_session_id, receipt_id,
                      action_event_subscription_id, object_view_layout_id, ontology_element_id, pipeline_run_id,
                      support_ticket_message_id) = 1),
  check ((support_ticket_id is not null) = (support_ticket_message_id is not null)),
  check (case kind
           when 'cron_notify'           then automation_run_action_id is not null
           when 'cron_escalate'         then automation_run_action_id is not null
           when 'approval_waiting'      then approval_chain_id is not null
           when 'finding_new'           then finding_id is not null
           when 'scenario_run_complete' then simulation_run_id is not null
           when 'operator_access_waiting'   then operator_access_session_id is not null
           when 'operator_access_emergency' then operator_access_session_id is not null
           when 'action_completed'          then receipt_id is not null
           when 'action_event_dead_lettered' then action_event_subscription_id is not null
           when 'object_view_layout_invalidated' then object_view_layout_id is not null
           when 'element_deprecated'        then ontology_element_id is not null
           when 'element_retiring'          then ontology_element_id is not null
           when 'pipeline_run_failed'       then pipeline_run_id is not null
           when 'support_replied'           then support_ticket_message_id is not null
         end),
  check ((acknowledge_due_at is not null) = (kind = 'cron_escalate')),
  check (acknowledged_at is null or kind = 'cron_escalate'),
  check (acknowledged_at is null or read_at is not null)
);
comment on table workspace.notifications is
  'Delivered items with read and acknowledgement state. No text: rendered on read from the source row.';
comment on column workspace.notifications.created_at is 'When the item was raised.';
comment on column workspace.notifications.delivered_at is 'When the channel accepted it.';
comment on column workspace.notifications.acknowledge_due_at is 'Escalations only: when the recipient must acknowledge by.';
-- One delivery per recipient, kind, channel and source.
create unique index notifications_once_run_action
  on workspace.notifications (organisation_id, recipient_membership_id, kind, channel, automation_run_action_id)
  where automation_run_action_id is not null;
create unique index notifications_once_approval_chain
  on workspace.notifications (organisation_id, recipient_membership_id, kind, channel, approval_chain_id)
  where approval_chain_id is not null;
create unique index notifications_once_support_message
  on workspace.notifications (organisation_id, recipient_membership_id, kind, channel, support_ticket_message_id)
  where support_ticket_message_id is not null;
create unique index notifications_once_finding
  on workspace.notifications (organisation_id, recipient_membership_id, kind, channel, finding_id)
  where finding_id is not null;
create unique index notifications_once_pipeline_run
  on workspace.notifications (organisation_id, recipient_membership_id, kind, channel, pipeline_run_id)
  where pipeline_run_id is not null;
create index notifications_pipeline_run on workspace.notifications (organisation_id, pipeline_run_id) where pipeline_run_id is not null;
create index notifications_support_message on workspace.notifications (organisation_id, support_ticket_message_id)
  where support_ticket_message_id is not null;
create index notifications_support_ticket on workspace.notifications (organisation_id, support_ticket_id) where support_ticket_id is not null;
create unique index notifications_once_simulation_run
  on workspace.notifications (organisation_id, recipient_membership_id, kind, channel, simulation_run_id)
  where simulation_run_id is not null;
create unique index notifications_once_operator_access
  on workspace.notifications (organisation_id, recipient_membership_id, kind, channel, operator_access_session_id)
  where operator_access_session_id is not null;
create unique index notifications_once_receipt
  on workspace.notifications (organisation_id, recipient_membership_id, kind, channel, receipt_id)
  where receipt_id is not null;
-- Not unique: a subscription resumed and dead-lettered again tells its owner again.
create index notifications_action_event_subscription on workspace.notifications (organisation_id, action_event_subscription_id)
  where action_event_subscription_id is not null;
create unique index notifications_once_object_view_layout
  on workspace.notifications (organisation_id, recipient_membership_id, kind, channel, object_view_layout_id)
  where object_view_layout_id is not null;
create unique index notifications_once_ontology_element
  on workspace.notifications (organisation_id, recipient_membership_id, kind, channel, ontology_element_id)
  where ontology_element_id is not null;
create index notifications_object_view_layout on workspace.notifications (organisation_id, object_view_layout_id)
  where object_view_layout_id is not null;
create index notifications_feed on workspace.notifications (organisation_id, recipient_membership_id, created_at desc);
create index notifications_unread on workspace.notifications (organisation_id, recipient_membership_id, created_at desc)
  where read_at is null;
create index notifications_escalation_due on workspace.notifications (organisation_id, acknowledge_due_at)
  where kind = 'cron_escalate' and acknowledged_at is null;
create index notifications_run_action on workspace.notifications (organisation_id, automation_run_action_id)
  where automation_run_action_id is not null;
create index notifications_approval_chain on workspace.notifications (organisation_id, approval_chain_id)
  where approval_chain_id is not null;
create index notifications_finding on workspace.notifications (organisation_id, finding_id)
  where finding_id is not null;
create index notifications_simulation_run on workspace.notifications (organisation_id, simulation_run_id)
  where simulation_run_id is not null;
create index notifications_operator_access on workspace.notifications (organisation_id, operator_access_session_id)
  where operator_access_session_id is not null;
select platform.enable_tenant_rls('workspace.notifications');

grant select, insert, update (delivered_at, read_at, acknowledged_at) on workspace.notifications to silo_app;
grant select on workspace.notifications to silo_report;

