-- workspace.recent_items: a preference nothing references. Capped at 50 per
-- membership; trimmed rows are deleted.
create table workspace.recent_items (
  id              uuid primary key,
  organisation_id uuid not null references iam.organisations (id),
  membership_id   uuid not null,
  object_type_id  uuid,
  object_ref      uuid,
  saved_view_id   uuid,
  canvas_view_id  uuid,
  app_id          uuid,
  scenario_id     uuid,
  last_opened_at  timestamptz not null default now(),
  open_count      integer not null default 1 check (open_count >= 1),
  unique (organisation_id, id),
  foreign key (organisation_id, membership_id) references iam.memberships (organisation_id, id),
  foreign key (organisation_id, saved_view_id) references workspace.saved_views (organisation_id, id),
  foreign key (organisation_id, canvas_view_id) references clone.canvas_views (organisation_id, id),
  foreign key (organisation_id, app_id) references workspace.apps (organisation_id, id),
  check (num_nonnulls(object_ref, saved_view_id, canvas_view_id, app_id, scenario_id) = 1),
  check ((object_type_id is null) = (object_ref is null))
);
comment on table workspace.recent_items is
  'A person''s most recently opened items for Explorer and Cmd-K, resolved under current permissions on read.';
comment on column workspace.recent_items.object_ref is 'Object in its source system. A reference, no foreign key.';
-- Per-arm uniques: opening again upserts last_opened_at and open_count.
create unique index recent_items_one_object
  on workspace.recent_items (organisation_id, membership_id, object_type_id, object_ref) where object_ref is not null;
create unique index recent_items_one_saved_view
