create unique index recent_items_one_app
  on workspace.recent_items (organisation_id, membership_id, app_id) where app_id is not null;
create unique index recent_items_one_scenario
  on workspace.recent_items (organisation_id, membership_id, scenario_id) where scenario_id is not null;
create index recent_items_list on workspace.recent_items (organisation_id, membership_id, last_opened_at desc);
create index recent_items_saved_view on workspace.recent_items (organisation_id, saved_view_id)
  where saved_view_id is not null;
create index recent_items_canvas_view on workspace.recent_items (organisation_id, canvas_view_id)
  where canvas_view_id is not null;
create index recent_items_app on workspace.recent_items (organisation_id, app_id) where app_id is not null;
