  where object_type_id is not null;
select platform.enable_tenant_rls('workspace.recent_items');
create trigger recent_items_frozen before update on workspace.recent_items
  for each row execute function platform.freeze_columns(
    'id', 'organisation_id', 'membership_id', 'object_type_id', 'object_ref', 'saved_view_id',
    'canvas_view_id', 'app_id', 'scenario_id');

-- Keeps the 50 most recent per membership, trimming in the inserting transaction.
create function workspace.recent_items_trim() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
begin
  delete from workspace.recent_items r
  using (
    select o.organisation_id, o.id
    from (select distinct organisation_id, membership_id from new_rows) m
    cross join lateral (
      select i.organisation_id, i.id
      from workspace.recent_items i
      where i.organisation_id = m.organisation_id and i.membership_id = m.membership_id
      order by i.last_opened_at desc, i.id desc
      offset 50) o
  ) stale
  where r.organisation_id = stale.organisation_id and r.id = stale.id;
  return null;
end
$$;
create trigger recent_items_trim after insert on workspace.recent_items
  referencing new table as new_rows
  for each statement execute function workspace.recent_items_trim();

grant select, insert, update, delete on workspace.recent_items to silo_app;
grant select on workspace.recent_items to silo_report;

