-- ============================================================================
-- Domain: recognition, simulation
-- ============================================================================

-- Recognition and scenarios (spec chapters 38 and 39).
-- Design: docs/siloDatabaseDesign.doc.md, schemas recognition and simulation, with the
-- review decisions of 2026-10-28.
--
-- Written by the recognition and simulation services as silo_app. Findings,
-- associations and scenario results hold references, counts and statistics only;
-- the record values of this domain live only in the encrypted
-- simulation.staged_action_bases.base_value and staged_value.
-- Keys into ontology, connect, gov and action are added in the cross-domain section.
-- recognition.detectors is created empty: its seed comes with the recognition service.

-- ===========================================================================
-- recognition.detectors: the global detector registry (38.2)
-- ===========================================================================

create table recognition.detectors (
  id                  uuid primary key,
  key                 text not null unique check (key ~ '^[a-z][a-z0-9_]*$'),
  name                text not null unique check (length(btrim(name)) > 0),
  description         text not null,
  execution_mode      text not null check (execution_mode in ('federated', 'history')),
  requires_property   boolean not null,
  requires_time_field boolean not null,
  minimum_baseline    jsonb,
  current_version     text not null,
  status              text not null default 'active' check (status in ('active', 'retired')),
  retired_at          timestamptz,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),
  check ((minimum_baseline is not null) = (execution_mode = 'history')),
  check (minimum_baseline is null
         or coalesce(jsonb_typeof(minimum_baseline -> 'amount') = 'number'
                     and minimum_baseline ->> 'unit' in ('days', 'transitions'), false)),
  check ((status = 'retired') = (retired_at is not null))
);
comment on table recognition.detectors is
  'Global registry of the Silo-authored detectors. Seeded by Fleet migrations; not tenant data.';
comment on column recognition.detectors.key is 'Stable machine name used by code and seeds. Never renamed.';
comment on column recognition.detectors.minimum_baseline is
  'History needed before a history detector runs: {"amount": n, "unit": "days" | "transitions"}.';
create trigger detectors_frozen before update on recognition.detectors
  for each row execute function platform.freeze_columns('id', 'key');
select platform.add_updated_at_trigger('recognition.detectors');

grant select on recognition.detectors to silo_app, silo_report;

-- The detectors spec 38 names, and the two federated ones it counts but does not name,
-- named by decision 2026-11-14 (D82): uniqueness and timeliness, of the DAMA UK data
-- quality dimensions.
insert into recognition.detectors (id, key, name, description, execution_mode, requires_property, requires_time_field, minimum_baseline, current_version) values
  ('00000000-0000-4000-8000-0000000000d1', 'disagreement', 'Disagreement', 'Two systems hold different values for one property of one resolved object.', 'federated', true, false, null, '1.0.0'),
  ('00000000-0000-4000-8000-0000000000d2', 'missing_value', 'Missing value', 'A property is empty on an object where it is filled on most of the population.', 'federated', true, false, null, '1.0.0'),
  ('00000000-0000-4000-8000-0000000000d3', 'outlier', 'Outlier', 'A numeric property lies far from the population median, by the modified z-score.', 'federated', true, false, null, '1.0.0'),
  ('00000000-0000-4000-8000-0000000000d4', 'duplicate_value', 'Duplicate value', 'Several objects share one value of a property.', 'federated', true, false, null, '1.0.0'),
  ('00000000-0000-4000-8000-0000000000d5', 'unmatched_record', 'Unmatched record', 'A record stands alone for want of a match key.', 'federated', false, false, null, '1.0.0'),
  ('00000000-0000-4000-8000-0000000000d6', 'uniqueness', 'Uniqueness', 'Several objects agree on every property named, so may be one thing held twice, in one system or across systems.', 'federated', true, false, null, '1.0.0'),
  ('00000000-0000-4000-8000-0000000000d7', 'timeliness', 'Timeliness', 'An object was last updated far longer ago than its population, so has missed its expected cycle.', 'federated', false, true, null, '1.0.0'),
  -- The history detectors time what Capture observed: each transition carries its own time, so none needs a time field (D58).
  ('00000000-0000-4000-8000-0000000000d8', 'timing_deviation', 'Timing deviation', 'An object took longer than usual between two recorded states.', 'history', true, false, '{"amount": 30, "unit": "days"}', '1.0.0'),
  ('00000000-0000-4000-8000-0000000000d9', 'drift', 'Drift', 'A property moved steadily away from its own past values.', 'history', true, false, '{"amount": 90, "unit": "days"}', '1.0.0'),
  ('00000000-0000-4000-8000-0000000000da', 'recurrence', 'Recurrence', 'The same state recurs on an object more often than its population.', 'history', true, false, '{"amount": 60, "unit": "transitions"}', '1.0.0');

-- What a detector examines on an object type (spec 38.2), by property identity.
create table recognition.detector_configurations (
  id                     uuid primary key,
  organisation_id        uuid not null references iam.organisations (id),
  detector_id            uuid not null references recognition.detectors (id),
  object_type_id         uuid not null,
  property_identity_ids  uuid[] not null default '{}',
  time_field_identity_id uuid,
  enabled                boolean not null default true,
  configured_by          uuid not null,
  version                integer not null default 1,
  created_at             timestamptz not null default now(),
  updated_at             timestamptz not null default now(),
  unique (organisation_id, id),
  constraint detector_configurations_target_key unique (organisation_id, detector_id, object_type_id),
  constraint detector_configurations_object_type_fkey
    foreign key (organisation_id, object_type_id) references ontology.object_types (organisation_id, id),
  constraint detector_configurations_configured_by_fkey
    foreign key (organisation_id, configured_by) references iam.memberships (organisation_id, id),
  check (cardinality(property_identity_ids) <= 50)
);
comment on table recognition.detector_configurations is
  'What a detector examines on an object type (spec 38.2, 38.11 recognition.configure): properties by identity, the time field, enabled.';
comment on column recognition.detector_configurations.property_identity_ids is
  'ontology.property_identities ids, stable across renames. Identifiers only.';
create index detector_configurations_object_type on recognition.detector_configurations (organisation_id, object_type_id);
select platform.enable_tenant_rls('recognition.detector_configurations');
select platform.add_updated_at_trigger('recognition.detector_configurations');
grant select, insert, update on recognition.detector_configurations to silo_app;
grant select on recognition.detector_configurations to silo_report;

-- ===========================================================================
-- recognition.detector_runs: one detector over one object type (38.2, 38.12)
-- ===========================================================================

create table recognition.detector_runs (
  id                   uuid primary key,
  organisation_id      uuid not null references iam.organisations (id),
  detector_id          uuid not null,
  detector_version     text not null,
  object_type_id       uuid not null,
  properties           text[] not null default '{}',
  state                text not null check (state in ('ran', 'not_configured', 'accumulating_baseline',
                                                      'history_unavailable', 'source_unreachable', 'bounded')),
  state_detail         jsonb,
  population_count     bigint check (population_count >= 0),
  baseline             jsonb,
  findings_count       integer not null default 0 check (findings_count >= 0),
  run_by_membership_id uuid,
  started_at           timestamptz not null,
  completed_at         timestamptz,
  created_at           timestamptz not null default now(),
  unique (organisation_id, id),
  constraint detector_runs_org_id_detector_key unique (organisation_id, id, detector_id),
  constraint detector_runs_org_id_detector_object_type_key
    unique (organisation_id, id, detector_id, object_type_id),
  constraint detector_runs_detector_fkey foreign key (detector_id) references recognition.detectors (id),
  constraint detector_runs_run_by_fkey
    foreign key (organisation_id, run_by_membership_id) references iam.memberships (organisation_id, id),
  check (state <> 'ran' or population_count is not null),
  check ((baseline is not null) = (state = 'accumulating_baseline')),
  check (baseline is null or (jsonb_typeof(baseline) = 'object' and baseline ?& array['have', 'need'])),
  check (state = 'ran' or findings_count = 0)
);
comment on table recognition.detector_runs is
  'One run of one detector over one object type, recorded even when it produced nothing.';
comment on column recognition.detector_runs.properties is 'Configured property names of the object type. Names only.';
comment on column recognition.detector_runs.state_detail is
  'Connection ids for source_unreachable; the bound and population seen for bounded. Identifiers and counts only.';
comment on column recognition.detector_runs.run_by_membership_id is 'Member who ran it on demand; null for scheduled runs.';
create index detector_runs_latest on recognition.detector_runs
  (organisation_id, object_type_id, detector_id, started_at desc);
create index detector_runs_list on recognition.detector_runs (organisation_id, started_at desc);
create index detector_runs_by_detector on recognition.detector_runs (organisation_id, detector_id, started_at desc);
select platform.enable_tenant_rls('recognition.detector_runs');

grant select, insert, update on recognition.detector_runs to silo_app;
grant select on recognition.detector_runs to silo_report;

-- ===========================================================================
-- recognition.findings: stated facts about named objects (38.3, 38.12)
-- ===========================================================================

create table recognition.findings (
  id                 uuid primary key,
  organisation_id    uuid not null references iam.organisations (id),
  detector_run_id    uuid not null,
  detector_id        uuid not null,
  object_type_id     uuid not null,
  object_refs        jsonb not null,
  properties         text[] not null,
  computation        jsonb not null,
  coverage           jsonb not null,
  org_disposition    text check (org_disposition in ('confirmed', 'dismissed', 'deferred')),
  org_disposition_by uuid,
  org_disposition_at timestamptz,
  superseded_at      timestamptz,
  raised_at          timestamptz not null,
  version            integer not null default 1,
  updated_at         timestamptz not null default now(),
  unique (organisation_id, id),
  unique (organisation_id, id, detector_id),
  unique (organisation_id, id, object_type_id),
  constraint findings_detector_run_fkey
    foreign key (organisation_id, detector_run_id, detector_id, object_type_id)
    references recognition.detector_runs (organisation_id, id, detector_id, object_type_id),
  constraint findings_org_disposition_by_fkey
    foreign key (organisation_id, org_disposition_by) references iam.memberships (organisation_id, id),
  check (num_nonnulls(org_disposition, org_disposition_by, org_disposition_at) in (0, 3))
);
comment on table recognition.findings is
  'A fact a detector stated about named objects in one run. References and counts, never record values.';
comment on column recognition.findings.object_refs is
  'Object identifiers for display. The queryable copy is recognition.finding_objects.';
comment on column recognition.findings.computation is
  'Statistic, threshold crossed, population and sample size. Never record values.';
comment on column recognition.findings.coverage is 'Counts of decided, disputed, empty and unchecked.';
comment on column recognition.findings.superseded_at is
  'Set when a later run no longer raises, or re-raises, this finding. Null means current.';
comment on constraint findings_detector_run_fkey on recognition.findings is
  'lint:no-index served by findings_by_run (organisation_id, detector_run_id); the run id alone is unique';
create index findings_by_run on recognition.findings (organisation_id, detector_run_id);
create index findings_current on recognition.findings (organisation_id, object_type_id, raised_at desc)
  where superseded_at is null;
create index findings_dispositions on recognition.findings
  (organisation_id, detector_id, object_type_id, org_disposition_at)
  where org_disposition is not null;
create index findings_by_detector on recognition.findings (organisation_id, detector_id, raised_at desc);
select platform.enable_tenant_rls('recognition.findings');
select platform.add_updated_at_trigger('recognition.findings');

-- After creation only the organisation disposition, superseded_at, version and
-- updated_at change. A Siloes purge never deletes a finding (38.3).
create trigger findings_frozen before update on recognition.findings
  for each row execute function platform.freeze_columns(
    'id', 'organisation_id', 'detector_run_id', 'detector_id', 'object_type_id', 'object_refs',
    'properties', 'computation', 'coverage', 'raised_at');
create trigger findings_no_delete before delete on recognition.findings
  for each row execute function platform.reject_ledger_change('strict');

grant select, insert on recognition.findings to silo_app;
grant update (org_disposition, org_disposition_by, org_disposition_at, superseded_at, version, updated_at)
  on recognition.findings to silo_app;
grant select on recognition.findings to silo_report;

