create table recognition.finding_links (
  organisation_id   uuid not null references iam.organisations (id),
  finding_id        uuid not null,
  linked_finding_id uuid not null,
  shared_refs_count integer not null check (shared_refs_count > 0),
  created_at        timestamptz not null default now(),
  primary key (organisation_id, finding_id, linked_finding_id),
  foreign key (organisation_id, finding_id) references recognition.findings (organisation_id, id),
  foreign key (organisation_id, linked_finding_id) references recognition.findings (organisation_id, id),
  check (finding_id <> linked_finding_id)
);
comment on table recognition.finding_links is
  'Links between findings about the same records, stored in both directions.';
create index finding_links_linked on recognition.finding_links (organisation_id, linked_finding_id);
select platform.enable_tenant_rls('recognition.finding_links');
select platform.make_append_only('recognition.finding_links', true);

-- Each link is stored in both directions in one transaction, so a lookup by
-- finding_id is complete. Checked at commit.
create function recognition.finding_links_both_directions() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
begin
  if not exists (
    select 1 from recognition.finding_links l
    where l.organisation_id = new.organisation_id
      and l.finding_id = new.linked_finding_id
      and l.linked_finding_id = new.finding_id) then
    raise exception 'finding link % -> % has no reverse row', new.finding_id, new.linked_finding_id
      using errcode = 'check_violation';
  end if;
  return null;
end
$$;
create constraint trigger finding_links_both_directions
  after insert on recognition.finding_links
  deferrable initially deferred
  for each row execute function recognition.finding_links_both_directions();

grant select, insert on recognition.finding_links to silo_app;
grant select on recognition.finding_links to silo_report;

