  value           numeric not null,
  origin          text not null check (origin in ('derived', 'tuned')),
  tuned           boolean not null default false,
  version         integer not null default 1,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  unique (organisation_id, id),
  constraint detector_thresholds_target_key
    unique nulls not distinct (organisation_id, detector_id, object_type_id, property),
  check (tuned = (origin = 'tuned'))
);
comment on table recognition.detector_thresholds is
  'Current threshold per detector, object type and optional property; tuned only by organisation dispositions.';
comment on column recognition.detector_thresholds.property is 'Property name; null when the threshold is not per property.';
