-- ===========================================================================
-- Association analysis (38.6)
-- ===========================================================================

create table recognition.association_computations (
  id                        uuid primary key,
  organisation_id           uuid not null references iam.organisations (id),
  supersedes_computation_id uuid,
  computed_by_membership_id uuid,
  computed_at               timestamptz not null,
  created_at                timestamptz not null default now(),
  unique (organisation_id, id),
  constraint association_computations_supersedes_fkey
    foreign key (organisation_id, supersedes_computation_id)
    references recognition.association_computations (organisation_id, id),
  constraint association_computations_computed_by_fkey
    foreign key (organisation_id, computed_by_membership_id) references iam.memberships (organisation_id, id),
  check (supersedes_computation_id is distinct from id)
);
comment on table recognition.association_computations is
  'One association analysis run, so an earlier set is a real reference.';
comment on column recognition.association_computations.computed_by_membership_id is 'Null when scheduled.';
create index association_computations_latest on recognition.association_computations
  (organisation_id, computed_at desc);
create index association_computations_supersedes on recognition.association_computations
  (organisation_id, supersedes_computation_id)
  where supersedes_computation_id is not null;
select platform.enable_tenant_rls('recognition.association_computations');
select platform.make_append_only('recognition.association_computations', true);

grant select, insert on recognition.association_computations to silo_app;
grant select on recognition.association_computations to silo_report;

create table recognition.associations (
  id                   uuid primary key,
  organisation_id      uuid not null references iam.organisations (id),
  computation_id       uuid not null,
  left_object_type_id  uuid not null,
  left_property        text,
  left_detector_id     uuid,
  right_object_type_id uuid not null,
  right_property       text,
  right_detector_id    uuid,
  link_type_id         uuid,
  link_direction       text check (link_direction in ('forward', 'reverse')),
  co_occurrence_count  bigint not null check (co_occurrence_count >= 0),
  sample_size          bigint not null check (sample_size > 0),
  temporal_order       jsonb,
  statement            text not null,
  computed_at          timestamptz not null,
  unique (organisation_id, id),
  foreign key (organisation_id, computation_id)
    references recognition.association_computations (organisation_id, id),
  constraint associations_left_detector_fkey foreign key (left_detector_id) references recognition.detectors (id),
  constraint associations_right_detector_fkey foreign key (right_detector_id) references recognition.detectors (id),
  check (co_occurrence_count <= sample_size),
  check (num_nonnulls(left_property, left_detector_id) = 1),
  check (num_nonnulls(right_property, right_detector_id) = 1),
  check ((link_type_id is null) = (link_direction is null)),
  check (link_type_id is not null or left_object_type_id = right_object_type_id),
  constraint associations_no_causal_language
    check (statement !~* '\m(cause|causes|caused|drive|drives|driven)\M')
);
comment on table recognition.associations is
  'A co-occurrence between two populations, with its sample size, stated in fixed non-causal language.';
comment on column recognition.associations.temporal_order is 'Counts for "precedes in N of M instances". Counts only.';
comment on column recognition.associations.link_type_id is
  'Set when the populations are on types a link type joins ("is linked through"); link_direction says which way it was read.';
comment on constraint associations_left_detector_fkey on recognition.associations is
  'lint:no-index global registry of ten rows; detectors are retired, never deleted';
comment on constraint associations_right_detector_fkey on recognition.associations is
  'lint:no-index global registry of ten rows; detectors are retired, never deleted';
create index associations_computation on recognition.associations (organisation_id, computation_id);
create index associations_left_object_type on recognition.associations (organisation_id, left_object_type_id);
create index associations_right_object_type on recognition.associations (organisation_id, right_object_type_id);
select platform.enable_tenant_rls('recognition.associations');
select platform.make_append_only('recognition.associations', true);

grant select, insert on recognition.associations to silo_app;
grant select on recognition.associations to silo_report;

-- A person designates an outcome of interest (38.6: outcome.designate): a yes/no property of a
-- type, or a finding kind (a detector) on it. Association analysis then reports what co-occurs
-- with it; a designation never changes what a detector raises. Revoked, never deleted.
create table recognition.outcome_designations (
  id              uuid primary key,
  organisation_id uuid not null references iam.organisations (id),
  object_type_id  uuid not null,
  property        text,
  detector_id     uuid,
  designated_by   uuid not null,
  designated_at   timestamptz not null default now(),
  revoked_by      uuid,
  revoked_at      timestamptz,
  unique (organisation_id, id),
  constraint outcome_designations_detector_fkey foreign key (detector_id) references recognition.detectors (id),
  constraint outcome_designations_designated_by_fkey
    foreign key (organisation_id, designated_by) references iam.memberships (organisation_id, id),
  constraint outcome_designations_revoked_by_fkey
    foreign key (organisation_id, revoked_by) references iam.memberships (organisation_id, id),
  check (num_nonnulls(property, detector_id) = 1),
  check ((revoked_at is null) = (revoked_by is null))
);
comment on table recognition.outcome_designations is
  'An outcome of interest for association analysis (38.6): a property name or a detector, never a value.';
comment on constraint outcome_designations_detector_fkey on recognition.outcome_designations is
  'lint:no-index global registry of ten rows; detectors are retired, never deleted';
create index outcome_designations_live on recognition.outcome_designations (organisation_id, object_type_id) where revoked_at is null;
create unique index outcome_designations_one_live on recognition.outcome_designations
  (organisation_id, object_type_id, coalesce(property, ''), coalesce(detector_id::text, '')) where revoked_at is null;
create index outcome_designations_designated_by on recognition.outcome_designations (organisation_id, designated_by);
create index outcome_designations_revoked_by on recognition.outcome_designations (organisation_id, revoked_by) where revoked_by is not null;
select platform.enable_tenant_rls('recognition.outcome_designations');
grant select, insert, update on recognition.outcome_designations to silo_app;
grant select on recognition.outcome_designations to silo_report;

-- ===========================================================================
-- Lenses: a person's private working layer (38.9)
-- ===========================================================================

create table recognition.lenses (
  id              uuid primary key,
  organisation_id uuid not null references iam.organisations (id),
  membership_id   uuid not null,
  name            text not null check (length(btrim(name)) > 0),
  working_sets    jsonb not null default '[]',
  counts          jsonb,
  evaluated_at    timestamptz,
  archived_at     timestamptz,
  version         integer not null default 1,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  unique (organisation_id, id),
  foreign key (organisation_id, membership_id) references iam.memberships (organisation_id, id)
);
comment on table recognition.lenses is
  'A member''s private working layer over the shared ontology. Readable by others only through a live share.';
comment on column recognition.lenses.working_sets is
  'Set definitions and reference lists. References, counts and definitions only; no record values.';
