-- ===========================================================================
-- simulation.graph_state: the organisation's graph version (39.3)
-- ===========================================================================

create table simulation.graph_state (
  organisation_id uuid primary key references iam.organisations (id),
  graph_version   bigint not null default 0 check (graph_version >= 0),
  updated_at      timestamptz not null default now()
);
comment on table simulation.graph_state is
  'Current dependency graph version per organisation. Locked and incremented first by every edge change.';
select platform.enable_tenant_rls('simulation.graph_state');
select platform.add_updated_at_trigger('simulation.graph_state');

create function simulation.graph_state_only_increase() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
begin
  if new.graph_version <= old.graph_version or new.organisation_id <> old.organisation_id then
    raise exception 'graph version can only increase' using errcode = 'insufficient_privilege';
  end if;
  return new;
end
$$;
create trigger graph_state_only_increase before update on simulation.graph_state
  for each row execute function simulation.graph_state_only_increase();

grant select, insert, update on simulation.graph_state to silo_app;
grant select on simulation.graph_state to silo_report;

-- ===========================================================================
-- simulation.dependency_edges and their history (39.2, 39.3, 39.11)
-- ===========================================================================

create table simulation.dependency_edges (
  id                               uuid primary key,
  organisation_id                  uuid not null references iam.organisations (id),
  from_object_type_id              uuid not null,
  to_object_type_id                uuid not null,
  via_link_type_id                 uuid not null,
  kind                             text not null check (kind in ('hard', 'soft', 'resource')),
  -- A resource edge (decision 2026-11-14; D86): the resource object's capacity property (units
  -- per period), the dependant's demand property, and how much of the resource one unit of
  -- the dependant consumes. A confirmed resource edge states all four.
  consumption                      numeric check (consumption > 0),
  capacity_property_id             uuid,
  demand_property_id               uuid,
  capacity_period                  text check (capacity_period in ('day', 'week', 'month')),
  lead_time                        jsonb,
  buffer                           jsonb,
  source                           text not null check (source in ('structure', 'history', 'stated')),
  evidence_ref                     jsonb,
  status                           text not null default 'proposed'
                                     check (status in ('proposed', 'confirmed', 'retired')),
  proposed_by_membership_id        uuid,
  proposed_by_service_principal_id uuid,
  confirmed_by                     uuid,
  confirmed_at                     timestamptz,
  retired_at                       timestamptz,
  version                          integer not null default 1,
  created_at                       timestamptz not null default now(),
  updated_at                       timestamptz not null default now(),
  unique (organisation_id, id),
  constraint dependency_edges_proposed_by_membership_fkey
    foreign key (organisation_id, proposed_by_membership_id) references iam.memberships (organisation_id, id),
  constraint dependency_edges_proposed_by_principal_fkey
    foreign key (organisation_id, proposed_by_service_principal_id)
    references iam.service_principals (organisation_id, id),
  constraint dependency_edges_confirmed_by_fkey
    foreign key (organisation_id, confirmed_by) references iam.memberships (organisation_id, id),
  check (num_nonnulls(proposed_by_membership_id, proposed_by_service_principal_id) = 1),
  check (lead_time is null or (jsonb_typeof(lead_time) = 'object' and lead_time ?& array['value', 'unit'])),
  check (buffer is null or (jsonb_typeof(buffer) = 'object' and buffer ?& array['value', 'unit'])),
  check ((confirmed_by is null) = (confirmed_at is null)),
  check (status <> 'proposed' or (confirmed_at is null and retired_at is null)),
  check (status <> 'confirmed' or (confirmed_by is not null and confirmed_at is not null and retired_at is null)),
  check (status <> 'retired' or retired_at is not null),
  check (status <> 'confirmed' or lead_time is not null),
  check (status <> 'confirmed' or source <> 'structure'),
  check (kind = 'resource' or num_nonnulls(consumption, capacity_property_id, demand_property_id, capacity_period) = 0),
  check (kind <> 'resource' or status <> 'confirmed'
         or num_nonnulls(consumption, capacity_property_id, demand_property_id, capacity_period) = 4)
);
comment on table simulation.dependency_edges is
  'A directed dependency between two object types over a link type. Live only once a person confirms it.';
comment on column simulation.dependency_edges.lead_time is '{"value": n, "unit": "..."}. Required once confirmed.';
comment on column simulation.dependency_edges.buffer is '{"value": n, "unit": "..."}.';
comment on column simulation.dependency_edges.evidence_ref is
  'Reference to the evidence (observation window, sample count). References only.';
comment on column simulation.dependency_edges.confirmed_by is 'A membership only: a service principal can never confirm.';
create unique index dependency_edges_live on simulation.dependency_edges
  (organisation_id, from_object_type_id, to_object_type_id, via_link_type_id, kind)
  where status <> 'retired';
create index dependency_edges_confirmed_from on simulation.dependency_edges (organisation_id, from_object_type_id)
  where status = 'confirmed';
create index dependency_edges_to on simulation.dependency_edges (organisation_id, to_object_type_id);
create index dependency_edges_via on simulation.dependency_edges (organisation_id, via_link_type_id);
create index dependency_edges_proposal_queue on simulation.dependency_edges (organisation_id, created_at desc)
  where status = 'proposed';
create index dependency_edges_proposed_by_principal on simulation.dependency_edges
  (organisation_id, proposed_by_service_principal_id)
  where proposed_by_service_principal_id is not null;
select platform.enable_tenant_rls('simulation.dependency_edges');
select platform.add_updated_at_trigger('simulation.dependency_edges');

grant select, insert, update on simulation.dependency_edges to silo_app;
grant select on simulation.dependency_edges to silo_report;

create table simulation.edge_observations (
  id              uuid primary key,
  organisation_id uuid not null references iam.organisations (id),
  edge_id         uuid not null,
  sample_count    integer not null check (sample_count >= 0),
  distribution    jsonb not null,
  observed_from   timestamptz not null,
  observed_to     timestamptz not null,
  computed_at     timestamptz not null,
  unique (organisation_id, id),
  unique (organisation_id, edge_id, computed_at),
  foreign key (organisation_id, edge_id) references simulation.dependency_edges (organisation_id, id),
  check (observed_to >= observed_from)
);
comment on table simulation.edge_observations is
  'Observed lead-time statistics for an edge from Silo history. Statistics only, never values.';
select platform.enable_tenant_rls('simulation.edge_observations');
select platform.make_append_only('simulation.edge_observations', true);

grant select, insert on simulation.edge_observations to silo_app;
grant select on simulation.edge_observations to silo_report;

create table simulation.edge_revisions (
  id              uuid primary key,
  organisation_id uuid not null references iam.organisations (id),
  edge_id         uuid not null,
  change_kind     text not null check (change_kind in ('confirmed', 'revised', 'retired')),
  previous_state  jsonb,
  new_state       jsonb not null,
  reason          text not null check (length(btrim(reason)) > 0),
  revised_by      uuid not null,
  graph_version   bigint not null check (graph_version >= 1),
  revised_at      timestamptz not null default now(),
  unique (organisation_id, id),
  unique (organisation_id, graph_version),
  foreign key (organisation_id, edge_id) references simulation.dependency_edges (organisation_id, id),
  constraint edge_revisions_revised_by_fkey
    foreign key (organisation_id, revised_by) references iam.memberships (organisation_id, id),
  check (previous_state is not null or change_kind = 'confirmed')
);
comment on table simulation.edge_revisions is
  'Append-only record of every confirmation, revision and retirement of a dependency edge.';
comment on column simulation.edge_revisions.graph_version is 'The graph version this change produced.';
create index edge_revisions_by_edge on simulation.edge_revisions (organisation_id, edge_id, revised_at desc);
select platform.enable_tenant_rls('simulation.edge_revisions');
select platform.make_append_only('simulation.edge_revisions');

grant select, insert on simulation.edge_revisions to silo_app;
grant select on simulation.edge_revisions to silo_report;

-- ===========================================================================
-- Scenarios, branches and runs (39.7, 39.8, 39.9, 39.11)
-- ===========================================================================

create table simulation.scenarios (
  id                  uuid primary key,
  organisation_id     uuid not null references iam.organisations (id),
  owner_membership_id uuid not null,
  name                text not null check (length(btrim(name)) > 0),
  kind                text not null check (kind in ('failure', 'branch')),
  stated_failure      jsonb,
  mode                text not null check (mode in ('deterministic', 'probabilistic')),
  bounds              jsonb not null,
  graph_version       bigint not null,
  archived_at         timestamptz,
  version             integer not null default 1,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),
  unique (organisation_id, id),
  foreign key (organisation_id, owner_membership_id) references iam.memberships (organisation_id, id),
  check ((stated_failure is not null) = (kind = 'failure'))
);
comment on table simulation.scenarios is
  'A saved failure or branch scenario, rerunnable on current data and graph. Private by default.';
comment on column simulation.scenarios.stated_failure is 'Failure form and the named objects, as identifiers only.';
comment on column simulation.scenarios.bounds is 'Hops, fan-out and iterations.';
comment on column simulation.scenarios.graph_version is 'Graph version when saved.';
create index scenarios_by_owner on simulation.scenarios (organisation_id, owner_membership_id, created_at desc)
  where archived_at is null;
select platform.enable_tenant_rls('simulation.scenarios');
select platform.add_updated_at_trigger('simulation.scenarios');

grant select, insert, update on simulation.scenarios to silo_app;
grant select on simulation.scenarios to silo_report;

create table simulation.scenario_branches (
  id              uuid primary key,
  organisation_id uuid not null references iam.organisations (id),
  scenario_id     uuid not null,
  name            text not null check (length(btrim(name)) > 0),
  created_by      uuid not null,
  status          text not null default 'open' check (status in ('open', 'promoted', 'partially_promoted', 'closed')),
  retention       interval not null check (retention >= interval '0 seconds'),
  closed_at       timestamptz,
  bases_purge_at  timestamptz,
  bases_purged_at timestamptz,
  version         integer not null default 1,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  unique (organisation_id, id),
  unique (organisation_id, scenario_id, name),
  foreign key (organisation_id, scenario_id) references simulation.scenarios (organisation_id, id),
  constraint scenario_branches_created_by_fkey
    foreign key (organisation_id, created_by) references iam.memberships (organisation_id, id),
  check (bases_purge_at is not distinct from closed_at + retention),
  check (bases_purged_at is null or bases_purge_at is not null)
);
comment on table simulation.scenario_branches is
  'A branch of clone state in which Actions are staged and never executed.';
comment on column simulation.scenario_branches.retention is
  'How long staged bases are kept after close. No default: the default is an open decision.';
comment on column simulation.scenario_branches.bases_purge_at is 'closed_at + retention, set at close.';
-- Retention sweep across organisations, run by silo_migrate: the one index in this
-- domain without a leading organisation_id.
create index scenario_branches_purge_due on simulation.scenario_branches (bases_purge_at)
  where bases_purge_at is not null and bases_purged_at is null;
select platform.enable_tenant_rls('simulation.scenario_branches');
select platform.add_updated_at_trigger('simulation.scenario_branches');

grant select, insert, update on simulation.scenario_branches to silo_app;
grant select on simulation.scenario_branches to silo_report;

create table simulation.simulation_runs (
  id                      uuid primary key,
  organisation_id         uuid not null references iam.organisations (id),
  scenario_id             uuid not null,
  branch_id               uuid,
  run_by_membership_id    uuid not null,
  mode                    text not null check (mode in ('deterministic', 'probabilistic')),
  iterations              integer check (iterations > 0),
  -- D72: the organisation had simulation inference on: paths lacking observations were inferred from priors.
  inferred                boolean not null default false,
  graph_version           bigint not null,
  status                  text not null default 'running' check (status in ('running', 'completed', 'failed')),
  started_at              timestamptz not null,
  completed_at            timestamptz,
  bounded_at_hop          integer,
  created_at              timestamptz not null default now(),
  unique (organisation_id, id),
  foreign key (organisation_id, scenario_id) references simulation.scenarios (organisation_id, id),
  foreign key (organisation_id, branch_id) references simulation.scenario_branches (organisation_id, id),
  constraint simulation_runs_run_by_fkey
    foreign key (organisation_id, run_by_membership_id) references iam.memberships (organisation_id, id),
  check ((mode = 'probabilistic') = (iterations is not null))
);
comment on table simulation.simulation_runs is
  'One execution of a scenario or branch against current data and graph, under the runner''s permissions.';
comment on column simulation.simulation_runs.bounded_at_hop is
  'Where propagation stopped at its hop bound, if it did. The charge is the billing.token_transactions row naming '
  'this run (simulation_run_id); the run holds no ledger id, since that row is written for it.';
create index simulation_runs_by_scenario on simulation.simulation_runs (organisation_id, scenario_id, started_at desc);
create index simulation_runs_by_branch on simulation.simulation_runs (organisation_id, branch_id, started_at desc)
  where branch_id is not null;
select platform.enable_tenant_rls('simulation.simulation_runs');

grant select, insert, update on simulation.simulation_runs to silo_app;
grant select on simulation.simulation_runs to silo_report;

create table simulation.simulation_results (
  id                      uuid primary key,
  organisation_id         uuid not null references iam.organisations (id),
  run_id                  uuid not null,
  result_kind             text not null check (result_kind in ('reached', 'stopped')),
  affected_object_type_id uuid,
  affected_object_key     text,
  via_soft_edge           boolean not null default false,
  path_mode               text not null check (path_mode in ('deterministic', 'probabilistic', 'inferred')),
  accumulated_delay       interval,
  -- Unavailable for a period (D83): how long the object is unavailable, the longer of the
  -- outage reaching it and its recovery lead time; null where it fails outright or is delayed.
  unavailable_for         interval,
  -- Capacity (D86): the share of this dependant's resource demand its resource cannot meet in
  -- the period, where demand exceeds the capacity left; null otherwise.
  capacity_shortfall      numeric check (capacity_shortfall > 0 and capacity_shortfall <= 1),
  capacity_period         text check (capacity_period in ('day', 'week', 'month')),
  delay_spread            jsonb,
  probability             numeric check (probability between 0 and 1),
  stop_reason             text check (stop_reason in ('unconfirmed_edge', 'bounded_hop', 'uncleared_object_type')),
  stop_edge_id            uuid,
  stop_object_type_id     uuid,
  stop_hop                integer check (stop_hop >= 0),
  created_at              timestamptz not null default now(),
  unique (organisation_id, id),
  foreign key (organisation_id, run_id) references simulation.simulation_runs (organisation_id, id),
  foreign key (organisation_id, stop_edge_id) references simulation.dependency_edges (organisation_id, id),
  check (result_kind <> 'reached' or (affected_object_type_id is not null and affected_object_key is not null)),
  check (path_mode in ('probabilistic', 'inferred') or (probability is null and delay_spread is null)),
  check ((result_kind = 'stopped') = (stop_reason is not null)),
  check (num_nonnulls(stop_edge_id, stop_object_type_id, stop_hop)
         = case result_kind when 'reached' then 0 else 1 end),
  check (stop_reason is distinct from 'unconfirmed_edge' or stop_edge_id is not null),
  check (stop_reason is distinct from 'uncleared_object_type' or stop_object_type_id is not null),
  check (stop_reason is distinct from 'bounded_hop' or stop_hop is not null)
);
comment on table simulation.simulation_results is
  'One affected object or stopping point reached by a run, with delay and probability. References only.';
comment on column simulation.simulation_results.affected_object_key is
  'Resolved-object identifier, the same identity key as recognition.finding_objects.object_key.';
comment on column simulation.simulation_results.accumulated_delay is 'For probabilistic paths, the median delay.';
create index simulation_results_by_run on simulation.simulation_results
  (organisation_id, run_id, affected_object_type_id, affected_object_key);
create index simulation_results_by_object on simulation.simulation_results
  (organisation_id, affected_object_type_id, affected_object_key, run_id);
create index simulation_results_stop_edge on simulation.simulation_results (organisation_id, stop_edge_id)
  where stop_edge_id is not null;
create index simulation_results_stop_object_type on simulation.simulation_results (organisation_id, stop_object_type_id)
  where stop_object_type_id is not null;
select platform.enable_tenant_rls('simulation.simulation_results');
select platform.make_append_only('simulation.simulation_results', true);

grant select, insert on simulation.simulation_results to silo_app;
grant select on simulation.simulation_results to silo_report;

create table simulation.simulation_result_edges (
  organisation_id uuid not null references iam.organisations (id),
  result_id       uuid not null,
  position        integer not null check (position >= 1),
  edge_id         uuid not null,
  edge_kind       text not null check (edge_kind in ('hard', 'soft', 'resource')),
  edge_source     text not null check (edge_source in ('structure', 'history', 'stated')),
  sample_size     integer check (sample_size >= 0),
  primary key (organisation_id, result_id, position),
  foreign key (organisation_id, result_id) references simulation.simulation_results (organisation_id, id),
  foreign key (organisation_id, edge_id) references simulation.dependency_edges (organisation_id, id),
  check (edge_source <> 'stated' or sample_size is null)
);
comment on table simulation.simulation_result_edges is
  'The ordered edges on the path to one result, with the kind and source of each at run time.';
comment on column simulation.simulation_result_edges.position is '1 is the edge leaving the origin.';
create index simulation_result_edges_edge on simulation.simulation_result_edges (organisation_id, edge_id);
select platform.enable_tenant_rls('simulation.simulation_result_edges');
select platform.make_append_only('simulation.simulation_result_edges', true);

grant select, insert on simulation.simulation_result_edges to silo_app;
grant select on simulation.simulation_result_edges to silo_report;

-- ===========================================================================
-- Staged Actions in a branch (39.8). No execution path exists from these tables.
-- ===========================================================================

create table simulation.staged_actions (
  id                   uuid primary key,
  organisation_id      uuid not null references iam.organisations (id),
  branch_id            uuid not null,
  sequence             integer not null check (sequence >= 1),
  action_type_id       uuid not null,
  manifest             jsonb not null,
  staleness            text not null default 'clean'
                         check (staleness in ('clean', 'conflicted', 'already_applied', 'orphaned')),
  conflicts            jsonb,
  manifest_values      bytea,
  staged_by            uuid not null,
  promoted_action_id   uuid,
  promoted_by          uuid,
  promoted_at          timestamptz,
  staleness_checked_at timestamptz,
  version              integer not null default 1,
  created_at           timestamptz not null default now(),
  updated_at           timestamptz not null default now(),
  unique (organisation_id, id),
  unique (organisation_id, branch_id, sequence),
  foreign key (organisation_id, branch_id) references simulation.scenario_branches (organisation_id, id),
  constraint staged_actions_staged_by_fkey
    foreign key (organisation_id, staged_by) references iam.memberships (organisation_id, id),
  constraint staged_actions_promoted_by_fkey
    foreign key (organisation_id, promoted_by) references iam.memberships (organisation_id, id),
  check (num_nonnulls(promoted_action_id, promoted_by, promoted_at) in (0, 3))
);
comment on table simulation.staged_actions is
  'An Action staged in a branch, with its manifest, staleness and promotion. Never executed from here.';
comment on column simulation.staged_actions.manifest is
  'Action type, targets as identifiers, parameter names and structure. No record values.';
comment on column simulation.staged_actions.conflicts is
  'Per property: name, who changed it where knowable, and the resolution chosen. Names and choices only.';
comment on column simulation.staged_actions.promoted_action_id is 'The real Action (mutation) created at promotion.';
comment on column simulation.staged_actions.manifest_values is
  'Encrypted (AES-256-GCM, organisation data key): the parameter values staged, for re-staging and promotion. '
  'Null once the branch''s bases are purged.';
create index staged_actions_action_type on simulation.staged_actions (organisation_id, action_type_id);
create index staged_actions_promoted on simulation.staged_actions (organisation_id, promoted_action_id)
  where promoted_action_id is not null;
select platform.enable_tenant_rls('simulation.staged_actions');
select platform.add_updated_at_trigger('simulation.staged_actions');

grant select, insert, update on simulation.staged_actions to silo_app;
grant select on simulation.staged_actions to silo_report;

create table simulation.staged_action_bases (
  id               uuid primary key,
  organisation_id  uuid not null references iam.organisations (id),
  staged_action_id uuid not null,
  object_type_id   uuid not null,
  object_key       text not null,
  connection_id    uuid not null,
  property         text not null,
  base_value       bytea,
  staged_value     bytea,
  read_at          timestamptz not null,
  purged_at        timestamptz,
  unique (organisation_id, id),
  constraint staged_action_bases_target_key
    unique (organisation_id, staged_action_id, connection_id, object_type_id, object_key, property),
  foreign key (organisation_id, staged_action_id) references simulation.staged_actions (organisation_id, id),
  check ((purged_at is null) = (base_value is not null)),
  check ((purged_at is null) = (staged_value is not null))
);
comment on table simulation.staged_action_bases is
  'Prior and staged value of each touched property on each target, for the three-way staleness check.';
comment on column simulation.staged_action_bases.base_value is
  'Record value. AES-256-GCM under the organisation data key. Never indexed or logged; null once purged.';
comment on column simulation.staged_action_bases.staged_value is
  'Record value the staged Action would write. Encrypted as base_value; null once purged.';
comment on column simulation.staged_action_bases.purged_at is
  'Set when branch retention ends or the connection is purged; both values are nulled in the same update.';
create index staged_action_bases_connection on simulation.staged_action_bases (organisation_id, connection_id);
create index staged_action_bases_object_type on simulation.staged_action_bases (organisation_id, object_type_id);
create index staged_action_bases_unpurged on simulation.staged_action_bases (organisation_id, staged_action_id)
  where purged_at is null;
select platform.enable_tenant_rls('simulation.staged_action_bases');

-- Purge is removal by status plus timestamp: setting purged_at nulls both values in
-- the same update, and a purged base can never be restored.
create function simulation.staged_action_bases_purge() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
begin
  if old.purged_at is not null and new.purged_at is distinct from old.purged_at then
    raise exception 'simulation.staged_action_bases: a purged base cannot be restored'
      using errcode = 'insufficient_privilege';
  end if;
  if new.purged_at is not null then
    new.base_value := null;
    new.staged_value := null;
  end if;
  return new;
end
$$;
create trigger staged_action_bases_purge before update on simulation.staged_action_bases
  for each row execute function simulation.staged_action_bases_purge();

grant select, insert, update on simulation.staged_action_bases to silo_app;
-- Reporting never needs the ciphertext.
grant select (id, organisation_id, staged_action_id, object_type_id, object_key, connection_id, property,
              read_at, purged_at)
  on simulation.staged_action_bases to silo_report;

-- ============================================================================
-- Domain: automation, files, fde
-- ============================================================================

-- Crons (automation), Files (files) and the AI FDE (fde).
-- Design: docs/siloDatabaseDesign.doc.md, "Recognition, scenarios, Crons and Files"
-- (schemas automation and files) and "08. AI FDE, Siloes, billing" (schema fde), with
-- review decisions D9, R8 and R15 (files.files.silo_file_id; object key, content type
-- and size for exports only), D4 (cell ids are text) and D11 (previous_value encrypted).
--
-- Foreign keys into other domains (workspace, ontology, connect, recognition, action,
-- simulation, siloes, clone, gov) are added by automation_files_fde_fks.sql once their
-- targets exist. Their supporting indexes are created here.
--
-- Not here: the refusal of an execute authorisation on a physical actuation Action type
-- (automation_actions, 40.5). It needs action.action_types and is enforced by the
-- scheduler until the actions domain can carry it.

-- ===========================================================================
-- Schema automation (chapter 40)
-- ===========================================================================

create table automation.automations (
  id                   uuid primary key,
  organisation_id      uuid not null references iam.organisations (id),
  owner_membership_id  uuid not null,
  service_principal_id uuid not null,
  name                 text not null check (length(btrim(name)) > 0),
  saved_view_id        uuid,
  object_set_id        uuid,
  schedule             text check (schedule ~ '^\S+(\s+\S+){4}$'),
  watch                jsonb check (jsonb_typeof(watch) = 'object'),
  timezone             text not null check (length(btrim(timezone)) > 0),
  status               text not null default 'active' check (status in ('active', 'paused', 'stopped')),
  paused_reason        text check (paused_reason in ('manual', 'repeated_failure', 'connection_halted',
                                                     'owner_removed', 'billing_suspended', 'authorisation_expired')),
  failure_policy       jsonb not null check (jsonb_typeof(failure_policy) = 'object'),
  next_run_at          timestamptz,
  lease_expires_at     timestamptz,
  last_run_at          timestamptz,
  paused_at            timestamptz,
  deleted_at           timestamptz,
  version              integer not null default 1,
  created_at           timestamptz not null default now(),
  updated_at           timestamptz not null default now(),
  unique (organisation_id, id),
  unique (organisation_id, service_principal_id),
  foreign key (organisation_id, owner_membership_id) references iam.memberships (organisation_id, id),
  foreign key (organisation_id, service_principal_id) references iam.service_principals (organisation_id, id),
  -- A saved question, an object set, or neither: a finding-only Cron (spec 40.3), on a schedule.
  check (num_nonnulls(saved_view_id, object_set_id) <= 1),
  check (num_nonnulls(schedule, watch) = 1),
  check (watch is null or object_set_id is not null),
  -- next_run_at: a schedule's next occurrence, or a watch's coalesced due time (spec 40.2).
  check (status <> 'paused' or paused_at is not null),
  check ((paused_reason is null) = (paused_at is null))
);
comment on table automation.automations is
  'A Cron: its subject, trigger, owner and the service principal it executes as.';
comment on column automation.automations.service_principal_id is
  'Principal of kind automation, one per Cron. Executes, never authorises.';
comment on column automation.automations.timezone is
  'IANA name of the organisation time zone; validated by the scheduler against pg_timezone_names.';
comment on column automation.automations.lease_expires_at is
  'Set by automation.claim_due_automations so two scheduler instances never take the same run.';
create unique index automations_owner_name on automation.automations (organisation_id, owner_membership_id, name)
  where deleted_at is null;
-- Cross-tenant due sweep, read only through automation.claim_due_automations.
create index automations_due on automation.automations (next_run_at, id)
  where status = 'active' and next_run_at is not null and deleted_at is null;
create index automations_saved_view on automation.automations (organisation_id, saved_view_id)
  where saved_view_id is not null;
create index automations_object_set on automation.automations (organisation_id, object_set_id)
  where object_set_id is not null;
create trigger automations_frozen before update on automation.automations
  for each row execute function platform.freeze_columns('id', 'organisation_id', 'service_principal_id');
select platform.add_updated_at_trigger('automation.automations');
select platform.enable_tenant_rls('automation.automations');

grant select, insert, update on automation.automations to silo_app;
grant select on automation.automations to silo_report;

