create table automation.automation_conditions (
  id                  uuid primary key,
  organisation_id     uuid not null references iam.organisations (id),
  automation_id       uuid not null,
  parent_condition_id uuid,
  kind                text not null check (kind in ('result', 'finding', 'value', 'composite')),
  detector_id         uuid,
  object_type_id      uuid,
  target              jsonb,
  operator            text,
  value               jsonb,
  combinator          text check (combinator in ('AND', 'OR')),
  sequence            integer not null check (sequence >= 0),
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),
  unique (organisation_id, id),
  constraint automation_conditions_sibling_order
    unique nulls not distinct (organisation_id, automation_id, parent_condition_id, sequence),
  foreign key (organisation_id, automation_id) references automation.automations (organisation_id, id),
  constraint automation_conditions_parent_fkey
    foreign key (organisation_id, parent_condition_id) references automation.automation_conditions (organisation_id, id),
  check (parent_condition_id is distinct from id),
  check ((kind = 'finding') = (detector_id is not null)),
  check ((kind = 'finding') = (object_type_id is not null)),
  check ((kind = 'composite') = (combinator is not null)),
  check (kind <> 'composite' or target is null),
  check (kind not in ('result', 'value') or target is not null),
  check ((kind = 'composite' and operator is null)
         or (kind = 'result' and operator in ('returned_rows', 'returned_none', 'count_crossed', 'differs_from_previous'))
         or (kind = 'finding' and operator in ('raised', 'score_above', 'recurred'))
         or (kind = 'value' and operator in ('above', 'below', 'changed_by_proportion', 'unchanged_for')))
);
comment on table automation.automation_conditions is
  'The condition tree of a Cron. No rows means a schedule that always fires.';
comment on column automation.automation_conditions.parent_condition_id is
  'Null for the root. A composite condition is the parent of its operands; at most three levels.';
create unique index automation_conditions_one_root on automation.automation_conditions (organisation_id, automation_id)
  where parent_condition_id is null;
create index automation_conditions_parent on automation.automation_conditions (organisation_id, parent_condition_id)
  where parent_condition_id is not null;
-- Crons affected when a detector or an object type is retired. The first also serves
-- the detector key (recognition.detectors is global).
create index automation_conditions_detector on automation.automation_conditions (organisation_id, detector_id, object_type_id)
  where kind = 'finding';
create index automation_conditions_object_type on automation.automation_conditions (organisation_id, object_type_id)
  where kind = 'finding';
create trigger automation_conditions_frozen before update on automation.automation_conditions
  for each row execute function platform.freeze_columns('id', 'organisation_id', 'automation_id');
select platform.add_updated_at_trigger('automation.automation_conditions');
select platform.enable_tenant_rls('automation.automation_conditions');

-- The parent is a composite condition of the same Cron, the tree is at most three
-- levels deep (40.3), and a move never creates a cycle.
create function automation.automation_conditions_check_tree() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
declare
  v_depth    integer := 1;
  v_cursor   uuid := new.parent_condition_id;
  v_parent   record;
  v_below    integer;
begin
  while v_cursor is not null loop
    if v_cursor = new.id then
      raise exception 'a condition cannot be its own ancestor' using errcode = 'check_violation';
    end if;
    select c.automation_id, c.kind, c.parent_condition_id into v_parent
    from automation.automation_conditions c
    where c.organisation_id = new.organisation_id and c.id = v_cursor;
    if not found then
      raise exception 'parent condition % not found', v_cursor using errcode = 'foreign_key_violation';
    end if;
    if v_cursor = new.parent_condition_id
       and (v_parent.automation_id <> new.automation_id or v_parent.kind <> 'composite') then
      raise exception 'the parent of a condition must be a composite condition of the same Cron'
        using errcode = 'check_violation';
    end if;
    v_depth := v_depth + 1;
    if v_depth > 3 then
      raise exception 'a condition tree is at most three levels deep' using errcode = 'check_violation';
    end if;
    v_cursor := v_parent.parent_condition_id;
  end loop;

  if tg_op = 'UPDATE' then
    with recursive below (id, level) as (
      select c.id, 1
      from automation.automation_conditions c
      where c.organisation_id = new.organisation_id and c.parent_condition_id = new.id
      union all
      select c.id, b.level + 1
      from automation.automation_conditions c
      join below b on c.organisation_id = new.organisation_id and c.parent_condition_id = b.id
      where b.level < 3)
    select coalesce(max(level), 0) into v_below from below;
    if v_below > 0 and new.kind <> 'composite' then
      raise exception 'a condition with operands must stay composite' using errcode = 'check_violation';
    end if;
    if v_depth + v_below > 3 then
      raise exception 'a condition tree is at most three levels deep' using errcode = 'check_violation';
    end if;
  end if;
  return new;
end
$$;
create trigger automation_conditions_check_tree before insert or update of parent_condition_id, kind
  on automation.automation_conditions
  for each row execute function automation.automation_conditions_check_tree();

grant select, insert, update on automation.automation_conditions to silo_app;
grant select on automation.automation_conditions to silo_report;

