create table automation.automation_authorisations (
  id               uuid primary key,
  organisation_id  uuid not null references iam.organisations (id),
  automation_id    uuid not null,
  mode             text not null check (mode in ('propose', 'execute')),
  max_rows         integer check (max_rows > 0 and max_rows < 10000),
  permitted_fields text[] check (array_position(permitted_fields, null) is null),
  authorised_by    uuid not null,
  expires_at       timestamptz,
  revoked_at       timestamptz,
  revoked_by       uuid,
  -- Set once by maintenance's sweep when an execute authorisation's expiry passes (D70): automation_authorisation_expired.
  expiry_recorded_at timestamptz,
  created_at       timestamptz not null default now(),
  unique (organisation_id, id),
  constraint automation_authorisations_automation_key unique (organisation_id, id, automation_id),
  constraint automation_authorisations_automation_fkey
    foreign key (organisation_id, automation_id) references automation.automations (organisation_id, id),
  constraint automation_authorisations_authorised_by_fkey
    foreign key (organisation_id, authorised_by) references iam.memberships (organisation_id, id),
  constraint automation_authorisations_revoked_by_fkey
    foreign key (organisation_id, revoked_by) references iam.memberships (organisation_id, id),
  check (mode <> 'execute'
         or (max_rows is not null and cardinality(permitted_fields) > 0 and expires_at is not null)),
  check (expires_at is null or expires_at > created_at),
  check (revoked_by is null or revoked_at is not null)
);
comment on table automation.automation_authorisations is
  'Bounds and the named authorising person for a mutate action. Set at creation; only revocation changes it.';
comment on column automation.automation_authorisations.max_rows is
  'Ten thousand or more is refused. The fall back to propose above one hundred rows is applied at run time.';
create index automation_authorisations_live on automation.automation_authorisations (organisation_id, automation_id)
  where revoked_at is null;
-- Cross-tenant expiry sweep, read only through automation.claim_expired_authorisations.
create index automation_authorisations_expiry on automation.automation_authorisations (expires_at)
  where mode = 'execute' and revoked_at is null;
select platform.enable_tenant_rls('automation.automation_authorisations');

create function automation.automation_authorisations_revoke_only() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
begin
  -- Revocation, and the record that an expiry passed (D70), are the only changes.
  if old.revoked_at is not null
     or (to_jsonb(new) - 'revoked_at' - 'revoked_by' - 'expiry_recorded_at') <> (to_jsonb(old) - 'revoked_at' - 'revoked_by' - 'expiry_recorded_at') then
    raise exception 'automation.automation_authorisations is immutable; only revocation is recorded'
      using errcode = 'insufficient_privilege';
  end if;
  return new;
end
$$;
create trigger automation_authorisations_revoke_only before update on automation.automation_authorisations
  for each row execute function automation.automation_authorisations_revoke_only();

grant select, insert, update (revoked_at, revoked_by, expiry_recorded_at) on automation.automation_authorisations to silo_app;
grant select on automation.automation_authorisations to silo_report;

