create table automation.automation_actions (
  id                     uuid primary key,
  organisation_id        uuid not null references iam.organisations (id),
  automation_id          uuid not null,
  kind                   text not null check (kind in ('notify', 'report', 'mutate', 'escalate')),
  configuration          jsonb not null check (jsonb_typeof(configuration) = 'object'),
  action_type_id         uuid,
  authorisation_id       uuid,
  escalate_membership_id uuid,
  escalate_scope_id      uuid,
  -- A mutate action's parameter values (40.5; D157): authored by the person attaching it, sealed
  -- to the row (they may be record values), opened only by actions when the Cron proposes.
  parameter_values       bytea,
  sequence               integer not null check (sequence >= 1),
  created_at             timestamptz not null default now(),
  updated_at             timestamptz not null default now(),
  unique (organisation_id, id),
  constraint automation_actions_sequence_key unique (organisation_id, automation_id, sequence),
  foreign key (organisation_id, automation_id) references automation.automations (organisation_id, id),
  constraint automation_actions_authorisation_fkey
    foreign key (organisation_id, authorisation_id, automation_id)
    references automation.automation_authorisations (organisation_id, id, automation_id),
  constraint automation_actions_escalate_membership_fkey
    foreign key (organisation_id, escalate_membership_id) references iam.memberships (organisation_id, id),
  constraint automation_actions_escalate_scope_fkey
    foreign key (organisation_id, escalate_scope_id) references iam.scopes (organisation_id, id),
  check ((kind = 'mutate') = (action_type_id is not null)),
  check ((kind = 'mutate') = (authorisation_id is not null)),
  check (kind = 'mutate' or parameter_values is null),
  check (num_nonnulls(escalate_membership_id, escalate_scope_id) = case when kind = 'escalate' then 1 else 0 end)
);
comment on table automation.automation_actions is
  'The ordered actions a Cron takes when its condition holds.';
comment on column automation.automation_actions.configuration is
  'Channel and recipient identifiers, report format and folder. Never record values.';
create index automation_actions_action_type on automation.automation_actions (organisation_id, action_type_id)
  where action_type_id is not null;
create index automation_actions_authorisation on automation.automation_actions (organisation_id, authorisation_id, automation_id)
  where authorisation_id is not null;
create index automation_actions_escalate_membership on automation.automation_actions (organisation_id, escalate_membership_id)
  where escalate_membership_id is not null;
create index automation_actions_escalate_scope on automation.automation_actions (organisation_id, escalate_scope_id)
  where escalate_scope_id is not null;
create trigger automation_actions_frozen before update on automation.automation_actions
  for each row execute function platform.freeze_columns('id', 'organisation_id', 'automation_id');
