create table automation.automation_runs (
  id                          uuid primary key,
  organisation_id             uuid not null references iam.organisations (id),
  automation_id               uuid not null,
  trigger_kind                text not null check (trigger_kind in ('schedule', 'change', 'manual')),
  status                      text not null default 'running'
                                check (status in ('running', 'completed', 'failed', 'skipped')),
  started_at                  timestamptz not null,
  completed_at                timestamptz,
  condition_outcome           text check (condition_outcome in ('met', 'not_met', 'indeterminate')),
  authorised_by_membership_id uuid,
  change_count                bigint,
  error                       text,
  skipped_reason              text check (skipped_reason in ('overlap', 'connection_halted', 'owner_unavailable',
                                                               'authorisation_expired', 'billing_suspended', 'stream_gap',
                                                               'tenant_migration')),
  created_at                  timestamptz not null default now(),
  unique (organisation_id, id),
  foreign key (organisation_id, automation_id) references automation.automations (organisation_id, id),
  constraint automation_runs_authorised_by_fkey
    foreign key (organisation_id, authorised_by_membership_id) references iam.memberships (organisation_id, id),
  check ((status = 'running') = (completed_at is null)),
  check (completed_at is null or completed_at >= started_at),
  check (status not in ('running', 'skipped') or condition_outcome is null),
  check ((status = 'skipped') = (skipped_reason is not null)),
  check (change_count is null or (trigger_kind = 'change' and change_count >= 0))
);
comment on table automation.automation_runs is
  'Every run of a Cron, including runs where the condition did not hold, skipped and indeterminate runs.';
comment on column automation.automation_runs.authorised_by_membership_id is
  'For execute runs, the authorising person, recorded on every run (40.5).';
comment on column automation.automation_runs.error is 'Redacted. Never a record value.';
-- Overlap guard (40.7): a second concurrent run of a Cron cannot start.
create unique index automation_runs_one_running on automation.automation_runs (organisation_id, automation_id)
  where status = 'running';
create index automation_runs_history on automation.automation_runs (organisation_id, automation_id, started_at desc);
create index automation_runs_met on automation.automation_runs (organisation_id, started_at desc)
  where condition_outcome = 'met';
select platform.enable_tenant_rls('automation.automation_runs');
create trigger automation_runs_frozen before update on automation.automation_runs
  for each row execute function platform.freeze_columns(
    'id', 'organisation_id', 'automation_id', 'trigger_kind', 'started_at', 'created_at');

create function automation.automation_runs_reject_completed() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
begin
  raise exception 'automation run % is %; a finished run is immutable', old.id, old.status
    using errcode = 'insufficient_privilege';
end
$$;
create trigger automation_runs_immutable_once_finished before update on automation.automation_runs
  for each row when (old.status <> 'running')
  execute function automation.automation_runs_reject_completed();

grant select, insert, update on automation.automation_runs to silo_app;
grant select on automation.automation_runs to silo_report;

