create table automation.automation_run_actions (
  id                      uuid primary key,
  organisation_id         uuid not null references iam.organisations (id),
  run_id                  uuid not null,
  action_id               uuid not null,
  action_kind             text not null check (action_kind in ('notify', 'report', 'mutate', 'escalate')),
  sequence                integer not null check (sequence >= 1),
  outcome                 text not null check (outcome in ('succeeded', 'failed', 'skipped', 'proposed',
                                                           'executed', 'delivered')),
  result_counts           jsonb check (jsonb_typeof(result_counts) = 'object'),
  mutation_id             uuid,
  file_id                 uuid,
  escalated_membership_id uuid,
  escalated_scope_id      uuid,
  acknowledged_by         uuid,
  acknowledged_at         timestamptz,
  error                   text,
  created_at              timestamptz not null default now(),
  unique (organisation_id, id),
  unique (organisation_id, run_id, sequence),
  foreign key (organisation_id, run_id) references automation.automation_runs (organisation_id, id),
  foreign key (organisation_id, action_id) references automation.automation_actions (organisation_id, id),
  constraint automation_run_actions_escalated_membership_fkey
    foreign key (organisation_id, escalated_membership_id) references iam.memberships (organisation_id, id),
  constraint automation_run_actions_escalated_scope_fkey
    foreign key (organisation_id, escalated_scope_id) references iam.scopes (organisation_id, id),
  constraint automation_run_actions_acknowledged_by_fkey
    foreign key (organisation_id, acknowledged_by) references iam.memberships (organisation_id, id),
  check (num_nonnulls(mutation_id, file_id) <= 1),
  check (mutation_id is null or action_kind = 'mutate'),
  check (file_id is null or action_kind = 'report'),
  check (num_nonnulls(escalated_membership_id, escalated_scope_id) = case when action_kind = 'escalate' then 1 else 0 end),
  check (acknowledged_by is null or action_kind = 'escalate'),
  check ((acknowledged_by is null) = (acknowledged_at is null))
);
comment on table automation.automation_run_actions is
  'Outcome of each action in a run, its artefact, and the acknowledgement of escalations.';
comment on column automation.automation_run_actions.result_counts is 'Counts only, never record values.';
comment on column automation.automation_run_actions.error is 'Redacted. Never a record value.';
create index automation_run_actions_action on automation.automation_run_actions (organisation_id, action_id);
-- Open escalations on Home and Governance until acknowledged.
create index automation_run_actions_open_by_membership
  on automation.automation_run_actions (organisation_id, escalated_membership_id, created_at desc)
  where action_kind = 'escalate' and acknowledged_at is null;
create index automation_run_actions_open_by_scope
  on automation.automation_run_actions (organisation_id, escalated_scope_id, created_at desc)
  where action_kind = 'escalate' and acknowledged_at is null;
create index automation_run_actions_mutation on automation.automation_run_actions (organisation_id, mutation_id)
  where mutation_id is not null;
create index automation_run_actions_file on automation.automation_run_actions (organisation_id, file_id)
  where file_id is not null;
select platform.enable_tenant_rls('automation.automation_run_actions');

-- Written by the scheduler; only the escalation acknowledgement changes afterwards.
grant select, insert, update (acknowledged_by, acknowledged_at) on automation.automation_run_actions to silo_app;
grant select on automation.automation_run_actions to silo_report;

