-- One row per Cron. The design keys it by automation_id with unique
-- (organisation_id, automation_id); the primary key leads with organisation_id
-- instead (build rules: a tenant table without id). automation_id stays unique
-- because automations.id is.
create table automation.automation_run_state (
  organisation_id      uuid not null references iam.organisations (id),
  automation_id        uuid not null,
  previous_result_hash bytea check (octet_length(previous_result_hash) = 32),
  previous_row_count   bigint check (previous_row_count >= 0),
  previous_value       bytea,
  follow_up_pending    boolean not null default false,
  consecutive_failures integer not null default 0 check (consecutive_failures >= 0),
  findings_checked_at  timestamptz,
  updated_at           timestamptz not null default now(),
  primary key (organisation_id, automation_id),
  foreign key (organisation_id, automation_id) references automation.automations (organisation_id, id)
);
comment on table automation.automation_run_state is
  'Minimum state kept between runs for "differs from previous", value and change conditions.';
comment on column automation.automation_run_state.previous_result_hash is
  'HMAC of the previous result under the organisation HMAC key. Never the rows.';
comment on column automation.automation_run_state.previous_value is
  'Record value: AES-256-GCM under the organisation data key. Never indexed, never logged.';
comment on column automation.automation_run_state.findings_checked_at is
  'When the last run read the findings its finding conditions name (40.3): a finding raised after it is new to the next run.';
comment on column automation.automation_run_state.follow_up_pending is
  'At most one pending follow-up for changes arriving during a run (40.2).';
create trigger automation_run_state_frozen before update on automation.automation_run_state
  for each row execute function platform.freeze_columns('organisation_id', 'automation_id');
select platform.add_updated_at_trigger('automation.automation_run_state');
select platform.enable_tenant_rls('automation.automation_run_state');

grant select, insert, update on automation.automation_run_state to silo_app;
grant select (organisation_id, automation_id, previous_result_hash, previous_row_count, follow_up_pending,
              consecutive_failures, findings_checked_at, updated_at)
  on automation.automation_run_state to silo_report;

-- ---------------------------------------------------------------------------
-- Cross-tenant sweeps. The scheduler cannot read across organisations under RLS;
-- these return only the identifiers it needs, after which it sets app.org_id per
-- row and works under RLS. Owned by silo_migrate.

-- Claims due Crons: returns them and sets the lease in the same statement, so two
-- scheduler instances never take the same run. A claim lasts five minutes; the
-- scheduler sets the next due time and clears the lease when it starts the run.
create function automation.claim_due_automations(batch_size integer, now timestamptz)
returns table (organisation_id uuid, id uuid, next_run_at timestamptz)
language plpgsql
security definer
set search_path = pg_catalog
as $$
#variable_conflict use_column
begin
  if claim_due_automations.batch_size is null or claim_due_automations.batch_size not between 1 and 1000 then
    raise exception 'batch_size must be between 1 and 1000' using errcode = 'invalid_parameter_value';
  end if;
  if claim_due_automations.now is null then
    raise exception 'now must be given' using errcode = 'invalid_parameter_value';
  end if;
  return query
  with due as (
    select a.organisation_id, a.id
    from automation.automations a
    where a.status = 'active' and a.next_run_at is not null and a.deleted_at is null
      and a.next_run_at <= claim_due_automations.now
      and (a.lease_expires_at is null or a.lease_expires_at <= claim_due_automations.now)
    order by a.next_run_at, a.id
    limit claim_due_automations.batch_size
    for update of a skip locked
  )
  update automation.automations a
     set lease_expires_at = claim_due_automations.now + interval '5 minutes'
    from due
   where a.organisation_id = due.organisation_id and a.id = due.id
  returning a.organisation_id, a.id, a.next_run_at;
end
$$;

-- Finds execute authorisations past their expiry and locks them for the caller's
-- transaction, in which the scheduler records the expiry under RLS
-- (automation_authorisation_expired) and returns the mutate actions to propose.
create function automation.claim_expired_authorisations(batch_size integer, now timestamptz)
returns table (organisation_id uuid, id uuid, automation_id uuid)
language plpgsql
security definer
set search_path = pg_catalog
as $$
#variable_conflict use_column
begin
  if claim_expired_authorisations.batch_size is null
     or claim_expired_authorisations.batch_size not between 1 and 1000 then
    raise exception 'batch_size must be between 1 and 1000' using errcode = 'invalid_parameter_value';
  end if;
  if claim_expired_authorisations.now is null then
    raise exception 'now must be given' using errcode = 'invalid_parameter_value';
  end if;
  return query
  select a.organisation_id, a.id, a.automation_id
  from automation.automation_authorisations a
  where a.mode = 'execute' and a.revoked_at is null
    and a.expires_at <= claim_expired_authorisations.now
  order by a.expires_at, a.id
  limit claim_expired_authorisations.batch_size
  for update of a skip locked;
end
$$;

grant execute on function automation.claim_due_automations(integer, timestamptz),
                          automation.claim_expired_authorisations(integer, timestamptz)
  to silo_app;

-- Crons watching an object set (spec 40.2), across organisations: identifiers only, for the
-- scheduler's watcher, which reads each under its own organisation.
create function automation.watching_automations(p_limit integer)
  returns table (organisation_id uuid, id uuid)
language sql stable security definer
set search_path = pg_catalog
as $$
  select a.organisation_id, a.id from automation.automations a
  where a.watch is not null and a.status = 'active' and a.deleted_at is null
  order by a.id
  limit least(greatest(p_limit, 1), 1000)
$$;
revoke all on function automation.watching_automations(integer) from public;
grant execute on function automation.watching_automations(integer) to silo_app;

