create table files.folders (
  id              uuid primary key,
  organisation_id uuid not null references iam.organisations (id),
  name            text not null check (length(btrim(name)) > 0),
  parent_id       uuid,
  path            ltree not null,
  created_by      uuid not null,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  unique (organisation_id, id),
  unique nulls not distinct (organisation_id, parent_id, name),
  foreign key (organisation_id, parent_id) references files.folders (organisation_id, id),
  constraint folders_created_by_fkey
    foreign key (organisation_id, created_by) references iam.memberships (organisation_id, id),
  check (parent_id is distinct from id)
);
comment on table files.folders is
  'An arrangement tree for files. It grants nothing and never shows a file count.';
comment on column files.folders.path is
  'Ancestor chain. Each label is the folder id as 32 hex characters, so a rename never '
  'rewrites paths. Maintained by trigger; never written by the application.';
create index folders_path on files.folders using gist (organisation_id, path);
create trigger folders_frozen before update on files.folders
  for each row execute function platform.freeze_columns('id', 'organisation_id');
select platform.add_updated_at_trigger('files.folders');
select platform.enable_tenant_rls('files.folders');

create function files.folders_maintain_path() returns trigger
language plpgsql
set search_path = pg_catalog, public
as $$
declare
  v_parent_path ltree;
begin
  if tg_op = 'INSERT' or new.parent_id is distinct from old.parent_id then
    if new.parent_id is null then
      new.path := text2ltree(replace(new.id::text, '-', ''));
    else
      select f.path into v_parent_path
      from files.folders f
      where f.organisation_id = new.organisation_id and f.id = new.parent_id;
      if v_parent_path is null then
        raise exception 'parent folder % not found', new.parent_id using errcode = 'foreign_key_violation';
      end if;
      if tg_op = 'UPDATE' and v_parent_path <@ old.path then
        raise exception 'a folder cannot move under its own descendant' using errcode = 'check_violation';
      end if;
      new.path := v_parent_path || text2ltree(replace(new.id::text, '-', ''));
    end if;
  elsif new.path is distinct from old.path then
    -- Only the descendant rewrite below (a nested trigger) may change a path.
    if pg_trigger_depth() < 2 then
      raise exception 'folder path is maintained by the database' using errcode = 'insufficient_privilege';
    end if;
  end if;
  return new;
end
$$;
create trigger folders_maintain_path before insert or update on files.folders
  for each row execute function files.folders_maintain_path();

-- A move rewrites the prefix of every descendant in the same transaction.
create function files.folders_move_descendants() returns trigger
language plpgsql
set search_path = pg_catalog, public
as $$
begin
  update files.folders f
     set path = new.path || subpath(f.path, nlevel(old.path))
   where f.organisation_id = new.organisation_id
     and f.path <@ old.path
     and f.id <> new.id;
  return null;
end
$$;
create trigger folders_move_descendants after update of parent_id on files.folders
  for each row when (old.parent_id is distinct from new.parent_id)
  execute function files.folders_move_descendants();

grant select, insert, update on files.folders to silo_app;
grant select on files.folders to silo_report;

