create table files.files (
  id               uuid primary key,
  organisation_id  uuid not null references iam.organisations (id),
  folder_id        uuid,
  kind             text not null check (kind in ('export', 'upload')),
  name             text not null check (length(btrim(name)) > 0),
  object_store_key text,
  content_type     text,
  size             bigint check (size >= 0),
  silo_file_id     uuid,
  ingestion_state  text check (ingestion_state in ('stored', 'ingested')),
  status           text not null default 'available' check (status in ('available', 'deleted')),
  retention        interval check (retention > interval '0'),
  expires_at       timestamptz,
  deleted_at       timestamptz,
  created_by       uuid not null,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  unique (organisation_id, id),
  foreign key (organisation_id, folder_id) references files.folders (organisation_id, id),
  constraint files_created_by_fkey
    foreign key (organisation_id, created_by) references iam.memberships (organisation_id, id),
  -- Review R8, R15: the object key, content type and size are an export's. An
  -- upload's bytes, type and size live at siloes.silo_files.
  check ((kind = 'export') = (object_store_key is not null)),
  check ((kind = 'export') = (content_type is not null)),
  check ((kind = 'export') = (size is not null)),
  check ((kind = 'upload') = (silo_file_id is not null)),
  check ((kind = 'upload') = (ingestion_state is not null)),
  check ((status = 'deleted') = (deleted_at is not null)),
  check ((retention is null) = (expires_at is null))
);
comment on table files.files is
  'The Files catalogue entry for an export or an upload, with its markings and retention.';
comment on column files.files.content_type is 'Detected from the bytes, not the declared header.';
comment on column files.files.silo_file_id is
  'The stored object of an upload (review D9). Its Silo is siloes.silo_files.silo_id.';
comment on column files.files.retention is 'Null is indefinite. For uploads, the Silo''s window.';
comment on column files.files.expires_at is
  'created_at + retention; recomputed when the Silo window is shortened. Null when indefinite.';
create unique index files_object_store_key on files.files (organisation_id, object_store_key)
  where object_store_key is not null;
create index files_folder_contents on files.files (organisation_id, folder_id, created_at desc)
  where status = 'available';
create index files_silo_file on files.files (organisation_id, silo_file_id)
  where silo_file_id is not null;
-- Cross-tenant retention sweep, run by silo_migrate.
create index files_retention_due on files.files (expires_at)
  where status = 'available' and expires_at is not null;
create trigger files_frozen before update on files.files
  for each row execute function platform.freeze_columns(
    'id', 'organisation_id', 'kind', 'object_store_key', 'content_type', 'size', 'silo_file_id',
    'created_by', 'created_at');
select platform.add_updated_at_trigger('files.files');
select platform.enable_tenant_rls('files.files');

-- A deleted file is the anchor of its deletion receipt and never changes again.
create function files.files_reject_deleted_change() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
begin
  raise exception 'file % is deleted; the row is immutable', old.id using errcode = 'insufficient_privilege';
end
$$;
create trigger files_deleted_is_final before update on files.files
  for each row when (old.status = 'deleted')
  execute function files.files_reject_deleted_change();

grant select, insert, update on files.files to silo_app;
grant select on files.files to silo_report;

-- The retention sweep's claim across organisations (spec 41.5): identifiers only, locked.
create function files.claim_expired_files(batch_size integer, now timestamptz)
returns table (organisation_id uuid, id uuid, created_by uuid)
language plpgsql
security definer
set search_path = pg_catalog
as $$
#variable_conflict use_column
begin
  if claim_expired_files.batch_size is null or claim_expired_files.batch_size not between 1 and 1000 then
    raise exception 'batch_size must be between 1 and 1000' using errcode = 'invalid_parameter_value';
  end if;
  return query
  select f.organisation_id, f.id, f.created_by
  from files.files f
  -- Exports only: an upload carries its Silo's window, and goes with its Silo file's purge.
  where f.kind = 'export' and f.status = 'available' and f.expires_at is not null and f.expires_at <= claim_expired_files.now
  order by f.expires_at, f.id
  limit claim_expired_files.batch_size
  for update of f skip locked;
end
$$;
grant execute on function files.claim_expired_files(integer, timestamptz) to silo_app;

