create table files.file_provenance (
  organisation_id          uuid not null references iam.organisations (id),
  file_id                  uuid not null,
  source_saved_view_id     uuid,
  source_finding_id        uuid,
  source_detector_run_id   uuid,
  source_receipt_id        uuid,
  source_simulation_run_id uuid,
  source_automation_run_id uuid,
  -- A Clone Canvas view exported as a drawing (spec 29.10).
  source_canvas_view_id    uuid,
  -- A lineage graph a reviewer exported (spec 59.4, 59.7): the node the walk began at.
  source_lineage_node_id   uuid,
  -- A Studio app version exported as a package for another organisation (D231).
  source_app_version_id    uuid,
  -- A workbook exported with its values computed (D232).
  source_workbook_id       uuid,
  -- A report exported as a document (D233).
  source_report_id         uuid,
  -- A process analysis exported as a document (D234).
  source_process_analysis_id uuid,
  -- A notebook exported with its tables computed (D239).
  source_notebook_id       uuid,
  source_kind              text not null generated always as (
                             case
                               when source_saved_view_id is not null then 'view'
                               when source_finding_id is not null then 'finding'
                               when source_detector_run_id is not null then 'ranking'
                               when source_receipt_id is not null then 'receipt'
                               when source_simulation_run_id is not null then 'scenario_run'
                               when source_automation_run_id is not null then 'cron_report'
                               when source_canvas_view_id is not null then 'canvas_view'
                               when source_lineage_node_id is not null then 'lineage'
                               when source_app_version_id is not null then 'app_package'
                               when source_workbook_id is not null then 'workbook'
                               when source_report_id is not null then 'report'
                               when source_process_analysis_id is not null then 'process_analysis'
                               when source_notebook_id is not null then 'notebook'
                             end) stored
                             check (source_kind in ('view', 'finding', 'ranking', 'receipt', 'scenario_run',
                                                    'cron_report', 'canvas_view', 'lineage', 'app_package', 'workbook', 'report',
                                                    'process_analysis', 'notebook')),
  run_reference            uuid,
  produced_at              timestamptz not null,
  primary key (organisation_id, file_id),
  foreign key (organisation_id, file_id) references files.files (organisation_id, id),
  constraint file_provenance_source_automation_run_fkey
    foreign key (organisation_id, source_automation_run_id) references automation.automation_runs (organisation_id, id),
  constraint file_provenance_source_lineage_node_fkey
    foreign key (organisation_id, source_lineage_node_id) references gov.lineage_nodes (organisation_id, id),
  constraint file_provenance_source_app_version_fkey
    foreign key (organisation_id, source_app_version_id) references workspace.app_versions (organisation_id, id),
  constraint file_provenance_source_workbook_fkey
    foreign key (organisation_id, source_workbook_id) references workspace.workbooks (organisation_id, id),
  constraint file_provenance_source_report_fkey
    foreign key (organisation_id, source_report_id) references workspace.reports (organisation_id, id),
  constraint file_provenance_source_process_analysis_fkey
    foreign key (organisation_id, source_process_analysis_id) references workspace.process_analyses (organisation_id, id),
  constraint file_provenance_source_notebook_fkey
    foreign key (organisation_id, source_notebook_id) references workspace.notebooks (organisation_id, id),
  check (num_nonnulls(source_saved_view_id, source_finding_id, source_detector_run_id, source_receipt_id,
                      source_simulation_run_id, source_automation_run_id, source_canvas_view_id,
                      source_lineage_node_id, source_app_version_id, source_workbook_id, source_report_id,
                      source_process_analysis_id, source_notebook_id) = 1)
);
comment on table files.file_provenance is
  'Which source and run produced a file, when; kept after the source is removed.';
comment on column files.file_provenance.source_detector_run_id is
  'A ranking export, sourced to the detector run whose findings were ranked.';
comment on column files.file_provenance.run_reference is
  'Opaque id of the executed query run (view, finding and receipt exports). No foreign key: data plane. Null for a lineage export, which runs no query.';
create index file_provenance_saved_view on files.file_provenance (organisation_id, source_saved_view_id)
  where source_saved_view_id is not null;
create index file_provenance_finding on files.file_provenance (organisation_id, source_finding_id)
  where source_finding_id is not null;
create index file_provenance_detector_run on files.file_provenance (organisation_id, source_detector_run_id)
  where source_detector_run_id is not null;
create index file_provenance_receipt on files.file_provenance (organisation_id, source_receipt_id)
  where source_receipt_id is not null;
create index file_provenance_simulation_run on files.file_provenance (organisation_id, source_simulation_run_id)
  where source_simulation_run_id is not null;
create index file_provenance_canvas_view on files.file_provenance (organisation_id, source_canvas_view_id)
  where source_canvas_view_id is not null;
create index file_provenance_lineage_node on files.file_provenance (organisation_id, source_lineage_node_id)
  where source_lineage_node_id is not null;
create index file_provenance_app_version on files.file_provenance (organisation_id, source_app_version_id)
  where source_app_version_id is not null;
create index file_provenance_workbook on files.file_provenance (organisation_id, source_workbook_id)
  where source_workbook_id is not null;
create index file_provenance_report on files.file_provenance (organisation_id, source_report_id)
  where source_report_id is not null;
create index file_provenance_process_analysis on files.file_provenance (organisation_id, source_process_analysis_id)
  where source_process_analysis_id is not null;
create index file_provenance_notebook on files.file_provenance (organisation_id, source_notebook_id)
