create table files.file_shares (
  id                         uuid primary key,
  organisation_id            uuid not null references iam.organisations (id),
  file_id                    uuid not null,
  grantee_membership_id      uuid,
  grantee_scope_id           uuid,
  grantee_whole_organisation boolean check (grantee_whole_organisation),
  access                     text not null check (access in ('view', 'download')),
  shared_by                  uuid not null,
  expires_at                 timestamptz,
  revoked_at                 timestamptz,
  revoked_by                 uuid,
  created_at                 timestamptz not null default now(),
  unique (organisation_id, id),
  foreign key (organisation_id, file_id) references files.files (organisation_id, id),
  constraint file_shares_grantee_membership_fkey
    foreign key (organisation_id, grantee_membership_id) references iam.memberships (organisation_id, id),
  constraint file_shares_grantee_scope_fkey
    foreign key (organisation_id, grantee_scope_id) references iam.scopes (organisation_id, id),
  constraint file_shares_shared_by_fkey
    foreign key (organisation_id, shared_by) references iam.memberships (organisation_id, id),
  constraint file_shares_revoked_by_fkey
    foreign key (organisation_id, revoked_by) references iam.memberships (organisation_id, id),
  check (num_nonnulls(grantee_membership_id, grantee_scope_id, grantee_whole_organisation) = 1),
  check (expires_at is null or expires_at > created_at),
  check (revoked_by is null or revoked_at is not null)
);
comment on table files.file_shares is
  'A share of a file with a membership, a scope or the organisation. Never grants a marking or Silo access.';
comment on column files.file_shares.grantee_whole_organisation is 'True or null.';
create unique index file_shares_live_membership on files.file_shares (organisation_id, file_id, grantee_membership_id)
  where revoked_at is null and grantee_membership_id is not null;
create unique index file_shares_live_scope on files.file_shares (organisation_id, file_id, grantee_scope_id)
  where revoked_at is null and grantee_scope_id is not null;
create unique index file_shares_live_organisation on files.file_shares (organisation_id, file_id)
  where revoked_at is null and grantee_whole_organisation;
-- "Shared with me".
create index file_shares_by_membership on files.file_shares (organisation_id, grantee_membership_id)
  where revoked_at is null and grantee_membership_id is not null;
create index file_shares_by_scope on files.file_shares (organisation_id, grantee_scope_id)
  where revoked_at is null and grantee_scope_id is not null;
select platform.enable_tenant_rls('files.file_shares');
create trigger file_shares_frozen before update on files.file_shares
  for each row execute function platform.freeze_columns(
    'id', 'organisation_id', 'file_id', 'grantee_membership_id', 'grantee_scope_id',
    'grantee_whole_organisation', 'shared_by', 'created_at');

