-- The six limits of 52.5, exactly, each a positive integer.
create function fde.rate_limits_valid(p_limits jsonb) returns boolean
language plpgsql
immutable parallel safe
set search_path = pg_catalog
as $$
declare
  v_keys  constant text[] := array['model_calls_per_minute', 'probes_per_minute', 'proposals_per_hour',
                                   'concurrent_tasks', 'pending_proposals_per_decider', 'attempts_per_task'];
  v_key   text;
  v_value jsonb;
begin
  if p_limits is null or jsonb_typeof(p_limits) <> 'object' then
    return false;
  end if;
  if not (p_limits ?& v_keys) then
    return false;
  end if;
  if (select count(*) from jsonb_object_keys(p_limits)) <> cardinality(v_keys) then
    return false;
  end if;
  foreach v_key in array v_keys loop
    v_value := p_limits -> v_key;
    if jsonb_typeof(v_value) <> 'number' then
      return false;
    end if;
    if v_value::numeric <= 0 or v_value::numeric <> trunc(v_value::numeric) or v_value::numeric > 2147483647 then
      return false;
    end if;
  end loop;
  return true;
end
$$;

-- 52.4: a proposal without evidence of a known type is rejected by constraint.
create function fde.evidence_valid(p_evidence jsonb) returns boolean
language plpgsql
immutable parallel safe
set search_path = pg_catalog
as $$
declare
  v_item jsonb;
begin
  if p_evidence is null or jsonb_typeof(p_evidence) <> 'array' then
    return false;
  end if;
  if jsonb_array_length(p_evidence) < 1 then
    return false;
  end if;
  for v_item in select e.value from jsonb_array_elements(p_evidence) as e (value) loop
    if jsonb_typeof(v_item) <> 'object' then
      return false;
    end if;
    if coalesce(v_item ->> 'type', '') not in ('foreign_key', 'field_profile', 'value_overlap', 'documentation',
                                               'probe', 'sandbox_cycle', 'history', 'organisation_statement') then
      return false;
    end if;
  end loop;
  return true;
end
$$;

-- Check constraints run with the writer's privileges.
grant execute on function fde.rate_limits_valid(jsonb), fde.evidence_valid(jsonb) to silo_app;

