create table fde.fde_engagements (
  id                                 uuid primary key,
  organisation_id                    uuid not null references iam.organisations (id),
  name                               text not null check (length(btrim(name)) > 0),
  goals                              text not null check (length(btrim(goals)) > 0),
  engaging_membership_id             uuid not null,
  -- The customer's named engagement owner, who alone confirms stage exits (decision 2026-11-14;
  -- D80); null is the engaging administrator. Never the supervising engineer.
  owner_membership_id                uuid,
  supervising_engineer_membership_id uuid,
  scope_id                           uuid,
  engagement_class                   text not null check (engagement_class in ('standard', 'enterprise', 'sovereign',
                                                                                'regulated')),
  cell_id                            text not null references platform.cells (id),
  status                             text not null default 'active'
                                       check (status in ('active', 'paused', 'stopped', 'handed_over', 'closed')),
  current_stage                      integer not null default 0 check (current_stage between 0 and 9),
  token_budget                       bigint not null check (token_budget >= 0),
  tokens_consumed                    bigint not null default 0 check (tokens_consumed >= 0),
  provider_cost_budget               numeric(14,4) not null check (provider_cost_budget >= 0),
  provider_cost_consumed             numeric(14,4) not null default 0 check (provider_cost_consumed >= 0),
  rate_limits                        jsonb not null check (fde.rate_limits_valid(rate_limits)),
  model_route                        text not null check (length(btrim(model_route)) > 0),
  started_at                         timestamptz not null,
  agent_installed_at                 timestamptz,
  paused_at                          timestamptz,
  stopped_at                         timestamptz,
  stopped_by                         uuid,
  stop_reason                        text,
  handed_over_at                     timestamptz,
  handed_over_to                     uuid,
  closed_at                          timestamptz,
  predecessor_engagement_id          uuid,
  created_at                         timestamptz not null default now(),
  updated_at                         timestamptz not null default now(),
  version                            bigint not null default 1,
  unique (organisation_id, id),
  constraint fde_engagements_predecessor_fkey
    foreign key (organisation_id, predecessor_engagement_id) references fde.fde_engagements (organisation_id, id),
  check (predecessor_engagement_id is distinct from id),
  check (owner_membership_id is null or owner_membership_id is distinct from supervising_engineer_membership_id),
  foreign key (organisation_id, owner_membership_id) references iam.memberships (organisation_id, id),
  constraint fde_engagements_engaging_membership_fkey
    foreign key (organisation_id, engaging_membership_id) references iam.memberships (organisation_id, id),
  constraint fde_engagements_supervising_engineer_fkey
    foreign key (organisation_id, supervising_engineer_membership_id) references iam.memberships (organisation_id, id),
  constraint fde_engagements_stopped_by_fkey
    foreign key (organisation_id, stopped_by) references iam.memberships (organisation_id, id),
  constraint fde_engagements_handed_over_to_fkey
    foreign key (organisation_id, handed_over_to) references iam.memberships (organisation_id, id),
  foreign key (organisation_id, scope_id) references iam.scopes (organisation_id, id),
  check (num_nonnulls(stopped_at, stopped_by, stop_reason) in (0, 3)),
  check (status <> 'stopped' or stopped_at is not null),
  check (num_nonnulls(handed_over_at, handed_over_to) in (0, 2)),
  check (status <> 'handed_over' or handed_over_at is not null),
  check (status <> 'closed' or closed_at is not null),
  check (status <> 'paused' or paused_at is not null),
  check (status <> 'active' or paused_at is null)
);
comment on table fde.fde_engagements is
  'One bounded AI FDE deployment in one organisation: ceiling holder, budgets, limits and lifecycle.';
comment on column fde.fde_engagements.goals is
  'The organisation''s own description, sent to the model as vocabulary. Never record values.';
comment on column fde.fde_engagements.scope_id is
  'Set when fde.engage was delegated to a scope admin: the engagement is confined to that scope (49.8).';
comment on column fde.fde_engagements.tokens_consumed is
  'Running total, incremented by metering with each engagement row in billing.token_transactions.';
comment on column fde.fde_engagements.provider_cost_budget is 'Pounds sterling.';
comment on column fde.fde_engagements.predecessor_engagement_id is
  'Set on the Reliability successor of a handed-over engagement (50.12): it watches the systems its predecessor had in scope.';
comment on column fde.fde_engagements.rate_limits is
  'The six limits of 52.5 as positive integers, checked by fde.rate_limits_valid.';
create index fde_engagements_list on fde.fde_engagements (organisation_id, created_at desc);
create index fde_engagements_live on fde.fde_engagements (organisation_id, status)
  where status in ('active', 'paused');
create index fde_engagements_supervising_engineer on fde.fde_engagements (organisation_id, supervising_engineer_membership_id)
  where supervising_engineer_membership_id is not null and status in ('active', 'paused');
create index fde_engagements_engaging_membership on fde.fde_engagements (organisation_id, engaging_membership_id);
create index fde_engagements_scope on fde.fde_engagements (organisation_id, scope_id) where scope_id is not null;
create index fde_engagements_cell on fde.fde_engagements (cell_id);
create index fde_engagements_predecessor on fde.fde_engagements (organisation_id, predecessor_engagement_id)
  where predecessor_engagement_id is not null;
create trigger fde_engagements_frozen before update on fde.fde_engagements
  for each row execute function platform.freeze_columns('id', 'organisation_id', 'cell_id', 'predecessor_engagement_id');
select platform.add_updated_at_trigger('fde.fde_engagements');
select platform.enable_tenant_rls('fde.fde_engagements');

-- Stopped, handed over and closed are final: no transition out of them (52.7).
create function fde.fde_engagements_reject_final_transition() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
begin
  raise exception 'engagement % is %; its status cannot change', old.id, old.status
    using errcode = 'check_violation';
end
$$;
create trigger fde_engagements_final_status before update of status on fde.fde_engagements
  for each row when (old.status in ('stopped', 'handed_over', 'closed') and new.status is distinct from old.status)
  execute function fde.fde_engagements_reject_final_transition();

grant select, insert, update on fde.fde_engagements to silo_app;
grant select on fde.fde_engagements to silo_report;

-- The deferred key from 0003 (iam.service_principals.engagement_id). Its index,
-- service_principals_engagement, exists already.
alter table iam.service_principals
  add constraint service_principals_engagement_fkey
    foreign key (organisation_id, engagement_id) references fde.fde_engagements (organisation_id, id);
comment on column iam.service_principals.engagement_id is 'The AI FDE engagement of a principal of kind fde.';

