create table fde.fde_stages (
  id                uuid primary key,
  organisation_id   uuid not null references iam.organisations (id),
  engagement_id     uuid not null,
  stage_number      integer not null check (stage_number between 0 and 9),
  attempt           integer not null default 1 check (attempt >= 1),
  status            text not null default 'pending'
                      check (status in ('pending', 'running', 'awaiting_confirmation', 'passed', 'failed', 'stopped')),
  exit_criteria     jsonb not null check (jsonb_typeof(exit_criteria) = 'array'),
  failure_detail    jsonb check (jsonb_typeof(failure_detail) = 'object'),
  exit_confirmed_by uuid,
  entered_at        timestamptz,
  exited_at         timestamptz,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  unique (organisation_id, id),
  unique (organisation_id, engagement_id, id),
  constraint fde_stages_attempt_key unique (organisation_id, engagement_id, stage_number, attempt),
  foreign key (organisation_id, engagement_id) references fde.fde_engagements (organisation_id, id),
  constraint fde_stages_exit_confirmed_by_fkey
    foreign key (organisation_id, exit_confirmed_by) references iam.memberships (organisation_id, id),
  check (status <> 'failed' or failure_detail is not null),
  check (status <> 'passed' or exit_confirmed_by is not null),
  check (status not in ('passed', 'failed', 'stopped') or exited_at is not null),
  check (exited_at is null or entered_at is null or exited_at >= entered_at)
);
comment on table fde.fde_stages is
  'One attempt at one of the ten lifecycle stages, with exit criteria and the person who confirmed the exit.';
comment on column fde.fde_stages.failure_detail is
  'Failing mechanism, sub-stage and error semantic. References only.';
create index fde_stages_open on fde.fde_stages (organisation_id, status)
  where status in ('running', 'awaiting_confirmation');
create trigger fde_stages_frozen before update on fde.fde_stages
  for each row execute function platform.freeze_columns('id', 'organisation_id', 'engagement_id', 'stage_number', 'attempt');
select platform.add_updated_at_trigger('fde.fde_stages');
select platform.enable_tenant_rls('fde.fde_stages');

