create table fde.fde_principals (
  id                   uuid primary key,
  organisation_id      uuid not null references iam.organisations (id),
  engagement_id        uuid not null,
  service_principal_id uuid not null,
  principal_kind       text not null default 'fde' check (principal_kind = 'fde'),
  role                 text not null check (role in ('survey', 'integration', 'ontology', 'action', 'application',
                                                     'simulation', 'reliability')),
  tool_permissions     text[] not null,
  created_by           uuid not null,
  created_at           timestamptz not null default now(),
  revoked_at           timestamptz,
  unique (organisation_id, id),
  unique (organisation_id, engagement_id, id, role),
  unique (organisation_id, service_principal_id),
  foreign key (organisation_id, engagement_id) references fde.fde_engagements (organisation_id, id),
  constraint fde_principals_service_principal_fkey
    foreign key (organisation_id, service_principal_id, principal_kind)
    references iam.service_principals (organisation_id, id, kind),
  constraint fde_principals_created_by_fkey
    foreign key (organisation_id, created_by) references iam.memberships (organisation_id, id),
  check (array_position(tool_permissions, null) is null),
  -- Second line behind iam.service_principal_roles: the forbidden set of 52.1, with the
  -- marking, role assignment and connection grant identifiers of chapter 76.
  constraint fde_principals_no_forbidden_permission check (not (tool_permissions && array[
    'mutation.approve', 'mutation.execute', 'automation.mutate', 'automation.execute',
    'silo.enable', 'silo.create', 'silo.manage', 'silo.purge', 'silo.import',
    'clearance.grant', 'marking.manage', 'marking.declassify', 'ontology.mark',
    'admin.delegate', 'member.invite', 'service_principal.manage', 'connection.grant',
    'discovery.manage', 'billing.manage', 'billing.view', 'tokens.purchase', 'seat.allocate', 'seat.release',
    'contract.manage', 'payment.record', 'fde.engage', 'fde.confirm']::text[]))
);
comment on table fde.fde_principals is
  'The service principal one role uses inside one engagement, with its tool permissions.';
comment on column fde.fde_principals.principal_kind is
  'Always fde. Exists so the composite key proves the service principal''s kind.';
comment on column fde.fde_principals.tool_permissions is
  'Chapter 76 permission identifiers the role''s tools need, intersected with the ceiling at every call.';
-- One live principal per role per engagement (49.4).
create unique index fde_principals_live_role on fde.fde_principals (organisation_id, engagement_id, role)
  where revoked_at is null;
select platform.enable_tenant_rls('fde.fde_principals');

create function fde.fde_principals_revoke_only() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
begin
  if old.revoked_at is not null or (to_jsonb(new) - 'revoked_at') <> (to_jsonb(old) - 'revoked_at') then
    raise exception 'fde.fde_principals rows change only to record revocation'
      using errcode = 'insufficient_privilege';
  end if;
  return new;
end
$$;
create trigger fde_principals_revoke_only before update on fde.fde_principals
  for each row execute function fde.fde_principals_revoke_only();

grant select, insert, update (revoked_at) on fde.fde_principals to silo_app;
grant select on fde.fde_principals to silo_report;

-- 52.1: "The forbidden set is enforced by a database constraint on service_principal_roles
-- for principals of kind fde." A role holding a forbidden permission can never be held by an
-- FDE principal, whichever side changes: deferred to commit and serialised on the role row,
-- as iam.reject_authorising_for_principals is.
create function fde.forbidden_permissions() returns text[]
language sql immutable parallel safe
set search_path = pg_catalog
as $$
  select array[
    'mutation.approve', 'mutation.execute', 'automation.mutate', 'automation.execute',
    'silo.enable', 'silo.create', 'silo.manage', 'silo.purge', 'silo.import',
    'clearance.grant', 'marking.manage', 'marking.declassify', 'ontology.mark',
    'admin.delegate', 'member.invite', 'service_principal.manage', 'connection.grant',
    'discovery.manage', 'billing.manage', 'billing.view', 'tokens.purchase', 'seat.allocate', 'seat.release',
    'contract.manage', 'payment.record', 'fde.engage', 'fde.confirm']::text[]
$$;

create function iam.reject_forbidden_for_fde_principals() returns trigger
language plpgsql
security definer
set search_path = pg_catalog
as $$
begin
  perform 1 from iam.roles r where r.organisation_id = new.organisation_id and r.id = new.role_id for update;
  if exists (
    select 1
    from iam.service_principal_roles spr
    join iam.service_principals sp on sp.organisation_id = spr.organisation_id and sp.id = spr.service_principal_id
    join iam.role_permissions rp on rp.organisation_id = spr.organisation_id and rp.role_id = spr.role_id
    where spr.organisation_id = new.organisation_id and spr.role_id = new.role_id and sp.kind = 'fde'
      and rp.permission_id = any (fde.forbidden_permissions())) then
    raise exception 'an AI FDE principal never holds a forbidden permission (spec 52.1): role %', new.role_id
      using errcode = 'insufficient_privilege';
  end if;
  return null;
end
$$;
create constraint trigger service_principal_roles_fde_forbidden
  after insert or update on iam.service_principal_roles
  deferrable initially deferred
  for each row execute function iam.reject_forbidden_for_fde_principals();
create constraint trigger role_permissions_fde_forbidden
  after insert or update on iam.role_permissions
  deferrable initially deferred
  for each row execute function iam.reject_forbidden_for_fde_principals();

-- The orchestrator's sweep across organisations: engagements it has work for, identifiers only.
create function fde.engagements_to_run(p_limit integer) returns table (organisation_id uuid, id uuid)
language sql stable security definer
set search_path = pg_catalog
as $$
  select e.organisation_id, e.id from fde.fde_engagements e where e.status = 'active'
  order by e.updated_at, e.id limit p_limit
$$;
grant execute on function fde.engagements_to_run(integer) to silo_app;

