create table fde.fde_tasks (
  id                     uuid primary key,
  organisation_id        uuid not null references iam.organisations (id),
  engagement_id          uuid not null,
  stage_id               uuid not null,
  role                   text not null check (role in ('survey', 'integration', 'ontology', 'action', 'application',
                                                       'simulation', 'reliability')),
  principal_id           uuid not null,
  connection_id          uuid,
  kind                   text not null check (kind ~ '^[a-z][a-z0-9_]*$'),
  input_refs             jsonb not null check (jsonb_typeof(input_refs) = 'object'),
  status                 text not null default 'queued'
                           check (status in ('queued', 'running', 'succeeded', 'partial', 'failed', 'cancelled')),
  attempts               integer not null default 0 check (attempts >= 0),
  max_attempts           integer not null check (max_attempts >= 1),
  tokens_consumed        bigint not null default 0 check (tokens_consumed >= 0),
  provider_input_tokens  bigint not null default 0 check (provider_input_tokens >= 0),
  provider_output_tokens bigint not null default 0 check (provider_output_tokens >= 0),
  provider_cost          numeric(14,4) not null default 0 check (provider_cost >= 0),
  failed_at_stage        text,
  error_semantic         text check (error_semantic in ('auth', 'rate_limit', 'not_found', 'upstream', 'bounds',
                                                        'schema', 'unsupported_transport', 'ceiling', 'limit')),
  created_at             timestamptz not null default now(),
  started_at             timestamptz,
  completed_at           timestamptz,
  updated_at             timestamptz not null default now(),
  unique (organisation_id, id),
  unique (organisation_id, engagement_id, id),
  constraint fde_tasks_stage_fkey
    foreign key (organisation_id, engagement_id, stage_id) references fde.fde_stages (organisation_id, engagement_id, id),
  constraint fde_tasks_principal_fkey
    foreign key (organisation_id, engagement_id, principal_id, role)
    references fde.fde_principals (organisation_id, engagement_id, id, role),
  check (attempts <= max_attempts),
  check (status <> 'failed' or error_semantic is not null)
);
comment on table fde.fde_tasks is
  'One unit of agent work for one role in one stage, with attempts, token use and provider cost.';
comment on column fde.fde_tasks.connection_id is
  'The source system the task works on, so repeated failure per system is a query.';
comment on column fde.fde_tasks.input_refs is 'References to connections, manifests, profiles, documents. Never values.';
comment on column fde.fde_tasks.provider_cost is 'Pounds sterling, measured at the model gateway.';
create index fde_tasks_log on fde.fde_tasks (organisation_id, engagement_id, created_at desc);
create index fde_tasks_runnable on fde.fde_tasks (organisation_id, engagement_id, created_at)
  where status in ('queued', 'running');
