create table fde.fde_confirmation_sessions (
  id                        uuid primary key,
  organisation_id           uuid not null references iam.organisations (id),
  engagement_id             uuid not null,
  stage_id                  uuid not null,
  mode                      text not null check (mode in ('queue', 'workshop')),
  facilitator_membership_id uuid,
  agenda                    jsonb not null check (jsonb_typeof(agenda) = 'array'),
  scheduled_at              timestamptz,
  started_at                timestamptz,
  ended_at                  timestamptz,
  presented_count           integer not null default 0 check (presented_count >= 0),
  accepted_count            integer not null default 0 check (accepted_count >= 0),
  edited_count              integer not null default 0 check (edited_count >= 0),
  rejected_count            integer not null default 0 check (rejected_count >= 0),
  deferred_count            integer not null default 0 check (deferred_count >= 0),
  escalated_count           integer not null default 0 check (escalated_count >= 0),
  created_at                timestamptz not null default now(),
  updated_at                timestamptz not null default now(),
  unique (organisation_id, id),
  constraint fde_confirmation_sessions_stage_fkey
    foreign key (organisation_id, engagement_id, stage_id) references fde.fde_stages (organisation_id, engagement_id, id),
  constraint fde_confirmation_sessions_facilitator_fkey
    foreign key (organisation_id, facilitator_membership_id) references iam.memberships (organisation_id, id),
  check (mode <> 'workshop' or facilitator_membership_id is not null),
  check (ended_at is null or (started_at is not null and ended_at >= started_at))
);
comment on table fde.fde_confirmation_sessions is
  'A queue review or structured workshop in which deciders work through proposals.';
comment on column fde.fde_confirmation_sessions.agenda is
  'Ordered proposal ids grouped by object type or system. Identifiers only.';
create index fde_confirmation_sessions_list on fde.fde_confirmation_sessions (organisation_id, engagement_id, scheduled_at desc);
create index fde_confirmation_sessions_stage on fde.fde_confirmation_sessions (organisation_id, stage_id, engagement_id);
create trigger fde_confirmation_sessions_frozen before update on fde.fde_confirmation_sessions
  for each row execute function platform.freeze_columns('id', 'organisation_id', 'engagement_id', 'stage_id');
select platform.add_updated_at_trigger('fde.fde_confirmation_sessions');
select platform.enable_tenant_rls('fde.fde_confirmation_sessions');

grant select, insert, update on fde.fde_confirmation_sessions to silo_app;
grant select on fde.fde_confirmation_sessions to silo_report;

