create table fde.fde_proposals (
  id                      uuid primary key,
  organisation_id         uuid not null references iam.organisations (id),
  engagement_id           uuid not null,
  task_id                 uuid not null,
  kind                    text not null check (kind in (
                            'discovery_finding', 'estate_entry', 'connector_manifest', 'connector_mapping',
                            'write_enablement', 'object_type', 'link_type', 'interface', 'resolution_pair',
                            'field_authority', 'field_alias', 'time_field', 'action_type', 'studio_app',
                            'object_view_layout', 'dashboard', 'cron_notify', 'detector_configuration',
                            'dependency_edge', 'heal_review', 'reliability_finding')),
  payload                 jsonb not null check (jsonb_typeof(payload) = 'object'),
  evidence                jsonb not null check (fde.evidence_valid(evidence)),
  confidence              numeric(4,3) not null check (confidence between 0 and 1),
  confidence_band         text not null check (confidence_band in ('high', 'medium', 'low')),
  verification            jsonb not null check (jsonb_typeof(verification) = 'object'),
  required_permission     text not null check (required_permission ~ '^[a-z][a-z0-9_]*(\.[a-z][a-z0-9_]*)+$'),
  assigned_membership_id  uuid,
  status                  text not null default 'pending'
                            check (status in ('pending', 'accepted', 'accepted_edited', 'rejected', 'deferred',
                                              'superseded', 'withdrawn', 'expired')),
  superseded_by_id        uuid,
  expires_at              timestamptz,
  edit_diff               jsonb,
  rejection_reason        text check (rejection_reason ~ '^[a-z][a-z0-9_]*(:.*)?$'),
  decided_by              uuid,
  decided_at              timestamptz,
  confirmation_session_id uuid,
  model_call_id           uuid,
  model_call_occurred_at  timestamptz,
  created_at              timestamptz not null default now(),
  updated_at              timestamptz not null default now(),
  unique (organisation_id, id),
  unique (organisation_id, id, kind),
  constraint fde_proposals_task_fkey
    foreign key (organisation_id, engagement_id, task_id) references fde.fde_tasks (organisation_id, engagement_id, id),
  constraint fde_proposals_assigned_membership_fkey
    foreign key (organisation_id, assigned_membership_id) references iam.memberships (organisation_id, id),
  constraint fde_proposals_decided_by_fkey
    foreign key (organisation_id, decided_by) references iam.memberships (organisation_id, id),
  constraint fde_proposals_confirmation_session_fkey
    foreign key (organisation_id, confirmation_session_id) references fde.fde_confirmation_sessions (organisation_id, id),
  constraint fde_proposals_superseded_by_fkey
    foreign key (organisation_id, superseded_by_id) references fde.fde_proposals (organisation_id, id),
  check (superseded_by_id is distinct from id),
  check ((status = 'superseded') = (superseded_by_id is not null)),
  check (status <> 'accepted_edited' or edit_diff is not null),
  check (status <> 'rejected' or rejection_reason is not null),
  check ((status in ('accepted', 'accepted_edited', 'rejected', 'deferred')) = (decided_by is not null)),
  check ((status in ('accepted', 'accepted_edited', 'rejected', 'deferred')) = (decided_at is not null)),
  check ((model_call_id is null) = (model_call_occurred_at is null))
);
comment on table fde.fde_proposals is
  'One AI FDE output awaiting a person''s decision, with evidence, confidence and the required permission.';
comment on column fde.fde_proposals.payload is
  'The artefact in the target system''s own schema. References and structure only.';
comment on column fde.fde_proposals.evidence is
  'At least one item, each with a known type (52.4), checked by fde.evidence_valid.';
comment on column fde.fde_proposals.assigned_membership_id is
  'The decider the orchestrator routed it to. Null while escalated to the engaging administrator.';
comment on column fde.fde_proposals.rejection_reason is
  'A closed enumeration value, optionally followed by a colon and free text.';
comment on column fde.fde_proposals.decided_by is
  'A membership, never a service principal: memberships hold no principals.';
comment on column fde.fde_proposals.model_call_id is
  'Soft reference to the drafting row in platform.model_calls (a ledger, so no foreign key).';
create index fde_proposals_by_status on fde.fde_proposals (organisation_id, engagement_id, status, created_at desc);
-- A decider's queue and the pending-per-decider limit (52.5).
create index fde_proposals_decider_queue on fde.fde_proposals (organisation_id, assigned_membership_id, created_at)
  where status = 'pending';
create index fde_proposals_task on fde.fde_proposals (organisation_id, task_id, engagement_id);
create index fde_proposals_confirmation_session on fde.fde_proposals (organisation_id, confirmation_session_id)
  where confirmation_session_id is not null;
create index fde_proposals_superseded_by on fde.fde_proposals (organisation_id, superseded_by_id)
  where superseded_by_id is not null;
create index fde_proposals_expiry on fde.fde_proposals (organisation_id, expires_at)
  where status = 'pending' and expires_at is not null;
-- The artefact is fixed at insert.
create trigger fde_proposals_frozen before update on fde.fde_proposals
  for each row execute function platform.freeze_columns(
    'id', 'organisation_id', 'engagement_id', 'task_id', 'kind', 'payload', 'evidence', 'confidence',
    'required_permission', 'created_at');
select platform.add_updated_at_trigger('fde.fde_proposals');
select platform.enable_tenant_rls('fde.fde_proposals');

-- The decision is fixed once decided_at is set.
create function fde.fde_proposals_decision_final() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
begin
  if (new.status, new.decided_by, new.decided_at, new.edit_diff, new.rejection_reason, new.confirmation_session_id)
     is distinct from
     (old.status, old.decided_by, old.decided_at, old.edit_diff, old.rejection_reason, old.confirmation_session_id) then
    raise exception 'proposal % is decided; its decision cannot change', old.id
      using errcode = 'insufficient_privilege';
  end if;
  return new;
end
$$;
create trigger fde_proposals_decision_final before update on fde.fde_proposals
  for each row when (old.decided_at is not null)
  execute function fde.fde_proposals_decision_final();

grant select, insert, update on fde.fde_proposals to silo_app;
grant select on fde.fde_proposals to silo_report;

