-- Exclusive arc over the target tables. Each kind may set only its own column;
-- reliability_finding has no target row and never appears here.
create table fde.fde_proposal_targets (
  id                     uuid primary key,
  organisation_id        uuid not null references iam.organisations (id),
  proposal_id            uuid not null,
  proposal_kind          text not null,
  relation               text not null check (relation in ('revises', 'applied')),
  discovery_finding_id   uuid,
  estate_snapshot_id     uuid,
  connector_manifest_id  uuid,
  property_mapping_id    uuid,
  connection_id          uuid,
  object_type_id         uuid,
  link_type_id           uuid,
  interface_id           uuid,
  resolution_proposal_id uuid,
  field_authority_id     uuid,
  field_alias_id         uuid,
  time_field_id          uuid,
  action_type_id         uuid,
  app_id                 uuid,
  object_view_layout_id  uuid,
  saved_view_id          uuid,
  automation_id          uuid,
  detector_configuration_id  uuid,
  dependency_edge_id     uuid,
  heal_proposal_id       uuid,
  created_at             timestamptz not null default now(),
  unique (organisation_id, id),
  constraint fde_proposal_targets_relation_key unique (organisation_id, proposal_id, relation),
  constraint fde_proposal_targets_proposal_fkey
    foreign key (organisation_id, proposal_id, proposal_kind) references fde.fde_proposals (organisation_id, id, kind),
  constraint fde_proposal_targets_automation_fkey
    foreign key (organisation_id, automation_id) references automation.automations (organisation_id, id),
  constraint fde_proposal_targets_one_target check (num_nonnulls(
    discovery_finding_id, estate_snapshot_id, connector_manifest_id, property_mapping_id, connection_id,
    object_type_id, link_type_id, interface_id, resolution_proposal_id, field_authority_id, field_alias_id,
    time_field_id, action_type_id, app_id, object_view_layout_id, saved_view_id, automation_id,
    detector_configuration_id, dependency_edge_id, heal_proposal_id) = 1),
  constraint fde_proposal_targets_kind_column check (case proposal_kind
    when 'discovery_finding'      then discovery_finding_id is not null
    when 'estate_entry'           then estate_snapshot_id is not null
    when 'connector_manifest'     then connector_manifest_id is not null
    -- A connector build's object mapping, confirmed on its connection (16.3); later property mappings may name it.
    when 'connector_mapping'      then connection_id is not null or property_mapping_id is not null
    when 'write_enablement'       then connection_id is not null
    when 'object_type'            then object_type_id is not null
    when 'link_type'              then link_type_id is not null
    when 'interface'              then interface_id is not null
    when 'resolution_pair'        then resolution_proposal_id is not null
    when 'field_authority'        then field_authority_id is not null
    when 'field_alias'            then field_alias_id is not null
    when 'time_field'             then time_field_id is not null
    when 'action_type'            then action_type_id is not null
    when 'studio_app'             then app_id is not null
    -- The layout's Studio app, accepted as a draft; its layout row exists once it is published (34.6).
    when 'object_view_layout'     then app_id is not null or object_view_layout_id is not null
    when 'dashboard'              then saved_view_id is not null
    when 'cron_notify'            then automation_id is not null
    when 'detector_configuration' then detector_configuration_id is not null
    when 'dependency_edge'        then dependency_edge_id is not null
    when 'heal_review'            then heal_proposal_id is not null
    else false
  end)
);
comment on table fde.fde_proposal_targets is
  'The record a proposal revises and the record created when it is applied, as typed foreign keys.';
comment on column fde.fde_proposal_targets.proposal_kind is 'Copy of the proposal kind, pinned by the composite key.';
comment on constraint fde_proposal_targets_proposal_fkey on fde.fde_proposal_targets is
  'lint:no-index served by unique (organisation_id, proposal_id, relation); proposal_kind follows proposal_id';
-- One partial index per arc column: "which proposals touched this" for every target.
-- The object type one also serves the object type view's "proposed by the AI FDE" badge.
create index fde_proposal_targets_discovery_finding on fde.fde_proposal_targets (organisation_id, discovery_finding_id)
  where discovery_finding_id is not null;
create index fde_proposal_targets_estate_snapshot on fde.fde_proposal_targets (organisation_id, estate_snapshot_id)
  where estate_snapshot_id is not null;
create index fde_proposal_targets_connector_manifest on fde.fde_proposal_targets (organisation_id, connector_manifest_id)
  where connector_manifest_id is not null;
create index fde_proposal_targets_property_mapping on fde.fde_proposal_targets (organisation_id, property_mapping_id)
  where property_mapping_id is not null;
create index fde_proposal_targets_connection on fde.fde_proposal_targets (organisation_id, connection_id)
  where connection_id is not null;
create index fde_proposal_targets_object_type on fde.fde_proposal_targets (organisation_id, object_type_id)
  where object_type_id is not null;
create index fde_proposal_targets_link_type on fde.fde_proposal_targets (organisation_id, link_type_id)
  where link_type_id is not null;
create index fde_proposal_targets_interface on fde.fde_proposal_targets (organisation_id, interface_id)
  where interface_id is not null;
create index fde_proposal_targets_resolution_proposal on fde.fde_proposal_targets
  (organisation_id, resolution_proposal_id) where resolution_proposal_id is not null;
create index fde_proposal_targets_field_authority on fde.fde_proposal_targets (organisation_id, field_authority_id)
  where field_authority_id is not null;
create index fde_proposal_targets_field_alias on fde.fde_proposal_targets (organisation_id, field_alias_id)
  where field_alias_id is not null;
create index fde_proposal_targets_time_field on fde.fde_proposal_targets (organisation_id, time_field_id)
  where time_field_id is not null;
create index fde_proposal_targets_action_type on fde.fde_proposal_targets (organisation_id, action_type_id)
  where action_type_id is not null;
create index fde_proposal_targets_app on fde.fde_proposal_targets (organisation_id, app_id)
  where app_id is not null;
create index fde_proposal_targets_object_view_layout on fde.fde_proposal_targets
  (organisation_id, object_view_layout_id) where object_view_layout_id is not null;
create index fde_proposal_targets_saved_view on fde.fde_proposal_targets (organisation_id, saved_view_id)
  where saved_view_id is not null;
create index fde_proposal_targets_automation on fde.fde_proposal_targets (organisation_id, automation_id)
  where automation_id is not null;
create index fde_proposal_targets_detector_configuration on fde.fde_proposal_targets
  (organisation_id, detector_configuration_id) where detector_configuration_id is not null;
create index fde_proposal_targets_dependency_edge on fde.fde_proposal_targets (organisation_id, dependency_edge_id)
  where dependency_edge_id is not null;
create index fde_proposal_targets_heal_proposal on fde.fde_proposal_targets (organisation_id, heal_proposal_id)
  where heal_proposal_id is not null;
select platform.enable_tenant_rls('fde.fde_proposal_targets');

grant select, insert on fde.fde_proposal_targets to silo_app;
grant select on fde.fde_proposal_targets to silo_report;

