create table fde.fde_engagement_systems (
  id                  uuid primary key,
  organisation_id     uuid not null references iam.organisations (id),
  engagement_id       uuid not null,
  name                text not null check (char_length(btrim(name)) between 1 and 200),
  provider            text not null check (char_length(btrim(provider)) between 1 and 200),
  slug                text not null check (slug ~ '^[a-z0-9][a-z0-9-]{0,62}$'),
  documentation_kind  text not null check (documentation_kind in ('openapi', 'text', 'wsdl', 'graphql', 'odata', 'url')),
  documentation_title text check (documentation_title is null or char_length(documentation_title) <= 200),
  documentation       text not null check (char_length(documentation) between 1 and 2097152),
  base_url            text check (base_url is null or char_length(base_url) <= 500),
  owning_scope_id     uuid not null,
  parameters          jsonb not null default '{}'
                        check (jsonb_typeof(parameters) = 'object' and octet_length(parameters::text) <= 16384),
  status              text not null default 'listed' check (status in ('listed', 'drafted', 'withdrawn')),
  connection_id       uuid,
  listed_by           uuid not null,
  listed_at           timestamptz not null default now(),
  drafted_at          timestamptz,
  withdrawn_at        timestamptz,
  updated_at          timestamptz not null default now(),
  unique (organisation_id, id),
  unique (organisation_id, engagement_id, slug),
  foreign key (organisation_id, engagement_id) references fde.fde_engagements (organisation_id, id),
  foreign key (organisation_id, owning_scope_id) references iam.scopes (organisation_id, id),
  foreign key (organisation_id, connection_id) references connect.connections (organisation_id, id),
  constraint fde_engagement_systems_listed_by_fkey
    foreign key (organisation_id, listed_by) references iam.memberships (organisation_id, id),
  check ((documentation_kind = 'text') = (documentation_title is not null)),
  check (status <> 'drafted' or (connection_id is not null and drafted_at is not null)),
  check (status <> 'withdrawn' or withdrawn_at is not null)
);
comment on table fde.fde_engagement_systems is
  'A system the organisation lists for an engagement, with the documentation its connector is drafted from (51.2 to 51.4).';
comment on column fde.fde_engagement_systems.documentation is
  'A specification or documentation as given (OpenAPI, text, WSDL, GraphQL, OData $metadata): structure, never records. Email samples are never kept here (62.5).';
comment on column fde.fde_engagement_systems.connection_id is
  'The sandbox connection the Integration principal drafted; its owner is the engagement''s engaging administrator.';
comment on constraint fde_engagement_systems_listed_by_fkey on fde.fde_engagement_systems is
  'lint:no-index who listed a system is read with the system, never searched';
create index fde_engagement_systems_scope on fde.fde_engagement_systems (organisation_id, owning_scope_id);
create index fde_engagement_systems_connection on fde.fde_engagement_systems (organisation_id, connection_id) where connection_id is not null;
create trigger fde_engagement_systems_frozen before update on fde.fde_engagement_systems
  for each row execute function platform.freeze_columns(
    'id', 'organisation_id', 'engagement_id', 'slug', 'documentation_kind', 'documentation', 'listed_by', 'listed_at');
select platform.add_updated_at_trigger('fde.fde_engagement_systems');
select platform.enable_tenant_rls('fde.fde_engagement_systems');

grant select, insert on fde.fde_engagement_systems to silo_app;
grant update (status, connection_id, drafted_at, withdrawn_at) on fde.fde_engagement_systems to silo_app;
grant select on fde.fde_engagement_systems to silo_report;

