create table fde.fde_escalations (
  id                      uuid primary key,
  organisation_id         uuid not null references iam.organisations (id),
  engagement_id           uuid not null,
  proposal_id             uuid,
  task_id                 uuid,
  stage_id                uuid,
  cause                   text not null check (cause in ('unsupported_transport', 'contested_ontology_decision',
                                                         'no_eligible_decider', 'regulated_requirement',
                                                         'repeated_stage_failure', 'physical_actuation')),
  path                    text not null check (path in ('support_ticket', 'ontology_owner', 'engaging_administrator',
                                                        'compliance_officer', 'deployment_engineer',
                                                        'operations_safety_owner')),
  status                  text not null default 'open' check (status in ('open', 'resolved')),
  raised_by_membership_id uuid,
  resolved_by             uuid,
  resolution_note         text,
  resolved_at             timestamptz,
  ticket_ref              text,
  created_at              timestamptz not null default now(),
  updated_at              timestamptz not null default now(),
  unique (organisation_id, id),
  foreign key (organisation_id, engagement_id) references fde.fde_engagements (organisation_id, id),
  foreign key (organisation_id, proposal_id) references fde.fde_proposals (organisation_id, id),
  foreign key (organisation_id, task_id) references fde.fde_tasks (organisation_id, id),
  foreign key (organisation_id, stage_id) references fde.fde_stages (organisation_id, id),
  constraint fde_escalations_raised_by_fkey
    foreign key (organisation_id, raised_by_membership_id) references iam.memberships (organisation_id, id),
  constraint fde_escalations_resolved_by_fkey
    foreign key (organisation_id, resolved_by) references iam.memberships (organisation_id, id),
  check (num_nonnulls(proposal_id, task_id, stage_id) >= 1),
  check (num_nonnulls(resolved_by, resolution_note, resolved_at) = case when status = 'resolved' then 3 else 0 end)
);
comment on table fde.fde_escalations is
  'An escalation from the AI FDE or a facilitator, with its path and resolution (53.4).';
comment on column fde.fde_escalations.raised_by_membership_id is 'Null when raised by the orchestrator.';
create index fde_escalations_list on fde.fde_escalations (organisation_id, engagement_id, created_at desc);
create index fde_escalations_open on fde.fde_escalations (organisation_id, engagement_id) where status = 'open';
create index fde_escalations_proposal on fde.fde_escalations (organisation_id, proposal_id) where proposal_id is not null;
create index fde_escalations_task on fde.fde_escalations (organisation_id, task_id) where task_id is not null;
create index fde_escalations_stage on fde.fde_escalations (organisation_id, stage_id) where stage_id is not null;
create trigger fde_escalations_frozen before update on fde.fde_escalations
  for each row execute function platform.freeze_columns(
    'id', 'organisation_id', 'engagement_id', 'proposal_id', 'task_id', 'stage_id', 'cause', 'created_at');
select platform.add_updated_at_trigger('fde.fde_escalations');
select platform.enable_tenant_rls('fde.fde_escalations');

grant select, insert, update on fde.fde_escalations to silo_app;
grant select on fde.fde_escalations to silo_report;

-- ---------------------------------------------------------------------------

create table fde.fde_metrics (
  id              uuid primary key,
  organisation_id uuid not null references iam.organisations (id),
  engagement_id   uuid not null,
  metric          text not null check (metric in (
                    'time_to_first_answer', 'time_to_first_live_clone', 'time_to_first_app', 'time_per_stage',
                    'proposals_accepted_unchanged', 'proposals_edited', 'proposals_rejected', 'calibration',
                    'conformance_pass_rate', 'heal_proposal_accuracy', 'unconfirmed_edge_crossing_rate',
                    'stage_failure_rate', 'tokens_per_engagement', 'provider_cost_per_engagement',
                    'post_handover_reversal_rate')),
  dimensions      jsonb not null default '{}' check (jsonb_typeof(dimensions) = 'object'),
  value           numeric not null,
  unit            text not null check (unit in ('working_hours', 'working_days', 'ratio', 'tokens', 'gbp')),
  numerator       bigint,
  denominator     bigint,
  computed_from   jsonb not null check (case when jsonb_typeof(computed_from) = 'array'
                                             then jsonb_array_length(computed_from) >= 1
                                             else false end),
  measured_at     timestamptz not null,
  unique (organisation_id, id),
  foreign key (organisation_id, engagement_id) references fde.fde_engagements (organisation_id, id),
  check (unit <> 'ratio'
         or (numerator is not null and denominator is not null and denominator > 0
             and numerator between 0 and denominator))
);
comment on table fde.fde_metrics is
  'A measured AI FDE metric for one engagement, with its sample and the events it was computed from.';
comment on column fde.fde_metrics.dimensions is
  'The cut the value applies to: stage_number, role, proposal_kind, confidence_band and so on.';
comment on column fde.fde_metrics.computed_from is
  'References to the audit events and rows used. A metric that cannot cite its events is not recorded.';
create index fde_metrics_latest on fde.fde_metrics (organisation_id, engagement_id, metric, measured_at desc);
select platform.enable_tenant_rls('fde.fde_metrics');

-- A recomputation is a new row; the latest measured_at wins.
grant select, insert on fde.fde_metrics to silo_app;
grant select on fde.fde_metrics to silo_report;

-- Cell-level aggregate for Silo staff: by engagement class and metric only, with no
-- organisation or engagement identifier in the output. Owned by silo_migrate, which
-- bypasses RLS, so it reads every organisation in the cell (the intent). It uses the
-- latest row per engagement, metric and cut, so recomputations are not double counted.
-- Granted to nobody for now: the admin-portal read role does not exist yet.
create view fde.fde_metrics_cell_aggregate as
  with latest as (
    select distinct on (m.organisation_id, m.engagement_id, m.metric, m.dimensions)
           m.organisation_id, m.engagement_id, m.metric, m.numerator, m.denominator
    from fde.fde_metrics m
    order by m.organisation_id, m.engagement_id, m.metric, m.dimensions, m.measured_at desc, m.id desc
  )
  select e.engagement_class,
         l.metric,
         count(distinct l.engagement_id) as engagement_count,
         count(*)                        as measurement_count,
         sum(l.numerator)                as numerator_sum,
         sum(l.denominator)              as denominator_sum
  from latest l
  join fde.fde_engagements e on e.organisation_id = l.organisation_id and e.id = l.engagement_id
  group by e.engagement_class, l.metric;
comment on view fde.fde_metrics_cell_aggregate is
  'Cell-level AI FDE metrics by engagement class and metric; no organisation or engagement ids.';

-- ============================================================================
-- Domain: action
-- ============================================================================

-- Schema action: Action types, mutation path, approval, execution and verification,
-- receipts and history, revert, real-world actuation, outbound Action events.
-- Design: docs/siloDatabaseDesign.doc.md, schema `action` (decisions 1 to 6 and the
-- enforcement summary), with review D8 (a purge chain points at
-- siloes.purge_requests) and D11 (mutations.intent is encrypted).
--
-- Foreign keys whose target is in another schema of this migration (ontology,
-- connect, simulation, siloes) are added in action_fks.sql; their indexes are here.
-- Trigger functions that read gov.markings and connect.connections resolve those
-- names when they run, not when they are created.
--
-- action.action_ledger is deliberately not created: it is not a Postgres table. It
-- lives in the customer's own Silo store (BigQuery, or a UK-resident store in the
-- sovereign cell) and is written by the actions service through platform.outbox.

-- ===========================================================================
-- Shared functions
-- ===========================================================================

-- Super admin (spec 56.5): a live organisation-wide role assignment (no target) on
-- a live role, held by an active membership. Used by the policy and floor triggers.
create function action.membership_is_super_admin(p_organisation_id uuid, p_membership_id uuid)
returns boolean
language sql
stable
set search_path = pg_catalog
as $$
  select exists (
    select 1
    from iam.role_assignments ra
    join iam.memberships m on m.organisation_id = ra.organisation_id and m.id = ra.membership_id
    join iam.roles r on r.organisation_id = ra.organisation_id and r.id = ra.role_id
    where ra.organisation_id = p_organisation_id
      and ra.membership_id = p_membership_id
      and m.status = 'active'
      and r.retired_at is null
      and ra.revoked_at is null
      and ra.silenced_at is null
      and (ra.expires_at is null or ra.expires_at > now())
      and num_nonnulls(ra.on_scope_id, ra.on_connection_id, ra.on_silo_id, ra.on_view_id,
                       ra.on_object_type_id, ra.on_app_id) = 0)
$$;
-- Called from trigger functions that run as the service role.
grant execute on function action.membership_is_super_admin(uuid, uuid) to silo_app;

-- Decision 3: purge never deletes. silo_migrate sets the encrypted columns (named in
-- the trigger arguments) to null and stamps purged_at; every other column is
-- unchanged. No other update is allowed.
create function action.purge_only() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
declare
  c text;
  o jsonb := to_jsonb(old) - 'purged_at';
  n jsonb := to_jsonb(new) - 'purged_at';
begin
  if current_user <> 'silo_migrate' or old.purged_at is not null or new.purged_at is null then
    raise exception '%.% is insert-only; the one permitted update is purge by silo_migrate',
      tg_table_schema, tg_table_name using errcode = 'insufficient_privilege';
  end if;
  foreach c in array tg_argv loop
    if not n ? c then
      raise exception '%.%: purge column % does not exist', tg_table_schema, tg_table_name, c;
    end if;
    if n -> c <> 'null'::jsonb then
      raise exception '%.%: purge sets % to null', tg_table_schema, tg_table_name, c
        using errcode = 'insufficient_privilege';
    end if;
    o := o - c;
    n := n - c;
  end loop;
  if o <> n then
    raise exception '%.%: purge may change only the encrypted columns and purged_at',
      tg_table_schema, tg_table_name using errcode = 'insufficient_privilege';
  end if;
  return new;
end
$$;

-- Approval policies and floors are superseded, never edited: only superseded_at
-- and superseded_by_id may change, once, from null.
create function action.supersede_only() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
begin
  if old.superseded_at is not null or new.superseded_at is null
     or (to_jsonb(new) - array['superseded_at', 'superseded_by_id'])
        <> (to_jsonb(old) - array['superseded_at', 'superseded_by_id']) then
    raise exception '%.% is supersede-only: only superseded_at and superseded_by_id may be set, once',
      tg_table_schema, tg_table_name using errcode = 'insufficient_privilege';
  end if;
  return new;
end
$$;

-- ===========================================================================
-- Action types
-- ===========================================================================

create table action.action_types (
  id                        uuid primary key,
  organisation_id           uuid not null references iam.organisations (id),
  api_name                  text not null check (api_name ~ '^[a-z][a-z0-9_]*(\.[a-z][a-z0-9_]*)*$'),
  display_name              text not null check (length(btrim(display_name)) > 0),
  current_version_id        uuid,
  status                    text not null default 'proposed'
                              check (status in ('proposed', 'confirmed', 'blocked', 'retired', 'rejected')),
  proposed_by_membership_id uuid,
  proposed_by_principal_id  uuid,
  owning_scope_id           uuid not null,
  is_system                 boolean not null default false,
  disabled_at               timestamptz,
  created_at                timestamptz not null default now(),
  retired_at                timestamptz,
  -- A proposal a holder of action.define declined (42.10): never confirmed, never a version.
  rejected_at               timestamptz,
  updated_at                timestamptz not null default now(),
  version                   integer not null default 1,
  unique (organisation_id, id),
  constraint action_types_api_name_key unique (organisation_id, api_name),
  constraint action_types_proposed_by_membership_fkey
    foreign key (organisation_id, proposed_by_membership_id) references iam.memberships (organisation_id, id),
  constraint action_types_proposed_by_principal_fkey
    foreign key (organisation_id, proposed_by_principal_id) references iam.service_principals (organisation_id, id),
  constraint action_types_owning_scope_fkey
    foreign key (organisation_id, owning_scope_id) references iam.scopes (organisation_id, id),
  check (api_name not like 'silo.%' or is_system),
  check ((api_name = 'silo.edit') = is_system),
  check ((status in ('proposed', 'rejected')) = (current_version_id is null)),
  check ((status = 'rejected') = (rejected_at is not null)),
  -- silo.edit is Silo's own (42.9): it has no proposer; every other type has exactly one.
  check (num_nonnulls(proposed_by_membership_id, proposed_by_principal_id) = case when is_system then 0 else 1 end),
  check (disabled_at is null or is_system),
  check (is_system or (status = 'retired') = (retired_at is not null))
);
comment on table action.action_types is
  'One Action type per organisation: identity and lifecycle; content lives in immutable versions (ch 42).';
comment on column action.action_types.is_system is
  'True only for the per-organisation silo.edit row (generic governed edit), created by provisioning.';
comment on column action.action_types.disabled_at is
  'Set when the organisation disables silo.edit (42.9); new generic-edit mutations are then refused.';
create unique index action_types_one_system on action.action_types (organisation_id) where is_system;
create index action_types_list on action.action_types (organisation_id, status, created_at desc);
create index action_types_owning_scope on action.action_types (organisation_id, owning_scope_id);
create index action_types_proposed_by_membership on action.action_types (organisation_id, proposed_by_membership_id)
  where proposed_by_membership_id is not null;
create index action_types_proposed_by_principal on action.action_types (organisation_id, proposed_by_principal_id)
  where proposed_by_principal_id is not null;
-- Serves the composite current-version key added at the end of this file.
create index action_types_current_version on action.action_types (organisation_id, current_version_id, id)
  where current_version_id is not null;
select platform.add_updated_at_trigger('action.action_types');
select platform.enable_tenant_rls('action.action_types');
create trigger action_types_frozen before update on action.action_types
  for each row execute function platform.freeze_columns(
    'id', 'organisation_id', 'is_system', 'proposed_by_membership_id', 'proposed_by_principal_id', 'created_at');

-- Allowed moves: proposed to confirmed; confirmed to blocked; blocked to confirmed;
-- confirmed or blocked to retired. Retired is final except for the system row,
-- which may be re-enabled. The API name is fixed once the type has been confirmed.
create function action.action_types_guard() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
begin
  if old.status <> 'proposed' and new.api_name is distinct from old.api_name then
    raise exception 'action type api_name is immutable once confirmed' using errcode = 'insufficient_privilege';
  end if;
  if new.status is distinct from old.status and not (
       (old.status = 'proposed' and new.status in ('confirmed', 'rejected'))
    or (old.status = 'confirmed' and new.status in ('blocked', 'retired'))
    or (old.status = 'blocked' and new.status in ('confirmed', 'retired'))
    or (old.status = 'retired' and new.status = 'confirmed' and old.is_system)) then
    raise exception 'action type status cannot move from % to %', old.status, new.status
      using errcode = 'check_violation';
  end if;
  return new;
end
$$;
create trigger action_types_guard before update on action.action_types
  for each row execute function action.action_types_guard();

grant select, insert on action.action_types to silo_app;
grant update (api_name, display_name, current_version_id, status, owning_scope_id, disabled_at, retired_at, rejected_at,
              updated_at, version)
  on action.action_types to silo_app;
grant select on action.action_types to silo_report;

-- ===========================================================================
-- Approval policies and floors (before versions, which reference policies)
-- ===========================================================================

create table action.approval_policies (
  id                      uuid primary key,
  organisation_id         uuid not null references iam.organisations (id),
  connection_id           uuid,
  scope_id                uuid,
  approvals_required      integer not null check (approvals_required >= 0),
  approver_qualification  text not null
                            check (approver_qualification in ('any_permitted', 'role', 'scope_admin', 'named_role',
                                                              'marking_holder')),
  qualifying_role_id      uuid,
  requires_admin          boolean not null default false,
  same_scope_required     boolean not null default false,
  self_approval_permitted boolean not null default false,
  sequential              boolean not null default false,
  row_threshold           integer check (row_threshold is null or row_threshold >= 1),
  marking_condition       uuid[] check (marking_condition is null
                                        or (cardinality(marking_condition) > 0
                                            and array_position(marking_condition, null) is null)),
  risk_class_condition    text[] check (risk_class_condition is null
                                        or (cardinality(risk_class_condition) > 0
                                            and risk_class_condition <@ array['data', 'bulk', 'external', 'physical'])),
  expiry_hours            integer not null default 24 check (expiry_hours between 1 and 720),
  created_by              uuid not null,
  created_at              timestamptz not null default now(),
  superseded_at           timestamptz,
  superseded_by_id        uuid,
  unique (organisation_id, id),
  constraint approval_policies_scope_fkey
    foreign key (organisation_id, scope_id) references iam.scopes (organisation_id, id),
  constraint approval_policies_qualifying_role_fkey
    foreign key (organisation_id, qualifying_role_id) references iam.roles (organisation_id, id),
  constraint approval_policies_created_by_fkey
    foreign key (organisation_id, created_by) references iam.memberships (organisation_id, id),
  constraint approval_policies_superseded_by_fkey
    foreign key (organisation_id, superseded_by_id) references action.approval_policies (organisation_id, id),
  check ((approver_qualification in ('role', 'named_role')) = (qualifying_role_id is not null)),
  check ((superseded_at is null) = (superseded_by_id is null)),
  check (superseded_by_id is distinct from id),
  -- A policy cannot express a weaker rule for physical (in addition to the built-in floor).
  check (not ('physical' = any (risk_class_condition)) or (approvals_required >= 2 and not self_approval_permitted))
);
comment on table action.approval_policies is
  'Approval requirement for a connection, scope, threshold, marking or risk class; superseded, never edited (ch 44).';
comment on column action.approval_policies.id is 'The row id is the policy version; a chain snapshot names ids.';
comment on column action.approval_policies.connection_id is 'Null means the organisation default.';
comment on column action.approval_policies.marking_condition is
  'gov.markings ids, checked on insert; the policy applies only when the mutation touches a marked field.';
comment on column action.approval_policies.expiry_hours is 'Provisional default of 24 until the spec decides.';
create index approval_policies_resolution on action.approval_policies (organisation_id, connection_id, scope_id)
  where superseded_at is null;
create index approval_policies_scope on action.approval_policies (organisation_id, scope_id)
  where scope_id is not null;
create index approval_policies_qualifying_role on action.approval_policies (organisation_id, qualifying_role_id)
  where qualifying_role_id is not null;
create index approval_policies_created_by on action.approval_policies (organisation_id, created_by);
create index approval_policies_superseded_by on action.approval_policies (organisation_id, superseded_by_id)
  where superseded_by_id is not null;
select platform.enable_tenant_rls('action.approval_policies');
create trigger approval_policies_supersede_only before update on action.approval_policies
  for each row execute function action.supersede_only();
create trigger approval_policies_no_delete before delete on action.approval_policies
  for each row execute function platform.reject_ledger_change('strict');
create trigger approval_policies_no_truncate before truncate on action.approval_policies
  for each statement execute function platform.reject_ledger_change();

create table action.policy_floors (
  id                    uuid primary key,
  organisation_id       uuid not null references iam.organisations (id),
  connection_id         uuid,
  minimum_approvals     integer not null check (minimum_approvals >= 1),
  minimum_qualification text not null
                          check (minimum_qualification in ('any_permitted', 'role', 'scope_admin', 'named_role',
                                                           'marking_holder')),
  unwaivable_markings   uuid[] not null default '{}' check (array_position(unwaivable_markings, null) is null),
  risk_class            text check (risk_class in ('data', 'bulk', 'external', 'physical')),
  set_by                uuid not null,
  set_at                timestamptz not null default now(),
  superseded_at         timestamptz,
  superseded_by_id      uuid,
  unique (organisation_id, id),
  constraint policy_floors_set_by_fkey
    foreign key (organisation_id, set_by) references iam.memberships (organisation_id, id),
  constraint policy_floors_superseded_by_fkey
    foreign key (organisation_id, superseded_by_id) references action.policy_floors (organisation_id, id),
  check (risk_class is distinct from 'physical' or minimum_approvals >= 2),
  check ((superseded_at is null) = (superseded_by_id is null)),
  check (superseded_by_id is distinct from id)
);
comment on table action.policy_floors is
  'Minimum approval requirements set by a super admin that no policy can weaken; supersede only (44.4).';
comment on column action.policy_floors.connection_id is 'Null means organisation-wide.';
comment on column action.policy_floors.unwaivable_markings is 'gov.markings ids, checked on insert.';
create index policy_floors_resolution on action.policy_floors (organisation_id, connection_id)
  where superseded_at is null;
create index policy_floors_set_by on action.policy_floors (organisation_id, set_by);
create index policy_floors_superseded_by on action.policy_floors (organisation_id, superseded_by_id)
  where superseded_by_id is not null;
select platform.enable_tenant_rls('action.policy_floors');
create trigger policy_floors_supersede_only before update on action.policy_floors
  for each row execute function action.supersede_only();
create trigger policy_floors_no_delete before delete on action.policy_floors
  for each row execute function platform.reject_ledger_change('strict');
create trigger policy_floors_no_truncate before truncate on action.policy_floors
  for each statement execute function platform.reject_ledger_change();

-- Policy insert (44.4, 44.8): marking ids exist; a locked connection takes policy
-- only from a super admin, a delegated one only from the named admin or a super
-- admin; a non-super-admin cannot write a policy weaker than an applicable floor;
-- a scope_admin policy needs an admin in a scope reaching the connection. The actor
-- is app.membership_id.
create function action.approval_policies_insert_guard() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
declare
  v_actor     uuid := nullif(current_setting('app.membership_id', true), '')::uuid;
  v_super     boolean;
  v_authority text;
  v_delegate  uuid;
  v_scope_id  uuid;
  v_path      public.ltree;
begin
  v_super := v_actor is not null and action.membership_is_super_admin(new.organisation_id, v_actor);

  if new.marking_condition is not null and exists (
       select 1 from unnest(new.marking_condition) as mc(id)
       where not exists (select 1 from gov.markings g
                         where g.organisation_id = new.organisation_id and g.id = mc.id)) then
    raise exception 'marking_condition names a marking that does not exist' using errcode = 'foreign_key_violation';
  end if;

  if new.connection_id is not null then
    select c.policy_authority, c.policy_authority_granted_to, c.owning_scope_id
      into v_authority, v_delegate, v_scope_id
    from connect.connections c
    where c.organisation_id = new.organisation_id and c.id = new.connection_id;

    if v_authority = 'locked' and not v_super then
      raise exception 'policy on connection % is locked: only a super admin may set it', new.connection_id
        using errcode = 'insufficient_privilege';
    elsif v_authority = 'delegated' and not v_super and v_actor is distinct from v_delegate then
      raise exception 'policy on connection % is delegated: only the named admin or a super admin may set it',
        new.connection_id using errcode = 'insufficient_privilege';
    end if;
  else
    v_scope_id := new.scope_id;
  end if;

  -- Floors apply by connection (or organisation-wide), risk class and marking. A
  -- policy is weaker when it asks for fewer approvals, or for any permitted approver
  -- where the floor names a qualification.
  if not v_super and exists (
       select 1 from action.policy_floors f
       where f.organisation_id = new.organisation_id
         and f.superseded_at is null
         and (f.connection_id is null or new.connection_id is null or f.connection_id = new.connection_id)
         and (f.risk_class is null or new.risk_class_condition is null or f.risk_class = any (new.risk_class_condition))
         and (cardinality(f.unwaivable_markings) = 0 or new.marking_condition is null
              or f.unwaivable_markings && new.marking_condition)
         and (new.approvals_required < f.minimum_approvals
              or (f.minimum_qualification <> 'any_permitted' and new.approver_qualification = 'any_permitted'))) then
    raise exception 'policy is weaker than an applicable floor; only a super admin may set it'
      using errcode = 'insufficient_privilege';
  end if;

  if new.approvals_required > 0 and new.approver_qualification = 'scope_admin' then
    if v_scope_id is not null then
      select s.path into v_path from iam.scopes s
      where s.organisation_id = new.organisation_id and s.id = v_scope_id;
    end if;
    if not exists (
         select 1
         from iam.role_assignments ra
         join iam.scopes s on s.organisation_id = ra.organisation_id and s.id = ra.on_scope_id
         join iam.memberships m on m.organisation_id = ra.organisation_id and m.id = ra.membership_id
         where ra.organisation_id = new.organisation_id
           and ra.revoked_at is null
           and ra.silenced_at is null
           and (ra.expires_at is null or ra.expires_at > now())
           and m.status = 'active'
           and s.archived_at is null
           and (v_path is null or s.path operator(public.@>) v_path)) then
      raise exception 'a scope_admin policy needs an admin in a scope reaching the connection'
        using errcode = 'check_violation';
    end if;
  end if;

  return new;
end
$$;
create trigger approval_policies_insert_guard before insert on action.approval_policies
  for each row execute function action.approval_policies_insert_guard();

-- Floor insert: marking ids exist and set_by holds the super admin tier.
create function action.policy_floors_insert_guard() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
begin
  if exists (
       select 1 from unnest(new.unwaivable_markings) as um(id)
       where not exists (select 1 from gov.markings g
                         where g.organisation_id = new.organisation_id and g.id = um.id)) then
    raise exception 'unwaivable_markings names a marking that does not exist' using errcode = 'foreign_key_violation';
  end if;
  if not action.membership_is_super_admin(new.organisation_id, new.set_by) then
    raise exception 'policy floors are set by a super admin' using errcode = 'insufficient_privilege';
  end if;
  return new;
end
$$;
create trigger policy_floors_insert_guard before insert on action.policy_floors
  for each row execute function action.policy_floors_insert_guard();

grant select, insert on action.approval_policies, action.policy_floors to silo_app;
grant update (superseded_at, superseded_by_id) on action.approval_policies, action.policy_floors to silo_app;
grant select on action.approval_policies, action.policy_floors to silo_report;

-- ===========================================================================
-- Action type versions and parameters (append-only)
-- ===========================================================================

create table action.action_type_versions (
  id                    uuid primary key,
  organisation_id       uuid not null references iam.organisations (id),
  action_type_id        uuid not null,
  version               integer not null check (version >= 1),
  ontology_version_id   uuid not null,
  description           text,
  targets               jsonb not null,
  rules                 jsonb not null,
  permitted_connections uuid[] not null check (array_position(permitted_connections, null) is null),
  permitted_operations  jsonb not null,
  side_effects          jsonb not null default '[]' check (jsonb_typeof(side_effects) = 'array'),
  risk_class            text not null check (risk_class in ('data', 'external', 'physical')),
  approval_policy_id    uuid,
  revert_behaviour      text not null default 'three_way'
                          check (revert_behaviour in ('three_way', 'compensating', 'state_only', 'not_revertible')),
  compensating_action   text,
  submission_criteria   text,
  -- A member; null only for silo.edit's versions, which Silo publishes (checked on insert).
  confirmed_by          uuid,
  confirmed_at          timestamptz not null default now(),
  unique (organisation_id, id),
  constraint action_type_versions_version_key unique (organisation_id, action_type_id, version),
  -- Target of action_types (organisation_id, id, current_version_id): the current
  -- version always belongs to its own type.
  constraint action_type_versions_type_key unique (organisation_id, action_type_id, id),
  constraint action_type_versions_action_type_fkey
    foreign key (organisation_id, action_type_id) references action.action_types (organisation_id, id),
  constraint action_type_versions_approval_policy_fkey
    foreign key (organisation_id, approval_policy_id) references action.approval_policies (organisation_id, id),
  constraint action_type_versions_confirmed_by_fkey
    foreign key (organisation_id, confirmed_by) references iam.memberships (organisation_id, id),
  check (revert_behaviour <> 'not_revertible' or risk_class = 'physical'),
  check ((revert_behaviour = 'compensating') = (compensating_action is not null))
);
comment on table action.action_type_versions is
  'Immutable published version of an Action type: targets, rules, connections, risk, policy and revert (ch 42).';
comment on column action.action_type_versions.permitted_connections is
  'connect.connections ids; every element is checked on insert (connections are never hard-deleted).';
comment on column action.action_type_versions.side_effects is
  'Array of {"kind": "notification"|"webhook", "physical": boolean}. A webhook forces risk_class external or '
  'higher; an entry with "physical": true (endpoint declared physical) forces physical.';
comment on column action.action_type_versions.approval_policy_id is
  'Optional extra policy; resolution follows superseded_by_id to the policy in force.';
comment on column action.action_type_versions.confirmed_by is
  'Membership; never a service principal. Null only for silo.edit''s versions: Silo publishes one per ontology version an edit compiles against, carrying no content of its own (42.9).';
create index action_type_versions_ontology_version on action.action_type_versions (organisation_id, ontology_version_id);
create index action_type_versions_connections on action.action_type_versions using gin (permitted_connections);
create index action_type_versions_approval_policy on action.action_type_versions (organisation_id, approval_policy_id)
  where approval_policy_id is not null;
create index action_type_versions_confirmed_by on action.action_type_versions (organisation_id, confirmed_by);
select platform.enable_tenant_rls('action.action_type_versions');
select platform.make_append_only('action.action_type_versions');

-- Version insert: contiguous numbering; permitted connections exist; the declared
-- risk class is at least what the side effects force; silo.edit is data only and
-- never fires webhooks (42.9), and only its versions have no confirming member.
create function action.action_type_versions_insert_guard() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
declare
  v_is_system boolean;
  v_next      integer;
  v_floor     text := 'data';
  v_ranks     constant text[] := array['data', 'external', 'physical'];
begin
  select t.is_system into v_is_system
  from action.action_types t
  where t.organisation_id = new.organisation_id and t.id = new.action_type_id;

  select coalesce(max(v.version), 0) + 1 into v_next
  from action.action_type_versions v
  where v.organisation_id = new.organisation_id and v.action_type_id = new.action_type_id;
  if new.version <> v_next then
    raise exception 'action type versions are contiguous: expected version %, got %', v_next, new.version
      using errcode = 'check_violation';
  end if;

  if exists (
       select 1 from unnest(new.permitted_connections) as p(id)
       where not exists (select 1 from connect.connections c
                         where c.organisation_id = new.organisation_id and c.id = p.id)) then
    raise exception 'permitted_connections names a connection that does not exist'
      using errcode = 'foreign_key_violation';
  end if;

  if exists (
       select 1 from jsonb_array_elements(new.side_effects) as e(v)
       where jsonb_typeof(e.v) <> 'object'
          or coalesce(e.v ->> 'kind', '') not in ('notification', 'webhook')
          or (e.v ? 'physical' and jsonb_typeof(e.v -> 'physical') <> 'boolean')) then
    raise exception 'side_effects entries are objects with kind notification or webhook and an optional boolean physical'
      using errcode = 'check_violation';
  end if;
  if exists (select 1 from jsonb_array_elements(new.side_effects) as e(v) where e.v -> 'physical' = 'true'::jsonb) then
    v_floor := 'physical';
  elsif exists (select 1 from jsonb_array_elements(new.side_effects) as e(v) where e.v ->> 'kind' = 'webhook') then
    v_floor := 'external';
  end if;
  if array_position(v_ranks, new.risk_class) < array_position(v_ranks, v_floor) then
    raise exception 'side effects force risk class % or higher; declared %', v_floor, new.risk_class
      using errcode = 'check_violation';
  end if;

  if v_is_system and (new.risk_class <> 'data' or v_floor <> 'data') then
    raise exception 'silo.edit never fires webhooks or writes physical endpoints: risk class data only'
      using errcode = 'check_violation';
  end if;
  if (new.confirmed_by is null) is distinct from coalesce(v_is_system, false) then
    raise exception 'a version is confirmed by a member; only silo.edit''s versions are published by Silo'
      using errcode = 'check_violation';
  end if;

  return new;
end
$$;
create trigger action_type_versions_insert_guard before insert on action.action_type_versions
  for each row execute function action.action_type_versions_insert_guard();

grant select, insert on action.action_type_versions to silo_app;
grant select on action.action_type_versions to silo_report;

create table action.action_parameters (
  id                     uuid primary key,
  organisation_id        uuid not null references iam.organisations (id),
  action_type_version_id uuid not null,
  sequence               integer not null check (sequence >= 1),
  name                   text not null check (length(btrim(name)) > 0),
  param_type             text not null
                           check (param_type in ('string', 'integer', 'decimal', 'boolean', 'date', 'timestamp',
                                                 'enumeration', 'object_reference', 'object_set_reference',
                                                 'attachment_reference')),
  object_type_id         uuid,
  enum_values            text[],
  required               boolean not null default false,
  default_expression     text,
  validation             text,
  validation_message     text,
  unique (organisation_id, id),
  constraint action_parameters_name_key unique (organisation_id, action_type_version_id, name),
  constraint action_parameters_sequence_key unique (organisation_id, action_type_version_id, sequence),
  constraint action_parameters_version_fkey
    foreign key (organisation_id, action_type_version_id) references action.action_type_versions (organisation_id, id),
  check ((param_type in ('object_reference', 'object_set_reference')) = (object_type_id is not null)),
  check ((param_type = 'enumeration') = (enum_values is not null)),
  check (enum_values is null or (cardinality(enum_values) > 0 and array_position(enum_values, null) is null)),
  check (validation_message is null or validation is not null)
);
comment on table action.action_parameters is
  'Typed parameters of one Action type version, with CEL defaults and validation; immutable (42.3).';
create index action_parameters_object_type on action.action_parameters (organisation_id, object_type_id)
  where object_type_id is not null;
select platform.enable_tenant_rls('action.action_parameters');
select platform.make_append_only('action.action_parameters');

grant select, insert on action.action_parameters to silo_app;
grant select on action.action_parameters to silo_report;

-- ===========================================================================
-- Mutation path
-- ===========================================================================

create table action.mutations (
  id                        uuid primary key,
  organisation_id           uuid not null references iam.organisations (id),
  intent                    bytea,
  manifest                  jsonb not null check (jsonb_typeof(manifest) = 'object'),
  manifest_values           bytea,
  action_type_version_id    uuid not null,
  generic_edit              boolean not null default false,
  object_type_id            uuid not null,
  proposer_membership_id    uuid,
  proposer_principal_id     uuid,
  authorising_membership_id uuid,
  origin                    text not null check (origin in ('action', 'ask', 'cron', 'scenario_promotion', 'revert')),
  cron_mode                 text check (cron_mode in ('propose', 'execute_within_bounds')),
  status                    text not null default 'previewed'
                              check (status in ('previewed', 'awaiting_approval', 'approved', 'canary', 'executing',
                                                'completed', 'completed_with_divergence', 'partially_failed',
                                                'failed', 'refused', 'rejected', 'expired')),
  resolution_policy         text not null default 'strict' check (resolution_policy in ('strict', 'partial')),
  risk_class                text not null check (risk_class in ('data', 'bulk', 'external', 'physical')),
  row_count                 integer not null default 0 check (row_count >= 0),
  diff                      bytea,
  diff_hash                 bytea check (diff_hash is null or octet_length(diff_hash) = 32),
  scenario_id               uuid,
  previous_mutation_id      uuid,
  dry_run                   boolean not null default false,
  dry_run_receipt_id        uuid,
  execution_separated       boolean not null default false,
  refused_stage             text check (refused_stage in ('intent', 'resolve', 'policy_gate', 'plan',
                                                          'read_prior_state', 'blast_radius', 'preview',
                                                          'approval', 'execute')),
  refusal_reason            text,
  canary_confirmed_by       uuid,
  canary_confirmed_at       timestamptz,
  created_at                timestamptz not null default now(),
  previewed_at              timestamptz,
  completed_at              timestamptz,
  expires_at                timestamptz,
  purged_at                 timestamptz,
  updated_at                timestamptz not null default now(),
  version                   integer not null default 1,
  unique (organisation_id, id),
  -- Target of the approval chain's composite key: an approver approves exactly the
  -- stored diff and class.
  constraint mutations_chain_target_key unique (organisation_id, id, diff_hash, risk_class),
  constraint mutations_action_type_version_fkey
    foreign key (organisation_id, action_type_version_id) references action.action_type_versions (organisation_id, id),
  constraint mutations_proposer_membership_fkey
    foreign key (organisation_id, proposer_membership_id) references iam.memberships (organisation_id, id),
  constraint mutations_proposer_principal_fkey
    foreign key (organisation_id, proposer_principal_id) references iam.service_principals (organisation_id, id),
  constraint mutations_authorising_membership_fkey
    foreign key (organisation_id, authorising_membership_id) references iam.memberships (organisation_id, id),
  constraint mutations_canary_confirmed_by_fkey
    foreign key (organisation_id, canary_confirmed_by) references iam.memberships (organisation_id, id),
  constraint mutations_previous_mutation_fkey
    foreign key (organisation_id, previous_mutation_id) references action.mutations (organisation_id, id),
  check (num_nonnulls(proposer_membership_id, proposer_principal_id) = 1),
  check ((origin = 'cron') = (authorising_membership_id is not null)),
  check ((origin = 'cron') = (cron_mode is not null)),
  -- 43.11: never unattended for external, physical, bulk or generic edit.
  check (cron_mode is distinct from 'execute_within_bounds'
         or (risk_class = 'data' and not generic_edit and row_count < 100)),
  check (resolution_policy = 'strict' or cron_mode is null),
  check (risk_class <> 'bulk' or row_count >= 100),
  check (risk_class <> 'data' or row_count < 100),
  check ((diff is null) = (diff_hash is null) or purged_at is not null),
  check (status = 'refused' or diff_hash is not null),
  check (status = 'refused' or previewed_at is not null),
  check ((origin = 'scenario_promotion') = (scenario_id is not null)),
  check (dry_run_receipt_id is null or not dry_run),
  check ((status = 'refused') = (refused_stage is not null)),
  check ((status = 'refused') = (refusal_reason is not null)),
  check ((canary_confirmed_by is null) = (canary_confirmed_at is null)),
  check ((status in ('completed', 'completed_with_divergence', 'partially_failed', 'failed', 'refused', 'rejected',
                     'expired')) = (completed_at is not null)),
  check (manifest_values is not null or purged_at is not null),
  check (previous_mutation_id is distinct from id)
);
comment on table action.mutations is
  'One governed change from intent to terminal status: Actions, generic edits, Crons, promotions, reverts (ch 43).';
comment on column action.mutations.intent is 'Encrypted (AES-256-GCM): the person''s own words. Null after purge.';
comment on column action.mutations.manifest is
  'Structure only: Action type and version, object type, operation, field names, object set by reference.';
comment on column action.mutations.manifest_values is
  'Encrypted: parameter values, filter literals and new values. Null only after purge.';
comment on column action.mutations.diff is 'Encrypted canonical diff. Immutable once set; null after purge.';
comment on column action.mutations.diff_hash is 'SHA-256 of the canonical diff; survives purge.';
comment on column action.mutations.generic_edit is
  'Copy of the Action type''s is_system (checked by trigger), so generic edits are countable.';
comment on column action.mutations.authorising_membership_id is
  'For a Cron run, the person who authorised it; counts as the proposer for self-approval.';
comment on column action.mutations.previous_mutation_id is
  'Set when this mutation carries forward one closed as stale at execution (44.7).';
comment on column action.mutations.execution_separated is
  'Copied at creation from the organisation setting; the execution trigger then refuses the proposer as executor.';
comment on column action.mutations.refusal_reason is 'Names the failed check; never values.';
comment on column action.mutations.expires_at is 'The latest chain''s expires_at, maintained by trigger.';
create index mutations_list on action.mutations (organisation_id, created_at desc);
create index mutations_open on action.mutations (organisation_id, status, created_at)
  where status in ('awaiting_approval', 'approved', 'canary', 'executing');
create index mutations_proposer_membership on action.mutations (organisation_id, proposer_membership_id, created_at desc)
  where proposer_membership_id is not null;
create index mutations_proposer_principal on action.mutations (organisation_id, proposer_principal_id, created_at desc)
  where proposer_principal_id is not null;
create index mutations_authorising_membership on action.mutations (organisation_id, authorising_membership_id, created_at desc)
  where authorising_membership_id is not null;
create index mutations_action_type_version on action.mutations (organisation_id, action_type_version_id);
create index mutations_object_type on action.mutations (organisation_id, object_type_id, created_at desc);
create index mutations_scenario on action.mutations (organisation_id, scenario_id) where scenario_id is not null;
create index mutations_previous_mutation on action.mutations (organisation_id, previous_mutation_id)
  where previous_mutation_id is not null;
create index mutations_generic_edit on action.mutations (organisation_id, generic_edit, created_at desc)
  where generic_edit;
create index mutations_canary_confirmed_by on action.mutations (organisation_id, canary_confirmed_by)
  where canary_confirmed_by is not null;
create index mutations_canary_expiry on action.mutations (expires_at) where status = 'canary';
create index mutations_dry_run_receipt on action.mutations (organisation_id, dry_run_receipt_id)
  where dry_run_receipt_id is not null;
select platform.add_updated_at_trigger('action.mutations');
select platform.enable_tenant_rls('action.mutations');

-- Mutation insert: created previewed or refused; generic_edit equals the type's
-- is_system; a live mutation needs a confirmed type (reverts excepted: they use the
-- version in the receipt, 42.10) and, for a generic edit, silo.edit enabled; the
-- effective risk class is at least the version's declared class; a dry-run receipt
-- named is a dry run.
create function action.mutations_insert_guard() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
declare
  v_is_system    boolean;
  v_type_status  text;
  v_disabled_at  timestamptz;
  v_version_risk text;
  v_ranks        constant text[] := array['data', 'bulk', 'external', 'physical'];
begin
  new.expires_at := null;

  if new.status not in ('previewed', 'refused') then
    raise exception 'a mutation is created previewed or refused, never %', new.status using errcode = 'check_violation';
  end if;

  select t.is_system, t.status, t.disabled_at, v.risk_class
    into v_is_system, v_type_status, v_disabled_at, v_version_risk
  from action.action_type_versions v
  join action.action_types t on t.organisation_id = v.organisation_id and t.id = v.action_type_id
  where v.organisation_id = new.organisation_id and v.id = new.action_type_version_id;
  if not found then
    return new;  -- the foreign key reports it
  end if;

  if new.generic_edit is distinct from v_is_system then
    raise exception 'generic_edit must equal the Action type''s is_system' using errcode = 'check_violation';
  end if;

  if new.status <> 'refused' and new.origin <> 'revert' then
    if v_type_status <> 'confirmed' then
      raise exception 'the Action type is %: only a confirmed type takes new mutations', v_type_status
        using errcode = 'check_violation';
    end if;
    if v_is_system and v_disabled_at is not null then
      raise exception 'the generic governed edit is disabled for this organisation' using errcode = 'check_violation';
    end if;
  end if;

  if new.status <> 'refused'
     and array_position(v_ranks, new.risk_class) < array_position(v_ranks, v_version_risk) then
    raise exception 'effective risk class % is below the declared class %', new.risk_class, v_version_risk
      using errcode = 'check_violation';
  end if;

  if new.dry_run_receipt_id is not null and exists (
       select 1 from action.receipts r
       where r.organisation_id = new.organisation_id and r.id = new.dry_run_receipt_id and not r.dry_run) then
    raise exception 'dry_run_receipt_id must name a dry-run receipt' using errcode = 'check_violation';
  end if;

  return new;
end
$$;
create trigger mutations_insert_guard before insert on action.mutations
  for each row execute function action.mutations_insert_guard();

-- Mutation update. Purge (decision 3): silo_migrate nulls intent, diff and
-- manifest_values and stamps purged_at. Otherwise identity, manifest, diff, class
-- and every creation-time column are frozen (rows are previewed or refused when
-- inserted); only status, refusal, canary confirmation and completion change, and a
-- terminal mutation changes not at all. Status moves only as 43.10 allows; approved
-- needs a satisfied, unexpired chain or an in-bounds Cron, and a revert with
-- undecided conflicts is not approved. expires_at follows the latest chain.
create function action.mutations_guard() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
declare
  v_terminal  constant text[] := array['completed', 'completed_with_divergence', 'partially_failed', 'failed',
                                       'refused', 'rejected', 'expired'];
  v_encrypted constant text[] := array['intent', 'diff', 'manifest_values'];
  v_mutable   text[] := array['status', 'refused_stage', 'refusal_reason', 'canary_confirmed_by',
                              'canary_confirmed_at', 'completed_at', 'updated_at', 'version', 'expires_at'];
begin
  select c.expires_at into new.expires_at
  from action.approval_chains c
  where c.organisation_id = new.organisation_id and c.mutation_id = new.id
  order by c.created_at desc, c.id desc
  limit 1;

  if old.purged_at is null and new.purged_at is not null then
    if current_user <> 'silo_migrate' then
      raise exception 'mutations are purged only by silo_migrate' using errcode = 'insufficient_privilege';
    end if;
    if num_nonnulls(new.intent, new.diff, new.manifest_values) > 0
       or (to_jsonb(old) - v_encrypted - array['purged_at', 'updated_at', 'expires_at'])
          <> (to_jsonb(new) - v_encrypted - array['purged_at', 'updated_at', 'expires_at']) then
      raise exception 'purge nulls intent, diff and manifest_values and changes nothing else'
        using errcode = 'insufficient_privilege';
    end if;
    return new;
  end if;

  if old.status = any (v_terminal) then
    v_mutable := array['updated_at', 'version', 'expires_at'];
  end if;
  if (to_jsonb(old) - v_mutable) <> (to_jsonb(new) - v_mutable) then
    raise exception 'mutation %: only status, refusal, canary confirmation and completion may change, and nothing once terminal',
      old.id using errcode = 'insufficient_privilege';
  end if;

  if old.canary_confirmed_at is not null
     and (new.canary_confirmed_at, new.canary_confirmed_by) is distinct from (old.canary_confirmed_at, old.canary_confirmed_by) then
    raise exception 'the canary confirmation is recorded once' using errcode = 'insufficient_privilege';
  end if;
  if old.canary_confirmed_at is null and new.canary_confirmed_at is not null and old.status <> 'canary' then
    raise exception 'the remainder is confirmed only after a canary' using errcode = 'check_violation';
  end if;

  if new.status is distinct from old.status then
    if not (
         (old.status = 'previewed' and new.status in ('awaiting_approval', 'approved', 'refused'))
      or (old.status = 'awaiting_approval' and new.status in ('approved', 'rejected', 'expired', 'refused'))
      or (old.status = 'approved' and new.status in ('canary', 'executing', 'expired', 'refused'))
      or (old.status = 'canary' and new.status in ('executing', 'expired', 'refused'))
      or (old.status = 'executing'
          and new.status in ('completed', 'completed_with_divergence', 'partially_failed', 'failed', 'refused'))) then
      raise exception 'mutation status cannot move from % to %', old.status, new.status
        using errcode = 'check_violation';
    end if;

    if new.status = 'approved' then
      if new.origin = 'revert' and exists (
           select 1
           from action.reverts r
           join action.revert_conflicts rc on rc.organisation_id = r.organisation_id and rc.revert_id = r.id
           where r.organisation_id = new.organisation_id and r.new_mutation_id = new.id and rc.decision is null) then
        raise exception 'undecided revert conflicts block approval of the revert' using errcode = 'check_violation';
      end if;
      if not (new.cron_mode is not distinct from 'execute_within_bounds' and new.risk_class = 'data')
         and not exists (
           select 1 from action.approval_chains c
           where c.organisation_id = new.organisation_id and c.mutation_id = new.id
             and c.status = 'approved' and now() < c.expires_at) then
        raise exception 'a mutation is approved only by a satisfied, unexpired approval chain'
          using errcode = 'check_violation';
      end if;
    end if;
  end if;

  return new;
end
$$;
create trigger mutations_guard before update on action.mutations
  for each row execute function action.mutations_guard();

grant select, insert on action.mutations to silo_app;
grant update (status, refused_stage, refusal_reason, canary_confirmed_by, canary_confirmed_at, completed_at,
              updated_at, version)
  on action.mutations to silo_app;
grant select (id, organisation_id, manifest, action_type_version_id, generic_edit, object_type_id,
              proposer_membership_id, proposer_principal_id, authorising_membership_id, origin, cron_mode, status,
              resolution_policy, risk_class, row_count, diff_hash, scenario_id, previous_mutation_id, dry_run,
              dry_run_receipt_id, execution_separated, refused_stage, refusal_reason, canary_confirmed_by,
              canary_confirmed_at, created_at, previewed_at, completed_at, expires_at, purged_at, updated_at, version)
  on action.mutations to silo_report;

create table action.mutation_targets (
  id               uuid primary key,
  organisation_id  uuid not null references iam.organisations (id),
  mutation_id      uuid not null,
  connection_id    uuid,
  object_id        uuid not null,
  entity_reference text,
  operation        text not null
                     check (operation in ('create', 'update_full', 'update_partial', 'delete', 'upsert', 'custom')),
  custom_action    text,
  fields           text[] not null default '{}' check (array_position(fields, null) is null),
  idempotency_key  text not null,
  excluded         boolean not null default false,
  resolved_at      timestamptz,
  created_at       timestamptz not null default now(),
  unique (organisation_id, id),
  constraint mutation_targets_idempotency_key unique (organisation_id, idempotency_key),
  constraint mutation_targets_mutation_fkey
    foreign key (organisation_id, mutation_id) references action.mutations (organisation_id, id),
  check (excluded or (connection_id is not null and entity_reference is not null)),
  check ((operation = 'custom') = (custom_action is not null)),
  check (operation <> 'delete' or cardinality(fields) = 0),
  check (not excluded or resolved_at is null)
);
comment on table action.mutation_targets is
  'One row per record (or excluded object) a mutation intends to write, with operation, fields and idempotency key.';
comment on column action.mutation_targets.object_id is
  'Ontology object identity minted by Resolution (decision 1); no foreign key.';
comment on column action.mutation_targets.entity_reference is
  'Source record identifier; for a create, a placeholder until verification assigns it.';
comment on column action.mutation_targets.excluded is 'Unresolved under a partial resolution policy.';
create index mutation_targets_mutation on action.mutation_targets (organisation_id, mutation_id, connection_id);
create index mutation_targets_connection on action.mutation_targets (organisation_id, connection_id)
  where connection_id is not null;
select platform.enable_tenant_rls('action.mutation_targets');
create trigger mutation_targets_no_delete before delete on action.mutation_targets
  for each row execute function platform.reject_ledger_change('strict');
create trigger mutation_targets_no_truncate before truncate on action.mutation_targets
  for each statement execute function platform.reject_ledger_change();

-- Exclusion only under a partial policy; before preview only resolved_at and
-- excluded may change; once the mutation is previewed, rows are insert-only.
create function action.mutation_targets_guard() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
declare
  v_policy    text;
  v_previewed timestamptz;
begin
  select m.resolution_policy, m.previewed_at into v_policy, v_previewed
  from action.mutations m
  where m.organisation_id = new.organisation_id and m.id = new.mutation_id;

  if new.excluded and v_policy is distinct from 'partial' then
    raise exception 'a target may be excluded only under a partial resolution policy' using errcode = 'check_violation';
  end if;
  if tg_op = 'UPDATE' then
    if v_previewed is not null then
      raise exception 'mutation targets are insert-only once the mutation is previewed'
        using errcode = 'insufficient_privilege';
    end if;
    if (to_jsonb(new) - array['excluded', 'resolved_at']) <> (to_jsonb(old) - array['excluded', 'resolved_at']) then
      raise exception 'only resolved_at and excluded may change on a mutation target'
        using errcode = 'insufficient_privilege';
    end if;
  end if;
  return new;
end
$$;
create trigger mutation_targets_guard before insert or update on action.mutation_targets
  for each row execute function action.mutation_targets_guard();

grant select, insert on action.mutation_targets to silo_app;
grant update (excluded, resolved_at) on action.mutation_targets to silo_app;
grant select on action.mutation_targets to silo_report;

create table action.blast_radius_results (
