-- ===========================================================================
-- Approval
-- ===========================================================================

create table action.approval_chains (
  id                         uuid primary key,
  organisation_id            uuid not null references iam.organisations (id),
  subject_kind               text not null check (subject_kind in ('mutation', 'purge', 'discovery_scan', 'declassification', 'receipt_purge')),
  mutation_id                uuid,
  purge_request_id           uuid,
  discovery_authorisation_id uuid,
  declassification_id        uuid,
  receipt_purge_id           uuid,
  requester_membership_id    uuid not null,
  risk_class                 text check (risk_class in ('data', 'bulk', 'external', 'physical')),
  policy_snapshot            jsonb not null
                               check (jsonb_typeof(policy_snapshot) = 'object'
                                      and coalesce(jsonb_typeof(policy_snapshot -> 'conditions'), '') = 'array'),
  floor_overrode_policy      boolean not null default false,
  diff_hash                  bytea check (diff_hash is null or octet_length(diff_hash) = 32),
  approvals_required         integer not null check (approvals_required >= 0),
  approvals_received         integer not null default 0 check (approvals_received >= 0),
  status                     text not null default 'pending' check (status in ('pending', 'approved', 'rejected', 'expired')),
  expires_at                 timestamptz not null,
  closed_at                  timestamptz,
  created_at                 timestamptz not null default now(),
  updated_at                 timestamptz not null default now(),
  version                    integer not null default 1,
  unique (organisation_id, id),
  -- All four columns are non-null for mutation chains; the other arcs skip this key.
  constraint approval_chains_mutation_fkey
    foreign key (organisation_id, mutation_id, diff_hash, risk_class)
    references action.mutations (organisation_id, id, diff_hash, risk_class),
  constraint approval_chains_requester_fkey
    foreign key (organisation_id, requester_membership_id) references iam.memberships (organisation_id, id),
  constraint approval_chains_declassification_fkey
    foreign key (organisation_id, declassification_id) references gov.marking_declassifications (organisation_id, id),
  check (num_nonnulls(mutation_id, purge_request_id, discovery_authorisation_id, declassification_id, receipt_purge_id) = 1),
  check ((subject_kind = 'declassification') = (declassification_id is not null)),
  check ((subject_kind = 'receipt_purge') = (receipt_purge_id is not null)),
  check ((subject_kind = 'mutation') = (mutation_id is not null)),
  check ((subject_kind = 'purge') = (purge_request_id is not null)),
  check ((subject_kind = 'discovery_scan') = (discovery_authorisation_id is not null)),
  check (subject_kind <> 'mutation' or (diff_hash is not null and risk_class is not null)),
  check (not floor_overrode_policy or policy_snapshot ? 'override'),
  check (risk_class is distinct from 'physical' or approvals_required >= 2),
  check (status <> 'approved' or approvals_received >= approvals_required),
  check (expires_at > created_at),
  check ((status = 'pending') = (closed_at is null))
);
comment on table action.approval_chains is
  'One approval chain per approvable subject (mutation, Silo purge, discovery scan, declassification, receipt purge) with its immutable snapshot (ch 44).';
comment on column action.approval_chains.policy_snapshot is
  'Immutable. Resolved policy ids, floor ids, any override, the Action type policy, the risk class and physical '
  'floors, and "conditions": the union as [{id, count, qualification, qualifying_role_id, '
  'self_approval_permitted}]. References and numbers only.';
comment on column action.approval_chains.requester_membership_id is
  'The proposer (for a Cron run, the authorising person), purge requester or scan requester.';
comment on column action.approval_chains.approvals_received is
  'Count of approved steps, maintained by trigger; never set by the application.';
comment on column action.approval_chains.expires_at is
  'Creation plus the shortest expiry_hours in the union. Immutable.';
create unique index approval_chains_open_mutation on action.approval_chains (organisation_id, mutation_id)
  where status = 'pending' and mutation_id is not null;
create unique index approval_chains_open_purge on action.approval_chains (organisation_id, purge_request_id)
  where status = 'pending' and purge_request_id is not null;
create unique index approval_chains_open_discovery on action.approval_chains (organisation_id, discovery_authorisation_id)
  where status = 'pending' and discovery_authorisation_id is not null;
-- Chain lookup at execution and chain history of a mutation. diff_hash and
-- risk_class are fixed per mutation, so this also serves the composite key.
create index approval_chains_mutation
  on action.approval_chains (organisation_id, mutation_id, diff_hash, risk_class, created_at desc)
  where mutation_id is not null;
create index approval_chains_purge_request on action.approval_chains (organisation_id, purge_request_id)
  where purge_request_id is not null;
create index approval_chains_discovery_authorisation on action.approval_chains (organisation_id, discovery_authorisation_id)
  where discovery_authorisation_id is not null;
create unique index approval_chains_open_declassification on action.approval_chains (organisation_id, declassification_id)
  where status = 'pending' and declassification_id is not null;
create unique index approval_chains_open_receipt_purge on action.approval_chains (organisation_id, receipt_purge_id)
  where status = 'pending' and receipt_purge_id is not null;
create index approval_chains_receipt_purge on action.approval_chains (organisation_id, receipt_purge_id)
  where receipt_purge_id is not null;
create index approval_chains_declassification on action.approval_chains (organisation_id, declassification_id)
  where declassification_id is not null;
create index approval_chains_expiry on action.approval_chains (organisation_id, expires_at)
  where status in ('pending', 'approved');
create index approval_chains_pending on action.approval_chains (organisation_id, id) where status = 'pending';
create index approval_chains_requester on action.approval_chains (organisation_id, requester_membership_id);
select platform.add_updated_at_trigger('action.approval_chains');
select platform.enable_tenant_rls('action.approval_chains');

-- Chain insert and update. approvals_received is recounted from the steps on every
-- write. On insert the chain is pending, or approved when nothing is required, and a
-- mutation chain's requester is the proposer (the authorising person for a Cron).
-- After insert only approvals_received, status, closed_at, updated_at and version
-- change. Status: pending to approved, rejected or expired; approved to expired until
-- the full execution begins. Approval needs an unexpired chain, no rejected step and,
-- for physical, two approved steps by distinct memberships, none the requester and
-- none a self-approval, at least one holding actuation.approve.
create function action.approval_chains_guard() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
declare
  v_mutable   constant text[] := array['approvals_received', 'status', 'closed_at', 'updated_at', 'version'];
  v_requester uuid;
  v_valid     integer;
  v_bad       integer;
  v_actuation boolean;
begin
  if tg_op = 'INSERT' then
    new.approvals_received := 0;
    if not (new.status = 'pending' or (new.status = 'approved' and new.approvals_required = 0)) then
      raise exception 'a chain is created pending, or approved when it requires no approval'
        using errcode = 'check_violation';
    end if;
    if new.mutation_id is not null then
      select coalesce(m.authorising_membership_id, m.proposer_membership_id) into v_requester
      from action.mutations m
      where m.organisation_id = new.organisation_id and m.id = new.mutation_id;
      if v_requester is not null and v_requester <> new.requester_membership_id then
        raise exception 'the requester of a mutation chain is its proposer (for a Cron run, the authorising person)'
          using errcode = 'check_violation';
      end if;
    end if;
    return new;
  end if;

  select count(*) into new.approvals_received
  from action.approval_steps s
  where s.organisation_id = new.organisation_id and s.chain_id = new.id and s.decision = 'approved';

  if (to_jsonb(old) - v_mutable) <> (to_jsonb(new) - v_mutable) then
    raise exception 'approval chain %: snapshot, subject, hash, class, requirement and expiry are immutable', old.id
      using errcode = 'insufficient_privilege';
  end if;

  if new.status is distinct from old.status then
    if not ((old.status = 'pending' and new.status in ('approved', 'rejected', 'expired'))
            or (old.status = 'approved' and new.status = 'expired')) then
      raise exception 'approval chain status cannot move from % to %', old.status, new.status
        using errcode = 'check_violation';
    end if;

    if old.status = 'approved' and new.mutation_id is not null and exists (
         select 1 from action.mutation_executions e
         where e.organisation_id = new.organisation_id and e.mutation_id = new.mutation_id
           and e.phase = 'full' and e.status <> 'pending') then
      raise exception 'execution has begun: the chain can no longer expire' using errcode = 'check_violation';
    end if;

    if new.status = 'approved' then
      if now() >= new.expires_at then
        raise exception 'approval chain % has expired', new.id using errcode = 'check_violation';
      end if;
      if exists (select 1 from action.approval_steps s
                 where s.organisation_id = new.organisation_id and s.chain_id = new.id and s.decision = 'rejected') then
        raise exception 'one rejection rejects the chain' using errcode = 'check_violation';
      end if;
      if new.risk_class = 'physical' then
        select count(*) filter (where s.approver_membership_id <> new.requester_membership_id and not s.self_approval),
               count(*) filter (where s.approver_membership_id = new.requester_membership_id or s.self_approval),
               coalesce(bool_or(s.holds_actuation_approve)
                          filter (where s.approver_membership_id <> new.requester_membership_id and not s.self_approval),
                        false)
          into v_valid, v_bad, v_actuation
        from action.approval_steps s
        where s.organisation_id = new.organisation_id and s.chain_id = new.id and s.decision = 'approved';
        if v_bad > 0 or v_valid < 2 or not v_actuation then
          raise exception 'a physical Action needs two distinct approvers, neither the requester nor a self-approval, '
                          'at least one holding actuation.approve' using errcode = 'check_violation';
        end if;
      end if;
    end if;
  end if;

  return new;
end
$$;
create trigger approval_chains_guard before insert or update on action.approval_chains
  for each row execute function action.approval_chains_guard();

-- A new chain refreshes its mutation, whose own trigger copies the latest chain's
-- expires_at.
create function action.approval_chains_refresh_mutation() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
begin
  update action.mutations m set updated_at = now()
   where m.organisation_id = new.organisation_id and m.id = new.mutation_id;
  return null;
end
$$;
create trigger approval_chains_refresh_mutation after insert on action.approval_chains
  for each row when (new.mutation_id is not null)
  execute function action.approval_chains_refresh_mutation();

grant select, insert on action.approval_chains to silo_app;
grant update (status, closed_at, updated_at, version) on action.approval_chains to silo_app;
grant select on action.approval_chains to silo_report;

create table action.approval_steps (
  id                      uuid primary key,
  organisation_id         uuid not null references iam.organisations (id),
  chain_id                uuid not null,
  sequence                integer check (sequence is null or sequence >= 1),
  qualifying_rule         text not null check (length(btrim(qualifying_rule)) > 0),
  qualifying_role_id      uuid,
  offered_at              timestamptz,
  approver_membership_id  uuid,
  decision                text check (decision in ('approved', 'rejected')),
  self_approval           boolean not null default false,
  holds_actuation_approve boolean not null default false,
  decided_at              timestamptz,
  comment                 text,
  created_at              timestamptz not null default now(),
  unique (organisation_id, id),
  -- Distinct approvers: one person cannot satisfy two required approvals. Nulls are
  -- distinct, so empty slots do not collide.
  constraint approval_steps_one_per_approver unique (organisation_id, chain_id, approver_membership_id),
  constraint approval_steps_sequence_key unique (organisation_id, chain_id, sequence),
  constraint approval_steps_chain_fkey
    foreign key (organisation_id, chain_id) references action.approval_chains (organisation_id, id),
  constraint approval_steps_approver_fkey
    foreign key (organisation_id, approver_membership_id) references iam.memberships (organisation_id, id),
  constraint approval_steps_qualifying_role_fkey
    foreign key (organisation_id, qualifying_role_id) references iam.roles (organisation_id, id),
  check ((approver_membership_id is null) = (decision is null)),
  check ((decision is null) = (decided_at is null)),
  check (not self_approval or decision = 'approved'),
  check (decision is not null or not holds_actuation_approve)
);
comment on table action.approval_steps is
  'Slots in a chain and the decisions made in them; one row per required approval, decided once (ch 44).';
comment on column action.approval_steps.sequence is 'Null when parallel.';
comment on column action.approval_steps.qualifying_rule is
  'Id of the union condition in the chain''s policy_snapshot that this step satisfies.';
comment on column action.approval_steps.offered_at is
  'When the step may be acted on; for a sequential chain, when the previous step is approved.';
comment on column action.approval_steps.self_approval is
  'Set by trigger: the approver is the chain''s requester. Never set by the caller.';
comment on column action.approval_steps.holds_actuation_approve is
  'Recorded by the approvals service at decision time, after permission resolution.';
create unique index approval_steps_one_self_approval on action.approval_steps (organisation_id, chain_id)
  where self_approval;
create index approval_steps_open on action.approval_steps (organisation_id, chain_id)
  where decided_at is null and offered_at is not null;
create index approval_steps_inbox_by_role on action.approval_steps (organisation_id, qualifying_role_id)
  where decided_at is null and offered_at is not null and qualifying_role_id is not null;
create index approval_steps_approver on action.approval_steps (organisation_id, approver_membership_id, decided_at desc)
  where approver_membership_id is not null;
create index approval_steps_self_approvals on action.approval_steps (organisation_id, decided_at)
  where self_approval;
select platform.enable_tenant_rls('action.approval_steps');

-- Steps are created empty in a pending chain, naming a condition of its snapshot.
-- Before a decision only offered_at changes (once). A decision is made once, on an
-- offered step, in a pending, unexpired chain, after every earlier sequential step is
-- approved. self_approval is set here from the chain's requester; it is refused
-- unless the step's snapshot condition permits it, and always for physical.
create function action.approval_steps_guard() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
declare
  v_chain record;
  v_decision_columns constant text[] := array['offered_at', 'approver_membership_id', 'decision', 'self_approval',
                                              'holds_actuation_approve', 'decided_at', 'comment'];
begin
  select c.status, c.expires_at, c.requester_membership_id, c.risk_class, c.policy_snapshot
    into v_chain
  from action.approval_chains c
  where c.organisation_id = new.organisation_id and c.id = new.chain_id
  for no key update;
  if not found then
    return new;  -- the foreign key reports it
  end if;

  if tg_op = 'INSERT' then
    if v_chain.status <> 'pending' then
      raise exception 'steps are added only to a pending chain' using errcode = 'check_violation';
    end if;
    if new.approver_membership_id is not null or new.decision is not null then
      raise exception 'a step is created empty and decided once by update' using errcode = 'check_violation';
    end if;
    if not jsonb_path_exists(v_chain.policy_snapshot, '$.conditions[*] ? (@.id == $rule)',
                             jsonb_build_object('rule', new.qualifying_rule)) then
      raise exception 'qualifying_rule % names no condition in the chain snapshot', new.qualifying_rule
        using errcode = 'check_violation';
    end if;
    new.self_approval := false;
    return new;
  end if;

  if old.decision is not null then
    raise exception 'approval step % is decided; it never changes', old.id using errcode = 'insufficient_privilege';
  end if;
  if (to_jsonb(new) - v_decision_columns) <> (to_jsonb(old) - v_decision_columns) then
    raise exception 'only the offer and the decision of an approval step may change' using errcode = 'insufficient_privilege';
  end if;
  if old.offered_at is not null and new.offered_at is distinct from old.offered_at then
    raise exception 'offered_at is set once' using errcode = 'insufficient_privilege';
  end if;

  if new.decision is null then
    new.self_approval := false;
    return new;
  end if;

  if v_chain.status <> 'pending' then
    raise exception 'the chain is %: decisions are made only on a pending chain', v_chain.status
      using errcode = 'check_violation';
  end if;
  if now() >= v_chain.expires_at then
    raise exception 'the chain has expired' using errcode = 'check_violation';
  end if;
  if new.offered_at is null then
    raise exception 'a step is decided only once offered' using errcode = 'check_violation';
  end if;
  if new.sequence is not null and exists (
       select 1 from action.approval_steps s
       where s.organisation_id = new.organisation_id and s.chain_id = new.chain_id
         and s.sequence < new.sequence and s.decision is distinct from 'approved') then
    raise exception 'sequential steps are decided in order' using errcode = 'check_violation';
  end if;

  new.self_approval := new.approver_membership_id = v_chain.requester_membership_id;
  if new.self_approval then
    if new.decision <> 'approved' then
      raise exception 'the requester cannot decide their own chain except by permitted self-approval'
        using errcode = 'check_violation';
    end if;
    if v_chain.risk_class = 'physical' then
      raise exception 'self-approval is never permitted for a physical Action' using errcode = 'check_violation';
    end if;
    if not jsonb_path_exists(v_chain.policy_snapshot,
                             '$.conditions[*] ? (@.id == $rule && @.self_approval_permitted == true)',
                             jsonb_build_object('rule', new.qualifying_rule)) then
      raise exception 'self-approval is not permitted by this step''s policy condition'
        using errcode = 'check_violation';
    end if;
  end if;
  return new;
end
$$;
create trigger approval_steps_guard before insert or update on action.approval_steps
  for each row execute function action.approval_steps_guard();

-- A decision refreshes the chain, whose own trigger recounts approvals_received.
create function action.approval_steps_refresh_chain() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
begin
  update action.approval_chains c set updated_at = now()
   where c.organisation_id = new.organisation_id and c.id = new.chain_id;
  return null;
end
$$;
create trigger approval_steps_refresh_chain after update on action.approval_steps
  for each row when (old.decision is null and new.decision is not null)
  execute function action.approval_steps_refresh_chain();

grant select, insert on action.approval_steps to silo_app;
grant update (offered_at, approver_membership_id, decision, holds_actuation_approve, decided_at, comment)
  on action.approval_steps to silo_app;
grant select on action.approval_steps to silo_report;

create table action.approval_chain_connections (
  id              uuid primary key,
  organisation_id uuid not null references iam.organisations (id),
  chain_id        uuid not null,
  connection_id   uuid not null,
  created_at      timestamptz not null default now(),
  unique (organisation_id, id),
  constraint approval_chain_connections_key unique (organisation_id, chain_id, connection_id),
  constraint approval_chain_connections_chain_fkey
    foreign key (organisation_id, chain_id) references action.approval_chains (organisation_id, id)
);
comment on table action.approval_chain_connections is
  'Connections a chain covers, so the approvals inbox finds chains a membership may approve (44.3).';
create index approval_chain_connections_connection
  on action.approval_chain_connections (organisation_id, connection_id, chain_id);
select platform.enable_tenant_rls('action.approval_chain_connections');
select platform.make_append_only('action.approval_chain_connections');

grant select, insert on action.approval_chain_connections to silo_app;
grant select on action.approval_chain_connections to silo_report;

-- Specification 08 names, kept addressable (44.1). Invoker rights, so base RLS applies.
create view action.mutation_chains with (security_invoker = true) as
  select c.id,
         c.organisation_id,
         c.mutation_id,
         c.policy_snapshot as snapshotted_policy,
         c.approvals_required,
         c.approvals_received,
         c.status,
         c.expires_at
  from action.approval_chains c
  where c.subject_kind = 'mutation';
comment on view action.mutation_chains is 'Read-only view of mutation approval chains with the specification 08 names.';

create view action.mutation_approvals with (security_invoker = true) as
  select s.chain_id,
         s.organisation_id,
         s.sequence,
         s.approver_membership_id as approver,
         s.decision,
         s.comment,
         s.decided_at
  from action.approval_steps s
  join action.approval_chains c on c.organisation_id = s.organisation_id and c.id = s.chain_id
  where c.subject_kind = 'mutation' and s.approver_membership_id is not null;
comment on view action.mutation_approvals is 'Read-only view of decided steps of mutation chains with the specification 08 names.';

grant select on action.mutation_chains, action.mutation_approvals to silo_app, silo_report;

-- ===========================================================================
-- Execution and verification
-- ===========================================================================

create table action.mutation_executions (
  id                        uuid primary key,
  organisation_id           uuid not null references iam.organisations (id),
  mutation_id               uuid not null,
  connection_id             uuid not null,
  phase                     text not null check (phase in ('canary', 'full')),
  status                    text not null default 'pending'
                              check (status in ('pending', 'executing', 'succeeded', 'partially_succeeded', 'failed')),
  executed_by_membership_id uuid,
  executed_by_principal_id  uuid,
  connector_version         text not null,
  records_attempted         integer not null default 0 check (records_attempted >= 0),
  records_applied           integer not null default 0 check (records_applied >= 0 and records_applied <= records_attempted),
  attempted_at              timestamptz,
  completed_at              timestamptz,
  error                     text,
  created_at                timestamptz not null default now(),
  updated_at                timestamptz not null default now(),
  unique (organisation_id, id),
  constraint mutation_executions_phase_key unique (organisation_id, mutation_id, connection_id, phase),
  constraint mutation_executions_mutation_fkey
    foreign key (organisation_id, mutation_id) references action.mutations (organisation_id, id),
  constraint mutation_executions_executed_by_membership_fkey
    foreign key (organisation_id, executed_by_membership_id) references iam.memberships (organisation_id, id),
  constraint mutation_executions_executed_by_principal_fkey
    foreign key (organisation_id, executed_by_principal_id) references iam.service_principals (organisation_id, id),
  check (num_nonnulls(executed_by_membership_id, executed_by_principal_id) <= 1),
  check (status = 'pending' or num_nonnulls(executed_by_membership_id, executed_by_principal_id) = 1),
  check ((status in ('succeeded', 'partially_succeeded', 'failed')) = (completed_at is not null))
);
comment on table action.mutation_executions is
  'Execution of one mutation against one connection in one phase, with counts and error class (ch 45).';
comment on column action.mutation_executions.error is
  'Semantic class (auth, rate_limit, not_found, upstream, bounds) with redacted detail; never values.';
create index mutation_executions_connection on action.mutation_executions (organisation_id, connection_id, created_at desc);
create index mutation_executions_executed_by_membership on action.mutation_executions (organisation_id, executed_by_membership_id)
  where executed_by_membership_id is not null;
create index mutation_executions_executed_by_principal on action.mutation_executions (organisation_id, executed_by_principal_id)
  where executed_by_principal_id is not null;
create index mutation_executions_resume on action.mutation_executions (organisation_id, status)
  where status in ('pending', 'executing');
select platform.add_updated_at_trigger('action.mutation_executions');
select platform.enable_tenant_rls('action.mutation_executions');

-- The execution guard (enforcement summary). When an execution is created or starts
-- (leaves pending other than as failed): the mutation is approved (or in canary or
-- executing) and has a satisfied, unexpired chain for its stored diff and class, or
-- is an in-bounds Cron run executed by its own service principal (never physical);
-- a full phase at 10,000 rows or more needs a succeeded canary and a recorded
-- confirmation. Whenever an executor is recorded: with separated execution it is not
-- the proposer. Identity, phase and the executor are fixed once set, and a completed
-- execution never changes.
create function action.mutation_executions_guard() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
declare
  m            record;
  v_start      boolean;
  v_executor   boolean;
  v_chain_ok   boolean;
  v_cron_ok    boolean;
begin
  if tg_op = 'UPDATE' then
    if old.completed_at is not null and (to_jsonb(new) - 'updated_at') <> (to_jsonb(old) - 'updated_at') then
      raise exception 'a completed execution never changes' using errcode = 'insufficient_privilege';
    end if;
    if (new.id, new.organisation_id, new.mutation_id, new.connection_id, new.phase, new.created_at, new.connector_version)
       is distinct from (old.id, old.organisation_id, old.mutation_id, old.connection_id, old.phase, old.created_at,
                         old.connector_version) then
      raise exception 'an execution''s mutation, connection, phase and connector version are fixed'
        using errcode = 'insufficient_privilege';
    end if;
    if num_nonnulls(old.executed_by_membership_id, old.executed_by_principal_id) > 0
       and (new.executed_by_membership_id, new.executed_by_principal_id)
           is distinct from (old.executed_by_membership_id, old.executed_by_principal_id) then
      raise exception 'the executor is recorded once' using errcode = 'insufficient_privilege';
    end if;
    v_start := old.status = 'pending' and new.status in ('executing', 'succeeded', 'partially_succeeded');
    v_executor := (new.executed_by_membership_id, new.executed_by_principal_id)
                  is distinct from (old.executed_by_membership_id, old.executed_by_principal_id);
  else
    v_start := true;
    v_executor := true;
  end if;

  if not (v_start or v_executor) then
    return new;
  end if;

  select mu.status, mu.risk_class, mu.diff_hash, mu.row_count, mu.origin, mu.cron_mode, mu.execution_separated,
         mu.proposer_membership_id, mu.proposer_principal_id, mu.authorising_membership_id, mu.canary_confirmed_at
    into m
  from action.mutations mu
  where mu.organisation_id = new.organisation_id and mu.id = new.mutation_id;
  if not found then
    return new;  -- the foreign key reports it
  end if;

  if v_start then
    if m.status not in ('approved', 'canary', 'executing') then
      raise exception 'the mutation is %: only an approved mutation executes', m.status using errcode = 'check_violation';
    end if;

    v_chain_ok := exists (
      select 1 from action.approval_chains c
      where c.organisation_id = new.organisation_id and c.mutation_id = new.mutation_id
        and c.status = 'approved' and now() < c.expires_at
        and c.diff_hash = m.diff_hash and c.risk_class = m.risk_class);
    v_cron_ok := m.cron_mode is not distinct from 'execute_within_bounds'
                 and m.risk_class = 'data'
                 and new.executed_by_membership_id is null
                 and (new.executed_by_principal_id is null or new.executed_by_principal_id = m.proposer_principal_id);
    if not (v_chain_ok or v_cron_ok) then
      raise exception 'execution needs a satisfied, unexpired approval chain for the stored diff, or an in-bounds Cron run'
        using errcode = 'insufficient_privilege';
    end if;

    if new.phase = 'full' and m.row_count >= 10000 and (
         m.canary_confirmed_at is null
         or not exists (select 1 from action.mutation_executions e
                        where e.organisation_id = new.organisation_id and e.mutation_id = new.mutation_id
                          and e.phase = 'canary' and e.status = 'succeeded')) then
      raise exception 'at 10,000 rows or more the full phase needs a succeeded canary and a recorded confirmation'
        using errcode = 'check_violation';
    end if;
  end if;

  if m.execution_separated and (
       new.executed_by_membership_id = m.proposer_membership_id
       or new.executed_by_membership_id = m.authorising_membership_id
       or (m.origin <> 'cron' and new.executed_by_principal_id = m.proposer_principal_id)) then
    raise exception 'separated execution: the executor may not be the proposer' using errcode = 'insufficient_privilege';
  end if;

  return new;
end
$$;
create trigger mutation_executions_guard before insert or update on action.mutation_executions
  for each row execute function action.mutation_executions_guard();

grant select, insert on action.mutation_executions to silo_app;
grant update (status, executed_by_membership_id, executed_by_principal_id, records_attempted, records_applied,
              attempted_at, completed_at, error, updated_at)
  on action.mutation_executions to silo_app;
grant select on action.mutation_executions to silo_report;

-- Canaries whose chain expired unconfirmed, across organisations (45.4): identifiers only,
-- for the actions sweep, which finishes each under its organisation's context.
create function action.canaries_expired(p_now timestamptz, p_limit integer)
  returns table (organisation_id uuid, id uuid)
language sql stable security definer
set search_path = pg_catalog
as $$
  select m.organisation_id, m.id from action.mutations m
  where m.status = 'canary' and m.expires_at < p_now
    and not exists (select 1 from action.mutation_executions e
                    where e.organisation_id = m.organisation_id and e.mutation_id = m.id and e.phase = 'canary' and e.completed_at is null)
  order by m.expires_at, m.id
  limit least(greatest(p_limit, 1), 1000)
$$;
revoke all on function action.canaries_expired(timestamptz, integer) from public;
grant execute on function action.canaries_expired(timestamptz, integer) to silo_app;

-- Executions a process started and never finished (it died), across organisations: the
-- mutation and the phase, for the actions recovery sweep, which reads the sources to learn
-- what landed rather than writing again (45.3).
create function action.executions_interrupted(p_before timestamptz, p_limit integer)
  returns table (organisation_id uuid, mutation_id uuid, phase text)
language sql stable security definer
set search_path = pg_catalog
as $$
  select distinct e.organisation_id, e.mutation_id, e.phase from action.mutation_executions e
  join action.mutations m on m.organisation_id = e.organisation_id and m.id = e.mutation_id
  where e.completed_at is null and e.attempted_at < p_before and m.status in ('executing', 'canary')
  order by e.mutation_id
  limit least(greatest(p_limit, 1), 1000)
$$;
revoke all on function action.executions_interrupted(timestamptz, integer) from public;
grant execute on function action.executions_interrupted(timestamptz, integer) to silo_app;

create table action.mutation_verifications (
  id               uuid primary key,
  organisation_id  uuid not null references iam.organisations (id),
  execution_id     uuid not null,
  target_id        uuid not null,
  entity_reference text not null,
  field            text,
  intended         bytea,
  observed         bytea,
  outcome          text not null check (outcome in ('verified', 'diverged', 'failed')),
  reason           text,
  verified_at      timestamptz not null,
  purged_at        timestamptz,
  unique (organisation_id, id),
  constraint mutation_verifications_field_key
    unique nulls not distinct (organisation_id, execution_id, target_id, field),
  constraint mutation_verifications_execution_fkey
    foreign key (organisation_id, execution_id) references action.mutation_executions (organisation_id, id),
  constraint mutation_verifications_target_fkey
    foreign key (organisation_id, target_id) references action.mutation_targets (organisation_id, id)
);
comment on table action.mutation_verifications is
  'Per-field read-back comparison of intended and observed values after a write (45.6).';
comment on column action.mutation_verifications.field is
  'Null for record-level results (create identifier, delete absence).';
comment on column action.mutation_verifications.intended is 'Encrypted. Null for deletes and after purge.';
comment on column action.mutation_verifications.observed is 'Encrypted. Null when absent, failed or purged.';
comment on column action.mutation_verifications.reason is 'Semantic class such as not_observed, truncated, clamped. No values.';
create index mutation_verifications_target on action.mutation_verifications (organisation_id, target_id);
create index mutation_verifications_not_verified on action.mutation_verifications (organisation_id, execution_id, outcome)
  where outcome <> 'verified';
select platform.enable_tenant_rls('action.mutation_verifications');
create trigger mutation_verifications_purge_only before update on action.mutation_verifications
  for each row execute function action.purge_only('intended', 'observed');
create trigger mutation_verifications_no_delete before delete on action.mutation_verifications
  for each row execute function platform.reject_ledger_change('strict');
create trigger mutation_verifications_no_truncate before truncate on action.mutation_verifications
  for each statement execute function platform.reject_ledger_change();

grant select, insert on action.mutation_verifications to silo_app;
grant select (id, organisation_id, execution_id, target_id, entity_reference, field, outcome, reason, verified_at,
              purged_at)
  on action.mutation_verifications to silo_report;

-- ===========================================================================
-- Receipts, history and revert
-- ===========================================================================

create table action.receipts (
  id                 uuid primary key,
  organisation_id    uuid not null references iam.organisations (id),
  mutation_id        uuid not null,
  document           bytea,
  reference_summary  jsonb not null check (jsonb_typeof(reference_summary) = 'object'),
  document_hash      bytea not null check (octet_length(document_hash) = 32),
  dry_run            boolean not null default false,
  reverts_receipt_id uuid,
  created_at         timestamptz not null default now(),
  retention_until    timestamptz not null,
  purged_at          timestamptz,
  unique (organisation_id, id),
  constraint receipts_mutation_key unique (organisation_id, mutation_id),
  -- Deferred: the mutation may itself reference a dry-run receipt.
  constraint receipts_mutation_fkey
    foreign key (organisation_id, mutation_id) references action.mutations (organisation_id, id)
    deferrable initially deferred,
  constraint receipts_reverts_receipt_fkey
    foreign key (organisation_id, reverts_receipt_id) references action.receipts (organisation_id, id),
  check ((document is null) = (purged_at is not null)),
  check (reverts_receipt_id is distinct from id)
);
comment on table action.receipts is
  'The immutable, hashed record of one mutation, which a reviewer reads (46.1). Insert-only; purge nulls the document.';
comment on column action.receipts.document is
  'Canonical JSON encrypted as one blob (AES-256-GCM). Null only after purge.';
comment on column action.receipts.reference_summary is
  'Value-free part kept after purge: type and version, class, executor, approvers, self-approval, counts, commits.';
comment on column action.receipts.document_hash is
  'SHA-256 of the canonical document before encryption; also written to audit.audit_events. Survives purge.';
comment on column action.receipts.reverts_receipt_id is
  'Receipt this one reverts; equals the reverted_receipt_id of the revert for the same mutation (trigger).';
create index receipts_list on action.receipts (organisation_id, created_at desc);
create index receipts_retention on action.receipts (organisation_id, retention_until) where purged_at is null;
create index receipts_reverts_receipt on action.receipts (organisation_id, reverts_receipt_id)
  where reverts_receipt_id is not null;
select platform.enable_tenant_rls('action.receipts');
create trigger receipts_purge_only before update on action.receipts
  for each row execute function action.purge_only('document');
create trigger receipts_no_delete before delete on action.receipts
  for each row execute function platform.reject_ledger_change('strict');
create trigger receipts_no_truncate before truncate on action.receipts
  for each statement execute function platform.reject_ledger_change();

-- Receipt insert: reverts_receipt_id equals the reverted receipt of the revert row
-- for the same mutation (both null when the mutation is not a revert), and the
-- receipt is a dry run exactly when its mutation is.
create function action.receipts_insert_guard() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
declare
  v_reverted uuid;
begin
  select r.reverted_receipt_id into v_reverted
  from action.reverts r
  where r.organisation_id = new.organisation_id and r.new_mutation_id = new.mutation_id;
  if new.reverts_receipt_id is distinct from v_reverted then
    raise exception 'reverts_receipt_id must equal the receipt reverted by this mutation''s revert'
      using errcode = 'check_violation';
  end if;
  if exists (select 1 from action.mutations m
             where m.organisation_id = new.organisation_id and m.id = new.mutation_id
               and m.dry_run is distinct from new.dry_run) then
    raise exception 'a receipt is a dry run exactly when its mutation is' using errcode = 'check_violation';
  end if;
  return new;
end
$$;
create trigger receipts_insert_guard before insert on action.receipts
  for each row execute function action.receipts_insert_guard();

grant select, insert on action.receipts to silo_app;
grant select (id, organisation_id, mutation_id, reference_summary, document_hash, dry_run, reverts_receipt_id,
              created_at, retention_until, purged_at)
  on action.receipts to silo_report;

-- Append-only ledger. A uuid id (not bigint identity) because receipts, ledger rows
-- and parent links name it: a documented exception to the ledger key rule. The
-- spec's unique (object_id, parent_commit_id) is enforced by action.object_heads.
create table action.action_commits (
  id                      uuid not null,
  organisation_id         uuid not null references iam.organisations (id),
  object_id               uuid not null,
  object_type_id          uuid not null,
  mutation_id             uuid not null,
  receipt_id              uuid not null,
  parent_commit_id        uuid,
  reverts_commit_id       uuid,
  author_membership_id    uuid not null,
  approver_membership_ids uuid[] not null default '{}' check (array_position(approver_membership_ids, null) is null),
  executor_membership_id  uuid,
  executor_principal_id   uuid,
  self_approved           boolean not null default false,
  fields_changed          text[] not null default '{}' check (array_position(fields_changed, null) is null),
  object_diff_hash        bytea check (object_diff_hash is null or octet_length(object_diff_hash) = 32),
  outcome                 text not null check (outcome in ('verified', 'diverged', 'failed')),
  scenario_id             uuid,
  committed_at            timestamptz not null default now(),
  primary key (id, committed_at),
  constraint action_commits_mutation_fkey
    foreign key (organisation_id, mutation_id) references action.mutations (organisation_id, id),
  constraint action_commits_receipt_fkey
    foreign key (organisation_id, receipt_id) references action.receipts (organisation_id, id),
  constraint action_commits_author_fkey
    foreign key (organisation_id, author_membership_id) references iam.memberships (organisation_id, id),
  constraint action_commits_executor_membership_fkey
    foreign key (organisation_id, executor_membership_id) references iam.memberships (organisation_id, id),
  constraint action_commits_executor_principal_fkey
    foreign key (organisation_id, executor_principal_id) references iam.service_principals (organisation_id, id),
  check (num_nonnulls(executor_membership_id, executor_principal_id) = 1),
  check (parent_commit_id is distinct from id),
  check (reverts_commit_id is distinct from id)
) partition by range (committed_at);
comment on table action.action_commits is
  'Append-only, Git-like history of governed changes per object; monthly partitions (46.2).';
comment on column action.action_commits.object_id is 'Ontology object identity (decision 1); no foreign key.';
comment on column action.action_commits.parent_commit_id is 'Null for an object''s first commit. No foreign key (ledger).';
comment on column action.action_commits.reverts_commit_id is
  'Set when this commit is a revert; its parent is still the object''s latest commit. No foreign key.';
comment on column action.action_commits.author_membership_id is 'Proposer, or the authorising person for a Cron.';
comment on column action.action_commits.approver_membership_ids is
  'No element key; validated when the chain was satisfied.';
comment on column action.action_commits.object_diff_hash is
  'Hash of this object''s slice of the diff; the diff is read from the receipt by (receipt_id, object_id).';
comment on column action.action_commits.scenario_id is 'Provenance only: the commit came from a scenario promotion.';
create index action_commits_object_log on action.action_commits (organisation_id, object_id, committed_at desc);
create index action_commits_mutation on action.action_commits (organisation_id, mutation_id);
create index action_commits_author on action.action_commits (organisation_id, author_membership_id, committed_at desc);
create index action_commits_object_type on action.action_commits (organisation_id, object_type_id);
