create table action.object_heads (
  id              uuid primary key,
  organisation_id uuid not null references iam.organisations (id),
  object_id       uuid not null,
  object_type_id  uuid not null,
  head_commit_id  uuid not null,
  commit_count    bigint not null default 1 check (commit_count >= 1),
  updated_at      timestamptz not null default now(),
  created_at      timestamptz not null default now(),
  unique (organisation_id, id),
  constraint object_heads_object_key unique (organisation_id, object_id)
);
comment on table action.object_heads is
  'Current head commit of each object: serialises commits by compare and swap and gives the next parent (46.2).';
comment on column action.object_heads.object_id is 'Ontology object identity (decision 1); no foreign key.';
comment on column action.object_heads.head_commit_id is 'Latest commit in action.action_commits. No foreign key (ledger).';
create index object_heads_object_type on action.object_heads (organisation_id, object_type_id);
select platform.add_updated_at_trigger('action.object_heads');
select platform.enable_tenant_rls('action.object_heads');

-- Compare and swap: the head moves only with commit_count increasing by exactly one,
-- and the count never moves without the head.
create function action.object_heads_guard() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
begin
  if (new.id, new.organisation_id, new.object_id, new.object_type_id, new.created_at)
     is distinct from (old.id, old.organisation_id, old.object_id, old.object_type_id, old.created_at) then
    raise exception 'an object head''s identity is fixed' using errcode = 'insufficient_privilege';
  end if;
  if new.head_commit_id is distinct from old.head_commit_id then
    if new.commit_count <> old.commit_count + 1 then
      raise exception 'the head moves only with commit_count increasing by exactly one' using errcode = 'check_violation';
    end if;
  elsif new.commit_count <> old.commit_count then
    raise exception 'commit_count changes only with the head' using errcode = 'check_violation';
  end if;
  return new;
end
$$;
create trigger object_heads_guard before update on action.object_heads
  for each row execute function action.object_heads_guard();

grant select, insert on action.object_heads to silo_app;
grant update (head_commit_id, commit_count, updated_at) on action.object_heads to silo_app;
grant select on action.object_heads to silo_report;

create table action.reverts (
  id                  uuid primary key,
  organisation_id     uuid not null references iam.organisations (id),
  reverted_receipt_id uuid not null,
  new_mutation_id     uuid not null,
  scope               text not null check (scope in ('full', 'partial_objects', 'partial_connections', 'succeeded_half')),
  conflict_count      integer not null default 0 check (conflict_count >= 0),
  resolved_per_field  boolean not null default false,
  requested_by        uuid not null,
  requested_at        timestamptz not null default now(),
  updated_at          timestamptz not null default now(),
  unique (organisation_id, id),
  constraint reverts_new_mutation_key unique (organisation_id, new_mutation_id),
  constraint reverts_reverted_receipt_fkey
    foreign key (organisation_id, reverted_receipt_id) references action.receipts (organisation_id, id),
  constraint reverts_new_mutation_fkey
    foreign key (organisation_id, new_mutation_id) references action.mutations (organisation_id, id),
  constraint reverts_requested_by_fkey
    foreign key (organisation_id, requested_by) references iam.memberships (organisation_id, id)
);
comment on table action.reverts is
  'Links a revert mutation to the receipt it reverts, with scope and conflict summary (ch 46).';
comment on column action.reverts.new_mutation_id is 'The mutation that performs the revert; its origin is revert.';
comment on column action.reverts.conflict_count is 'Count of revert_conflicts rows, maintained by trigger.';
comment on column action.reverts.requested_by is 'Membership holding mutation.revert.';
create index reverts_reverted_receipt on action.reverts (organisation_id, reverted_receipt_id);
create index reverts_requested_by on action.reverts (organisation_id, requested_by, requested_at desc);
select platform.add_updated_at_trigger('action.reverts');
select platform.enable_tenant_rls('action.reverts');

-- Insert: the new mutation's origin is revert. Update: conflict_count is recounted
-- from revert_conflicts; only it, resolved_per_field and updated_at change, and only
-- while the revert mutation is before approval.
create function action.reverts_guard() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
declare
  v_origin text;
  v_status text;
begin
  select m.origin, m.status into v_origin, v_status
  from action.mutations m
  where m.organisation_id = new.organisation_id and m.id = new.new_mutation_id;

  if tg_op = 'INSERT' then
    if v_origin is distinct from 'revert' then
      raise exception 'a revert is performed by a mutation whose origin is revert' using errcode = 'check_violation';
    end if;
    new.conflict_count := 0;
    return new;
  end if;

  select count(*) into new.conflict_count
  from action.revert_conflicts rc
  where rc.organisation_id = new.organisation_id and rc.revert_id = new.id;

  if (to_jsonb(new) - array['conflict_count', 'resolved_per_field', 'updated_at'])
     <> (to_jsonb(old) - array['conflict_count', 'resolved_per_field', 'updated_at']) then
    raise exception 'only conflict_count and resolved_per_field change on a revert' using errcode = 'insufficient_privilege';
  end if;
  if v_status not in ('previewed', 'awaiting_approval') then
    raise exception 'a revert changes only before its mutation is approved' using errcode = 'check_violation';
  end if;
  return new;
end
$$;
create trigger reverts_guard before insert or update on action.reverts
  for each row execute function action.reverts_guard();

grant select, insert on action.reverts to silo_app;
grant update (resolved_per_field, updated_at) on action.reverts to silo_app;
grant select on action.reverts to silo_report;

create table action.revert_conflicts (
  id               uuid primary key,
  organisation_id  uuid not null references iam.organisations (id),
  revert_id        uuid not null,
  object_id        uuid not null,
  entity_reference text not null,
  field            text,
  kind             text not null
                     check (kind in ('field_changed', 'record_missing', 'record_reappeared', 'created_record_changed')),
  post_write_value bytea,
  current_value    bytea,
  changed_by       text,
  decision         text check (decision in ('restore_prior', 'keep_current', 'exclude_record')),
  decided_by       uuid,
  decided_at       timestamptz,
  created_at       timestamptz not null default now(),
  purged_at        timestamptz,
  unique (organisation_id, id),
  constraint revert_conflicts_field_key
    unique nulls not distinct (organisation_id, revert_id, object_id, entity_reference, field),
  constraint revert_conflicts_revert_fkey
    foreign key (organisation_id, revert_id) references action.reverts (organisation_id, id),
  constraint revert_conflicts_decided_by_fkey
    foreign key (organisation_id, decided_by) references iam.memberships (organisation_id, id),
  check (kind in ('field_changed', 'created_record_changed') or field is null),
  check (kind in ('field_changed', 'created_record_changed') or (post_write_value is null and current_value is null)),
  check (num_nonnulls(decision, decided_by, decided_at) in (0, 3))
);
comment on table action.revert_conflicts is
  'Per-field conflicts found by the three-way comparison and the decision on each (46.3).';
comment on column action.revert_conflicts.object_id is 'Ontology object identity (decision 1); no foreign key.';
comment on column action.revert_conflicts.post_write_value is 'Encrypted. Null for record-level kinds and after purge.';
comment on column action.revert_conflicts.current_value is 'Encrypted. Null for record-level kinds and after purge.';
comment on column action.revert_conflicts.changed_by is
  'Where knowable: a later commit, a Capture transition or a mapped source audit field.';
create index revert_conflicts_decided_by on action.revert_conflicts (organisation_id, decided_by)
  where decided_by is not null;
create index revert_conflicts_undecided on action.revert_conflicts (organisation_id, revert_id)
  where decision is null;
select platform.enable_tenant_rls('action.revert_conflicts');
create trigger revert_conflicts_no_delete before delete on action.revert_conflicts
  for each row execute function platform.reject_ledger_change('strict');
create trigger revert_conflicts_no_truncate before truncate on action.revert_conflicts
  for each statement execute function platform.reject_ledger_change();

-- The decision is set once; values never change; purge (silo_migrate) nulls the two
-- value columns and stamps purged_at.
create function action.revert_conflicts_guard() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
declare
  v_values   constant text[] := array['post_write_value', 'current_value'];
  v_decision constant text[] := array['decision', 'decided_by', 'decided_at'];
begin
  if old.purged_at is null and new.purged_at is not null then
    if current_user <> 'silo_migrate'
       or new.post_write_value is not null or new.current_value is not null
       or (to_jsonb(old) - v_values - 'purged_at') <> (to_jsonb(new) - v_values - 'purged_at') then
      raise exception 'purge (silo_migrate) nulls the two value columns and changes nothing else'
        using errcode = 'insufficient_privilege';
    end if;
    return new;
  end if;
  if old.decision is not null or (to_jsonb(old) - v_decision) <> (to_jsonb(new) - v_decision) then
    raise exception 'a conflict decision is set once and values never change' using errcode = 'insufficient_privilege';
  end if;
  return new;
end
$$;
create trigger revert_conflicts_guard before update on action.revert_conflicts
  for each row execute function action.revert_conflicts_guard();

-- A new conflict refreshes its revert, whose own trigger recounts conflict_count.
create function action.revert_conflicts_refresh_revert() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
begin
  update action.reverts r set updated_at = now()
   where r.organisation_id = new.organisation_id and r.id = new.revert_id;
  return null;
end
$$;
create trigger revert_conflicts_refresh_revert after insert on action.revert_conflicts
  for each row execute function action.revert_conflicts_refresh_revert();

grant select, insert on action.revert_conflicts to silo_app;
grant update (decision, decided_by, decided_at) on action.revert_conflicts to silo_app;
grant select (id, organisation_id, revert_id, object_id, entity_reference, field, kind, changed_by, decision,
              decided_by, decided_at, created_at, purged_at)
  on action.revert_conflicts to silo_report;

