-- ===========================================================================
-- Real-world actuation
-- ===========================================================================

create table action.actuation_allowlists (
  id                   uuid primary key,
  organisation_id      uuid not null references iam.organisations (id),
  connection_id        uuid not null,
  transport            text not null check (transport in ('mqtt', 'opcua', 'webhook')),
  node_address         text not null,
  kind                 text not null check (kind in ('setpoint', 'command', 'method')),
  data_type            text not null,
  min_value            numeric,
  max_value            numeric,
  max_step             numeric check (max_step is null or max_step > 0),
  min_interval_seconds integer not null check (min_interval_seconds >= 0),
  inverse_command      text,
  simulator_address    text,
  arguments            jsonb check (arguments is null or (transport = 'opcua' and kind = 'method'
                         and jsonb_typeof(arguments) = 'array' and jsonb_array_length(arguments) between 1 and 10)),
  object_id            uuid not null,
  added_by             uuid not null,
  approved_by          uuid not null,
  approved_at          timestamptz not null,
  signature            bytea not null,
  signature_key_ref    text not null,
  created_at           timestamptz not null default now(),
  removed_at           timestamptz,
  unique (organisation_id, id),
  constraint actuation_allowlists_added_by_fkey
    foreign key (organisation_id, added_by) references iam.memberships (organisation_id, id),
  constraint actuation_allowlists_approved_by_fkey
    foreign key (organisation_id, approved_by) references iam.memberships (organisation_id, id),
  check ((min_value is null) = (max_value is null)),
  check (min_value is null or min_value <= max_value),
  check (kind = 'setpoint' or (min_value is null and max_step is null)),
  check (inverse_command is null or kind in ('command', 'method')),
  check (approved_by <> added_by)
);
comment on table action.actuation_allowlists is
  'Signed allow-list of industrial nodes and physical endpoints Silo may write, added under two-person control (ch 47).';
comment on column action.actuation_allowlists.node_address is 'Node identifier, topic or path.';
comment on column action.actuation_allowlists.simulator_address is 'Dry-run counterpart of the node.';
comment on column action.actuation_allowlists.arguments is
  'An OPC UA method''s input arguments in the order it declares them, each its name, data type and bounds (a range for a number, the values allowed for text); signed with the entry and checked at intent and by the agent (D245). Null for a method that takes none.';
comment on column action.actuation_allowlists.object_id is
  'Digital clone the node belongs to (ontology identity, decision 1); no foreign key.';
comment on column action.actuation_allowlists.signature is 'Control plane signature over the canonical entry.';
comment on column action.actuation_allowlists.signature_key_ref is 'Signing key used, so the agent can verify after rotation.';
create unique index actuation_allowlists_live_node
  on action.actuation_allowlists (organisation_id, connection_id, transport, node_address)
  where removed_at is null;
create index actuation_allowlists_connection on action.actuation_allowlists (organisation_id, connection_id, created_at desc);
create index actuation_allowlists_object on action.actuation_allowlists (organisation_id, object_id);
create index actuation_allowlists_added_by on action.actuation_allowlists (organisation_id, added_by);
create index actuation_allowlists_approved_by on action.actuation_allowlists (organisation_id, approved_by);
select platform.enable_tenant_rls('action.actuation_allowlists');
create trigger actuation_allowlists_no_delete before delete on action.actuation_allowlists
  for each row execute function platform.reject_ledger_change('strict');
create trigger actuation_allowlists_no_truncate before truncate on action.actuation_allowlists
  for each statement execute function platform.reject_ledger_change();

-- Signed entries: the only change is setting removed_at, once. An edit is a removal
-- plus a new signed entry.
create function action.actuation_allowlists_guard() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
begin
  if old.removed_at is not null or new.removed_at is null
     or (to_jsonb(new) - 'removed_at') <> (to_jsonb(old) - 'removed_at') then
    raise exception 'allow-list entries are signed: only removed_at may be set, once'
      using errcode = 'insufficient_privilege';
  end if;
  return new;
end
$$;
create trigger actuation_allowlists_guard before update on action.actuation_allowlists
  for each row execute function action.actuation_allowlists_guard();

grant select, insert on action.actuation_allowlists to silo_app;
grant update (removed_at) on action.actuation_allowlists to silo_app;
grant select on action.actuation_allowlists to silo_report;

-- A requested allow-list entry, waiting for the second person (47.4). Added for the
-- two-person rule: an entry is inserted only once approved, signed.
create table action.actuation_allowlist_requests (
  id                         uuid primary key,
  organisation_id            uuid not null references iam.organisations (id),
  connection_id              uuid not null,
  transport                  text not null check (transport in ('mqtt', 'opcua', 'webhook')),
  entry                      jsonb not null check (jsonb_typeof(entry) = 'object'),
  requested_by               uuid not null,
  requester_holds_actuation  boolean not null,
  status                     text not null default 'pending' check (status in ('pending', 'approved', 'rejected')),
  decided_by                 uuid,
  decided_at                 timestamptz,
  entry_id                   uuid,
  created_at                 timestamptz not null default now(),
  unique (organisation_id, id),
  constraint actuation_allowlist_requests_requested_by_fkey
    foreign key (organisation_id, requested_by) references iam.memberships (organisation_id, id),
  constraint actuation_allowlist_requests_decided_by_fkey
    foreign key (organisation_id, decided_by) references iam.memberships (organisation_id, id),
  constraint actuation_allowlist_requests_entry_fkey
    foreign key (organisation_id, entry_id) references action.actuation_allowlists (organisation_id, id),
  check ((status = 'pending') = (decided_by is null and decided_at is null)),
  check (decided_by is null or decided_by <> requested_by),
  check ((status = 'approved') = (entry_id is not null))
);
comment on table action.actuation_allowlist_requests is
  'Allow-list entries asked for and waiting for a second person; approved, the signed entry is inserted (47.4).';
create index actuation_allowlist_requests_pending on action.actuation_allowlist_requests (organisation_id, connection_id, created_at)
  where status = 'pending';
create index actuation_allowlist_requests_requested_by on action.actuation_allowlist_requests (organisation_id, requested_by);
create index actuation_allowlist_requests_decided_by on action.actuation_allowlist_requests (organisation_id, decided_by);
create index actuation_allowlist_requests_entry on action.actuation_allowlist_requests (organisation_id, entry_id);
select platform.enable_tenant_rls('action.actuation_allowlist_requests');

-- Decided once: a pending request takes its decision, and nothing else changes.
create function action.actuation_allowlist_requests_guard() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
begin
  if old.status <> 'pending'
     or (to_jsonb(new) - array['status', 'decided_by', 'decided_at', 'entry_id']) <> (to_jsonb(old) - array['status', 'decided_by', 'decided_at', 'entry_id']) then
    raise exception 'an allow-list request is decided once, and nothing else about it changes'
      using errcode = 'insufficient_privilege';
  end if;
  return new;
end
$$;
create trigger actuation_allowlist_requests_guard before update on action.actuation_allowlist_requests
  for each row execute function action.actuation_allowlist_requests_guard();

-- Every node a physical write named and what became of it (47.5, 47.8): the last write time
-- and the connection's writes a minute at intent, and the nodes physical_action_executed
-- names. Never a value: the receipt holds those. Added.
create table action.physical_writes (
  id                  uuid primary key,
  organisation_id     uuid not null references iam.organisations (id),
  connection_id       uuid not null,
  mutation_id         uuid not null,
  allowlist_entry_id  uuid,
  node_address        text not null check (length(btrim(node_address)) > 0),
  outcome             text not null check (outcome in ('applied', 'rejected', 'refused', 'unknown', 'not_written')),
  reason              text check (reason is null or reason ~ '^[a-z_]{1,40}$'),
  dry_run             boolean not null default false,
  written_at          timestamptz not null default now(),
  unique (organisation_id, id),
  constraint physical_writes_mutation_fkey foreign key (organisation_id, mutation_id) references action.mutations (organisation_id, id),
  constraint physical_writes_entry_fkey foreign key (organisation_id, allowlist_entry_id) references action.actuation_allowlists (organisation_id, id)
);
comment on table action.physical_writes is
  'Each node a physical write named and its outcome: the last write and the rate at intent (47.5), the nodes the executed event names (47.8). No values.';
create index physical_writes_connection on action.physical_writes (organisation_id, connection_id, written_at desc);
create index physical_writes_mutation on action.physical_writes (organisation_id, mutation_id);
create index physical_writes_entry on action.physical_writes (organisation_id, allowlist_entry_id, written_at desc);
select platform.enable_tenant_rls('action.physical_writes');
select platform.make_append_only('action.physical_writes');
grant select, insert on action.physical_writes to silo_app;
grant select on action.physical_writes to silo_report;

grant select, insert on action.actuation_allowlist_requests to silo_app;
grant update (status, decided_by, decided_at, entry_id) on action.actuation_allowlist_requests to silo_app;
grant select on action.actuation_allowlist_requests to silo_report;

-- ===========================================================================
-- Outbound Action events. The Action ledger (action.action_ledger) is not here:
