  status            text not null default 'active' check (status in ('active', 'paused', 'dead_lettered')),
  status_changed_at timestamptz not null default now(),
  created_by        uuid not null,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  version           integer not null default 1,
  unique (organisation_id, id),
  constraint action_event_subscriptions_endpoint_key unique (organisation_id, endpoint_url, secret_ref),
  constraint action_event_subscriptions_created_by_fkey
    foreign key (organisation_id, created_by) references iam.memberships (organisation_id, id),
  constraint action_event_subscriptions_secret_fkey
    foreign key (organisation_id, secret_ref) references connect.connection_credentials (organisation_id, id)
);
comment on table action.action_event_subscriptions is
  'Customer endpoints that receive one signed outbound event per executed Action (48.3).';
comment on column action.action_event_subscriptions.secret_ref is
  'Reference into the credential service (HMAC-SHA256 secret); the secret is never stored here.';
comment on column action.action_event_subscriptions.filter is
