-- One event's delivery to one subscription (48.3), written by notify when it takes the
-- event from bus-durable (once per subscription and event: the bus redelivers), and
-- attempted until delivered or dead-lettered. The payload is the event itself: identifiers,
-- names, outcomes and times, never record values.
create table action.action_event_deliveries (
  id               uuid primary key,
  organisation_id  uuid not null references iam.organisations (id),
  subscription_id  uuid not null,
  event_id         uuid not null,
  mutation_id      uuid not null,
  receipt_id       uuid not null,
  payload          jsonb not null check (jsonb_typeof(payload) = 'object'),
  status           text not null default 'pending' check (status in ('pending', 'delivered', 'dead_lettered')),
  attempts         integer not null default 0 check (attempts >= 0),
  next_attempt_at  timestamptz not null default now(),
  last_status      integer check (last_status between 100 and 599),
  last_error       text check (length(last_error) <= 200),
  delivered_at     timestamptz,
  dead_lettered_at timestamptz,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  unique (organisation_id, id),
  constraint action_event_deliveries_once unique (organisation_id, subscription_id, event_id),
  constraint action_event_deliveries_subscription_fkey
    foreign key (organisation_id, subscription_id) references action.action_event_subscriptions (organisation_id, id),
  constraint action_event_deliveries_mutation_fkey
    foreign key (organisation_id, mutation_id) references action.mutations (organisation_id, id),
  constraint action_event_deliveries_receipt_fkey
    foreign key (organisation_id, receipt_id) references action.receipts (organisation_id, id),
  check ((status = 'delivered') = (delivered_at is not null)),
  check ((status = 'dead_lettered') = (dead_lettered_at is not null))
);
comment on table action.action_event_deliveries is
  'One outbound Action event for one subscription, attempted with backoff until delivered or dead-lettered (48.3).';
comment on column action.action_event_deliveries.event_id is 'The bus event id: the delivery''s idempotency key at the subscriber.';
comment on column action.action_event_deliveries.last_error is 'A code, never the remote''s text.';
create index action_event_deliveries_due on action.action_event_deliveries (next_attempt_at) where status = 'pending';
create index action_event_deliveries_mutation on action.action_event_deliveries (organisation_id, mutation_id);
create index action_event_deliveries_receipt on action.action_event_deliveries (organisation_id, receipt_id);
select platform.add_updated_at_trigger('action.action_event_deliveries');
select platform.enable_tenant_rls('action.action_event_deliveries');
create trigger action_event_deliveries_frozen before update on action.action_event_deliveries
  for each row execute function platform.freeze_columns('id', 'organisation_id', 'subscription_id', 'event_id', 'mutation_id',
    'receipt_id', 'payload', 'created_at');

grant select, insert on action.action_event_deliveries to silo_app;
grant update (status, attempts, next_attempt_at, last_status, last_error, delivered_at, dead_lettered_at, updated_at)
  on action.action_event_deliveries to silo_app;
grant select on action.action_event_deliveries to silo_report;

-- Outbound webhook side effects (spec 20.4, 42.6; D64): one delivery per Action and target,
-- queued by actions when the Action executed, posted by notify with backoff until delivered or
-- failed. The payload is references only; receipt_id names the receipt that recorded it.
create table action.webhook_deliveries (
  id               uuid primary key,
  organisation_id  uuid not null references iam.organisations (id),
  endpoint_id      uuid not null,
  mutation_id      uuid not null,
  receipt_id       uuid not null,
  execution_key    text not null check (length(execution_key) between 1 and 200),
  -- Sealed (record values, bound to the row): a JSONata-shaped payload may carry the Action's values (20.4).
  -- Cleared when the delivery ends, or its receipt is purged: values do not outlive their use (65.3).
  payload          bytea,
  payload_cleared_at timestamptz,
  status           text not null default 'pending' check (status in ('pending', 'delivered', 'failed')),
  attempts         integer not null default 0 check (attempts >= 0),
  next_attempt_at  timestamptz not null default now(),
  last_status      integer check (last_status between 100 and 599),
  last_error       text check (length(last_error) <= 200),
  delivered_at     timestamptz,
  failed_at        timestamptz,
  -- The effect, where the target declares a status endpoint (20.4): read after delivery until it
  -- says applied or failed, or the window ends unconfirmed. Null where only delivery is known.
  effect               text check (effect in ('pending', 'applied', 'failed', 'unconfirmed')),
  effect_attempts      integer not null default 0 check (effect_attempts >= 0),
  next_effect_check_at timestamptz,
  effect_checked_at    timestamptz,
  -- A physical target's (47.4): the allow-list entry it is sent under, checked again before each attempt.
  allowlist_entry_id   uuid,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  unique (organisation_id, id),
  constraint webhook_deliveries_once unique (organisation_id, endpoint_id, mutation_id),
  constraint webhook_deliveries_entry_fkey
    foreign key (organisation_id, allowlist_entry_id) references action.actuation_allowlists (organisation_id, id),
  constraint webhook_deliveries_endpoint_fkey
    foreign key (organisation_id, endpoint_id) references connect.webhook_endpoints (organisation_id, id),
  constraint webhook_deliveries_mutation_fkey
    foreign key (organisation_id, mutation_id) references action.mutations (organisation_id, id),
  check ((status = 'delivered') = (delivered_at is not null)),
  check ((status = 'failed') = (failed_at is not null)),
  check ((payload is null) = (payload_cleared_at is not null)),
  check (payload_cleared_at is null or status <> 'pending'),
  check (effect is null or status = 'delivered'),
  check ((effect = 'pending') = (next_effect_check_at is not null))
);
comment on table action.webhook_deliveries is
  'One outbound webhook side effect of one Action, attempted with backoff until delivered or failed (20.4, 42.6).';
comment on column action.webhook_deliveries.execution_key is 'The Action execution identifier sent as the idempotency key.';
comment on column action.webhook_deliveries.receipt_id is
  'The receipt that records the delivery as queued. No foreign key: the receipt is written after the side effects are decided.';
comment on column action.webhook_deliveries.last_error is 'A code, never the remote''s text.';
comment on column action.webhook_deliveries.allowlist_entry_id is
  'A physical target''s actuation allow-list entry (47.4): a delivery whose entry is removed before it is sent is refused, never sent.';
create index webhook_deliveries_due on action.webhook_deliveries (next_attempt_at) where status = 'pending';
create index webhook_deliveries_effect_due on action.webhook_deliveries (next_effect_check_at) where effect = 'pending';
create index webhook_deliveries_mutation on action.webhook_deliveries (organisation_id, mutation_id);
create index webhook_deliveries_endpoint on action.webhook_deliveries (organisation_id, endpoint_id);
create index webhook_deliveries_entry on action.webhook_deliveries (organisation_id, allowlist_entry_id) where allowlist_entry_id is not null;
select platform.add_updated_at_trigger('action.webhook_deliveries');
select platform.enable_tenant_rls('action.webhook_deliveries');
create trigger webhook_deliveries_frozen before update on action.webhook_deliveries
  for each row execute function platform.freeze_columns('id', 'organisation_id', 'endpoint_id', 'mutation_id', 'receipt_id',
    'execution_key', 'allowlist_entry_id', 'created_at');
-- The payload never changes, except to go, once.
create function action.webhook_deliveries_payload_guard() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
begin
  if new.payload is distinct from old.payload and (new.payload is not null or old.payload is null) then
    raise exception 'a webhook payload is cleared once and never changed' using errcode = 'insufficient_privilege';
  end if;
  return new;
end
$$;
create trigger webhook_deliveries_payload_guard before update on action.webhook_deliveries
  for each row execute function action.webhook_deliveries_payload_guard();

grant select, insert on action.webhook_deliveries to silo_app;
grant update (status, attempts, next_attempt_at, last_status, last_error, delivered_at, failed_at, updated_at,
  payload, payload_cleared_at, effect, effect_attempts, next_effect_check_at, effect_checked_at)
  on action.webhook_deliveries to silo_app;
grant select on action.webhook_deliveries to silo_report;

-- Deliveries due across organisations, for notify's delivery sweep, which then acts per
-- organisation under row-level security. A paused subscription's deliveries wait.
create function action.action_event_deliveries_due(p_now timestamptz, p_limit integer)
  returns table (organisation_id uuid, id uuid)
language sql stable security definer
set search_path = pg_catalog
as $$
  select d.organisation_id, d.id from action.action_event_deliveries d
  join action.action_event_subscriptions s on s.organisation_id = d.organisation_id and s.id = d.subscription_id
  where d.status = 'pending' and d.next_attempt_at <= p_now and s.status = 'active'
  order by d.next_attempt_at, d.id
  limit least(greatest(p_limit, 1), 1000)
$$;
revoke all on function action.action_event_deliveries_due(timestamptz, integer) from public;
grant execute on function action.action_event_deliveries_due(timestamptz, integer) to silo_app;

-- Receipt purge (46.1, 48.2, 65.3, 70; D152): one receipt, or every receipt of a commit on an
-- object (an erasure), asked by a holder of silo.purge and approved as every wipe is (70.3).
create table action.receipt_purges (
  id                uuid primary key,
  organisation_id   uuid not null references iam.organisations (id),
  scope             text not null check (scope in ('receipt', 'object')),
  receipt_id        uuid,
  object_id         uuid,
  requested_by      uuid not null,
  requested_at      timestamptz not null default now(),
  status            text not null default 'awaiting_approval'
                      check (status in ('awaiting_approval', 'approved', 'rejected', 'running', 'completed', 'failed')),
  approval_chain_id uuid,
  decided_at        timestamptz,
  receipts_purged   integer check (receipts_purged >= 0),
  ledger_rows       integer check (ledger_rows >= 0),
  completed_at      timestamptz,
  failure_stage     text check (length(failure_stage) <= 64),
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  unique (organisation_id, id),
  constraint receipt_purges_receipt_fkey
    foreign key (organisation_id, receipt_id) references action.receipts (organisation_id, id),
  constraint receipt_purges_requested_by_fkey
    foreign key (organisation_id, requested_by) references iam.memberships (organisation_id, id),
  constraint receipt_purges_approval_chain_fkey
    foreign key (organisation_id, approval_chain_id) references action.approval_chains (organisation_id, id),
  check ((scope = 'receipt') = (receipt_id is not null)),
  check ((scope = 'object') = (object_id is not null)),
  check ((status = 'completed') = (completed_at is not null))
);
comment on table action.receipt_purges is
  'A request to purge receipts'' values (46.1, 70): references and counts, never a value.';
comment on column action.receipt_purges.object_id is 'A Silo object: every receipt of a commit on it is purged.';
create index receipt_purges_open on action.receipt_purges (organisation_id, status) where status in ('awaiting_approval', 'approved', 'running');
create index receipt_purges_receipt on action.receipt_purges (organisation_id, receipt_id) where receipt_id is not null;
create index receipt_purges_requested_by on action.receipt_purges (organisation_id, requested_by);
create index receipt_purges_approval_chain on action.receipt_purges (organisation_id, approval_chain_id) where approval_chain_id is not null;
select platform.add_updated_at_trigger('action.receipt_purges');
select platform.enable_tenant_rls('action.receipt_purges');
grant select, insert, update on action.receipt_purges to silo_app;
grant select on action.receipt_purges to silo_report;

-- ---------------------------------------------------------------------------
-- action.ledger_copies
-- An Action ledger copy owed (48.2): the rows a receipt's copy to the Silo holding the ledger
-- carries, kept when the copy failed after its brief retries and sent again later until written.
-- The rows may carry record values (the ledger's values option), so they are sealed to this row
-- as the receipt's values are; purged with the receipt, and dropped once written or once no Silo
-- holds the ledger.
create table action.ledger_copies (
  id              uuid primary key,
  organisation_id uuid not null references iam.organisations (id),
  store           text not null check (store in ('warehouse', 'capture')),
  rows_sealed     bytea not null,
  row_count       integer not null check (row_count > 0),
  attempts        integer not null default 0 check (attempts >= 0),
  next_attempt_at timestamptz not null,
  last_failure    text check (length(last_failure) <= 120),
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  unique (organisation_id, id),
  constraint ledger_copies_receipt_fkey foreign key (organisation_id, id) references action.receipts (organisation_id, id)
);
comment on table action.ledger_copies is
  'Action ledger copies owed (48.2): a receipt''s ledger rows, sealed, sent again until written; purged with the receipt.';
comment on column action.ledger_copies.id is 'The receipt the copy is of: one copy per receipt.';
comment on column action.ledger_copies.last_failure is 'The last failure''s error code, never its text.';
create index ledger_copies_due on action.ledger_copies (next_attempt_at);
select platform.add_updated_at_trigger('action.ledger_copies');
select platform.enable_tenant_rls('action.ledger_copies');
grant select, insert, update, delete on action.ledger_copies to silo_app;

-- Ledger copies due across the cell, for the actions service's retries. Identifiers only.
create function action.ledger_copies_due(p_now timestamptz, p_limit integer)
  returns table (organisation_id uuid, id uuid)
language sql stable security definer
set search_path = pg_catalog
as $$
  select c.organisation_id, c.id from action.ledger_copies c
  where c.next_attempt_at <= p_now
  order by c.next_attempt_at, c.id
  limit least(greatest(p_limit, 1), 1000)
$$;
revoke all on function action.ledger_copies_due(timestamptz, integer) from public;
grant execute on function action.ledger_copies_due(timestamptz, integer) to silo_app;

-- Open receipt purges across the cell, for the approval watcher. Identifiers only.
create function action.receipt_purges_open(p_limit integer)
  returns table (organisation_id uuid, id uuid)
language sql stable security definer
set search_path = pg_catalog
as $$
  select p.organisation_id, p.id from action.receipt_purges p
  where p.status in ('awaiting_approval', 'approved')
  order by p.requested_at, p.id
  limit least(greatest(p_limit, 1), 1000)
$$;
revoke all on function action.receipt_purges_open(integer) from public;
grant execute on function action.receipt_purges_open(integer) to silo_app;

-- Organisations with receipts past their retention, for the sweep. Identifiers only.
create function action.organisations_with_receipts_due(p_now timestamptz)
  returns table (organisation_id uuid)
language sql stable security definer
set search_path = pg_catalog
as $$
  select distinct r.organisation_id from action.receipts r where r.purged_at is null and r.retention_until <= p_now
$$;
revoke all on function action.organisations_with_receipts_due(timestamptz) from public;
grant execute on function action.organisations_with_receipts_due(timestamptz) to silo_app;

-- Purge one mutation's values in the caller's organisation (app.org_id): the tables' purge
-- guards admit only silo_migrate, which owns this function. Hashes, references and counts stay.
create function action.purge_mutation_values(p_mutation_id uuid)
  returns table (receipt_ids uuid[], prior_states integer, verifications integer, conflicts integer, deliveries_failed integer)
language plpgsql security definer
set search_path = pg_catalog
as $$
declare
  v_org uuid := current_setting('app.org_id')::uuid;
  v_now timestamptz := now();
begin
  update action.mutations set intent = null, diff = null, manifest_values = null, purged_at = v_now
   where organisation_id = v_org and id = p_mutation_id and purged_at is null;
  with purged as (
    update action.receipts set document = null, purged_at = v_now
     where organisation_id = v_org and mutation_id = p_mutation_id and purged_at is null returning id)
  select coalesce(array_agg(id order by id), '{}') into receipt_ids from purged;
  update action.prior_states set value = null, purged_at = v_now
   where organisation_id = v_org and mutation_id = p_mutation_id and purged_at is null;
  get diagnostics prior_states = row_count;
  update action.mutation_verifications v set intended = null, observed = null, purged_at = v_now
    from action.mutation_executions e
   where e.organisation_id = v_org and e.mutation_id = p_mutation_id
     and v.organisation_id = v_org and v.execution_id = e.id and v.purged_at is null;
  get diagnostics verifications = row_count;
  update action.revert_conflicts c set post_write_value = null, current_value = null, purged_at = v_now
    from action.reverts r
   where r.organisation_id = v_org and r.new_mutation_id = p_mutation_id
     and c.organisation_id = v_org and c.revert_id = r.id and c.purged_at is null;
  get diagnostics conflicts = row_count;
  update action.webhook_deliveries set status = 'failed', failed_at = v_now, last_error = 'receipt_purged', payload = null, payload_cleared_at = v_now
   where organisation_id = v_org and mutation_id = p_mutation_id and status = 'pending';
  get diagnostics deliveries_failed = row_count;
  return next;
end
$$;
revoke all on function action.purge_mutation_values(uuid) from public;
grant execute on function action.purge_mutation_values(uuid) to silo_app;

create function action.webhook_deliveries_due(p_now timestamptz, p_limit integer)
  returns table (organisation_id uuid, id uuid)
language sql stable security definer
set search_path = pg_catalog
as $$
  select d.organisation_id, d.id from action.webhook_deliveries d
  where d.status = 'pending' and d.next_attempt_at <= p_now
  order by d.next_attempt_at, d.id
  limit least(greatest(p_limit, 1), 1000)
$$;
revoke all on function action.webhook_deliveries_due(timestamptz, integer) from public;
grant execute on function action.webhook_deliveries_due(timestamptz, integer) to silo_app;

-- Delivered webhooks whose effect is due to be read again, across the cell. Identifiers only.
create function action.webhook_effects_due(p_now timestamptz, p_limit integer)
  returns table (organisation_id uuid, id uuid)
language sql stable security definer
set search_path = pg_catalog
as $$
  select d.organisation_id, d.id from action.webhook_deliveries d
  where d.effect = 'pending' and d.next_effect_check_at <= p_now
  order by d.next_effect_check_at, d.id
  limit least(greatest(p_limit, 1), 1000)
$$;
revoke all on function action.webhook_effects_due(timestamptz, integer) from public;
grant execute on function action.webhook_effects_due(timestamptz, integer) to silo_app;

-- ===========================================================================
-- Circular keys inside this schema, added once both tables exist. Deferred to
-- commit: a version references its type, and a receipt references its mutation.
-- ===========================================================================

-- Composite with the type id, so a type's current version is always one of its own.
alter table action.action_types
  add constraint action_types_current_version_fkey
    foreign key (organisation_id, id, current_version_id)
    references action.action_type_versions (organisation_id, action_type_id, id)
    deferrable initially deferred;

alter table action.mutations
  add constraint mutations_dry_run_receipt_fkey
    foreign key (organisation_id, dry_run_receipt_id) references action.receipts (organisation_id, id)
    deferrable initially deferred;

-- ===========================================================================
-- Partitions: the plan only. Partitions are created by platform.maintain_partitions().
-- ===========================================================================

insert into platform.partition_plan (parent, granularity, create_ahead) values
  ('action.action_commits', 'month', 3);

-- ============================================================================
-- Domain: siloes, billing
-- ============================================================================

-- Siloes and billing. Design: docs/siloDatabaseDesign.doc.md, section 08 (schemas
-- `siloes` and `billing`), with review decisions D8 (purge requests), R12, R14 and
-- R16. Keys to tables of other domains are added in siloes_billing_fks.sql.
--
-- Every service named by the design (siloes-capture, siloes-import, metering,
-- billing, auth, admin-portal) uses silo_app; "writes by" is a service rule. Record
-- values (encrypted envelopes) are never granted to silo_report.

-- ===========================================================================
-- siloes.siloes
-- ===========================================================================

create table siloes.siloes (
  id                           uuid primary key,
  organisation_id              uuid not null references iam.organisations (id),
  kind                         text not null check (kind in ('capture', 'import', 'object_index', 'warehouse')),
  name                         text not null check (length(btrim(name)) > 0),
  purpose                      text not null check (length(btrim(purpose)) > 0),
  retention_days               integer not null check (retention_days > 0),
  location                     text not null check (length(btrim(location)) > 0),
  status                       text not null default 'active' check (status in ('provisioning', 'active', 'purging', 'disabled')),
  store_ref                    text,
  source_connection_id         uuid,
  carveout_acknowledged_by     uuid,
  carveout_acknowledged_at     timestamptz,
  action_ledger_enabled_at     timestamptz,
  action_ledger_include_values boolean,
  service_principal_id         uuid,
  created_by                   uuid not null,
  created_at                   timestamptz not null default now(),
  updated_at                   timestamptz not null default now(),
  disabled_at                  timestamptz,
  version                      bigint not null default 1,
  unique (organisation_id, id),
  unique (organisation_id, id, kind),
  constraint siloes_created_by_fkey
    foreign key (organisation_id, created_by) references iam.memberships (organisation_id, id),
  constraint siloes_carveout_acknowledged_by_fkey
    foreign key (organisation_id, carveout_acknowledged_by) references iam.memberships (organisation_id, id),
  constraint siloes_service_principal_fkey
    foreign key (organisation_id, service_principal_id) references iam.service_principals (organisation_id, id),
  constraint siloes_source_connection_by_kind
    check (kind <> 'capture' or source_connection_id is null),
  constraint siloes_source_connection_when_active
    check (kind = 'capture' or status <> 'active' or source_connection_id is not null),
  constraint siloes_carveout_pair
    check ((carveout_acknowledged_by is null) = (carveout_acknowledged_at is null)),
  constraint siloes_carveout_import_only
    check (kind = 'import' or carveout_acknowledged_at is null),
  constraint siloes_action_ledger_pair
    check ((action_ledger_enabled_at is null) = (action_ledger_include_values is null)),
  constraint siloes_action_ledger_kinds
    check (action_ledger_enabled_at is null or kind in ('capture', 'import', 'warehouse')),
  check (status <> 'disabled' or disabled_at is not null)
);
comment on table siloes.siloes is
  'One opt-in Silo of one of four kinds, created for a stated purpose with a retention window.';
comment on column siloes.siloes.location is
  'Residency location of the backing store, set at creation from the cell''s permitted locations.';
comment on column siloes.siloes.store_ref is
  'Backing store name: the BigQuery dataset id, or pg-capture for Capture. Named in purge receipts.';
comment on column siloes.siloes.source_connection_id is
  'The connect.connections row through which an Import Silo, Object Index or Warehouse is queried.';
comment on column siloes.siloes.service_principal_id is
  'The Silo''s automation principal, for a Silo that runs scheduled source queries (Object Index refresh, spec 69.4): '
  'owned by its creator, bounded by them at run time, holding read grants on the connections it reads.';
comment on column siloes.siloes.carveout_acknowledged_at is
  'Acceptance of the document-extraction prompt carve-out. Without it no definition may require a model.';
create unique index siloes_live_name on siloes.siloes (organisation_id, name) where disabled_at is null;
create unique index siloes_one_live_warehouse on siloes.siloes (organisation_id)
  where kind = 'warehouse' and disabled_at is null;
create index siloes_list on siloes.siloes (organisation_id, created_at desc) where disabled_at is null;
-- One Silo holds an organisation's Action ledger: its Warehouse, or where the cell has none, a Capture Silo (48.2; D205).
create unique index siloes_one_ledger on siloes.siloes (organisation_id) where action_ledger_enabled_at is not null;
create index siloes_active_by_kind on siloes.siloes (organisation_id, kind) where status = 'active';
create index siloes_source_connection on siloes.siloes (organisation_id, source_connection_id)
  where source_connection_id is not null;
select platform.add_updated_at_trigger('siloes.siloes');
select platform.enable_tenant_rls('siloes.siloes');
create trigger siloes_frozen before update on siloes.siloes
  for each row execute function platform.freeze_columns('id', 'organisation_id', 'kind', 'location',
                                                         'created_by', 'created_at');

grant select, insert, update on siloes.siloes to silo_app;
grant select on siloes.siloes to silo_report;

-- ===========================================================================
-- siloes.silo_object_types
-- ===========================================================================

create table siloes.silo_object_types (
  id                   uuid primary key,
  organisation_id      uuid not null references iam.organisations (id),
  silo_id              uuid not null,
  object_type_id       uuid not null,
  nominated_properties text[] not null
                         check (cardinality(nominated_properties) >= 1
                                and array_ndims(nominated_properties) = 1
                                and array_position(nominated_properties, null) is null),
  added_by             uuid not null,
  added_at             timestamptz not null default now(),
  removed_at           timestamptz,
  updated_at           timestamptz not null default now(),
  version              bigint not null default 1,
  unique (organisation_id, id),
  constraint silo_object_types_silo_fkey
    foreign key (organisation_id, silo_id) references siloes.siloes (organisation_id, id),
  constraint silo_object_types_added_by_fkey
    foreign key (organisation_id, added_by) references iam.memberships (organisation_id, id)
);
comment on table siloes.silo_object_types is
  'The object types a Silo holds and, per type, the properties nominated.';
comment on column siloes.silo_object_types.nominated_properties is
  'Property API names held, as named at the time. Nothing outside this list is stored.';
create unique index silo_object_types_live on siloes.silo_object_types (organisation_id, silo_id, object_type_id)
  where removed_at is null;
create index silo_object_types_by_object_type on siloes.silo_object_types (organisation_id, object_type_id, silo_id)
  where removed_at is null;
select platform.add_updated_at_trigger('siloes.silo_object_types');
select platform.enable_tenant_rls('siloes.silo_object_types');
create trigger silo_object_types_frozen before update on siloes.silo_object_types
  for each row execute function platform.freeze_columns('id', 'organisation_id', 'silo_id', 'object_type_id',
                                                         'added_by', 'added_at');

