-- ===========================================================================
-- siloes.silo_extractions
-- ===========================================================================

create table siloes.silo_extractions (
  id              uuid primary key,
  organisation_id uuid not null references iam.organisations (id),
  file_id         uuid not null,
  object          text not null,
  row_ref         text not null,
  field           text not null,
  value           bytea not null,
  method          text not null check (method in ('certain', 'near', 'inferred')),
  confidence      numeric(4,3) check (confidence between 0 and 1),
  raw_text_ref    text not null,
  confirmed_by    uuid,
  confirmed_at    timestamptz,
  created_at      timestamptz not null default now(),
  unique (organisation_id, id),
  constraint silo_extractions_location_key unique (organisation_id, file_id, object, row_ref, field),
  constraint silo_extractions_file_fkey
    foreign key (organisation_id, file_id) references siloes.silo_files (organisation_id, id),
  constraint silo_extractions_confirmed_by_fkey
    foreign key (organisation_id, confirmed_by) references iam.memberships (organisation_id, id),
  check ((confirmed_by is null) = (confirmed_at is null)),
  check (confirmed_at is null or method = 'certain')
);
comment on table siloes.silo_extractions is
  'A value extracted by a method less certain than a column read, with its source location, for flag display.';
comment on column siloes.silo_extractions.value is
  'Encrypted envelope. AAD (organisation_id, file_id, object, row_ref, field).';
comment on column siloes.silo_extractions.row_ref is 'Key of the row in the BigQuery row store.';
comment on column siloes.silo_extractions.raw_text_ref is 'Location of the source text (page, cell or offset). Not the text.';
create index silo_extractions_review_queue on siloes.silo_extractions (organisation_id, object, created_at desc)
  where confirmed_at is null;
select platform.enable_tenant_rls('siloes.silo_extractions');

-- The only update is the confirmation: method, confirmed_by and confirmed_at change,
-- everything else (confidence included) stays, and only while unconfirmed.
create function siloes.silo_extractions_confirm_once() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
begin
  if old.confirmed_at is not null then
    raise exception 'siloes.silo_extractions: value % is already confirmed', old.id
      using errcode = 'insufficient_privilege';
  end if;
  if new.confirmed_at is null
     or (to_jsonb(new) - array['method', 'confirmed_by', 'confirmed_at'])
        <> (to_jsonb(old) - array['method', 'confirmed_by', 'confirmed_at']) then
    raise exception 'siloes.silo_extractions: the only update allowed is the confirmation'
      using errcode = 'insufficient_privilege';
  end if;
  return new;
end
$$;
create trigger silo_extractions_confirm_once before update on siloes.silo_extractions
  for each row execute function siloes.silo_extractions_confirm_once();

grant select, insert on siloes.silo_extractions to silo_app;
grant update (method, confirmed_by, confirmed_at) on siloes.silo_extractions to silo_app;
grant select (id, organisation_id, file_id, object, row_ref, field, method, confidence, raw_text_ref,
              confirmed_by, confirmed_at, created_at)
  on siloes.silo_extractions to silo_report;

