create table siloes.extraction_confirmations (
  id              uuid primary key,
  organisation_id uuid not null references iam.organisations (id),
  extraction_id   uuid not null,
  membership_id   uuid not null,
  previous_method text not null check (previous_method in ('near', 'inferred')),
  confirmed_at    timestamptz not null default now(),
  unique (organisation_id, id),
  constraint extraction_confirmations_once unique (organisation_id, extraction_id),
  constraint extraction_confirmations_extraction_fkey
    foreign key (organisation_id, extraction_id) references siloes.silo_extractions (organisation_id, id),
  constraint extraction_confirmations_membership_fkey
    foreign key (organisation_id, membership_id) references iam.memberships (organisation_id, id)
);
comment on table siloes.extraction_confirmations is
  'Append-only record of each confirmation of an extracted value, with the method before it.';
create index extraction_confirmations_by_member on siloes.extraction_confirmations
  (organisation_id, membership_id, confirmed_at desc);
select platform.enable_tenant_rls('siloes.extraction_confirmations');
select platform.make_append_only('siloes.extraction_confirmations', purge_by_migrate => true);

grant select, insert on siloes.extraction_confirmations to silo_app;
grant select on siloes.extraction_confirmations to silo_report;

-- ===========================================================================
-- siloes.index_definitions
-- ===========================================================================

create table siloes.index_definitions (
  id                   uuid primary key,
  organisation_id      uuid not null references iam.organisations (id),
  silo_id              uuid not null,
  silo_kind            text not null default 'object_index' check (silo_kind = 'object_index'),
  object_type_id       uuid not null,
  nominated_properties text[] not null
                         check (cardinality(nominated_properties) >= 1
                                and array_ndims(nominated_properties) = 1
                                and array_position(nominated_properties, null) is null),
  refresh_schedule     text not null check (length(btrim(refresh_schedule)) > 0),
  uses_change_stream   boolean not null,
  added_by             uuid not null,
  added_at             timestamptz not null default now(),
  removed_at           timestamptz,
  next_refresh_at      timestamptz,
  last_refreshed_at    timestamptz,
  updated_at           timestamptz not null default now(),
  version              bigint not null default 1,
  unique (organisation_id, id),
  constraint index_definitions_silo_fkey
    foreign key (organisation_id, silo_id, silo_kind) references siloes.siloes (organisation_id, id, kind),
  constraint index_definitions_added_by_fkey
    foreign key (organisation_id, added_by) references iam.memberships (organisation_id, id),
  check (removed_at is null or next_refresh_at is null)
);
comment on table siloes.index_definitions is
  'An object type nominated into an Object Index, with its properties and refresh schedule.';
comment on column siloes.index_definitions.silo_kind is 'Pins the Silo kind through the composite key.';
comment on column siloes.index_definitions.refresh_schedule is 'Cron expression in the organisation''s time zone.';
create unique index index_definitions_live on siloes.index_definitions (organisation_id, silo_id, object_type_id)
  where removed_at is null;
create index index_definitions_silo on siloes.index_definitions (organisation_id, silo_id, silo_kind);
create index index_definitions_refresh_due on siloes.index_definitions (organisation_id, next_refresh_at)
  where removed_at is null;
create index index_definitions_by_object_type on siloes.index_definitions (organisation_id, object_type_id)
  where removed_at is null;
select platform.add_updated_at_trigger('siloes.index_definitions');
select platform.enable_tenant_rls('siloes.index_definitions');
create trigger index_definitions_frozen before update on siloes.index_definitions
  for each row execute function platform.freeze_columns('id', 'organisation_id', 'silo_id', 'silo_kind',
                                                         'object_type_id', 'added_by', 'added_at');

grant select, insert, update on siloes.index_definitions to silo_app;
grant select on siloes.index_definitions to silo_report;

-- ===========================================================================
-- siloes.index_refreshes
-- ===========================================================================

create table siloes.index_refreshes (
  id                  uuid primary key,
  organisation_id     uuid not null references iam.organisations (id),
  index_definition_id uuid not null,
  trigger             text not null check (trigger in ('schedule', 'change_stream', 'rebuild')),
  objects_written     bigint not null default 0 check (objects_written >= 0),
  objects_removed     bigint not null default 0 check (objects_removed >= 0),
  started_at          timestamptz not null default now(),
  completed_at        timestamptz,
  status              text not null default 'running' check (status in ('running', 'completed', 'failed', 'refused')),
  error_stage         text,
  unique (organisation_id, id),
  constraint index_refreshes_definition_fkey
    foreign key (organisation_id, index_definition_id) references siloes.index_definitions (organisation_id, id),
  check (status = 'running' or completed_at is not null),
  check (status not in ('failed', 'refused') or error_stage is not null)
);
comment on table siloes.index_refreshes is 'One refresh run of an index definition, with counts and outcome.';
comment on column siloes.index_refreshes.error_stage is 'The failing stage, never a value.';
create unique index index_refreshes_one_running on siloes.index_refreshes (organisation_id, index_definition_id)
  where status = 'running';
create index index_refreshes_history on siloes.index_refreshes (organisation_id, index_definition_id, started_at desc);
select platform.enable_tenant_rls('siloes.index_refreshes');
create trigger index_refreshes_frozen before update on siloes.index_refreshes
  for each row execute function platform.freeze_columns('id', 'organisation_id', 'index_definition_id',
                                                         'trigger', 'started_at');

grant select, insert, update on siloes.index_refreshes to silo_app;
grant select on siloes.index_refreshes to silo_report;

-- ===========================================================================
-- siloes.warehouse_projects
-- ===========================================================================

create table siloes.warehouse_projects (
  id                uuid primary key,
  organisation_id   uuid not null unique references iam.organisations (id),
  silo_id           uuid not null,
  silo_kind         text not null default 'warehouse' check (silo_kind = 'warehouse'),
  gcp_project_id    text not null unique,
  dataset           text not null,
  location          text not null,
  kms_key_ref       text not null,
  provisioning_step text not null default 'none'
                      check (provisioning_step in ('none', 'project_created', 'dataset_created', 'key_bound',
                                                   'access_granted', 'tables_created', 'backfill_started')),
  service_principal_id uuid,
  status            text not null default 'provisioning'
                      check (status in ('provisioning', 'backfilling', 'active', 'failed', 'handed_over', 'purged')),
  failed_step       text,
  handed_over_at    timestamptz,
  purged_at         timestamptz,
  created_by        uuid not null,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  version           bigint not null default 1,
  unique (organisation_id, id),
  constraint warehouse_projects_silo_fkey
    foreign key (organisation_id, silo_id, silo_kind) references siloes.siloes (organisation_id, id, kind),
  constraint warehouse_projects_created_by_fkey
    foreign key (organisation_id, created_by) references iam.memberships (organisation_id, id),
  constraint warehouse_projects_service_principal_fkey
    foreign key (organisation_id, service_principal_id) references iam.service_principals (organisation_id, id),
  check (status <> 'failed' or failed_step is not null),
  check (status <> 'handed_over' or handed_over_at is not null),
  check (status <> 'purged' or purged_at is not null)
);
comment on table siloes.warehouse_projects is
  'The dedicated cloud project and dataset of an organisation''s Warehouse, with provisioning state.';
comment on column siloes.warehouse_projects.kms_key_ref is 'KMS key resource name. A reference, never key material.';
comment on column siloes.warehouse_projects.provisioning_step is 'Last completed provisioning step.';
comment on column siloes.warehouse_projects.failed_step is 'The step that failed, never a value.';
comment on column siloes.warehouse_projects.service_principal_id is
  'The Warehouse''s automation principal: it reads the nominated types through the federated engine, bounded by its '
  'owner (the creator) at run time, and holds read grants on their connections.';
create index warehouse_projects_silo on siloes.warehouse_projects (organisation_id, silo_id, silo_kind);
create index warehouse_projects_retry on siloes.warehouse_projects (organisation_id, status)
  where status in ('provisioning', 'backfilling', 'failed');
select platform.add_updated_at_trigger('siloes.warehouse_projects');
select platform.enable_tenant_rls('siloes.warehouse_projects');
create trigger warehouse_projects_frozen before update on siloes.warehouse_projects
  for each row execute function platform.freeze_columns('id', 'organisation_id', 'silo_id', 'silo_kind',
                                                         'location', 'created_by', 'created_at');

-- The Warehouse location equals its Silo's; both are immutable after insert.
create function siloes.warehouse_projects_location_matches() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
begin
  if not exists (select 1 from siloes.siloes s
                 where s.organisation_id = new.organisation_id and s.id = new.silo_id
                   and s.location = new.location) then
    raise exception 'warehouse location % must equal the location of Silo %', new.location, new.silo_id
      using errcode = 'check_violation';
  end if;
  return new;
end
$$;
create trigger warehouse_projects_location_matches before insert on siloes.warehouse_projects
  for each row execute function siloes.warehouse_projects_location_matches();

grant select, insert, update on siloes.warehouse_projects to silo_app;
grant select on siloes.warehouse_projects to silo_report;

-- The Warehouses that scheduled sync and reconciliation visit, across organisations:
-- identifiers only.
create function siloes.active_warehouses(p_limit integer) returns table (organisation_id uuid, id uuid, service_principal_id uuid)
language sql stable security definer
set search_path = pg_catalog
as $$
  select w.organisation_id, w.id, w.service_principal_id from siloes.warehouse_projects w
  where w.status = 'active' and w.service_principal_id is not null
  order by w.updated_at, w.id limit p_limit
$$;
grant execute on function siloes.active_warehouses(integer) to silo_app;

-- The index definitions due a scheduled refresh, across organisations: identifiers only.
create function siloes.due_index_definitions(p_limit integer) returns table (organisation_id uuid, id uuid)
language sql stable security definer
set search_path = pg_catalog
as $$
  select d.organisation_id, d.id from siloes.index_definitions d
  where d.removed_at is null and d.next_refresh_at <= now()
  order by d.next_refresh_at, d.id limit p_limit
$$;
grant execute on function siloes.due_index_definitions(integer) to silo_app;

-- The Siloes held in Silo's BigQuery (Import, Object Index, Warehouse) that metering
-- measures, across organisations: identifiers only.
create function siloes.bigquery_siloes(p_limit integer) returns table (organisation_id uuid, id uuid, kind text)
language sql stable security definer
set search_path = pg_catalog
as $$
  select s.organisation_id, s.id, s.kind from siloes.siloes s
  where s.kind in ('import', 'object_index', 'warehouse') and s.disabled_at is null and s.store_ref is not null
  order by s.organisation_id, s.id limit p_limit
$$;
grant execute on function siloes.bigquery_siloes(integer) to silo_app;


-- ===========================================================================
-- siloes.warehouse_tables
-- ===========================================================================

create table siloes.warehouse_tables (
  id                   uuid primary key,
  organisation_id      uuid not null references iam.organisations (id),
  warehouse_project_id uuid not null,
  object_type_id       uuid,
  link_type_id         uuid,
  table_name           text not null check (length(btrim(table_name)) > 0),
  kind                 text not null check (kind in ('current', 'history', 'link', 'ledger')),
  ontology_version_id  uuid not null,
  last_synced_at       timestamptz,
  row_count            bigint not null default 0 check (row_count >= 0),
  -- A current table's columns whose property left the nomination or changed type, by name, with
  -- when that was seen: each is dropped once the Silo's window has passed since (69.14, D59).
  retired_columns      jsonb not null default '{}' check (jsonb_typeof(retired_columns) = 'object'),
  dropped_at           timestamptz,
  created_at           timestamptz not null default now(),
  updated_at           timestamptz not null default now(),
  unique (organisation_id, id),
  constraint warehouse_tables_name_key unique (organisation_id, warehouse_project_id, table_name),
  constraint warehouse_tables_project_fkey
    foreign key (organisation_id, warehouse_project_id) references siloes.warehouse_projects (organisation_id, id),
  constraint warehouse_tables_kind_target check (
    case kind
      when 'current' then object_type_id is not null and link_type_id is null
      when 'history' then object_type_id is not null and link_type_id is null
      when 'link'    then link_type_id is not null and object_type_id is null
      when 'ledger'  then object_type_id is null and link_type_id is null
    end)
);
comment on table siloes.warehouse_tables is
  'Each BigQuery table of a Warehouse, the ontology version it reflects and its freshness.';
comment on column siloes.warehouse_tables.ontology_version_id is 'The ontology version the table schema reflects.';
create index warehouse_tables_by_object_type on siloes.warehouse_tables (organisation_id, object_type_id, kind)
  where dropped_at is null;
create index warehouse_tables_link_type on siloes.warehouse_tables (organisation_id, link_type_id)
  where link_type_id is not null;
create index warehouse_tables_ontology_version on siloes.warehouse_tables (organisation_id, ontology_version_id);
select platform.add_updated_at_trigger('siloes.warehouse_tables');
select platform.enable_tenant_rls('siloes.warehouse_tables');
create trigger warehouse_tables_frozen before update on siloes.warehouse_tables
  for each row execute function platform.freeze_columns('id', 'organisation_id', 'warehouse_project_id', 'kind',
                                                         'object_type_id', 'link_type_id', 'created_at');

grant select, insert, update on siloes.warehouse_tables to silo_app;
grant select on siloes.warehouse_tables to silo_report;

