  constraint warehouse_sync_runs_table_fkey
    foreign key (organisation_id, warehouse_table_id) references siloes.warehouse_tables (organisation_id, id),
  check (status <> 'failed' or error is not null)
);
comment on table siloes.warehouse_sync_runs is
  'One backfill, stream roll-up, scheduled sync or reconciliation of one Warehouse table.';
comment on column siloes.warehouse_sync_runs.error is 'The failing stage, never a value.';
