create trigger warehouse_sync_runs_frozen before update on siloes.warehouse_sync_runs
  for each row execute function platform.freeze_columns('id', 'organisation_id', 'warehouse_table_id', 'mode',
                                                         'started_at');

grant select, insert, update on siloes.warehouse_sync_runs to silo_app;
grant select on siloes.warehouse_sync_runs to silo_report;

-- ===========================================================================
-- siloes.warehouse_sql_grants: never deleted; revocation sets revoked_at
-- ===========================================================================

create table siloes.warehouse_sql_grants (
  id                   uuid primary key,
  organisation_id      uuid not null references iam.organisations (id),
  warehouse_project_id uuid not null,
  google_identity      text not null
                         check (position('@' in google_identity) > 1 and google_identity = lower(google_identity)),
  granted_by           uuid not null,
  granted_at           timestamptz not null default now(),
  revoked_by           uuid,
  revoked_at           timestamptz,
  revoked_reason       text check (revoked_reason in ('revoked', 'marked_data', 'handed_over', 'purged')),
  unique (organisation_id, id),
  constraint warehouse_sql_grants_project_fkey
    foreign key (organisation_id, warehouse_project_id) references siloes.warehouse_projects (organisation_id, id),
  constraint warehouse_sql_grants_granted_by_fkey
    foreign key (organisation_id, granted_by) references iam.memberships (organisation_id, id),
  constraint warehouse_sql_grants_revoked_by_fkey
    foreign key (organisation_id, revoked_by) references iam.memberships (organisation_id, id),
  check ((revoked_reason is null) = (revoked_at is null)),
  -- A person's revocation names them; the system's (marked data, hand-over, purge) names none.
  check ((revoked_reason = 'revoked') = (revoked_by is not null))
);
comment on table siloes.warehouse_sql_grants is
  'A super admin''s grant of read-only direct SQL access on the Warehouse to a named Google identity.';
create unique index warehouse_sql_grants_active on siloes.warehouse_sql_grants
  (organisation_id, warehouse_project_id, google_identity) where revoked_at is null;
comment on column siloes.warehouse_sql_grants.revoked_reason is
  'revoked by a super admin; marked_data when a marked property reached the dataset (spec 69.16); handed_over or purged at exit.';
select platform.enable_tenant_rls('siloes.warehouse_sql_grants');
create trigger warehouse_sql_grants_frozen before update on siloes.warehouse_sql_grants
  for each row execute function platform.freeze_columns('id', 'organisation_id', 'warehouse_project_id',
                                                         'google_identity', 'granted_by', 'granted_at');

grant select, insert, update on siloes.warehouse_sql_grants to silo_app;
grant select on siloes.warehouse_sql_grants to silo_report;

-- The Warehouses with live direct SQL grants, for the marking check (spec 69.16): identifiers only.
create function siloes.warehouses_with_sql_grants(p_limit integer) returns table (organisation_id uuid, warehouse_project_id uuid)
language sql stable security definer
set search_path = pg_catalog
as $$
  select distinct g.organisation_id, g.warehouse_project_id from siloes.warehouse_sql_grants g
  where g.revoked_at is null
  order by g.organisation_id, g.warehouse_project_id limit p_limit
$$;
grant execute on function siloes.warehouses_with_sql_grants(integer) to silo_app;

-- ===========================================================================
-- siloes.purge_requests (review D8): what an approval chain approves before the
-- wipe runs
-- ===========================================================================

create table siloes.purge_requests (
  id                uuid primary key,
  organisation_id   uuid not null references iam.organisations (id),
  silo_id           uuid not null,
  scope             text not null check (scope in ('entity', 'file', 'object', 'index', 'concept', 'silo')),
  object_type_id    uuid,
  silo_file_id      uuid,
  object_ref        text,
  requested_by      uuid not null,
  requested_at      timestamptz not null default now(),
  status            text not null default 'awaiting_approval'
                      check (status in ('awaiting_approval', 'approved', 'rejected', 'running', 'completed',
                                        'failed', 'cancelled')),
  approval_chain_id uuid,
  decided_at        timestamptz,
  completed_at      timestamptz,
  failure_stage     text,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  version           bigint not null default 1,
  unique (organisation_id, id),
  constraint purge_requests_silo_fkey
    foreign key (organisation_id, silo_id) references siloes.siloes (organisation_id, id),
  constraint purge_requests_silo_file_fkey
    foreign key (organisation_id, silo_file_id) references siloes.silo_files (organisation_id, id),
  constraint purge_requests_requested_by_fkey
    foreign key (organisation_id, requested_by) references iam.memberships (organisation_id, id),
  constraint purge_requests_scope_target check (
    case scope
      when 'entity'  then object_type_id is not null and object_ref is not null and silo_file_id is null
      when 'file'    then silo_file_id is not null and object_type_id is null and object_ref is null
      when 'object'  then object_ref is not null and object_type_id is null and silo_file_id is null
      when 'index'   then silo_file_id is null and object_ref is null
      when 'concept' then object_type_id is not null and silo_file_id is null and object_ref is null
      when 'silo'    then object_type_id is null and silo_file_id is null and object_ref is null
    end),
  check ((status = 'completed') = (completed_at is not null))
);
comment on table siloes.purge_requests is
  'A request to purge Silo data, approved by a chain where one is configured, before the wipe runs.';
comment on column siloes.purge_requests.object_ref is
  'A resolved object reference for scope entity, a definition object name for scope object.';
comment on column siloes.purge_requests.approval_chain_id is
  'The chain whose decided steps are the approvers. Null where none is configured: the requester is the approver.';
comment on column siloes.purge_requests.failure_stage is 'The failing stage, never a value.';
create index purge_requests_by_silo on siloes.purge_requests (organisation_id, silo_id, requested_at desc);
create index purge_requests_open on siloes.purge_requests (organisation_id, status)
  where status in ('awaiting_approval', 'approved', 'running');
create index purge_requests_silo_file on siloes.purge_requests (organisation_id, silo_file_id)
  where silo_file_id is not null;
create index purge_requests_object_type on siloes.purge_requests (organisation_id, object_type_id)
  where object_type_id is not null;
create index purge_requests_approval_chain on siloes.purge_requests (organisation_id, approval_chain_id)
  where approval_chain_id is not null;
select platform.add_updated_at_trigger('siloes.purge_requests');
select platform.enable_tenant_rls('siloes.purge_requests');
create trigger purge_requests_frozen before update on siloes.purge_requests
  for each row execute function platform.freeze_columns('id', 'organisation_id', 'silo_id', 'scope',
                                                         'object_type_id', 'silo_file_id', 'object_ref',
                                                         'requested_by', 'requested_at', 'created_at');

grant select, insert, update on siloes.purge_requests to silo_app;
grant select on siloes.purge_requests to silo_report;

-- ===========================================================================
-- siloes.purge_receipts: append-only proof of what a wipe removed. Inserted once
-- the wipe completes; retained indefinitely, never purged.
-- ===========================================================================

create table siloes.purge_receipts (
  id               uuid primary key,
  organisation_id  uuid not null references iam.organisations (id),
  purge_request_id uuid not null,
  silo_id          uuid not null,
  scope            text not null check (scope in ('entity', 'file', 'object', 'index', 'concept', 'silo')),
  object_type_id   uuid,
  silo_file_id     uuid,
  object_ref       text,
  removed          jsonb not null check (jsonb_typeof(removed) = 'object'),
  counts           jsonb not null check (jsonb_typeof(counts) = 'object'),
  impact           jsonb not null,
  completed_at     timestamptz not null,
  unique (organisation_id, id),
  constraint purge_receipts_one_per_request unique (organisation_id, purge_request_id),
  constraint purge_receipts_request_fkey
    foreign key (organisation_id, purge_request_id) references siloes.purge_requests (organisation_id, id),
  constraint purge_receipts_silo_fkey
    foreign key (organisation_id, silo_id) references siloes.siloes (organisation_id, id),
  constraint purge_receipts_silo_file_fkey
    foreign key (organisation_id, silo_file_id) references siloes.silo_files (organisation_id, id),
  constraint purge_receipts_scope_target check (
    case scope
      when 'entity'  then object_type_id is not null and object_ref is not null and silo_file_id is null
      when 'file'    then silo_file_id is not null and object_type_id is null and object_ref is null
      when 'object'  then object_ref is not null and object_type_id is null and silo_file_id is null
      when 'index'   then silo_file_id is null and object_ref is null
      when 'concept' then object_type_id is not null and silo_file_id is null and object_ref is null
      when 'silo'    then object_type_id is null and silo_file_id is null and object_ref is null
    end)
);
comment on table siloes.purge_receipts is
  'Append-only proof of what a completed wipe removed, from which stores, and its detector impact.';
comment on column siloes.purge_receipts.removed is 'References and counts per store. Never values.';
comment on column siloes.purge_receipts.impact is
  'Detectors, timelines, lead times and search routes that stop working.';
create index purge_receipts_by_silo on siloes.purge_receipts (organisation_id, silo_id, completed_at desc);
create index purge_receipts_ledger on siloes.purge_receipts (organisation_id, completed_at desc);
create index purge_receipts_silo_file on siloes.purge_receipts (organisation_id, silo_file_id)
  where silo_file_id is not null;
create index purge_receipts_object_type on siloes.purge_receipts (organisation_id, object_type_id)
  where object_type_id is not null;
select platform.enable_tenant_rls('siloes.purge_receipts');
select platform.make_append_only('siloes.purge_receipts');

grant select, insert on siloes.purge_receipts to silo_app;
grant select on siloes.purge_receipts to silo_report;

-- ===========================================================================
-- Silo wipes and sweeps (spec 70; D39). The Capture tables and the extraction
-- tables are append-only or carry no delete grant: only these functions delete
-- from them, as their owner, for the organisation of the transaction, and each
-- returns what it removed so the receipt can count it. siloes-capture calls them.
-- ===========================================================================

create function siloes.require_organisation(p_organisation_id uuid) returns void
language plpgsql stable
set search_path = pg_catalog
as $$
begin
  if p_organisation_id is distinct from nullif(current_setting('app.org_id', true), '')::uuid then
    raise exception 'a Silo wipe acts on the organisation of its transaction only' using errcode = 'insufficient_privilege';
  end if;
end
$$;

-- Purge entity (one object), purge concept (one object type) or the whole Silo's Capture data.
create function siloes.purge_capture(p_organisation_id uuid, p_silo_id uuid, p_object_type_id uuid default null,
                                     p_object_ref text default null)
returns table (transitions bigint, baselines bigint, ledger bigint)
language plpgsql security definer
set search_path = pg_catalog
as $$
declare
  v_transitions bigint;
  v_baselines bigint;
  v_ledger bigint := 0;
begin
  perform siloes.require_organisation(p_organisation_id);
  delete from siloes.transitions t
  where t.organisation_id = p_organisation_id and t.silo_id = p_silo_id
    and (p_object_type_id is null or t.object_type_id = p_object_type_id)
    and (p_object_ref is null or t.object_ref = p_object_ref);
  get diagnostics v_transitions = row_count;
  delete from siloes.silo_baselines b
  where b.organisation_id = p_organisation_id and b.silo_id = p_silo_id
    and (p_object_type_id is null or b.object_type_id = p_object_type_id)
    and (p_object_ref is null or b.object_ref = p_object_ref);
  get diagnostics v_baselines = row_count;
  -- The whole Silo: the copy of the Action ledger it holds goes with it; receipts stay (70.3, D205).
  if p_object_type_id is null and p_object_ref is null then
    delete from siloes.action_ledger l where l.organisation_id = p_organisation_id and l.silo_id = p_silo_id;
    get diagnostics v_ledger = row_count;
  end if;
  return query select v_transitions, v_baselines, v_ledger;
end
$$;
grant execute on function siloes.purge_capture(uuid, uuid, uuid, text) to silo_app;

-- The retention sweep for a Capture Silo: transitions observed, and baselines last seen, before the cutoff.
create function siloes.sweep_capture(p_organisation_id uuid, p_silo_id uuid, p_before timestamptz)
returns table (transitions bigint, baselines bigint, ledger bigint)
language plpgsql security definer
set search_path = pg_catalog
as $$
declare
  v_transitions bigint;
  v_baselines bigint;
  v_ledger bigint;
begin
  perform siloes.require_organisation(p_organisation_id);
  delete from siloes.transitions t
  where t.organisation_id = p_organisation_id and t.silo_id = p_silo_id and t.observed_at < p_before;
  get diagnostics v_transitions = row_count;
  delete from siloes.silo_baselines b
  where b.organisation_id = p_organisation_id and b.silo_id = p_silo_id and b.last_seen_at < p_before;
  get diagnostics v_baselines = row_count;
  -- The ledger copy keeps to the Silo's window too (70; D205).
  delete from siloes.action_ledger l
  where l.organisation_id = p_organisation_id and l.silo_id = p_silo_id and l.executed_at < p_before;
  get diagnostics v_ledger = row_count;
  return query select v_transitions, v_baselines, v_ledger;
end
$$;
grant execute on function siloes.sweep_capture(uuid, uuid, timestamptz) to silo_app;

-- Extracted values and their confirmations: of one file, of one definition object, or of the whole Silo.
create function siloes.purge_extractions(p_organisation_id uuid, p_silo_id uuid, p_file_id uuid default null,
                                         p_object text default null)
returns bigint
language plpgsql security definer
set search_path = pg_catalog
as $$
declare
  v_removed bigint;
begin
  perform siloes.require_organisation(p_organisation_id);
  -- One statement: the confirmations and their extractions go together.
  with gone as (
    select e.id from siloes.silo_extractions e
    join siloes.silo_files f on f.organisation_id = e.organisation_id and f.id = e.file_id
    where e.organisation_id = p_organisation_id and f.silo_id = p_silo_id
      and (p_file_id is null or e.file_id = p_file_id) and (p_object is null or e.object = p_object)
  ), confirmations as (
    delete from siloes.extraction_confirmations c
    where c.organisation_id = p_organisation_id and c.extraction_id in (select id from gone)
  )
  delete from siloes.silo_extractions e where e.organisation_id = p_organisation_id and e.id in (select id from gone);
  get diagnostics v_removed = row_count;
  return v_removed;
end
$$;
grant execute on function siloes.purge_extractions(uuid, uuid, uuid, text) to silo_app;

-- Bytes a Capture Silo holds in Postgres, for metering (67.6): its rows, encrypted values included.
create function siloes.capture_bytes(p_organisation_id uuid, p_silo_id uuid) returns bigint
language sql stable security definer
set search_path = pg_catalog
as $$
  select coalesce((select sum(octet_length(t.previous_value) + octet_length(t.new_value) + octet_length(t.object_ref)
                              + octet_length(t.property) + 72)
                   from siloes.transitions t where t.organisation_id = p_organisation_id and t.silo_id = p_silo_id), 0)::bigint
       + coalesce((select sum(octet_length(b.last_observed_value) + octet_length(b.object_ref) + octet_length(b.property) + 64)
                   from siloes.silo_baselines b where b.organisation_id = p_organisation_id and b.silo_id = p_silo_id), 0)::bigint
       -- The Action ledger copy it holds is metered with it (66.4; D205).
       + coalesce((select sum(coalesce(octet_length(l.prior_values), 0) + coalesce(octet_length(l.new_values), 0) + octet_length(l.action_type)
                              + octet_length(l.object_type) + 16 * (cardinality(l.approvers) + cardinality(l.marking_ids)) + 200)
                   from siloes.action_ledger l where l.organisation_id = p_organisation_id and l.silo_id = p_silo_id), 0)::bigint
$$;
grant execute on function siloes.capture_bytes(uuid, uuid) to silo_app;

-- Across organisations, identifiers only: the workers' lists.
create function siloes.live_siloes(p_limit integer) returns table (organisation_id uuid, id uuid, kind text)
language sql stable security definer
set search_path = pg_catalog
as $$
  select s.organisation_id, s.id, s.kind from siloes.siloes s where s.disabled_at is null
  order by s.organisation_id, s.id limit p_limit
$$;
grant execute on function siloes.live_siloes(integer) to silo_app;

create function siloes.open_purge_requests(p_limit integer) returns table (organisation_id uuid, id uuid)
language sql stable security definer
set search_path = pg_catalog
as $$
  select r.organisation_id, r.id from siloes.purge_requests r
  where r.status in ('awaiting_approval', 'approved') order by r.requested_at, r.id limit p_limit
$$;
grant execute on function siloes.open_purge_requests(integer) to silo_app;

create function siloes.files_to_process(p_limit integer) returns table (organisation_id uuid, id uuid)
language sql stable security definer
set search_path = pg_catalog
as $$
  select f.organisation_id, f.id from siloes.silo_files f where f.status = 'received'
  order by f.received_at, f.id limit p_limit
$$;
grant execute on function siloes.files_to_process(integer) to silo_app;

create function siloes.watched_sources_due(p_limit integer) returns table (organisation_id uuid, id uuid)
language sql stable security definer
set search_path = pg_catalog
as $$
  select w.organisation_id, w.id from siloes.silo_sources w
  where w.kind = 'watched' and w.disabled_at is null
    and (w.last_polled_at is null or w.last_polled_at <= now() - make_interval(mins => w.poll_interval_minutes))
  order by w.last_polled_at nulls first, w.id limit p_limit
$$;
grant execute on function siloes.watched_sources_due(integer) to silo_app;

-- ===========================================================================
-- billing.subscriptions
-- ===========================================================================

create table billing.subscriptions (
  id                     uuid primary key,
  organisation_id        uuid not null references iam.organisations (id),
  plan                   text not null check (plan in ('standard', 'business')),
  seat_count             integer not null check (seat_count >= 1),
  term                   text not null check (term in ('monthly', 'annual')),
  discount_tier          text not null
                           check (discount_tier in ('list', 'tier_25_99', 'tier_100_249', 'tier_250_499', 'quoted')),
  stripe_customer_id     text not null,
  stripe_subscription_id text not null unique,
  current_period_start   timestamptz not null,
  current_period_end     timestamptz not null,
  status                 text not null check (status in ('active', 'past_due', 'suspended', 'cancelled')),
  cancelled_at           timestamptz,
  created_at             timestamptz not null default now(),
  updated_at             timestamptz not null default now(),
  unique (organisation_id, id),
  check (current_period_end > current_period_start),
  check (status <> 'cancelled' or cancelled_at is not null)
);
comment on table billing.subscriptions is
  'A self-serve Stripe subscription (Standard or Business), mirrored from verified webhooks.';
comment on column billing.subscriptions.status is
  'Mirrors iam.organisations.billing_status; written in the same transaction by the webhook or a staff path.';
create unique index subscriptions_one_live on billing.subscriptions (organisation_id) where status <> 'cancelled';
create index subscriptions_history on billing.subscriptions (organisation_id, created_at desc);
select platform.add_updated_at_trigger('billing.subscriptions');
select platform.enable_tenant_rls('billing.subscriptions');
create trigger subscriptions_frozen before update on billing.subscriptions
  for each row execute function platform.freeze_columns('id', 'organisation_id', 'stripe_customer_id',
                                                         'stripe_subscription_id', 'created_at');

grant select, insert, update on billing.subscriptions to silo_app;
grant select on billing.subscriptions to silo_report;

-- ===========================================================================
-- billing.contracts: the tenant reads its own; only an admin-portal operator
-- session writes (contract.manage is staff only)
-- ===========================================================================

create table billing.contracts (
  id                     uuid primary key,
  organisation_id        uuid not null references iam.organisations (id),
  status                 text not null default 'draft'
                           check (status in ('draft', 'awaiting_margin_approval', 'active', 'expired', 'terminated')),
  platform_fee           numeric(14,2) not null check (platform_fee >= 0),
  seat_count             integer not null check (seat_count >= 0),
  seat_rate              numeric(10,2) not null check (seat_rate >= 0),
  token_allocation       bigint not null check (token_allocation >= 0),
  daily_token_limit      integer not null check (daily_token_limit >= 0),
  simulation_allocation  integer not null check (simulation_allocation >= 0),
  storage_included_bytes bigint not null check (storage_included_bytes >= 0),
  -- Distinct live objects the organisation may hold at once (9.5, 30.5: contractual on Enterprise); null is the cell's default.
  live_objects_limit          integer check (live_objects_limit is null or live_objects_limit between 1 and 100000000),
  storage_rate           numeric(6,4) not null default 0.1000 check (storage_rate >= 0),
  capabilities           text[] not null
                           check (capabilities <@ array['sso', 'scim', 'custom_roles', 'dedicated', 'sovereign']::text[]),
  sovereign              boolean not null default false,
  fde_onboarding_bundled boolean not null default false,
  term_start             date not null,
  term_end               date not null,
  payment_terms          text not null check (length(btrim(payment_terms)) > 0),
  purchase_order_ref     text,
  renewal_state          text not null default 'upcoming'
                           check (renewal_state in ('upcoming', 'in_negotiation', 'renewed', 'lapsed')),
  signed_by              text,
  countersigned_at       timestamptz,
  quoted_margin          numeric(5,4),
  margin_approved_by     uuid constraint contracts_margin_approved_by_fkey references platform.operators (id),
  margin_approved_at     timestamptz,
  stripe_customer_id     text,
  created_by             uuid not null constraint contracts_created_by_fkey references platform.operators (id),
  countersigned_by       uuid constraint contracts_countersigned_by_fkey references platform.operators (id),
  overage_reported_tokens bigint not null default 0 check (overage_reported_tokens >= 0),
  created_at             timestamptz not null default now(),
  updated_at             timestamptz not null default now(),
  version                bigint not null default 1,
  unique (organisation_id, id),
  constraint contracts_no_overlap
    exclude using gist (organisation_id with =, daterange(term_start, term_end, '[]') with &&)
    where (status = 'active'),
  check (term_end > term_start),
  check (status <> 'active' or signed_by is not null),
  check (status <> 'active' or countersigned_at is not null),
  check ((margin_approved_by is null) = (margin_approved_at is null)),
  check ((countersigned_by is null) = (countersigned_at is null)),
  -- Sign-off below the margin floor is someone else's than the quote's author (74.4).
  constraint contracts_margin_approved_by_other check (margin_approved_by is null or margin_approved_by <> created_by),
  -- Per seat per month, as entitlements carry them (71.4, 73.3).
  check (token_allocation <= 2147483647)
);
comment on table billing.contracts is 'An Enterprise contract, from which entitlements derive while active.';
comment on column billing.contracts.storage_rate is 'Margin over provider storage cost, as a fraction (0.1000 is 10%).';
comment on column billing.contracts.signed_by is 'Customer signatory.';
comment on column billing.contracts.margin_approved_by is 'Staff sign-off where the quoted margin is below the floor.';
comment on column billing.contracts.token_allocation is
  'Tokens per seat per month (73.3: negotiated on Enterprise); the term''s allocation is this times seats times months.';
comment on column billing.contracts.simulation_allocation is 'Simulations per seat per month (73.7: negotiated on Enterprise).';
comment on column billing.contracts.created_by is 'The member of staff who quoted it.';
comment on column billing.contracts.countersigned_by is 'The member of staff who countersigned for Silo.';
comment on column billing.contracts.overage_reported_tokens is
  'Overage already reported (74.3: overage accrues and reports, never charges); a report is raised when it grows.';
create index contracts_renewals on billing.contracts (organisation_id, term_end) where status = 'active';
select platform.add_updated_at_trigger('billing.contracts');
create trigger contracts_frozen before update on billing.contracts
  for each row execute function platform.freeze_columns('id', 'organisation_id', 'created_at');

-- Reads under the standard tenant policy; writes also need a member of staff (app.operator_id,
-- which only the admin portal's requests carry; D45). The renewal sweep moves renewal state
-- through billing.advance_contract_renewal. An empty setting counts as unset: a custom
-- setting reads '' after SET LOCAL ends.
alter table billing.contracts enable row level security;
alter table billing.contracts force row level security;
create policy tenant_read on billing.contracts for select
  using (organisation_id = (select current_setting('app.org_id')::uuid));
create policy operator_insert on billing.contracts for insert
  with check (organisation_id = (select current_setting('app.org_id')::uuid)
              and (select nullif(current_setting('app.operator_id', true), '')::uuid) is not null);
create policy operator_update on billing.contracts for update
  using (organisation_id = (select current_setting('app.org_id')::uuid)
         and (select nullif(current_setting('app.operator_id', true), '')::uuid) is not null)
  with check (organisation_id = (select current_setting('app.org_id')::uuid)
              and (select nullif(current_setting('app.operator_id', true), '')::uuid) is not null);

-- The renewal sweep, across organisations: identifiers of active contracts whose renewal
-- state moves today (lapse at term end without renewal; a renewed contract's next renewal
-- becomes upcoming within the notice window).
create function billing.contracts_to_advance(p_today date, p_notice_days integer, p_limit integer)
  returns table (organisation_id uuid, id uuid)
language sql stable security definer
set search_path = pg_catalog
as $$
  select c.organisation_id, c.id from billing.contracts c
  where c.status = 'active'
    and (c.term_end < p_today or (c.renewal_state = 'renewed' and c.term_end <= p_today + p_notice_days))
  order by c.term_end, c.id
  limit least(greatest(p_limit, 1), 1000)
$$;
revoke all on function billing.contracts_to_advance(date, integer, integer) from public;
grant execute on function billing.contracts_to_advance(date, integer, integer) to silo_app;

-- Moves one contract's renewal state, in its organisation's context, and says what it did:
-- 'lapsed' (term ended unrenewed: expired, renewal state lapsed), 'upcoming', or null.
create function billing.advance_contract_renewal(p_contract_id uuid, p_today date, p_notice_days integer)
  returns text
language plpgsql security definer
set search_path = pg_catalog
as $$
declare
  v_org uuid := nullif(current_setting('app.org_id', true), '')::uuid;
  v_row billing.contracts%rowtype;
begin
  select * into v_row from billing.contracts where id = p_contract_id and organisation_id = v_org and status = 'active' for update;
  if not found then
    return null;
  end if;
  if v_row.term_end < p_today then
    update billing.contracts set status = 'expired', renewal_state = 'lapsed', version = version + 1 where id = p_contract_id;
    return 'lapsed';
  end if;
  if v_row.renewal_state = 'renewed' and v_row.term_end <= p_today + p_notice_days then
    update billing.contracts set renewal_state = 'upcoming', version = version + 1 where id = p_contract_id;
    return 'upcoming';
  end if;
  return null;
end
$$;
revoke all on function billing.advance_contract_renewal(uuid, date, integer) from public;
grant execute on function billing.advance_contract_renewal(uuid, date, integer) to silo_app;

-- A canvas drawn as an image (decision 2026-11-14; D88): queued by the exporter, claimed by
-- the renderer (headless Chromium rendering the web client's own components), completed
-- into Files under the exporter's own session, or failed. A job unclaimed or unfinished by
-- its expiry is expired. The renderer is deferred until the web client exists; the record
-- and its API are fixed now so it plugs in without a backend change.
create table clone.render_jobs (
  id              uuid primary key,
  organisation_id uuid not null references iam.organisations (id),
  canvas_view_id  uuid not null,
  requested_by    uuid not null,
  session_id      uuid not null,
  format          text not null check (format = 'png'),
  width           integer not null check (width between 64 and 8192),
  height          integer not null check (height between 64 and 8192),
  scale           numeric not null default 1 check (scale between 1 and 4),
  folder_id       uuid,
  status          text not null default 'queued' check (status in ('queued', 'completed', 'failed', 'expired')),
  -- The markings the exporter's browser was told to print (29.10): the image is filed only if its inputs carry no other.
  printed_marking_ids uuid[] not null default '{}',
  -- What the browser drew besides the set (D228): a site plan or a 3D model, whose own markings the image carries.
  drawn_plan_id        uuid,
  drawn_asset_model_id uuid,
  file_id         uuid,
  failure_code    text check (failure_code is null or failure_code ~ '^[a-z][a-z0-9_.]{2,80}$'),
  requested_at    timestamptz not null default now(),
  completed_at    timestamptz,
  expires_at      timestamptz not null,
  unique (organisation_id, id),
  foreign key (organisation_id, canvas_view_id) references clone.canvas_views (organisation_id, id),
  foreign key (organisation_id, requested_by) references iam.memberships (organisation_id, id),
  foreign key (organisation_id, drawn_plan_id) references clone.spatial_plans (organisation_id, id),
  foreign key (organisation_id, drawn_asset_model_id) references clone.asset_models (organisation_id, id),
  check (num_nonnulls(drawn_plan_id, drawn_asset_model_id) <= 1),
  check ((status = 'completed') = (file_id is not null)),
  check ((status = 'failed') = (failure_code is not null)),
  check (expires_at > requested_at)
);
comment on table clone.render_jobs is
  'A canvas exported as an image (D88, D225): queued for the exporter''s own browser to draw, then completed into Files or failed.';
create index render_jobs_canvas_view on clone.render_jobs (organisation_id, canvas_view_id);
create index render_jobs_drawn_plan on clone.render_jobs (organisation_id, drawn_plan_id) where drawn_plan_id is not null;
create index render_jobs_drawn_asset_model on clone.render_jobs (organisation_id, drawn_asset_model_id) where drawn_asset_model_id is not null;
select platform.enable_tenant_rls('clone.render_jobs');
create trigger render_jobs_frozen before update on clone.render_jobs
  for each row execute function platform.freeze_columns('id', 'organisation_id', 'canvas_view_id', 'requested_by', 'session_id', 'format',
    'width', 'height', 'scale', 'folder_id', 'printed_marking_ids', 'drawn_plan_id', 'drawn_asset_model_id', 'requested_at', 'expires_at');
grant select, insert, update on clone.render_jobs to silo_app;

-- The overage sweep, across organisations: identifiers of active contracts.
create function billing.active_contracts(p_limit integer, p_after uuid)
  returns table (organisation_id uuid, id uuid)
language sql stable security definer
set search_path = pg_catalog
as $$
  select c.organisation_id, c.id from billing.contracts c
  where c.status = 'active' and (p_after is null or c.id > p_after)
  order by c.id
  limit least(greatest(p_limit, 1), 1000)
$$;
revoke all on function billing.active_contracts(integer, uuid) from public;
grant execute on function billing.active_contracts(integer, uuid) to silo_app;

-- Records overage newly reported on one contract, in its organisation's context; false
-- when it is not more than already reported (74.3: overage accrues and reports).
create function billing.record_contract_overage(p_contract_id uuid, p_tokens bigint)
  returns boolean
language plpgsql security definer
set search_path = pg_catalog
as $$
declare
  v_org uuid := nullif(current_setting('app.org_id', true), '')::uuid;
begin
  update billing.contracts set overage_reported_tokens = p_tokens, version = version + 1
  where id = p_contract_id and organisation_id = v_org and status = 'active' and overage_reported_tokens < p_tokens;
  return found;
end
$$;
revoke all on function billing.record_contract_overage(uuid, bigint) from public;
grant execute on function billing.record_contract_overage(uuid, bigint) to silo_app;

grant select, insert, update on billing.contracts to silo_app;
grant select on billing.contracts to silo_report;

-- ===========================================================================
-- billing.entitlements: never updated in place except to close the open row
-- ===========================================================================

-- A sovereign customer's entitlement terms in the sovereign cell (D204; decision 2026-11-19): the
-- contract itself is held in Silo's commercial billing (sovereign set, invoiced through Stripe as
-- any Enterprise contract); billing is compiled out of the sovereign cell, so UK cleared staff
-- enter the terms that contract grants here, by its reference, and a second approves them, which
-- opens the entitlement and the seats. No price: those are the commercial record's.
create table billing.sovereign_terms (
  id                          uuid primary key,
  organisation_id             uuid not null references iam.organisations (id),
  commercial_contract_ref     text not null check (commercial_contract_ref ~ '^[A-Za-z0-9][A-Za-z0-9._:/-]{0,99}$'),
  seats                       integer not null check (seats >= 0),
  tokens_per_seat_period      integer not null check (tokens_per_seat_period >= 0),
  simulations_per_seat_period integer not null check (simulations_per_seat_period >= 0),
  daily_token_limit           integer not null check (daily_token_limit >= 0),
  storage_included_bytes      bigint not null check (storage_included_bytes >= 0),
  live_objects_limit          integer check (live_objects_limit is null or live_objects_limit between 1 and 100000000),
  capabilities                text[] not null
                                check (capabilities <@ array['sso', 'scim', 'custom_roles', 'dedicated', 'sovereign',
                                                             'ai_connector_builder', 'nocode_connector_builder']::text[]),
  term_start                  date not null,
  term_end                    date not null,
  status                      text not null default 'pending' check (status in ('pending', 'approved', 'rejected')),
  entered_by                  uuid not null constraint sovereign_terms_entered_by_fkey references platform.operators (id),
  entered_at                  timestamptz not null default now(),
  decided_by                  uuid constraint sovereign_terms_decided_by_fkey references platform.operators (id),
  decided_at                  timestamptz,
  created_at                  timestamptz not null default now(),
  updated_at                  timestamptz not null default now(),
  unique (organisation_id, id),
  check (term_end > term_start),
  check ((decided_by is null) = (decided_at is null)),
  check ((status = 'pending') = (decided_at is null)),
  -- Two people: whoever enters the terms never approves them.
  constraint sovereign_terms_decided_by_other check (decided_by is null or decided_by <> entered_by)
);
comment on table billing.sovereign_terms is
  'A sovereign customer''s entitlement terms, entered and approved by two UK cleared operators, from the commercial contract by reference (D204).';
create index sovereign_terms_organisation on billing.sovereign_terms (organisation_id, entered_at desc);
select platform.add_updated_at_trigger('billing.sovereign_terms');
select platform.enable_tenant_rls('billing.sovereign_terms');
create trigger sovereign_terms_frozen before update on billing.sovereign_terms
  for each row execute function platform.freeze_columns('id', 'organisation_id', 'commercial_contract_ref', 'seats', 'tokens_per_seat_period',
    'simulations_per_seat_period', 'daily_token_limit', 'storage_included_bytes', 'live_objects_limit', 'capabilities', 'term_start', 'term_end',
    'entered_by', 'entered_at', 'created_at');
grant select, insert on billing.sovereign_terms to silo_app;
grant update (status, decided_by, decided_at, updated_at) on billing.sovereign_terms to silo_app;
grant select on billing.sovereign_terms to silo_report;

create table billing.entitlements (
  id                          uuid primary key,
  organisation_id             uuid not null references iam.organisations (id),
  seats                       integer not null check (seats >= 0),
  tokens_per_seat_period      integer not null check (tokens_per_seat_period >= 0),
  simulations_per_seat_period integer not null check (simulations_per_seat_period >= 0),
  daily_token_limit           integer not null check (daily_token_limit >= 0),
  storage_included_bytes      bigint not null check (storage_included_bytes >= 0),
  -- Distinct live objects the organisation may hold at once (9.5, 30.5: contractual on Enterprise); null is the cell's default.
  live_objects_limit          integer check (live_objects_limit is null or live_objects_limit between 1 and 100000000),
  -- Connections the organisation may hold, from the plan; null is unlimited (Enterprise).
  -- Decision 2026-11-14 amending 71.2: adding one beyond it is refused, none is ever disconnected (D76).
  connections_limit           integer check (connections_limit >= 0),
  -- ai_connector_builder and nocode_connector_builder: the build routes, Enterprise only (D76).
  capabilities                text[] not null
                                check (capabilities <@ array['sso', 'scim', 'custom_roles', 'dedicated', 'sovereign',
                                                             'ai_connector_builder', 'nocode_connector_builder']::text[]),
  source                      text not null check (source in ('subscription', 'contract', 'sovereign_terms')),
  subscription_id             uuid,
  contract_id                 uuid,
  -- A sovereign customer's, in the sovereign cell (D204).
  sovereign_terms_id          uuid,
  effective_from              timestamptz not null,
  effective_to                timestamptz,
  created_at                  timestamptz not null default now(),
  unique (organisation_id, id),
  constraint entitlements_subscription_fkey
    foreign key (organisation_id, subscription_id) references billing.subscriptions (organisation_id, id),
  constraint entitlements_contract_fkey
    foreign key (organisation_id, contract_id) references billing.contracts (organisation_id, id),
  constraint entitlements_no_overlap
    exclude using gist (organisation_id with =, tstzrange(effective_from, effective_to) with &&),
  constraint entitlements_sovereign_terms_fkey
    foreign key (organisation_id, sovereign_terms_id) references billing.sovereign_terms (organisation_id, id),
  constraint entitlements_source_arc
    check ((source = 'subscription' and subscription_id is not null and contract_id is null and sovereign_terms_id is null)
           or (source = 'contract' and contract_id is not null and subscription_id is null and sovereign_terms_id is null)
           or (source = 'sovereign_terms' and sovereign_terms_id is not null and subscription_id is null and contract_id is null)),
  check (effective_to > effective_from)
);
comment on table billing.entitlements is
  'Versioned limits and capabilities in force for an organisation: the only billing data the product reads.';
create unique index entitlements_open on billing.entitlements (organisation_id) where effective_to is null;
create index entitlements_subscription on billing.entitlements (organisation_id, subscription_id)
  where subscription_id is not null;
create index entitlements_contract on billing.entitlements (organisation_id, contract_id)
  where contract_id is not null;
create index entitlements_sovereign_terms on billing.entitlements (organisation_id, sovereign_terms_id)
  where sovereign_terms_id is not null;
select platform.enable_tenant_rls('billing.entitlements');

-- The one permitted update closes the open row by setting effective_to.
create function billing.entitlements_close_once() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
begin
  if old.effective_to is not null or new.effective_to is null
     or (to_jsonb(new) - 'effective_to') <> (to_jsonb(old) - 'effective_to') then
    raise exception 'billing.entitlements rows are not updated in place: the only update sets effective_to on the open row'
      using errcode = 'insufficient_privilege';
  end if;
  return new;
end
$$;
create trigger entitlements_close_once before update on billing.entitlements
  for each row execute function billing.entitlements_close_once();

grant select, insert on billing.entitlements to silo_app;
grant update (effective_to) on billing.entitlements to silo_app;
grant select on billing.entitlements to silo_report;

-- ===========================================================================
-- billing.seats
-- ===========================================================================

create table billing.seats (
  id                 uuid primary key,
  organisation_id    uuid not null references iam.organisations (id),
  subscription_id    uuid,
  contract_id        uuid,
  -- A sovereign customer's seats, from its approved terms (D204).
  sovereign_terms_id uuid,
  membership_id      uuid,
  allocated_scope_id uuid,
  allocated_by       uuid,
  allocated_at       timestamptz,
  plan_tier          text not null check (plan_tier in ('standard', 'business', 'enterprise')),
  status             text not null default 'unassigned' check (status in ('unassigned', 'assigned', 'reclaimed', 'released')),
  created_at         timestamptz not null default now(),
  released_at        timestamptz,
  updated_at         timestamptz not null default now(),
  version            bigint not null default 1,
  unique (organisation_id, id),
  constraint seats_subscription_fkey
    foreign key (organisation_id, subscription_id) references billing.subscriptions (organisation_id, id),
  constraint seats_contract_fkey
    foreign key (organisation_id, contract_id) references billing.contracts (organisation_id, id),
  constraint seats_membership_fkey
    foreign key (organisation_id, membership_id) references iam.memberships (organisation_id, id),
  constraint seats_allocated_scope_fkey
    foreign key (organisation_id, allocated_scope_id) references iam.scopes (organisation_id, id),
  constraint seats_allocated_by_fkey
    foreign key (organisation_id, allocated_by) references iam.memberships (organisation_id, id),
  constraint seats_sovereign_terms_fkey
    foreign key (organisation_id, sovereign_terms_id) references billing.sovereign_terms (organisation_id, id),
  constraint seats_source_arc check (num_nonnulls(subscription_id, contract_id, sovereign_terms_id) = 1),
  check ((status = 'assigned') = (membership_id is not null)),
  check ((allocated_by is null) = (allocated_at is null)),
  check ((status = 'released') = (released_at is not null))
);
comment on table billing.seats is
  'One purchased seat and its lifecycle, independent of the membership occupying it.';
comment on column billing.seats.allocated_scope_id is 'Scope whose pool holds the seat while unassigned.';
create unique index seats_one_per_membership on billing.seats (organisation_id, membership_id)
  where status = 'assigned';
create index seats_by_status on billing.seats (organisation_id, status);
create index seats_available on billing.seats (organisation_id, allocated_scope_id, plan_tier)
  where status in ('unassigned', 'reclaimed');
create index seats_subscription on billing.seats (organisation_id, subscription_id) where subscription_id is not null;
create index seats_contract on billing.seats (organisation_id, contract_id) where contract_id is not null;
create index seats_sovereign_terms on billing.seats (organisation_id, sovereign_terms_id) where sovereign_terms_id is not null;
select platform.add_updated_at_trigger('billing.seats');
select platform.enable_tenant_rls('billing.seats');
create trigger seats_frozen before update on billing.seats
  for each row execute function platform.freeze_columns('id', 'organisation_id', 'subscription_id', 'contract_id',
                                                         'plan_tier', 'created_at');

-- A released seat cannot return to another status.
create function billing.seats_released_is_terminal() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
begin
  raise exception 'billing.seats: seat % is released and cannot return to another status', old.id
    using errcode = 'check_violation';
end
$$;
create trigger seats_released_is_terminal before update on billing.seats
  for each row when (old.status = 'released' and new.status <> 'released')
  execute function billing.seats_released_is_terminal();

grant select, insert, update on billing.seats to silo_app;
grant select on billing.seats to silo_report;

-- ===========================================================================
-- billing.seat_allocations
-- ===========================================================================

create table billing.seat_allocations (
  id              uuid primary key,
  organisation_id uuid not null references iam.organisations (id),
  scope_id        uuid not null,
  seats_allocated integer not null check (seats_allocated >= 0),
  plan_tier       text not null check (plan_tier in ('standard', 'business', 'enterprise')),
  allocated_by    uuid not null,
  allocated_at    timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  version         bigint not null default 1,
  unique (organisation_id, id),
  constraint seat_allocations_pool_key unique (organisation_id, scope_id, plan_tier),
  constraint seat_allocations_scope_fkey
    foreign key (organisation_id, scope_id) references iam.scopes (organisation_id, id),
  constraint seat_allocations_allocated_by_fkey
    foreign key (organisation_id, allocated_by) references iam.memberships (organisation_id, id)
);
comment on table billing.seat_allocations is
  'A pool of seats held against a scope, drawn from its parent scope''s pool.';
select platform.add_updated_at_trigger('billing.seat_allocations');
select platform.enable_tenant_rls('billing.seat_allocations');
create trigger seat_allocations_frozen before update on billing.seat_allocations
  for each row execute function platform.freeze_columns('id', 'organisation_id', 'scope_id', 'plan_tier');

grant select, insert, update on billing.seat_allocations to silo_app;
grant select on billing.seat_allocations to silo_report;

-- ===========================================================================
-- billing.token_allowances, billing.simulation_allowances, billing.token_balances:
-- the charge path. Column-level update grants keep the keys fixed without a
-- trigger on every charge.
-- ===========================================================================

create table billing.token_allowances (
  id                uuid primary key,
  organisation_id   uuid not null references iam.organisations (id),
  membership_id     uuid not null,
  period_start      timestamptz not null,
  period_end        timestamptz not null,
  tokens_granted    integer not null check (tokens_granted >= 0),
  tokens_consumed   integer not null default 0,
  daily_limit       integer not null check (daily_limit >= 0),
  daily_consumed    integer not null default 0,
  daily_consumed_on date,
  created_at        timestamptz not null default now(),
  unique (organisation_id, id),
  constraint token_allowances_period_key unique (organisation_id, membership_id, period_start),
  constraint token_allowances_membership_fkey
    foreign key (organisation_id, membership_id) references iam.memberships (organisation_id, id),
  check (period_end > period_start),
  check (tokens_consumed between 0 and tokens_granted),
  check (daily_consumed between 0 and daily_limit)
);
comment on table billing.token_allowances is
  'A membership''s token allowance for one billing period, with consumption and the daily counter.';
comment on column billing.token_allowances.daily_consumed_on is
  'Date of daily_consumed in the organisation''s time zone; the charge resets the counter on a new date.';
select platform.enable_tenant_rls('billing.token_allowances');

grant select, insert on billing.token_allowances to silo_app;
grant update (tokens_granted, tokens_consumed, daily_limit, daily_consumed, daily_consumed_on)
  on billing.token_allowances to silo_app;
grant select on billing.token_allowances to silo_report;

create table billing.simulation_allowances (
  id                   uuid primary key,
  organisation_id      uuid not null references iam.organisations (id),
  membership_id        uuid not null,
  period_start         timestamptz not null,
  period_end           timestamptz not null,
  simulations_granted  integer not null check (simulations_granted >= 0),
  simulations_consumed numeric(10,4) not null default 0,
  created_at           timestamptz not null default now(),
  unique (organisation_id, id),
  constraint simulation_allowances_period_key unique (organisation_id, membership_id, period_start),
  constraint simulation_allowances_membership_fkey
    foreign key (organisation_id, membership_id) references iam.memberships (organisation_id, id),
  check (period_end > period_start),
  check (simulations_consumed between 0 and simulations_granted)
);
comment on table billing.simulation_allowances is 'A membership''s simulation allowance for one billing period.';
comment on column billing.simulation_allowances.simulations_consumed is 'Numeric because a re-run charges a fraction.';
select platform.enable_tenant_rls('billing.simulation_allowances');

grant select, insert on billing.simulation_allowances to silo_app;
grant update (simulations_granted, simulations_consumed) on billing.simulation_allowances to silo_app;
grant select on billing.simulation_allowances to silo_report;

create table billing.token_balances (
  id                              uuid primary key,
  organisation_id                 uuid not null references iam.organisations (id),
  membership_id                   uuid not null,
  purchased_remaining             integer not null default 0 check (purchased_remaining >= 0),
  onboarding_grant_remaining      integer not null default 0 check (onboarding_grant_remaining between 0 and 200),
  simulations_purchased_remaining numeric(10,4) not null default 0 check (simulations_purchased_remaining >= 0),
  auto_topup                      boolean not null default false,
  onboarding_granted_at           timestamptz,
  updated_at                      timestamptz not null default now(),
  unique (organisation_id, id),
  constraint token_balances_membership_key unique (organisation_id, membership_id),
  constraint token_balances_membership_fkey
    foreign key (organisation_id, membership_id) references iam.memberships (organisation_id, id)
);
comment on table billing.token_balances is
  'A membership''s purchased and onboarding balances, which never expire.';
comment on column billing.token_balances.onboarding_granted_at is
  'When the 200-token onboarding grant was given: once ever, whenever the balance itself was opened (by a purchase, say).';
select platform.add_updated_at_trigger('billing.token_balances');
select platform.enable_tenant_rls('billing.token_balances');

grant select, insert on billing.token_balances to silo_app;
grant update (purchased_remaining, onboarding_grant_remaining, simulations_purchased_remaining, auto_topup, onboarding_granted_at)
  on billing.token_balances to silo_app;
grant select on billing.token_balances to silo_report;

-- ===========================================================================
-- billing.token_transactions: append-only ledger of every charge, partitioned by
-- month on occurred_at
-- ===========================================================================

create table billing.token_transactions (
  id                    bigint generated always as identity,
  organisation_id       uuid not null references iam.organisations (id),
  membership_id         uuid,
  operation             text not null
                          check (operation in ('compile', 'advanced_compile', 'connector_generation', 'repair_proposal',
                                               'document_extraction', 'simulation', 'simulation_rerun')),
  pool                  text not null check (pool in ('tokens', 'simulations')),
  weight                numeric(12,4) not null check (weight > 0),
  source                text not null check (source in ('grant', 'allowance', 'purchase', 'contract')),
  correlation_id        uuid not null,
  silo_file_id          uuid,
  simulation_run_id     uuid,
  heal_proposal_id      uuid,
  connector_manifest_id uuid,
  engagement_id         uuid,
  occurred_at           timestamptz not null default now(),
  primary key (id, occurred_at),
  constraint token_transactions_membership_fkey
    foreign key (organisation_id, membership_id) references iam.memberships (organisation_id, id),
  constraint token_transactions_silo_file_fkey
    foreign key (organisation_id, silo_file_id) references siloes.silo_files (organisation_id, id),
  constraint token_transactions_pool
    check ((pool = 'simulations') = (operation in ('simulation', 'simulation_rerun'))),
  constraint token_transactions_whole_tokens check (pool <> 'tokens' or weight = trunc(weight)),
  constraint token_transactions_contract_debit check ((source = 'contract') = (membership_id is null)),
  constraint token_transactions_paid_for_arc
    check (num_nonnulls(silo_file_id, simulation_run_id, heal_proposal_id, connector_manifest_id) <= 1),
  constraint token_transactions_extraction_file
    check ((operation = 'document_extraction') = (silo_file_id is not null)),
  constraint token_transactions_simulation_run
    check ((operation in ('simulation', 'simulation_rerun')) = (simulation_run_id is not null)),
  constraint token_transactions_heal_proposal
    check ((operation = 'repair_proposal') = (heal_proposal_id is not null)),
  constraint token_transactions_connector_manifest
    check ((operation = 'connector_generation') = (connector_manifest_id is not null))
) partition by range (occurred_at);
comment on table billing.token_transactions is
  'Append-only ledger of every charge, traceable to what it bought.';
comment on column billing.token_transactions.membership_id is
  'The membership whose balance was debited. Null when the debit was against a contract allocation.';
comment on column billing.token_transactions.weight is 'Units charged. Whole for tokens; a simulation re-run charges a fraction.';
comment on column billing.token_transactions.source is 'Funding source. AI FDE work is marked by engagement_id.';
comment on column billing.token_transactions.correlation_id is
  'Identity of the charged operation (query, connector, file or simulation). Not a foreign key.';
create index token_transactions_list on billing.token_transactions (organisation_id, occurred_at desc);
create index token_transactions_by_member on billing.token_transactions (organisation_id, membership_id, occurred_at desc)
  where membership_id is not null;
create index token_transactions_by_engagement on billing.token_transactions (organisation_id, engagement_id, occurred_at)
  where engagement_id is not null;
create index token_transactions_silo_file on billing.token_transactions (organisation_id, silo_file_id)
  where silo_file_id is not null;
create index token_transactions_simulation_run on billing.token_transactions (organisation_id, simulation_run_id)
  where simulation_run_id is not null;
create index token_transactions_heal_proposal on billing.token_transactions (organisation_id, heal_proposal_id)
  where heal_proposal_id is not null;
create index token_transactions_connector_manifest on billing.token_transactions (organisation_id, connector_manifest_id)
  where connector_manifest_id is not null;
create index token_transactions_time on billing.token_transactions using brin (occurred_at);
select platform.enable_tenant_rls('billing.token_transactions');
select platform.make_append_only('billing.token_transactions');

