create table billing.purchases (
  id                        uuid primary key,
  organisation_id           uuid not null references iam.organisations (id),
  kind                      text not null check (kind in ('tokens', 'simulations', 'seats')),
  quantity                  integer not null check (quantity > 0),
  amount                    numeric(12,2) not null check (amount >= 0),
  currency                  char(3) not null default 'GBP' check (currency ~ '^[A-Z]{3}$'),
  purchased_by              uuid not null,
  beneficiary_membership_id uuid,
  auto_topup                boolean not null default false,
  stripe_invoice_id         text,
  occurred_at               timestamptz not null default now(),
  unique (organisation_id, id),
  constraint purchases_purchased_by_fkey
    foreign key (organisation_id, purchased_by) references iam.memberships (organisation_id, id),
  constraint purchases_beneficiary_fkey
    foreign key (organisation_id, beneficiary_membership_id) references iam.memberships (organisation_id, id),
  check ((kind in ('tokens', 'simulations')) = (beneficiary_membership_id is not null))
);
comment on table billing.purchases is 'Each purchase of tokens, simulations or seats, manual or automatic.';
comment on column billing.purchases.purchased_by is
  'The purchasing membership; for an auto top-up, the membership whose balance was topped up.';
comment on column billing.purchases.beneficiary_membership_id is 'Whose balance receives the tokens or simulations.';
create index purchases_list on billing.purchases (organisation_id, occurred_at desc);
create index purchases_beneficiary on billing.purchases (organisation_id, beneficiary_membership_id)
  where beneficiary_membership_id is not null;
select platform.enable_tenant_rls('billing.purchases');

grant select, insert on billing.purchases to silo_app;
