-- ===========================================================================
-- billing.storage_measurements: insert and select only
-- ===========================================================================

create table billing.storage_measurements (
  id              uuid primary key,
  organisation_id uuid not null references iam.organisations (id),
  silo_id         uuid not null,
  store           text not null check (store in ('postgres', 'gcs', 'bigquery', 'index')),
  bytes_held      bigint not null check (bytes_held >= 0),
  bytes_scanned   bigint not null default 0 check (bytes_scanned >= 0),
  bytes_egressed  bigint not null default 0 check (bytes_egressed >= 0),
  provider_cost   numeric(14,6) not null,
  cost_storage    numeric(14,6) not null default 0,
  cost_compute    numeric(14,6) not null default 0,
  cost_egress     numeric(14,6) not null default 0,
  period          text not null check (period ~ '^[0-9]{4}-(0[1-9]|1[0-2])$'),
  measured_at     timestamptz not null,
  unique (organisation_id, id),
  constraint storage_measurements_point_key unique (organisation_id, silo_id, store, measured_at),
  constraint storage_measurements_silo_fkey
    foreign key (organisation_id, silo_id) references siloes.siloes (organisation_id, id),
  constraint storage_measurements_cost_breakdown
    check (provider_cost = cost_storage + cost_compute + cost_egress)
);
comment on table billing.storage_measurements is
  'Bytes held and scanned per Silo and store, with provider cost, for billing at cost plus 10%.';
comment on column billing.storage_measurements.provider_cost is
  'At the regional rate, for the interval since the previous measurement of the same Silo and store.';
comment on column billing.storage_measurements.period is 'Billing period, YYYY-MM.';
create index storage_measurements_by_period on billing.storage_measurements (organisation_id, period, silo_id);
create index storage_measurements_trend on billing.storage_measurements (organisation_id, silo_id, measured_at desc);
select platform.enable_tenant_rls('billing.storage_measurements');

