-- billing.invoices
-- ===========================================================================

create table billing.invoices (
  id                uuid primary key,
  organisation_id   uuid not null references iam.organisations (id),
  stripe_invoice_id text,
  manual            boolean not null default false,
  contract_id       uuid,
  period_covered    text not null
                      check (period_covered ~ '^[0-9]{4}-(0[1-9]|1[0-2])(/[0-9]{4}-(0[1-9]|1[0-2]))?$'),
  amount            numeric(14,2) not null check (amount > 0),
  currency          char(3) not null default 'GBP' check (currency ~ '^[A-Z]{3}$'),
  terms             text not null,
  due_date          date not null,
  status            text not null default 'draft' check (status in ('draft', 'open', 'paid', 'overdue', 'void')),
  paid_at           timestamptz,
  recorded_by       uuid constraint invoices_recorded_by_fkey references platform.operators (id),
  purchase_order    text,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  unique (organisation_id, id),
  constraint invoices_contract_fkey
    foreign key (organisation_id, contract_id) references billing.contracts (organisation_id, id),
  check (status <> 'paid' or paid_at is not null),
  constraint invoices_manual_has_no_stripe_id check (manual = (stripe_invoice_id is null)),
  constraint invoices_manual_payment_recorded check (not manual or status <> 'paid' or recorded_by is not null),
  constraint invoices_recorded_by_manual_only check (manual or recorded_by is null)
);
comment on table billing.invoices is
  'Each invoice mirrored from Stripe, or recorded manually when paid outside Stripe.';
comment on column billing.invoices.period_covered is 'YYYY-MM, or YYYY-MM/YYYY-MM for an annual invoice.';
comment on column billing.invoices.recorded_by is 'Staff identity that recorded a manual payment.';
create unique index invoices_stripe_invoice on billing.invoices (stripe_invoice_id) where stripe_invoice_id is not null;
create index invoices_list on billing.invoices (organisation_id, created_at desc);
create index invoices_overdue_sweep on billing.invoices (organisation_id, due_date) where status = 'open';
create index invoices_contract on billing.invoices (organisation_id, contract_id) where contract_id is not null;
select platform.add_updated_at_trigger('billing.invoices');
select platform.enable_tenant_rls('billing.invoices');
create trigger invoices_frozen before update on billing.invoices
  for each row execute function platform.freeze_columns('id', 'organisation_id', 'manual', 'stripe_invoice_id',
                                                         'created_at');

grant select, insert, update on billing.invoices to silo_app;
grant select on billing.invoices to silo_report;

-- The overdue sweep (75.3), across organisations: open invoices past their due date.
create function billing.invoices_past_due(p_today date, p_limit integer)
  returns table (organisation_id uuid, id uuid)
language sql stable security definer
set search_path = pg_catalog
as $$
  select i.organisation_id, i.id from billing.invoices i
  where i.status = 'open' and i.due_date < p_today
  order by i.due_date, i.id
  limit least(greatest(p_limit, 1), 1000)
$$;
revoke all on function billing.invoices_past_due(date, integer) from public;
grant execute on function billing.invoices_past_due(date, integer) to silo_app;

-- Live subscriptions counted above their billable seats (a release the provider has not yet
-- been told of): what the seat sweep corrects (spec 72.2).
create function billing.subscriptions_seat_drift(p_limit integer)
  returns table (organisation_id uuid)
language sql stable security definer
set search_path = pg_catalog
as $$
  select s.organisation_id from billing.subscriptions s
  where s.status <> 'cancelled'
    and s.seat_count > greatest(1, (select count(*) from billing.seats t where t.subscription_id = s.id and t.status <> 'released'))
  order by s.organisation_id
  limit least(greatest(p_limit, 1), 1000)
$$;
revoke all on function billing.subscriptions_seat_drift(integer) from public;
grant execute on function billing.subscriptions_seat_drift(integer) to silo_app;

-- ===========================================================================
-- billing.silo_charges: Siloes at provider cost plus 10% (spec 74.1, 74.2), one line per
-- organisation, month, Silo and store, summed from storage_measurements when the month
-- closes and invoiced in arrears. Each line keeps its provider cost and its 10% apart.
-- ===========================================================================

create table billing.silo_charges (
  id              uuid primary key,
  organisation_id uuid not null references iam.organisations (id),
  period          text not null check (period ~ '^[0-9]{4}-(0[1-9]|1[0-2])$'),
  silo_id         uuid not null,
  store           text not null check (store in ('postgres', 'gcs', 'bigquery', 'index')),
  mean_bytes_held bigint not null check (mean_bytes_held >= 0),
  bytes_scanned   bigint not null check (bytes_scanned >= 0),
  bytes_egressed  bigint not null check (bytes_egressed >= 0),
  cost_storage    numeric(14,6) not null check (cost_storage >= 0),
  cost_compute    numeric(14,6) not null check (cost_compute >= 0),
  cost_egress     numeric(14,6) not null check (cost_egress >= 0),
  included_cost   numeric(14,6) not null check (included_cost between 0 and cost_storage),
  provider_cost   numeric(14,6) not null,
  uplift          numeric(14,6) not null,
  amount          numeric(14,2) not null check (amount >= 0),
  invoice_state   text not null default 'pending' check (invoice_state in ('pending', 'invoiced', 'not_billed')),
  invoice_id      uuid,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  unique (organisation_id, id),
  constraint silo_charges_line_key unique (organisation_id, period, silo_id, store),
  constraint silo_charges_silo_fkey foreign key (organisation_id, silo_id) references siloes.siloes (organisation_id, id),
  constraint silo_charges_invoice_fkey foreign key (organisation_id, invoice_id) references billing.invoices (organisation_id, id),
  constraint silo_charges_provider_cost check (provider_cost = cost_storage - included_cost + cost_compute + cost_egress),
  constraint silo_charges_uplift check (uplift = round(provider_cost * 0.1, 6)),
  check ((invoice_state = 'invoiced') = (invoice_id is not null))
);
comment on table billing.silo_charges is
  'Siloes billed at provider cost plus 10% (spec 74.1): per month, Silo and store, the provider cost and the 10% shown apart.';
comment on column billing.silo_charges.included_cost is
  'The storage cost the entitlement''s included storage covers (74.2), not billed.';
comment on column billing.silo_charges.provider_cost is 'Billed provider cost: storage less included, plus compute and egress.';
comment on column billing.silo_charges.amount is 'provider_cost plus uplift, to the penny: the invoice line.';
create index silo_charges_by_silo on billing.silo_charges (organisation_id, silo_id);
create index silo_charges_by_invoice on billing.silo_charges (organisation_id, invoice_id) where invoice_id is not null;
create index silo_charges_pending on billing.silo_charges (organisation_id, period) where invoice_state = 'pending';
select platform.add_updated_at_trigger('billing.silo_charges');
select platform.enable_tenant_rls('billing.silo_charges');

grant select, insert on billing.silo_charges to silo_app;
grant update (invoice_state, invoice_id) on billing.silo_charges to silo_app;
grant select on billing.silo_charges to silo_report;

-- The organisations with a closed month's Silo charges still to make or to invoice.
create function billing.silo_charges_due(p_period text, p_limit integer)
  returns table (organisation_id uuid, period text)
language sql stable security definer
set search_path = pg_catalog
as $$
  (select distinct m.organisation_id, m.period from billing.storage_measurements m
   where m.period = p_period
     and not exists (select 1 from billing.silo_charges c where c.organisation_id = m.organisation_id and c.period = m.period))
  union
  (select distinct c.organisation_id, c.period from billing.silo_charges c where c.invoice_state = 'pending' and c.period <= p_period)
  order by 2, 1
  limit least(greatest(p_limit, 1), 1000)
$$;
revoke all on function billing.silo_charges_due(text, integer) from public;
grant execute on function billing.silo_charges_due(text, integer) to silo_app;


