alter table action.prior_states
  add constraint prior_states_connection_fkey
    foreign key (organisation_id, connection_id) references connect.connections (organisation_id, id);
alter table action.blast_radius_results
  add constraint blast_radius_results_connection_fkey
    foreign key (organisation_id, connection_id) references connect.connections (organisation_id, id);
alter table action.approval_policies
  add constraint approval_policies_connection_fkey
    foreign key (organisation_id, connection_id) references connect.connections (organisation_id, id);
alter table action.policy_floors
  add constraint policy_floors_connection_fkey
    foreign key (organisation_id, connection_id) references connect.connections (organisation_id, id);
alter table action.approval_chains
  add constraint approval_chains_discovery_authorisation_fkey
    foreign key (organisation_id, discovery_authorisation_id)
    references connect.discovery_authorisations (organisation_id, id);
alter table action.approval_chain_connections
  add constraint approval_chain_connections_connection_fkey
    foreign key (organisation_id, connection_id) references connect.connections (organisation_id, id);
alter table action.mutation_executions
  add constraint mutation_executions_connection_fkey
    foreign key (organisation_id, connection_id) references connect.connections (organisation_id, id);
alter table action.id_remappings
  add constraint id_remappings_connection_fkey
