    foreign key (organisation_id, scenario_id) references simulation.scenarios (organisation_id, id);
alter table action.action_commits
  add constraint action_commits_scenario_fkey
    foreign key (organisation_id, scenario_id) references simulation.scenarios (organisation_id, id);

-- siloes (review D8: the chain points at the request, which exists before the wipe)
alter table action.approval_chains
  add constraint approval_chains_purge_request_fkey
    foreign key (organisation_id, purge_request_id) references siloes.purge_requests (organisation_id, id);
-- A receipt purge's chain points at its request likewise (D152).
alter table action.approval_chains
  add constraint approval_chains_receipt_purge_fkey
    foreign key (organisation_id, receipt_purge_id) references action.receipt_purges (organisation_id, id);

-- Stated exception to indexing rule 1 on the commit ledger: scenarios are never
-- deleted, and every read goes through mutation_id or object_id.
comment on constraint action_commits_scenario_fkey on action.action_commits is
  'lint:no-index scenarios are never deleted; reads go through mutation_id or object_id';

-- From siloes, billing
-- Keys from the siloes and billing tables to tables of other domains. Supporting
-- indexes are created with the tables in siloes_billing.sql.

-- To connect.connections (organisation_id, id)
