    foreign key (organisation_id, connection_id) references connect.connections (organisation_id, id);
comment on constraint transitions_connection_fkey on siloes.transitions is
  'lint:no-index no query filters by connection_id and connections are never deleted (design: siloes.transitions)';

-- To ontology.object_types (organisation_id, id)
alter table siloes.silo_object_types
  add constraint silo_object_types_object_type_fkey
    foreign key (organisation_id, object_type_id) references ontology.object_types (organisation_id, id);
alter table siloes.transitions
