comment on constraint silo_baselines_object_type_fkey on siloes.silo_baselines is
  'lint:no-index object types are never deleted; design keeps the primary key as the only index (HOT updates)';
alter table siloes.index_definitions
  add constraint index_definitions_object_type_fkey
    foreign key (organisation_id, object_type_id) references ontology.object_types (organisation_id, id);
alter table siloes.warehouse_tables
