alter table iam.role_assignments
  add constraint role_assignments_on_connection_fkey
    foreign key (organisation_id, on_connection_id) references connect.connections (organisation_id, id),
  add constraint role_assignments_on_silo_fkey
    foreign key (organisation_id, on_silo_id) references siloes.siloes (organisation_id, id),
  add constraint role_assignments_on_view_fkey
    foreign key (organisation_id, on_view_id) references workspace.saved_views (organisation_id, id),
  add constraint role_assignments_on_object_type_fkey
    foreign key (organisation_id, on_object_type_id) references ontology.object_types (organisation_id, id),
  add constraint role_assignments_on_app_fkey
    foreign key (organisation_id, on_app_id) references workspace.apps (organisation_id, id);

alter table iam.invitations
  add constraint invitations_seat_fkey
    foreign key (organisation_id, seat_id) references billing.seats (organisation_id, id);

alter table audit.audit_events
  add constraint audit_events_purpose_session_fkey
    foreign key (organisation_id, purpose_session_id) references gov.purpose_sessions (organisation_id, id);


-- ============================================================================
-- Partitions
-- ============================================================================

select platform.maintain_partitions();

-- ===========================================================================
-- KEK rotation (spec 61.1, 61.2; key.rotate). Owned by silo_migrate, executed only by
-- silo_credential: the registry is the cell's, and the rows a version wraps span every
-- organisation and user. A rotation makes a new version active and the old decrypt_only;
-- each row's wrapped DEK is re-wrapped under the new version, one transaction a row, the
-- ciphertext never opened; a version no live row references is retired (the guard above
-- refuses otherwise). Key material never passes through here: references and wrapped DEKs.
-- ===========================================================================

create function iam.start_key_rotation(p_provider text, p_key_uri text)
returns table (id uuid, previous_id uuid)
language plpgsql security definer
set search_path = pg_catalog
as $$
declare
  v_previous uuid;
  v_id uuid := gen_random_uuid();
begin
  if exists (select 1 from iam.kms_key_versions where status = 'decrypt_only') then
    raise exception 'a rotation is already under way' using errcode = 'unique_violation';
  end if;
  update iam.kms_key_versions set status = 'decrypt_only' where status = 'active' returning kms_key_versions.id into v_previous;
  insert into iam.kms_key_versions (id, provider, key_uri, version, status, activated_at)
  values (v_id, p_provider, p_key_uri,
          coalesce((select max(v.version) from iam.kms_key_versions v where v.provider = p_provider and v.key_uri = p_key_uri), 0) + 1,
          'active', now());
  return query select v_id, v_previous;
end
$$;

create function iam.key_version_references(p_key_version_id uuid, p_limit integer)
returns table (kind text, id uuid, organisation_id uuid, user_id uuid, connection_id uuid, field_name text, purpose text, row_kind text,
               key_version integer, dek_wrapped bytea)
language sql stable security definer
set search_path = pg_catalog
as $$
  (select 'connection_credential', c.id, c.organisation_id, null::uuid, c.connection_id, c.field_name, c.purpose, null::text, null::integer, c.dek_wrapped
     from connect.connection_credentials c where c.key_version_id = p_key_version_id and c.revoked_at is null and c.dek_wrapped is not null limit p_limit)
  union all
  (select 'identity_provider', i.id, i.organisation_id, null, null, null, null, i.kind, null, i.dek_wrapped
     from iam.identity_providers i where i.key_version_id = p_key_version_id limit p_limit)
  union all
  (select 'mfa_factor', m.id, null, m.user_id, null, null, null, m.kind, null, m.dek_wrapped
     from iam.mfa_factors m where m.key_version_id = p_key_version_id and m.revoked_at is null and m.dek_wrapped is not null limit p_limit)
  union all
  (select 'organisation_key', k.id, k.organisation_id, null, null, null, k.purpose, null, k.version, k.dek_wrapped
     from iam.organisation_keys k where k.key_version_id = p_key_version_id and k.status <> 'retired' limit p_limit)
$$;

create function iam.rewrap_sealed(p_kind text, p_id uuid, p_from uuid, p_to uuid, p_dek_wrapped bytea)
returns boolean
language plpgsql security definer
set search_path = pg_catalog
as $$
declare
  v_rows integer;
begin
  if p_kind = 'connection_credential' then
    update connect.connection_credentials set dek_wrapped = p_dek_wrapped, key_version_id = p_to where id = p_id and key_version_id = p_from;
  elsif p_kind = 'identity_provider' then
    update iam.identity_providers set dek_wrapped = p_dek_wrapped, key_version_id = p_to where id = p_id and key_version_id = p_from;
  elsif p_kind = 'mfa_factor' then
    update iam.mfa_factors set dek_wrapped = p_dek_wrapped, key_version_id = p_to where id = p_id and key_version_id = p_from;
  elsif p_kind = 'organisation_key' then
    update iam.organisation_keys set dek_wrapped = p_dek_wrapped, key_version_id = p_to where id = p_id and key_version_id = p_from;
  else
    raise exception 'no sealed row kind %', p_kind using errcode = 'invalid_parameter_value';
  end if;
  get diagnostics v_rows = row_count;
  return v_rows = 1;
end
$$;

create function iam.retire_key_version(p_id uuid)
returns boolean
language plpgsql security definer
set search_path = pg_catalog
as $$
declare
  v_rows integer;
begin
  update iam.kms_key_versions set status = 'retired', retired_at = now() where id = p_id and status = 'decrypt_only';
  get diagnostics v_rows = row_count;
  return v_rows = 1;
end
$$;

-- A cell-wide event (a key rotation reaches every organisation's secrets) written to each
-- organisation's audit log through the outbox: the payload is built and checked by the caller.
create function iam.record_cell_event(p_event text, p_schema_version integer, p_topic text, p_payload jsonb, p_correlation_id uuid)
returns integer
language plpgsql security definer
set search_path = pg_catalog
as $$
declare
  v_rows integer;
begin
  insert into platform.outbox (id, organisation_id, topic, ordering_key, event, schema_version, payload, correlation_id)
  select gen_random_uuid(), o.id, p_topic, o.id::text, p_event, p_schema_version, p_payload, p_correlation_id
    from iam.organisations o;
  get diagnostics v_rows = row_count;
  return v_rows;
end
$$;

-- Fleet's events about a single-tenant cell, copied into its customers' audit logs (spec 11.6:
-- "Events affecting a single-tenant install are also written to its audit log"; D199): each
-- once, by its sequence in Fleet's log, whatever retries the cell's Fleet agent makes. Cell-level:
-- the event names a release and a rollout, never a customer's value.
create table platform.fleet_event_copies (
  seq       bigint primary key check (seq > 0),
  event     text not null check (event ~ '^[a-z][a-z0-9_]*$'),
  copied_at timestamptz not null default now()
);
comment on table platform.fleet_event_copies is
  'Fleet events about this single-tenant cell already copied into its customers'' audit logs, by Fleet''s sequence (11.6; D199).';
grant select on platform.fleet_event_copies to silo_report;

-- One Fleet event into every customer organisation's audit log (not the system or synthetic
-- organisation's), once: 0 when its sequence was copied before.
create function platform.copy_fleet_event(p_seq bigint, p_event text, p_schema_version integer, p_topic text, p_payload jsonb, p_correlation_id uuid)
returns integer
language plpgsql security definer
set search_path = pg_catalog
as $$
declare
  v_rows integer;
begin
  insert into platform.fleet_event_copies (seq, event) values (p_seq, p_event) on conflict do nothing;
  if not found then return 0; end if;
  insert into platform.outbox (id, organisation_id, topic, ordering_key, event, schema_version, payload, correlation_id)
  select gen_random_uuid(), o.id, p_topic, o.id::text, p_event, p_schema_version, p_payload, p_correlation_id
    from iam.organisations o where not o.is_system and not o.is_synthetic;
  get diagnostics v_rows = row_count;
  return v_rows;
end
$$;
revoke all on function platform.copy_fleet_event(bigint, text, integer, text, jsonb, uuid) from public;
grant execute on function platform.copy_fleet_event(bigint, text, integer, text, jsonb, uuid) to silo_audit_writer;

-- Status page incidents naming this shared cell, copied into its customers' audit logs (13.5: incident_declared and
-- incident_resolved; D209), once each by the notice and the event.
create table platform.incident_event_copies (
  notice_id uuid not null,
  event     text not null check (event in ('incident_declared', 'incident_resolved')),
  copied_at timestamptz not null default now(),
  primary key (notice_id, event)
);
comment on table platform.incident_event_copies is
  'Status incidents naming this cell already copied into its customers'' audit logs, by notice and event (13.5; D209).';
grant select on platform.incident_event_copies to silo_report;

create function platform.copy_incident_event(p_notice_id uuid, p_event text, p_schema_version integer, p_topic text, p_payload jsonb, p_correlation_id uuid)
returns integer
language plpgsql security definer
set search_path = pg_catalog
as $$
declare
  v_rows integer;
begin
  insert into platform.incident_event_copies (notice_id, event) values (p_notice_id, p_event) on conflict do nothing;
  if not found then return 0; end if;
  insert into platform.outbox (id, organisation_id, topic, ordering_key, event, schema_version, payload, correlation_id)
  select gen_random_uuid(), o.id, p_topic, o.id::text, 'audit_event', p_schema_version, p_payload, p_correlation_id
    from iam.organisations o where not o.is_system and not o.is_synthetic;
  get diagnostics v_rows = row_count;
  return v_rows;
end
$$;
revoke all on function platform.copy_incident_event(uuid, text, integer, text, jsonb, uuid) from public;
grant execute on function platform.copy_incident_event(uuid, text, integer, text, jsonb, uuid) to silo_audit_writer;

revoke all on function iam.start_key_rotation(text, text), iam.key_version_references(uuid, integer), iam.rewrap_sealed(text, uuid, uuid, uuid, bytea),
  iam.retire_key_version(uuid), iam.record_cell_event(text, integer, text, jsonb, uuid) from public;
grant execute on function iam.start_key_rotation(text, text), iam.key_version_references(uuid, integer), iam.rewrap_sealed(text, uuid, uuid, uuid, bytea),
  iam.retire_key_version(uuid), iam.record_cell_event(text, integer, text, jsonb, uuid) to silo_credential;

